!<arch>
wrplot.f/       1675793801  5006  320   100644  25203     `
C!!!      PROGRAM WRPLOT
      SUBROUTINE WRPLOT

C**********************************************************************
C***                                                                ***
C***  PLOT PROGRAM OF THE WR PROGRAM SYSTEM                         ***
C***  HOST: KIEL CRAY-VAX                                           ***
C***  PURPOSE:                                                      ***
C***  (i)  STANDARD PLOT OF A GIVEN STANDARD DATA TABLE             ***
C***         AS PRODUCED BY THE SUBROUTINES PLOTANF/PLOTCON         ***
C***                                                                ***
C***  (ii) GENERAL PLOT DESIGN                                      ***
C***                                                                ***
C**********************************************************************

C***  MAXIMUM NUMBER OF DATASETS (DEFAULT) 
      PARAMETER (NSETMAXDEFAULT= 100)
      PARAMETER (NSETMAXMAX = NSETMAXDEFAULT * 10)
C***  MAXIMUM NUMBER OF DATA POINTS IN ONE DATASET
      PARAMETER (NDATMAXDEFAULT= 100000)
      PARAMETER (NDATMAXMAX = NDATMAXDEFAULT * 10)
      PARAMETER (NDATTOT = NSETMAXDEFAULT * NDATMAXDEFAULT)
C***  Image data dimensions - this branch is disabled
C!!!      PARAMETER (NDATMAXIM= 2000000)
      PARAMETER (NDATMAXIM= 1)
      PARAMETER (NSETMAXIM= 1)
C***  MAXIMUM OF IMAGE PARAMETERS, I.E. NAXIS, NAXIS1, ETC.
      PARAMETER (IMPARMAX= 10)
C***  MAXIMUM OF KASDEF LINES
      PARAMETER (NKDMAX  = 20000)
      PARAMETER (NKDMAX2 = 100)
C***  MAXIMUM OF INTERACTIVE POINTS
      PARAMETER (NINTMAX = 5000)
C***  MAXIMUM NUMBER OF VARIABLES
      PARAMETER (MAXVAR=2000)
C***  MAXIMUN OF BUTTONS IN ONE ROW IN INTERACTIVE BRANCH
      PARAMETER (MAXBUTT = 20)
C***  MAXIMUN OF ROWS IN INTERACTIVE BRANCH
      PARAMETER (MAXRBUTT = 100)

      DIMENSION B(6), C(6), BSAVE(6), CSAVE(6)
      DIMENSION X(NDATTOT), Y(NDATTOT)
      DIMENSION XINT(NINTMAX), YINT(NINTMAX)
      DIMENSION NDAT(NSETMAXMAX), ISYMBOL(NSETMAXMAX), NPEN(NSETMAXMAX)
      DIMENSION SSIZE(NSETMAXMAX), ICOLOR(NSETMAXMAX)
      DIMENSION STRIP(2,NSETMAXMAX)
      DIMENSION ISETXERR(NSETMAXMAX), ISETYERR(NSETMAXMAX)
      CHARACTER*10 XERRTYPE(NSETMAXMAX), YERRTYPE(NSETMAXMAX)
      CHARACTER*60 SETNAME(NSETMAXMAX)
      CHARACTER*900 DATASETLINE(NSETMAXMAX)
C***  SCRATCH ARRAYS
      DIMENSION X1(NDATMAXMAX), Y1(NDATMAXMAX)
      DIMENSION YCONV(NDATMAXMAX), T(NDATMAXMAX)
      DIMENSION XCMA(NDATMAXMAX), YCMA(NDATMAXMAX)
      CHARACTER FNAME*255, LINE*132, ICHAR*1, FORMSTR*80 
      CHARACTER FNAMENEW*255, ICHAR2*3
      CHARACTER*144 HEADER, XTEXT, YTEXT
      CHARACTER KDLINE(NKDMAX)*132, KDLINE2(NKDMAX2)*132
      CHARACTER KEY*20, STATLINE*30, USER*8, HOST*8, AUTOSCALE*8
      CHARACTER*132 VAR(MAXVAR,2), COMMLINE
      CHARACTER*20 INTACT, INTACT2
      DIMENSION ISELSET(3)

C***  32bit vectors for INFITS
      REAL*4 XKIND4(NDATMAXMAX), YKIND4(NDATMAXMAX) 
      REAL*4 YKIND4HELP(NDATMAXMAX)
 
C***  IMAGE ARRAYS
      DIMENSION ZIM(NSETMAXIM, NDATMAXIM)
      DIMENSION XIMPAR(NSETMAXIM, IMPARMAX)

C***  Communication of Devive Nr. to Subr. CENSYMO
      COMMON / COMIDEV / IDEV

C***  Operating System:
      COMMON / COMOS / OPSYS
      CHARACTER*8 OPSYS
C***  Unix Commad 'cat' available?      
      COMMON / COMBC / BCAT
      LOGICAL BCAT
C***  Active plot driver
      COMMON / COMACT / ACTDRIV
      CHARACTER ACTDRIV*7

C***  Hatching-Flag: prologue written by PS_PLTEND, enabled by PS_HFILL
      COMMON / COMHATCHFLAG / HATCHFLAG
      LOGICAL HATCHFLAG

C***  Current color index
      COMMON / COMCOLOR / LASTCOLOR

      LOGICAL MPSTART,MPENDE,MPACTIVE, INBOX, CPRGHT, BINTER, BSINGLE
      LOGICAL KDPAUSE, LATEBOX, BINSEX, BPREDEF_VAR

c***  PLOTBOX keywords
      LOGICAL NOMINMAX(10), ALTX, ALTY
      LOGICAL NOTICKX, NOTICKY, NOTICK2X, NOTICK2Y, NOLABX, NOLABY

C***  VARIABLES FOR BUTTON HANDLING
      DIMENSION POSBUTT(MAXBUTT,MAXRBUTT,2), NSCRBUTT(MAXRBUTT)
      CHARACTER*20 TEXTBUTT(MAXBUTT,MAXRBUTT)

C***  SAVE THE ACTION IN INTERACTIVE BRANCH
      SAVE INTACT

C***  Do not write Hatching-Prologue if PS_HFILL is not used
      HATCHFLAG = .FALSE.

C***  SET INSTALLATION PARAMETERS
      IF (.FALSE.) THEN
         CALL ADV_INSTALL(USER, HOST)
      ELSE
         CALL INSTALL
C***  USER IDENTIFICATION
         CALL IDUSER (USER, HOST)
      ENDIF

C***  USER STATISTICS
      CALL WRSTAT (STATLINE, USER, -1)

C***  NO INSTRUCTION EXPORT 
      BINSEX = .FALSE.

C***  AUTOMATIC ABGESCHALTET 
C***    IAUTO = 3 : AUTOMATISCHE ERZEUGUNG VON POSTSCRIPT-FILES
C***    IAUTO = 5 : AUTOMATISCHE ERZEUGUNG VON X11-FENSTERN
      IAUTO = -1

C***  SET VARIABLE ENCOUNTER TO ZERO
      NVAR = 0

C***  INPUT CHANNEL FOR WRPLOT FILE
      NRUNIT = 1

C***  NO BUTTONS SO FAR
      NBUTT = 0

C***  INTERACTIVE ACTION = START
      INTACT = 'START'
      COMMLINE = ' '
      IACT = 1

C***  SELECTED SET UNDEFINED (I.E. 0)
      ISELSET(1) = 0
      ISELSET(2) = 0
      ISELSET(3) = 0

C**********************************************************************
C***          OPEN PLOT DATA FILE AND READ IT                            ***
C**********************************************************************

    1 CONTINUE

C***  No multiplot Option is active
      MPSTART=.FALSE.
      MPENDE =.FALSE.
      MPACTIVE=.FALSE.

C***  Default fuer die schwachsinnige COPYRIGHT-Zeile
ccc      CPRGHT = .TRUE.
      CPRGHT = .FALSE.

C***  OPEN WRPLOT DATA FILE ******************************************
         WRITE (6,'(A)') 'NAME OF WRPLOT DATA FILE (END= CTRL D)'
         WRITE (6,'(A)') 'Present directory is:'
         CALL SYSTEM ('pwd')
         READ (*, '(A)', END=100) FNAME
         FNAME = FNAME(:IDX(FNAME))
         IF (FNAME .EQ. '.' .OR. FNAME .EQ. './' .OR. 
     >       FNAME .EQ. '..' .OR. FNAME .EQ. '../' ) GOTO 97
         OPEN (UNIT=NRUNIT, FILE=FNAME, STATUS='OLD', ERR=97)
      WRITE (6,*) 'FILE OPENED: ', FNAME(:IDX(FNAME))

C***  INFORMATION OF ALL PLOTS IN DATAFILE
      CALL DATACAT (NRUNIT, BSINGLE)


    6 CONTINUE

      CALL READDATA(FNAME, NRUNIT, X, Y, X1, Y1, NDAT, NSET, NSETMAX, 
     >              B, C, ISYMBOL, HEADER, XTEXT, YTEXT, K, NPEN, 
     >              ICOLOR, PLOTSKAL, OFSX, OFSY,
     >              MPSTART, MPENDE, MPACTIVE, PSIZEX, PSIZEY,
     >              FORMATFA, SSIZE, NOTICKX, NOTICKY, NOTICK2X, 
     >              NOTICK2Y, INBOX, 
     >              KDLINE, NKD, NKDMAX, NDATMAX, IDEV, CPRGHT, 
     >              NOLABX, NOLABY, NOBOX, SIZELET, LATEBOX,
     >              VAR, MAXVAR, NVAR, BINSEX, AUTOSCALE, BINTER, 
     >              NDATMAXIM, NSETMAXIM, IMPARMAX, ZIM, XIMPAR, 
     >              ISETIM, NSETIM, STRIP, 
     >              ISETXERR, ISETYERR, XERRTYPE, YERRTYPE,
     >              SETNAME, NSETMAXMAX, NSETMAXDEFAULT, NDATMAXMAX,
     >              NDATMAXDEFAULT, NDATTOT, NOMINMAX, SIZETIC, 
     >              BPREDEF_VAR, ALTX, ALTY, DATASETLINE,
     >              XKIND4, YKIND4, YKIND4HELP)

C***  IF AUTOSCALE IS REQUESTED
      IF (AUTOSCALE .NE. 'NONE') THEN
        CALL AUTOS(B, C, X, Y, NDAT, NDATMAX, NSET, NSETMAX, AUTOSCALE)
      ENDIF

C***  Only now, the predefined-variables kann be set (if requested)
      IF (BPREDEF_VAR) CALL PREVAR 
     >               (FNAME, B, C, OFSX, OFSY, FORMATFA, PLOTSKAL, 
     >                PSIZEX, PSIZEY, VAR, MAXVAR, NVAR)


C***  STORE THE AXIS-INFORMATION
      CALL BSTORE (B, C, BSAVE, CSAVE, 'STORE')

C*** If readdata returned with MPENDE-SIGNAL and plot active,
C     then close plot, disable multiplot and ask for REWIND or next plot
      IF (MPENDE) THEN
         IF (CPRGHT) CALL SUBCP(IDEV)
         CALL GPLTEND
         MPSTART  = .FALSE.
         MPACTIVE = .FALSE.
         MPENDE   = .FALSE.
  310    FORMSTR = '(A)'
         WRITE (6, FORMSTR) 
     >          'REWIND THIS PLOTFILE? /N/ (END=CTRL D): '
         IF (IAUTO .EQ. -1) THEN
           READ (5, '(A)', END=100) ICHAR
           ELSE
           ICHAR = 'N'
           ENDIF

         IF (ICHAR .EQ. 'Y' .OR. ICHAR .EQ. 'y') THEN
            REWIND (NRUNIT)
            GOTO 6
            ENDIF

         GOTO 350
         ENDIF

C***  HANDLING OF THE ERROR FLAG "K" RETURNED BY SUBROUTINE READDATA
C***     K = 1: ERROR DETECTED, THIS PLOT SKIPPED, READ NEXT PLOT
         IF (K .EQ. 1) GOTO 6
C***     K = 2: E-O-F REACHED, OFFER NEXT FILE
         IF (K .EQ. 2) THEN
            CLOSE (NRUNIT)
            WRITE (6,*) 'FILE CLOSED:', FNAME(1:IDX(FNAME))
            IF (IAUTO .EQ. 3 .OR. IAUTO .EQ. 5) THEN
              STOP 'AUTOMATICALLY STOPPED'
            ENDIF
            GOTO 1
            ENDIF

C***  ARITHMETIC IS NOT POSSIBLE WITHIN MULTIPLOTS, BUT SKIPS
      IF (MPACTIVE) THEN
        IF (MPSTART) THEN
          WRITE(6,*) 'N = NONE (DEFAULT)'
          WRITE (6,*) '+ = AUTOMATIC PS-FILE'
          WRITE (6,*) '= = AUTOMATIC X11'
          WRITE(6,*) 'S = SKIP (REWIND), ONLY NEGATIVE NUMBERS ARE ',
     >               'ALLOWED'
          FORMSTR = '(''INPUT: '')' 
    4     CALL NOLF (FORMSTR)
          WRITE (6, FORMSTR) 
          IF (IAUTO .EQ. -1) THEN
            READ(5,'(A)') ICHAR      
          ENDIF
          IF (ICHAR .EQ. 'S' .OR. ICHAR .EQ. 's') THEN
            CALL SKIP (NRUNIT)
            MPSTART  = .FALSE.
            MPACTIVE = .FALSE.
            MPENDE   = .FALSE.
            GOTO 6
C***  AUTOMATIC 
         ELSE IF (ICHAR .EQ. '+') THEN
            IAUTO = 3
         ELSE IF (ICHAR .EQ. '=') THEN
            IAUTO = 5
         ENDIF
        ENDIF
        GOTO 200
      ENDIF
 

      IF (IAUTO .EQ. 3 .OR. IAUTO .EQ. 5) GOTO 27

C**********************************************************************
C***   MANIPULATION OF PLOT DATA                                    ***
C**********************************************************************

8     WRITE (6,*) 'MANIPULATION OF PLOT DATA'
      WRITE (6,*) 'R = REDDENING OF FLUXES'
      WRITE (6,*) 'C = CONVOLUTION OF PROFILES'
      WRITE (6,*) 'H = CORRECTING FOR HYDROGEN Ly alpha'
      WRITE (6,*) 'A = ARITHMETIC'
      WRITE (6,*) 'X = CROSSING POINTS'
      WRITE (6,*) 'D = DELETE PLOT SET'
      WRITE (6,*) 'L = LIST DATA' 
      WRITE (6,*) 'W = WRITE DATA' 
      WRITE (6,*) 'I = INTERACTIVE MODUS' 
      WRITE (6,*) '+ = AUTOMATIC PS-FILE'
      WRITE (6,*) '= = AUTOMATIC X11'
      WRITE (6,*) 'N = NONE (DEFAULT)'
      WRITE (6,*) 'S = SKIP (REWIND)'
      FORMSTR = '(''Enter Option or only <CR> to continue: '')'
      CALL NOLF (FORMSTR)
      WRITE (6, FORMSTR) 
      READ(5,'(A)') ICHAR      
      WRITE (6,*) 

C**** LIST DATA
      IF (ICHAR .EQ. 'L' .OR. ICHAR .EQ. 'l') THEN
 1050    WRITE (6,*) ' WHICH OF THE ',NSET,' DATASETS DO YOU WANT ',
     >               'TO LIST, 0 : EXIT'
         READ (5,*) ILIST
         IF (ILIST .EQ. 0) GOTO 1102
         IF (ILIST .LT. 1 .OR. ILIST .GT. NSET) THEN
           WRITE (6,*) 'ILLEGAL INPUT'
           GOTO 1050
         ENDIF
         WRITE(6,'(A,I5,A)') ' DATASET CONTAINS ',NDAT(ILIST), 
     >                       ' DATAPOINTS'

         NOUT = 0
         I = 0
1100     I = I + 1
         NOUT = NOUT + 1
         IF (I .GT. NDAT(ILIST)) THEN
           I = I - 1
           NOUT = 20
         ENDIF
         IF (NOUT .EQ. 20) THEN
           NOUT = 0
           WRITE (6,*) 'WEITER : RETURN, ',
     >                 'ZURUECK : B, ZUM ANFANG : A, ZUM ENDE : ',
     >                 'E, QUIT : Q'
           READ (5, '(A)') ICHAR
           IF (ICHAR .EQ. 'Q' .OR. ICHAR .EQ. 'q') GOTO 1050
           IF (ICHAR .EQ. 'A' .OR. ICHAR .EQ. 'a') THEN
             I = 0
             GOTO 1100
           ENDIF
           IF (ICHAR .EQ. 'E' .OR. ICHAR .EQ. 'e') THEN
             I = NDAT(ILIST) - 19
             GOTO 1100
           ENDIF
           IF (ICHAR .EQ. 'B' .OR. ICHAR .EQ. 'b') THEN
             I = I - 41
             GOTO 1100
           ENDIF
         ENDIF
	 INDEX = NDATMAX * (ILIST-1) + I
         WRITE (6,*) I,': X,Y=', X(INDEX), Y(INDEX)
         GOTO 1100
1102     CONTINUE

C**** WRITE DATA
      ELSE IF (ICHAR .EQ. 'W' .OR. ICHAR .EQ. 'w') THEN
 1052    WRITE (6,*) ' WHICH OF THE ',NSET,' DATASETS DO YOU WANT ',
     >               'TO WRITE IN FILE, 0 : EXIT'
         READ (5,*) IWRI
         IF (IWRI .EQ. 0) GOTO 1054
         IF (IWRI .LT. 1 .OR. IWRI .GT. NSET) THEN
           WRITE (6,*) 'ILLEGAL INPUT'
           GOTO 1052
         ENDIF
         WRITE (ICHAR2,'(I3)') IWRI
         CALL FLUSHLEFT (ICHAR2)
         FNAMENEW = FNAME(:IDX(FNAME)) // ICHAR2(:IDX(ICHAR2))
	 INDEX = NDATMAX * (IWRI-1) + 1
         CALL SAVESET (X(INDEX), Y(INDEX), NDAT(IWRI), 5, 1, 
     >                 FNAMENEW, .FALSE.)
         GOTO 1052
 1054 CONTINUE

C***  AUTOMATIC 
      ELSE IF (ICHAR .EQ. '+') THEN
         IAUTO = 3
      ELSE IF (ICHAR .EQ. '=') THEN
         IAUTO = 5

C***  INTERSTELLAR REDDENING
      ELSE IF (ICHAR .EQ. 'R' .OR. ICHAR .EQ. 'r') THEN
         CALL EXTINT (X, Y, X1, Y1, NDAT, NSET, NDATMAX, NSETMAX,
     >                 B, C, ISYMBOL, NPEN, ICOLOR, FNAME, MPACTIVE, 
     >                 ' ')

C***  CONVOLUTION
      ELSE IF (ICHAR .EQ. 'C' .OR. ICHAR .EQ. 'c') THEN
         CALL CONVOL (X, Y, YCONV, NDAT, NDATMAX, NSET, NSETMAX, 
     >               ISYMBOL, NPEN, ICOLOR, FNAME )

C***  LYMAN-ALPHA CORRECTION
      ELSE IF (ICHAR .EQ. 'H' .OR. ICHAR .EQ. 'h') THEN
         LINE = ' '
         CALL HLYMANA (X, Y, NDAT, NSET, NDATMAX, NSETMAX, ISYMBOL, 
     >                 NPEN, ICOLOR, .FALSE., IDUMMY, LINE, X1, Y1)

C***  ARITHMETIC OPERATIONS
      ELSE IF (ICHAR .EQ. 'A' .OR. ICHAR .EQ. 'a') THEN
         CALL ARI (X, Y, NDAT, NSET, NDATMAX, NSETMAX, B, C, ISYMBOL, 
     >             NPEN, ICOLOR, FNAME)

C***  FIND CROSSING POINTS
      ELSE IF (ICHAR .EQ. 'X' .OR. ICHAR .EQ. 'x') THEN
         CALL WRPCROSS (X, Y, T, NDAT, NSET, NDATMAX, NSETMAX, X1, 
     >                  Y1, B, C)

C***  DELETE DATA-SET
      ELSE IF (ICHAR .EQ. 'D' .OR. ICHAR .EQ. 'd') THEN
        CALL DELSET(X,Y,NDAT,NSET,NSETMAX,ISYMBOL)
        IF (NSET .EQ. 0) PRINT *, 'LAST DATASET WAS DELETED NOW'
        GOTO 8

      ELSE IF (ICHAR .EQ. 'S' .OR. ICHAR .EQ. 's') THEN
        CALL SKIP (NRUNIT)
        MPSTART  = .FALSE.
        MPACTIVE = .FALSE.
        MPENDE   = .FALSE.
        GOTO 6

      ELSE IF (ICHAR .EQ. 'I' .OR. ICHAR .EQ. 'i') THEN
        BINTER = .TRUE.
        GOTO 8
      ELSE IF (ICHAR .NE. '') THEN
        WRITE (6,*) 'INVALID INPUT - TRY AGAIN!'
	GOTO 8
      ENDIF        

C***  ENTRY POINT FOR AUTOMATIC
   27 CONTINUE

C**********************************************************************
C***                       PLOTTING                                 ***
C**********************************************************************

200   IF (MPACTIVE .AND. .NOT. MPSTART) GOTO 250

   21 CONTINUE
C***  Define Plotting device and driver
      CALL DEFINDEV (IDEV, IAUTO)
      IF (IDEV .LT. 0) GOTO 350

C**********************************************************************
C***                      OPEN PLOT                                 ***
C**********************************************************************

  225 CONTINUE
C***  USER STATISTICS
      CALL WRSTAT (STATLINE, USER, IDEV)

C***  OPEN PLOT
      CALL GPLOTS (3,IDEV, PSIZEX, PSIZEY)
      MPSTART = .FALSE.

  250 CONTINUE

      CALL COLOR ('INIT', LINE, IDUMMY, IDEV)
      CALL GFACTOR (FORMATFA)
      CALL GPLOT (.0, .0, 3)
      CALL GPLOT (OFSX, OFSY, -3)
      CALL GFACTOR (PLOTSKAL * FORMATFA)

C**********************************************************************
C***                  SET CLIPPING TO FULL PAPER SIZE               ***
C**********************************************************************
C***  Note that OFSX = OFS-Parameter * PLOTSKAL 
      CALL GCPLOT (-OFSX/PLOTSKAL, -OFSY/PLOTSKAL, 997)
      CALL GCPLOT (PSIZEX/FORMATFA/PLOTSKAL-OFSX/PLOTSKAL, 
     >               PSIZEY/FORMATFA/PLOTSKAL-OFSY/PLOTSKAL, 998)
CCC   CALL GCPLOT (PSIZEX-OFSX, PSIZEY-OFSY, 998)

C**********************************************************************
C***                   EXECUTE KASDEF OPTIONS                       ***
C**********************************************************************

C*** FOR THE FIRST CALL OF KDPLOT, START WITH NKDP = 1
      KDPAUSE = .FALSE.
      NKDP = 1
      CALL KDPLOT (B, C, KDLINE, NKD, NKDMAX, NKDP, KDPAUSE, 
     >             IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR, BINSEX, 
     >             XCMA, YCMA, NDATMAX)

C**********************************************************************
C***                   PLOT BOX FRAME (NORMAL SEQUENCE)             ***
C**********************************************************************
      IF (.NOT. LATEBOX) THEN 
         CALL PLOTBOX (HEADER, XTEXT, YTEXT, B, C, NOTICKX, NOTICKY, 
     >              NOTICK2X, NOTICK2Y, ALTX, ALTY, 
     >              NOLABX, NOLABY, NOBOX, SIZELET, LASTPEN, IDEV, 
     >              VAR, MAXVAR, NVAR,NOMINMAX, SIZETIC)
      ELSE
C***     store current color for later box plotting
         IBOXCOLOR = LASTCOLOR
      ENDIF

C**********************************************************************
C***               PLOT SETS OF X-Y-DATA                            ***
C**********************************************************************

C***  DEFINE FRAME FOR CLIPPING
      IF (INBOX) THEN
         CALL GCPLOT (.0, .0, 997)
         CALL GCPLOT (B(1)*(B(3)-B(2)), C(1)*(C(3)-C(2)), 998)
      ENDIF

      DO ISET=1,NSET
        IF (ISETXERR(ISET) .NE. 0) THEN
	   IXE = ISETXERR(ISET)
C***       Check if error-dataset has a valid dataset number
           IF (IXE .LE. 0 .OR. IXE .GT. NSET) THEN
              PRINT *
	      PRINT *, '*** XERROR DATASET NUMBER IS INVALID' 
	      WRITE (*, '(A,I5)') '*** REQUESTED NUMBER:', IXE 
	      WRITE (*, '(A,I5)') '*** NUMBER OF EXISTING SETS:', NSET 
              STOP     '*** ERROR IN SUBR: WRPLOT'
           ENDIF
	   INDEX = NDATMAX * (ISET-1) + 1
	   INDEXE = NDATMAX * (IXE-1) + 1
           CALL PLOTXERR (X(INDEX), Y(INDEX), NDAT(ISET), NDAT(IXE),
     >                    X(INDEXE), Y(INDEXE), ISYMBOL(IXE), 
     >         	          SSIZE(IXE), ICOLOR(IXE), NPEN(IXE), B, C, 
     >                    XERRTYPE(ISET))
        ENDIF
        IF (ISETYERR(ISET) .NE. 0) THEN
	   IYE = ISETYERR(ISET)
C***       Check if error-dataset has a valid dataset number
           IF (IYE .LE. 0 .OR. IYE .GT. NSET) THEN
              PRINT *
	      PRINT *, '*** YERROR DATASET NUMBER IS INVALID' 
	      WRITE (*, '(A,I5)') '*** REQUESTED NUMBER:', IYE 
	      WRITE (*, '(A,I5)') '*** NUMBER OF EXISTING SETS:', NSET 
              STOP     '*** ERROR IN SUBR: WRPLOT'
           ENDIF
	   INDEX = NDATMAX * (ISET-1) + 1
	   INDEXE = NDATMAX * (IYE-1) + 1
           CALL PLOTYERR (X(INDEX), Y(INDEX), NDAT(ISET), NDAT(IYE),
     >                    X(INDEXE), Y(INDEXE), ISYMBOL(IYE), 
     >         	          SSIZE(IYE), ICOLOR(IYE), NPEN(IYE), B, C, 
     >                    YERRTYPE(ISET))
        ENDIF
        CALL PEN (NPEN(ISET), IDEV)
        CALL COLOR ('DATA', LINE, ICOLOR(ISET), IDEV) 
        INDEX = NDATMAX * (ISET-1) + 1
        CALL PLOTDAT (X(INDEX),Y(INDEX),NDAT(ISET),ISYMBOL(ISET)
     >                ,SSIZE(ISET), XCMA, YCMA, B, C, T, 'UNIT', 
     >                VAR, MAXVAR, NVAR, STRIP(1,ISET), ICOLOR(ISET)
     >                , DATASETLINE(ISET))
      ENDDO
C**********************************************************************
C***               PLOT SETS OF IMAGES                              ***
C**********************************************************************
ccc   this branch is disabled - wrh 01.06.2022  
ccc      DO ISETIM=1, NSETIM
ccc        CALL PLOTDATIM (NDATMAXIM, NSETMAXIM, IMPARMAX, ZIM, XIMPAR, 
ccc    >                  ISETIM, B, C)
ccc      ENDDO

C**********************************************************************
C***           EXECUTE DELAYED KASDEF OPTIONS                       ***
C**********************************************************************
C*** FOR THE SECOND CALL OF KDPLOT, GO ON WITH NKDP
C***  this call is now suppressed if KASDEFs are not paused, in order 
C***  to avoid initialization of font and color (wrh 03.03.2007) 
      IF (KDPAUSE)
     >CALL KDPLOT (B, C, KDLINE, NKD, NKDMAX, NKDP, KDPAUSE, 
     >             IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR, BINSEX, 
     >             XCMA, YCMA, NDATMAX)

C**********************************************************************
C***                   PLOT BOX FRAME  (Delayed)                    ***
C**********************************************************************

      IF (LATEBOX) THEN
       CALL COLOR ('DATA', 'DUMMY', IBOXCOLOR, IDEV)
       CALL PLOTBOX (HEADER, XTEXT, YTEXT, B, C, NOTICKX, NOTICKY, 
     >              NOTICK2X, NOTICK2Y, ALTX, ALTY,
     >              NOLABX, NOLABY, NOBOX, SIZELET, LASTPEN, IDEV, 
     >              VAR, MAXVAR, NVAR, NOMINMAX, SIZETIC)
      ENDIF

C**********************************************************************
C***  CALL INTERACTIVE PLOT-ROUTINE IF REQUESTED
C**********************************************************************
      IF (BINTER .AND. IAUTO .NE. 3) THEN 
C***     SET CLIPPING TO FULL PAPER SIZE             
         CALL GCPLOT (-OFSX/PLOTSKAL, -OFSY/PLOTSKAL, 997)
         CALL GCPLOT (PSIZEX/FORMATFA/PLOTSKAL-OFSX/PLOTSKAL, 
     >               PSIZEY/FORMATFA/PLOTSKAL-OFSY/PLOTSKAL, 998)
        CALL INTIN (XINT, YINT, NINTMAX, NINT, NINT2, B, C,
     >              BSAVE, CSAVE, 
     >              KDLINE, NKD, NKDMAX, NKDP,
     >              KDLINE2, NKD2, NKDMAX2,
     >              KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >              BINSEX,
     >              MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, 
     >              TEXTBUTT, INTACT, INTACT2,
     >              X, Y, NDAT, NDATMAX, NSET, NSETMAX, 
     >              ISYMBOL, SSIZE, XCMA, YCMA, T, ICOLOR, NPEN,
     >              ISELSET, COMMLINE, IACT,
     >              X1, Y1, ISET, MPACTIVE, NSCRBUTT, HEADER, STRIP, 
     >              ISETXERR, ISETYERR, XERRTYPE, YERRTYPE, SETNAME)

      ENDIF

C**********************************************************************
C***                  SET CLIPPING TO FULL PAPER SIZE               ***
C**********************************************************************

         CALL GCPLOT (-OFSX/PLOTSKAL, -OFSY/PLOTSKAL, 997)
         CALL GCPLOT (PSIZEX/FORMATFA/PLOTSKAL-OFSX/PLOTSKAL, 
     >               PSIZEY/FORMATFA/PLOTSKAL-OFSY/PLOTSKAL, 998)

C**********************************************************************
C***              RESET ZERO POINT AND                              ***
C***                   CLOSE PLOT                                   ***
C**********************************************************************

      CALL GFACTOR(FORMATFA)
      CALL GPLOT (0.0, 0.0, 3)
      CALL GPLOT (-OFSX, -OFSY, -3)
      IF (.NOT. MPACTIVE) THEN
         IF (CPRGHT) CALL SUBCP(IDEV)
         IF (BINTER .AND. INTACT2 .EQ. 'REFRESH') GOTO 250
         CALL GPLTEND
         BINTER = .FALSE.
         GOTO 6
      ELSE
         GOTO 6
      ENDIF

      IF (BINTER) THEN
        CALL INTMAN (FNAME, XINT, YINT, NINTMAX, NINT, NINT2, 
     >               X, Y, NDAT, NSET, 
     >               NDATMAX, NSETMAX, B, C, BINTER, BSINGLE)
      ENDIF

      IF (IAUTO .EQ. 3 .OR. IAUTO .EQ. 5) GOTO 6

      FORMSTR = '(A)'
      CALL NOLF (FORMSTR) 
       WRITE (6, FORMSTR) 
     >    'SAME PLOT AGAIN ? /N/ (END = CTRL D): '

      READ (5,'(A)', END=100) ICHAR
      IF (ICHAR .EQ. 'Y' .OR. ICHAR .EQ. 'y') GOTO 21

      FORMSTR = '(A)'
      CALL NOLF (FORMSTR)
      WRITE (6, FORMSTR) 
     >  'MANIPULATION OF PLOT DATA? (DEFAULT /N/ = END THIS PLOT): '     
C        ==========================================================
      READ(5,'(A)') ICHAR
      IF (ICHAR .EQ. 'Y' .OR. ICHAR .EQ. 'y') GOTO 8


  350 FORMSTR = '(A)'
      CALL NOLF ( FORMSTR)
      WRITE (6, FORMSTR) 'READ NEXT PLOT FROM SAME FILE? (Y/N) /N/: '
C                         =========================================
      IF (IAUTO .EQ. -1) THEN
        READ (5,'(A)') ICHAR
      ELSE
        ICHAR='Y'
      ENDIF
      IF (ICHAR .EQ. 'Y' .OR. ICHAR .EQ. 'y') THEN
         GOTO 6
        ELSE
         CLOSE (NRUNIT)
         WRITE (6,*) 'FILE CLOSED:', FNAME(1:IDX(FNAME))
         GOTO 1
        ENDIF

  100 STOP 'O.K.'

C**********************************************************************
C***                         ERROR BRANCH                           ***
C**********************************************************************

   99 WRITE (6,98) FNAME(:IDX(FNAME))
   98 FORMAT (/, 1X, 70('*'), /, ' ERROR: CANNOT OPEN FILE: ', A, /,
     >        ' POSSIBLE REASON: READ PERMISSION DENIED', 
     >        /, 1X, 70('*'), /)
      GOTO 1

   97 WRITE (6,96) FNAME(:IDX(FNAME))
   96 FORMAT (/, 1X, 70('*'), /, ' ERROR: CANNOT OPEN FILE: ', A, /,
     >        ' POSSIBLE REASONS: FILE NOT FOUND OR', 
     >        ' READ PERMISSION DENIED', 
     >        /, 1X, 70('*'), /)
      GOTO 1

      END

install.f/      1555506844  5006  320   100644  2173      `
      SUBROUTINE INSTALL
C***********************************************************************
C***  Called from: WRPLOT
C***  Hier werden die installations-abhaengigen Parameter definiert
C***********************************************************************

      CHARACTER DISPLAY*80

C***  Installierte Plotter-Treiber
      COMMON / COMDRIV / CALCOMP, X11OWN, PSOWN
      LOGICAL CALCOMP, X11OWN, PSOWN

C***  Operating system:
      COMMON / COMOS / OPSYS
      CHARACTER*8 OPSYS

C***  Unix Commad 'cat' available?      
      COMMON / COMBC / BCAT
      LOGICAL BCAT

C***  Filename des Benutzerverzeichnisses
      COMMON / COMWRUS / WRUSFIL
      CHARACTER*255 WRUSFIL

C***  Filename der WRPLOT-Statistik:
      COMMON / COMWRSTAT / WRSTATFIL
      CHARACTER*255 WRSTATFIL

C***  Path to the font files
      COMMON / COMFOPA / FONTPATH
      CHARACTER FONTPATH*255, PATH_WRPLOT*255

C***  Estimate largest floating-point number
C***    to be used, e.g., in subr. DOUBREAD
C***    note: HUGE is an intrincic function in F90
C***    for the f77 compiler, it must be provided as an 
C***    external function (in libvax_linux)
      COMMON / COMFPMAX / FPMAX
      FPMAX = 0.5 * HUGE(FPMAX)

      CALCOMP = .FALSE.
      X11OWN = .TRUE.
      PSOWN = .TRUE.
      OPSYS = 'UNIX'
      BCAT = .TRUE.

      CALL GETENV ('PATH_WRPLOT', PATH_WRPLOT)
      IF (PATH_WRPLOT .EQ. '') THEN
         WRITE (*, '(A)') '*** Shell variable PATH_WRPLOT undefined'
         WRITE (*, '(A)') '*** give: setenv PATH_WRPLOT ... '
         STOP 'FATAL ERROR IN SUBROUTINE INSTALL'
      ENDIF
      LFP = IDX(PATH_WRPLOT)
      FONTPATH  = PATH_WRPLOT(:LFP) // '/font.dir/'
      WRUSFIL   = PATH_WRPLOT(:LFP) // '/admin.dir/wruser.dat'
      WRSTATFIL = PATH_WRPLOT(:LFP) // '/admin.dir/wrplot.statistic'

C***  In UNIX Systems: If no DISPLAY known, disable X11 driver
      IF (OPSYS .EQ. 'UNIX' .AND. X11OWN) THEN
         CALL GETENV ('DISPLAY', DISPLAY)
         IF (DISPLAY .EQ. ' ') THEN
            WRITE (6,'(A)') 
     >      '>>> WARNING: No DISPLAY open, X11 driver disabled'
            X11OWN = .FALSE.
            ENDIF
         ENDIF

      RETURN
      END

abun.f/         1653499742  5006  320   100644  1611      `
      SUBROUTINE ABUN

      PARAMETER (NAMAX=10)

      DIMENSION ABXYZ(NAMAX), ATMASS(NAMAX)
      CHARACTER*3 SYMBOL(NAMAX)

4     WRITE(*,*) 'Wieviele Ionen?'
      READ(5,*) NATOM
      IF (NATOM .GT. NAMAX) THEN
        WRITE(*,*) 'Zu viele Ionen!'
        GOTO 4
      ENDIF

      DO 1, NA=1, NATOM
        WRITE(*,*)
        WRITE(*,*) 'Ion Nr.:',NA
        WRITE(*,*)
        WRITE(*,*) 'SYMBOL:'
        READ(5,'(3A)') SYMBOL(NA)
        WRITE(*,*) 'Haeufigkeit (nach Masse): '
        READ(5,'(BN,F10.0)') ABXYZ(NA)
        WRITE(*,*) 'Atomgewicht:'
        READ(5,'(BN,F10.0)') ATMASS(NA)
1     CONTINUE


C***  CALCULATION OF THE MEAN ATOMIC WEIGHT "ATMEAN";
C***  SEARCH FOR THE INDEX OF MAIN ELEMENT "HELIUM"
      ATMEAN=0.0
      NAHE=0
      DO 10 NA=1, NATOM
      ATMEAN=ATMEAN+ABXYZ(NA)*ATMASS(NA)
      IF (SYMBOL(NA) .EQ. 'HE') NAHE=NA
   10 CONTINUE
      IF (NAHE .GT. 0) THEN
         PRINT 11
   11    FORMAT
     >   (1X,' REL. ABUN.:',1X,' BY NUMBER ',2X,'  BY MASS  ',
     >    1X,' REL. TO HE.:',2X,' BY NUMBER ',2X,'  BY MASS  ')
      ELSE
         PRINT 12
   12    FORMAT
     >   (1X,' REL. ABUN.:',1X,' BY NUMBER ',2X,'  BY MASS  ')
      ENDIF

      DO 19 NA=1,NATOM
      ABNA=ABXYZ(NA)
      ATMASNA=ATMASS(NA)
      FRACM=ABNA*ATMASNA/ATMEAN
      IF (NAHE .GT. 0) THEN
         ABHE=ABXYZ(NAHE)
         PRINT 13, SYMBOL(NA),ABNA,FRACM,
     >             SYMBOL(NA),ABNA/ABHE,ABNA*ATMASNA/(ABHE*ATMASS(NAHE))
      ELSE
         PRINT 13, SYMBOL(NA),ABNA,FRACM
      ENDIF
   13 FORMAT (9X,A2,3X,1PE11.4,3X,E11.4,11X,A2,2X,E11.4,3X,E11.4)
   19 CONTINUE

      END

appform.f/      1553528659  5006  320   100644  3489      `
      SUBROUTINE APPFORM
C********************************************************************
C***  KOPIERT ALLE FORMAL.OUT UND FORMAL. FILES GLEICHEN NAMENS   ***
C***  ABER MIT UNTERSCHIEDLICHER VERSIONSNUMMER IN EIN FILE       ***
C********************************************************************

      CHARACTER*255 FNNAMEN, FNFORMAL, FN2FORMAL, FNANF
      CHARACTER*255 FN3FORMAL, FN4FORMAL
      CHARACTER*132 LINE, ACTPAR

C***  EINLESEN DES FILE-NAMENS IN DEM DIE FORMAL-NAMEN GESPEICHERT SIND
      WRITE (*,*) 'NAME DES NAMEN-FILES = '
      CALL GETNAM(FNNAMEN,'[]')
      OPEN (UNIT=1,FILE=FNNAMEN, STATUS='OLD',ERR=99, RECL=132)

C***  EINLESEN DER KEYWORDS
C***    SPLINE  : SPEZIFIEZIERT DIE LINIE, DIE AUSGEWERTET WERDEN SOLL
C***    REDIS   : ELECTRON REDISTRIBUTION (REDIS = (TRUE, FALSE))
C***    FNANF   : GIBT DEN ANFEANG DER FORMAL-NAMEN AN, ZB. FORMAL_C_...
C***    KEYWORD : HINTER DER POSITION DES KEYWORDS WIRD DER WERT EINGELESEN

C*** DUMMY READING KEYWORD
      READ(1, '(A)', END=2) LINE
C*** DUMMY READING KEYWORD
      READ(1, '(A)', END=2) LINE
      READ(1, '(A)', END=2) LINE
      CALL SARGV (LINE, 1, ACTPAR)
      IF (ACTPAR .EQ. '#FNANF') THEN
        CALL SARGV (LINE, 2, ACTPAR)
        FNANF = ACTPAR
      ELSE
        STOP 'ERROR IN READING FNANF'
      ENDIF
C*** DUMMY READING KEYWORD
      READ(1, '(A)', END=2) LINE

C***  EINLESEN DER FORMAL-NAMEN
      NFORMAL = 0
1     IVERS = 0
      READ(1, '(A)', END=2) LINE
      CALL SARGV (LINE, 1, ACTPAR)
      IF (ACTPAR .EQ. '#NAME') THEN
        CALL SARGV (LINE, 2, ACTPAR)
        FNFORMAL = FNANF( :ISTRL(FNANF( :132)))//ACTPAR( :13)//'.OUT'
        FN2FORMAL = FNANF( :ISTRL(FNANF( :132)))//ACTPAR( :13)//'.'
        OPEN (UNIT=2, FILE=FNFORMAL, STATUS='OLD', ERR=50, RECL=132)
        OPEN (UNIT=3, FILE=FN2FORMAL, STATUS='OLD', ERR=52, RECL=132)
        NFORMAL = NFORMAL + 1
        WRITE(*,*) 'NAME DES FORMAL FILES  : ',FNFORMAL( :70)
        WRITE(*,*)
        GOTO 51
      ELSE
        GOTO 1
      ENDIF
   50 WRITE(*,*) 'FILE ',FNFORMAL,' LAESST SICH NICHT OEFFNEN'
      WRITE(*,*) '==========================================='
      WRITE (*,*)
      GOTO 1
   52 WRITE(*,*) 'FILE ',FN2FORMAL,' LAESST SICH NICHT OEFFNEN'
      WRITE(*,*) '==========================================='
      WRITE (*,*)
      GOTO 1
   51 CONTINUE

C***  OEFFNEN DER NEUEN FILES
      OPEN (UNIT=12, FILE=FNFORMAL, STATUS='NEW', RECL=132)
      OPEN (UNIT=13, FILE=FN2FORMAL, STATUS='NEW', RECL=132)
      IVERS = -1
   60 CONTINUE
      READ (2, '(A)', END=61) LINE
      LEN = IDX(LINE)
      IF (LEN .EQ. 0) THEN
        LINE = ' '
        WRITE (12, '(A)') LINE(1:1)
      ELSE
        WRITE (12, '(A)') LINE( :ISTRL(LINE))
      ENDIF
      GOTO 60
   61 CONTINUE
      READ (3, '(A)', END=62) LINE
      LEN = IDX(LINE)
      IF (LEN .EQ. 0) THEN
        LINE = ' '
        WRITE (13, '(A)') LINE(1:1)
      ELSE
        WRITE (13, '(A)') LINE( :ISTRL(LINE))
      ENDIF
      GOTO 61
   62 CONTINUE
      CLOSE (2)
      CLOSE (3)

      IVERS= IVERS - 1
      WRITE (ACTPAR, '(I3)') IVERS
      FN3FORMAL = FNFORMAL( :ISTRL(FNFORMAL( :132))) // ';' // ACTPAR
      FN4FORMAL = FN2FORMAL( :ISTRL(FNFORMAL( :132))) // ';' // ACTPAR
      OPEN (UNIT=2, FILE=FN3FORMAL, STATUS='OLD', ERR=1, RECL=132)
      OPEN (UNIT=3, FILE=FN4FORMAL, STATUS='OLD', ERR=1, RECL=132)
      GOTO 60
     
    2 CLOSE (1)
      GOTO 100

   99 WRITE(*,*) 'OPEN FEHLERHAFT'

  100 CONTINUE

      END

ari.f/          1553528659  5006  320   100644  6389      `
      SUBROUTINE ARI (X, Y, NDAT, NSET, NDATMAX, NSETMAX, B, C, 
     >                ISYMBOL, NPEN, ICOLOR, FNAME)

C**********************************************************************
C***  CALLED FROM: WRPLOT
C***        THIS SUBROUTINE ALLOWS ARITHMETIC OPERATION             ***
C***  + - * /  D=10** L=ALOG10                                      ***
C**********************************************************************

      DIMENSION X(NDATMAX,NSETMAX), Y(NDATMAX,NSETMAX)
      DIMENSION NDAT(NSETMAX), ISYMBOL(NSETMAX), NPEN(NSETMAX)
      DIMENSION ICOLOR(NSETMAX)
      DIMENSION B(6), C(6)
      CHARACTER ICHAR*1
      LOGICAL BCMD

C**********************************************************************
C***             INPUT DATA SET NUMBER(S)                           ***
C**********************************************************************

1     WRITE(6,*) 'EXISTING DATA SETS: ',NSET
      I1=1
      I2=0
      IF (NSET .GT. 1) THEN
2       WRITE(6,'(''$'',A)') 'INPUT DATA SET NR: '
        READ(5,*) I1
        IF (I1 .LT. 1 .OR. I1 .GT. NSET) GOTO 2

C**********************************************************************
C***  OPERATIONS WITH SECOND DATASET?
C**********************************************************************
        WRITE(6,'(''$'',A)') 'OPERATION WITH SECOND DATA SET? /N/ '
        READ(5,'(A)') ICHAR
        IF (ICHAR .EQ. 'Y' .OR. ICHAR .EQ. 'y') THEN
3         WRITE(6,'(''$'',A)') 'INPUT SECOND DATA SET NR: '
          READ(5,*) I2
          IF (I2 .LT. 1 .OR. I2 .GT. NSET) THEN
            WRITE(6,*) 'EXISTING DATA SETS: ',NSET
            GOTO 3
          ENDIF
        ENDIF
      ENDIF

C***  BRANCHING FOR OPERATIONS WITH TWO DATASETS:
      IF (I2 .NE. 0) GOTO 30

C**********************************************************************
C***                  X OR Y - VALUES CHANGED ?                     ***
C***              L0 = 1 : Y - VALUES                               ***
C***                   2 : X - VALUES                               ***
C**********************************************************************
      
      L0=1
      WRITE(6,'(''$'',A)') 'OPERATION WITH X OR Y - VALUES? (X/Y) /Y/ '
      READ(5,'(A)') ICHAR
      IF (ICHAR .EQ. 'X' .OR. ICHAR .EQ. 'x') L0=2      

C**********************************************************************
C***          INPUT ARITHMETIC OPERATOR                             ***
C**********************************************************************

    4 WRITE(6,'(''$'',A)') 'L=ALOG10 / D=10** / R=VRAD [KM/SEC] '
      WRITE(6,'(''$'',A)') 'INPUT OPERATOR (+,-,*,/,D,L): '
      READ(5,'(A)') ICHAR

C**********************************************************************
C***                ARITHMETIC BY NUMBER                            ***
C**********************************************************************

C***  D = DE-LOGARITHM ************************************************
      IF (ICHAR .EQ. 'D' .OR. ICHAR .EQ. 'd') THEN
        IF (L0 .EQ. 1) THEN
          DO 2000 I=1,NDAT(I1)
2000        Y(I,I1)=10.**Y(I,I1)
        ENDIF
        IF (L0 .EQ. 2) THEN
          DO 2001 I=1,NDAT(I1)
2001        X(I,I1)=10.**X(I,I1)
        ENDIF

C***  L = LOGARYTHM ************************************************
      ELSE IF (ICHAR .EQ. 'L' .OR. ICHAR .EQ. 'l') THEN
        IF (L0 .EQ. 1) THEN
          LM=0
          DO 2002 I=1,NDAT(I1)
2002        IF(Y(I,I1) .LE. 0.) LM=1
          IF (LM .EQ. 0) THEN
            DO 2003 I=1,NDAT(I1)
2003          Y(I,I1)=ALOG10(Y(I,I1))
          ELSE
            WRITE(6,'(''$'',A)') 'NEGATIV Y-VALUES, LOG IS NOT POSSIBLE'
          ENDIF
        ENDIF
        IF (L0 .EQ. 2) THEN
          LM=0
          DO 2004 I=1,NDAT(I1)
2004        IF(X(I,I1) .LE. 0.) LM=1
          IF (LM .EQ. 0) THEN
            DO 2005 I=1,NDAT(I1)
2005          X(I,I1)=ALOG10(X(I,I1))
          ELSE
            WRITE(6,'(''$'',A)') 'NEGATIV X-VALUES, LOG IS NOT POSSIBLE'
          ENDIF
        ENDIF

C***  R = RADIAL VELOCITY ************************************************
      ELSE IF (ICHAR .EQ. 'R' .OR. ICHAR .EQ. 'r') THEN
        WRITE(6,'(''$'',A)') 'INPUT VRAD [KM/SEC]: '
        READ(5,*) VRAD
          DO 2006 I=1,NDAT(I1)
2006      X(I,I1) = X(I,I1) * (1. + VRAD/2.9979E+5)

C***  ARITHMETIC OPERATIONS *********************************************
      ELSE IF (ICHAR .EQ. '+' .OR. ICHAR .EQ. '-' .OR. 
     >         ICHAR .EQ. '*' .OR. ICHAR .EQ. '/' ) THEN

      WRITE(6,'(''$'',A)') 'INPUT NUMBER : '
      READ(5,*) R1

      IF (ICHAR .EQ. '-') R1=-R1

      IF (ICHAR .EQ. '/') THEN
        IF (R1 .EQ. .0) THEN
          WRITE (6,*) 'DIVISION BY ZERO FORBIDDEN!'
          GOTO 4
          ENDIF
        R1=1./R1
        ENDIF

      IF (ICHAR .EQ. '+' .OR. ICHAR .EQ. '-') THEN
        IF (L0 .EQ. 1) CALL ARINUM (Y, NDAT, NDATMAX, NSETMAX,I1,R1,1.)
        IF (L0 .EQ. 2) CALL ARINUM (X, NDAT, NDATMAX, NSETMAX,I1,R1,1.)
        ENDIF

      IF (ICHAR .EQ. '*' .OR. ICHAR .EQ. '/') THEN
        IF (L0 .EQ. 1) CALL ARINUM (Y, NDAT, NDATMAX, NSETMAX,I1,0.,R1)
        IF (L0 .EQ. 2) CALL ARINUM (X, NDAT, NDATMAX, NSETMAX,I1,0.,R1)
        ENDIF

      ELSE
      WRITE (6,*) 'INVALID OPERATOR - REPEAT INPUT!'
      GOTO 4
      ENDIF

      GOTO 99


C**********************************************************************
C***          ARITHMETIC WITH TWO DATASETS                          ***
C**********************************************************************

C***  DEFINE INPUT OPERATOR 
30    WRITE(6,'(''$'',A)') 'INPUT OPERATOR (+,-,*,/): '
      READ(5,'(A)') ICHAR
      IF (ICHAR .NE. '+' .AND. ICHAR .NE. '-' .AND. 
     >         ICHAR .NE. '*' .AND. ICHAR .NE. '/' ) GOTO 30

      BCMD = .FALSE.
      CALL ARISET (X, Y, I1, I2, NDAT, NSET, NDATMAX, NSETMAX,
     >             ISYMBOL, NPEN, ICOLOR, ICHAR, BCMD, .FALSE.)


C**********************************************************************
C***  CONTINUE OR LEAVE ARITHMETIC OPERATIONS
C**********************************************************************
   99 CONTINUE
      WRITE(6,'(''$'',A)') 'MORE ARITHMETIC OPERATIONS ? /Y/ '
      READ(5,'(A)') ICHAR
      IF (ICHAR .NE. 'N' .AND. ICHAR .NE. 'n') GOTO 1

C***  OPTIONAL SAVING OF NEW DATASET ON DISK FILE
      CALL SAVESET (X(1,I1), Y(1,I1), NDAT(I1), ISYMBOL(I1), NPEN(I1), 
     >              FNAME, .TRUE.)

      RETURN
      END

arinum.f/       1553528659  5006  320   100644  502       `
      SUBROUTINE ARINUM (X, NDAT, NDATMAX, NSETMAX, I1, R1, R2)

C**********************************************************************
C***  CALLED FROM SUBROUTINE ARI (WRPLOT-PROGRAM)
C***  DATASET ARITHMETIC:
C***          X(..,I1)=X(..,I1) * R2 + R1                           ***
C**********************************************************************

      DIMENSION X(NDATMAX,NSETMAX)
      DIMENSION NDAT(NSETMAX)

      DO 1 I=1,NDAT(I1)
1       X(I,I1)=X(I,I1)*R2+R1

      RETURN
      END
ariset.f/       1553528659  5006  320   100644  9675      `
      SUBROUTINE ARISET (X, Y, I1, I2, NDAT, NSET, NDATMAX, NSETMAX,
     >                   ISYMBOL, NPEN, ICOLOR, ICHAR, BCMD, BARI2)

C**********************************************************************
C***  CALLED FROM: SUBROUTINE ARI (WRPLOT PROGRAM)
C***      ADDITION OF Y - VALUES FROM DATASET I1 AND I2             ***
C**********************************************************************

C***  BCMD = TRUE  :  ARISET CALLED BY EXCMD
C***                  CALCULATED VALUES STORED IN DATASET I1

C**********************************************************************
C***    SMALLEST DIFFERENCE BETWEEN TWO POINTS                       ***
C**********************************************************************

      PARAMETER (EPS=1.E-15)

      DIMENSION X(NDATMAX,NSETMAX), Y(NDATMAX,NSETMAX)

C!!!  Wird nicht mehr benoetigt
C!!!!!!!!!!  ACHTUNG, FESTE DIMENSIONIERUNG !!!!!!!!!!!!!!!
C!!!      DIMENSION X1(32000), Y1(32000)

      DIMENSION NDAT(NSETMAX), ISYMBOL(NSETMAX), NPEN(NSETMAX)
      DIMENSION ICOLOR(NSETMAX)
      CHARACTER ICHAR*1
      LOGICAL   SET1, SET2, BCMD, BARI2

C**********************************************************************
C***    EXPLANATION OF SOME VARIABLES                               ***
C***    I1 : NUMBER OF FIRST  DATASET                               ***
C***    I2 : NUMBER OF SECOND DATASET                               ***
C***    L1 : COUNTER [1..NDAT(I1)]                                  ***
C***    L2 : COUNTER [1..NDAT(I2)]                                  ***
C***    BARI2 : IF .TRUE. DO NOT INTERPOLATE THE FIRST DATASET      ***
C**********************************************************************

C**********************************************************************
C***                   NEW DATA SET NR.                             ***
C**********************************************************************

      IF (NSET .LT. NSETMAX) THEN
        NSET = NSET + 1
        I3 = NSET
      ELSE
        WRITE(6,'(''$'',A)') 'NO MORE DATASETS, ARI SKIPPED'
        RETURN
      ENDIF

C**********************************************************************
C***         CHECK Y - VALUES FOR DIVISION                          ***
C**********************************************************************

      IF (ICHAR .EQ. '/') THEN
        DO 5 I=1,NDAT(I2)
          IF (ABS(Y(I,I2)) .EQ. 0 ) THEN
            WRITE (6, '(A,I4,A)' ) 
     >         'Y2(', I, ')0 ==> DIVISION SKIPPED IN ARISET'
            RETURN
          ENDIF
5       CONTINUE
      ENDIF

C**********************************************************************
C***    NOTE: X-VALUES OF BOTH DATASETS MUST BE EITHER IDENTICAL
C***          OR IN MONOTONIC ORDER
C**********************************************************************

C**********************************************************************
C***  SPECIAL BRANCH FOR IDENTICAL X-TABLES:
C**********************************************************************
      IF (NDAT(I1) .NE. NDAT(I2)) GOTO 17
      DO 19 I=1, NDAT(I1)
      IF (X(I,I1) .NE. X(I,I2) ) GOTO 17
   19 CONTINUE

      DO 18 I=1, NDAT(I1)
          X(I,I3) = X(I,I1)
          IF (ICHAR .EQ. '+') Y(I,I3) = Y(I,I1) + Y(I,I2)
          IF (ICHAR .EQ. '-') Y(I,I3) = Y(I,I1) - Y(I,I2)
          IF (ICHAR .EQ. '*') Y(I,I3) = Y(I,I1) * Y(I,I2)
          IF (ICHAR .EQ. '/') Y(I,I3) = Y(I,I1) / Y(I,I2)
   18 CONTINUE
      NDAT(I3) = NDAT(I1)
      GOTO 111

C***  FROM HERE: BRANCH FOR NON-IDENTICAL X-VALUES --> INTERPOLATION
   17 CONTINUE
C**********************************************************************
C***      PUT X-VALUES IN INCREASING ORDER                          ***
C**********************************************************************

      IF (X(2,I1) .LT. X(1,I1)) THEN
        DO 1 I=1,NDAT(I1)
          X(I,I3)=X(NDAT(I1)-I+1,I1)
1         Y(I,I3)=Y(NDAT(I1)-I+1,I1)
        DO 2 I=1,NDAT(I1)
          X(I,I1)=X(I,I3)
2         Y(I,I1)=Y(I,I3)
      ENDIF
      IF (X(2,I2) .LT. X(1,I2)) THEN
        DO 3 I=1,NDAT(I2)
          X(I,I3)=X(NDAT(I2)-I+1,I2)
3         Y(I,I3)=Y(NDAT(I2)-I+1,I2)
        DO 4 I=1,NDAT(I2)
          X(I,I2)=X(I,I3)
4         Y(I,I2)=Y(I,I3)
      ENDIF
       
C**********************************************************************
C***         CHECK MONOTONIC ORDER
C**********************************************************************

      DO 15 I=2, NDAT(I1)
         IF (X(I,I1) .LT. X(I-1,I1) ) THEN
            WRITE (6, *) 'FIRST DATASET NOT MONOTONIC'
            STOP 'ERROR IN DATASET ARITHMETIC'
            ENDIF
   15 CONTINUE

      DO 16 I=2, NDAT(I2)
         IF (X(I,I2) .LT. X(I-1,I2) ) THEN
            WRITE (6, *) 'SECOND DATASET NOT MONOTONIC'
            STOP 'ERROR IN DATASET ARITHMETIC'
            ENDIF
   16 CONTINUE

C**********************************************************************
C***                 CALCULATE NEW (X,Y) POINTS                     ***
C**********************************************************************

      L1=1
      L2=1
      SET1=.TRUE.
      SET2=.TRUE.

      IF (X(L1,I1) .LT. X(L2,I2)) THEN
57      L1 = L1 + 1
        IF (X(L1,I1) .LT. X(L2,I2)) GOTO 57
      ELSE
        IF (X(L2,I2) .LT. X(L1,I1)) THEN
58        L2 = L2 + 1
          IF (X(L2,I2) .LT. X(L1,I1)) GOTO 58
        ENDIF
      ENDIF

      I=1
6     IF (X(L1,I1) .EQ. X(L2,I2)) THEN
C***  Next two X-points are identical in both Datasets
          X(I,I3)=X(L1,I1)  
          IF (ICHAR .EQ. '+') Y(I,I3) = Y(L1,I1) + Y(L2,I2)
          IF (ICHAR .EQ. '-') Y(I,I3) = Y(L1,I1) - Y(L2,I2)
          IF (ICHAR .EQ. '*') Y(I,I3) = Y(L1,I1) * Y(L2,I2)
          IF (ICHAR .EQ. '/') Y(I,I3) = Y(L1,I1) / Y(L2,I2)
          I=I+1
          IF (L1 .LT. NDAT(I1)) THEN
            L1=L1+1
          ELSE
            SET1=.FALSE.
          ENDIF
          IF (L2 .LT. NDAT(I2)) THEN 
            L2=L2+1
          ELSE
            SET2=.FALSE.
          ENDIF

      ELSE  IF (X(L1,I1) .LT. X(L2,I2)) THEN
C***  X-POINT DEFINED BY DATASET 1 --> DATASET 2 INTERPOLATED
          X(I,I3)=X(L1,I1)  

          K1=L2-1
          IF (K1 .EQ. 0) K1=K1+1
          K2=K1+1
          IF (K2 .GT. NDAT(I2)) THEN
            K2=K2-1
            K1=K2-1
          ENDIF
7         IF (X(K2,I2) .EQ. X(K1,I2)) THEN
            K1=K1-1
            IF (K1 .EQ. 0) THEN
              K1=K1+1
              K2=K2+1
            ENDIF
            GOTO 7
          ENDIF
C***  SPLINE INTERPOLATION IF SYMBOL OF SECOND DATASET IS 6 OR 7
          IF (ISYMBOL(I2) .NE. 6 .AND. 
     >        ISYMBOL(I2) .NE. 7) THEN
            Q = (X(I,I3) - X(K1,I2)) / (X(K2,I2) - X(K1,I2))
            YINPO = (1.-Q) * Y(K1,I2) + Q * Y(K2,I2)
          ELSE
            CALL FSPLINE (YINPO, X(L1,I1), Y(1,I2), X(1,I2), NDAT(I2))
          ENDIF

          IF (ICHAR .EQ. '+') Y(I,I3) = Y(L1,I1) + YINPO
          IF (ICHAR .EQ. '-') Y(I,I3) = Y(L1,I1) - YINPO
          IF (ICHAR .EQ. '*') Y(I,I3) = Y(L1,I1) * YINPO
          IF (ICHAR .EQ. '/') Y(I,I3) = Y(L1,I1) / YINPO
          I=I+1
          IF (L1 .LT. NDAT(I1)) THEN
            L1=L1+1
          ELSE
            SET1=.FALSE.
          ENDIF
        ELSE

C***  X-POINT DEFINED BY DATASET 2 --> DATASET 1 INTERPOLATED
         IF (.NOT. BARI2) THEN
          X(I,I3)=X(L2,I2)

          K1=L1-1
          IF (K1 .EQ. 0) K1=K1+1
          K2=K1+1
          IF (K2 .GT. NDAT(I1)) THEN
            K2=K2-1
            K1=K2-1
          ENDIF
8         IF (X(K2,I1) .EQ. X(K1,I1)) THEN
            K1=K1-1
            IF (K1 .EQ. 0) THEN
              K1=K1+1
              K2=K2+1
            ENDIF
            GOTO 8
          ENDIF
C***  SPLINE INTERPOLATION IF SYMBOL OF FIRST DATASET IS 6 OR 7
          IF (ISYMBOL(I1) .NE. 6 .AND. 
     >        ISYMBOL(I1) .NE. 7) THEN
            Q = (X(I,I3) - X(K1,I1)) / (X(K2,I1) - X(K1,I1))
            YINPO =(1. -Q) * Y(K1,I1) + Q * Y(K2,I1)
          ELSE
            CALL FSPLINE (YINPO, X(L2,I2), Y(1,I1), X(1,I1), NDAT(I1))
          ENDIF

          IF (ICHAR .EQ. '+') Y(I,I3) = YINPO + Y(L2,I2)
          IF (ICHAR .EQ. '-') Y(I,I3) = YINPO - Y(L2,I2)
          IF (ICHAR .EQ. '*') Y(I,I3) = YINPO * Y(L2,I2)
          IF (ICHAR .EQ. '/') Y(I,I3) = YINPO / Y(L2,I2)
          I=I+1
         ENDIF ! end of BARI2 - interpolation of dataset1 skipping 
          IF (L2 .LT. NDAT(I2)) THEN 
            L2=L2+1
          ELSE
            SET2=.FALSE.
          ENDIF
        ENDIF
      IF (SET1 .AND. SET2) GOTO 6
   11 NDAT(I3) = I - 1

      IF (BARI2 .AND. (NDAT(I3) .LT. NDAT(I1))) WRITE 
     > (*,'(A,I8$)') 
     > " ++ WARNING ++ ARI : N DECREASED TO ", NDAT(I3)

  111 CONTINUE
      IF (.NOT. BCMD) THEN
C**********************************************************************
C***                   SAVE NEW DATA IN DATASET                     ***
C**********************************************************************

      ISYMBOL(I3) = ISYMBOL(I1)
      NPEN   (I3) = NPEN   (I1)
      ICOLOR (I3) = ICOLOR (I1)
      WRITE(6,*) 'NEW DATA SAVED IN SET NR: ',I3

C**********************************************************************
C***    INVERSION OF Y(I2) IF NOT OVERWRITTEN BY NEW DATA SET       ***
C**********************************************************************

      IF (ICHAR .EQ. '-' .AND. I3 .NE. I2) THEN
        DO 14 I=1,NDAT(I2)
14        Y(I,I2)=-Y(I,I2)
        ENDIF

C*** FOR POSSIBLE SAVING OF NEW DATASET: RETURN I1 AS NUMBER OF NEW SET
      I1 = I3

      ELSE
        NDAT(I1) = NDAT(I3)
        NSET = NSET - 1
        DO 20 I=1, NDAT(I1)
          X(I,I1) = X(I,I3)
          Y(I,I1) = Y(I,I3)
   20   CONTINUE

      ENDIF

      RETURN
      END

austart.f/      1553528659  5006  320   100644  1744      `
      SUBROUTINE AUSTART
C********************************************************************
C***  COPIES AU_TEMP.JOB INTO AU_TEMP2.JOB AND ACTIVATES THE      ***
C***  NEXT #NAME=M LINE                                           ***
C********************************************************************

      LOGICAL BRUN
      CHARACTER*255 ACTPAR
      CHARACTER*132 LINE

C***  ABFRAGE OB NOCH EIN JOB COPIERT WERDEN SOLL
C***    (WENN DAS NAME=...  STATEMENT NICHT DAS LETZTE VOR ENDENAMEN IST)
C***
      OPEN (UNIT=1, FILE='AU_TEMP.JOB', STATUS='OLD', ERR=90)
    1 CONTINUE
      READ(1, '(A)', END=100) LINE
      IF (LINE( :4) .NE. 'NAME') THEN
        GOTO 1
      ELSE
    2   CONTINUE
        READ(1, '(A)', END=100) LINE
        IF (LINE( :5) .EQ. '#NAME') THEN
          BRUN = .TRUE.
        ELSE IF (LINE( :10) .EQ. '#ENDENAMEN') THEN
          BRUN = .FALSE.
        ELSE
          GOTO 2
        ENDIF
      ENDIF

      REWIND(1)

      IF (.NOT. BRUN) GOTO 110

C***  UMSPEICHERN VON AU_TEMP.JOB NACH AU_TEMP2.JOB
C***    NAME WIRD EINEN SCHRITT WEITER GESTEZT

      OPEN (UNIT=2, FILE='AU_TEMP2.JOB', STATUS='NEW', ERR=95, RECL=132)

    5 CONTINUE

      READ (1, '(A)', END=100) LINE
      IF (LINE( :4) .NE. 'NAME') THEN
        WRITE (2, '(A)') LINE( :ISTRL(LINE))
      ELSE
        WRITE (2, '(A)') '#'//LINE( :ISTRL(LINE))
    6   READ (1, '(A)', END=100) LINE
        IF (LINE( :5) .NE. '#NAME') THEN
          WRITE (2, '(A)') LINE( :ISTRL(LINE))
          GOTO 6
        ELSE
          WRITE (2, '(A)') LINE(2:ISTRL(LINE))
        ENDIF
      ENDIF

      GOTO 5

   90 WRITE(*,*) 'ERROR IN UNIT=1'
      GOTO 200

   95 WRITE(*,*) 'ERROR IN UNIT=2'
      GOTO 200

  100 CLOSE (2)
  110 CLOSE (1)

  200 END
blend.f/        1653499974  5006  320   100644  13695     `
      SUBROUTINE BLEND
C********************************************************************
C***  BERECHNET ALLE MOEGLICHEN BLENDS ZWISCHEN DEN ENERGIE-NIVEAUS,*
C***    DIE IN DER DATEI BLENDIN.DAT ANGEGEBEN SIND.              ***
C********************************************************************

      PARAMETER (MAXELEM = 23)
      PARAMETER (NLEVMAX=500)

      CHARACTER*6 ELEM(MAXELEM)
      CHARACTER*11 STERM(NLEVMAX)
      CHARACTER*60 LINE, ACTPAR
      DIMENSION ITERM(NLEVMAX,6), TERME(NLEVMAX)
      LOGICAL ATERM(NLEVMAX)

C***  ITERM (...,1) : ELEMENTNUMMER
C***  ITERM (...,2) : n
C***  ITERM (...,3) : l
C***  ITERM (...,4) : MULTIPLIZITAET
C***  ITERM (...,5) : L
C***  ITERM (...,6) : l OF SECOND ELECTRON

C***  TERME (...)   : LEVEL-ENERGY

C***  ATERM (...)   : BOOLEAN DEPENDS WETHER THE LEVEL IS AN AUTOIONISATION 
C***                  LEVEL OR NOT

      PARAMETER (NLINMAX=40000)
      DIMENSION LINEIND(NLINMAX,2), XLINE(NLINMAX)

      ELEM(1)  = 'HEI'
      ELEM(2)  = 'HEII'
      ELEM(3)  = 'CI'
      ELEM(4)  = 'CII'
      ELEM(5)  = 'C3'
      ELEM(6)  = 'CIV'
      ELEM(7)  = 'HEIII'
      ELEM(8)  = 'NII'
      ELEM(9)  = 'NIII'
      ELEM(10) = 'N3'
      ELEM(11) = 'NIV'
      ELEM(12) = 'N4'
      ELEM(13) = 'NV'
      ELEM(14) = 'NVI'
      ELEM(15) = 'OI'
      ELEM(16) = 'OII'
      ELEM(17) = 'OIII'
      ELEM(18) = 'OIV'
      ELEM(19) = 'OV'
      ELEM(20) = 'OVI'
      ELEM(21) = 'OVII'
      ELEM(22) = 'HI'
      ELEM(23) = 'O8'

      NLEVEL = 0

      OPEN (UNIT=1, FILE='blendin.dat', STATUS='OLD', ERR=99)

C***  EINLESEN DER LEVEL-INFORMATIONEN
1     READ (1, '(A)', END=5) LINE
        IF (LINE(1:1) .EQ. '*') GOTO 1
        CALL SARGV (LINE, 1, ACTPAR)
        IF (ACTPAR .NE. 'LEVEL') GOTO 1
        NLEVEL = NLEVEL + 1
        IF (NLEVEL .GT. NLEVMAX) THEN
          WRITE (6,*) 'LEVEL DIMENSION INSUFFICIENT'
          STOP
        ENDIF
C***  READ AUTOIONISATION LEVEL
        ACTPAR = LINE(12:12)
        IF (ACTPAR .EQ. '#') THEN
          ATERM(NLEVEL) = .TRUE.
        ELSE
          ATERM(NLEVEL) = .FALSE.
        ENDIF
C***  READ LEVEL NAME
        ACTPAR = LINE(13:23)
        STERM(NLEVEL) = ACTPAR
        ACTPAR = LINE(32:40)
        READ (ACTPAR, '(F13.4)') TERME(NLEVEL)
      GOTO 1
5     CLOSE (1)

C***  ENTSCHLUESSELN DES ELEMENTES
      DO 10 I=1, NLEVEL
        K = 1
        LINE(K:K) = STERM(I)(K:K)
        DO 15 J=2, 10
          IF (STERM(I)(J:J) .NE. ' ') THEN
            K = K + 1
            LINE(K:K) = STERM(I)(J:J)
          ENDIF
15      CONTINUE
        DO 20 J=1, MAXELEM
          L = IDX(ELEM(J))
          IF (LINE(1:L) .EQ. ELEM(J)) THEN
            ITERM(I,1) = J
            IF (ITERM(I,1) .EQ. 10) ITERM(I,1) = 9
            IF (ITERM(I,1) .EQ. 12) ITERM(I,1) = 11
          ENDIF
20      CONTINUE
10    CONTINUE


C***  ENTSCHLUESSELN DER TERMBEZEICHNUNGEN NACH ELEMENTEN SORTIERT
      DO 30 I=1, NLEVEL

        IF (ITERM(I,1) .EQ. 1.) THEN
C***      HEI FOUND
C------------------
C***      READ n
          READ (STERM(I)(5:5), '(I1)') ITERM(I,2)
C***      READ l
          ITERM(I,3) = IDAM(STERM(I)(6:6))
C***      READ MULTPLICITY
          READ (STERM(I)(7:7), '(I1)') ITERM(I,4)
          ITERM(I,5) = ITERM(I,3)
          ITERM(I,6) = 0

        ELSE IF (ITERM(I,1) .EQ. 2.) THEN
C***      HEII FOUND
C-------------------
C***      READ n
          IF (STERM(I)(9:9) .EQ. '.') THEN
            READ (STERM(I)(10:10), '(I1)') ITERM(I,2)
          ELSE
            READ (STERM(I)(9:10), '(I2)') ITERM(I,2)
          ENDIF
C***      SET OTHER PARAMETER
          ITERM(I,3) = -1
          ITERM(I,4) = 2
          ITERM(I,5) = -1
          ITERM(I,6) = 0
          TERME(I) = (1. - 1./FLOAT(ITERM(I,2)**2) * 438889.2)

        ELSE IF (ITERM(I,1) .EQ. 7) THEN
C***      HEIII FOUND
C-------------------
          WRITE(*,*) 'HEIII FOUND'
          STOP

        ELSE IF (ITERM(I,1) .EQ. 3) THEN
C***      CI FOUND
C-------------------
          WRITE(*,*) 'CI FOUND'
          STOP

        ELSE IF (ITERM(I,1) .EQ. 4) THEN
C***      CII FOUND
C-------------------
          WRITE(*,*) 'CII FOUND'
          STOP

        ELSE IF (ITERM(I,1) .EQ. 5) THEN
C***      C3 FOUND
C-------------------
C***      READ n
          READ (STERM(I)(4:4), '(I1)') ITERM(I,2)
C***      READ l
          ITERM(I,3) = IDAM(STERM(I)(5:5))
C***      READ MULTPLICITY
          READ (STERM(I)(6:6), '(I1)') ITERM(I,4)
C***      READ L
          ITERM(I,5) = IDAM(STERM(I)(7:7))
C***      READ l OF INNER ELECTRON
          ITERM(I,6) = IDAM(STERM(I)(8:8))

        ELSE IF (ITERM(I,1) .EQ. 6) THEN
C***      C IV FOUND
C-------------------
C***      READ n
          READ (STERM(I)(5:6), '(I2)') ITERM(I,2)
C***      READ l
          ITERM(I,3) = IDAM(STERM(I)(7:7))
          ITERM(I,4) = 2
          ITERM(I,5) = ITERM(I,3)
          ITERM(I,6) = 0

        ELSE IF (ITERM(I,1) .EQ. 8) THEN
C***      NII FOUND
C-------------------
          WRITE(*,*) 'NII FOUND'
          STOP

        ELSE IF (ITERM(I,1) .EQ. 9) THEN
C***      NIII FOUND
C-------------------
          WRITE(*,*) 'NIII FOUND'
          IF (STERM(I)(6:6) .EQ. '''' .OR.
     >        STERM(I)(6:6) .EQ. '"') THEN
            READ (STERM(I)(4:4), '(I1)') ITERM(I,2)
            ITERM(I,3) = IDAM(STERM(I)(5:5))
            ITERM(I,5) = IDAM(STERM(I)(7:7))
            READ (STERM(I)(8:8), '(I1)') ITERM(I,4)
            IF (STERM(I)(9:9) .EQ. '''') THEN
              ITERM(I,6) = 2
            ELSE
              ITERM(I,6) = 1
            ENDIF            
          ELSE
            READ (STERM(I)(6:6), '(I1)') ITERM(I,2)
            ITERM(I,3) = IDAM(STERM(I)(7:7))
            ITERM(I,5) = ITERM(I,3)
            READ (STERM(I)(8:8), '(I1)') ITERM(I,4)
            ITERM(I,6) = 0
          ENDIF

        ELSE IF (ITERM(I,1) .EQ. 11) THEN
C***      NIV FOUND
        WRITE(*,*) 'NIV FOUND'
C-------------------
C*** SEARCH FOR ' IN THE LEVEL-STRING
          IF (STERM(I)(6:6) .EQ. '''' .OR.
     >        STERM(I)(7:7) .EQ. '''') THEN
            IF (STERM(I)(6:6) .EQ. '''') THEN
              J = 6
            ELSE
              J = 7
            ENDIF
            READ (STERM(I)(J-2:J-2), '(I1)') ITERM(I,2)
            ITERM(I,3) = IDAM(STERM(I)(J-1:J-1))
            ITERM(I,5) = IDAM(STERM(I)(J+1:J+1))
            READ (STERM(I)(J+2:J+2), '(I1)') ITERM(I,4)
            ITERM(I,6) = 1
          ELSE
            IF (STERM(I)(5:5) .EQ. ' ') THEN
              J = 6
            ELSE
              J = 5
            ENDIF
            READ (STERM(I)(J:J), '(I1)') ITERM(I,2)
            ITERM(I,3) = IDAM(STERM(I)(J+1:J+1))
            ITERM(I,5) = ITERM(I,3)
            READ (STERM(I)(J+2:J+2), '(I1)') ITERM(I,4)
            ITERM(I,6) = 0
          ENDIF            

        ELSE IF (ITERM(I,1) .EQ. 13) THEN
C***      NV FOUND
        WRITE(*,*) 'NV FOUND'
C-------------------
C***      READ n
          READ (STERM(I)(4:5), '(I2)') ITERM(I,2)
C***      READ l
          ITERM(I,3) = IDAM(STERM(I)(6:6))
          ITERM(I,4) = 2
          ITERM(I,5) = ITERM(I,3)
          ITERM(I,6) = 0

        ELSE IF (ITERM(I,1) .EQ. 14) THEN
C***      NVI FOUND
C-------------------
          WRITE(*,*) 'NVI FOUND'
          STOP

        ELSE IF (ITERM(I,1) .EQ. 15) THEN
C***      OI FOUND
C-------------------
          WRITE(*,*) 'OI FOUND'
          STOP

        ELSE IF (ITERM(I,1) .EQ. 16) THEN
C***      OII FOUND
C-------------------
          WRITE(*,*) 'OII FOUND'
          STOP

        ELSE IF (ITERM(I,1) .EQ. 17) THEN
C***      OIII FOUND
C-------------------
          WRITE(*,*) 'OIII FOUND'
          STOP

        ELSE IF (ITERM(I,1) .EQ. 18) THEN
C***      OIV FOUND
C-------------------
          WRITE(*,*) 'OIV FOUND'
          STOP

        ELSE IF (ITERM(I,1) .EQ. 19) THEN
C***      OV FOUND
C-------------------
C***      READ n
          READ (STERM(I)(4:4), '(I1)') ITERM(I,2)
C***      READ l
          ITERM(I,3) = IDAM(STERM(I)(5:5))
C***      READ MULTPLICITY
          READ (STERM(I)(8:8), '(I1)') ITERM(I,4)
C***      READ L
          ITERM(I,5) = IDAM(STERM(I)(9:9))
C***      READ l OF INNER ELECTRON
          IF (STERM(I)(6:6) .EQ. '''') THEN
            ITERM(I,6) = 1
          ELSE
            ITERM(I,6) = 0
          ENDIF

        ELSE IF (ITERM(I,1) .EQ. 20) THEN
C***      O VI FOUND
C-------------------
C***      READ n
          READ (STERM(I)(6:6), '(I1)') ITERM(I,2)
C***      READ l
          IF (STERM(I)(7:7) .NE. 'L') THEN
            ITERM(I,3) = IDAM(STERM(I)(8:8))
          ELSE
            ITERM(I,3) = IDAM(STERM(I)(7:7))
          ENDIF
          ITERM(I,4) = 2
          ITERM(I,5) = ITERM(I,3)
          ITERM(I,6) = 0

        ELSE IF (ITERM(I,1) .EQ. 21) THEN
C***      OVII FOUND
C-------------------
          WRITE(*,*) 'OVII FOUND'
          IF (STERM(I)(7:7) .EQ. '.') THEN
            READ (STERM(I)(6:6), '(I1)') ITERM(I,2)
          ELSE
            READ (STERM(I)(6:7), '(I2)') ITERM(I,2)
          ENDIF
C***      SET OTHER PARAMETER
          ITERM(I,3) = -1
          ITERM(I,4) = 2
          ITERM(I,5) = -1
          ITERM(I,6) = 0

        ELSE IF (ITERM(I,1) .EQ. 23) THEN
C***      OVII FOUND
C-------------------
          WRITE(*,*) 'OVIII FOUND'
          IF (STERM(I)(7:7) .EQ. '.') THEN
            READ (STERM(I)(6:6), '(I1)') ITERM(I,2)
          ELSE
            READ (STERM(I)(6:7), '(I2)') ITERM(I,2)
          ENDIF
C***      SET OTHER PARAMETER
          ITERM(I,3) = -1
          ITERM(I,4) = 2
          ITERM(I,5) = -1
          ITERM(I,6) = 0

        ELSE IF (ITERM(I,1) .EQ. 22) THEN
C***      H I FOUND
C-------------------
          IF (STERM(I)(9:9) .EQ. '.') THEN
            READ (STERM(I)(10:10), '(I1)') ITERM(I,2)
          ELSE
            READ (STERM(I)(9:10), '(I2)') ITERM(I,2)
          ENDIF
C***      SET OTHER PARAMETER
          ITERM(I,3) = -1
          ITERM(I,4) = 2
          ITERM(I,5) = -1
          ITERM(I,6) = 0
          TERME(I) = (1. - 1./FLOAT(ITERM(I,2)**2) * 109677.584)

        ENDIF
30    CONTINUE

      DO 90 I=1,NLEVEL
        IF (ATERM(I)) THEN
          STERM(I) = '#' // STERM(I)
        ELSE
          STERM(I) = ' ' // STERM(I)
        ENDIF
        WRITE(*,91) STERM(I), (ITERM(I,J), J=1,6),TERME(I)
91      FORMAT (' Level: ',A11,'   Nr.',I2, ' n=',I2, ' l=',I2, ' M=',
     >          I2, ' L=',I2, ' li=',I2, '       ',F10.2)
        STERM(I) = STERM(I)(2:11)
90    CONTINUE

C***  BERECHNUNG DER EINZELNEN UEBERGAENGE
      ILINE = 0
      DO 40 I=1, NLEVEL
        DO 50 J=1, NLEVEL
C***  SAME ELEMENT AND ELOW < EUP
          IF (ITERM(I,1) .EQ. ITERM(J,1) .AND.
     >        TERME(I) .LT. TERME(J)) THEN
C***  SAME MULTIPLET
            IF (ITERM(I,4) .EQ. ITERM(J,4)) THEN
C***  BERECHNUNG DER SUMME DER EINZELDREHIMPULSE
              IP = ITERM(I,3) + ITERM(I,6)
              JP = ITERM(J,3) + ITERM(J,6)
C***  ZUSAMMENGEFASSTES NIVEAU
              IF (ITERM(I,5) .EQ. -1 .OR. ITERM(J,5) .EQ. -1  .OR.
C***  AENDERUNG DER SUMME DER DREHIMPULSE UM 1
     >          ABS(JP - IP) .EQ. 1) THEN
                ILINE = ILINE + 1
                IF (NLEVEL .GT. NLINMAX) THEN
                  WRITE (6,*) 'LINE DIMENSION INSUFFICIENT'
                  STOP
                ENDIF
                LINEIND(ILINE,1) = I
                LINEIND(ILINE,2) = J
                XLINE(ILINE) = 1.E8 / (TERME(J) - TERME(I))
              ENDIF
            ENDIF
          ENDIF
50      CONTINUE
40    CONTINUE

C*** SORTIEREN NACH LAMBDA
      DO 52 K=1, ILINE
        DO 52 I=1, ILINE-1
            J = I + 1
            IF (XLINE(I) .GT. XLINE(J)) THEN
              X = XLINE(I)
              XLINE(I) = XLINE(J)
              XLINE(J) = X
              M = LINEIND(I,1)
              LINEIND(I,1) = LINEIND(J,1)
              LINEIND(J,1) = M
              M = LINEIND(I,2)
              LINEIND(I,2) = LINEIND(J,2)
              LINEIND(J,2) = M
            ENDIF
52    CONTINUE

      OPEN (UNIT=2, FILE='blendout.dat', STATUS='UNKNOWN', ERR=98)
C***  PRINTOUT THE LINES BETWEEN "NORMAL" LEVELS
      WRITE(2,*) 'LINES BETWEEN "NORMAL" LEVELS'
      DO 60 I=1, ILINE
        IF (ATERM(LINEIND(I,1)) .EQV. .FALSE. .AND.
     >      ATERM(LINEIND(I,2)) .EQV. .FALSE.) THEN
          WRITE(2,61) LINEIND(I,2), STERM(LINEIND(I,2)), 
     >                LINEIND(I,1), STERM(LINEIND(I,1)),
     >                XLINE(I)
61        FORMAT (10X, I3, 2X, A10, 5X, I3, 2X, A10, 10X, F15.3)
        ENDIF
60    CONTINUE
      WRITE(2,*)
      WRITE(2,*)
C***  PRINTOUT THE LINES WITH ONE OR MORE AUTOIONISATION LEVEL INCORPORATED
      WRITE(2,*) 'LINES WITH ONE ORE MORE AUTOIONISATION LEVEL ',
     >           'INCORPORATED'
      DO 65 I=1, ILINE
        IF (ATERM(LINEIND(I,1)) .EQV. .TRUE. .OR.
     >      ATERM(LINEIND(I,2)) .EQV. .TRUE.) THEN
          IF (ATERM(LINEIND(I,1))) THEN
            STERM(LINEIND(I,1)) = '#' // STERM(LINEIND(I,1))
          ELSE
            STERM(LINEIND(I,1)) = ' ' // STERM(LINEIND(I,1))
          ENDIF
          IF (ATERM(LINEIND(I,2))) THEN
            STERM(LINEIND(I,2)) = '#' // STERM(LINEIND(I,2))
          ELSE
            STERM(LINEIND(I,2)) = ' ' // STERM(LINEIND(I,2))
          ENDIF
          WRITE(2,66) LINEIND(I,2), STERM(LINEIND(I,2)), 
     >                LINEIND(I,1), STERM(LINEIND(I,1)),
     >                XLINE(I)
66        FORMAT (10X, I3, 1X, A11, 5X, I3, 1X, A11, 10X, F15.3)
          STERM(LINEIND(I,1)) = STERM(LINEIND(I,1))(2:11)
          STERM(LINEIND(I,2)) = STERM(LINEIND(I,2))(2:11)
        ENDIF
65    CONTINUE
      CLOSE (2)

      GOTO 100

98    WRITE(*,*) 'ERROR OPENING blendout.dat'
      STOP

99    WRITE(*,*) 'ERROR OPENING blendin.dat'
      STOP

100   CONTINUE

      END

buoy.f/         1553528659  5006  320   100644  519       `
      SUBROUTINE BUOY (X, Y, SSIZE)
C**********************************************************************
C***  PLOT OF BUOY (CLIPPED) -- diamond made of two triangles
C**********************************************************************

      S = SSIZE / 1.2

      CALL GCPLOT (X-0.3333*S, Y         , 3)
      CALL GCPLOT (X         , Y+0.5833*S, 2)
      CALL GCPLOT (X+0.3333*S, Y         , 2)
      CALL GCPLOT (X         , Y-0.5833*S, 2)
      CALL GCPLOT (X-0.3333*S, Y         , 2)
      RETURN
      END

buoy_h.f/       1553528659  5006  320   100644  521       `
      SUBROUTINE BUOY_H (X, Y, SSIZE)
C**********************************************************************
C***  PLOT OF BUOY (CLIPPED) -- diamond made of two triangles
C**********************************************************************

      S = SSIZE / 1.2

      CALL GCPLOT (X         , Y-0.3333*S, 3)
      CALL GCPLOT (X+0.5833*S, Y         , 2)
      CALL GCPLOT (X         , Y+0.3333*S, 2)
      CALL GCPLOT (X-0.5833*S, Y         , 2)
      CALL GCPLOT (X         , Y-0.3333*S, 2)
      RETURN
      END

censymo.f/      1553528659  5006  320   100644  11381     `
      SUBROUTINE CENSYMO (XCM, YCM, ISYMBOL, SSIZE, N, DATASETLINE)

      DIMENSION XCM(N), YCM(N)
      COMMON /COMIDEV / IDEV

C***  Active driver
      COMMON / COMACT / ACTDRIV 
      CHARACTER*7 ACTDRIV 
      CHARACTER*(*) DATASETLINE
      CHARACTER*80 ACTPAR
      LOGICAL BHATCH

!***  CHECK DATASETLINE FOR HATCHED OPTIONS:
      BHATCH=.FALSE.
      CALL SARGC (DATASETLINE, NARG)
      DO I=1, NARG
         CALL SARGV (DATASETLINE, I, ACTPAR) 
         IF (ACTPAR .EQ. 'HATCHED' .OR. ACTPAR .EQ. 'HTYPE') THEN
            BHATCH=.TRUE.
         ENDIF
      ENDDO
      
C***  DOTS *************************************************************
      IF (ISYMBOL .EQ. 0) THEN
   77    DO 10 I=1,N
         CALL GCPLOT (XCM(I)-0.005, YCM(I), 3)
   10    CALL GCPLOT (XCM(I)+0.005, YCM(I), 2)

C***  CROSSES (+)  *****************************************************
      ELSE IF (ISYMBOL .EQ. 1) THEN
         DO 1 I=1, N
         CALL GCPLOT (XCM(I)-0.3333*SSIZE, YCM(I)    , 3)
         CALL GCPLOT (XCM(I)+0.3333*SSIZE, YCM(I)    , 2)
         CALL GCPLOT (XCM(I)    , YCM(I)-0.3333*SSIZE, 3)
         CALL GCPLOT (XCM(I)    , YCM(I)+0.3333*SSIZE, 2)
    1    CONTINUE

C*** ASTERISKS (*) *****************************************************
      ELSE IF (ISYMBOL .EQ. 2) THEN
         DO 2 I=1,N
         CALL GCPLOT (XCM(I)-0.3333*SSIZE,  YCM(I)            , 3)
         CALL GCPLOT (XCM(I)+0.3333*SSIZE,  YCM(I)            , 2)
         CALL GCPLOT (XCM(I)+0.1666*SSIZE,  YCM(I)+0.290*SSIZE, 3)
         CALL GCPLOT (XCM(I)-0.1666*SSIZE,  YCM(I)-0.290*SSIZE, 2)
         CALL GCPLOT (XCM(I)+0.1666*SSIZE,  YCM(I)-0.290*SSIZE, 3)
         CALL GCPLOT (XCM(I)-0.1666*SSIZE,  YCM(I)+0.290*SSIZE, 2)
    2    CONTINUE

C***  TRIANGLES  (UPRIGHT OR DOWNWARD) ***************************************
      ELSE IF (ISYMBOL .EQ.  3 .OR. ISYMBOL .EQ. 11) THEN
         DOWN = 1.
         IF (ISYMBOL .EQ. 11) DOWN= -1.
         IF (SSIZE .GT. .0 .OR. IDEV .EQ. 3 
     >       .OR. ACTDRIV .EQ. 'X11OWN') THEN
C***        OPEN SYMBOL:
            DO 3 I=1,N
            CALL TRIANGLE (XCM(I), YCM(I), DOWN*ABS(SSIZE))
C***        Filling Command for Postscript
            IF (SSIZE .LT. .0) THEN
                CALL GFILL
            ELSEIF (BHATCH) THEN
                CALL HFILL(DATASETLINE)
            ENDIF 
    3       CONTINUE
         ELSE
C***        FILLED SYMBOL (not Postscript):
            DO 13 I=1, N
            R = DOWN*ABS(SSIZE) 
   14       CALL TRIANGLE (XCM(I), YCM(I), R)
            R = R - 0.01
            IF (R .GT. .0) GOTO 14
   13       CONTINUE
         ENDIF


C***  SQUARES  ********************************************************
      ELSE IF (ISYMBOL .EQ. 4) THEN
         IF (SSIZE .GT. .0 .OR. IDEV .EQ. 3 
     >       .OR. ACTDRIV .EQ. 'X11OWN') THEN
C***        OPEN SYMBOL:
            DO 4 I=1,N
            CALL SQUARE (XCM(I), YCM(I), ABS(SSIZE))
C***        Filling Command for Postscript
            IF (SSIZE .LT. .0) THEN
                CALL GFILL
            ELSEIF (BHATCH) THEN
                CALL HFILL(DATASETLINE)
            ENDIF 
    4       CONTINUE
         ELSE
C***        FILLED SYMBOL (not Postscript):
            DO 15 I=1, N
            R = ABS(SSIZE) 
   16       CALL SQUARE (XCM(I), YCM(I), R)
            R = R - 0.01
            IF (R .GT. .0) GOTO 16
   15       CONTINUE
         ENDIF

C***  DIAMONDS  ********************************************************
      ELSE IF (ISYMBOL .EQ. 12) THEN
         IF (SSIZE .GT. .0 .OR. IDEV .EQ. 3 
     >       .OR. ACTDRIV .EQ. 'X11OWN') THEN
C***        OPEN SYMBOL:
            DO 47 I=1,N
            CALL DIAMOND (XCM(I), YCM(I), ABS(SSIZE))
C***        Filling Command for Postscript
            IF (SSIZE .LT. .0) THEN
                CALL GFILL
            ELSEIF (BHATCH) THEN
                CALL HFILL(DATASETLINE)
            ENDIF             
   47       CONTINUE
         ELSE
C***        FILLED SYMBOL (not Postscript):
            DO 46 I=1, N
            R = ABS(SSIZE) 
   45       CALL DIAMOND (XCM(I), YCM(I), R)
            R = R - 0.01
            IF (R .GT. .0) GOTO 45
   46       CONTINUE
         ENDIF

C***  CIRCLES  *********************************************************
      ELSE IF (ISYMBOL .EQ. 8) THEN
         DO 44 I=1,N
            IF (SSIZE .GT. .0 .OR. IDEV .EQ. 3 
     >       .OR. ACTDRIV .EQ. 'X11OWN') THEN
            CALL CIRCLE(XCM(I),YCM(I),0.0,360.0, ABS(SSIZE)*.3333)
C***        Filling Command for Postscript
            IF (SSIZE .LT. .0) THEN
                CALL GFILL
            ELSEIF (BHATCH) THEN
                CALL HFILL(DATASETLINE)
            ENDIF 
         ELSE
C***        FILLED SYMBOL (not Postscript):
               R = ABS(SSIZE) * 0.3333
   43          CALL CIRCLE(XCM(I), YCM(I), 0.0, 360.0, R)
               R = R - 0.01
               IF (R .GT. .0) GOTO 43
            ENDIF
   44    CONTINUE

C***  BOMBS  *********************************************************
      ELSE IF (ISYMBOL .EQ. 13) THEN
         DO 54 I=1,N
!            IF (SSIZE .GT. .0 
!     >       .OR. ACTDRIV .EQ. 'X11OWN') THEN
C***           OPEN SYMBOL:
!               SSIZE2 = SSIZE * 0.3333
!               CALL CIRCLE(XCM(I),YCM(I),0.0,360.0,SSIZE2)
C***  HEAD
!               OFFY = SSIZE2 * COS(ASIN(0.5))
!               SSIZE3 = SSIZE2 / 2.
!               TXCM = XCM(I)
!               TYCM = YCM(I) + OFFY + SSIZE3
!               CALL GCPLOT (TXCM+SSIZE3, TYCM-SSIZE3, 3)
!               CALL GCPLOT (TXCM+SSIZE3, TYCM+SSIZE3, 2)
!               CALL GCPLOT (TXCM-SSIZE3, TYCM+SSIZE3, 2)
!               CALL GCPLOT (TXCM-SSIZE3, TYCM-SSIZE3, 2)
!            ELSE
C***           FILLED SYMBOL:
               SSIZE2 = ABS(SSIZE) * 0.3333
               R = SSIZE2
!   53          CALL CIRCLE(XCM(I), YCM(I), 0.0, 360.0, R)       
!               R = R - 0.01
!               IF (R .GT. .0) GOTO 53
               CALL CIRCLE(XCM(I), YCM(I), 0.0, 360.0, R)       
               IF (SSIZE .LT. .0) THEN
                   CALL GFILL
               ELSEIF (BHATCH) THEN
                   CALL HFILL(DATASETLINE)
               ENDIF                
C***  HEAD
               OFFY = SSIZE2 * COS(ASIN(0.5))
               SSIZE3 = SSIZE2 / 2.
               R = ABS(SSIZE3)
               TXCM = XCM(I)
               TYCM = YCM(I) + OFFY + SSIZE3
!   55          CONTINUE
                 CALL GCPLOT (TXCM+R, TYCM-SSIZE3, 3)
                 CALL GCPLOT (TXCM+R, TYCM+R     , 2)
                 CALL GCPLOT (TXCM-R, TYCM+R     , 2)
                 CALL GCPLOT (TXCM-R, TYCM-SSIZE3, 2)
!                 R = R - 0.01
!               IF (R .GT. .0) GOTO 55
               IF (SSIZE .LT. .0) THEN
                   CALL GFILL
               ELSEIF (BHATCH) THEN
                   CALL HFILL(DATASETLINE)
               ENDIF                                
!            ENDIF
C***  SLOW MATCH
            TXCM = TXCM + SSIZE2
            TYCM = TYCM + SSIZE3
            CALL CIRCLE(TXCM, TYCM, 
     >                  180., -90., SSIZE2)
   54    CONTINUE

C***  STARS  ********************************************************
      ELSE IF (ISYMBOL .EQ. 14) THEN
        DO I=1, N
            CALL STAR(XCM(I), YCM(I), SSIZE, DATASETLINE)
C           Note: filling is done in subr. STAR
        END DO

C***  BUOY  ********************************************************
      ELSE IF (ISYMBOL .EQ. 15) THEN
         IF (SSIZE .GT. .0 .OR. IDEV .EQ. 3 
     >       .OR. ACTDRIV .EQ. 'X11OWN') THEN
C***        OPEN SYMBOL:
            DO 56 I=1,N
            CALL BUOY (XCM(I), YCM(I), ABS(SSIZE))
C***        Filling Command for Postscript
            IF (SSIZE .LT. .0) THEN
                CALL GFILL
            ELSEIF (BHATCH) THEN
                CALL HFILL(DATASETLINE)
            ENDIF 
   56       CONTINUE
         ELSE
C***        FILLED SYMBOL (not Postscript):
            DO 150 I=1, N
            R = ABS(SSIZE) 
  160       CALL BUOY (XCM(I), YCM(I), R)
            R = R - 0.01
            IF (R .GT. .0) GOTO 160
  150       CONTINUE
         ENDIF

C***  BUOY_H (horizontal) ************************************************
      ELSE IF (ISYMBOL .EQ. 17) THEN
         IF (SSIZE .GT. .0 .OR. IDEV .EQ. 3 
     >       .OR. ACTDRIV .EQ. 'X11OWN') THEN
C***        OPEN SYMBOL:
            DO 66 I=1,N
            CALL BUOY_H (XCM(I), YCM(I), ABS(SSIZE))
C***        Filling Command for Postscript
            IF (SSIZE .LT. .0) THEN
                CALL GFILL
            ELSEIF (BHATCH) THEN
                CALL HFILL(DATASETLINE)
            ENDIF 
   66       CONTINUE
         ELSE
C***        FILLED SYMBOL (not Postscript):
            DO 152 I=1, N
            R = ABS(SSIZE) 
  162       CALL BUOY_H (XCM(I), YCM(I), R)
            R = R - 0.01
            IF (R .GT. .0) GOTO 162
  152       CONTINUE
         ENDIF
C***  PENTAGRAM STAR ************************************************
      ELSE IF (ISYMBOL .EQ. 18) THEN
        DO I=1,N
          IF (SSIZE .GT. .0 .OR. IDEV .EQ. 3 
     >       .OR. ACTDRIV .EQ. 'X11OWN') THEN
            CALL PENTASTAR (XCM(I), YCM(I), ABS(SSIZE)*1.2)
C***        Filling Command for Postscript
            IF (SSIZE .LT. .0) THEN
                CALL GFILL
            ELSEIF (BHATCH) THEN
                CALL HFILL(DATASETLINE)
            ENDIF 
          ELSE
            STOP '*** OBSOLETE BRANCH'
          ENDIF
        ENDDO

C***  Vertical Line ********************************************
      ELSE IF (ISYMBOL .EQ. 16) THEN
         DO I=1, N
         CALL GCPLOT (XCM(I), YCM(I)+0.5*SSIZE, 3)
         CALL GCPLOT (XCM(I), YCM(I)-0.5*SSIZE, 2)
         ENDDO

C***  More fillable symbols ********************************************
      ELSE IF (ISYMBOL .EQ. 26 
     >    .OR. ISYMBOL .EQ. 27
     >    .OR. ISYMBOL .EQ. 29
     >    .OR. ISYMBOL .EQ. 30
     >    .OR. ISYMBOL .EQ. 33
     >    ) THEN
         IF (SSIZE .GT. .0 .OR. IDEV .EQ. 3 
     >       .OR. ACTDRIV .EQ. 'X11OWN') THEN
C***        OPEN SYMBOL:
            DO I=1,N
C***          Fillable cross
              IF (ISYMBOL == 26) THEN
                CALL BIGCROSS (XCM(I), YCM(I), ABS(SSIZE)*1.0)
C***          Andreas cross (fillable) 
              ELSE IF (ISYMBOL == 27) THEN
                CALL BIGCROSSROT (XCM(I), YCM(I), ABS(SSIZE)*1.0)
C***          Pentagon (fillable) 
              ELSE IF (ISYMBOL == 29) THEN
                CALL PENTAGON (XCM(I), YCM(I), ABS(SSIZE)*0.85)
C***          Star with seven spikes (fillable) 
              ELSE IF (ISYMBOL == 30) THEN
                CALL HEPTASTAR (XCM(I), YCM(I), ABS(SSIZE)*0.7)
C***          Star with fourteen spikes (fillable) 
              ELSE IF (ISYMBOL == 33) THEN
                CALL TETRADECASTAR (XCM(I), YCM(I), ABS(SSIZE)*0.7)
              ELSE
                STOP 'internal error in subr. censymo'
              ENDIF
C***          Filling Command 
              IF (SSIZE .LT. .0) THEN
                CALL GFILL
              ELSEIF (BHATCH) THEN
                CALL HFILL(DATASETLINE)
              ENDIF 
            ENDDO
         ELSE
            STOP '*** OBSOLETE BRANCH'
         ENDIF


C***  ILLEGAL SYMBOL CALLED *****************************************
      ELSE 
        WRITE(6,*) '>>>> ILLEGAL SYMBOL=',ISYMBOL,' CALLED <<<<'
        STOP 'ERROR IN SUBROUTINE CENSYMO'
      ENDIF

      RETURN
      END

chrinstr.f/     1553528659  5006  320   100644  458       `
      LOGICAL FUNCTION CHRINSTR (TESTCHAR, STRING)
C********************************************************************
C***  Returns .TRUE. if the character TESTCHAR is member of STRING 
C********************************************************************
      CHARACTER TESTCHAR*1, STRING*(*)

      CHRINSTR = .FALSE.
      L = IDX(STRING)

      DO I=1, L
      CHRINSTR = CHRINSTR .OR. (TESTCHAR .EQ. STRING(I:I))
      ENDDO

      RETURN
      END
circle.f/       1553528659  5006  320   100644  1378      `
      SUBROUTINE CIRCLE (X, Y, PHISTART, PHILENG, RADIUS)
C*************************************************************
C     ... PLOTTET EINEN KREIS ODER KREISBOGEN; 
C     ... ENTSPRICHT DER GLEICHNAMIGEN KALHOFF-ROUTINE, DIE JEDOCH
C         ANSCHEINEND SCHWUND VERURSACHT UND AUSSERDEM ZU GROBE 
C         WINKELABSTAENDE WAEHLT
C     X, Y : KOORDINATEN DES KREISMITTELPUNKTS IN CM
C     PHISTART: ANFANGSWINKEL UND WINKELLAENGE DES BOGENS 
C     RADIUS : IN CM
C*****************************************************************

      DATA PI / 3.14159 /

C***  SPACING DER PUNKTE IN CM:
      DATA SPACING  / 0.1 /

C***  ... JEDOCH MAXIMALER WINKELABSTAND (IN GRAD)
       DATA DPMAX / 10. /

      DELPHI = SPACING * 180. / (PI * RADIUS)
      IF (DELPHI .GT. DPMAX) DELPHI = DPMAX
      IF (PHILENG .LT. 0) DELPHI = -DELPHI

      PHI = PHISTART
      PHIEND = PHISTART + PHILENG

      PHIRAD = PHI * PI / 180. 
      CALL GCPLOT (X+RADIUS*COS(PHIRAD), Y+RADIUS*SIN(PHIRAD), 3)

    1 CONTINUE
      PHI = PHI + DELPHI
      IF ( (PHI-PHISTART)*(PHI-PHIEND) .LT. .0) THEN
         PHIRAD = PHI * PI / 180. 
         CALL GCPLOT (X+RADIUS*COS(PHIRAD), Y+RADIUS*SIN(PHIRAD), 2)
         GOTO 1
       ELSE
         PHI = PHIEND
         PHIRAD = PHI * PI / 180. 
         CALL GCPLOT (X+RADIUS*COS(PHIRAD), Y+RADIUS*SIN(PHIRAD), 2)
       ENDIF

      RETURN
      END
color.f/        1553528659  5006  320   100640  4631      `
      SUBROUTINE COLOR (SWITCH, LINE, ICOLOR, IDEV)
C************************************************************************
C***  PART OF WRPLOT SYSTEM
C***  - ALLOWS TO WRITE COLOR COMMANDS INTO POSTCRIPT FILES
C***  - THIS ROUTINE DEFINES A NUMBER OF RGB COLORS (DEFAULTS).
C***    DEPENDING ON THE SWITCH, IT CAN BE USED FOR
C***    - RESTORING THE INITIAL COLOR DEFINITIONS
C***    - CHANGING THE COLOR DEFINITIONS
C***    - WRITING A POSTSCRIPT COLOR COMMAND
C***    - WRITING COLOR DEFINITIONS INTO LATEX FILE (for INLATEX)
C************************************************************************

C***  ACTIVE GRAPHIC DRIVER
      COMMON / COMACT / ACTDRIV
      CHARACTER ACTDRIV*7
      LOGICAL CHRINSTR
C***  Current color index
      COMMON / COMCOLOR / LASTCOLOR
C***  Last text attribute status (for special use by WRPLOT)
      COMMON / COMATT / ATTCOLOR, ATTINCL, ATTWIDTH, ATTSUB, ATTBOLD, 
     >                  ALLATT
      CHARACTER*2 ATTCOLOR, ATTINCL, ATTWIDTH, ATTSUB, ATTBOLD
      CHARACTER   ALLATT*8

      CHARACTER SWITCH*(*), LINE*(*), ACTPAR*20
      PARAMETER (NCOLOR=9)
      DIMENSION RCOLOR(0:NCOLOR), GCOLOR(0:NCOLOR), BCOLOR(0:NCOLOR)
      DIMENSION RINI  (0:NCOLOR), GINI  (0:NCOLOR), BINI  (0:NCOLOR)
      SAVE RCOLOR, GCOLOR, BCOLOR, RINI, GINI, BINI, RLAST, GLAST, BLAST

C***  PRE-DEFINED COLORS
      DATA RINI / 1., 0., 1., 0., 0., 1., 1., 0., .5, 0. /
      DATA GINI / 1., 0., 0., 1., 0., 1., 0., 1., 1., .5 /
      DATA BINI / 1., 0., 0., 0., 1., 0., 1., 1., 0., 1. /

      DATA RLAST /-1./ GLAST /-1./ BLAST /-1./

C***  INITIALIZE PRE-DEFINED COLORS
      IF (SWITCH(:4) .EQ. 'INIT') THEN
         DO 1 I=0,NCOLOR
         RCOLOR(I) = RINI(I)
         GCOLOR(I) = GINI(I)
    1    BCOLOR(I) = BINI(I)

C***  MODIFY THE DEFINITION OF COLORS
      ELSE IF (SWITCH(:6) .EQ. 'DEFINE') THEN
         CALL SARGVR (LINE, 3, ACTPAR)
         READ (ACTPAR, '(18X, I2)', ERR=99) ICOLOR
         IF (ICOLOR .LT. 0 .OR. ICOLOR .GT. NCOLOR) THEN
            PRINT *, 'DEFINITION OF INVALID COLOR NUMBER IGNORED'
            RETURN
            ENDIF
         CALL SARGVR (LINE, 4, ACTPAR)
         READ (ACTPAR, '(F20.0)', ERR=99) RCOLOR(ICOLOR)
         CALL SARGVR (LINE, 5, ACTPAR)
         READ (ACTPAR, '(F20.0)', ERR=99) GCOLOR(ICOLOR)
         CALL SARGVR (LINE, 6, ACTPAR)
         READ (ACTPAR, '(F20.0)', ERR=99) BCOLOR(ICOLOR)

C***  WRITE COLOR COMMAND INTO POSTSCRIPT FILE
      ELSE IF (SWITCH(:6) .EQ. 'KASDEF' 
     >         .OR. SWITCH(:4) .EQ. 'DATA') THEN
         IF (SWITCH(:6) .EQ. 'KASDEF') THEN
            CALL SARGVR (LINE, 3, ACTPAR)
            READ (ACTPAR, '(18X,I2)', ERR=99) ICOLOR
            IF (ICOLOR .LT. 0 .OR. ICOLOR .GT. NCOLOR) THEN
               PRINT *, 'INVALID COLOR NUMBER REPLACED BY 1:', ICOLOR
               ICOLOR = 1
               ENDIF
            ENDIF
         IF (RCOLOR(ICOLOR) .NE. RLAST .OR. 
     >       GCOLOR(ICOLOR) .NE. GLAST .OR.
     >       BCOLOR(ICOLOR) .NE. BLAST) THEN
             RLAST = RCOLOR(ICOLOR)
             GLAST = GCOLOR(ICOLOR)
             BLAST = BCOLOR(ICOLOR)
C***   Store current color index
             LASTCOLOR = ICOLOR

            IF (ACTDRIV .EQ. 'PSOWN') THEN
               CALL PS_NEWCOLOR
     >           (RCOLOR(ICOLOR), GCOLOR(ICOLOR), BCOLOR(ICOLOR))

            ELSE IF (ACTDRIV .EQ. 'X11OWN') THEN
               CALL X_NEWCOLOR 
     >           (RCOLOR(ICOLOR), GCOLOR(ICOLOR), BCOLOR(ICOLOR))
            ELSE
               STOP 'ERROR: UNKNOWN DRIVER IN COLOR'
            ENDIF

         ENDIF

      ELSE IF (SWITCH .EQ. 'INLATEX') THEN

         IF (CHRINSTR(ATTCOLOR(2:2), '0123456789')) THEN
            READ (ATTCOLOR(2:2), '(I1)') ICOLOR
         ELSE
            ICOLOR = LASTCOLOR
         ENDIF
	 WRITE (14,'(A,3(F4.2,A))') 
     >        CHAR(92) // 'definecolor{fgcolor}{rgb}{',
     >        RCOLOR(ICOLOR), ',',
     >        GCOLOR(ICOLOR), ',',
     >        BCOLOR(ICOLOR), '}'
	 WRITE (14,'(A,3(F4.2,A))') 
     >        CHAR(92) // 'definecolor{bgcolor}{rgb}{',
     >        1.-RCOLOR(ICOLOR), ',',
     >        1.-GCOLOR(ICOLOR), ',',
     >        1.-BCOLOR(ICOLOR), '}'
      
      ELSE IF (SWITCH .EQ. 'KD_LATEX') THEN
	 WRITE (14,'(A,3(F4.2,A))') 
     >        CHAR(92) // 'definecolor{fgcolor}{rgb}{',
     >        RCOLOR(LASTCOLOR), ',',
     >        GCOLOR(LASTCOLOR), ',',
     >        BCOLOR(LASTCOLOR), '}'

      ELSE
      
        STOP 'ERROR: INVALID SWITCH IN COLOR'
      ENDIF

      RETURN

C***  ERROR BRANCHES
   99 PRINT *, '***** ERROR IN COLOR OPTION -- OPTION IGNORED! *******'
      PRINT *, LINE
      RETURN

      END

convadd.f/      1553528659  5006  320   100644  1857      `
      SUBROUTINE CONVADD (XA, X, Y, CHAR, K, L, IDAT, 
     >                    YCONV, S, NDATMAX, BETA)
C**********************************************************************
C*** AUXILIARY SUBROUTINE OF WRPLOT, CALLED FROM CONVOL
C*** ADDING ONE SUMMATION TERM TO THE CONVOLUTION INTEGRAL
C**********************************************************************

      DIMENSION X(NDATMAX), Y(NDATMAX), YCONV(NDATMAX)
      CHARACTER CHAR*1
      
      DATA SQRTPI / 1.7724538509055159 / ! sqrt(pi)
      DATA TWOBYPI / 0.6366197723675814 / ! 2/pi
      
C***  define weights
      IF (CHAR .EQ. 'M') THEN
C***  Radial-Tangential profile is given by Gray 1975, ApJ 202, 148, Eq. 4.
C***  The integral in this equation, with x = W/lambda, is identical to: xe^(-1/x^2) + sqrt(pi) (erf(1/x) - 1)
C***  Here: XA = 1/x. Replacing this and the latter identity in Eq. 4 in Gray results in 
C***  the following weight (up to normalization): (~Tomer, 2.12.2014)
         G=EXP(-XA*XA) + SQRTPI * ABS(XA) * (ERF(ABS(XA)) - 1.)
      ELSEIF (CHAR .EQ. 'G') THEN
         G = EXP(-XA*XA)
      ELSE IF (CHAR .EQ. 'R') THEN 
C***  Rotation profile with limb darkening parameter beta acc. to Eq. (123,11)
C***  in Unsoeld (1968) "Physik der Sternatmosphaeren", by Helge 8.6.2015
         G = TWOBYPI * SQRT(1.-XA*XA) + BETA*0.5*(1.-XA*XA) 
      ELSE IF (CHAR .EQ. 'K') THEN
         G=1.
      ELSE
         STOP 'ERROR1'
      ENDIF

      IF (K .GT. 1 .AND. K .LT. IDAT) THEN 
         Z = (X(K+1) - X(K-1)) / 2.
      ELSE IF (K .EQ. 1) THEN 
         Z = X(1) - X(2)
      ELSE IF (K .EQ. IDAT) THEN 
         Z = X(IDAT-1) - X(IDAT)
      ELSE
         STOP 'ERROR2' 
      ENDIF

      G = G * ABS(Z)

C***  ADD SUMMATION TERM
      YCONV(L) = YCONV(L) + G * Y(K)

C***  ADD SUMMATION WEIGHTS FOR LATER RE-NORMALIZATION
      S = S + G

      RETURN
      END

convert.f/      1553528659  5006  320   100644  1227      `
      SUBROUTINE CONVERT

C***  LIEST ALLE ZEILEN EINES FILES UND VERSIEHT SIE MIT EINEM 
C***  FUEHRENDEN STERNCHEN FALLS SIE NICHT MIT EINEM BLANK, 
C***  "FINISH", "END" ODER MIT DEM WORT "MASSTAB" BEGINNEN

      CHARACTER*60 ACTPAR
      CHARACTER*132 LINE
      CHARACTER*255 FNAME

      CALL GETNAM (FNAME, '[]')
      I = IDX(FNAME) + 1
5     CONTINUE
        I = I - 1
      IF (FNAME(I:I) .NE. ';') GOTO 5
      FNAME = FNAME(:I)
      WRITE(*,*) FNAME
      OPEN (UNIT=1, FILE=FNAME, STATUS='OLD', ERR=99, RECL=132)
      OPEN (UNIT=2, FILE=FNAME, STATUS='NEW', ERR=100, RECL=132)

10    CONTINUE
        READ (1,'(A)', END=98) LINE
        CALL SARGV (LINE, 1, ACTPAR)
        IF (LINE(1:1) .EQ. ' ' .AND. ACTPAR .NE. 'MASSTAB' .OR. 
     >      ACTPAR .EQ. 'FINISH' .OR. ACTPAR(1:1) .EQ. 'N' .OR.
     >      ACTPAR (1:1) .EQ. '*') THEN 
          WRITE (2,'(A)') LINE(1:IDX(LINE))
        ELSE
          LINE = '*' // LINE(1:131)
          WRITE (2,'(A)') LINE(1:IDX(LINE))
          WRITE (*,'(A)') ' ' // LINE(1:79)
        ENDIF
      GOTO 10

98    CLOSE(1)
      CLOSE(2)

      STOP

99    WRITE(*,*) ' ERROR IN OPENING FILE 1'
      STOP

100   WRITE(*,*) ' ERROR IN OPENING FILE 2'
      STOP

      END

convex.f/       1553528659  5006  320   100644  3508      `
      SUBROUTINE CONVEX (YCONV, X, Y, NDATMAX, IDAT, BCONV, LINE)
C**********************************************************************
C***  CONVOLUTION OF DATASET WITH:
C***  (G) GAUSS-PROFILE
C***  (K) KASTEN
C***  (R) ROTATATIONS-ELLIPSE WITH LIMB DARKENING PARAMETER BETA
C***  (M) MACROTURBULENZ (RADIAL-TANGENTIAL,Gray 1975, 202, 148-164, Eq. 4.)
C***  CALLED FROM: SUBR. CONVOL (INTERACTIVE) 
C***           OR: SUBR. EXCMD  (WRPLOT-COMMAND)
C**********************************************************************
      DIMENSION X(NDATMAX), Y(NDATMAX), YCONV(NDATMAX)
      CHARACTER LINE*(*), ACTPAR*20, ACTPAR2*20, CHAR*1
      CHARACTER ACTPAR3*20, ACTPAR4*20
      LOGICAL BCONV

      BETA = 0.0

      CALL SARGV (LINE, 3, ACTPAR)
      CALL SARGV (LINE, 4, ACTPAR2)
      READ (ACTPAR2, '(BN,F20.0)', ERR=99) D
      IF (D .EQ. 0.) RETURN 

      IF (ACTPAR(1:8) .EQ. 'MACRO-RT') THEN        
        P=3
        CHAR='M'
      ELSE IF (ACTPAR(1:3) .EQ. 'ROT') THEN
        P=1
        CHAR='R' 
        CALL SARGC(LINE, NARG)
        IF (NARG .GE. 6) THEN
           CALL SARGV (LINE, 5, ACTPAR3)
           IF (ACTPAR3(1:4) .EQ. 'BETA') THEN
              CALL SARGV (LINE, 6, ACTPAR4)
              READ (ACTPAR4, '(F20.0)', ERR=97) BETA
           ENDIF
        ENDIF
      ELSE IF (ACTPAR(:4) .EQ. 'KAST' .OR. ACTPAR(:3) .EQ. 'BOX') THEN
        P=1
        CHAR='K'
      ELSE IF (ACTPAR(1:5) .EQ. 'GAUSS') THEN
         D=D*0.6006
         P=3
         CHAR='G'
      ELSE
         WRITE (6,'(/A)') 
     >         '*** FATAL ERROR - invalid function: ' // ACTPAR
         GOTO 98
      ENDIF

C**********************************************************************
C***              CHECK OF MONOTONIC SEQUENCE                       ***
C**********************************************************************

      V = X(IDAT)-X(1)
      DO 2 I=2,IDAT
        IF (V*(X(I)-X(I-1)) .LT. 0.) THEN
          WRITE(6,*) ' '
          WRITE(6,*) '*** FATAL ERROR in data convolution:'
          WRITE(6,*) '*** DATASET NOT IN MONOTONIC SEQUENCE'
          WRITE (6,*) X(I), X(I-1)
          STOP '*** ERROR detected by Subr. CONVEX' 
        ENDIF
2     CONTINUE

C*** INITIALIZE THE RESULTING VECTOR YCONV
      DO 5 L=1, IDAT
        YCONV(L) = 0.
5     CONTINUE

C**** LOOP OVER ALL DATA POINTS *******************************
      DO 4 L=1,IDAT

C***  CENTRAL POINT
      S=0.
      K=L
      XA=0.
      CALL CONVADD (XA, X, Y, CHAR, K, L, IDAT,  
     >            YCONV, S, NDATMAX, BETA)

C***  LOOP OVER STEPS TO THE LEFT
510   K=K-1
      IF (K .LT. 1) GOTO 610
      XA=(X(K) - X(L)) / D
      IF (ABS(XA) .GE. P) GOTO 610
      CALL CONVADD (XA, X, Y, CHAR, K, L, IDAT,  
     >            YCONV, S, NDATMAX, BETA)
        GOTO 510

610   K=L

C***  LOOP OVER STEPS TO THE RIGHT
620   K=K+1
      IF (K .GT. IDAT) GOTO 720
      XA=(X(K) - X(L)) / D
      IF (ABS(XA) .GE. P) GOTO 680
      CALL CONVADD (XA, X, Y, CHAR, K, L, IDAT,  
     >            YCONV, S, NDATMAX, BETA)
      GOTO 620

680   CONTINUE

C*** NACHNORMIERUNG
720     IF (S .NE. .0) YCONV(L) = YCONV(L) / S

4     CONTINUE
C*****END OF LOOP ******************************************************

      BCONV = .TRUE.
      RETURN



   99 WRITE(6,'(//,A)') 'ERROR: INVALID FORMAT OF CONVOLUTION WIDTH - '

   98 WRITE(6,*) 'The error occured in the following line: '
      WRITE(6,*) LINE

   97 WRITE(6,'(//,A)') 'ERROR: INVALID FORMAT OF BETA - '
  
      STOP '*** ERROR in Subr. CONVEX'


      END
convol.f/       1553528659  5006  320   100644  4396      `
      SUBROUTINE CONVOL (X, Y, YCONV, NDAT, NDATMAX, NSET, NSETMAX, 
     >                   ISYMBOL, NPEN, ICOLOR, FNAME)

C**********************************************************************
C***      SUBROUTINE ZUR FALTUNG VON DATEN AUF DEM PLOT-FILE        ***
C***                 MIT EINER GAUSS-FUNKTION                       ***
C***     ODER MIT EINEM ROTATIONSPROFIL (OHNE RANDVERDUNKLUNG)      ***
C***     ODER MIT EINEM KASTENPROFIL                                ***
C**********************************************************************

      DIMENSION X(NDATMAX,NSETMAX), Y(NDATMAX,NSETMAX)
      DIMENSION YCONV(NDATMAX)
      DIMENSION NDAT(NSETMAX), ISYMBOL(NSETMAX), NPEN(NSETMAX)
      DIMENSION ICOLOR(NSETMAX)
      CHARACTER ACTPAR*20, ACTPAR2*20, CHAR*1, LINE*132
      LOGICAL  BCONV

      BCONV = .FALSE.

      IF (NSET .EQ. 1) THEN
        I1=1
        ELSE
1         WRITE(6,*) 'EXISTING DATA SETS: ',NSET
          WRITE(6,'(''$'',A)') 'INPUT DATA SET NR: '
          READ(5,*) I1
          IF (I1 .LT. 1 .OR. I1 .GT. NSET) GOTO 1
      ENDIF	

      IDAT=NDAT(I1)

C**********************************************************************
C***              CHECK OF MONOTONIC SEQUENCE                       ***
C**********************************************************************

      V = X(IDAT,I1)-X(1,I1)
      DO 2 I=2,IDAT
        IF (V*(X(I,I1)-X(I-1,I1)) .LT. 0.) THEN
          WRITE(6,*) '*** DATASET NOT IN MONOTONIC SEQUENCE'
          WRITE (6,*) X(I,I1), X(I-1,I1)
          STOP '*** FATAL ERROR detected in Subr. CONVOL ***'
        ENDIF
2     CONTINUE

C**********************************************************************
C***                     MAIN MENUE                                 ***
C**********************************************************************

3     WRITE(6,*) 'RT = RADIAL-TANGENTIAL (MACROTURBULENCE)'
      WRITE(6,*) 'G  = GAUSS PROFILE'
      WRITE(6,*) 'R  = ROTATION PROFILE'
      WRITE(6,*) 'K  = KASTEN (BOX) PROFILE'
      WRITE(6,*) 'B  = BACK TO MAIN PROGRAM'
      WRITE(6,'(''$'',A)') 'INPUT: '
      READ(5,'(A)') ACTPAR
      
      IF (ACTPAR(1:1) .EQ. 'B' .OR. ACTPAR(1:1) .EQ. 'b') THEN
         RETURN

C***  RAD = RADIAL-TANGENTIAL (MACROTURBULENCE)
      ELSE IF (ACTPAR(1:3) .EQ. 'RT' .OR. ACTPAR(1:3) .EQ. 'rt') THEN
        ACTPAR = 'MACRO-RT'        
        WRITE(6,'(''$'',A)') 'MACROTURBULENCE PARAMETER: '
        READ(5,*) ACTPAR2    

C***  R = ROTATION
      ELSE IF (ACTPAR(1:1) .EQ. 'R' .OR. ACTPAR(1:1) .EQ. 'r') THEN
        ACTPAR = 'ROTATION'
        WRITE(6,'(''$'',A)') 'DELTA LAMBDA - MAX: '
        READ(5,*) ACTPAR2

C***  K = KASTEN
      ELSE IF (ACTPAR(1:1) .EQ. 'K' .OR. ACTPAR(1:1) .EQ. 'k') THEN
        ACTPAR = 'KASTEN'
        WRITE(6,'(''$'',A)') 'BOX WIDTH (KASTEN BREITE): '
        READ(5,*) ACTPAR2

C***  G = GAUSS
      ELSE IF (ACTPAR(1:1) .EQ. 'G' .OR. ACTPAR(1:1) .EQ. 'g') THEN
        ACTPAR = 'GAUSS'
        WRITE(6,'(''$'',A)') 'FWHM (HALBWERTSBREITE): '
        READ(5,*) ACTPAR2
         
      ELSE
         GOTO 3

      ENDIF

C***  CONSTRUCT COMMAND LINE FOR CALL
      LINE = 'COMMAND CONVOL ' // ACTPAR // ' '  // ACTPAR2

C***  CONVOLUTION ARITHMETIC:
      CALL CONVEX (YCONV, X(1,I1), Y(1,I1), NDATMAX, IDAT, BCONV, LINE)

C***  STORE NEW DATASET YCONV
20    WRITE(6,'(''$'',A)') 'OVERWRITE OLD DATA-SET NR. (Y/N) /N/: '
      READ(5,'(A)') CHAR
      IF (CHAR .EQ. 'Y' .OR. CHAR .EQ. 'y') THEN
        I2=I1
        GOTO 33
      ENDIF
      IF (NSET .LT. NSETMAX) THEN
        NSET=NSET+1
        I2=NSET
        GOTO 33
      ENDIF
      WRITE(6,*) 'ALL DATA SETS USED !'
      WRITE(6,'(''$'',A)') 'OVERWRITE DATA-SET NR: '
      READ(5,*) I2
      IF (I2 .LT. 1 .OR. I2 .GT. NSETMAX) THEN
        WRITE(6,*) 'THIS DATA NOT SAVED'
        GOTO 3
      ENDIF


33    WRITE(6,*) 'NEW DATA IN SET NR: ',I2
      ISYMBOL(I2)=ISYMBOL(I1)
      NPEN(I2) = NPEN(I1)
      ICOLOR(I2) = ICOLOR(I1)
      NDAT(I2)=IDAT
      IF (BCONV) THEN
        DO I=1, IDAT
           X(I,I2) = X(I,I1)
           Y(I,I2) = YCONV(I)
        ENDDO
      ELSE
        DO I=1, IDAT
           X(I,I2) = X(I,I1)
           Y(I,I2) = Y(I,I1)
        ENDDO        
      ENDIF
 
C***  OPTIONAL SAVING OF NEW DATA ON DISK FILE
      CALL SAVESET (X(1,I2), Y(1,I2), NDAT(I2), ISYMBOL(I2), NPEN(I2),
     >              FNAME, .TRUE.)
      RETURN
      END
cstown.f/       1553528659  5006  320   100644  1502      `
C**********************************************************************
C***  PROGRAMM ZUM AUSWERTEN DES CRAY-STATUS-FILES
C**********************************************************************
      SUBROUTINE CSTOWN

      CHARACTER CLASS*7,CR*1
      CHARACTER*80 B(4), LINE(100), MINLINE
      CHARACTER*330 BLOCK

    1 FORMAT (A) 
   11 FORMAT (1X,A)

      READ (5,1) CLASS
      IF (CLASS(1:1) .EQ. ' ') CLASS='smed_SH'
      IF (CLASS(1:1) .EQ. 'A') CLASS='sma_SH'
      IF (CLASS(1:1) .EQ. 'B') CLASS='smb_SH'
      IF (CLASS(1:3) .EQ. 'MED') CLASS='med_SH'
      IF (CLASS(1:3) .EQ. 'LAR') CLASS='lar_SH'
      IF (CLASS(1:2) .EQ. 'ML') CLASS='ml_SH'
      PRINT *,'class:"',class,'"<<<'

      CR=CHAR(13)

      OPEN (UNIT=1, FILE='CST.INF', STATUS='OLD')
      LTOT=0
      L=0

    2 READ (1,1,END=99) BLOCK
      LASTCR=0
      DO 10 I=1,4
      NEWCR=INDEX(BLOCK(LASTCR+1:),CR)+LASTCR
      B(I)=BLOCK(LASTCR+1:NEWCR-1)
      LASTCR=NEWCR+1
C***  HEADER LINES (2)
      LTOT=LTOT+1
      IF (LTOT .LE. 2) THEN
         PRINT 11, B(I)
      ELSE IF (CLASS .EQ. B(I)(20:27)) THEN
         L=L+1
         LINE(L)=B(I)
         ENDIF
   10 CONTINUE
      GOTO 2

   99 CONTINUE 
C***  PRINTOUT SORTED BY JSQ NUMBERS
      DO 20 I=1,L
      MINLINE='A'
C***  FIND MIN. JSQ
      DO 21 J=1,L
      IF (LINE(J) .LT. MINLINE) THEN
         MINLINE=LINE(J)
         JMIN=J
         ENDIF
   21 CONTINUE

      PRINT 11, MINLINE
      LINE(JMIN)='A'
   20 CONTINUE

      STOP 'O.K.'
      END
cubic.f/        1553528659  5006  320   100644  3234      `
C*******************************************************
C***  Subroutine cubic : spline-interpolation          *
C*******************************************************

       subroutine cubic (fx,x,fi,xi,l,n,MONO)
       
       dimension fi(n),xi(n)
       common/cubi/p1,p2,p3,p4
       LOGICAL MONO
       

       D1=1./(xi(l)-xi(l-1))
       d2=d1*d1
       d3=d1*d2
       d23=d2/3.
       h11=d3
       h12=-d3
       h13=d23
       h14=2.*d23
       h21=-d1
       h22=2.*d1
       h23=-0.3333333
       h24=-0.6666666
       h31=-d3
       h32=d3
       h33=-2.*d23
       h34=-d23
       h41=2.*d1
       h42=-d1
       h43=0.6666666
       h44=0.3333333
       
       la=max0(l-2,1)
       lb=min0(l+1,n)
       
       IF (.NOT. MONO) THEN

       f1=fi(l-1)
       f2=fi(l)
       dx1=xi(l-1)-xi(l)
       if (la .ne. l-2) goto 10
       
       f0=fi(la)
       dx0=xi(la)-xi(l-1)
       dx2=xi(l)-xi(la)
       pdx=dx0*dx1*dx2
       
       f3=((f1-f0)*dx1*dx1+(f2-f1)*dx0*dx0)/pdx
       if (lb .ne. l) goto 5
       f4=((f0-f2)*dx1*dx1+(f2-f1)*dx2*dx2)/pdx
5      continue
10     continue
       if (lb.ne.l+1) goto 20
       
       f0=fi(lb)
       dx0=xi(lb)-xi(l-1)
       dx2=xi(l)-xi(lb)
       pdx=dx0*dx1*dx2
       if (la.ne.l-1) goto 15
       
       f3=((f2-f1)*dx0*dx0+(f1-f0)*dx1*dx1)/pdx
15     continue

       f4=((f2-f1)*dx2*dx2+(f0-f2)*dx1*dx1)/pdx
20     continue
       if (lb.ne.l.or.la.ne.l-1) goto 30

       f3=(f1-f2)/dx1
       f4=f3
30     continue
       
       ELSE

C***  FUNCTION TO BE INTERPOLATED: FI
      F1 = FI(L-1)
      F2 = FI(L)
      F3 = (FI(L) - FI(LA)) / (XI(L) - XI(LA))
      F4 = (FI(LB) - FI(L-1)) / (XI(LB) - XI(L-1))

      IF (N .GT. 2) THEN
        S4 = ( FI(L) - FI(L-1) ) / ( XI(L) - XI(L-1) )

C*** LEFT BOUNDARY, EXTRAPOLATION BY PARABOLA, SECOND SUGGESTION OF STEFFEN
        IF (L .EQ. 2) THEN
          TEMP = (XI(2) - XI(1)) / (XI(3) - XI(1))
          P1 = (FI(2) - FI(1)) / (XI(2) - XI(1)) * (1 + TEMP) -
     >         (FI(3) - FI(2)) / (XI(3) - XI(2)) * TEMP
          F3 = (SIGN(0.5,P1) + SIGN(0.5,S4)) *
     >         MIN(ABS(P1), ABS(2.*S4))
        ELSE
C***  NOT LEFT BOUNDARY
          S3 = ( FI(L-1) - FI(L-2) ) / ( XI(L-1) - XI(L-2) )
          F3 = (SIGN(1.0,S3)+SIGN(1.0,S4)) *
     >         MIN(ABS(S3),ABS(S4),0.5*ABS(F3))
        ENDIF
C***  RIGHT BOUNDARY, EXTRAPOLATION BY PARABOLA, SECOND SUGGESTION OF STEFFEN
        IF (L .EQ. N) THEN
          TEMP = (XI(N) - XI(N-1)) / (XI(N) - XI(N-2))
          PN = (FI(N) - FI(N-1)) / (XI(N) - XI(N-1)) * (1. + TEMP) -
     >         (FI(N-1) - FI(N-2)) / (XI(N-1) - XI(N-2)) * TEMP
          F4 = (SIGN(0.5,PN) + SIGN(0.5,S4)) *
     >         MIN(ABS(PN), ABS(2.*S4))
        ELSE
C***  NO RIGHT BOUNDARY
          S5 = ( FI(L+1) - FI(L) ) / ( XI(L+1) - XI(L) )
          F4 = (SIGN(1.0,S4)+SIGN(1.0,S5)) *
     >         MIN(ABS(S4),ABS(S5),0.5*ABS(F4))
        ENDIF

      ENDIF

      ENDIF

       p1=h11*f1+h12*f2+h13*f3+h14*f4
       p2=h21*f1+h22*f2+h23*f3+h24*f4
       p3=h31*f1+h32*f2+h33*f3+h34*f4
       p4=h41*f1+h42*f2+h43*f3+h44*f4



       fx=p1*(x-xi(l-1))**3 + p2*(x-xi(l-1))
     +   +p3*(xi(l) - x)**3 + p4*(xi(l) - x)
      
       return
       
       end
datacat.f/      1641579051  5006  320   100644  3352      `
      SUBROUTINE DATACAT (NRUNIT, BSINGLE)
C********************************************************************
C***  GIVES A CATALOGUE OF ALL PLOT-HEADER                        ***
C********************************************************************

      LOGICAL BSINGLE
      CHARACTER*60 LINE, ACTPAR, ICHAR*1, FORMSTR*80

      BSINGLE = .TRUE.
      N = 0
      NOUT = 0
      ICHAR = ' '

      WRITE (6, *)
      WRITE (6, *) 'The file contains the following plots: '

    1 CONTINUE
      READ (NRUNIT, '(A)', END=2) LINE
      CALL SARGC (LINE,NPAR)
      IF (NPAR .EQ. 0) GOTO 1
      CALL SARGV (LINE, 1, ACTPAR)
      IF (ACTPAR .EQ. 'PLOT') THEN
        N = N + 1
        IF (N .GT. 1) BSINGLE = .FALSE.
        WRITE (6, '(X, I3, 4X, A)') N, LINE( :IDX(LINE))
        NOUT = NOUT + 1
c        IF (NOUT/12*12 .EQ. NOUT) THEN
c           FORMSTR = '(''Type <CR> to continue (i: no inquire) ...'')'
c           CALL NOLF (FORMSTR)
c           WRITE (6, FORMSTR) 
c           IF (ICHAR .NE. 'I' .AND. ICHAR .NE. 'i') THEN
c             READ  (5, '(A)' ) ICHAR
c           ENDIF
c           ENDIF
    3   READ (NRUNIT, '(A)', END=2) LINE
        CALL SARGC (LINE,NPAR)
        IF (NPAR .EQ. 0) GOTO 3
        CALL SARGV (LINE, 1, ACTPAR)
        IF (ACTPAR .EQ. 'HEADER') GOTO 1
        GOTO 3
      ENDIF
    6 IF (ACTPAR .EQ. 'MULTIPLOT') THEN
        N = N + 1
        BSINGLE = .FALSE.
        WRITE (6, '(1X, A)') LINE
        NOUT = NOUT + 1
        IF (NOUT/12*12 .EQ. NOUT) THEN
           FORMSTR = '(''Type <CR> to continue (i: no inquire) ...'')'
           CALL NOLF (FORMSTR)
           WRITE (6, FORMSTR) 
           IF (ICHAR .NE. 'I' .AND. ICHAR .NE. 'i') THEN
             READ  (5, '(A)' ) ICHAR
           ENDIF
           ENDIF
        GOTO 4
      ENDIF
      GOTO 1

    4 M = 0
    7 READ (NRUNIT, '(A)', END=2) LINE
      CALL SARGC (LINE,NPAR)
      IF (NPAR .EQ. 0) GOTO 7
      CALL SARGV (LINE, 1, ACTPAR)
      IF (ACTPAR .EQ. 'MULTIPLOT') THEN
        WRITE (6, '(1X, A)') LINE
        NOUT = NOUT + 1
        IF (NOUT/12*12 .EQ. NOUT) THEN
           FORMSTR = '(''Type <CR> to continue (i: no inquire) ...'')'
           CALL NOLF (FORMSTR)
           WRITE (6, FORMSTR) 
           IF (ICHAR .NE. 'I' .AND. ICHAR .NE. 'i') THEN
             READ  (5, '(A)' ) ICHAR
           ENDIF
           ENDIF
        GOTO 1
      ENDIF
      IF (ACTPAR .EQ. 'PLOT') THEN
        M = M + 1
        WRITE (6, '(X, I3, A1, I2, 4X, A)') N, '-', M, LINE
        NOUT = NOUT + 1
        IF (NOUT/12*12 .EQ. NOUT) THEN
           FORMSTR = '(''Type <CR> to continue (i: no inquire) ...'')'
           CALL NOLF (FORMSTR)
           WRITE (6, FORMSTR) 
           IF (ICHAR .NE. 'I' .AND. ICHAR .NE. 'i') THEN
             READ  (5, '(A)' ) ICHAR
           ENDIF
           ENDIF
    5   READ (NRUNIT, '(A)', END=2) LINE
        CALL SARGC (LINE,NPAR)
        IF (NPAR .EQ. 0) GOTO 5
        CALL SARGV (LINE, 1, ACTPAR)
        IF (ACTPAR .NE. 'HEADER') GOTO 5
      ENDIF
      GOTO 7

    2 CONTINUE
      REWIND (NRUNIT)
      FORMSTR = '(''E-O-F reached -- type <CR> to continue ...'')'
      CALL NOLF (FORMSTR)
      WRITE (6, FORMSTR)
      IF (ICHAR .NE. 'I' .AND. ICHAR .NE. 'i') THEN
        READ  (5, '(A)' ) ICHAR
      ENDIF

      WRITE (6, '(/, A)') ' Loading the first plot now ...'
      RETURN
      END
deccmd.f/       1553528659  5006  320   100644  7109      `
      SUBROUTINE DECCMD (LINE, BXRANG, XRANG1, XRANG2, BYRANG, YRANG1, 
     >                YRANG2, EXDATA, IEXDATA, IERR, K, MPACTIVE, 
     >                MPSTART, NCMD, NCMDMAX, SCMD, 
     >                X, Y, NDAT, NDATMAX, ISET, NSET, NSETMAX, I, 
     >                BFITS, FITSNAM, FITSCOM, VAR, MAXVAR, NVAR, FNAME, 
     >                BSKEY, SKEY, IDX_SKEY, SETNAME)

C*******************************************************************
C***  CALLED FROM: SUBR. READDATA (WRPLOT SYSTEM)
C***  DECODES "COMMAND" LINES IN THE WRPLOT DATASETS 
C*******************************************************************

      CHARACTER*(*) VAR(MAXVAR,2), FNAME, SKEY
      CHARACTER*132 SCMD(NCMDMAX)
      CHARACTER LINE*(*), ACTPAR*20, INCKEY*132, LINE2*132
      CHARACTER*(*) SETNAME(NSETMAX)
      CHARACTER EXNAM*255 
      CHARACTER FITSNAM*255, FITSCOM*(*)
      LOGICAL BXRANG, BYRANG, EXDATA, BFITS
      LOGICAL MPACTIVE, MPSTART, BSKEY

      DIMENSION X(NDATMAX, NSETMAX), Y(NDATMAX, NSETMAX)
      DIMENSION NDAT(NSETMAX)

      CALL SARGV (LINE, 2, ACTPAR)

C--------------------
      IF (ACTPAR .EQ. 'SETNAME') THEN
         CALL SUBVAR (LINE, VAR, MAXVAR, NVAR)
         CALL SARGV (LINE, 3, ACTPAR)
         CALL FLUSHLEFT (ACTPAR)
	 DO J=1, NSET
	    IF (SETNAME(J) .EQ. ACTPAR) THEN
	       WRITE (*,'(//,2A)') 
     >            'Double definition of dataset name: ', 
     >             ACTPAR(:IDX(ACTPAR))
	       GOTO 97
            ENDIF 
	 END DO
 	 SETNAME(ISET) = ACTPAR
 
C--------------------
      ELSE IF (ACTPAR .EQ. 'APPEND') THEN
         CALL SUBVAR (LINE, VAR, MAXVAR, NVAR)
         CALL DECSETNAME (LINE, 3, SETNAME, NSET, ISETOP)
         I = I - 1
         IF (I + NDAT(ISETOP) .GT. NDATMAX) THEN
           WRITE (6,*) 'ERROR: TOO MANY (X,Y)-VALUES - '
           STOP
         ENDIF
         DO 72 J=1, NDAT(ISETOP)
           X(I + J, ISET) = X(J, ISETOP)
           Y(I + J, ISET) = Y(J, ISETOP)
72       CONTINUE
         I = I + NDAT(ISETOP) + 1

C--------------------
      ELSE IF (ACTPAR .EQ. 'X-RANGE') THEN
         CALL SUBVAR (LINE, VAR, MAXVAR, NVAR)
         CALL SARGVR (LINE, 3, ACTPAR)
         READ (ACTPAR, '(F20.0)', ERR=96) XRANG1
         CALL SARGVR (LINE, 4, ACTPAR)
         READ (ACTPAR, '(F20.0)', ERR=96) XRANG2
         BXRANG = .TRUE.

C--------------------
      ELSE IF (ACTPAR .EQ. 'Y-RANGE') THEN
         CALL SUBVAR (LINE, VAR, MAXVAR, NVAR)
         CALL SARGVR (LINE, 3, ACTPAR)
         READ (ACTPAR, '(F20.0)', ERR=96) YRANG1
         CALL SARGVR (LINE, 4, ACTPAR)
         READ (ACTPAR, '(F20.0)', ERR=96) YRANG2
         BYRANG = .TRUE.

C--------------------
      ELSE IF (ACTPAR .EQ. 'INFITS') THEN
         CALL SUBVAR (LINE, VAR, MAXVAR, NVAR)
         BFITS = .TRUE.
         CALL SARGV (LINE, 3, FITSNAM)
ccc         CALL DECVAR (FITSNAM, VAR, MAXVAR, NVAR)     
         CALL SARGREST (LINE, N, 4, IFIRST, ILAST)
         FITSCOM = LINE(IFIRST:ILAST)

C--------------------
      ELSE IF (ACTPAR .EQ. 'INCLUDE') THEN
cccc         CALL SUBVAR (LINE, VAR, MAXVAR, NVAR)
cccc    einzeln expandieren, damit INCKEY Trennzeichen enthalten kann!
         EXDATA = .TRUE.
         IEXDATA = IEXDATA + 1
         NUMBER = 1
         INCKEY = ''
         CALL SARGV (LINE, 3, EXNAM)
         CALL DECVAR (EXNAM, VAR, MAXVAR, NVAR)     
         IF (EXNAM .EQ. 'SELF') EXNAM = FNAME
C***     If necessary, create unzipped file and modify EXNAM
         CALL MY_OPEN (9+IEXDATA, EXNAM, IERR)
	 IF (IERR .NE. 0) GOTO 93
         CALL SARGC (LINE, NPAR)

C***     LOOP over additional INCLUDE parameters
C***     Note: all existing options are KEYWORD=PARAMETER
         DO IPAR=4, NPAR, 2         
            CALL SARGV (LINE, IPAR, ACTPAR)
            IF (ACTPAR .EQ. 'INCKEY') THEN
C***                         ======
               IF (IPAR+1 .GT. NPAR) THEN
                  PRINT *, 'PARAMETER MISSING FOR INCKEY=?'
                  GOTO 97
               ENDIF
               CALL SARGV (LINE, IPAR+1, INCKEY)
               CALL DECVAR (INCKEY, VAR, MAXVAR, NVAR)     
               ID = IDX(INCKEY)
            ELSE IF (ACTPAR .EQ. 'SKEY') THEN
C***        Den Sinn dieser Option kenne ich nicht! wrh 28-Feb-2004 
               BSKEY = .TRUE.
               CALL SARGV (LINE, 5, SKEY)
               CALL DECVAR (SKEY, VAR, MAXVAR, NVAR)     
               IDX_SKEY = IDX(SKEY)

            ELSE IF (ACTPAR .EQ. 'DATASET') THEN
               IF (IPAR+1 .GT. NPAR) THEN
                  PRINT *, 'PARAMETER MISSING FOR DATASET=?'
                  GOTO 97
               ENDIF
               CALL SARGV (LINE, IPAR+1, ACTPAR)
               CALL DECVAR (ACTPAR, VAR, MAXVAR, NVAR)     
               READ (ACTPAR, '(I20)',ERR=94) NUMBER
            ENDIF
         ENDDO
   
         IF (INCKEY .NE. '') THEN
C***        READ UNTIL A LINE BEGINNING WITH STRING "INCKEY" IS FOUND
  150       READ (9 + IEXDATA, '(A)', END=91) LINE
            IF (LINE(1:ID) .NE. INCKEY(1:ID)) GOTO 150
         ENDIF

C***     SEARCH FOR NEXT 'N=' LINE (repeat this NUMBER times)
         DO II=1, NUMBER
  151      READ (9 + IEXDATA, '(A)', END=155) LINE2
           CALL SARGV (LINE2, 1, ACTPAR)
           IF (ACTPAR .NE. 'N') GOTO 151
         ENDDO

         GOTO 156

C***     NO N= CARD FOUND, INCLUDE DATA-SET IS RAW DATA-SET
  155    CONTINUE
         IF (NUMBER .GT. 1) THEN
            WRITE (6,'(//,A,I3,A)') 'DATASET=', NUMBER, 
     >           '  does not exist in INCLUDE file'
            GOTO 97
         ENDIF
         REWIND (9 + IEXDATA)
  156    CONTINUE

C--------------------
      ELSE
           NCMD = NCMD + 1
           IF (NCMD .GT. NCMDMAX) THEN
             WRITE (6,*) 'MORE COMMANDS THAN DIMENSIONED:'
             WRITE (6,*) 'NCMDMAX = ', NCMDMAX 
             STOP 'ERROR IN DECCMD'
           ENDIF
           SCMD(NCMD) = LINE
C--------------------

      ENDIF

         IERR = 0
         RETURN


C***************  ERROR BRANCHES  ****************************

91    CONTINUE
      IF (MPACTIVE .AND. .NOT. MPSTART) CALL GPLTEND
      WRITE (6,*) 'INCKEY=', INCKEY(1:IDX(INCKEY)), ' NOT FOUND'
      WRITE (6,*) 'THIS PLOT SKIPPED!'
      DO 92 I=1, IEXDATA
        CLOSE (9 + IEXDATA)
92    CONTINUE
      IEXDATA = 0
      EXDATA = .FALSE.
      K = 1
      IERR = 91
      RETURN

93    CONTINUE
      IF (MPACTIVE .AND. .NOT. MPSTART) CALL GPLTEND
      WRITE (6,*) 'ERROR WHEN OPENING EXTERNAL DATASET'
      WRITE (6,*) 'EXTERNAL NAME :',EXNAM
      WRITE (6,*) 'THIS PLOT SKIPPED!'
      K = 1
      IERR = 93
      RETURN

94    CONTINUE
      WRITE (6,'(//,A)') 'ERROR WHEN DECODING DATASET NUMBER'
      GOTO 97

96    CONTINUE
      IF (MPACTIVE .AND. .NOT. MPSTART) CALL GPLTEND
      WRITE (6,*) 'ERROR: INVALID FORMAT IN COMMAND LINE - ',
     *            'THIS PLOT SKIPPED!'
      WRITE (6,*) 'The error occured in the following line:'
      WRITE (6,*) LINE
      K = 1
      IERR = 96
      RETURN 

97    CONTINUE
      WRITE (6,*) 'The error occured in the following line:'
      WRITE (6,*) LINE(:IDX(LINE))
      STOP 'ERROR STOP IN DECCMD'



      END

decvar.f/       1553528659  5006  320   100644  971       `
      SUBROUTINE DECVAR (ACTPAR, VAR, MAXVAR, NVAR)
C***************************************************
C***  DECODING OF VARIABLES:
C***  ACTPAR IS INPUT AND OUTPUT
C***************************************************

      CHARACTER*(*) VAR(MAXVAR,2)
      CHARACTER*(*) ACTPAR
      CHARACTER*900 ACTPAR2

      IF (ACTPAR(1:1) .NE. '$') GOTO 100

C***  If no variables have been defined yet, the $ sign is a normal character
      IF (NVAR .EQ. 0) GOTO 100
      IF (NVAR .EQ. 1 .AND. VAR(1,1) .EQ. 'NEXT_YOFS') GOTO 100


      ACTPAR2 = ACTPAR(2: )
      I = 1
    5 IF (I .LE. NVAR) THEN
        IF (ACTPAR2 .EQ. VAR(I,1)) THEN
          ACTPAR = VAR(I,2)( :IDX(VAR(I,2)))
          GOTO 100
        ENDIF
        I = I + 1
      GOTO 5
      ENDIF

C***  ERROR BRANCH
      WRITE (*,'(//,A,/,3A)') '****** FATAL ERROR *******', 
     >      'Variable $',ACTPAR2( :IDX(ACTPAR2)), ' is not defined'
      STOP 'ERROR IN SUBROUTINE DECVAR'

  100 RETURN
      END

defindev.f/     1553528659  5006  320   100644  3263      `
      SUBROUTINE DEFINDEV (IDEV,IAUTO)
C***********************************************************************
C***  Called from: WRPLOT
C***  Defines Plottig Device and active driver
C***********************************************************************

C***  Installierte Plotter-Treiber 
      COMMON / COMDRIV / CALCOMP, X11OWN, PSOWN
      LOGICAL CALCOMP, X11OWN, PSOWN

C***  Aktiver Plotter-Treiber 
      COMMON / COMACT / ACTDRIV
      CHARACTER*7 ACTDRIV

C***  Operating system:
      COMMON / COMOS / OPSYS
      CHARACTER*8 OPSYS

      CHARACTER ONECHAR*1, FORMSTR*80

C***  Prepare FORMAT string for one A Format output:
      FORMSTR = '(A)'
      CALL NOLF (FORMSTR)

      IF (IAUTO .EQ. 3) THEN
        ACTDRIV = 'PSOWN'
        IDEV = 3
        GOTO 10
      ELSE IF (IAUTO .EQ. 5) THEN
        ACTDRIV = 'X11OWN'
        IDEV = 5
        GOTO 10
      ENDIF

      IF (CALCOMP) THEN 
    1    WRITE (6, *) ' SELECT GRAPHIC DEVICE:'
         WRITE (6, FORMSTR)
     >    '5 = TERMINAL, 8 = HPG, 3=POSTSCRIPT, 0 = OTHER, <0 = ABORT: '
c         READ (5,*, ERR=1) IDEV
         READ (5,*) IDEV
         IF (IDEV .EQ. 3  .AND. PSOWN) THEN
    2       WRITE (6, FORMSTR) 
     >       'Calcomp (C) or Own (O) Postscript driver? '
            READ (5, '(A)') ONECHAR
            IF (ONECHAR .EQ. 'C' .OR. ONECHAR .EQ. 'c') THEN
               ACTDRIV = 'CALCOMP'
            ELSEIF (ONECHAR .EQ. 'O' .OR. ONECHAR .EQ. 'o') THEN
               ACTDRIV = 'PSOWN'
            ELSE
               GOTO 2
            ENDIF
         ELSE IF (IDEV .EQ. 5  .AND. X11OWN) THEN
    3       WRITE (6, FORMSTR) 'Calcomp TEK (C) or Own (O) X11 driver? '
            READ (5, *) ONECHAR
            IF (ONECHAR .EQ. 'C' .OR. ONECHAR .EQ. 'c') THEN
               ACTDRIV = 'CALCOMP'
            ELSEIF (ONECHAR .EQ. 'O' .OR. ONECHAR .EQ. 'o') THEN
               ACTDRIV = 'X11OWN'
            ELSE
               GOTO 3
            ENDIF
         ELSE
            ACTDRIV = 'CALCOMP'
         ENDIF
      ELSE IF (PSOWN .AND. X11OWN) THEN
    4    WRITE (6, *) ' SELECT GRAPHIC DEVICE:' 
         WRITE (6, FORMSTR) '5 = TERMINAL, 3=POSTSCRIPT, <0 = ABORT: '
c         READ (5,*, ERR=4) IDEV
         READ (5,*) IDEV
         IF (IDEV .EQ. 5) THEN
            ACTDRIV = 'X11OWN'
         ELSE IF (IDEV .EQ. 3) THEN
            ACTDRIV = 'PSOWN'
         ELSE IF (IDEV .GT. 0) THEN
            GOTO 4 
         ENDIF

      ELSE IF (PSOWN) THEN
         WRITE (6, *) 'ONLY AVAILABLE DRIVER IS FOR POSTSCRIPT (OWN);'
         WRITE (6, FORMSTR) 'ENTER "S" IF YOU WANT TO SKIP: '
         READ (5, '(A)') ONECHAR
         IF (ONECHAR .EQ. 'S' .OR. ONECHAR .EQ. 's') THEN
            IDEV = -1
         ELSE
            ACTDRIV = 'PSOWN'
            IDEV = 3
         ENDIF

      ELSE IF (X11OWN) THEN
         WRITE (6,*) 'ONLY AVAILABLE DRIVER IS FOR X11 (OWN);'
         WRITE (6, FORMSTR) 'ENTER "S" IF YOU WANT TO SKIP: '
         READ (5,*) ONECHAR
         IF (ONECHAR .EQ. 'S' .OR. ONECHAR .EQ. 's') THEN
            IDEV = -1
         ELSE
            ACTDRIV = 'X11OWN'
            IDEV = 5
         ENDIF

      ELSE
         WRITE (6, *) 'ERROR: NO GRAPHIC DRIVER INSTALLED!'
         IDEV = -1
      ENDIF

   10 CONTINUE

      RETURN
      END

delset.f/       1553528659  5006  320   100644  1271      `
      SUBROUTINE DELSET(X,Y,NDAT,NSET,NSETMAX,ISYMBOL)

C**********************************************************************
C***        THIS SUBROUTINE DELETES DATASETS                        ***
C**********************************************************************

      DIMENSION X(5000,NSETMAX), Y(5000,NSETMAX)
      DIMENSION NDAT(NSETMAX), ISYMBOL(NSETMAX)
      CHARACTER ICHAR*1

C**********************************************************************
C***          INPUT DATA SET NR.                                    ***
C**********************************************************************

1     IF (NSET .EQ. 0) RETURN
      
      WRITE(6,'(''$'',A)') 'INPUT DATA SET NR: '
      READ(5,*) I1
      IF (I1 .GT. NSET .OR. I1 .LT. 1) GOTO 1

      IF (I1 .NE. NSET) THEN
        WRITE (6,*) ' OLD SET NR  NEW SET NR'
        DO 12 I=I1+1,NSET
          DO 10 J=1,NDAT(I)
            X(J,I-1)=X(J,I)
10          Y(J,I-1)=Y(J,I)
          ISYMBOL(I-1)=ISYMBOL(I)
          WRITE(6,*) I,I-1
12        NDAT(I-1)=NDAT(I)
      ENDIF
      NSET=NSET-1

      IF (NSET .GT. 0) THEN
        WRITE(6,'(''$'',A)') 'DELETE NEXT SET ? /N/: '
        READ(5,'(A)') ICHAR
        IF (ICHAR .EQ. 'Y' .OR. ICHAR .EQ. 'y') GOTO 1
      ENDIF

      RETURN
      END

diamond.f/      1553528659  5006  320   100644  523       `
      SUBROUTINE DIAMOND (X, Y, SSIZE)
C**********************************************************************
C***  PLOTTING OF A SQUARE (CLIPPED)
C**********************************************************************
      CALL GCPLOT (X,               Y-0.4714 *SSIZE, 3)
      CALL GCPLOT (X+0.4714 *SSIZE, Y,               2)
      CALL GCPLOT (X,               Y+0.4714 *SSIZE, 2)
      CALL GCPLOT (X-0.4714 *SSIZE, Y,               2)
      CALL GCPLOT (X,               Y-0.4714 *SSIZE, 2)
      RETURN
      END

dirform.f/      1553528659  5006  320   100644  4061      `
      SUBROUTINE DIRFORM
C********************************************************************
C***  GIBT EIN KURZES DIRECTORY ALLER SPEZIFIZIERTEN FORMAL-FILES ***
C***  IN DAS FILE DIRFORM.OUT AUS                                 ***
C********************************************************************

      CHARACTER*255 FNNAMEN, FNFORMAL, FN2FORMAL
      CHARACTER*255 FN3FORMAL, FN4FORMAL, FNANF
      CHARACTER LINE*132, OUTLINE*132, ACTPAR*60

C***  EINLESEN DES FILE-NAMENS IN DEM DIE FORMAL-NAMEN GESPEICHERT SIND
      WRITE (*,*) 'NAME DES NAMEN-FILES = '
      CALL GETNAM(FNNAMEN,'[]')
      OPEN (UNIT=1,FILE=FNNAMEN, STATUS='OLD',ERR=99)
      OPEN (UNIT=3,FILE='DIRFORM.OUT', STATUS='NEW', RECL=132)
C***  EINLESEN DER KEYWORDS
C***    SPLINE  : SPEZIFIEZIERT DIE LINIE, DIE AUSGEWERTET WERDEN SOLL
C***    REDIS   : ELECTRON REDISTRIBUTION (REDIS = (TRUE, FALSE))
C***    FNANF   : GIBT DEN ANFEANG DER FORMAL-NAMEN AN, ZB. FORMAL_C_...
C***    KEYWORD : HINTER DER POSITION DES KEYWORDS WIRD DER WERT EINGELESEN

C*** DUMMY READING KEYWORD
      READ(1, '(A)', END=2) LINE
C*** DUMMY READING KEYWORD
      READ(1, '(A)', END=2) LINE
      READ(1, '(A)', END=2) LINE
      CALL SARGV (LINE, 1, ACTPAR)
      IF (ACTPAR .EQ. '#FNANF') THEN
        CALL SARGV (LINE, 2, ACTPAR)
        FNANF = ACTPAR
      ELSE
        STOP 'ERROR IN READING FNANF'
      ENDIF
C*** DUMMY READING KEYWORD
      READ(1, '(A)', END=2) LINE

      
C***  EINLESEN DER FORMAL-NAMEN
      NFORMAL = 0
1     IVERS = 0
      READ(1, '(A)', END=2) LINE
      CALL SARGV (LINE, 1, ACTPAR)
      IF (ACTPAR .EQ. '#NAME') THEN
        CALL SARGV (LINE, 2, ACTPAR)
        FNFORMAL = FNANF( :ISTRL(FNANF( :132)))//ACTPAR( :13)//'.OUT'
        FN3FORMAL = FNANF( :ISTRL(FNANF( :132)))//ACTPAR( :13)//'.'
        OPEN (UNIT=2, FILE=FNFORMAL, STATUS='OLD', ERR=50)
        OPEN (UNIT=4, FILE=FN3FORMAL, STATUS='OLD', ERR=60)
        NFORMAL = NFORMAL + 1
        WRITE(*,*) 'NAME DES FORMAL FILES  : ',FNFORMAL( :70)
        WRITE(*,*)
        GOTO 51
      ELSE
        GOTO 1
      ENDIF
   50 WRITE(*,*) 'FILE ',FNFORMAL,' LAESST SICH NICH OEFFNEN'
      WRITE(*,*) '==========================================='
      WRITE (*,*)
      GOTO 1
   51 CONTINUE

      WRITE (3, 11)
   11 FORMAT (132('='))
      WRITE (3, '(A)') FNFORMAL( :ISTRL(FNFORMAL( :132)))
      NLINE = 0
    9 READ (2, '(A)', END=4) LINE
      CALL SARGV( LINE, 1, ACTPAR)
      IF (ACTPAR( :5) .NE. '-----' .OR. ACTPAR(60:60) .NE. '-') GOTO 9
      WRITE (3, '(A)') LINE( :ISTRL(LINE))
      READ (2, '(A)', END=4) LINE
      WRITE (3, '(A)') LINE( :ISTRL(LINE))
      READ (2, '(A)', END=4) LINE
      WRITE (3, '(A)') LINE( :ISTRL(LINE))
      NLINE = NLINE + 1
   10 READ (2, '(A)', END=4) LINE
      CALL SARGV( LINE, 1, ACTPAR)
      IF (ACTPAR .NE. 'LINE') GOTO 10
      OUTLINE = '               '//ACTPAR
   12 CALL SARGV( LINE, 2, ACTPAR)
      OUTLINE = OUTLINE( :ISTRL(OUTLINE))//'-'
     >          //ACTPAR( :4)
      READ (2, '(A)', END=4) LINE
      CALL SARGV (LINE, 1, ACTPAR)
      IF (ACTPAR .EQ. 'LINE') GOTO 12
      WRITE (3, '(A)') OUTLINE( :ISTRL(OUTLINE))
      GOTO 9

    4 WRITE (3, '(A,I4)') 'Zahl der Linien im File : ',NLINE
      CLOSE (2)
      CLOSE (4)

C***  TRY TO READ MORE VERSIONS
      IVERS = IVERS - 1
      WRITE (ACTPAR, '(I3)') IVERS
      FN2FORMAL = FNFORMAL( :ISTRL(FNFORMAL( :132))) // ';' // ACTPAR
      FN4FORMAL = FN3FORMAL( :ISTRL(FNFORMAL( :132))) // ';' // ACTPAR
      OPEN (UNIT=2, FILE=FN2FORMAL, STATUS='OLD', ERR=1)
      OPEN (UNIT=4, FILE=FN4FORMAL, STATUS='OLD', ERR=60)
      WRITE (3, '(A,I3)') 'VERSIONSNUMMER : ',IVERS
      GOTO 9

    2 CLOSE (3)
      CLOSE (1)
      GOTO 100

   99 WRITE(*,*) 'OPEN FEHLERHAFT'
      GOTO 100

   60 WRITE(*,*) 'FILE ',FNFORMAL,' HAT KEIN PLOT-GEGENSTUECK'
      WRITE(*,*) '==========================================='
      WRITE(3,*) 'FILE ',FNFORMAL,' HAT KEIN PLOT-GEGENSTUECK'
      WRITE(3,*) '==========================================='
      WRITE (*,*)

  100 CONTINUE

      END

dummy.f/        1173186307  1000  100   100644  46        `
      SUBROUTINE DUMMY
      RETURN
      END
elli.f/         1553528659  5006  320   100644  1940      `
      SUBROUTINE ELLI(X, Y, A, B, ALPHA, PHISTART, PHILENG, 
     >                XUNA, YUNA, NA, MAXA)

C*************************************************************
C     ... PLOTTET EINE ELLIPSE ODER ELLIPSENBOGENBOGEN; 
C     X, Y : KOORDINATEN DES KREISMITTELPUNKTS IN CM
C     A, B : HALBACHSEN DER ELLIPSE
C     A LIEGT IN X-RICHTUNG
C     B LIEGT IN Y-RICHTUNG
C     ALPHA : DREHWINKEL DER ELLIPSE
C     PHISTART: ANFANGSWINKEL UND WINKELLAENGE DES BOGENS 
C     RADIUS : IN CM
C*****************************************************************

      DIMENSION XUNA(MAXA), YUNA(MAXA)

      DATA PI / 3.14159 /

C***  SPACING DER PUNKTE IN CM:
      DATA SPACING  / 0.1 /

C***  ... JEDOCH MAXIMALER WINKELABSTAND (IN GRAD)
       DATA DPMAX / 10. /

      MAXA2 = MAXA - 2

      DELPHI = SPACING * 180. / (PI * AMAX1(ABS(A), ABS(B)))
      IF (DELPHI .GT. DPMAX) DELPHI = DPMAX
      IF (PHILENG .LT. 0) DELPHI = -DELPHI

      PHI = PHISTART
      PHIEND = PHISTART + PHILENG

      PHIRAD = PHI * PI / 180. 
      CALL TURN (XP, YP, A*COS(PHIRAD), B*SIN(PHIRAD), ALPHA)
      NA = NA + 1
      IF (NA .GE. MAXA2) STOP 'DIMENSION ERROR IN ELLI'
      XUNA(NA) = X+XP
      YUNA(NA) = Y+YP
C!!!      CALL GCPLOT (X+XP, Y+YP, 3)

    1 CONTINUE
      PHI = PHI + DELPHI
      IF ( (PHI-PHISTART)*(PHI-PHIEND) .LT. .0) THEN
         PHIRAD = PHI * PI / 180. 
         CALL TURN (XP, YP, A*COS(PHIRAD), B*SIN(PHIRAD), ALPHA)
      IF (NA .GE. MAXA2) STOP 'DIMENSION ERROR IN ELLI'
      NA = NA + 1
      XUNA(NA) = X+XP
      YUNA(NA) = Y+YP
C!!!         CALL GCPLOT (X+XP, Y+YP, 2)
         GOTO 1
       ELSE
         PHI = PHIEND
         PHIRAD = PHI * PI / 180. 
         CALL TURN (XP, YP, A*COS(PHIRAD), B*SIN(PHIRAD), ALPHA)
      IF (NA .GE. MAXA2) STOP 'DIMENSION ERROR IN ELLI'
      NA = NA + 1
      XUNA(NA) = X+XP
      YUNA(NA) = Y+YP
C!!!         CALL GCPLOT (X+XP, Y+YP, 2)
       ENDIF

      RETURN
      END
excmd.f/        1553528659  5006  320   100644  31495     `
      SUBROUTINE EXCMD (NCMD, NCMDMAX, SCMD, X, Y, X1, Y1, ISET, NDAT,
     >                  NDATMAX, NSET, NSETMAX, ISYMBOL, NPEN, ICOLOR, 
     >                  B, C, MPACTIVE, VAR, MAXVAR, NVAR, STRIP, ISKIP,
     >                  ISETXERR, ISETYERR, XERRTYPE, YERRTYPE, SETNAME,
     >                  DATASETLINE, SSIZE)

C**********************************************************************
C***  EXECUTE THE COMMAND LINES
C***  CALLED FROM INTIN AND READDATA
C**********************************************************************


      DIMENSION X(NDATMAX, NSETMAX), Y(NDATMAX, NSETMAX)
      DIMENSION X1(NDATMAX), Y1(NDATMAX)
      DIMENSION B(6), C(6)
      DIMENSION NDAT(NSETMAX), NPEN(NSETMAX), ICOLOR(NSETMAX)
      DIMENSION ISYMBOL(NSETMAX), STRIP(2,NSETMAX), SSIZE(NSETMAX)
      DIMENSION ISETXERR(NSETMAX), ISETYERR(NSETMAX)
      CHARACTER*(*) SETNAME(NSETMAX)
      CHARACTER*(*) XERRTYPE(NSETMAX), YERRTYPE(NSETMAX)
      CHARACTER*(*) VAR(MAXVAR,2)
      CHARACTER*(*) DATASETLINE(NSETMAX)
      CHARACTER*132 SCMD(NCMDMAX), LINE
      CHARACTER ACTPAR*20, ACTPAR2*20, ARICHR*1, KEY*20
      CHARACTER*3 CNSET, FILENAME*60
      LOGICAL BCMD, MPACTIVE, BYNOM, BEXDONE, BSORT(2), BARI2
      LOGICAL BLINREGYERR, BCONV
      EXTERNAL MERGE
 
      ISETXERR(ISET) = 0
      ISETYERR(ISET) = 0

      I = 0
      BSORT(1) = .FALSE.
      BSORT(2) = .FALSE.
      BLINREGYERR = .FALSE.
      
C***  Start Loop =================================================
   10 I = I + 1
      IF (I .GT. NCMD) GOTO 12

        LINE = SCMD(I)
C***   Expand Variables in LINE
        CALL SUBVAR (LINE, VAR, MAXVAR, NVAR)
C***   Debugging output
c        write (*,*) 'line=', line(:idx(line))
        ISETOP = ISET

C***  SEARCH FOR KEYWORD "DATASET"
      CALL SARGC (LINE, NARG)
      DO 15 J=3, NARG-1
         CALL SARGV (LINE, J, ACTPAR)
         IF (ACTPAR .EQ. 'DATASET') THEN
            CALL DECSETNAME (LINE, J+1, SETNAME, NSET, ISETOP)
         ENDIF
   15 CONTINUE

      CALL SARGV (LINE, 2, ACTPAR)

C-----     
      IF (ACTPAR .EQ. 'SKIP') THEN
         CALL SUBVAR (LINE, VAR, MAXVAR, NVAR)
         CALL SARGC (LINE, NPAR)
         IF (NPAR .GE. 3) THEN
           CALL SARGV (LINE, 3, ACTPAR)
C*         SKIP refers to another dataset?
           IF (ISETOP .NE. ISET) THEN
            write (*,*) 
            write (*,*) '***** SKIP DATASET ', ISETOP
            CALL SKIPDATASET (ISETOP, NSET, NDATMAX, NSETMAX, X, Y, 
     >          ISYMBOL, STRIP, NPEN, SSIZE, ICOLOR, ISETXERR, ISETYERR,
     >          XERRTYPE, YERRTYPE, SETNAME, DATASETLINE)
           ELSE 
              READ (ACTPAR,'(I20)', ERR=110) ISKIP
C-            ignore non-integer argument
           ENDIF
         ELSE
  110       ISKIP = 1
         ENDIF

      ELSE IF (ACTPAR .EQ. 'XOFFSET' .OR. ACTPAR .EQ. 'X+'
     >      .OR. ACTPAR .EQ. 'XADD') THEN
          CALL SARGV (LINE, 3, ACTPAR)
          IF (ACTPAR .EQ. 'X') THEN
             DO 21 J=1, NDAT(ISETOP)
   21        X(J,ISETOP) = X(J,ISETOP) + X(J,ISETOP)
            ELSE IF (ACTPAR .EQ. 'Y') THEN
             DO 22 J=1, NDAT(ISETOP)
   22        X(J,ISETOP) = X(J,ISETOP) + Y(J,ISETOP)
            ELSE
              CALL DECVAR (ACTPAR, VAR, MAXVAR, NVAR)
              READ (ACTPAR, '(BN,F20.0)',ERR=99) ADD
              DO 20 J=1, NDAT(ISETOP)
   20         X(J,ISETOP) = X(J,ISETOP) + ADD
            ENDIF
C-----
        ELSE IF (ACTPAR .EQ. 'YOFFSET' .OR. ACTPAR .EQ. 'Y+'
     >      .OR. ACTPAR .EQ. 'YADD') THEN
          CALL SARGV (LINE, 3, ACTPAR)
          IF (ACTPAR .EQ. 'X') THEN
             DO 31 J=1, NDAT(ISETOP)
   31        Y(J,ISETOP) = Y(J,ISETOP) + X(J,ISETOP)
            ELSE IF (ACTPAR .EQ. 'Y') THEN
             DO 32 J=1, NDAT(ISETOP)
   32        Y(J,ISETOP) = Y(J,ISETOP) + Y(J,ISETOP)
            ELSE
              CALL DECVAR (ACTPAR, VAR, MAXVAR, NVAR)
              READ (ACTPAR, '(BN,F20.0)',ERR=99) ADD
              DO 30 J=1, NDAT(ISETOP)
   30         Y(J,ISETOP) = Y(J,ISETOP) + ADD
            ENDIF
   
C-----
        ELSE IF (ACTPAR .EQ. 'X-' .OR. ACTPAR .EQ. 'XSUB') THEN
          CALL SARGV (LINE, 3, ACTPAR)
          IF (ACTPAR .EQ. 'X') THEN
             DO 121 J=1, NDAT(ISETOP)
  121        X(J,ISETOP) = X(J,ISETOP) - X(J,ISETOP)
            ELSE IF (ACTPAR .EQ. 'Y') THEN
             DO 122 J=1, NDAT(ISETOP)
  122        X(J,ISETOP) = X(J,ISETOP) - Y(J,ISETOP)
            ELSE
             CALL DECVAR (ACTPAR, VAR, MAXVAR, NVAR)
             READ (ACTPAR, '(BN,F20.0)',ERR=99) ADD
             DO 120 J=1, NDAT(ISETOP)
  120        X(J,ISETOP) = X(J,ISETOP) - ADD
            ENDIF
C-----
        ELSE IF (ACTPAR .EQ. 'Y-' .OR. ACTPAR .EQ. 'YSUB') THEN
          CALL SARGV (LINE, 3, ACTPAR)
          IF (ACTPAR .EQ. 'X') THEN
             DO 131 J=1, NDAT(ISETOP)
  131        Y(J,ISETOP) = Y(J,ISETOP) - X(J,ISETOP)
            ELSE IF (ACTPAR .EQ. 'Y') THEN
             DO 132 J=1, NDAT(ISETOP)
  132        Y(J,ISETOP) = Y(J,ISETOP) - Y(J,ISETOP)
            ELSE
             CALL DECVAR (ACTPAR, VAR, MAXVAR, NVAR)
             READ (ACTPAR, '(BN,F20.0)',ERR=99) ADD
             DO 130 J=1, NDAT(ISETOP)
  130        Y(J,ISETOP) = Y(J,ISETOP) - ADD
            ENDIF
   
C-----
        ELSE IF (ACTPAR .EQ. 'XMULT' .OR. ACTPAR .EQ. 'X*') THEN
          CALL SARGV (LINE, 3, ACTPAR)
          IF (ACTPAR .EQ. 'X') THEN
             DO 41 J=1, NDAT(ISETOP)
   41        X(J,ISETOP) = X(J,ISETOP) * X(J,ISETOP)
            ELSE IF (ACTPAR .EQ. 'Y') THEN
             DO 42 J=1, NDAT(ISETOP)
   42        X(J,ISETOP) = X(J,ISETOP) * Y(J,ISETOP)
            ELSE
             CALL DECVAR (ACTPAR, VAR, MAXVAR, NVAR)
             READ (ACTPAR, '(BN,F20.0)',ERR=99) RMULT
             DO 40 J=1, NDAT(ISETOP)
   40        X(J,ISETOP) = X(J,ISETOP) * RMULT
            ENDIF

C-----
        ELSE IF (ACTPAR .EQ. 'YMULT' .OR. ACTPAR .EQ. 'Y*') THEN
          CALL SARGV (LINE, 3, ACTPAR)
          IF (ACTPAR .EQ. 'X') THEN
             DO 51 J=1, NDAT(ISETOP)
   51        Y(J,ISETOP) = Y(J,ISETOP) * X(J,ISETOP)
            ELSE IF (ACTPAR .EQ. 'Y') THEN
             DO 52 J=1, NDAT(ISETOP)
   52        Y(J,ISETOP) = Y(J,ISETOP) * Y(J,ISETOP)
            ELSE
             CALL DECVAR (ACTPAR, VAR, MAXVAR, NVAR)
             READ (ACTPAR, '(BN,F20.0)',ERR=99) RMULT
             DO 50 J=1, NDAT(ISETOP)
   50        Y(J,ISETOP) = Y(J,ISETOP) * RMULT
            ENDIF

C-----
        ELSE IF (ACTPAR .EQ. 'XDIV' .OR. ACTPAR .EQ. 'X/') THEN
          CALL SARGV (LINE, 3, ACTPAR)
          IF (ACTPAR .EQ. 'X') THEN
             DO 141 J=1, NDAT(ISETOP)
  141        X(J,ISETOP) = X(J,ISETOP) / X(J,ISETOP)
            ELSE IF (ACTPAR .EQ. 'Y') THEN
             DO 142 J=1, NDAT(ISETOP)
  142        X(J,ISETOP) = X(J,ISETOP) / Y(J,ISETOP)
            ELSE
             CALL DECVAR (ACTPAR, VAR, MAXVAR, NVAR)
             READ (ACTPAR, '(BN,F20.0)',ERR=99) RMULT
             DO 140 J=1, NDAT(ISETOP)
  140        X(J,ISETOP) = X(J,ISETOP) / RMULT
            ENDIF

C-----
        ELSE IF (ACTPAR .EQ. 'YDIV' .OR. ACTPAR .EQ. 'Y/') THEN
          CALL SARGV (LINE, 3, ACTPAR)
          IF (ACTPAR .EQ. 'X') THEN
             DO 151 J=1, NDAT(ISETOP)
  151        Y(J,ISETOP) = Y(J,ISETOP) / X(J,ISETOP)
            ELSE IF (ACTPAR .EQ. 'Y') THEN
             DO 152 J=1, NDAT(ISETOP)
  152        Y(J,ISETOP) = Y(J,ISETOP) / Y(J,ISETOP)
            ELSE
             CALL DECVAR (ACTPAR, VAR, MAXVAR, NVAR)
             READ (ACTPAR, '(BN,F20.0)',ERR=99) RMULT
             DO 150 J=1, NDAT(ISETOP)
  150        Y(J,ISETOP) = Y(J,ISETOP) / RMULT
            ENDIF

C-----
        ELSE IF (ACTPAR .EQ. 'XLOG' .OR. ACTPAR .EQ. 'LOG(X)') THEN
          DO 60 J=1, NDAT(ISETOP)
            ARG = X(J,ISETOP)
            IF (ARG .LE. .0) GOTO 98
   60       X(J,ISETOP) = ALOG10 (ARG)

C-----
        ELSE IF (ACTPAR .EQ. 'YLOG' .OR. ACTPAR .EQ. 'LOG(Y)') THEN
          DO 70 J=1, NDAT(ISETOP)
            ARG = Y(J,ISETOP)
            IF (ARG .LE. .0) GOTO 98
   70       Y(J,ISETOP) = ALOG10 (ARG)

C-----
        ELSE IF (ACTPAR .EQ. 'XDEX' .OR. ACTPAR .EQ. '10**X') THEN
          DO 80 J=1, NDAT(ISETOP)
   80       X(J,ISETOP) = 10**X(J,ISETOP)

C-----
        ELSE IF (ACTPAR .EQ. 'EXP(X)' .OR. ACTPAR .EQ. 'E**X') THEN
          DO J=1, NDAT(ISETOP)
            X(J,ISETOP) = EXP(X(J,ISETOP))
          ENDDO

C-----
        ELSE IF (ACTPAR .EQ. 'YDEX' .OR. ACTPAR .EQ. '10**Y') THEN
          DO 90 J=1, NDAT(ISETOP)
            Y(J,ISETOP) = 10**Y(J,ISETOP)
   90     CONTINUE

C-----
        ELSE IF (ACTPAR .EQ. 'EXP(Y)' .OR. ACTPAR .EQ. 'E**Y') THEN
          DO J=1, NDAT(ISETOP)
            Y(J,ISETOP) = EXP(Y(J,ISETOP))
          ENDDO

C-----
        ELSE IF (ACTPAR .EQ. 'XINV' .OR. ACTPAR .EQ. '1/X') THEN
          DO J=1, NDAT(ISETOP)
            X(J,ISETOP) = 1. / X(J,ISETOP)
          ENDDO
C-----
        ELSE IF (ACTPAR .EQ. 'YINV' .OR. ACTPAR .EQ. '1/Y') THEN
          DO J=1, NDAT(ISETOP)
            Y(J,ISETOP) = 1. / Y(J,ISETOP)
          ENDDO
C-----
        ELSE IF (ACTPAR .EQ. 'SIGN(X)') THEN
          DO J=1, NDAT(ISETOP)
          XX = X(J,ISETOP)
          X(J,ISETOP) = SIGN(1., XX)
          IF (XX .EQ. .0) X(J,ISETOP) = .0
          ENDDO
C-----
        ELSE IF (ACTPAR .EQ. 'SIGN(Y)') THEN
          DO J=1, NDAT(ISETOP)
          YY = Y(J,ISETOP)
          Y(J,ISETOP) = SIGN(1., YY)
          IF (YY .EQ. .0) Y(J,ISETOP) = .0
          ENDDO
C-----
        ELSE IF (ACTPAR .EQ. 'ABS(X)') THEN
          DO J=1, NDAT(ISETOP)
          X(J,ISETOP) = ABS(X(J,ISETOP))
          ENDDO
C-----
        ELSE IF (ACTPAR .EQ. 'ABS(Y)') THEN
          DO J=1, NDAT(ISETOP)
          Y(J,ISETOP) = ABS(Y(J,ISETOP))
          ENDDO
C-----
        ELSE IF (ACTPAR .EQ. 'XMIN') THEN
          CALL SARGV (LINE, 3, ACTPAR)
          READ (ACTPAR, '(BN,F20.0)',ERR=99) XMINDAT
          DO J=1, NDAT(ISETOP)
          X(J,ISETOP) = AMAX1(XMINDAT,X(J,ISETOP))
          END DO
C-----
        ELSE IF (ACTPAR .EQ. 'XMAX') THEN
          CALL SARGV (LINE, 3, ACTPAR)
          READ (ACTPAR, '(BN,F20.0)',ERR=99) XMAXDAT
          DO J=1, NDAT(ISETOP)
          X(J,ISETOP) = AMIN1(XMAXDAT,X(J,ISETOP))
          END DO
C-----
        ELSE IF (ACTPAR .EQ. 'YMIN') THEN
          CALL SARGV (LINE, 3, ACTPAR)
          READ (ACTPAR, '(BN,F20.0)',ERR=99) YMINDAT
          DO J=1, NDAT(ISETOP)
          Y(J,ISETOP) = AMAX1(YMINDAT,Y(J,ISETOP))
          END DO
C-----
        ELSE IF (ACTPAR .EQ. 'YMAX') THEN
          CALL SARGV (LINE, 3, ACTPAR)
          READ (ACTPAR, '(BN,F20.0)',ERR=99) YMAXDAT
          DO J=1, NDAT(ISETOP)
          Y(J,ISETOP) = AMIN1(YMAXDAT,Y(J,ISETOP))
          END DO
C-----  ONLY USED FOR FALSE-COLOR PLOT (SYMBOL=40)
        ELSE IF (ACTPAR .EQ. 'STRIP') THEN
          CALL SARGV (LINE, 3, ACTPAR)
          READ (ACTPAR, '(BN,F20.0)',ERR=99) STRIP(1,ISETOP)
          CALL SARGV (LINE, 4, ACTPAR)
          READ (ACTPAR, '(BN,F20.0)',ERR=99) STRIP(2,ISETOP)
C-----
        ELSE IF (ACTPAR .EQ. 'X-CUT') THEN
          CALL SARGV (LINE, 3, ACTPAR)
          CALL READPAR (ACTPAR, B, C, XCUT1, VAR, MAXVAR, NVAR)
          CALL SARGV (LINE, 4, ACTPAR)
          CALL READPAR (ACTPAR, B, C, XCUT2, VAR, MAXVAR, NVAR)
          J = 0
   92     J = J + 1
            IF (X(J,ISETOP) .LT. XCUT1 .OR. 
     >          X(J,ISETOP) .GT. XCUT2 ) THEN
              NDAT(ISETOP) = NDAT(ISETOP) - 1
              DO 94 J2=J, NDAT(ISETOP)
                X(J2,ISETOP) = X(J2+1,ISETOP)
                Y(J2,ISETOP) = Y(J2+1,ISETOP)
   94         CONTINUE
              J = J - 1
            ENDIF
          IF (J .LT. NDAT(ISETOP)) GOTO 92

C-----
        ELSE IF (ACTPAR .EQ. 'Y-CUT') THEN
          CALL SARGV (LINE, 3, ACTPAR)
          READ (ACTPAR, '(BN,F20.0)',ERR=99) YCUT1
          CALL SARGV (LINE, 4, ACTPAR)
          READ (ACTPAR, '(BN,F20.0)',ERR=99) YCUT2
          J = 0
   95     J = J + 1
            IF (Y(J,ISETOP) .LT. YCUT1 .OR. 
     >          Y(J,ISETOP) .GT. YCUT2 ) THEN
              NDAT(ISETOP) = NDAT(ISETOP) - 1
              DO 96 J2=J, NDAT(ISETOP)
                X(J2,ISETOP) = X(J2+1,ISETOP)
                Y(J2,ISETOP) = Y(J2+1,ISETOP)
   96         CONTINUE
              J = J - 1
            ENDIF
          IF (J .LT. NDAT(ISETOP)) GOTO 95

C-----
        ELSE IF (ACTPAR .EQ. 'X-OMIT') THEN
          CALL SARGV (LINE, 3, ACTPAR)
          CALL READPAR (ACTPAR, B, C, XCUT1, VAR, MAXVAR, NVAR)
          CALL SARGV (LINE, 4, ACTPAR)
          CALL READPAR (ACTPAR, B, C, XCUT2, VAR, MAXVAR, NVAR)
          J = 0
   91     J = J + 1
            IF (X(J,ISETOP) .GE. XCUT1 .AND. 
     >          X(J,ISETOP) .LE. XCUT2 ) THEN
              NDAT(ISETOP) = NDAT(ISETOP) - 1
              DO 93 J2=J, NDAT(ISETOP)
                X(J2,ISETOP) = X(J2+1,ISETOP)
                Y(J2,ISETOP) = Y(J2+1,ISETOP)
   93         CONTINUE
              J = J - 1
            ENDIF
          IF (J .LT. NDAT(ISETOP)) GOTO 91

C-----
        ELSE IF (ACTPAR .EQ. 'Y-OMIT') THEN
          CALL SARGV (LINE, 3, ACTPAR)
          READ (ACTPAR, '(BN,F20.0)',ERR=99) YCUT1
          CALL SARGV (LINE, 4, ACTPAR)
          READ (ACTPAR, '(BN,F20.0)',ERR=99) YCUT2
          J = 0
   88     J = J + 1
            IF (Y(J,ISETOP) .GE. YCUT1 .AND. 
     >          Y(J,ISETOP) .LE. YCUT2 ) THEN
              NDAT(ISETOP) = NDAT(ISETOP) - 1
              DO 89 J2=J, NDAT(ISETOP)
                X(J2,ISETOP) = X(J2+1,ISETOP)
                Y(J2,ISETOP) = Y(J2+1,ISETOP)
   89         CONTINUE
              J = J - 1
            ENDIF
          IF (J .LT. NDAT(ISETOP)) GOTO 88

C-----
        ELSE IF (ACTPAR .EQ. 'X-INC') THEN
          IF (NDAT(ISETOP) .GT. 1) THEN
            J = 1
  101       J = J + 1
              IF (X(J,ISETOP) .LT. X(J-1,ISETOP)) THEN
                NDAT(ISETOP) = NDAT(ISETOP) - 1
                DO J2=J, NDAT(ISETOP)
                  X(J2,ISETOP) = X(J2+1,ISETOP)
                  Y(J2,ISETOP) = Y(J2+1,ISETOP)
                ENDDO
                J = J - 1
              ENDIF
            IF (J .LT. NDAT(ISETOP)) GOTO 101
          ENDIF

C-----
        ELSE IF (ACTPAR .EQ. 'XY-SWAP') THEN
          DO 196 J=1, NDAT(ISETOP)
             TEMP = X(J,ISETOP)
             X(J,ISETOP) = Y(J,ISETOP)
             Y(J,ISETOP) = TEMP
  196     CONTINUE

C-----
        ELSE IF (ACTPAR .EQ. 'Y-NORM' .OR.
     >           ACTPAR .EQ. 'Y-NORM+' .OR.
     >           ACTPAR .EQ. 'Y-NORM*') THEN

          IF (ACTPAR .EQ. 'Y-NORM' .OR.
     >        ACTPAR .EQ. 'Y-NORM+') THEN
C***  ADDITION
            BYNOM = .FALSE.
          ELSE
C***  MULTIPLICATION
            BYNOM = .TRUE.
          ENDIF
          CALL SARGV (LINE, 3, ACTPAR)
          CALL DECVAR (ACTPAR, VAR, MAXVAR, NVAR)
          READ (ACTPAR, '(BN,F20.0)',ERR=99) XLAM
          CALL SARGV (LINE, 4, ACTPAR)
          CALL DECVAR (ACTPAR, VAR, MAXVAR, NVAR)
          READ (ACTPAR, '(BN,F20.0)',ERR=99) YNORM
C***    FIND FIRST TWO DATAPOINTS WHICH ENCIRCLE XLAM
          J = 1
          D = XLAM - X(J,ISETOP)
  300     J = J + 1
            IF (J .GT. NDAT(ISETOP)) THEN
              WRITE (*,*) '******* ',
     >                    'XLAM NOT IN THE RANGE OF THE DATASET'
              WRITE (*,*) 'COMMAND Y-NORM NOT APPLIED'
              STOP '******* ERROR IN SUBR. EXCMD'
            ENDIF
            DN = XLAM - X(J,ISETOP)
            IF (D * DN .LE. 0.) GOTO 302
            D = DN
          GOTO 300
  302     CONTINUE
C***    CALCULATE YADD
          Q = (XLAM - X(J,ISETOP)) / (X(J-1,ISETOP) - X(J,ISETOP))
          YDAT = Y(J-1,ISETOP)*Q + Y(J,ISETOP)*(1-Q)
          IF (.NOT. BYNOM) THEN
            YOP = YNORM - YDAT
            WRITE (*,'(A,G15.7,$)') " Y-NORM+ ", YOP
C***    APPLY YOP TO THE WHOLE DATASET
            DO J=1, NDAT(ISETOP)
              Y(J,ISETOP) = Y(J,ISETOP) + YOP
            ENDDO
304         CONTINUE
          ELSE
            YOP = YNORM / YDAT
            WRITE (*,'(A,G15.7,$)') " Y-NORM* ", YOP
C***    APPLY YOP TO THE WHOLE DATASET
            DO 305 J=1, NDAT(ISETOP)
              Y(J,ISETOP) = Y(J,ISETOP) * YOP
305         CONTINUE
          ENDIF

C-----
        ELSE IF (ACTPAR .EQ. 'ARI') THEN
          CALL DECSETNAME (LINE, 3, SETNAME, NSET, ISET1)
          CALL SARGV (LINE, 4, ACTPAR)
          READ (ACTPAR, '(BN,A1)',ERR=99) ARICHR
          CALL DECSETNAME (LINE, 5, SETNAME, NSET, ISET2)
          BCMD = .TRUE.
	  
C         Special parameter to suppress x-point merging
          BARI2 = .FALSE.
          IF (NARG .GE. 6) THEN
             CALL SARGV(LINE, 6, ACTPAR)
             BARI2 = ACTPAR .EQ. 'NOINTERPOLATIONIN1' .OR. 
     >           ACTPAR .EQ. 'KEEP_X1' 
          ENDIF
          CALL ARISET (X, Y, ISET1, ISET2, NDAT, NSET, NDATMAX, 
     >             NSETMAX, ISYMBOL, NPEN, ICOLOR, ARICHR, BCMD, BARI2)

C-----
        ELSE IF (ACTPAR .EQ. 'MERGE') THEN
          CALL DECSETNAME (LINE, 3, SETNAME, NSET, ISET1)
          CALL DECSETNAME (LINE, 4, SETNAME, NSET, ISET2)
          CALL MERGE (X, Y, ISET1, ISET2, NDAT, NDATMAX, NSETMAX, NSET)

C-----
        ELSE IF (ACTPAR(:6) .EQ. 'HLYMAN') THEN
          CALL HLYMANA (X, Y, NDAT, NSET, NDATMAX, NSETMAX, ISYMBOL, 
     >                  NPEN, ICOLOR, .TRUE., ISETOP, LINE, X1, Y1)

C-----
        ELSE IF (ACTPAR(:7) .EQ. 'ISMLINE') THEN
          CALL ISMLINE (X, Y, NDAT, NSET, NDATMAX, NSETMAX, ISYMBOL,
     >                  NPEN, ICOLOR, .TRUE., ISETOP, LINE)

C-----
        ELSE IF (ACTPAR .EQ. 'REDDENING') THEN
          CALL EXTINCT (X, Y, X1, Y1, NDAT, ISETOP, 
     >                  NDATMAX, NSETMAX, LINE, ISYMBOL, MPACTIVE)

C-----
        ELSE IF (ACTPAR .EQ. 'CONVOL') THEN
          BCONV = .FALSE.
          CALL CONVEX (Y1, X(1,ISETOP), Y(1,ISETOP), NDATMAX, 
     >                   NDAT(ISETOP), BCONV, LINE)
          IF (BCONV) THEN
           DO 106 J=1, NDAT(ISETOP)
              Y(J,ISETOP) = Y1(J)
  106       CONTINUE
          ENDIF
C-----
        ELSE IF (ACTPAR .EQ. 'BINNING') THEN
          CALL SARGV (LINE, 3, ACTPAR)
          CALL DECVAR (ACTPAR, VAR, MAXVAR, NVAR)
          READ (ACTPAR, '(BN,F20.0)', ERR=99) W
          IF (W .NE. 0) THEN
            CALL BINNING (X(1,ISETOP), Y(1,ISETOP), NDATMAX, 
     >                   NDAT(ISETOP), W, MPACTIVE)
          ENDIF
C-----
        ELSE IF (ACTPAR .EQ. 'SORT') THEN
C                             ====
         CALL SARGC (LINE, NARG)
         IF (NARG .GT. 4) PRINT *, 
     >     "INFO: COMMAND SORT: MORE OPTIONS THAN NEEDED"
         CALL SARGV (LINE, 3, ACTPAR)
         IF (ACTPAR .EQ. 'INV')  BSORT(1) = .TRUE.
         IF (ACTPAR .EQ. 'JOIN') BSORT(2) = .TRUE.
         CALL SARGV (LINE, 4, ACTPAR)
         IF (ACTPAR .EQ. 'INV')  BSORT(1) = .TRUE.
         IF (ACTPAR .EQ. 'JOIN') BSORT(2) = .TRUE.      
         CALL QUICKSORT(X(1,ISETOP), Y(1,ISETOP)
     >     ,NDATMAX, NDAT(ISETOP), BSORT, X1, Y1)           


C----- Write a dataset table into a file
       ELSE IF (ACTPAR .EQ. 'WRITE') THEN
C         Create default filename
          WRITE (CNSET,'(I3)') ISETOP
          CALL FLUSHLEFT (CNSET)
          FILENAME = 'WRPLOT_DATASET'// CNSET(:IDX(CNSET)) // '.DAT' 
C         Filename explicitely given?       
          DO J=3, NARG-1
             CALL SARGV (LINE, J, ACTPAR)
             IF (ACTPAR .EQ. 'FILE') CALL SARGV (LINE, J+1, FILENAME)
          ENDDO
C         Write the file
          OPEN (13, FILE= FILENAME(:IDX(FILENAME)),
     >            STATUS='UNKNOWN', ERR=100)
c          WRITE (13,'(A)', ERR=100) 'N=? XYTABLE'
          DO II = 1, NDAT(ISETOP) 
             WRITE (13,'(1P,G17.10,1x,G17.10)') 
     >             X(II,ISETOP), Y(II,ISETOP)
          ENDDO
c          WRITE (13,'(A)') 'FINISH'
          CLOSE (13)
C-----
        ELSE IF (ACTPAR .EQ. 'WAVECAL') THEN
C         Writes Y-Values of current dataset into X-values of set ISETC 
          CALL DECSETNAME (LINE, 3, SETNAME, NSET, ISETC)
          NDC = NDAT(ISETC)
	  NDO = NDAT(ISETOP)
C         Simple case ?
          IF (NDC .NE. NDO) GOTO 133
          DO II=1,NDAT(ISETC)
             IF (X(II,ISETC).NE.X(II,ISETOP)) GOTO 133
          ENDDO

C         Simple case: X-values of both datasets are identical
          DO II=1, NDC
            X(II,ISETC) = Y(II,ISETOP)
          ENDDO
          GOTO 10

  133     CONTINUE 
C         General case: X-values result from inter-  and extrapolation
C         Check calibration data
          IF (NDO .LT. 2) THEN
	     WRITE (*, '(//,A)') 
     >        'FATAL ERROR: Calibration Data need at least 2 points!' 
             GOTO 97
          ENDIF
          DELTA = X(NDO,ISETOP) - X(1,ISETOP)
          DO II=2, NDO
             IF ( (X(II,ISETOP)-X(II-1,ISETOP))*DELTA .LE. 0) THEN
	       WRITE (*, '(//,A)') 
     >           'FATAL ERROR: Calibration Data not monotonic!' 
               GOTO 97
             ENDIF
	  ENDDO
	  
	  DO II=1, NDC
            IF ((X(II,ISETC)-X(  1,ISETOP)) *
     >          (X(II,ISETC)-X(NDO,ISETOP)) .LE. .0) THEN	  
C           Point within the range of calibration data
               CALL FSPLINE 
     >            (XX,X(II,ISETC),Y(1,ISETOP),X(1,ISETOP),NDO)
C           Extrapolation, linear from the first or last two points
            ELSE IF ((X(II,ISETC)-X(  1,ISETOP)) * DELTA .LT. .0) THEN
               DX = X(2,ISETOP) - X(1,ISETOP)
	       P  = (X(II,ISETC) - X(1,ISETOP)) / DX
	       XX = (1.-P)*Y(1,ISETOP) + P*Y(2,ISETOP)
	    ELSE
               DX = X(NDO-1,ISETOP) - X(NDO,ISETOP)
	       P  = (X(II,ISETC) - X(NDO,ISETOP)) / DX
	       XX = (1.-P)*Y(NDO,ISETOP) + P*Y(NDO-1,ISETOP)
            ENDIF
            X(II,ISETC) = XX
	  ENDDO
c          STOP 'test'
	  
	  
C-----
        ELSE IF (ACTPAR(1:6) .EQ. 'EXPAND') THEN
           CALL EXPANDDAT (LINE, X(1,ISETOP), Y(1,ISETOP), X1, Y1, 
     >                    NDAT(ISETOP), NDATMAX, MPACTIVE)
C-----
        ELSE IF (ACTPAR .EQ. 'INSERT') THEN
C                             ======
          CALL SARGV (LINE, 3, ACTPAR)
          READ (ACTPAR, '(BN,F20.0)', ERR=99) XINS
          CALL INSERTPOINT (X(1,ISETOP), Y(1,ISETOP), NDATMAX, 
     >                     NDAT(ISETOP), XINS, LINS)
          GOTO 10
C-----
        ELSE IF (ACTPAR .EQ. 'COMBINE') THEN
C                             =======
          YNULL = 1.E-2
          CALL DECSETNAME (LINE, 3, SETNAME, NSET, ISET1)
          CALL DECSETNAME (LINE, 4, SETNAME, NSET, ISET2)
          CALL SARGV (LINE, 5, ACTPAR)
          CALL READPAR (ACTPAR, B, C, XL1, VAR, MAXVAR, NVAR)
          XL1 = MAX(0.1, XL1)
          CALL SARGV (LINE, 6, ACTPAR)
          CALL READPAR (ACTPAR, B, C, XL2, VAR, MAXVAR, NVAR)
          XL2 = MAX(0.1, XL2)
          CALL SARGV (LINE, 7, ACTPAR)
          CALL READPAR (ACTPAR, B, C, XL3, VAR, MAXVAR, NVAR)
          XL3 = MAX(0.1, XL3)
          CALL SARGV (LINE, 8, ACTPAR)
          CALL READPAR (ACTPAR, B, C, XL4, VAR, MAXVAR, NVAR)
          XL4 = MAX(0.1, XL4)
          IF (NARG .GE. 10) THEN
            CALL SARGV (LINE, 9, ACTPAR)
            IF (ACTPAR .EQ. 'DISPLAY') THEN
              CALL SARGV (LINE, 10, ACTPAR)
              READ (ACTPAR, '(BN,I10)',ERR=99) IDISP
            ENDIF
          ENDIF
C***  CHECK FOR FREE DATASETS
          IF (NSET .GT. NSETMAX-3) THEN
            WRITE (0,*) 'COMMAND COMBINE CANNOT BE USED, BECAUSE'
            WRITE (0,*) 'IT NEEDS AT THREE FREE DATASETS'
            WRITE (0,*) 'PLEASE INCREASE THE DIMENSION (NSETMAX)'
            STOP 'ERROR IN EXCMD'
          ENDIF
C***  CONSTRUCTION OF THE THREE DATASETS, USED FOR AS THE WEIGHTS
          IH1 = NSET + 1
          IH2 = NSET + 2
          IH3 = NSET + 3
          NSET = NSET + 3
C***  CRUDE CHECK OF INCREASING DATASETS
          IF (X(1,ISET1) .GT. X(NDAT(ISET1),ISET1)) THEN
            WRITE (0,*) 'ERROR WHEN COMMAND COMBINE IS USED'
            WRITE (0,*) 'X-DATA OF THE FIRST DATASET NOT INCREASING'
            STOP 'ERROR IN EXCMD'
          ENDIF
          IF (X(1,ISET2) .GT. X(NDAT(ISET2),ISET2)) THEN
            WRITE (0,*) 'ERROR WHEN COMMAND COMBINE IS USED'
            WRITE (0,*) 'X-DATA OF THE SECOND DATASET NOT INCREASING'
            STOP 'ERROR IN EXCMD'
          ENDIF

          NPEN(IH1) = 1
          NPEN(IH2) = 1
          NPEN(IH3) = 1
          ICOLOR(IH1) = 3
          ICOLOR(IH2) = 3
          ISYMBOL(IH1) = 9
          ISYMBOL(IH2) = 10

C***  CONSTRUCT THE FIRST DATASET, AND PRESET THE THIRD ONE
          IF (X(1,ISET2) .LT. X(1,ISET1)) THEN
            X(1, IH1) = X(1, ISET2)
            Y(1, IH1) = YNULL
            IIN = 1
          ELSE
            IIN = 0
          ENDIF
          X(1+IIN, IH1) = X(1,           ISET1)
          X(2+IIN, IH1) = X(1,           ISET1) + XL1
          X(3+IIN, IH1) = X(NDAT(ISET1), ISET1) - XL2
          X(4+IIN, IH1) = X(NDAT(ISET1), ISET1)
          Y(1+IIN, IH1) = YNULL
          Y(2+IIN, IH1) = 1.
          Y(3+IIN, IH1) = 1.
          Y(4+IIN, IH1) = YNULL
          IF (X(NDAT(ISET2), ISET2) .GT. X(NDAT(ISET1), ISET1)) THEN
            X(5+IIN, IH1) = X(NDAT(ISET2), ISET2)
            Y(5+IIN, IH1) = YNULL
            NDAT(IH1) = IIN + 5
          ELSE
            NDAT(IH1) = IIN + 4
          ENDIF
          DO I=1, NDAT(IH1)
            X(I,IH3) = X(I,IH1)
            Y(I,IH3) = Y(I,IH1)
          ENDDO
          NDAT(IH3) = NDAT(IH1)

C***  CONSTRUCT THE SECOND DATASET
          IF (X(1,ISET1) .LT. X(1,ISET2)) THEN
            X(1, IH2) = X(1, ISET1)
            Y(1, IH2) = YNULL
            IIN = 1
          ELSE
            IIN = 0
          ENDIF
          X(1+IIN, IH2) = X(1,           ISET2)
          X(2+IIN, IH2) = X(1,           ISET2) + XL3
          X(3+IIN, IH2) = X(NDAT(ISET2), ISET2) - XL4
          X(4+IIN, IH2) = X(NDAT(ISET2), ISET2)
          Y(1+IIN, IH2) = YNULL
          Y(2+IIN, IH2) = 1.
          Y(3+IIN, IH2) = 1.
          Y(4+IIN, IH2) = YNULL
          IF (X(NDAT(ISET1), ISET1) .GT. X(NDAT(ISET2), ISET2)) THEN
            X(5+IIN, IH2) = X(NDAT(ISET1), ISET1)
            Y(5+IIN, IH2) = YNULL
            NDAT(IH2) = IIN + 5
          ELSE
            NDAT(IH2) = IIN + 4
          ENDIF

C***  CONSTRUCT THE SECOND DATASET
          BCMD = .TRUE.
          ARICHR = '+'
          CALL ARISET(X, Y, IH3, IH2, NDAT, NSET, NDATMAX, NSETMAX, 
     >             5, NPEN, ICOLOR, ARICHR, BCMD, .FALSE.)
          ICOLOR(IH3) = 2
          ISYMBOL(IH3) = 5

          IF (IDISP .EQ. 3) GOTO 125

C***  APPLY THE WEIGHTFUNCTION
          ARICHR = '*'
          CALL ARISET(X, Y, ISET1, IH1, NDAT, NSET, NDATMAX, NSETMAX, 
     >                5, NPEN, ICOLOR, ARICHR, BCMD, .FALSE.)
          CALL ARISET(X, Y, ISET2, IH2, NDAT, NSET, NDATMAX, NSETMAX, 
     >                5, NPEN, ICOLOR, ARICHR, BCMD, .FALSE.)

          IF (IDISP .EQ. 2) GOTO 125

C***  THE X-VALUES OF BOTH DATASETS MUST HAVE THE FULL WIDTH
C***    FIRST DATASET
          IF (X(1,ISET1) .GT. X(1,IH3)) THEN
            NDAT(ISET1) = NDAT(ISET1) + 1
            IF (NDAT(ISET1) .GT. NDATMAX) THEN
              WRITE (0,*) 'NDAT CANNOT BE INCREASED'
c        write (0,*) 'ndat(iset1), ndatmax',ndat(iset1), ndatmax
              STOP 'ERROR IN EXCMD'
            ENDIF
            DO I=NDAT(ISET1), 2, -1
              X(I,ISET1) = X(I-1,ISET1)
              Y(I,ISET1) = Y(I-1,ISET1)
            ENDDO
            X(1,ISET1) = X(1,IH3)
            Y(1,ISET1) = YNULL
          ENDIF
          IF (X(NDAT(ISET1),ISET1) .LT. X(NDAT(IH3),IH3)) THEN
            NDAT(ISET1) = NDAT(ISET1) + 1
            IF (NDAT(ISET1) .GT. NDATMAX) THEN
              WRITE (0,*) 'NDAT CANNOT BE INCREASED'
              STOP 'ERROR IN EXCMD'
            ENDIF
            X(NDAT(ISET1),ISET1) = X(NDAT(IH3),IH3)
            Y(NDAT(ISET1),ISET1) = YNULL
          ENDIF

C***    SECOND DATASET
          IF (X(1,ISET2) .GT. X(1,IH3)) THEN
            NDAT(ISET2) = NDAT(ISET2) + 1
            IF (NDAT(ISET2) .GT. NDATMAX) THEN
              WRITE (0,*) 'NDAT CANNOT BE INCREASED'
              STOP 'ERROR IN EXCMD'
            ENDIF
            DO I=NDAT(ISET2), 2, -1
              X(I,ISET2) = X(I-1,ISET2)
              Y(I,ISET2) = Y(I-1,ISET2)
            ENDDO
            X(1,ISET2) = X(1,IH3)
            Y(1,ISET2) = YNULL
          ENDIF
          IF (X(NDAT(ISET2),ISET2) .LT. X(NDAT(IH3),IH3)) THEN
            NDAT(ISET2) = NDAT(ISET2) + 1
            IF (NDAT(ISET2) .GT. NDATMAX) THEN
              WRITE (0,*) 'NDAT CANNOT BE INCREASED'
              STOP 'ERROR IN EXCMD'
            ENDIF
            X(NDAT(ISET2),ISET2) = X(NDAT(IH3),IH3)
            Y(NDAT(ISET2),ISET2) = YNULL
          ENDIF

C***  CONCATENATE THE TWO DATASETS
          ARICHR = '+'
          CALL ARISET(X, Y, ISET1, ISET2, NDAT, NSET, NDATMAX, NSETMAX, 
     >                5, NPEN, ICOLOR, ARICHR, BCMD, .FALSE.)

          IF (IDISP .EQ. 1) GOTO 125

C***  DIVIDE BY THE WEIGHT
          ARICHR = '/'
          CALL ARISET(X, Y, ISET1, IH3, NDAT, NSET, NDATMAX, NSETMAX, 
     >                5, NPEN, ICOLOR, ARICHR, BCMD, .FALSE.)
          NSET = NSET - 3

  125     CONTINUE


C=============================================================
C===  COMMANDS WHICH RETURN OUTPUT IN VARIABLES
C===  I.E. SO CALLED COMMAND-FUNCTIONS
C===  THE KEYWORD SHOULD START WITH 'CF-'
C=============================================================

        ELSE IF (ACTPAR(:3) .EQ. 'CF-') THEN

          BLINREGYERR = (ISETYERR(ISETOP) .GT. 0)
!          If no YERROR is specified: dummy settin to current dataset
          IF (.NOT. BLINREGYERR) ISETYERR(ISETOP) = ISETOP

          CALL EXCF (LINE, ACTPAR, VAR, MAXVAR, NVAR, 
     >               X(1,ISETOP), Y(1,ISETOP), 
     >               NDAT(ISETOP), NDATMAX, ISYMBOL(ISETOP),
     >               BLINREGYERR, 
     >               X(1,ISETYERR(ISETOP)), Y(1,ISETYERR(ISETOP)), 
     >               YERRTYPE(ISETOP), 
     >               NDAT(ISETYERR(ISETOP)) )
          IF (.NOT. BLINREGYERR) ISETYERR(ISETOP) = 0

C**     Specify another dataset which contains the error margins
        ELSE IF (ACTPAR .EQ. 'XERROR') THEN
           CALL DECSETNAME (LINE, 3, SETNAME, NSET, ISETXERR(ISET))
           CALL SARGV (LINE, 4, XERRTYPE(ISET))

C**     Specify another dataset which contains the error margins
        ELSE IF (ACTPAR .EQ. 'YERROR') THEN
           CALL DECSETNAME (LINE, 3, SETNAME, NSET, ISETYERR(ISET))
           CALL SARGV (LINE, 4, YERRTYPE(ISET))

        ELSE

C***  CHECK FOR INSTRUCTIONS
C***  ----------------------
          CALL EXINST (SCMD, NCMDMAX, NCMD, I, 'COMMAND', IERR, 
     >                 VAR, MAXVAR, NVAR)
          IF (IERR .EQ. 1) THEN
            WRITE(6,'(/,A)') '*** ILLEGAL COMMAND INSTRUCTION: '
            WRITE(6,*) LINE
            STOP '*** ERROR IN SUBR. EXCMD'  
          ENDIF

        ENDIF

C***  End Loop =================================================
      GOTO 10
   12 CONTINUE

      RETURN

   98 WRITE (6,'(//,A)') 'ERROR while executing the following line: '
      WRITE (6,*) LINE
      WRITE (6,*) 'Attempt to calculate ALOG10(',ARG, ')'
      WRITE (6,'(A,I4,A,I4)') 
     >   'The error occured in DATASET=', ISETOP, ' at INDEX=', J 
      STOP '*** ERROR in Subr. EXCMD'

   99 WRITE(6,'(//,A)') 'ERROR: INVALID FORMAT IN COMMAND LINE - '
      GOTO 97

  100 WRITE(6,'(//,A)') 'ERROR: could not open file ' // 
     >     FILENAME(:IDX(FILENAME)) // ' for WRITE action'
      GOTO 97

   97 WRITE(6,*) 'The error occured in the following line: '
      WRITE(6,*) LINE
      STOP '*** ERROR in Subr. EXCMD'

      END

extinct.f/      1553528659  5006  320   100644  21975     `
      SUBROUTINE EXTINCT (X, Y, X1, Y1, NDAT, ISET, NDATMAX, 
     >                    NSETMAX, LINE, ISYMBOL, MPACTIVE)

C**********************************************************************
C***        SUBROUTINE ZUM ROETEN STELLARER FLUESSE                 ***
C***        DATEN: X=LOG(LAMBDA/ANGSTROEM)                          ***
C***               Y=LOG(FNUE)                                      ***
C***        CALLED FROM: EXINT OR FROM
C***                     EXCMD
C***  REDDENING LAWS: 
C***
C***  "SEATON" (default):
C***  1000 - 10000 ANG: SEATON, 1979: MNRAS 187, 73P 
C***   The following IR law was commented out 2. Aug 2005
C***       > 10000 ANG: ABBOTT, TELESCO & WOLF: 1984, APJ 279, 225
C***       > 200000 ANG: extrapolation: Extinction prop. 1/Lambda
C***   Instead we now employ from:
C***      Moneti A., Stolovy S., Blommaert J.A.D.L., Figer D.F., 
C***        Najarro F., 2001, A&A 366, 106
C***      for > 10000 Ang (Table FTAB3), 
C***       and extrapolation lambda^-2 for > 240000 Ang
C***
C***   Note added 23-Apr-2010 17:47:16 by wrh:
C***      There is a new paper on IR extinction that should be considered:
C***      Fitzpatrick E.L., Massa D.: 2009, ApJ 699, 1209
C***
C***  LMC : Howarth I., 1983, MNRAS 203, 301 
C***
C***  SMC : same as LMC, but with optional RV parameter (default 2.7)
C***
C***  SMC_BAR : special law from Gordon et al. (2003) for < 3000 Ang 
C***
C***  CARDELLI : 
C***    Cardelli J.A., Clayton G.C., Mathis J.S.: 1989,  APJ 345, 245 
C***    for 1000 - 33333 A
C***    Bluewards : Extrapolation of bluemost formula
C***    Redwards  : as above
C***    
C***  FITZPATRICK :
C***    Fitzpatrick E.L.: 1999, PASP 111, 63
C***  
C***  NOTE: The laws CARDELLI and FITZPATRICK have an optional parameter  
C***        R_V which is the Extinction in the V band per E(B-V)
C***        The default value is 3.1 for both laws. 
C***
C***  X-ray range 1.24 - 413 A:
C***  Absorption for solar abundances
C***  from Morrison R. & McCammon D., 1983, ApJ 270, 119 (Table 2)
C***  Since this table ends at 413A, the range between 413A and the
C***  Lyman edge is extrapolated assuming a nu**-3 dpendence of the
C***  opacity
C***  
C***  ATTENTION: The UV laws are extrapolated (!!!) below 1000 A 
C***      to the Lyman edge!   
C***  
C**********************************************************************

      DIMENSION X(NDATMAX,NSETMAX), Y(NDATMAX,NSETMAX)
      DIMENSION X1(NDATMAX), Y1(NDATMAX)
      DIMENSION FTAB1(18), ZTAB1(18)
      DIMENSION FTAB2(8), XTAB2(8)
      DIMENSION FTAB3(48), XTAB3(48)
      DIMENSION FTAB4(30), ZTAB4(30)
      DIMENSION CTAB1(2), CTAB2(2)
      DIMENSION CTAB3(8), CTAB4(8), CTAB5(5), CTAB6(5)
      DIMENSION CTAB7(4), CTAB8(4), CTAB9(4), CTAB10(4)
      DIMENSION NDAT(NSETMAX), ISYMBOL(NSETMAX) 
      DIMENSION XSPLUV(2), YOPIR(9), YSPLUV(2), XOPIR(9)
      LOGICAL NOEXPAND, MPACTIVE, BEBVREAD, CHRINSTR
      CHARACTER ACTPAR*20, LAW*20, LINE*(*), NEXTPAR*10
      REAL :: FZ
      
C***  Used for the X-ray range:
C***  CDPERMAG = 10. ** 21.58: = HYDROGEN COLUMN DENSITY FOR E(B-V)= 1 MAG
C***       (GROENEWEGEN & LAMERS, 1989)
C***  ACHTUNG: Bohlin et al. (1978: ApJ 224, 132) GEBEN EINEN 
C***           GROESSEREN WERT: 5.8E21
      DATA CDPERMAG / 3.8E21 /

C***  log lambda in Ang corresponding 1 keV (lambda = 12.39854 Ang)
      DATA XLOGLAM1KEV / 1.0933705 /   
 
C***  INTERPOLATION TABLE FOR PART OF SEATON'S RANGE
      DATA FTAB1/1.36,1.44,1.84,2.04,2.24,2.44,2.66,2.88,3.14,3.36,3.56,
     1        3.77,3.96,4.15,4.26,4.40,4.52,4.64/
      DATA ZTAB1 / 1.0, 1.1, 1.2, 1.3, 1.4, 1.5, 1.6, 1.7, 1.8, 
     >             1.9, 2.0, 2.1, 2.2, 2.3, 2.4, 2.5, 2.6, 2.7 /

C***  INTERPOLATION FOR INFRARED RANGE > 10000 ANG
      DATA FTAB2 /1.36,  0.87,  0.60,  0.38,  0.16,  0.11,  0.12,  0.03/
      DATA XTAB2 /4.00, 4.097, 4.217, 4.342, 4.538, 4.681, 5.009, 5.301/

C***  Interpolation for IR after Moneti et al 2001: 10000-240000 ANG
      DATA FTAB3 
     >    /0.4097, 0.2804, 0.1736, 0.1108, 0.0964, 0.0923, 0.0715,
     >     0.0530, 0.0510, 0.0492, 0.0477, 0.0464, 0.0452, 0.0441,
     >     0.0431, 0.0463, 0.0628, 0.0989, 0.1454, 0.1431, 0.1250,
     >     0.1023, 0.0835, 0.0721, 0.0634, 0.0569, 0.0545, 0.0553,      
     >     0.0561, 0.0573, 0.0589, 0.0612, 0.0643, 0.0677, 0.0707, 
     >     0.0726, 0.0730, 0.0721, 0.0704, 0.0683, 0.0663, 0.0644,
     >     0.0626, 0.0610, 0.0586, 0.0561, 0.0537, 0.0515/
      DATA XTAB3 
     >    /4.000, 4.097, 4.217, 4.342, 4.398, 4.477, 4.544, 4.602, 
     >     4.653, 4.699, 4.740, 4.778, 4.813, 4.845, 4.875, 4.903, 
     >     4.929, 4.954, 4.978, 5.000, 5.021, 5.041, 5.061, 5.079,
     >     5.097, 5.114, 5.130, 5.146, 5.161, 5.176, 5.190, 5.204,
     >     5.217, 5.230, 5.243, 5.255, 5.267, 5.279, 5.290, 5.301,
     >     5.312, 5.322, 5.332, 5.342, 5.352, 5.362, 5.371, 5.380/

C***  LMC
      DATA RLMC / 3.2 /
      
C***  for SMC_BAR: special law from Gordon et al. (2003) for < 3000 Ang 
C***  for longer wavelength, the FITZPATRICK law is taken with RV=2.74
      DATA RSMCBAR / 2.74 /

C***  CARDELLI ET AL. (APJ 345, 245)
      DATA CTAB1 /0.574, 1.61/
      DATA CTAB2 /-0.527, 1.61/
      DATA CTAB3 /1., 0.17699, -0.50447, -0.02427, 0.72085, 
     >            0.01979, -0.77530, 0.32999/
      DATA CTAB4 /0., 1.41338, 2.28305, 1.07233, -5.38434, 
     >            -0.62251, 5.30260, -2.09002/
      DATA CTAB5 /1.752, -0.316, -0.104, -4.67, 0.341/
      DATA CTAB6 /-3.090, 1.825, 1.206, -4.62, 0.263/
      DATA CTAB7 /-0.04473, -5.9, -0.009779, -5.9/
      DATA CTAB8 /0.2130, -5.9, 0.1207, -5.9/
      DATA CTAB9 /-1.073, -0.628, 0.137, -0.070/
      DATA CTAB10 /13.670, 4.257, -0.420, 0.374/

C***  FITZPATRICK AND MASSA (PASP 1999)
      DATA     fitz_x0    / 4.596 /
      DATA     fitz_gamma / 0.99 /
      DATA     fitz_c3    / 3.23 /
      DATA     fitz_c4    / 0.41 /
      DATA     xcutuv / 3.703704 /
      DATA     xspluv / 3.703704 , 3.846154 / !10000/2700.0,10000/2600.0
C     nach Fitzpatrick:
      DATA     xopir / 0.0, 0.377358, 0.819672, 1.666667, 1.828153,  
     >    2.141328, 2.433090, 3.703704, 3.846154 /

C***  X-ray absorption for solar abundances
C***  Morrison R. & McCammon D., 1983, ApJ 270, 119
C***  Table 2
      DIMENSION EX(15), CX0(14), CX1(14), CX2(14)
      DATA EX  / 0.030, 0.100, 0.284, 0.400, 0.532, 0.707, 0.867, 1.303, 
     >           1.840, 2.471, 3.210, 4.038, 7.111, 8.331, 10.00 /
      DATA CX0 /  17.3,  34.6,  78.1,  71.4,  95.5, 308.9, 120.6,
     >           141.3, 202.7, 342.7, 352.2, 433.9, 629.0, 701.2 /
      DATA CX1 / 608.1, 267.9,  18.8,  66.8, 145.8,-380.6, 169.3,
     >           146.8, 104.7,  18.7,  18.7,  -2.4,  30.9,  25.2 /
      DATA CX2 /-2150.,-476.1,   4.3, -51.4, -61.1, 294.0, -47.7,
     >           -31.5, -17.0,   0.0,   0.0,  0.75,   0.0,   0.0 /

C***  THE FOLLOWING DATA ARE FOR MIHALAS' FIT OF GAUNT-BF H I (Lyman-cont)
      DATA A0,A1,A2,A3,AM1,AM2 /
     > 1.2302628,  -3.1927214E-2, 8.9105122E-4, -1.1544111E-5,
     > -0.50812150, 0.10631895 /
 
C***  Hydrogen cross section (classical, without gaunt-bf)
      SIGMATH = 7.92E-18

C**********************************************************************
C***  THE DATA SET IS RESTRICTED TO THAT WAVELENGTH RANGE
C***     FOR WHICH THE REDENING LAW IS IMPLEMENTED, 
C***     AND TO THE LIMITS OF THE BOX
C***  NOTE: JUST ONE POINT OUTSIDE EACH END OF THE INTERVAL MAY BE KEPT
C**********************************************************************

C***  No EBV value read yet (should prevent double definition of EBV)
      BEBVREAD = .FALSE. 
      
C***  DECODE Parameters from the COMMAND line
      CALL SARGC (LINE, NPAR)
      
C**   Default reddening law:
      LAW = 'SEATON'
      NEXTPAR = 'NEW'
      DO I=3, NPAR   
         CALL SARGV (LINE, I, ACTPAR)
         IF (NEXTPAR .EQ. 'RV') THEN
            READ (ACTPAR, '(BN,F20.0)',ERR=99) RV
            NEXTPAR = 'NEW'
            CYCLE
         ELSE IF (NEXTPAR .EQ. 'R_fitz') THEN
            READ (ACTPAR, '(BN,F20.0)',ERR=99) R_fitz
            NEXTPAR = 'NEW'
            CYCLE
         ELSE IF (NEXTPAR .EQ. 'R_VSMC') THEN
            READ (ACTPAR, '(BN,F20.0)',ERR=99) R_VSMC
            NEXTPAR = 'NEW'
            CYCLE
         ELSE IF (NEXTPAR .EQ. 'COLDENS') THEN
            READ (ACTPAR, '(BN,F20.0)',ERR=99) COLDENS
            EBV = COLDENS / CDPERMAG
            NEXTPAR = 'NEW'
            CYCLE
         ENDIF
C***  Cardelli law: default Rv 
         IF (ACTPAR .EQ. 'CARDELLI') THEN
            LAW = 'CARDELLI'
            RV = 3.1
            NEXTPAR = 'RV'
C***  Fitzpatrick law: default R_fitz 
         ELSE IF (ACTPAR .EQ. 'FITZPATRICK') THEN
            LAW = 'FITZPATRICK'
            R_fitz = 3.1
            NEXTPAR = 'R_fitz'
C***  LMC law (no parameter)
         ELSE IF (ACTPAR .EQ. 'LMC') THEN
            LAW = 'LMC'
         ELSE IF (ACTPAR .EQ. 'SMC') THEN
            LAW = 'SMC'
            R_VSMC = 2.7
            NEXTPAR = 'R_VSMC'
         ELSE IF (ACTPAR .EQ. 'SMC_BAR') THEN
            LAW = 'SMC_BAR'
         ELSE IF (ACTPAR .EQ. 'SEATON') THEN
C            just skip ...
         ELSE IF (ACTPAR .EQ. 'EBV') THEN
C            just skip ...
         ELSE IF (ACTPAR .EQ. 'COLDENS') THEN
            NEXTPAR = 'COLDENS'
         ELSE IF (.NOT. CHRINSTR(ACTPAR(:1),'+-.0123456789')) THEN
            GOTO 96
         ELSE
C***  Lonely parameter just means EBV (must be a number!)
            IF (BEBVREAD) GOTO 98
            BEBVREAD = .TRUE.
            READ (ACTPAR, '(BN,F20.0)',ERR=99) EBV 
            COLDENS = EBV * CDPERMAG
         ENDIF
      ENDDO

      IDAT = NDAT(ISET)
      ISYM = ISYMBOL(ISET)

C***  EXPANSION OF DATASET SUPPRESSED IF DISCRETE PLOTSYMBOLS CHOSEN
      NOEXPAND = .FALSE.
cc      NOEXPAND = ISYM .NE. 5 .AND. ISYM .NE. 7 
cc     >      .AND. ISYM .NE. 9 .AND. ISYM .NE. 10

C***  COPYING OF THE DATA
      DO 30 I=1, IDAT
      X1(I)=X(I,ISET)
      Y1(I)=Y(I,ISET)
   30 CONTINUE

      IF (IDAT .LE. 1 .OR. NOEXPAND) GOTO 6

C***  CHECK MONOTONIC INCREASING ORDER
      DO 1 I=2, IDAT       
      IF ((X1(I)-X1(I-1))*(X1(IDAT)-X1(1)) .LT. .0) THEN
         WRITE (6,61) I, X1(I), I-1, X1(I-1)
   61 FORMAT (' >> DATA POINTS NOT IN MONOTONIC ORDER',
     >        ' - EXPANSION ABORTED', 
     >  /, ' >> X(', I4, ')=', G12.4, 5X, ' X(', I4, ')=', G12.4)
         GOTO 6
         ENDIF 
    1 CONTINUE

      N = 1000
      IOLD = IDAT

C***  LOOP **************************************
   2  IF (IDAT .GE. N) GOTO 6

C***  FIND LARGEST DISTANCE (L1,L1+1) 
        D1=0.
        DO 3 L=1,IDAT-1
          D2=ABS(X1(L)-X1(L+1))
          IF (D2 .LT. D1) GOTO 3
          L1=L
          D1=D2
3       CONTINUE

C*** HOCHSCHIEBEN DER ELEMENTE AB L1+1 
        DO 5 L=IDAT,L1+1,-1
           Y1(L+1)=Y1(L)
           X1(L+1)=X1(L)
5       CONTINUE

C*** INTERPOLIEREN 
        X1(L1+1)=0.5*(X1(L1)+X1(L1+2))
        Y1(L1+1)=0.5*(Y1(L1)+Y1(L1+2))
        IDAT=IDAT+1
      GOTO 2
C***  END-OF-LOOP ***************************
    6 CONTINUE 

      IF (IDAT .GT. IOLD .AND. .NOT. MPACTIVE)  WRITE (6,66) IDAT
   66    FORMAT (/,'  DATASET IS EXPANDED TO', I5, ' DATA POINTS')

C**********************************************************************
C***      REDDENING CORRECTION
C**********************************************************************


      IF (LAW .NE. 'LMC' .AND. LAW .NE. 'SMC'
     >    .AND. LAW .NE. 'CARDELLI' .AND. LAW .NE. 'SMC_BAR' .AND.
     >    LAW .NE. 'SEATON' .AND. LAW .NE. 'FITZPATRICK') THEN
        WRITE (*,*) 'Invalid Version for Extinction law'
        WRITE (*,*) 'Version=', LAW
        STOP 'ERROR in Subr. EXTINCT'
      ENDIF

C***  Loop over all data points
      DO 11 I=1,IDAT

C***  Skip X-ray branch if lambda > 911.7634 Ang
      IF (X1(I) .GT. 2.959882) GOTO 100

C***  X-ray branch (same for all reddening-law keywords)
      XLOGE = XLOGLAM1KEV - X1(I) 
      E = 10.**XLOGE

C***  No Reddening for wavelength shorter than tabulated range 
C***    -> leave flux unreddened       
      IF (E .GT. EX(15)) THEN
         CYCLE

C***  Between Lyman edge and the HeI edge (911 - 504 A) we calculate
C***     the cross section like in the PoWR code 
C***     i.e. hydrogenic * gaunt-bf
      ELSE IF (E .LT. EX(1) .AND. X1(I) .GT. 2.70265) THEN
         XX = 10.**X1(I) / 911.76  
         XINV = 1. / XX
         GAUNT=A0 + XX*(AM1+XX*AM2) + (A1+(A2+A3*XINV)*XINV)*XINV
         SIGMA = SIGMATH * XX*XX*XX * GAUNT

C***  Between HeI edge and the tabulated Xray law (504 - 413 A) the 
C***  tabulated law is extrapolated 
      ELSE IF (E .LT. EX(1) .AND. X1(I) .LE. 2.70265) THEN
       SIGMA = ((CX0(1) / E + CX1(1)) / E + CX2(1)) / E * 1.E-24

C***  Apply the tabulated absorption
      ELSE
       CALL LIPO_IND (IX, NB, E, EX, 15)
       SIGMA = ((CX0(IX) / E + CX1(IX)) / E + CX2(IX)) / E * 1.E-24
      ENDIF 

C***  opt. depth TAU = SIGMA * COLDENs (Hydrogen column density)
      Y1(I) = Y1(I) -  SIGMA * COLDENS * 0.4342944

      CYCLE

C***  Non-Xray branch
  100 CONTINUE
C***  Z IS IN    1. / mu-m
      Z=10.**(4.-X1(I))

C****************************************************************
C***  CARDELLI law  
C***  Note: originally defined for lambda > 3.33mu
C***     for longer lambda, the IR law is used
C***     this limit was changed to 2.44mu (Z > 0.41) for smoother
C***     transition to Moneti's law (2-Dec-2015, wrh)
C****************************************************************

      IF (LAW .EQ. 'CARDELLI' .AND. Z .GE. 0.41) THEN
        XCAR = Z
        IF (XCAR .LT. 3.3) THEN
          IF (XCAR .LT. 1.1) THEN
            ACAR = CTAB1(1) * XCAR**CTAB1(2)
            BCAR = CTAB2(1) * XCAR**CTAB2(2)
          ELSE
            YCAR = XCAR - 1.82
            CALL POLYNOM(ACAR, YCAR, CTAB3, 8)
            CALL POLYNOM(BCAR, YCAR, CTAB4, 8)
          ENDIF
        ELSE IF (XCAR .LT. 8.0) THEN
          IF (XCAR .LT. 5.9) THEN
            FACAR = 0.
            FBCAR = 0.
          ELSE
            FACAR = CTAB7(1)*(XCAR+CTAB7(2))**2. + 
     >           CTAB7(3)*(XCAR+CTAB7(4))**3.
            FBCAR = CTAB8(1)*(XCAR+CTAB8(2))**2. + 
     >           CTAB8(3)*(XCAR+CTAB8(4))**3.
          ENDIF
          ACAR = FACAR + CTAB5(1) + CTAB5(2)*XCAR + 
     >      CTAB5(3)/((XCAR+CTAB5(4))**2. + CTAB5(5))
          BCAR = FBCAR + CTAB6(1) + CTAB6(2)*XCAR + 
     >      CTAB6(3)/((XCAR+CTAB6(4))**2. + CTAB6(5))
        ELSE IF (XCAR .LE. 10.) THEN
          XXCAR = XCAR - 8.
          CALL POLYNOM(ACAR, XXCAR, CTAB9, 4)
          CALL POLYNOM(BCAR, XXCAR, CTAB10, 4)
        ELSE
C***  Here the bluemost formula is extrapolated
C          WRITE (*,*) 'Warning : Wavelength not in valid range (1000A)'
C          WRITE (*,*) 'LAW = CARDELLI'
          XXCAR = XCAR - 8.
          CALL POLYNOM(ACAR, XXCAR, CTAB9, 4)
          CALL POLYNOM(BCAR, XXCAR, CTAB10, 4)
        ENDIF
C***  NOTE : The Cardelli Function is 1. at V-Band and NOT 3.1 as the
C***           other formulae
        F = RV * ACAR + BCAR

c========================================================
C***   Fitzpatrick-Law, adopted after his IDL-Routine...
C***     lang-wave limit adopted at 5mu (Z=0.2)
C***     -- this limit changed to 4mu (Z=0.25) for better 
C***        transition to Moneti
c========================================================

        ELSE IF ((LAW .EQ. 'FITZPATRICK' .AND. Z .GT. 0.25  ) .OR.
     >   (LAW .EQ. 'SMC' .AND. ( Z .LT. 1.83 .AND. Z .GT. 0.2 )) .OR.
     >   (LAW .EQ. 'SMC_BAR' .AND. 
     >   ( Z .LE. 3.375 .AND. Z .GT. 0.2 ))) THEN
           IF (LAW .EQ. 'SMC')  R_fitz = R_VSMC    !  RV = R_VSMC
           IF (LAW .EQ. 'SMC_BAR')  R_fitz = RSMCBAR   !  RV = R_V of SMC
           fitz_c2    = -0.824 + 4.717/R_fitz 
           fitz_c1    =  2.030 - 3.007*fitz_c2
              yspluv(1) = fitz_c1 + fitz_c2*xspluv(1) +
     >             (fitz_c3*xspluv(1)**2/((xspluv(1)**2-fitz_x0**2)**2 + 
     >             (xspluv(1)*fitz_gamma)**2)) + R_fitz
              yspluv(2) = fitz_c1 + fitz_c2*xspluv(2) +
     >             (fitz_c3*xspluv(2)**2/((xspluv(2)**2-fitz_x0**2)**2 + 
     >             (xspluv(2)*fitz_gamma)**2)) + R_fitz
           IF (Z .GE.  xcutuv) THEN
              yuv = fitz_c1 +  fitz_c2*Z
              yuv = yuv + fitz_c3*Z**2/
     >             ((Z**2-fitz_x0**2)**2 + (Z*fitz_gamma)**2)
              IF (Z .GT. 5.9) THEN
                 yuv=yuv+ fitz_c4*(0.5392*(Z-5.9)**2+
     >                0.05644*(Z-5.9)**3)
              ENDIF
              yuv = yuv + R_fitz
C     Da Fitzpatrick und Massa in E(lambda-V)\E(B-V) rechnen, Cardelli jedoch in 
C     A(lambda)\A(V) ist nach Cardelli et al die Umrechnung gegeben durch
C     A(lambda)\A(V) = FM(x)/R_V + 1 aber die wird hier nicht gebraucht.
               F = YUV
           ELSE IF (Z .LT. xcutuv) THEN
C     Vorbereiten der Kooeffizienten fuer die spline interpolation...
              yopir(1) = 0.0
              yopir(2) = 0.26469*R_fitz/3.1 ! Normierung auf R=3.1 im IR
              yopir(3) = 0.82925*R_fitz/3.1 ! Normierung auf R=3.1 im IR
              yopir(4) = -4.22809e-01 + 1.00270*R_fitz + 
     >             2.13572e-04*R_fitz**2
              yopir(5) = -5.13540e-02 + 1.00216*R_fitz - 
     >             7.35778e-05*(R_fitz)**2
              yopir(6) = 7.00127e-01 + 1.00184*R_fitz - 
     >             3.32598e-05*(R_fitz)**2
              yopir(7) = 1.19456     + 1.01707*R_fitz - 
     >             5.46959e-03*(R_fitz)**2 + 7.97809e-04*(R_fitz)**3 - 
     >             4.45636e-05*(R_fitz)**4
              yopir(8) = yspluv(1)
              yopir(9) = yspluv(2)
              call fspline (F , Z, yopir,xopir, 9)
           ENDIF


C****************************************************************
C***  LMC law + SMC law
C***  Note: for lambda > 5464 Ang, the default (SEATON) law is used
C****************************************************************

      ELSE IF (LAW .EQ. 'LMC' .AND. Z .GE. 1.83) THEN
C*** Note: Ian's formula is bad for Lambda > 5464 Ang --> galactic law taken
c***          F = ((1.86 - 0.48 * Z) * Z - 0.1) * Z
C***    Lambda > 3636 Ang
        IF (Z .LE. 2.75) THEN
          ZZ = Z - 1.83
          F = RLMC + ZZ * (2.04 + 0.094*ZZ)
C***    Lambda < 3636 Ang
        ELSE
          ZZ = Z-4.557
          F = RLMC - 0.236 + Z * (0.462 + 0.105*Z) + 
     >        0.454/(ZZ*ZZ + 0.293)
        ENDIF

      ELSE IF (LAW .EQ. 'SMC' .AND. Z .GE. 1.83) THEN
C*** Note: Ian's formula is bad for Lambda > 5464 Ang --> galactic law taken
c***          F = ((1.86 - 0.48 * Z) * Z - 0.1) * Z
C***    Lambda > 3636 Ang
        IF (Z .LE. 2.75) THEN
          ZZ = Z - 1.83
          F = R_VSMC + ZZ * (2.04 + 0.094*ZZ)
C***    Lambda < 3636 Ang
        ELSE
          ZZ = Z-4.557
          F = R_VSMC - 0.236 + Z * (0.462 + 0.105*Z) + 
     >        0.454/(ZZ*ZZ + 0.293)
        ENDIF

C****************************************************************
C***  new law for the SMC bar by Gordon et al. (2003)
C***  Note: for lambda > 21980 Ang, the default (SEATON) law is used
C****************************************************************

      ELSE IF (LAW .EQ. 'SMC_BAR' .AND. Z .GT. 3.375) THEN
         IF ( Z .LT. 5.9) THEN
         FZ = 0
      ELSE
         FZ = 0.5392 * (Z - 5.9)**2 + 0.05644 * (Z - 5.9)**3
      ENDIF
      F = RSMCBAR - 4.959 + 2.264*Z + 
     >      0.389*Z*Z/((Z*Z - 21.16)**2 + Z*Z) + 0.461*FZ
      
C****************************************************************
C***  SEATON law (default)
C***  Note: for lambda > 33333 Ang, the default law is used
C****************************************************************
      
      ELSE

C***  RANGE 1000 - 10000 ANGSTROEM 
        IF (X1(I) .LT. 4.) THEN
          IF (Z .LT. 2.7) THEN
             CALL FSPLINE (F, Z, FTAB1, ZTAB1, 18)
          ELSE IF (Z .LE. 3.65) THEN
             F=1.56+1.048*Z+1.01/((Z-4.6)**2+0.28)
   
          ELSE IF (Z .LE. 7.14) THEN
             F=2.29+0.848*Z+1.01/((Z-4.6)**2+0.28)
          ELSE
             F=16.17+Z*(0.2975*Z-3.2)
          ENDIF

        ELSE   
C***      redmost reddening law (Moneti or extrapolation)
C***      Since the Moneti Table refers A_V, we scale with R_V
          RVMONETI = 3.1
          IF (LAW .EQ. 'CARDELLI') THEN
C***          the following enhancement of the deviation from RV=3.1
C***          is arbiitrary, just in order to make a smooth transition 
C***          of the Monati law at 2.44mu 
              RVMONETI = 3.1 + (RV - 3.1) * 1.4
          ELSEIF (LAW .EQ. 'FITZPATRICK') THEN
              RVMONETI = R_fitz
          ELSEIF (LAW .EQ. 'LMC') THEN
              RVMONETI = RLMC
          ELSEIF (LAW .EQ. 'SMC') THEN
              RVMONETI = R_VSMC
          ELSEIF (LAW .EQ. 'SMC_BAR') THEN
              RVMONETI = RSMCBAR
          ENDIF

          IF (X1(I) .LT. XTAB3(48)) THEN
C*** The out-commented lines refer to Abbott, Telesco & Wolff 
c        ELSE IF (X1(I) .LT. XTAB2(8)) THEN

C***  RANGE 10 000 - 200 000 ANGSTROEM
c        CALL FSPLINE (F, X1(I), FTAB2, XTAB2, 8) 

C***  Range 10 000 - 240 000 ANG after Moneti
            CALL FSPLINE (F, X1(I), FTAB3, XTAB3, 48)
            F = F * RVMONETI
  
          ELSE
C***  > 240 000 ANG: extrapolation proportional 1/Lambda^2
            F = RVMONETI * FTAB3(48) * 10**(2 * (XTAB3(48)-X1(I)))
          ENDIF

        ENDIF

      ENDIF
C***  End branching the reddening laws

      Y1(I)=Y1(I)-0.4*F*EBV
11    CONTINUE
C***  End Loop over all data points

C***  Copy data back
      NDAT(ISET) = IDAT
      DO J=1, IDAT
         X(J,ISET) = X1(J)
         Y(J,ISET) = Y1(J)
      ENDDO

      RETURN
      
C***  ERRORS      
   96 WRITE(6,'(//,A)') '*** ERROR: Invalid keyword'
      GOTO 97
      
   98 WRITE(6,'(//,A)') '*** ERROR: Double definition of EBV'
      GOTO 97
      
   99 WRITE(6,'(//,A)') 'ERROR: INVALID DATA FORMAT IN COMMAND LINE'
      GOTO 97
      
   97 WRITE(6,*) 'The error occured in the following line: '
      WRITE(6,*) LINE
      STOP '*** ERROR in Subr. EXTINCT'

      END

extint.f/       1553528659  5006  320   100644  2463      `
      SUBROUTINE EXTINT (X, Y, X1, Y1, NDAT, NSET, NDATMAX, NSETMAX, 
     >                    B, C, ISYMBOL, NPEN, ICOLOR, FNAME, MPACTIVE)

C**********************************************************************
C***        SHELL FOR INTERACTIVE USE OF EXTINCT
C***        CALLED FROM: WRPLOT
C**********************************************************************

      DIMENSION X(NDATMAX,NSETMAX), Y(NDATMAX,NSETMAX)
      DIMENSION X1(NDATMAX), Y1(NDATMAX)
      DIMENSION B(6), C(6)
      DIMENSION NDAT(NSETMAX), ISYMBOL(NSETMAX), NPEN(NSETMAX)
      DIMENSION ICOLOR(NSETMAX)
      CHARACTER CHAR*1
      LOGICAL MPACTIVE
 
C**********************************************************************
C***       INPUT E(B-V)
C**********************************************************************
6     WRITE (6,'(''$'',A)') 
     >     '0 = RETURN TO MAIN PROGRAM OR INPUT  E(B-V) = '
      READ (5,*) EBV
      IF (EBV .EQ. 0) RETURN

C**********************************************************************
C***       INPUT OF DATASET-NUMBER
C**********************************************************************
      IF (NSET .EQ. 1) THEN
        ISET = 1
        ELSE 
 1        WRITE(6,*) 'NUMBER OF OLD DATA-SET (EXISTING:',NSET,'): '
          READ (5,*) ISET
          IF (ISET .LT. 1 .OR. ISET .GT. NSET) GOTO 1 
        ENDIF

      CALL EXTINCT (X, Y, X1, Y1, NDAT, IDAT, ISET, NDATMAX, 
     >              NSETMAX, B, C, EBV, ISYMBOL, MPACTIVE)

C**********************************************************************
C***  COPY RESULTS INTO A DATA-SET                                  ***    
C**********************************************************************

20    WRITE(6,'(''$'',A)') 'OVERWRITE OLD DATA-SET NR. (Y/N) /N/ '
      READ(5,'(A)') CHAR
      IF (CHAR .EQ. 'Y' .OR. CHAR .EQ. 'y') THEN
         I2=ISET
         ELSE
         IF (NSET .GE. NSETMAX) THEN
            WRITE(6,*) 
     >       '*** ERROR: NO MORE DATASETS FREE - NEW DATA NOT SAVED'
            GOTO 6
            ENDIF
         NSET=NSET+1
         I2=NSET
         ENDIF

      ISYMBOL(I2) = ISYMBOL(ISET)
      NPEN(I2)    = NPEN(ISET)
      ICOLOR(I2)  = ICOLOR(ISET)
      NDAT(I2)    = IDAT
      DO 16 I=1, IDAT
         X(I,I2)  = X1(I)
         Y(I,I2)  = Y1(I)
16    CONTINUE

C***  OPTIONAL SAVING OF NEW DATA ON DISK FILE
      CALL SAVESET (X(1,I2), Y(1,I2), NDAT(I2), ISYMBOL(I2), NPEN(I2),
     >              FNAME)

      GOTO 6
      END

fcubic.f/       1553528659  5006  320   100644  854       `
      SUBROUTINE FCUBIC (FX,XX,Y,X,N)
C *****************************************************************************
C --- TEST VERSION ---
C***  CUBIC INTERPOLATION (LAGRANGE POLYNIMIAL)
C***  X(I), Y(I): INTERPOLATION TABLE
C***  XX = ACTUAL ARGUMENT
C***  FX = RESULTING FUNCTION VALUE
C******************************************************************************

      DIMENSION X(N), Y(N), T(4)

C***  FIND INDEX INTERVAL (L-1, L) CONTAINING XX
      DO 1 I=2,N
      L=I
      IF ((XX-X(L-1))*(XX-X(L)) .LE. .0) GOTO 2
    1 CONTINUE
      STOP 'ERROR IN FCUBIC'

    2 CONTINUE

      L=MAX0 (0, L-2)
      L=MIN0 (L, N-4)

      DO 3 I=1,4
       T(I)=Y(L+I)
       IF (I .EQ. 1) GOTO 3
        DO 4 J=1,I-1
         M=I-J
    4    T(M)=T(M+1)+(XX-X(L+I))/(X(L+I)-X(L+M))*(T(M+1)-T(M))
    3  CONTINUE

      FX=T(1)
 
      RETURN
      END
findflex.f/     1553528659  5006  320   100644  1259      `
      SUBROUTINE FINDFLEX
C**********************************************************************
C***  Program to convert WRPLOT-Files from FLEX-XYTABLE to simple XY-Table
C***      (i.e. only one data pair per row)
C***********************************************************************
      CHARACTER FILENAME1*252, LINE*80
      OPEN (1, FILE='alldatafiles')
      OPEN (2, FILE='flexfiles')
      OPEN (3, FILE='noflexfiles')

    1 CONTINUE
      READ (1,'(A)', END=99) FILENAME1

      OPEN (4, FILE=FILENAME1)
CC      print *, 'File opened : ', filename1(:idx(filename1))

C***  SEARCH FOR MULTICOLUMN DATA ENTRIES
    4 READ (4, '(A)', END=3) LINE
      IF (LINE(:2) .NE. 'N=' .AND. LINE(:3) .NE. ' N=') GOTO 4
C***  Beginning of data table encountered
    5 READ (4, '(A)', END=3) LINE
      IF (LINE(:6) .EQ. 'FINISH' .OR. LINE(:7) .EQ. ' FINISH') GOTO 4
      IF (LINE(1:1) .EQ. '*') GOTO 5
      CALL SARGC (LINE, NPAR)
      IF (NPAR .GT. 2) GOTO 2
      GOTO 5

C***  Multicolumn entry found:
    2 WRITE (2, '(A)') FILENAME1(:IDX(FILENAME1))
      CLOSE (4)
      GOTO 1

C***  EOF reached, no multicolumn entry found
    3 WRITE (3, '(A)') FILENAME1(:IDX(FILENAME1))
      CLOSE (4)
      GOTO 1

   99 CONTINUE
      STOP 'O.K.'
      END

findndec.f/     1553528659  5006  320   100644  752       `
      SUBROUTINE FINDNDEC (X1, X2, NDEC)
C********************************************************************
C***  FIND NDEC = NUMBER OF NON-ZERO DECIMAL DIGITS BEHIND THE
C***               DECIMAL POINT, OF BOTH X1 AND X2
C***  THIS IS USED FOR THE AXIS DESCRIPTION BY SUBR. PLOTBOX (WRPLOT)
C***  RESTRICTED TO A MAXIMUM OF 5
C********************************************************************
      CHARACTER*20 STRING

      WRITE (STRING, '(F20.5)') X1
      DO I=20, 15, -1
        N1 = I - 15
        IF (STRING(I:I) .NE. '0') EXIT 
      END DO
      
      WRITE (STRING, '(F20.5)') X2
      DO I=20, 15, -1
        N2 = I - 15
        IF (STRING(I:I) .NE. '0') EXIT 
      END DO
      
      NDEC = MAX (N1, N2)

      RETURN
      END
flex.f/         1553528659  5006  320   100644  1682      `
      SUBROUTINE FLEX
C**********************************************************************
C***  Program to convert WRPLOT-Files from FLEX-XYTABLE to simple XY-Table
C***      (i.e. only one data pair per row)
C***********************************************************************
      CHARACTER FILENAME1*252, LINE*80, X*80, Y*80
      OPEN (1, FILE='flexfiles')

    1 CONTINUE
      READ (1,'(A)', END=99) FILENAME1

C***  Kanal 4 = Inputfile
      OPEN (4, FILE=FILENAME1(:IDX(FILENAME1))//'.flex')
C***  Kanal 3 = Outputfile
      OPEN (3, FILE=FILENAME1(:IDX(FILENAME1)))
      print *, 'File opened : ', filename1(:idx(filename1))

C***  SEARCH FOR MULTICOLUMN DATA ENTRIES
    4 READ  (4, '(A)', END=3) LINE
      WRITE (3, '(A)') LINE(:IDX(LINE))
      IF (LINE(:2) .NE. 'N=' .AND. LINE(:3) .NE. ' N=') GOTO 4
C***  Beginning of data table encountered
    5 READ (4, '(A)', END=3) LINE
      IF (LINE(:6) .EQ. 'FINISH' .OR. LINE(:7) .EQ. ' FINISH') THEN
        WRITE (3, '(A)') LINE(:IDX(LINE))
        GOTO 4
        ENDIF
      IF (LINE(1:1) .EQ. '*') GOTO 5
      CALL SARGC (LINE, NPAR)
      IF (NPAR .GT. 2) THEN
        CALL SARGV (LINE, 1, X)
        CALL SARGV (LINE, 2, Y)
        WRITE (3, '(A)') X(:IDX(X))//' '//Y(:IDX(Y))
        CALL SARGV (LINE, 3, X)
        CALL SARGV (LINE, 4, Y)
        WRITE (3, '(A)') X(:IDX(X))//' '//Y(:IDX(Y))
        IF (NPAR .GT. 4) THEN
          CALL SARGV (LINE, 5, X)
          CALL SARGV (LINE, 6, Y)
          WRITE (3, '(A)') X(:IDX(X))//' '//Y(:IDX(Y))
          ENDIF        
        ENDIF
      GOTO 5

C***  EOF reached 
    3 CLOSE (3)
      CLOSE (4)
      GOTO 1

   99 CONTINUE
      STOP 'O.K.'
      END
fraclen.f/      1553528659  5006  320   100644  2066      `
         SUBROUTINE FRACLEN (SIZE, STRPAR, XFRACLEN)
C*************************************************************************
C***  Estimating the length of a fraction
C*************************************************************************

C***  active graphic driver
      COMMON / COMACT / ACTDRIV
      CHARACTER ACTDRIV*7
      CHARACTER STRPAR*(*), UPPER*250, LOWER*250
      CHARACTER*2 TS1, TS2
      TS1 = CHAR(92) // CHAR(124)
      TS2 = CHAR(92) // CHAR(125)

C********** CALCOMP BRANCH ******************************************
      IF (ACTDRIV .EQ. 'CALCOMP') THEN
         PRINT *, 'FRACTIONS NOT IMPLEMENTED WITH CALCOMP DRIVER'
         STOP 'ERROR IN SUBROUTINE FRACLEN'
         ENDIF

      LENGTH = IDX(STRPAR)
      IF (LENGTH .EQ. 0) RETURN
      LAST = LENGTH

C***  SEARCH FOR END OF NOMINATOR
      CALL STRPOS (TS1, STRPAR, IPOS)
      IF (IPOS .NE. 0) THEN
           LAST = IPOS - 1
           UPPER = STRPAR(:LAST)
           STRPAR = STRPAR(LAST+3:)
           ELSE
           PRINT *, 'SYNTAX ERROR IN FRACTION ENVIRONMENT: MISSING ',TS1
           STOP 'ERROR IN SUBROUTINE FRACLEN'
           ENDIF

C***  SEARCH FOR END OF DENOMINATOR
      CALL STRPOS (TS2, STRPAR, IPOS)
      IF (IPOS .NE. 0) THEN
           LAST = IPOS - 1
           LOWER = STRPAR(:LAST)
           STRPAR = STRPAR(LAST+3:)
           ELSE
           PRINT *, 'SYNTAX ERROR IN FRACTION ENVIRONMENT: MISSING ',TS2
           STOP 'ERROR IN SUBROUTINE FRACTION'
           ENDIF


      ACTSIZE = SIZE * 0.8
C***  The actual text attributes are left from printing the previous string 
      CALL PREATTRIB (UPPER)
      IF (ACTDRIV .EQ. 'PSOWN') THEN
        CALL PS_TEXTLEN (DXUP , ACTSIZE, UPPER)
        CALL PREATTRIB (LOWER)
        CALL PS_TEXTLEN (DXLOW, ACTSIZE, LOWER)
      ELSE IF (ACTDRIV .EQ. 'X11OWN') THEN
        CALL  X_TEXTLEN (DXUP , ACTSIZE, UPPER)
        CALL PREATTRIB (LOWER)
        CALL  X_TEXTLEN (DXLOW, ACTSIZE, LOWER)
      ENDIF

      XFRACLEN = AMAX1(DXUP, DXLOW)

      CALL PREATTRIB (STRPAR)

      RETURN

      END
fraction.f/     1553528659  5006  320   100644  3293      `
      SUBROUTINE FRACTION (XPOS, YCM, SIZE, STRPAR, ANGLE)
C*************************************************************************
C***  PLOTTING A FRACTION
C*************************************************************************

C***  active graphic driver
      COMMON / COMACT / ACTDRIV
      CHARACTER ACTDRIV*7
      CHARACTER STRPAR*(*), UPPER*250, LOWER*250

      CHARACTER*2 TS1, TS2
      TS1 = CHAR(92) // CHAR(124)
      TS2 = CHAR(92) // CHAR(125)

C***  ERROR *****************
      IF (ANGLE .NE. .0) THEN
         PRINT *, 'FRACTIONS ONLY IMPLEMENTED IN HORIZONTAL ORIENTATION'
         STOP 'ERROR IN SUBROUTINE FRACTION'
         ENDIF
C********** CALCOMP BRANCH ******************************************
      IF (ACTDRIV .EQ. 'CALCOMP') THEN
         PRINT *, 'FRACTIONS ONLY IMPLEMENTED IN HORIZONTAL ORIENTATION'
         STOP 'ERROR IN SUBROUTINE FRACTION'
         ENDIF

      LENGTH = IDX(STRPAR)
      IF (LENGTH .EQ. 0) RETURN
      LAST = LENGTH

C***  SEARCH FOR END OF NOMINATOR
      CALL STRPOS (TS1, STRPAR, IPOS)
      IF (IPOS .NE. 0) THEN
           LAST = IPOS - 1
           UPPER = STRPAR(:LAST)
           STRPAR = STRPAR(LAST+3:)
           ELSE
           PRINT *, 'SYNTAX ERROR IN FRACTION ENVIRONMENT: MISSING ',TS1
           STOP 'ERROR IN SUBROUTINE FRACTION'
           ENDIF

C***  SEARCH FOR END OF DENOMINATOR
      CALL STRPOS (TS2, STRPAR, IPOS)
      IF (IPOS .NE. 0) THEN
           LAST = IPOS - 1
           LOWER = STRPAR(:LAST)
           STRPAR = STRPAR(LAST+3:)
           ELSE
           PRINT *, 'SYNTAX ERROR IN FRACTION ENVIRONMENT: MISSING ',TS2
           STOP 'ERROR IN SUBROUTINE FRACTION'
           ENDIF


      YUP  = YCM + 0.8 * SIZE
      YLOW = YCM - 0.8 * SIZE
C***  Hoehe des Bruchstrichs
      YB = YCM + 0.4 * SIZE
      ACTSIZE = SIZE * 0.8
C***  The actual text attributes are left from printing the previous string 
      CALL PREATTRIB (UPPER)
      IF (ACTDRIV .EQ. 'PSOWN') THEN
        CALL PS_TEXTLEN (DXUP , ACTSIZE, UPPER)
        CALL PREATTRIB (LOWER)
        CALL PS_TEXTLEN (DXLOW, ACTSIZE, LOWER)
      ELSE IF (ACTDRIV .EQ. 'X11OWN') THEN
        CALL  X_TEXTLEN (DXUP , ACTSIZE, UPPER)
        CALL PREATTRIB (LOWER)
        CALL  X_TEXTLEN (DXLOW, ACTSIZE, LOWER)
      ENDIF
      DDX = DXUP - DXLOW
      FRACLEN = AMAX1(DXUP, DXLOW)
      IF (DDX .GT. .0) THEN
        XUP  = XPOS
        XLOW = XPOS + 0.5 * DDX
        ELSE
        XUP  = XPOS - 0.5 * DDX
        XLOW = XPOS
        ENDIF

C********** PSOWN BRANCH ******************************************
      IF (ACTDRIV .EQ. 'PSOWN') THEN
        CALL PS_SYMBL (XUP , YUP , ACTSIZE, UPPER, ANGLE)
        CALL PS_PLOT (XPOS,         YB, 3)
        CALL PS_PLOT (XPOS+FRACLEN, YB, 2)
        CALL PS_SYMBL (XLOW, YLOW, ACTSIZE, LOWER, ANGLE)
      
C********** X11OWN BRANCH ******************************************
      ELSE IF (ACTDRIV .EQ. 'X11OWN') THEN
        CALL  X_SYMBL (XUP , YUP , ACTSIZE, UPPER, ANGLE)
        CALL  X_PLOT (XPOS,         YB, 3)
        CALL  X_PLOT (XPOS+FRACLEN, YB, 2)
        CALL  X_SYMBL (XLOW, YLOW, ACTSIZE, LOWER, ANGLE)
      
      ELSE
        STOP 'ERROR IN MYSYMBL: UNKNOWN DRIVER'
      ENDIF

      XPOS = XPOS + FRACLEN
      CALL PREATTRIB (STRPAR)

      RETURN

      END

fspline.f/      1553528659  5006  320   100644  3471      `
      SUBROUTINE FSPLINE (FX,XX,Y,X,N)
C***********************************************************************
C***  CUBIC INTERPOLATION WITH FIXED DERIVATIVES AT THE MESH POINTS
C***  THESE DERIVATIVES ARE CALCULATED BY LINEAR I5TERPOLATION BETWEEN
C***  NEIGHBOURING POINTS
C***  X(L) = GRID OF MESH POINTS
C***  Y(L) = FUNCTION TO BE INTERPOLATED
C***  P1,P2,P3,P4 = RESULTING COEFFICIENTS
C***  EVALUATION OF THE INTERPOLATED VALUE Z(X) : 
C***  FX = P1*(XX-X(L-1))**3 + P2*(XX-X(L-1))
C***                + P3*(X(L)-XX)**3 + P4*(X(L)-XX)
C***  THE COEFFICIENT MATRIX H HAS BEEN INVERTED ANALYTICALLY
C***********************************************************************
 
      DIMENSION Y(N), X(N)
 
C***  FIND INDEX ONTERVAL (L, L-1) CONTAINING XX

      DO 20 I=2, N
      L = I
      IF ((XX-X(L-1))*(XX-X(L)) .LE. .0) GOTO 21
   20 CONTINUE
      STOP 'ERROR IN FSPLINE'
   21 CONTINUE 

C***  SET UP THE COEFFICIENT MATRIX
      D1 = 1. / (X(L) - X(L-1))
      D2 = D1 * D1
      D3 = D1 * D2
      D23 = D2 / 3.
      H11 = D3
      H12 = -D3
      H13 = D23
      H14 = 2. * D23
      H21 = -D1
      H22 = 2. * D1
      H23 = -0.333333333333333
      H24 = -0.666666666666666
      H31 = -D3
      H32 = D3
      H33 = -2. * D23
      H34 = -D23
      H41 = 2. * D1
      H42 = -D1
      H43 = 0.666666666666666
      H44 = 0.333333333333333
C***  FOR THE BOUNDARY INTERVALS THE DERIVATIVE CANNOT EXTEND OVER THE BOUNDARY
      LA = MAX0(L-2,1)
      LB = MIN0(L+1,N)
C***  FUNCTION TO BE INTERPOLATED: ZRAY
      F1 = Y(L-1)
      F2 = Y(L)
 
      IF (.TRUE.) THEN
      F3 = (Y(L)-Y(LA)) / (X(L)-X(LA))
      F4 = (Y(LB)-Y(L-1)) / (X(LB)-X(L-1))

      ELSE
C***  Neue Version wrh 16-May-2002 13:39:29
C***  Statt der zentrierten Ableitung werden gewichtete Mittel der
C***  Ableitungen der angrenzenden Intervalle genommen. Das entspricht
C***  der Ableitung eines Parabel-Fits durch drei Punkte.

      FS0 = (Y(L) - Y(L-1)) / (X(L) - X(L-1))
      IF (L .EQ. 2) THEN
         F3 = FS0
      ELSE
         P = (X(L) - X(L-1)) / (X(L) - X(L-2))
         FSM = (Y(L-1) - Y(L-2)) / (X(L-1) - X(L-2))
         F3 = P * FSM + (1.-P) * FS0
      ENDIF
      IF (L .EQ. N) THEN
         F4 = FS0
      ELSE
         P = (X(L) - X(L-1)) / (X(L+1) - X(L-1))
         FSP = (Y(L+1) - Y(L)) / (X(L+1) - X(L))
         F4 = P * FSP + (1.-P) * FS0
      ENDIF
      ENDIF



C***  SET TRUE FOR MONO OPTION
      IF (.FALSE.) THEN

       S4 = ( Y(L) - Y(L-1) ) / ( X(L) - X(L-1) )
C***   We are not in the first interval:
       IF (LA .NE. L-2) THEN
         S3 = S4
       ELSE
         S3 = ( Y(L-1) - Y(L-2) ) / ( X(L-1) - X(L-2) )
       ENDIF
C***   We are not in the last interval:
       IF (LB .NE. L+1) THEN
          S5 = S4
       ELSE
          S5 = ( Y(L+1) - Y(L) ) / ( X(L+1) - X(L) )
       ENDIF


       F3 = (SIGN(1.0,S3)+SIGN(1.0,S4))*MIN(ABS(S3),ABS(S4),0.5*ABS(F3))
       F4 = (SIGN(1.0,S4)+SIGN(1.0,S5))*MIN(ABS(S4),ABS(S5),0.5*ABS(F4))


      ENDIF


C***  CALCULATE POLYNOMIAL COEFFICIENTS: P(VECTOR) = H(MATRIX) * F(VECTOR)
      P1 = H11*F1 + H12*F2 + H13*F3 + H14*F4
      P2 = H21*F1 + H22*F2 + H23*F3 + H24*F4
      P3 = H31*F1 + H32*F2 + H33*F3 + H34*F4
      P4 = H41*F1 + H42*F2 + H43*F3 + H44*F4
 
C***  EVALUATE THE INTERPOLATION POLYNOMIAL AT XX
      DLM = XX - X(L-1)
      DLM3 = DLM * DLM * DLM
      DL = X(L) - XX
      DL3 = DL * DL * DL
      FX = P1 * DLM3 + P2 * DLM + P3 * DL3 + P4 * DL

      RETURN
      END

ftplog.f/       1553528659  5006  320   100644  728       `
      SUBROUTINE FTPLOG
C***  HILFSPROGRAEMMCHEN ZUM UMSETZEN DES LOGS UNSERES ANONYMEN FTP-SERVERS
C***  IN EINE UEBERSICHTLICHE TABELLE
      CHARACTER LINE*250
      CHARACTER ADDRESS*30, FILENAME*34, PASSWORD*30
      OPEN (1, FILE='/usr/adm/xferlog')
    1 FORMAT (A)
    2 READ (1,1, END=99) LINE
      CALL SARGV (LINE,  9, ADDRESS)
      CALL SARGV (LINE, 11, FILENAME)
      CALL SARGV (LINE, 16, PASSWORD)

      IF (PASSWORD .EQ. '[none_given]') 
     > PASSWORD = '<< ' // ADDRESS

      WRITE (*,1) 
     > LINE (4:16) // ' ' //      
     > LINE (21:24) // ' ' //      
     > FILENAME(5:) // ' ' // 
     > PASSWORD

      GOTO 2

   99 WRITE (*,1) '>> For full information, see file: /usr/adm/xferlog'
      END
