grid.f/         1553528659  5006  320   100644  780       `
C*******************************************************************
C***  SUBROUTINE GRID : Einzeichnen der Stuetzstellen  (ISOPRO)
C*******************************************************************
      SUBROUTINE GRID (R, T, JMAX, IMAX, PPCM, ISYMB, GRSIZE,
     >                 XKAST,YKAST, MAXT, MAXR)

      DIMENSION R(MAXT,MAXR), T(MAXT), JMAX(MAXT)
      DIMENSION XKAST(6), YKAST(6)

C***  Umrechnen der Gridpunkte in cm 
      DO 20 I=1,IMAX
      SX = (T(I)-XKAST(2)) * XKAST(1)
      JMAXI=JMAX(I)
      DO 10 J=1,JMAXI
      SY = (R(I,J)-YKAST(2)) * YKAST(1)

      WRITE (2,'(A10, 2X, 4(F8.3,2X), A6, 2X, I1)') 
     >        'KASDEF SYM', T(I), R(I,J), 
     >                      0.0, 0.0, '$SIZES', 8
10    CONTINUE

20    CONTINUE

      RETURN
      END
grossb.f/       1553528659  5006  320   100644  859       `

	CHARACTER*(*) FUNCTION GROSSB( TEXT )
C ***
C ******************************************************************************
C ***
C ***	GROSSB converts string TEXT to upper case.
C ***	KLEINB converts string TEXT to lower case.
C ***
C ***	From Kiessling/Lowes, Programmieren mit FORTRAN77, pp97
C ***
C ***	 27-JUN-1988 13:37:09 
C ***
C ******************************************************************************
C ***
	CHARACTER*(*) KLEINB, TEXT, TAB(2)*26
	DATA TAB /'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 
     >	          'abcdefghijklmnopqrstuvwxyz'/
	DATA MODE /1/
	SAVE MODE

	MODE = 2
C ***
	ENTRY KLEINB( TEXT )
C             ======
C ***
	DO 1 L = 1, LEN(TEXT)
	   J = INDEX( TAB(MODE), TEXT(L:L) )
	   IF( J .EQ. 0 ) THEN
	      GROSSB(L:L) = TEXT(L:L)
	   ELSE
	      GROSSB(L:L) = TAB( 3 - MODE )(J:J)
	   END IF
1	CONTINUE
	MODE = 1
	RETURN
	END

gs_init.f/      1553528659  5006  320   100644  679       `
      SUBROUTINE GS_INIT
C****************************************************************
C***  PSOWN Graphic driver: Graphic State Algebra
C***  Transformation:
C***       x' = sx x + ry y + tx
C***       y' = rx x + sy y + ty
C***  Here: Initialize Graphic State Matrix 
C****************************************************************

      PARAMETER (MAXGS = 10)
      COMMON / COMGS_STACK / ISTACK, GSTACK(6,MAXGS)

      COMMON / COMGS_MAT / SX, RX, RY, SY, TX, TY

C***  Counter
      ISTACK = 0

C***  Transformation coefficients
      SX = 1.
      SY = 1.
      RX = 0.
      RY = 0.
      TX = 0.
      TY = 0.

C***  Color

C***  Linewidth

      RETURN
      END

gs_restore.f/   1553528659  5006  320   100644  850       `
      SUBROUTINE GS_RESTORE
C****************************************************************
C***  PSOWN Graphic driver: Graphic State Algebra
C***  Transformation:
C***       x' = sx x + ry y + tx
C***       y' = rx x + sy y + ty
C***  Here: Restore Graphic State Matrix from Stack
C****************************************************************

      PARAMETER (MAXGS = 10)
      COMMON / COMGS_STACK / ISTACK, GSSTACK(6, MAXGS)

      COMMON / COMGS_MAT / SX, RX, RY, SY, TX, TY

      IF (ISTACK .LE. 0) THEN 
         PRINT *, '>>> STACK UNDERFLOW <<<'
         STOP 'ERROR IN SUBROUTINE GS_RESTORE'
         ENDIF

      SX = GSSTACK(1,ISTACK)
      RX = GSSTACK(2,ISTACK)
      RY = GSSTACK(3,ISTACK)
      SY = GSSTACK(4,ISTACK)
      TX = GSSTACK(5,ISTACK)
      TY = GSSTACK(6,ISTACK)

      ISTACK = ISTACK - 1

      RETURN
      END
gs_rotate.f/    1553528659  5006  320   100644  817       `
      SUBROUTINE GS_ROTATE (PHI)
C****************************************************************
C***  PSOWN Graphic driver: Graphic State Algebra
C***  Transformation:
C***       x' = sx x + ry y + tx
C***       y' = rx x + sy y + ty
C***                                              ( cos -sin )
C***  Here: Multiplication with rotation matrix   ( sin  cos )
C***
C****************************************************************

      COMMON / COMGS_MAT / SX, RX, RY, SY, TX, TY

      DEGTORAD = 0.0174532925

      PHIRAD = PHI * DEGTORAD
      CO = COS (PHIRAD)
      SI = SIN (PHIRAD)

      SXNEW = CO * SX - SI * RX
      RXNEW = SI * SX + CO * RX
      SX = SXNEW
      RX = RXNEW

      RYNEW = CO * RY - SI * SY
      SYNEW = SI * RY + CO * SY
      RY = RYNEW
      SY = SYNEW

      RETURN
      END

gs_save.f/      1553528659  5006  320   100644  855       `
      SUBROUTINE GS_SAVE
C****************************************************************
C***  PSOWN Graphic driver: Graphic State Algebra
C***  Transformation:
C***       x' = sx x + ry y + tx
C***       y' = rx x + sy y + ty
C***  Here: Put present Graphic State Matrix on Stack
C****************************************************************

      PARAMETER (MAXGS = 10)
      COMMON / COMGS_STACK / ISTACK, GSSTACK(6, MAXGS)

      COMMON / COMGS_MAT / SX, RX, RY, SY, TX, TY

      ISTACK = ISTACK + 1
      IF (ISTACK .GT. MAXGS) THEN 
         PRINT *, '>>> STACK OVERFLOW <<<'
         STOP 'ERROR IN SUBROUTINE GS_STORE'
         ENDIF

      GSSTACK(1,ISTACK) = SX 
      GSSTACK(2,ISTACK) = RX 
      GSSTACK(3,ISTACK) = RY 
      GSSTACK(4,ISTACK) = SY 
      GSSTACK(5,ISTACK) = TX 
      GSSTACK(6,ISTACK) = TY 

      RETURN
      END

gs_scale.f/     1553528659  5006  320   100644  611       `
      SUBROUTINE GS_SCALE (SCX, SCY)
C********************************************************************
C***  PSOWN Graphic driver: Graphic State Algebra
C***  Transformation:
C***       x' = sx x + ry y + tx
C***       y' = rx x + sy y + ty
C***                                                      ( scx  0  )
C***  Here: Scaling in two axes, i.e. multiplication with (  0  scy )
C********************************************************************

      COMMON / COMGS_MAT / SX, RX, RY, SY, TX, TY

      SX = SX * SCX
      RY = RY * SCY
      RX = RX * SCX
      SY = SY * SCY

      RETURN
      END

gs_sheer.f/     1553528659  5006  320   100644  521       `
      SUBROUTINE GS_SHEER (SH)
C****************************************************************
C***  PSOWN Graphic driver: Graphic State Algebra
C***  Transformation:
C***       x' = sx x + ry y + tx
C***       y' = rx x + sy y + ty
C***                                   ( 1 SH )
C***  Here: Applies the Sheer Matrix   ( 0  1 )
C****************************************************************

      COMMON / COMGS_MAT / SX, RX, RY, SY, TX, TY

      RY = RY + SH * SX
      SY = SY + SH * RX

      RETURN
      END

gs_transform.f/ 1553528659  5006  320   100644  521       `
      SUBROUTINE GS_TRANSFORM (X, Y, XS, YS)
C****************************************************************
C***  PSOWN Graphic driver: Graphic State Algebra
C***  Transformation:
C***       x' = sx x + ry y + tx
C***       y' = rx x + sy y + ty
C***  Here: Applies the transformation to (X,Y); result: (XS,YS) 
C****************************************************************

      COMMON / COMGS_MAT / SX, RX, RY, SY, TX, TY

      XS = SX * X + RY * Y + TX
      YS = RX * X + SY * Y + TY

      RETURN
      END

gs_translate.f/ 1553528659  5006  320   100644  489       `
      SUBROUTINE GS_TRANSLATE (X, Y)
C****************************************************************
C***  PSOWN Graphic driver: Graphic State Algebra
C***  Transformation:
C***       x' = sx x + ry y + tx
C***       y' = rx x + sy y + ty
C***  Here: Add translation vector (given in current coordinates!)
C****************************************************************

      COMMON / COMGS_MAT / SX, RX, RY, SY, TX, TY

      CALL GS_TRANSFORM (X, Y, TX, TY)

      RETURN
      END

hlymana.f/      1553528659  5006  320   100644  17651     `
      SUBROUTINE HLYMANA (X, Y, NDAT, NSET, NDATMAX, NSETMAX, ISYMBOL, 
     >                    NPEN, ICOLOR, COMMAND, ISETOP, LINE, X1, Y1)

C**********************************************************************
C***  CORRECTING UV SPECTRA (e.g. IUE) FOR THE EXTINCTION BY        ***
C***                HYDROGEN Lyman lines                            ***
C***  - CALLED FROM: WRPLOT ( <-- COMMAND = .FALSE. )               ***
C***        OR FROM:  EXCMD ( <-- COMMAND = .TRUE. )                ***
C***                                                                ***
C***  SOURCE: GROENEWEGEN & LAMERS (1989, A&A Suppl Ser 79, 359)    ***
C***                                                                ***
C***  These data cover the series up to n=10
C***  An extension up to n=20 has been added by Thomas Rauch
C***    (see WR-Memo 19-Apr-2007). He writes: 
C***  "Ausrechnen (der atomaren Querschnitte) ist wohl ein schwieriges
C***  Geschaeft, da man de f-Werte aller s-p- und d-p-Uebergaenge vom HI dazu
C***  benoetigt - keine Ahnung wo ich die nun herbekommen sollte. Deshalb habe
C***  ich die C0 und C1 mal logarithmisch aufgetragen und dann nach Augenmass
C***  extrapoliert. Ich nehme an, dass liefert ein brauchbares Ergebnis."
C***  
C***  Note that this subroutine does not handle the b-f opacity     ***
C***  bluewards the Lyman edge, this is done by extinct!            ***
C***  Damping wings can extend bluewards of Lyman edge!             ***
C***                                                                ***
C***  DATA:  X = LAMBDA[ANGSTROEM]                                  ***
C***         Y = FLUX                                               ***
C**********************************************************************

      PARAMETER ( NHI = 31 ) 

      DIMENSION X(NDATMAX,NSETMAX), Y(NDATMAX,NSETMAX)
      DIMENSION X1(NDATMAX), Y1(NDATMAX)

      DIMENSION NDAT(NSETMAX), ISYMBOL(NSETMAX), NPEN(NSETMAX)
      DIMENSION ICOLOR(NSETMAX)

      CHARACTER KEY*20, LINE*(*), ACTPAR*20, ACTPAR2*20
      CHARACTER CHAR*1
      LOGICAL COMMAND

      DIMENSION C0(NHI), C1(NHI), XLAM(NHI), XLAM0(NHI)
      DIMENSION FVALUE(NHI), GAMM(NHI)            

C***  WAVELENGTHS OF HYDROGEN LY lines
      DATA XLAM0 /   1215.671,   1025.722,     972.5366,    949.74297, 
     >               937.80344,   930.74824,   926.22571,   923.15037, 
     >               920.96313,   919.35146,   918.12939,   917.18061,
     >               916.42917,   915.82388,   915.32904,   914.91936,
     >               914.57629,   914.28622,   914.03860,   913.82569,   
     >               913.64126,   913.48036,   913.33922,   913.21470,   
     >               913.10431,   913.00597,   912.91800,   912.83898,   
     >               912.76775,   912.70331,   912.64482              /

C***  CONSTANTS OF FORMULAE (16), (22) (GROENEWEGEN & LAMERS, 1989)
C *** LOG. EXTRAPOLATED FOR LINES HIGHER THAN LY 1-11 

      DATA C0 / 7.056E-11,   4.428E-11,   3.788E-11,   3.522E-11, 
     >          3.381E-11,   3.298E-11,   3.243E-11,   3.204E-11, 
     >          3.177E-11,   3.156E-11,   3.141E-11,   3.129E-11, 
     >          3.120E-11,   3.112E-11,   3.106E-11,   3.101E-11, 
     >          3.097E-11,   3.093E-11,   3.090E-11,   3.087E-11, 
     >          3.085E-11,   3.083E-11,   3.081E-11,   3.079E-11, 
     >          3.078E-11,   3.077E-11,   3.076E-11,   3.075E-11,  
     >          3.074E-11,   3.073E-11,   3.072E-11                  /

      DATA C1 / 1.657E+09,   3.575E+10,   2.402E+11,   9.867E+11, 
     >          3.059E+12,   7.871E+12,   1.773E+13,   3.628E+13, 
     >          6.036E+13,   9.760E+13,   1.427E+14,   1.941E+14, 
     >          2.505E+14,   3.106E+14,   3.734E+14,   4.381E+14, 
     >          5.042E+14,   5.712E+14,   6.387E+14,   7.064E+14, 
     >          7.743E+14,   8.421E+14,   9.098E+14,   9.773E+14, 
     >          1.044E+15,   1.111E+15,   1.178E+15,   1.244E+15, 
     >          1.310E+15,   1.376E+15,   1.441E+15                  /

C***  f values (oscillator strengths) of the Lyman lines
      DATA FVALUE / 4.1620E-01, 7.9100E-02, 2.8990E-02, 1.3940E-02,
     >              7.7990E-03, 4.8140E-03, 3.1830E-03, 2.2160E-03, 
     >              1.6050E-03, 1.2010E-03, 9.2140E-04, 7.2270E-04,
     >              5.7740E-04, 4.6860E-04, 3.8560E-04, 3.2110E-04, 
     >              2.7030E-04, 2.2960E-04, 1.9670E-04, 1.6980E-04, 
     >              1.4760E-04, 1.2910E-04, 1.1360E-04, 1.0050E-04, 
     >              8.9290E-05, 7.9700E-05, 7.1450E-05, 6.4300E-05, 
     >              5.8070E-05, 5.2610E-05, 4.7830E-05               /

C***  Gamma values (damping constants) of the Lyman lines
C***  The first 5 Gammas are from Morton (2003), ApJS 149: 205-238;
C***  this exactly reproduces the Groenewegen & Lamers profiles.
C***  Further values  were computed by Thomas Rauch (08.09.2012), 
C***  according to Groenewegen & +Lamers (1989); 
      DATA GAMM / 6.26500E+08, 1.89700E+08, 8.12700E+07, 4.20400E+07,
     >            2.45000E+07, 
     >                        1.4043E+07, 9.3788E+06, 6.5742E+06, 
     >            4.7849E+06, 3.5931E+06, 2.7643E+06, 2.1728E+06, 
     >            1.7388E+06, 1.4131E+06, 1.1641E+06, 9.7030E+05, 
     >            8.1739E+05, 6.9477E+05, 5.9556E+05, 5.1437E+05,
     >            4.4730E+05, 3.9138E+05, 3.4449E+05, 3.0485E+05,
     >            2.7091E+05, 2.4188E+05, 2.1689E+05, 1.9522E+05,
     >            1.7632E+05, 1.5978E+05, 1.4527E+05 /

C***  C2 = 10. ** 21.58 = HYDROGEN COLUMN DENSITY FOR E(B-V)= 1 MAG
C***  ACHTUNG: BOHLIN ET AL. GEBEN EINEN GROESSEREN WERT: 5.8E21
      DATA C2 / 3.8E21 /
      DATA CLIGHT /299792.458/

C***  Constants for Voigt profile in cgs units
      DATA  ATMASSH /1.00794/
      DATA  XKBOLTZ /1.38065000E-16/
      DATA  XMP     /1.67262160E-24/
      DATA  XLYEDGE0 /911.2670504/
      DATA  PI  /3.1415927/

C***  Default parameters
      TEMP  = -1.
      VTURB = 0.
      VRAD = 0. 
C***  Insert lambda point when relative change of TAU exceeds TAUCRIT
      TAUCRIT = 0.1  
C***  Insert MAXNPOINTS extra points per line on top of TAU criterion
      MAXNPOINTS = 0 

C***  Decoding of the COMMAND line
      IF (COMMAND) THEN
      CALL SARGC (LINE, NPAR)
      KEY = 'EBV'
      IF (NPAR .LT. 3) THEN
         WRITE (*,'(//,A)') 
     >       '*** ERROR: HLYMANA needs at least one parameter'
         GOTO 97
      ELSE IF (NPAR .EQ. 3) THEN
         CALL SARGV (LINE, 3, ACTPAR)
         READ (ACTPAR, '(BN,F20.0)',ERR=99) EBV
      ELSE

C***  For compatibility: if there are just 2 naked 
C***  numerical parameters, assume that they mean EBV, VRAD
         IF (NPAR .EQ. 4) THEN
            CALL SARGV (LINE, 3, ACTPAR)
            READ (ACTPAR, '(BN,F20.0)',ERR=30) EBV
            CALL SARGV (LINE, 4, ACTPAR)
            READ (ACTPAR, '(BN,F20.0)',ERR=30) VRAD
            GOTO 34
         ENDIF
   30    CONTINUE 

         DO IPAR=3, NPAR, 2
            CALL SARGV (LINE, IPAR, ACTPAR)
            IF (IPAR .EQ. NPAR) THEN
               WRITE (*,'(//,2A)') 
     >            '*** ERROR: Value missing for ', ACTPAR
               GOTO 97
            ENDIF
            CALL SARGV (LINE, IPAR+1, ACTPAR2)
            IF (ACTPAR .EQ. 'COLDENS' .OR. ACTPAR .EQ. 'EBV') THEN
C                            =======                    ===
               KEY = ACTPAR
               READ (ACTPAR2, '(BN,F20.0)',ERR=99) EBV
            ELSE IF (ACTPAR .EQ. 'VRAD') THEN
C                                 ====
                READ (ACTPAR2, '(BN,F20.0)',ERR=99) VRAD
C           For Voigt profile: T in K, VTURB in km/s
            ELSE IF (ACTPAR .EQ. 'T') THEN
C                                 =
                READ (ACTPAR2, '(BN,F20.0)',ERR=99) TEMP
            ELSE IF (ACTPAR .EQ. 'VTURB') THEN
C                                 =====
                READ (ACTPAR2, '(BN,F20.0)',ERR=99) VTURB
            ELSE IF (ACTPAR .EQ. 'MAXNPOINTS') THEN
C                                 ==========
                READ (ACTPAR2, '(BN,I6)',ERR=99) MAXNPOINTS
            ELSE IF (ACTPAR .EQ. 'TAUCRIT') THEN
C                                 =======
                READ (ACTPAR2, '(BN,F20.0)',ERR=99) TAUCRIT
            ELSE IF (ACTPAR .EQ. 'DATASET') THEN
C                                 =======
                CYCLE
            ELSE
	       WRITE (*,'(//,2A)') 
     >              '*** ERROR: Invalid Keyword: ', ACTPAR
               GOTO 97
            ENDIF
         ENDDO 
      ENDIF
   34 CONTINUE

      ENDIF ! END OF COMMAND LINE INTERPRETATION
      
      DO I=1, NHI
         XLAM(I) = XLAM0(I) * (1. + VRAD / CLIGHT)
      ENDDO
      XLYEDGE = XLYEDGE0 * (1. + VRAD / CLIGHT)

C     Convert VTURB from km/s to cm/s
      VTURB = VTURB * 1.E5
      
C***********************************************************************
C***  INTERAKTIVE INPUT ONLY IF NOT CALLED BY COMMAND
C***  This branch has been de-activated, wrh 12.03.2012
C***  This branch has been re-activated, htodt 14.09.2016 
C***********************************************************************

      CHAR = ' '
      IF (COMMAND) THEN
         I1 = ISETOP
         I2 = ISETOP

      ELSE

         IF (NSET .EQ. 1) THEN
            I1=1
         ELSE 
 1          WRITE(6,*) 
     >      'NUMBER OF OLD DATA-SET (EXISTING:',NSET,'): '
            READ(5,*) I1
            IF (I1 .LT. 1 .OR. I1 .GT. NSET) GOTO 1 
         ENDIF

    6    WRITE (6,'(''$'',A)')  
     >     'INPUT E(B-V) (NEGATIVE FOR REDDENING, POSITIVE FOR ' // 
     >     'DEREDDENING, "0" = RETURN; '
         WRITE (6,'(''$'',A)') 'TYPE "COLDENS" IF WANTED ) : '
         READ (*, '(A)') KEY
         IF (KEY(:7) .EQ. 'COLDENS' .OR. KEY(:7) .EQ. 'coldens') THEN
            KEY='COLDENS'
            WRITE (6, '(''$'',A)') 'INPUT COLUMN DENSITY PER CM**2 ' //
     >                             '(NEGATIVE FOR REDDENING, '
            WRITE (6, '(''$'',A)') 'POSITIVE FOR DEREDDENING):'
            READ (*,*) EBV
         ELSE
            READ (KEY, '(BN,F20.0)', ERR=99) EBV
            KEY = 'EBV'
         ENDIF
         IF (EBV .EQ. 0.) RETURN

20       WRITE(6,'(''$'',A)') 'OVERWRITE OLD DATA-SET NR. (Y/N) /N/ '
         READ(5,'(A)') CHAR
         IF (CHAR .EQ. 'Y' .OR. CHAR .EQ. 'y') THEN
            I2=I1
            GOTO 33
         ENDIF
         IF (NSET .LT. NSETMAX) THEN
            NSET=NSET+1
            I2=NSET
            ! COPY DATA TO NEW DATA SET
            NDAT(I2) = NDAT(I1)
            DO I=1, NDAT(I1) 
              X(I,I2) = X(I,I1)
              Y(I,I2) = Y(I,I1)        
            ENDDO
            GOTO 33
         ENDIF
         WRITE(6,*) 'ALL DATA-SETS USED !'
         WRITE(6,'(''$'',A)') 'OVERWRITE DATA-SET NR: '
         READ(5,*) I2
         IF (I2 .LT. 1 .OR. I2 .GT. NSETMAX) THEN
            WRITE(6,*) 'THIS DATASET NOT SAVED'
            GOTO 6
         ELSE ! COPY DATA TO NEW DATA SET
            NDAT(I2) = NDAT(I1)
            DO I=1, NDAT(I1) 
              X(I,I2) = X(I,I1)
              Y(I,I2) = Y(I,I1)        
            ENDDO
         ENDIF         

   33    CONTINUE
            WRITE(6,*) 'NEW DATA IN SET NR: ',I2
      ENDIF

C***  IF E(B-V) GIVEN, COVERT INTO COLUMN DENSITY
      IF (KEY .EQ. 'EBV') THEN
         ENH = C2 * EBV
      ELSE IF (KEY .EQ. 'COLDENS') THEN
         ENH = EBV
      ELSE
          STOP 'ERROR in HLYMANA: UNKNOWN KEYWORD'
      ENDIF

C**********************************************************************
C***                EXPAND DATA TO INSERT LYMAN LINES               ***
C**********************************************************************

      IDAT=NDAT(I2)

C***  Dataset must be in monotonic order
      CALL CHECKMONO (X(1,I2), IDAT, IORDER, IERR)
      IF (IERR .GT. 0) 
     >    STOP '*** FATAL ERROR detected by HLYMANA'

      XLAMMIN = X_MINVAL(X(1,I2), IDAT)
      XLAMMAX = X_MAXVAL(X(1,I2),IDAT) 

      XINSOLD = X(1,I2) ! insert also data points between line centers

      LOOP_NHI : DO I=NHI, 1, -1
         DLAMBDA = 1. / MAX(1,MAXNPOINTS)  / (FLOAT(I)*FLOAT(I))
         DO J=-MAXNPOINTS/2 , MAXNPOINTS/2, 1
          XINS = XLAM(I) + SIGN(1,J) * J * J * DLAMBDA
          XDL1 = XLAMMIN - XINS
          XDR1 = XLAMMAX - XINS
          IF (XDL1 * XDR1 .GT. 0. ) CYCLE 
          IF (IDAT .GE. NDATMAX) THEN
           WRITE (0,'(/,A,$)')
     >         'HLYMANA: CANNOT INSERT MORE POINTS TO COVER'
           WRITE (0,*) ' LYMAN LINE PROFILES, AT ', XLAM0(I)
           EXIT LOOP_NHI
          ENDIF 
          CALL INSERTPOINT (X(1,I2), Y(1,I2), NDATMAX,
     >                      IDAT, XINS, LINS)
          ! at least one data point per line inserted, add another 
          ! one for taucrit in between :
          IF (MAXNPOINTS .EQ. 0) THEN
           XMID = (XINSOLD + XINS) / 2. 
           CALL INSERTPOINT (X(1,I2), Y(1,I2), NDATMAX,
     >                       IDAT, XMID, LINS)
           XINSOLD = XINS
          ENDIF
          
         ENDDO
      ENDDO LOOP_NHI
      
C***  Insert two points around the edge 
      IF ((XLYEDGE-X(1,I2))*(XLYEDGE-X(IDAT,I2)) .LT. .0) THEN
          CALL INSERTPOINT (X(1,I2), Y(1,I2), NDATMAX,
     >                      IDAT, XLYEDGE-0.001, LINS)
          CALL INSERTPOINT (X(1,I2), Y(1,I2), NDATMAX,
     >                      IDAT, XLYEDGE+0.001, LINS)
      ENDIF

C***********************************************************************
C***  MULTIPLICATION WITH ABSORPTION PROFILE
C***********************************************************************

      NDAT(I2)    = IDAT
      ISYMBOL(I2) = ISYMBOL(I1)
      NPEN(I2)    = NPEN(I1)
      ICOLOR(I2)  = ICOLOR(I1)

      ! copy original data to scratch array for insertpoint
      DO I=1, NDAT(I2)
         X1(I) = X(I,I2)
         Y1(I) = Y(I,I2)
      ENDDO
      
      TAUOLD = 0. ! initialize tau criterion

      I = 1 ! number of data points is manipulated within loop

      DO        
 16      X(I,I2) = X1(I)
         TAU = 0.

         IF ( TEMP .GT. 0. .OR. VTURB .GT. 0.) THEN
C***     Temperature given => Voigt profile
          DO LY = 1, NHI
C          Doppler width in Hertz
           VDOPP = SQRT(2. * XKBOLTZ * TEMP / (XMP * ATMASSH)
     >               + VTURB * VTURB ) 
           DNDOPP  = VDOPP / (XLAM(LY) * 1.E-8)
C          Constant "A" for normalized Voigt function
           A   = GAMM(LY) / (4. * PI * DNDOPP) 
C          Variable "V" for normalized Voigt function
           DLAM = X1(I) - XLAM(LY)
           DNUE = CLIGHT * 1.E13 * DLAM / (XLAM(LY)*XLAM(LY))
           V = DNUE / DNDOPP
           HH = VOIGTH (A,V)
C          Cross section = (pi e^2)/mc * f * VoigtH / DNDOPP 
           SIGMACL = 0.026537
           FAK = SIGMACL * FVALUE(LY) / DNDOPP 
           TAU = TAU + FAK * HH * ENH
          ENDDO
          V = 0.0
          TAULYMEDGE = FAK * VOIGTH(A,V) * ENH
         ELSE 
C***     No or neg. Temperature given -> Lorentz profile 
          DO LY = 1, NHI
           DLAM = X1(I)-XLAM(LY)
           TAU = TAU + ENH * C0(LY) / (1.+C1(LY)*DLAM*DLAM)
          ENDDO
          TAULYMEDGE = ENH * C0(NHI)
         ENDIF

         ! insert another data point to fullfil tau criterion 
         IF ( TAUCRIT .GT. 0. 
     >        .AND. ABS((TAU - TAUOLD)/TAUOLD) .GT. TAUCRIT
     >        .AND. I .GT. 1 
     >        .AND. ABS(X1(I)-X1(I-1)) .GT. 0.001 ) THEN            
            XINS  = ( X1(I) + X1(I-1) ) / 2. 
            CALL INSERTPOINT (X1, Y1, NDATMAX, IDAT, XINS, LINS)
            GOTO 16
         ENDIF

         TAUOLD  = TAU
         X(I,I2) = X1(I)

         IF (TAU .LT. 10.) THEN ! prevent floating overflow 
                                ! for pos. tau (dereddening)
           Y(I,I2) = Y1(I) * EXP(TAU)
         ELSE
           Y(I,I2) = 0.
           WRITE(0,*) 'WARNING : LYMAN ALPHA CORRECTION ',
     >                'GREATER EXP(10.)', TAU, X(I,I2)
           WRITE(0,*) '          FLUX SET TO 0.'
         ENDIF

         I = I + 1 ! next original data point
         IF (I .GT. IDAT) EXIT

      ENDDO ! end of loop for reddening + point insertion


      NDAT(I2) = IDAT ! new number of data points

      IF (TAUCRIT .GT. 0. .AND. MAXNPOINTS .NE. 0) THEN
       WRITE (0,'(/,A,I6,A)') 'HLYMANA: DATASET EXPANDED TO ', IDAT,
     >    ' DATA POINTS BECAUSE OF TAU CRITERION AND MAXNPOINTS' 
      ELSE IF (MAXNPOINTS .EQ. 0 .AND. TAUCRIT .GT. 0) THEN
       WRITE (0,'(/,A,I6,A)') 'HLYMANA: DATASET EXPANDED TO ', IDAT,
     >                     ' DATA POINTS BECAUSE OF TAUCRITERION' 
      ELSE IF (MAXNPOINTS .NE. 0 .AND. TAUCRIT .LE. 0) THEN
       WRITE (0,'(/,A,I6,A)') 'HLYMANA: DATASET EXPANDED TO ', IDAT,
     >                     ' DATA POINTS BECAUSE OF MAXNPOINTS' 
      ELSE
       WRITE (0,'(/,A,I6,A)') 'HLYMANA: DATASET EXPANDED TO ', IDAT,
     >                     ' DATA POINTS ONLY FOR HLYMAN LINE CENTER' 
      ENDIF

      
C***  Set tau = tau(NHI) bluewards of LY(NHI) up to Lyman edge 
      IF (TAULYMEDGE .LT. 10.) THEN ! prevent floating overflow
                                    ! for pos. tau (dereddening)
         EXPTAULYMEDGE = EXP(TAULYMEDGE)
      ELSE
         EXPTAULYMEDGE = .0
      ENDIF

      DO I=1, NDAT(I2)
        IF ((X(I,I2) .LT. XLAM(NHI)) .AND. (X(I,I2).GT. XLYEDGE)) THEN 
            Y(I,I2) = Y(I,I2) * EXPTAULYMEDGE
        ENDIF
      ENDDO

      IF (COMMAND) RETURN 
      GOTO 6


C***  Errors ****************************************************

   99 WRITE(6,'(//,A)') '*** ERROR when decoding REAL number'
      GOTO 97

   97 WRITE(6,*) 'The error occured in the following line: '
      WRITE(6,*) LINE(1:IDX(LINE))
      STOP '*** ERROR in Subr. HLYMANA'

      END

hstlog.f/       1553528659  5006  320   100644  3343      `
      SUBROUTINE HSTLOG
C************************************************************
C***  Schneidet aus dem HST-Archiv-Verzeichnis ausgewaehlte Spalten aus
C************************************************************

      CHARACTER*1024 LINE1, LINEA, LINEB
      CHARACTER*132  LINE2, ACTPAR

      OPEN (1, FILE='query_results.txt', STATUS='UNKNOWN')
      OPEN (2, FILE='hst_log.txt', STATUS='UNKNOWN')
    1 FORMAT (A)

    2 CONTINUE
      READ (1,1, END=99) LINE1

C***  M = Position of first character to be read from input string
C***  N = Number of characters to be read from input string

c      CALL SARGC (LINE1, NA)
c      DO 10 I=1,NA
c      CALL SARGP (LINE1, NNA, I, IFIRST, ILAST)
c   10 print *, '(', IFIRST, ':', ILAST, ') ', LINE1(IFIRST:ILAST)


      L = 1
      LINE2 = ' '

      LA = 77
      LINEA = ' '

      LB = 77
      LINEB = ' '

C***  data set name
      N = 9
      M = 16
      LINE2(L:L+N-1) = LINE1(M:M+N-1)
      L = L + N + 1

C***  target name
      N = 15
      M = 93
      LINE2(L:L+N-1) = LINE1(M:M+N-1)
      L = L + N + 1

C***  sci_instrument_config
      N = 6
      M = 166
      LINE2(L:L+N-1) = LINE1(M:M+N-1)
      L = L + N + 1

C***  sci_operating mode
      N = 11
      M = 189
      LINE2(L:L+N-1) = LINE1(M:M+N-1)
      L = L + N + 1

C***  sci_spec_1234
      N = 10
      M = 209
      LINE2(L:L+N-1) = LINE1(M:M+N-1)
      L = L + N + 1

C***  sci_actual_duration
      N = 8
      M = 315
      LINE2(L:L+N-1) = LINE1(M:M+N-1)
      L = L + N + 1

C***  PI
      N = 10
      M = 324
      LINE2(L:L+N-1) = LINE1(M:M+N-1)
      L = L + N + 1

C***  Target description
      N = 55
      M = 609
      LINE2(L:L+N-1) = LINE1(M:M+N-1)
      L = L + N + 1

      IF (L .gt. 134) THEN
        print *, 'L=', L
        STOP 'ERROR: output line too long'
        ENDIF
      WRITE (2,'(A132)') LINE2


C***  Zweite Output-Zeile *******************************

C***  Release date (Year)
      LINEA(5:8) = LINE1(67:70)

C***  Release date (Month)
      LINEA(1:3) = LINE1(60:62)

C***  Spectral range
      IF (LINE1(602:607) .NE. '-1.000') THEN
         LINEA(46:49) = LINE1(570:573)
         LINEA(50:50) = '-'
         LINEA(51:54) = LINE1(600:603)
         ENDIF

C***  1. Comment
      N = 55
      M = 801
      LINEA(LA:LA+N-1) = LINE1(M:M+N-1)

      IF (LA+N+1 .gt. 134) THEN
        print *, 'LA=', LA+N+1
        STOP 'ERROR: output line too long'
        ENDIF

      WRITE (2,'(A132)') LINEA

C***  write continuation line if necessary
      M = M+N
      N = 18
      LA = LA + 5
      IF (LINE1(M:M+N-1) .NE. ' ') THEN
         LINEA = ' '
         LINEA(LA:LA+N-1) = LINE1(M:M+N-1)
         WRITE (2,'(A132)') LINEA
         ENDIF

C***  Dritte Output-Zeile *******************************

C***  2. comment
      N = 55
      M = 875
      LINEB(LB:LB+N-1) = LINE1(M:M+N-1)

      IF (LB+N+1 .gt. 134) THEN
        print *, 'LB=', LB+N+1
        STOP 'ERROR: output line too long'
        ENDIF

      WRITE (2,'(A132)') LINEB

C***  write continuation line if necessary
      M = M+N
      IF (LINE1(M:M+N-1) .NE. ' ') THEN
         LINEB = ' '
         LINEB(LB:LB+N-1) = LINE1(M:M+N-1)
         WRITE (2,'(A132)') LINEB
         ENDIF




      GOTO 2

   99 CONTINUE
      PRINT *, 'reduced hst-log written into file "hst_log.txt"'
      STOP 'O.K.'
      END

hydrof.f/       1553528659  5006  320   100644  7673      `
      SUBROUTINE HYDROF
C********************************************************************
C***  BERECHNUNG DER HYDROGENISCHEN F-WERTE, AUFGESPALTEN NACH    ***
C***    NEBENQUANTENZAHLEN. CARSON 1988 (A&A SUPPL. 75, 385-389   ***
C********************************************************************

      DIMENSION FSUM(5,5)
      CHARACTER*255 FNAME

      F10N1(X) = 2.**8. /3. *X**5. / (X**2.-1.)

      F20N1(X) = 2.**15. /3. *X**5. * (X**2.-1.)

      F21N0(X) = 2.**13. / 3.**3. * X**7.

      F21N2(X) = 2.**18. / 3.**3. * X**7. * (X**2.-1.) / (X**2.-4.)

      F30N1(X) = 2.**8. * 3.**4. * X**5. * (X**2.-1.) *
     >           (7.*X**2 - 27.)**2.

      F31N0(X) = 2.**11. * 3.**3. * X**7. * (X**2. - 3.)**2.

      F31N2(X) = 2.**12. * 3.**5. * X**7. * (X**2.-1.) * (X**2.-4.)

      F32N1(X) = 2.**12. * 3.**4. / 5.**2. * X**9. * (X**2.-1.)

      F32N3(X) = 2.**13. * 3.**7. / 5.**2. * X**9. * (X**2.-1.) *
     >           (X**2.-4.) / (X**2.-9.)


      F40N1(X) = 2.**22. / 3.**3. * X**5. * (X**2.-1.) *
     >           (23.*X**4. - 288.*X**2. + 768.)**2.

      F41N0(X) = 2.**18. / 3.**3. / 5. * X**7. *
     >           (57.*X**4. - 608.*X**2. + 1280)**2.

      F41N2(X) = 2.**27. / 3.**3. / 5. * X**7. * (X**2.-1.) *
     >           (X**2.-4.) * (9.*X**2. - 80.)**2.

      F42N1(X) = 2.**25. / 3.**3. / 5.**2. * X**9. *
     >           (X**2.-1) * (7.*X**2. - 48.)**2.

      F42N3(X) = 2.**34. / 3.**2. / 5.**2. * X**9. * (X**2.-1.) *
     >           (X**2.-4.) * (X**2.-9.)

      F43N2(X) = 2.**30. / 3.**2. / 5. / 7.**2. * X**11. *
     >           (X**2.-1.) * (X**2.-4.)

      F43N4(X) = 2.**38. / 3.**3. / 5. / 7.**2. * X**11. *
     >           (X**2.-1.) * (X**2.-4.) * (X**2.-9.) /
     >           (X**2.-16.)

      F50N1(X) = 2.**8. / 3.**3. * 5.**7. * X**5. * (X**2.-1.) *
     >           (91.*X**6. - 2545.*X**4. + 20625.*X**2. - 46875.)**2.

      F51N0(X) = 2.**11. / 3.**5. * 5.**5. * X**7. *
     >           (49.*X**6. - 3725.*X**4. + 25875.*X**2. - 46875.)**2.

      F51N2(X) = 2.**12. / 3.**5. * 5.**7. * X**7. * (X**2.-1.) *
     >           (X**2.-4.) *
     >           (67.*X**4. - 1650.*X**2. + 9375.)**2.

      F52N1(X) = 2.**12. / 3.**3. * 5.**6. / 7. * X**9. * (X**2.-1.) *
     >           (29.*X**4. - 590.*X**2. + 2625.)**2.

      F52N3(X) = 2.**13. / 3.**2. * 5.**8. / 7. * X**9. * (X**2.-1.) *
     >           (X**2.-4.) * (X**2.-9.) *
     >           (11.*X**2. - 175.)**2.

      F53N2(X) = 2.**17. / 3.**2. * 5.**7. / 7.**2. * X**11. *
     >           (X**2.-1.) * (X**2.-4.) * (2.*X**2. - 25.)**2.

      F53N4(X) = 2.**17. / 3.**3. * 5.**11. / 7.**2. * X**11. *
     >           (X**2.-1.) * (X**2.-4.) * (X**2.-9.) * (X**2.-16.)

      F54N3(X) = 2.**17. / 3.**7. * 5.**9. / 7. * X**13. * (X**2.-1.) *
     >           (X**2.-4.) * (X**2.-9.)

      F54N5(X) = 2.**17. / 3.**7. * 5.**11. / 7. * X**13. * (X**2.-1.) *
     >           (X**2.-4.) * (X**2.-9.) * (X**2.-16.) / (X**2.-25.)


      FNENN(XA,XB) = ((XB-XA) / (XB+XA))**(2.*XB) *
     >               (XB**2. - XA**2.)**(-(2*XA+1.))


      FNAME = 'HYDROF.OUT'
      OPEN (1, FILE=FNAME, STATUS='NEW')

      DO 10 NU=1, 20
        DO 25 NL=1, 5
          DO 25 LL=0, 4
            FSUM(NL,LL+1) = 0.
   25   CONTINUE
        DO 20 LU=0, NU    
          DO 30 NL=1, NU-1
            DO 40 LL= LU-1, LU+1
              IF (.NOT.(LL .LT. 0 .OR. LL .EQ. LU .OR. LL+1 .GT. NL 
     >                  .OR. NL .GT. 5)) THEN
                F = 0.
                
                IF (NL .EQ. 1) THEN
                  IF (LL .EQ. 0) THEN
                    IF (LU .EQ. 1) THEN
                      F = F10N1(FLOAT(NU))
                    ENDIF
                  ENDIF

                ELSE IF (NL .EQ. 2) THEN
                  IF (LL .EQ. 0) THEN
                    IF (LU .EQ. 1) THEN
                      F = F20N1(FLOAT(NU))
                    ENDIF
                  ELSE IF (LL .EQ. 1) THEN
                    IF (LU .EQ. 0) THEN
                      F = F21N0(FLOAT(NU))
                    ELSE IF (LU .EQ. 2) THEN
                      F = F21N2(FLOAT(NU))
                    ENDIF
                  ENDIF

                ELSE IF (NL .EQ. 3) THEN
                  IF (LL .EQ. 0) THEN
                    IF (LU .EQ. 1) THEN
                      F = F30N1(FLOAT(NU))
                    ENDIF
                  ELSE IF (LL .EQ. 1) THEN
                    IF (LU .EQ. 0) THEN
                      F = F31N0(FLOAT(NU))
                    ELSE IF (LU .EQ. 2) THEN
                      F = F31N2(FLOAT(NU))
                    ENDIF
                  ELSE IF (LL .EQ. 2) THEN
                    IF (LU .EQ. 1) THEN
                      F = F32N1(FLOAT(NU))
                    ELSE IF (LU .EQ. 3) THEN
                      F = F32N3(FLOAT(NU))
                    ENDIF
                  ENDIF

                ELSE IF (NL .EQ. 4) THEN
                  IF (LL .EQ. 0) THEN
                    IF (LU .EQ. 1) THEN
                      F = F40N1(FLOAT(NU))
                    ENDIF
                  ELSE IF (LL .EQ. 1) THEN
                    IF (LU .EQ. 0) THEN
                      F = F41N0(FLOAT(NU))
                    ELSE IF (LU .EQ. 2) THEN
                      F = F41N2(FLOAT(NU))
                    ENDIF
                  ELSE IF (LL .EQ. 2) THEN
                    IF (LU .EQ. 1) THEN
                      F = F42N1(FLOAT(NU))
                    ELSE IF (LU .EQ. 3) THEN
                      F = F42N3(FLOAT(NU))
                    ENDIF
                  ELSE IF (LL .EQ. 3) THEN
                    IF (LU .EQ. 2) THEN
                      F = F43N2(FLOAT(NU))
                    ELSE IF (LU .EQ. 4) THEN
                      F = F43N4(FLOAT(NU))
                    ENDIF
                  ENDIF

                ELSE IF (NL .EQ. 5) THEN
                  IF (LL .EQ. 0) THEN
                    IF (LU .EQ. 1) THEN
                      F = F50N1(FLOAT(NU))
                    ENDIF
                  ELSE IF (LL .EQ. 1) THEN
                    IF (LU .EQ. 0) THEN
                      F = F51N0(FLOAT(NU))
                    ELSE IF (LU .EQ. 2) THEN
                      F = F51N2(FLOAT(NU))
                    ENDIF
                  ELSE IF (LL .EQ. 2) THEN
                    IF (LU .EQ. 1) THEN
                      F = F52N1(FLOAT(NU))
                    ELSE IF (LU .EQ. 3) THEN
                      F = F52N3(FLOAT(NU))
                    ENDIF
                  ELSE IF (LL .EQ. 3) THEN
                    IF (LU .EQ. 2) THEN
                      F = F53N2(FLOAT(NU))
                    ELSE IF (LU .EQ. 4) THEN
                      F = F53N4(FLOAT(NU))
                    ENDIF
                  ELSE IF (LL .EQ. 4) THEN
                    IF (LU .EQ. 3) THEN
                      F = F54N3(FLOAT(NU))
                    ELSE IF (LU .EQ. 5) THEN
                      F = F54N5(FLOAT(NU))
                    ENDIF
                  ENDIF
                ENDIF
                F = F * FNENN (FLOAT(NL), FLOAT(NU))
                WRITE (1,50) NU, LU, NL, LL, F
   50           FORMAT ( 'NU=',I2,' LU=',I2,' NL=',I2,' LL=',I2,
     >                  '  F-WERT=',E15.9)
                FSUM(NL,LL+1) = FSUM(NL,LL+1) + F
              ENDIF
   40       CONTINUE
   30     CONTINUE
   20   CONTINUE
        WRITE (1,*)
        DO 60 NL=1, 5
          DO 60 LL=0, 4
            IF (FSUM(NL,LL+1) .NE. 0.) THEN 
              WRITE (1,70) NL, LL, FSUM(NL,LL+1)
            ENDIF
   70       FORMAT ('NL=',I1,'  LL=',I1,'   FSUM=',E15.9)
   60   CONTINUE
        WRITE (1,*)
        WRITE (1,*)
   10 CONTINUE

      CLOSE (1)
                    
      END

idam.f/         1553528659  5006  320   100644  663       `
      FUNCTION IDAM(C)
C********************************************************************
C***  TRANSLATION OF ANGULAR MOMENTUM CHARACTER (S, P, D, ...)    ***
C***    IN INTEGER NUMBER                                         ***
C********************************************************************

      CHARACTER C

      I = -1

      IF (C .EQ. 'S') I=0
      IF (C .EQ. 'P') I=1
      IF (C .EQ. 'D') I=2
      IF (C .EQ. 'F') I=3
      IF (C .EQ. 'G') I=4
      IF (C .EQ. 'H') I=5
      IF (C .EQ. 'I') I=6
      IF (C .EQ. 'K') I=7
      IF (C .EQ. 'A') I=8
      IF (C .EQ. 'M') I=9
      IF (C .EQ. '.') I=0

      IDAM = I

      RETURN
      END

iduser.f/       1553528659  5006  320   100644  3165      `
      SUBROUTINE IDUSER (USER, HOST)
C****************************************************************
C***  IDENTIFICATION OF PROGRAM USERS, AND USER STATISTICS
C****************************************************************

C***  FILENAME DES BENUTZERVERZEICHNISSES, DEFINIERT IN INSTALL
      COMMON / COMWRUS / WRUSFIL
      CHARACTER*255 WRUSFIL
C***  Operating System
      COMMON / COMOS / OPSYS
      CHARACTER*8 OPSYS

cccc  Note: With some INTEL ifort compiler GETENV made rubbish when the 
cccc   shell variable LOGNAME (i.e. the user name) is longer than 
cccc   the provided field. Therefore it is now read into a longer field
cccc   and clipped afterwards (19-Apr-2010)
      CHARACTER FILENAME*255, LINE*80, USER*8, ACTPAR*60, HOST*8
     > ,TMPUSER*99
      CHARACTER*80 CLINE

C***  Link data to identify program version
      CHARACTER LINK_DATE*30, LINK_USER*10, LINK_HOST*60
      COMMON / COM_LINKINFO / LINK_DATE, LINK_USER, LINK_HOST

C***  Identify Link Data (program Version)
      WRITE (*,'(2A)') '>>> Program Version from ', LINK_DATE
      WRITE (*,'(4A)') '>>> created by ', LINK_USER(:IDX(LINK_USER)),
     >      ' at host ', LINK_HOST(:IDX(LINK_HOST))

C***  workstation version:
      IF (OPSYS .EQ. 'UNIX') THEN 
C***     Workaround for LOGNAME longer than 8 chars:     
         CALL GETENV ('LOGNAME', TMPUSER)
         USER = TMPUSER(1:8)
         CALL GETENV ('HOSTNAME', HOST)
C***  Search for dot in HOST and remove the rest
         DO I=1, 8
           IF (HOST(I:I) .EQ. '.') THEN
             HOST = HOST( :I-1)
             EXIT
           ENDIF
         ENDDO
      ELSE 
         PRINT *, 'OPERATING SYSTEM NOT IMPLEMENTED'
         STOP 'ERROR IN IDUSER'
      ENDIF

C***  Skip the USER check, if $LOGNAME is empty -- 
C***   -- for http-demon, wrh 22-Jan-2004 11:25:40
      IF (USER .EQ. '' ) THEN
         LINE = '$LOGNAME is empty - user not identified'
         USER = 'unknown'
         GOTO 4
      ENDIF

      OPEN (1, FILE=WRUSFIL, STATUS='OLD', ERR=99)
    3 READ (1, '(A)', END=10) LINE
        CALL SARGV(LINE, 1, ACTPAR)
        IF (ACTPAR .EQ. 'INFO') THEN
          CALL SARGP (LINE, N, 2, IAS, IAE)
          PRINT *, LINE(IAS: IDX(LINE))
        ENDIF
        IF (USER .EQ. LINE(1:8)) GOTO 4
      GOTO 3

   10 CONTINUE
      PRINT *, ' '
      PRINT *, '*****************************************************'
      PRINT *, '*** USER IDENTIFICATION: ', USER 
      PRINT *, '*** (Please ask the Administrator to add your name  '
      PRINT *, '*** to wrplot.dir/admin.dir/wruser.dat)'
ccc      PRINT *, '*** YOU ARE NOT PERMITTED TO USE THIS PROGRAM!'
      PRINT *, '*****************************************************'
      PRINT *, ' '
ccc      STOP 'PERMISSION DENIED'
      RETURN

    4 CONTINUE
      CLOSE (1)
      PRINT *, ' '
      PRINT *, '*****************************************************'
      PRINT *, '*** USER IDENTIFICATION: ', LINE( :IDX(LINE))
      PRINT *, '*****************************************************'
      PRINT *, ' '

      RETURN

C**** ERROR EXIT ********************************************************
   99 CONTINUE
      RETURN

      END

