       DO IDX=LEN(TEXT),1,-1
          IF(TEXT(IDX:IDX).NE.' ') RETURN
       ENDDO
       IDX=0
       RETURN

       END
incom.f/        1641134587  5006  320   100644  12348     `
	SUBROUTINE INCOM(IMAX,JMAX,IMAXINS,R,T,F,RINS,FINS
     >                  ,TINS,STEP,ISOFOR,SLOPE
     >                  ,IHEAD,LETTX,LETTY,LEVDIM,ILEV,FLEV
     >                  ,XKAST,YKAST,PPCM,ISYMB,GRSIZE
     >                  ,SXMIN,SYMIN,FMIN,FMAX,ERRFLAG, SSIZE, MONO,
     >                  MAXT, MAXR, MAXINS, IWRSYM, WRSYMS, INPNAME,
     >                  KASDEFLINES, NKDLINES, BPORTRAIT)
C**********************************************************************
C***   DETAILED DECODING OF INPUT DATASET 
C***   CALLED FROM SUBR. INDAT (ISOPLOT-PROGRAM)
C**********************************************************************

      LOGICAL MONO, SECONDSET, BPORTRAIT, BSORT(2)

      integer jmax(MAXT)	! Aktuelle Belegung des Radiusarrays
      real r(MAXT,MAXR)	! alle Radiuswerte
      real f(MAXT,MAXR)	! zugehoerige Funktionswerte
      real t(MAXT)		! Alle Temperaturpunkte

        REAL RINS(MAXINS)
        REAL FINS(MAXINS)
        REAL TINS(MAXINS)

      CHARACTER*255 INPNAME, FILENAME2
      CHARACTER*20 ACTPAR, SETNAME2
      character*72 ihead	! Headline des Plots
      character*72 lettx	! X-Achsentext
      character*72 letty	! Y-Achsentext
      integer ilev		! Aktuelle Anzahl diskreter Levelwerte
      real flev(levdim)	! diskrete Levelwerte
      real xkast(6)		! alles, was die x-Achse beschreibt
      real ykast(6)		! alles, was die y-Achse beschreibt
      real ppcm		! Pixel per cm. Aufloesung der Rechnung
      real fmin,fmax		! Minimum und Maximum der Funktion
      logical errflag		! .TRUE., falls Fehler aufgetaucht
      CHARACTER ISOFOR*12, OPERATOR
      CHARACTER*80 KASDEFLINES(100)

C***  local Variables
      character oline*80,line*80, BS*1
      character kasnam*80
      REAL XDUMMY(MAXR), YDUMMY(MAXR), RIVEC(MAXR), FIVEC(MAXR)

C***  typed Subroutines
      character*255 grossb

      BS = CHAR(92)

C***  DEFAULT VALUES:
C***  ===============

C***  ISYMB = SYMBOL FUER GRID
      ISYMB = 14

C***  GRSIZE = GROESSE DES SYMBOLS
      GRSIZE = 0.2

C***  SSIZE = CHARCTER SIZE FOR ISOLINE LABELS
      SSIZE = 0.2

C***  POSITIONING OF PLOT (X,Y OF LEFT-LOWER CORNER, IN CM)
C***  NOTE: CAN PRESENTLY NOT BE INFLUENCED FROM DATA OPTION
      SXMIN = 4.0
      SYMIN = 3.0

C***  RESOLUTION (PIXEL PER CM)
      PPCM = 50.
   
C***  STEP = ISOLINE SPACING: DEFAULT --> 20 LINES BETWEEN MIN, MAX
      STEP = .0

C***  ISOFOR = FORMAT FOR ISOLINE LABELS
      ISOFOR='F4.1'

C***  SLOPE = OPTION FOR INCLINED INTERPOLATION
      SLOPE = .0

C***  RESET VALUES FOR SYMBOL AND SYMBOLSIZE OF WRPLOT-OUTPUT
      IWRSYM = 6
      WRSYMS = 0.008

C***  Arithmetic with second dataset
      SECONDSET = .FALSE.

C***  Buffer for KASDEF lines
      NKDLINES=0

C***  Orientation
      BPORTRAIT = .FALSE.

C **  vor einlesen der neuen Daten, die alten loeschen
      imax=0
      IMAXINS = 0
      lettx=' '
      letty=' '
      ihead=' '
      MONO = .FALSE.
      xkast(1)=.0
      ykast(1)=.0
      logx=0
      logy=0
	step=0.0

	ilev=0
	isofor=' '   
	errflag=.FALSE.

110   READ (100, 1001, ERR=980, END=900) OLINE
      LINE=GROSSB(OLINE)
      if (line(1:1) .eq. '*')    goto 110
      if (line(1:4) .eq. 'TYPE') goto 110
      if (line(1:3) .eq. 'END')  goto 200
      if (line(1:4) .eq. 'STEP') goto  14
      if (line(1:4) .eq. 'KAST') goto 500
      if (line(1:4) .eq. 'FORM') goto 50
      if (line(1:5) .eq. 'SLOPE') goto 60
      if (line(1:4) .eq. 'HEAD') goto 70
      if (line(1:5) .eq. 'LEVEL') goto 80
      IF (LINE(1:4) .EQ. 'MONO' ) GOTO 81
      IF (LINE(1:6) .EQ. 'WRPLOT') GOTO 470
      if (line(1:2) .eq. 'T=')   goto 30
      IF (LINE(1:1) .EQ. BS) THEN
         NKDLINES = NKDLINES + 1
         IF (NKDLINES .LT. 100) THEN
            KASDEFLINES(NKDLINES) = OLINE
         ELSE
            PRINT *, 'WARNING: TOO MANY KASDEF LINES - SKIPPING:'
            PRINT *, LINE(:IDX(LINE))
         ENDIF
         GOTO 110
      ENDIF

      IF (LINE(:6) .EQ. 'DIVIDE') THEN 
         OPERATOR = '/'
         GOTO 300
      ENDIF
      IF (LINE(:10) .EQ. 'DIFFERENCE') THEN
         OPERATOR = '-'
         GOTO 300
      ENDIF

C***  Zeilen ohne Schluesselworte = Radius und Funktionswerte
      if (imax .EQ. 0) then
         write(*,*)'Diese Zeile sollte nach einer',
     >	  ' Temperaturzeile (T=...) stehen!'
         write(*,*)line
         write(*,*)'Die Zeile wird ignoriert!'
         goto 110
      endif

      if (jmax(imax) .eq. MAXR) then
        write(*,*)'Mehr als ',MAXR,' Radiuswerte. Datenpunkt ignoriert'
      else
        CALL SARGV (LINE, 2, ACTPAR)
        IF (ACTPAR(1:1) .NE. '?') THEN
          JMAX(IMAX) = JMAX(IMAX) + 1
          READ (LINE,*,ERR=20) R(IMAX,JMAX(IMAX)), F(IMAX,JMAX(IMAX))

          IF (SECONDSET) THEN
             READ (30,'(A)', ERR=902) LINE
             READ (LINE,*,ERR=20) R2, F2
             IF (R(IMAX,JMAX(IMAX)) .NE. R2) STOP '*** troubles 3 ***'
             IF (OPERATOR .EQ. '/') THEN
              IF (F2 .EQ. .0) THEN
                WRITE (*,*) 'Second Value =0 at T=', T2 , ' and R=', R2
                F2 = 1E-6
              ENDIF
              F(IMAX,JMAX(IMAX)) = F(IMAX,JMAX(IMAX)) / F2
             ELSEIF (OPERATOR .EQ. '-') THEN
              F(IMAX,JMAX(IMAX)) = F(IMAX,JMAX(IMAX)) - F2
             ENDIF
          ENDIF
c marke
        ELSE
          IMAXINS = IMAXINS + 1
          TINS(IMAXINS) = T(IMAX)
          CALL SARGV (LINE, 1, ACTPAR)
          READ(ACTPAR,'(F10.0)') RINS(IMAXINS)
        ENDIF
      endif
      goto 110
20    write(*,*)'Diese Zeile ist wohl Schwachsinn'
      write(*,*)' (zumindest an dieser Stelle.)'
      write(*,*)line
      write(*,*)'Sie wird daher ignoriert'
      goto 110

C**** Temperaturpunkte einlesen
30    IMAX = IMAX + 1
      READ (LINE,'(2X,F10.0)') T(IMAX)
C***  JMAX(I)= Zahl der Radiuspunkte bei T(I)
      JMAX(IMAX)=0
C***  If second dataset to be read:
      IF (SECONDSET) THEN
         READ (30, '(A)', END=902) LINE     
         IF (LINE(1:2) .EQ. 'T=') THEN
            READ (LINE,'(2X,F10.0)') T2
            IF (T(IMAX) .NE. T2) STOP '***** troubles ***'
         ELSE 
            STOP '***** troubles 2 ***'
         ENDIF
      ENDIF
      GOTO 110

C***  Step fuer ISOPLOT einlesen
14    read(line,'(5x,f10.0)') step
      goto 110

C***  einlesen des Kastennamens
500   kasnam=line(8:)
      goto 110

C***  Format fuer Isolinienbeschriftung ****
50    isofor=line(8:)
      goto 110

C***  INCLINED INTERPOLATION WITH "SLOPE"
60    READ (LINE(7:),*) SLOPE
      GOTO 110

C***  Einlesen des Headers
70    ihead=oline(8:)
      goto 110

C***  Einlesen diskreter Niveauwerte
80    CALL SARGC (LINE(6:),NPAR)
      L = NPAR-1
      read(line(6:),*) LDUMMY, (FLEV(LL),LL=ILEV+1,ILEV+L)
      ILEV=ILEV+L
      goto 110

81    MONO = .TRUE.
      GOTO 110

470   CALL SARGV (LINE,2,ACTPAR)
      ID = IDX(ACTPAR)
      READ (ACTPAR(1:ID),'(I10)') IWRSYM
      CALL SARGV (LINE,3,ACTPAR)
      READ (ACTPAR,'(BN,F20.0)') WRSYMS
      GOTO 110

C***  "DIVIDE" option: open and position file for second dataset
  300 SECONDSET = .TRUE.
      CALL SARGV (OLINE, 3, SETNAME2)
      CALL SARGC (OLINE, NPAR)
      IF (NPAR .GT. 4) THEN
         CALL SARGV (OLINE, 5, FILENAME2)
      ELSE
         FILENAME2 = INPNAME
      ENDIF          
      OPEN (30, FILE=FILENAME2, ERR=350)

C***  SEARCH FOR THE BEGINNING OF THAT DATASET
  301 READ (30, '(A)', END=901) LINE
      IF (LINE( :6) .NE. '*NAME:') GOTO 301
      READ (30, '(A)', END=901) LINE
      IF (LINE .NE. SETNAME2) GOTO 301
      
  302 READ (30, '(A)', END=901) LINE     
      IF (LINE(1:2) .NE. 'T=')   GOTO 302
      BACKSPACE 30
      GOTO 110

200   if (imax .le. 1 .or. imax .gt. MAXT) goto 210
      do 201 i=1,imax
      if (jmax(i) .le. 0 .or. jmax(i) .gt. MAXR) goto 220
201   continue

C***  steigende folge der Temperaturwerte pruefen
      DO I=2,IMAX
        IF (T(I) .LE. T(I-1)) THEN
          IWRONG = I
          GOTO 351
        ENDIF
      ENDDO

C***  Sort columns in falling sequence - wrh 31-Jul-2021
      BSORT(1) = .TRUE.  ! sort in falling sequence
      BSORT(2) = .TRUE.  ! replace identical points by their average 
      DO I=1, IMAX
        JMAXI = JMAX(I)
        DO J=1, JMAXI
           RIVEC(J) = R(I,J)
           FIVEC(J) = F(I,J)
        ENDDO   
        CALL QUICKSORT (RIVEC, FIVEC, MAXR, JMAXI, BSORT, XDUMMY,YDUMMY)
        DO J=1, JMAXI
           R(I,J) = RIVEC(J)
           F(I,J) = FIVEC(J)
        ENDDO   
      ENDDO

C***  Einlesen der Kastendefinitionen
C***  Positionieren auf "Kasnam"
       rewind(100)

600   READ (100,1001,ERR=980,END=950) LINE
      LINE = GROSSB(LINE)
      IF (LINE .NE. KASNAM) GOTO 600
C***  Einlesen einer Zeile und pruefen des Schluesselwortes
610   oline=' '
      read(100,1001,err=980,end=800)oline
      line=grossb(oline)
      if (line(1:3) .eq. 'END')  goto 800
      if (line(1:4) .eq. 'XKAS') goto 710
      if (line(1:4) .eq. 'YKAS') goto 720
      if (line(1:4) .eq. 'XLET') goto 730
      if (line(1:4) .eq. 'YLET') goto 740
      if (line(1:4) .eq. 'PPCM') goto 750
      if (line(1:4) .eq. 'GRID') goto 760
      if (line(1:4) .eq. 'LOGX') logx=1
      if (line(1:4) .eq. 'LOGY') logy=1
      if (LINE(1:5) .EQ. 'SSIZE') GOTO 770
      IF (LINE(1:8) .EQ. 'PORTRAIT') BPORTRAIT = .TRUE.
      goto 610

710   READ(LINE(5:),*)XKAST
      GOTO 610
720   READ(LINE(5:),*)YKAST
      GOTO 610
730   LETTX=OLINE(6:)
      GOTO 610
740   LETTY=OLINE(6:)
      GOTO 610
750   READ (LINE(5:),*)PPCM
      GOTO 610
760   READ (LINE(5:),*) ISYMB, GRSIZE
      GOTO 610
770   READ (LINE(6:),*)SSIZE
      GOTO 610

C***  Ende der Kastendaten erreicht
  800 CONTINUE
      IF (XKAST(1) .EQ. 0.) THEN
        XKAST(1) = 20. / (XKAST(3) - XKAST(2))
      ENDIF
      IF (YKAST(1) .EQ. 0.) THEN
        YKAST(1) = 15. / (YKAST(3) - YKAST(2))
      ENDIF

      if (xkast(1) .eq. .0 .or. ykast(1) .eq. .0) goto 940

c***  MIN-MAX-SUCHE VON F
      FMIN=F(1,1)
      FMAX=FMIN
      DO 390 I=1,IMAX
      JMAXI=JMAX(I)
      DO 390 J=1,JMAXI
      FMAX=AMAX1(FMAX,F(I,J))
      FMIN=AMIN1(FMIN,F(I,J))
390   CONTINUE

C***   Stufe zwischen den Isolinien: DEFAULT = 20 BETWEEN MIN/MAX
C***   Ge"andert auf 10, Lars  9-Aug-1996 12:12:55
C!!!       IF (STEP .EQ. 0.0) STEP = (FMAX-FMIN)/20.0
       IF (STEP .EQ. 0.0) STEP = (FMAX-FMIN)/10.0

C***   FORMAT FUER DIE ISOLINIENBESCHRIFTUNG: ADD PARANTHESES
       ISOFOR='('//ISOFOR
       ISOFOR(IDX(ISOFOR)+1:)=')'

C***  Logarithmieren von T und/oder R
      DO 395 I=1,IMAX
      IF (LOGX .EQ. 0) GOTO 396
      IF (T(I) .LE. 0) GOTO 391
      T(I)=ALOG10(T(I))
396   IF (LOGY .EQ. 0) GOTO 395
      JMAXI=JMAX(I)
      DO 397 J=1,JMAXI
         IF (R(I,J) .LE. .0) GOTO 391
         R(I,J)=ALOG10(R(I,J))
397   CONTINUE
395   CONTINUE

      DO 501 I=1,IMAXINS
        IF (LOGX .EQ. 0) GOTO 510
        IF (TINS(I) .LE. 0.) GOTO 391
        TINS(I) = ALOG10(TINS(I))
510     CONTINUE
        IF (LOGY .EQ. 0) GOTO 501
        IF (RINS(I) .LE. 0.) GOTO 391
        RINS(I) = ALOG10(RINS(I))
501   CONTINUE

C***  =========
	RETURN
C***  =========


10	ERRFLAG = .TRUE.

C***  =========
	RETURN
C***  =========




C***  Fehlerzweige
210   write(6,*)'Fehler: Zahl der Temperaturpunkte'
      goto 10

220   write(6,*)'Fehler: Zahl der radiuspunkte'
      goto 10

350   WRITE (6,*) '*** ERROR: cannot open second input file:'
      WRITE (6,*) 'Filename: ', FILENAME2(:IDX(FILENAME2))
      GOTO 10

351   write(6,*)'Datenfehler : T nicht in steigender Reihenfolge'
      write (6,'(A,I3,A, G12.2)') 'T(', IWRONG-1, ')=', T(IWRONG-1)
      write (6,'(A,I3,A, G12.2)') 'T(', IWRONG  , ')=', T(IWRONG  )
      goto 10

391   write(6,*)'Datenfehler : R oder T kleiner als 0'
      goto 10

900   write(6,*)'Datensatz nicht gefunden'
      goto 10

901   write(6,*)'Error: Second dataset not found!'
      print *, 'second dataset name:', setname2 
      print *, 'second filename    :', filename2(:idx(filename2)) 
      goto 10

902   write(6,*)'Error: Second dataset finished too early!'
      print *, 'second dataset name:', setname2 
      print *, 'second filename    :', filename2(:idx(filename2)) 
      goto 10

940   write(6,*)'Kastenachsen nicht definiert'
      goto 10

950   write(6,*)'Kastendaten nicht gefunden. Name :',kasnam
      goto 10

980   PRINT *, 'Datenfile Lesefehler'
      STOP 'ERROR'

1001  format(A)

	end
indat.f/        1628779298  5006  320   100644  2332      `
      SUBROUTINE INDAT (R, F, T, RINS, FINS, TINS, IMAXINS, JMAX, 
     >                  IMAX, FMIN, FMAX, PPCM, 
     >                  ISYMB, GRSIZE, SXMIN, SYMIN, ILEV, FLEV,
     >                  XKAST, YKAST, IHEAD, LETTX, LETTY, SSIZE, 
     >                  MONO, STEP, ISOFOR, SLOPE, MAXT, MAXR, 
     >                  MAXINS, IWRSYM, WRSYMS, NAME, INPNAME,
     >                  KASDEFLINES, NKDLINES, BPORTRAIT)

C**********************************************************************
C***  CALLED FROM: ISOPRO
C***  HANDLES INTERACTIVE COMMAND INPUT,
C***  AND STARTS READING THE DATA FILE
C**********************************************************************

      CHARACTER*(*) NAME
      CHARACTER*255 LINE, GROSSB, INPNAME
      CHARACTER*80 KASDEFLINES(100)

      LOGICAL ERRFLAG, BPORTRAIT, MONO

C***  INTERACTIVE COMMAND INPUT:
10    PRINT *, 'NAME OF ISODATA-SET  (<RETURN> for first set, 
     > <CTRL D> for end):'
      READ (5, '(A)', END=990, ERR=10) NAME
      IF (IDX(NAME) .EQ. 0) THEN
        NAME = '0'
      ENDIF
      NAME = GROSSB(NAME) 
C***  REMOVE LEADING BLANKS
   20 IF (NAME(1:1) .EQ. ' ') THEN
         NAME = NAME(2:)
         GOTO 20
      ENDIF

C***  COMMAND IS ASSUMED TO GIVE A DATASET NAME
C***  ===============================================

C***  SEARCH FOR THE BEGINNING OF THAT DATASET
      REWIND 100
100   LINE=' '
      READ (100, '(A)', ERR=980, END=900) LINE
      IF (LINE( :6) .NE. '*NAME:') GOTO 100
      READ (100, '(A)', ERR=980, END=900) LINE
      LINE=GROSSB(LINE)
      IF (LINE .NE. NAME .AND. NAME .NE. '0') GOTO 100

C***  READ DATA IN DATASET 
      CALL INCOM(IMAX,JMAX,IMAXINS,R,T,F
     >                  ,RINS,FINS,TINS,STEP,ISOFOR, SLOPE
     >                  ,IHEAD,LETTX,LETTY,50,ILEV,FLEV
     >                  ,XKAST,YKAST,PPCM,ISYMB,GRSIZE
     >                  ,SXMIN,SYMIN,FMIN,FMAX,ERRFLAG,ssize,mono,
     >                  MAXT, MAXR, MAXINS, IWRSYM, WRSYMS, INPNAME,
     >                  KASDEFLINES, NKDLINES, BPORTRAIT)

      IF (ERRFLAG) GOTO 10

C     ======
      RETURN
C     ======

C***  ERROR MESSAGES

900	WRITE (6,*) 'DATENSATZ NICHT GEFUNDEN'
	GOTO 10

980	WRITE (6,*) '***** FEHLER BEIM lESEN DER EINGABEDATEI'
        STOP '***** ERROR in INDAT (ISOPRO)'

990	STOP 'O.K. in INDAT (ISOPRO)'

      END
infits.f/       1730308099  5006  320   100644  17402     `
      SUBROUTINE INFITS (FITSNAM, FITSCOM, X, Y, NDAT, NDATMAX, 
     >                   NSETMAX, ISET, BIMAGE, 
     >                   NDATMAXIM, NSETMAXIM, IMPARMAX, ZIM, XIMPAR,
     >                   ISETIM, XKIND4, YKIND4, YKIND4HELP)


C*************************************************************
C***  INTERPRETS FTIS HEADER AND READS DATA FROM A FITS FILE
C***    CALLED FROM SUBROUTINE READDATA
C*************************************************************

      DIMENSION X(NDATMAX, NSETMAX), Y(NDATMAX, NSETMAX)
      DIMENSION NDAT(NSETMAX)

      CHARACTER FITSNAM*(*), FITSCOM*(*), LINE*80, COMMENT*80
      CHARACTER*20 ACTPAR, ACTPAR2, ACTPAR3, VALUE
      CHARACTER CTYPE1*20, LOCALNAME*255, CCOMMAND*266

      PARAMETER (MAXDIM=100)
     
      LOGICAL SIMPLE, EXTEND, ANYF, BIMAGE, ISNAN

      DIMENSION ZIM(NDATMAXIM, NSETMAXIM)
      DIMENSION XIMPAR(NSETMAXIM, IMPARMAX)

C***  WARNING: THE INTEGER TYPE DECLARATION DOES MATCH TO THE 
C***           IMPLICIT TYPES
      INTEGER NAXES(MAXDIM), PCOUNT, GCOUNT, FUNIT
      INTEGER BLOCKSIZE, BITPIX

      CHARACTER*12 TTYPE(MAXDIM), TFORM(MAXDIM), TUNIT(MAXDIM),
     >             EXTNAME
      CHARACTER BS*1

C***  32-bit interface to libfitsio
      REAL*4 XKIND4(NDATMAX), YKIND4(NDATMAX), YKIND4HELP(NDATMAX)
      REAL*4 CRVAL1, CDELT1, CRPIX1, DUMMYNUL
ccc      INTEGER*4 ISTATUS

C***  dummy real*4 variable
      PARAMETER (DUMMYNUL = .0)

C***  backslash
      BS = CHAR(92)

C***  Fits-file fortran channel and error status
      FUNIT  = 10
      ISTATUS=0

C***  default Row for BINTABLE
      NROW=1

C***  default Values for BINTABLE
      STARTN=-999.
      DELTAN=0.
      CRPIX1=1.
      
C***  Open fits file
      CALL MY_FITSOPEN (FUNIT, FITSNAM, ISTATUS)

C*    Debug:      
c      WRITE (*,*) 'Opened: FITSNAM=',FITSNAM( :IDX(FITSNAM))

      IF (ISTATUS .NE. 0) THEN
           WRITE (*,*) 'ERROR RETURNED FROM SUBR. MY_FITSOPEN: STATUS=',
     >                 ISTATUS
           STOP 'FATAL ERROR IN SUBROUTINE INFITS'
      ENDIF
	   
      CALL FTGHPR (FUNIT, MAXDIM, SIMPLE, BITPIX, NAXIS, NAXES, PCOUNT, 
     >             GCOUNT, EXTEND, ISTATUS)

      IF (ISTATUS .NE. 0) THEN
         WRITE (*,*) 'ERROR RETURNED FROM SUBR. FTGHPR: STATUS=',ISTATUS
         STOP 'FATAL ERROR IN SUBROUTINE INFITS'
      ENDIF

C***  LOOP over all INFITS Options----------
    1 CONTINUE

      CALL SARGV (FITSCOM, 1, ACTPAR2)

C***  ENTRY COMMENTED:
      IF (ACTPAR2(1:1) .EQ. '*') THEN
        ISHL = 1
        GOTO 20
      ENDIF

C***  INTERPRETATION OF THE COMMAND LINE FITSCOM
      IF (ACTPAR2 .EQ. 'INFO' .OR. ACTPAR2 .EQ. 'SHORTINFO' .OR. 
C***                    ----                     ---------
     >    ACTPAR2 .EQ. 'SHORT-INFO') THEN
C***                    ----------
C***     INFO REQUESTED
         WRITE (*,'(/,A,A)') 'FITSCOM=',FITSCOM( :IDX(FITSCOM))

         ISHL = 1
         IF (ACTPAR2 .EQ. 'INFO') THEN
          WRITE (*,'(/,2A)') 
     >         'Long INFO on FITS File: ', FITSNAM(:IDX(FITSNAM))
C***    Number of (Header + Data) Units (HDU)
          CALL FTGHDN (FUNIT, NHDU)
          
C***    Loop over all units
         DO NN=1, NHDU 
C***     Select Unit
          CALL FTMAHD (FUNIT, NN, HDUTYPE, ISTATUS)
          WRITE (*,*) '================================================'
          WRITE (*,*) 'Number of HDU:     ', NN
          WRITE (*,*) ' '
          I = 0
    5     I = I + 1
          CALL FTGREC (FUNIT, I, LINE, ISTATUS)
          CALL SARGV (LINE, 1, ACTPAR)
          IF (ACTPAR .EQ. 'BITPIX' .OR.
     >        ACTPAR .EQ. 'NAXIS' .OR.
     >        ACTPAR .EQ. 'NAXIS1' .OR.
     >        ACTPAR .EQ. 'NAXIS2' .OR.
     >        ACTPAR .EQ. 'NAXIS3' .OR.
     >        ACTPAR .EQ. 'EXTEND' .OR.
     >        ACTPAR .EQ. 'DATE' .OR.
     >        ACTPAR .EQ. 'DATE-OBS' .OR.
     >        ACTPAR .EQ. 'TIME-OBS' .OR.
     >        ACTPAR .EQ. 'TARGNAME' .OR.
     >        ACTPAR .EQ. 'OBJECT' .OR.
     >        ACTPAR .EQ. 'RA_TARG' .OR.
     >        ACTPAR .EQ. 'DEC_TARG' ) WRITE (*,*) LINE( :IDX(LINE))
          IF (ACTPAR .NE. 'END' .AND. ISTATUS .EQ. 0) GOTO 5
C***    Binary Table Information
          CALL FTGHBN (FUNIT, MAXDIM, NROWS, NTFIELDS, TTYPE, TFORM,
     >                 TUNIT, EXTNAME, VARIDAT, ISTATUS)
          IF (ISTATUS .EQ. 0) THEN
             WRITE (*,*)
             WRITE (*,*) 'Binary Table: (', NROWS, ' Rows )'
             DO NM=1, NTFIELDS
                CALL FTGTDM (FUNIT, NM, MAXDIM, NNAXIS, NNAXES, ISTATUS)
                WRITE (*,*) 'Col.: ', TTYPE(NM), '[', TUNIT(NM), ']',
     >                      ' FMT=  ', TFORM(NM)
             ENDDO
          ENDIF
          ISTATUS=0
         ENDDO
C***   Back to first Unit
        CALL FTMAHD (FUNIT, 1, HDUTYPE, ISTATUS)

        ELSE
         WRITE (*,*) '==============================================='
         WRITE (*,*) 'SHORT INFO on FITS File: ',FITSNAM(:IDX(FITSNAM))
         WRITE (*,*) '==============================================='
         I = 0
    6     I = I + 1
          CALL FTGREC (FUNIT, I, LINE, ISTATUS)
          CALL SARGV (LINE, 1, ACTPAR)
          IF (ACTPAR .EQ. 'DATE' .OR.
     >        ACTPAR .EQ. 'DATE-OBS' .OR.
     >        ACTPAR .EQ. 'OBJECT' .OR.
     >        ACTPAR .EQ. 'TIME-OBS' .OR.
     >        ACTPAR .EQ. 'TARGNAME') WRITE (*,*) LINE( :IDX(LINE))
          IF (ACTPAR .NE. 'END' .AND. ISTATUS .EQ. 0) GOTO 6
        ENDIF
        WRITE (*,*) '==============================================='

      ELSE IF (ACTPAR2 .EQ. 'NHDU') THEN
C***                         ----
         ISHL = 2
         CALL SARGVR (FITSCOM, 2, ACTPAR)
         READ (ACTPAR,'(10X,I10)') NN

C***    Select Unit
         CALL FTMAHD (FUNIT, NN, HDUTYPE, ISTATUS)

      ELSE IF (ACTPAR2 .EQ. 'NROW') THEN
C***                         ----
         ISHL = 2
         CALL SARGVR (FITSCOM, 2, ACTPAR)
         READ (ACTPAR,'(10X,I10)') NN

C***    Select Row
         NROW = NN

      ELSE IF (ACTPAR2 .EQ. 'NSTART') THEN
C***                         ------
         ISHL = 2
         CALL SARGVR (FITSCOM, 2, ACTPAR)
         READ (ACTPAR,'(F20.0)') STARTN
         PRINT *,'STARTN=',STARTN

      ELSE IF (ACTPAR2 .EQ. 'DN') THEN
C***                         ------
         ISHL = 2
         CALL SARGVR (FITSCOM, 2, ACTPAR)
         READ (ACTPAR,'(F20.0)') DELTAN
         PRINT *,'DELTAN=',DELTAN

      ELSE IF (ACTPAR2 .EQ. 'ROW' .OR. ACTPAR2 .EQ. 'ROWS') THEN
C***                         ---
        CALL SARGVR (FITSCOM, 2, ACTPAR)
        IF (ACTPAR2 .EQ. 'ROW') THEN 
           ISHL = 2
           READ (ACTPAR,'(10X,I10)') IROW
        ELSE
           ISHL = 3
           READ (ACTPAR,'(10X,I10)') IROW1
           CALL SARGVR (FITSCOM, 3, ACTPAR)
           READ (ACTPAR,'(10X,I10)') IROW2
        ENDIF
        ISTATUS=0
        CALL FTGKEY (FUNIT, 'CTYPE1', CTYPE1, COMMENT, ISTATUS)
          IF (ISTATUS .NE. 0) 
     >       WRITE (*,*) 'SUBROUTINE INFITS: CTYPE1 NOT FOUND'
        ISTATUS=0
        CALL FTGKYJ (FUNIT, 'NAXIS1', NAXIS1, COMMENT, ISTATUS)
          IF (ISTATUS .NE. 0) 
     >       WRITE (*,*) 'SUBROUTINE INFITS: NAXIS1 NOT FOUND'
        ISTATUS=0
        CALL FTGKYJ (FUNIT, 'NAXIS2', NAXIS2, COMMENT, ISTATUS)
C***      Debug:
c          IF (ISTATUS .NE. 0) 
c     >       WRITE (*,*) 'SUBROUTINE INFITS: NAXIS2 NOT FOUND'

        ISTATUS=0
        CALL FTGKYE (FUNIT, 'CRPIX1', CRPIX1, COMMENT, ISTATUS)
          IF (ISTATUS .NE. 0) THEN
             WRITE (*,*) 'SUBROUTINE INFITS: CRPIX1 NOT FOUND'
     >       , ' SET TO DEFAULT CRPIX1= 1.'
             CRPIX1 = 1.        
C***      Debug:
c          ELSE 
c             PRINT *, 'CRPIX1=', CRPIX1
          ENDIF


        ISTATUS=0
        CALL FTGKYE (FUNIT, 'CRVAL1', CRVAL1, COMMENT, ISTATUS)
          IF (ISTATUS .NE. 0) THEN
             WRITE (*,*) 'SUBROUTINE INFITS: CRVAL1 NOT FOUND'
C***      Debug:
c          ELSE
c             PRINT *, 'CRVAL1=', CRVAL1
          ENDIF
          ISTAT_CRVAL1 = ISTATUS

        ISTATUS=0
        CALL FTGKYE (FUNIT, 'CDELT1', CDELT1, COMMENT, ISTATUS)
           IF (ISTATUS .EQ. 0) THEN
C***      Debug:
c              PRINT *, 'CDELT1=', CDELT1
           ELSE   
C             try alternative keyword CD1_1
              ISTATUS=0
              CALL FTGKYE (FUNIT, 'CD1_1', CDELT1, COMMENT, ISTATUS)
C***      Debug:
c              PRINT *, 'CD1_1=', CDELT1
           ENDIF
        IF (ISTATUS .NE. 0) THEN
             WRITE (*,*) 
     >       'SUBROUTINE INFITS: neither CDELT1 nor CD1_1 found'        
        ENDIF
        ISTAT_CDELT1 = ISTATUS

        NDAT(ISET) = NAXIS1
        IF (NDAT(ISET) .GT. NDATMAX) GOTO 97
        DO II=1, NAXIS1
          XKIND4(II) = FLOAT(II)
        ENDDO

        IF (ACTPAR2 .EQ. 'ROW') THEN 
          ISTATUS=0
          CALL FTGPVE (FUNIT, 0, NAXIS1*(IROW-1)+1, NAXIS1, DUMMYNUL, 
     >                 YKIND4(1), ANYF, ISTATUS)
        ELSE
C***      keyword ROWS: read each ROW into YKIND4HELP and add to YKIND4
          DO II=1, NAXIS1
             YKIND4(II) = .0
          ENDDO
          DO IROW=IROW1, IROW2
             ISTATUS=0
             CALL FTGPVE (FUNIT, 0, NAXIS1*(IROW-1)+1, NAXIS1, DUMMYNUL, 
     >                    YKIND4HELP, ANYF, ISTATUS)
             IF (ISTATUS .NE. 0) THEN
                WRITE (*,*) 'ERROR related to option ROW:'
                GOTO 99
             ENDIF
             DO II=1, NAXIS1
                YKIND4(II) = YKIND4(II) + YKIND4HELP(II)
             ENDDO
          ENDDO
        ENDIF

        IF (ISTAT_CRVAL1 .EQ. 0 .AND. ISTAT_CDELT1 .EQ. 0) THEN
           DO II=1, NDAT(ISET)
              XKIND4(II) = CRVAL1 + (FLOAT(II)-CRPIX1) * CDELT1
           ENDDO
        ENDIF
       

      ELSE IF (ACTPAR2 .EQ. 'BINTABLE') THEN
C***                         --------

        ISHL = 3

        CALL SARGC (FITSCOM, NREST)
        IF (NREST .LT. 3) THEN
           WRITE (*,'(/,A)') 
     >                 '*** BINTABLE needs two subsequent parameters'
           WRITE (*,*) '*** specifying the column names for X and Y'
           GOTO 99
        ENDIF
C***    First column --> X-data
        CALL SARGVL (FITSCOM, 2, ACTPAR)
C***    Second column --> Y-data
        CALL SARGVL (FITSCOM, 3, ACTPAR3)

        IF (ACTPAR .EQ. '@N' .AND. ACTPAR3 .EQ. '@N') THEN
          WRITE (*,'(/,A)') 
     >                '*** BINTABLE needs two subsequent parameters'
          WRITE (*,*) '*** specifying the column names for X and Y'
          WRITE (*,*) '*** which cannot be both the index @N'
          GOTO 99
        ENDIF 

C***    First column --> X-data
        IF (ACTPAR .NE. '@N') THEN

           CALL FTGCNO (FUNIT, .FALSE., ACTPAR, NCOL, ISTATUS)
           IF (ISTATUS .NE. 0) THEN
	      WRITE (*,'(/,A)') 
     >          'SUBROUTINE INFITS: CANNOT FIND COLUMN ' // ACTPAR
              GOTO 98
	   ENDIF
C***      Column Information
           CALL FTGTDM (FUNIT, NCOL, MAXDIM, NNAXIS, NNAXES, ISTATUS)
           IF (NNAXES .EQ. 1) THEN
              CALL FTGKYS (FUNIT, 'NAXIS2', VALUE, COMMENT, ISTATUS)
              IF (ISTATUS .NE. 0) THEN
	         WRITE (*,'(/,A)') 
     >          'CANNOT FIND COLUMN INFORMATION FOR ' // ACTPAR
                 GOTO 99
              ENDIF
              READ (VALUE, '(I20)') NNAXES 
           ENDIF
           NDAT(ISET) = NNAXES
           IF (NDAT(ISET) .GT. NDATMAX) GOTO 97

C***       Read-in X Data 
           CALL FTGCVE (FUNIT, NCOL, NROW, 1, NNAXES, DUMMYNUL,
     >                  XKIND4, ANYF, ISTATUS)

        ENDIF

C***    Second column --> Y-data
        IF (ACTPAR3 .NE. '@N') THEN
              CALL FTGCNO (FUNIT, .FALSE., ACTPAR3, NCOL, ISTATUS)
           IF (ISTATUS .NE. 0) THEN
	      WRITE (*,'(/,A)') 
     >          'SUBROUTINE INFITS: CANNOT FIND COLUMN ' // ACTPAR3
              GOTO 98
	   ENDIF
           CALL FTGTDM (FUNIT, NCOL, MAXDIM, NNAXIS, NNAXES, ISTATUS)
           IF (NNAXES .EQ. 1) THEN
              CALL FTGKYS (FUNIT, 'NAXIS2', VALUE, COMMENT, ISTATUS)
              IF (ISTATUS .NE. 0) THEN
	         WRITE (*,'(/,A)') 'CANNOT FIND HEADER ENTRY NAXIS2'
                 GOTO 99
              ENDIF
                 
              READ (VALUE, '(I20)') NNAXES 
           ENDIF
           NDAT(ISET) = NNAXES
           IF (NDAT(ISET) .GT. NDATMAX) GOTO 97

C***       Read-in Y Data 
           CALL FTGCVE (FUNIT, NCOL, NROW, 1, NNAXES, DUMMYNUL,
     >                     YKIND4, ANYF, ISTATUS)
        ENDIF
	   
C***    Fill @N column with index
        IF (ACTPAR .EQ. '@N') THEN
           DO II=1, NNAXES
              XKIND4(II) = FLOAT(II) 
           ENDDO
        ENDIF
        IF (ACTPAR3 .EQ. '@N') THEN
           DO II=1, NNAXES
              YKIND4(II) = FLOAT(II) 
           ENDDO
        ENDIF

      ELSE IF (ACTPAR2 .EQ. 'IMEXT' .AND. BIMAGE) THEN
C***                         -----
        write (*,*) '*** ERROR -- this branch is not working'
        STOP 'Keyworg IMEXT is not allowed in INFITS'

ccc     The rest of this block is dead code
        ISHL = 1
        ISTATUS=0
        CALL FTGKYE (FUNIT, 'CD1_1', CD1_1, COMMENT, ISTATUS)
          IF (ISTATUS .NE. 0) 
     >       WRITE (*,*) 'SUBROUTINE INFITS: CD1_1 NOT FOUND'
        ISTATUS=0
        CALL FTGKYE (FUNIT, 'CRPIX1', CRPIX1, COMMENT, ISTATUS)
          IF (ISTATUS .NE. 0) 
     >       WRITE (*,*) 'SUBROUTINE INFITS: CRPIX1 NOT FOUND'
        ISTATUS=0
        CALL FTGKEY (FUNIT, 'CTYPE1', CTYPE1, COMMENT, ISTATUS)
          IF (ISTATUS .NE. 0) 
     >       WRITE (*,*) 'SUBROUTINE INFITS: CTYPE1 NOT FOUND'
        ISTATUS=0
        CALL FTGKYJ (FUNIT, 'NAXIS1', NAXIS1, COMMENT, ISTATUS)
          IF (ISTATUS .NE. 0) 
     >       WRITE (*,*) 'SUBROUTINE INFITS: NAXIS1 NOT FOUND'
        ISTATUS=0
        CALL FTGKYJ (FUNIT, 'NAXIS2', NAXIS2, COMMENT, ISTATUS)
          IF (ISTATUS .NE. 0) 
     >       WRITE (*,*) 'SUBROUTINE INFITS: NAXIS2 NOT FOUND'
        ISTATUS=0
        CALL FTGKYE (FUNIT, 'CRVAL1', CRVAL1, COMMENT, ISTATUS)
          IF (ISTATUS .NE. 0)
     >       WRITE (*,*) 'SUBROUTINE INFITS: CRVAL1 NOT FOUND'
          print *, 'CRVAL1=',CRVAL1
          ISTAT_CRVAL1 = ISTATUS
        ISTATUS=0
        CALL FTGKYE (FUNIT, 'CDELT1', CDELT1, COMMENT, ISTATUS)
          IF (ISTATUS .NE. 0)
     >       WRITE (*,*) 'SUBROUTINE INFITS: CDELT1 NOT FOUND'
          print *, 'CDELT1=',CDELT1
          ISTAT_CDELT1 = ISTATUS

        ISTATUS=0
        XIMPAR(ISETIM, 1) = NAXIS
        XIMPAR(ISETIM, 2) = NAXIS1
        XIMPAR(ISETIM, 3) = NAXIS2
        XIMPAR(ISETIM, 4) = 2.
        XIMPAR(ISETIM, 5) = 2.
        write (*,*) '-------infits : isetim =',isetim

ccc        CALL FTGPVE (FUNIT, 0, 1, NAXIS1*NAXIS2, 0, ZIMFT(1,ISETIM), 
ccc     >               ANYF, ISTATUS)

ccc     End of dead code for image

      ELSE
        WRITE (*,*) 'FITSCOM CANNOT BE INTERPRETATED'
        WRITE (*,*) 'FITSCOM=', FITSCOM(:IDX(FITSCOM))
        STOP 'ERROR IN INFITS'
      ENDIF

   20 CONTINUE
      CALL SARGC (FITSCOM, N)
      IF (N .GT. ISHL) THEN
        CALL SARGREST (FITSCOM, N, ISHL+1, IFIRST, ILAST)
        FITSCOM = FITSCOM(IFIRST:ILAST)
        GOTO 1
      ENDIF
C******* END OF LOOP ******************************************


      CALL FTCLOS (FUNIT, ISTATUS)
      IF (ISTATUS .NE. 0) THEN
        WRITE (*,*) 'ERROR WHEN CLOSING FITS FILE'
        GOTO 99
      ENDIF

C***  Back storage with type conversion 
C***  and omission of NaN (not a number) entries
      III = 0
      DO II=1, NDAT(ISET)
C        Trick to identify NaN: Nan is not equal to anything
         IF (XKIND4(II) .NE. XKIND4(II) .OR. 
     >       YKIND4(II) .NE. YKIND4(II) ) CYCLE
         III = III + 1
         Y(III,ISET) = YKIND4(II)
         X(III,ISET) = XKIND4(II)
      ENDDO
      NDAT(ISET) = III

C***  Equidistant wavelength scale using options NSTART and DW
      IF (STARTN .NE. -999. .AND. DELTAN .EQ. .0 .OR.
     >    STARTN .EQ. -999. .AND. DELTAN .NE. .0) THEN
	 WRITE (*,*) 'ERROR: for equidistant X scale, options'
         WRITE (*,*) 'NSTART and DN must be set both!'  
         GOTO 99
      ENDIF  
      IF (STARTN .NE. -999.) THEN
         DO II=1, NDAT(ISET)
            X(II,ISET) = (II-1)* DELTAN + STARTN
        ENDDO
      ENDIF
      RETURN

C***  Error branches  *******************************************
   97 CONTINUE
      WRITE (*,'(/,A)') '*** DATASET HAS MORE ENTRIES THAN DIMENSIONED:'
      WRITE (*,'(A,I8)') '*** DATASET ENTRIES:', NDAT(ISET)
      WRITE (*,'(A,I8)') '*** DIMENSIONED    :', NDATMAX
      WRITE (*,'(A, I8)') 
     >        '*** solution: ' // BS // 'SET_NDATMAX =', NDAT(ISET)
      GOTO 99
   
   98 CONTINUE
C***  read number of TFIELDs
      ISTATUS=0
      CALL FTGKYS (FUNIT, 'TFIELDS', VALUE, COMMENT, ISTATUS)
      IF (ISTATUS .NE. 0) THEN
         WRITE (*,'(/,A,I3)') 'NO TFIELDS PRESENT IN THIS HDU ', NN
         GOTO 99
      ENDIF
      READ (VALUE, '(I20)') NTFIELDS 

      WRITE (*,'(/,A,I3)') 'TFIELDS PRESENT IN THIS HDU: ', NTFIELDS
      DO IFIELD = 1, NTFIELDS
         WRITE (ACTPAR3, '(I4)') IFIELD 
         CALL FLUSHLEFT (ACTPAR3)
         ACTPAR = 'TTYPE' // ACTPAR3(:IDX(ACTPAR3))
         CALL FTGKYS (FUNIT, ACTPAR(:IDX(ACTPAR)), VALUE, COMMENT, 
     >                ISTATUS)
         WRITE (*,*) ACTPAR, VALUE
      ENDDO

   99 WRITE (*,'(A, I5)') '*** DATASET =', ISET
      STOP '*** FATAL ERROR DETECTED BY INFITS'

      END
inpo1d.f/       1553528659  5006  320   100644  2619      `
      SUBROUTINE INPO1D (FY,Y,F,R,JMAXI,I,MONO,MAXT)

C*************************************************************
C***  Subroutine inpo1d : 1-DIM. Interpolation fuer ISOPRO:
C***      spezielle Datenversorgung! Dient zur Interpolation im 
C***      Radius bei einem gegebenem Temperatur-Index I
C***  CALLED FROM: INPO2D
C*************************************************************

      DIMENSION F(MAXT,1),R(MAXT,1)

C***  The following COMMON-Block is also defined in INPO2D 
      PARAMETER ( MAXHILF = 100 )
      COMMON /HILF/ RHILF(MAXHILF), FRHILF(MAXHILF), FTHILF(MAXHILF),
     >              MHCHECK

      COMMON/COEF/COP(4,70,70)

C***   COMMON /CUBI/: TRANSFER OF POLYNOMIAL COEFFICIENTS TO SUBR. CUBIC
       COMMON/CUBI/P1,P2,P3,P4
       LOGICAL MONO       

C***   Safety Check 
       IF ( MHCHECK .NE. MAXHILF) THEN
          WRITE (*,*) '*** Different dimension MAXHILF detected:' 
          WRITE (*,'(A,I5)') '*** in INPO2D:', MHCHECK
          WRITE (*,'(A,I5)') '*** in INPO1D:', MAXHILF
          STOP '*** ERROR detected in INPO1D'
       ENDIF
 
C***  BRANCH FOR ONLY ONE R POINT AT THAT TEMPERATURE --> CONSTANT VALUE
       IF (JMAXI .EQ. 1) THEN
         FY = F(I,1)
         RETURN
         ENDIF

C***  FIND INDEX INTERVAL (Y BETWEEN R(J-1) AND R(J))
       J=1
1      J=J+1
       IF (Y.LT.R(I,J) .AND. J .LT. JMAXI) GOTO 1
       JM1=J-1

C***  BRANCH FOR ONLY TWO R POINTS AT THAT TEMPERATURE --> LINEAR INTERPOLATION
C***  - THIS BRANCH IS ALSO USED IN CASE OF EXTRAPOLATION!
       IF (JMAXI .EQ. 2
     >    .OR.  Y .LT. R(I,JMAXI)  .OR.  Y .GT. R(I,1)
     >    ) THEN
          P=(R(I,J)-Y)/(R(I,J)-R(I,JM1))
          Q=1.-P
          FY=P*F(I,JM1)+Q*F(I,J)
          RETURN
          ENDIF

C***  TIME-SAVING RE-USE OF POLYNOMIAL COEFFICIENTS IF THOSE ARE ALREADY STORED
      IF (COP(2,I,JM1) .NE.0.) THEN 
          DR1=Y-R(I,JM1)
          DR2=R(I,J)-Y
          FY=COP(1,I,JM1)*DR1*DR1*DR1 +COP(2,I,JM1)*DR1+
     +      COP(3,I,JM1)*DR2*DR2*DR2 +COP(4,I,JM1)*DR2

      ELSE

C***  ELSE: INTERPOLATE, STORE COEFFICIENTS FOR FUTURE
       IF (JMAXI .GT. MAXHILF) THEN
          WRITE (*,*) '*** Dimension insufficient:'
          WRITE (*,'(A, I5)') '*** presently: MAXHILF=', MAXHILF
          WRITE (*,'(A, I5)') '*** needed   : MAXHILF=', JMAXI
          STOP '*** ERROR in INPO1D'
       ENDIF

       DO 4 L=1,JMAXI
       FRHILF(L)=F(I,L)
4      RHILF(L)=R(I,L)

       CALL CUBIC (FY,Y,FRHILF,RHILF,J,JMAXI,MONO)
       COP(1,I,JM1) = P1
       COP(2,I,JM1) = P2
       COP(3,I,JM1) = P3
       COP(4,I,JM1) = P4
      ENDIF

       RETURN
       
       END

inpo2d.f/       1553528659  5006  320   100644  1800      `
C************************************************************
C***    Subroutine INPO2D  Interpolation in einem 2D-Gitter *
C***    CALLED FROM: SUBR. ISOREC (ISOPLOT-PROGRAM)
C************************************************************

       Subroutine INPO2D (FINTE,INSIDE,X,Y,SLOPE,
     >          R,F,T,IMAX,JMAX,MONO,MAXT,MAXR)
       
       DIMENSION R(MAXT,MAXR), F(MAXT,MAXR), T(MAXT), JMAX(MAXT)

C***   The same COMMON-Block must be defined in INPO1D
       PARAMETER ( MAXHILF = 100 )
       COMMON /HILF/ RHILF(MAXHILF), FRHILF(MAXHILF), FTHILF(MAXHILF),
     >               MHCHECK

       LOGICAL MONO
       
       MHCHECK = MAXHILF

C****  BESTIMME I SO, DASS T(I-1) .LE. X .LE. T(I)
       IF (X .LT. T(1) .OR. X .GT. T(IMAX) ) GOTO 90
       I=1
1      I=I+1
       IF (X .GT. T(I) .AND. I .LT. IMAX) GOTO 1
       
C***   LINEARE INTERPLOATIONSGEWICHTE
       P = (T(I)-X) / (T(I)-T(I-1))
       Q = 1.-P
       
C***   LIEGT (X,Y) "INSIDE"
       RMAX = P * R(I-1,1) + Q * R(I,1)
       IF (Y .GT. RMAX) GOTO 90
       RMIN = P * R(I-1,JMAX(I-1)) + Q * R(I,JMAX(I))
       IF (Y .LT. RMIN) GOTO 90
       INSIDE=1

ccc    altenative version: not interpolation in pounded-up corners
       if (.true.) then
        if (y .gt. R(I,1) .or. y .lt. R(I,JMAX(I))) inside=0  
       endif
       
C***   Interpolation bei gegebenem r fuer +/- 2 Indexwerte um x
       IA=MAX0(I-2,1)
       IB=MIN0(I+1,IMAX)
       DO 10 L=IA,IB
C***   Interpolation mit steigung slope
       YY = Y + SLOPE * (T(L)-X)
10     CALL INPO1D (FTHILF(L), YY, F, R, JMAX(L), L, MONO, MAXT)
C***   Interpolation in R
       CALL CUBIC (FINTE, X, FTHILF, T, I, IMAX, MONO)
       
C      ======
99     RETURN
C      ======

C***   Ausserhalb des Gitterbereiches
90     INSIDE=0
       GOTO 99

       END
insert.f/       1553528659  5006  320   100644  3094      `
       SUBROUTINE INSERT(R,F,T,R2,F2,T2,RINS,FINS,TINS,
     >                   IMAXINS,JMAX,JMAX2,IMAX, SLOPE, MONO,
     >                   MAXT, MAXR, MAXINS)

       INTEGER JMAX(MAXT), JMAX2(MAXT)
       REAL RINS(MAXINS), FINS(MAXINS), TINS(MAXINS)
       REAL T(MAXT), R(MAXT,MAXR), F(MAXT,MAXR)
       REAL T2(MAXT), R2(MAXT,MAXR), F2(MAXT,MAXR)

       LOGICAL MONO

       COMMON /COEF/ COP(4,70,70)

C***   LOOP OVER ALL GRIDPOINTS, WHICH HAVE TO BE INSERTED
       DO 10 IINS=1,IMAXINS
C***   FIND TEMPERATURE INDEX OF INSERT POINT
         IND = 0
15       IND = IND + 1
         IF (T(IND) .NE. TINS(IINS) .AND. IND .LE. IMAX) GOTO 15

C***   SET UP THE NEW THE NEW GRID (T2,R2,F2)
         IF (IND .LE. IMAX) THEN
           IMAX2 = IMAX - 1
           DO 20 I=IND,IMAX2
             JMAX2(I) = JMAX(I+1)
             T2(I) = T(I+1)
             DO 30 J=1, JMAX2(I)
               R2(I,J) = R(I+1,J)
               F2(I,J) = F(I+1,J)
30           CONTINUE
20         CONTINUE

           DO 40 I=1,IND-1
             JMAX2(I) = JMAX(I)
             T2(I) = T(I)
             DO 50 J=1, JMAX2(I)
               R2(I,J) = R(I,J)
               F2(I,J) = F(I,J)
50           CONTINUE
40         CONTINUE

         ELSE
           print *, 'Hier Programmierfehler! MAX undefinded!' 
           print *, 'found by wrh 18-Dec-2003'
           print *, 'Unklar, muss bei Bedarf berichtigt werden'
           stop '*** ERROR IN SUBROUITINE INSERT' 
           IMAX2 = MAX
           DO 60 I=1,IMAX
             JMAX2(I) = JMAX(I)
             T2(I) = T(I)
             DO 70 J=1, JMAX2(I)
               R2(I,J) = R(I,J)
               F2(I,J) = F(I,J)
70           CONTINUE
60         CONTINUE

         ENDIF

C*** INITIALIZE ARRAY COP IN ORDER TO AVOID INTERFERENCES OF DIFFERENT GRIDS
      DO 502  JC=1,MAXR
      DO 502  IC=1,MAXT
      DO 502  LC=1,4
502   COP(LC,IC,JC) = 0.

C***  INTERPOLATE THE F-VALUE
        CALL INPO2D(FINS(IINS), INSIDE, TINS(IINS), RINS(IINS), 
     >              SLOPE, R2, F2, T2, IMAX2, JMAX2, MONO,
     >              MAXT, MAXR)

10     CONTINUE

C***  INSERT THE THE POINTS IN THE ORIGINAL GRID
       DO 110 IINS=1,IMAXINS
C***   FIND TEMPERATURE INDEX OF INSERT POINT
         IND = 0
120      IND = IND + 1
         IF (T(IND) .NE. TINS(IINS) .AND. IND .LE. IMAX) GOTO 120
C***   FIND RADIUS INDEX OF INSERT POINT
         IND2 = 0
130      IND2 = IND2 + 1
         IF (RINS(IINS) .LT. R(IND,IND2) .AND. IND2 .LT. JMAX(IND)) 
     >       GOTO 130
         JMAX(IND) = JMAX(IND) + 1
         DO 140 I=JMAX(IND),IND2+1,-1
           R(IND,I) = R(IND,I-1)
           F(IND,I) = F(IND,I-1)
140      CONTINUE
         R(IND,IND2) = RINS(IINS)
         F(IND,IND2) = FINS(IINS)
110    CONTINUE

C***  OUTPUT OF THE INSERTED POINT AND THEIR INTERPOLATED VALUES
       IF (IMAXINS .GT. 0) WRITE (*,'(1X,A32, I3)') 
     > 'NUMBER OF INTERPOLATED VALUES : ', IMAXINS
       DO 200 IINS=1, IMAXINS
         WRITE (*,'(3(A2,G10.3))') 'T=',TINS(IINS), 'R=',RINS(IINS),
     >                  'F=',FINS(IINS)
200    CONTINUE

       RETURN
       END
intin.f/        1553528659  5006  320   100644  58578     `
      SUBROUTINE INTIN (XINT, YINT, NINTMAX, NINT, NINT2, B, C,
     >              BSAVE, CSAVE, 
     >              KDLINE, NKD, NKDMAX, NKDP,
     >              KDLINE2, NKD2, NKDMAX2,
     >              KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >              BINSEX,
     >              MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, 
     >              TEXTBUTT, INTACT, INTACT2,
     >              X, Y, NDAT, NDATMAX, NSET, NSETMAX, 
     >              ISYMBOL, SSIZE, XCMA, YCMA, TA, ICOLOR, NPEN,
     >              ISELSET, COMMLINE, IACT, 
     >              X1, Y1, ISET, MPACTIVE, NSCRBUTT, HEADER, STRIP,
     >              ISETXERR, ISETYERR, XERRTYPE, YERRTYPE, SETNAME)

C***************************************************************
C***  SUBROUTINE TO PROVIDE INTERACTIVE BRANCH
C***************************************************************

      PARAMETER (NCMDMAX2 = 100)
      PARAMETER (MAXACT = 10)

      COMMON /COMACT/ ACTDRIV
      CHARACTER ACTDRIV*7

C***  Current color index
      COMMON / COMCOLOR / LASTCOLOR

      DIMENSION XINT(NINTMAX), YINT(NINTMAX)
      DIMENSION B(6), C(6), BSAVE(6), CSAVE(6)

      CHARACTER KDLINE(NKDMAX)*132, KDLINE2(NKDMAX2)*132
      CHARACTER SCMD2(NCMDMAX2)*132
      CHARACTER*(*) VAR(MAXVAR,2), HEADER
      DIMENSION POSBUTT(MAXBUTT,MAXRBUTT,2), NSCRBUTT(MAXRBUTT)
      CHARACTER*(*) TEXTBUTT(MAXBUTT,MAXRBUTT)
      CHARACTER*80 MESSAGE(5), COMMLINE
      CHARACTER ACTION*20
      CHARACTER*132 LINE, LINE2, ACTPAR*40, ACTPAR2*40
      CHARACTER*20 INTACT, INTACT2, CMODUS, BGSAVE
      CHARACTER FNAME*255
      CHARACTER*(*) SETNAME(NSETMAX)

      DIMENSION X(NDATMAX,NSETMAX), Y(NDATMAX,NSETMAX)
      DIMENSION X1(NDATMAX), Y1(NDATMAX)
      DIMENSION XCMA(NDATMAX), YCMA(NDATMAX), TA(NDATMAX)
      DIMENSION NDAT(NSETMAX), ICOLOR(NSETMAX), NPEN(NSETMAX)
      DIMENSION ISYMBOL(NSETMAX), SSIZE(NSETMAX)
      DIMENSION XFAKE(2), YFAKE(2)

C***  STORES THE NUMBERS OF SELECTED SETS
      DIMENSION ISELSET(3)

      CHARACTER*20 STACT(MAXACT)

      LOGICAL KDPAUSE, BINSEX

      NKDP2 = 1

      NINTS = NINTMAX - 100
      IF (NINTS .LE. 100) THEN
        STOP 'NINTMAX TOO SMALL IN SUBR INTIN'
      ENDIF

      IF (INTACT .EQ. 'START') THEN
C***  PRESET OF BUTTON POSITIONS
        NBUTT = 5
        IF (NBUTT .GT. MAXRBUTT) THEN
          WRITE (*,*) 'DIMENSION OF BUTTONS NOT SUFFICIENT'
          STOP 'ERROR IN SUBR. INTIN'
        ENDIF
        NACT = 1
        STACT(NACT) = 'START'
        CALL SETBUTT(MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT,
     >               WIDBUTT, HEIBUTT, STACT, NACT, IACT, NSCRBUTT, 
     >               NSET)
        INTACT = 'BASE'
        NACT = 1
        STACT(NACT) = INTACT
      ENDIF

    1 CONTINUE

c      MESSAGE(1) = '&N                                         &N'
c      CMODUS = 'P1BIG'
c      CALL PLOTMESS(B, C,
c     >        KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
c     >        BINSEX,
c     >        MAXBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
c     >        WIDBUTT, HEIBUTT, MESSAGE, 1, 
c     >        KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
c     >        XCMA, YCMA, NDATMAX)

C***  Create actual row of buttons
    2 CONTINUE

      CALL SETBUTT(MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT,
     >             WIDBUTT, HEIBUTT, STACT, NACT, IACT, NSCRBUTT, 
     >             NSET)

C***  PLOT BUTTONS
      CALL PLOTBUTT(B, C,
     >              IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >              BINSEX,
     >              MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, 
     >              WIDBUTT, HEIBUTT, 
     >              KDLINE2, NKD2, NKDMAX2, NKDP2, STACT, NACT, 
     >              XCMA, YCMA, NDATMAX)

   15 CONTINUE

C***  PLOT OF THE OLD DATAPOINTS
      CALL PLOTPOINT (B, C,
     >                IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >                BINSEX,
     >                MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT,
     >                WIDBUTT, HEIBUTT,
     >                KDLINE2, NKD2, NKDMAX2, NKDP2, XINT, YINT, NINT, 
     >                XCMA, YCMA, NDATMAX)

      NINT2 = 0
C***  ENTRY POINT FOR MENU POINTS
   10 CONTINUE
      IF (ACTDRIV .EQ. 'X11OWN') THEN
          CALL X_GINPUT (XCM, YCM)
      ELSE
        WRITE (*,*) '>>>> Driver Mismatch <<<<<<<'
        STOP        '>>>> FATAL ERROR IN SUBR. INTIN <<<<'
      ENDIF
        XINT(NINTS+NINT2+1) = XCM / B(1) + B(2)
        YINT(NINTS+NINT2+1) = YCM / C(1) + C(2)

C***  BUTTON KLICKED?
        CALL RECBUTT(MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, 
     >               WIDBUTT, HEIBUTT, XCM, YCM, INTACT2, NACT)

C----------------------------------------------------------------
C---  MENU-INDEPENDENT BUTTONS FOR SCROLLING
C----------------------------------------------------------------
      IF (INTACT2( :IDX(INTACT2)) .EQ. '>>') THEN
        NSCRBUTT(NACT) = NSCRBUTT(NACT) + 1
        GOTO 2
      ENDIF
      IF (INTACT2( :IDX(INTACT2)) .EQ. '<<') THEN
        NSCRBUTT(NACT) = NSCRBUTT(NACT) - 1
        GOTO 2
      ENDIF

C----------------------------------------------------------------
C---  MENU : BASE -----------------------------------------------
C----------------------------------------------------------------
      IF (STACT(1) .EQ. 'BASE' .AND.
     >    NACT .EQ. 1) THEN
        IF (INTACT2( :IDX(INTACT2)) .EQ.      'POINTS') THEN
C---                                           ------
          NACT = NACT + 1
          STACT(NACT) = INTACT2
          INTACT = INTACT2
          GOTO 1
        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'BOUND') THEN
C---                                           -----
          NACT = NACT + 1
          STACT(NACT) = INTACT2
          INTACT = INTACT2
C*** PRINT NEW BOUNDARIES
          CMODUS = 'P1NOR'
          WRITE(MESSAGE(1),'(4(A,F10.2))') 
     >          'L=', B(2), ' R=', B(3), ' D=',C(2), ' U=', C(3)

          CALL PLOTMESS(B, C,
     >            KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >            BINSEX,
     >            MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
     >            WIDBUTT, HEIBUTT, MESSAGE, 1, 
     >            KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >            XCMA, YCMA, NDATMAX)

          GOTO 2
C*** PLOT OLD BOUNDARIES
          CMODUS = 'P1NOR'
          WRITE(MESSAGE(1),'(4(A,F10.2))') 
     >          'L=', B(2), ' R=', B(3), ' D=',C(2), ' U=', C(3)
          CALL PLOTMESS(B, C,
     >            KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >            BINSEX,
     >            MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
     >            WIDBUTT, HEIBUTT, MESSAGE, 1, 
     >            KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >            XCMA, YCMA, NDATMAX)

          GOTO 2
        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'DATASETS') THEN
C---                                           --------
          NACT = NACT + 1
          STACT(NACT) = INTACT2
          INTACT = INTACT2
          GOTO 1
        ELSEIF (INTACT2( :IDX(INTACT2)) .EQ.  'QUIT') THEN 
C---                                           ----
          MESSAGE(1) = 'Press RETURN to continue'
          CMODUS = 'P1BIG'
          CALL PLOTMESS(B, C,
     >            KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >            BINSEX,
     >            MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
     >            WIDBUTT, HEIBUTT, MESSAGE, 1, 
     >            KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >            XCMA, YCMA, NDATMAX)

          GOTO 20
        ELSE
          GOTO 10
        ENDIF
      ENDIF
C---  END OF MENU POINTS ---------------------------------------


C----------------------------------------------------------------
C---  MENU : BASE-POINTS ----------------------------------------
C-----------------^^^^^^-----------------------------------------
      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'POINTS' .AND.
     >    NACT .EQ. 2) THEN

        IACT = 1

        IF (INTACT2( :IDX(INTACT2)) .EQ.      'BACK') THEN
C---                                           ----
          NACT = NACT - 1
          INTACT = STACT(NACT)
          GOTO 1
        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'REFRESH') THEN
C---                                           -------
          CALL WIPE(B, C,
     >              KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >              BINSEX,
     >              KDLINE2, NKD2, NKDMAX2, NKDP2, XCMA, YCMA, NDATMAX)
          GOTO 20
        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'ADD_POINTS') THEN
C---                                           ----------
          IF (NINT2 .EQ. 0) THEN
            MESSAGE(1) = 'No Points added'
            CMODUS = 'P1BIG'
            CALL PLOTMESS(B, C,
     >              KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >              BINSEX,
     >              MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
     >              WIDBUTT, HEIBUTT, MESSAGE, 1, 
     >              KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >              XCMA, YCMA, NDATMAX)

          ELSE
            DO I = 1, NINT2
              XINT(NINT+I) = XINT(NINTS+I)
              YINT(NINT+I) = YINT(NINTS+I)
            ENDDO
            NINT = NINT + NINT2
            IF (NINT .GE. NINTS) THEN
              STOP 'NINTMAX TO SMALL HERE, ERROR IN SUBR. INTIN'
            ENDIF
            NINT2 = 0
            MESSAGE(1) = 'Points added'
            CMODUS = 'P1BIG'
            CALL PLOTMESS(B, C,
     >              KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >              BINSEX,
     >              MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
     >              WIDBUTT, HEIBUTT, MESSAGE, 1, 
     >              KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >              XCMA, YCMA, NDATMAX)

            GOTO 15
c            CALL WIPE(B, C,
c     >                KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
c     >                BINSEX,
c     >                KDLINE2, NKD2, NKDMAX2, NKDP2, XCMA, YCMA, NDATMAX)
c            INTACT2 = 'REFRESH'
c            GOTO 20
          ENDIF

        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'DEL_ALL_P') THEN
C---                                           ----------
          IF (NINT .EQ. 0) THEN
            MESSAGE(1) = 'No Points deleted'
            CMODUS = 'P1BIG'
            CALL PLOTMESS(B, C,
     >              KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >              BINSEX,
     >              MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
     >              WIDBUTT, HEIBUTT, MESSAGE, 1, 
     >              KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >              XCMA, YCMA, NDATMAX)

            GOTO 10
          ELSE
            NINT = 0
            CALL WIPE(B, C,
     >                KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >                BINSEX,
     >                KDLINE2, NKD2, NKDMAX2, NKDP2, 
     >                XCMA, YCMA, NDATMAX)
            INTACT2 = 'REFRESH'
            GOTO 20
          ENDIF

        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'DEL_POINTS') THEN
C---                                           ----------
          IF (NINT2 .EQ. 0) THEN
            MESSAGE(1) = 'No Points deleted'
            CMODUS = 'P1BIG'
            CALL PLOTMESS(B, C,
     >              KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >              BINSEX,
     >              MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
     >              WIDBUTT, HEIBUTT, MESSAGE, 1, 
     >              KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >              XCMA, YCMA, NDATMAX)

            GOTO 10
          ELSE
            DO I=1, NINT2
              XCM1 = (XINT(NINTS+I) - B(2)) * B(1)
              YCM1 = (YINT(NINTS+I) - C(2)) * C(1)
               J = 0
  424          J = J + 1
                XCM2 = (XINT(J) - B(2)) * B(1)
                YCM2 = (YINT(J) - C(2)) * C(1)
c        write (*,*) xcm1, ycm1, xcm2, ycm2
                IF (ABS(XCM1-XCM2) .LT. 0.3 .AND.
     >              ABS(YCM1-YCM2) .LT. 0.3) THEN
                  NINT = NINT - 1
                  DO K=J, NINT
                    XINT(K) = XINT(K+1)
                    YINT(K) = YINT(K+1)
                  ENDDO
                ENDIF
              IF (J .LT. NINT) GOTO 424
            ENDDO
            CALL WIPE(B, C,
     >                KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >                BINSEX,
     >                KDLINE2, NKD2, NKDMAX2, NKDP2, 
     >                XCMA, YCMA, NDATMAX)
            INTACT2 = 'REFRESH'
            GOTO 20
          ENDIF

        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'SORT_POI.') THEN
C---                                           ---------
C***  SORT POINTS
          IF (NINT .EQ. 0) THEN
            MESSAGE(1) = 'There are no Points'
            CMODUS = 'P1BIG'
            CALL PLOTMESS(B, C,
     >              KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >              BINSEX,
     >              MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
     >              WIDBUTT, HEIBUTT, MESSAGE, 1, 
     >              KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >              XCMA, YCMA, NDATMAX)

            GOTO 10
          ELSE
            DO I=1, NINT
              DO J=1, NINT-1
                IF (XINT(J) .GT. XINT(J+1)) THEN
                  TEMP = XINT(J)
                  XINT(J) = XINT(J+1)
                  XINT(J+1) = TEMP
                  TEMP = YINT(J)
                  YINT(J) = YINT(J+1)
                  YINT(J+1) = TEMP
                 ENDIF
              ENDDO
            ENDDO
C***  DELETE CONSECUTIVE SIMILAR POINTS
            IF (NINT .GT. 1) THEN
              I = 0
  432         I = I + 1
                IF (XINT(I) .EQ. XINT(I+1) .AND.
     >              YINT(I) .EQ. YINT(I+1)) THEN
                  DO J=I+1, NINT - 1
                    XINT(J) = XINT(J+1)
                    YINT(J) = YINT(J+1)
                  ENDDO
                  I = I - 1
                  NINT = NINT - 1
                ENDIF
              IF (I .LT. NINT-1) GOTO 432
            ENDIF
            MESSAGE(1) = 'Points sorted'
            CMODUS = 'P1BIG'
            CALL PLOTMESS(B, C,
     >              KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >              BINSEX,
     >              MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
     >              WIDBUTT, HEIBUTT, MESSAGE, 1, 
     >              KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >              XCMA, YCMA, NDATMAX)

          ENDIF

        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'EQUIV.') THEN
C---                                           ------
C***    Calculate Eq.width:

C***    Error branches (less than two interactive points)
          IF (NINT .LT. 2) THEN
            IF (NINT .EQ. 0) THEN
              MESSAGE(1) = 'ERROR: There are no Points'
            ELSE
              MESSAGE(1) = 'ERROR: Second continuum point missing'
            ENDIF
            CMODUS = 'P1BIG'
            CALL PLOTMESS(B, C,
     >              KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >              BINSEX,
     >              MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
     >              WIDBUTT, HEIBUTT, MESSAGE, 1, 
     >              KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >              XCMA, YCMA, NDATMAX)

            GOTO 10
          ELSE IF (NINT .GT. 2) THEN
C***  Eq.width: Branch with more than 2 graphic-input points --> 
C***   integrate graphic-input curve

C***  CHECK MONOTONIC ORDER
            CALL CHECKMONO (XINT, NINT, IORDER, IERR)
            IF (IERR .GT. 0) THEN
              MESSAGE(1) = 
     >          'ERROR: Interactive points not in monotonic sequence'
              CMODUS = 'P1BIG'
              CALL PLOTMESS(B, C,
     >              KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >              BINSEX,
     >              MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
     >              WIDBUTT, HEIBUTT, MESSAGE, 1, 
     >              KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >              XCMA, YCMA, NDATMAX)

              GOTO 10
            ENDIF

C***     INTEGRATION FROM X1(1) TO X1(NDATX1)
          FLUX = 0.
          EQUI = 0.
          DO I=1, NINT
          IF (I .EQ. 1) THEN
            DWX = 0.5 * (XINT(2) - XINT(1))
          ELSE IF (I .EQ. NINT) THEN
            DWX = 0.5 * (XINT(NINT) - XINT(NINT-1))
          ELSE
            DWX = 0.5 * (XINT(I+1) - XINT(I-1))
          ENDIF
          P = (XINT(I) - XINT(1))/(XINT(NINT)-XINT(1))
          CONT = (1.-P) * YINT(1) + P * YINT(NINT)
          EQUI = EQUI + DWX * YINT(I) / CONT
          FLUX = FLUX + DWX * YINT(I)
          ENDDO
          EQUI = (XINT(NINT) - XINT(1) - EQUI) * IORDER
          FLUX = (FLUX - 
     >      0.5*(YINT(NINT)+YINT(1))*(XINT(NINT)-XINT(1))) * IORDER
C***  PRINT EQUIVALENT WIDTH AND LINEFLUX
          WRITE (MESSAGE(1), '(A, A, G12.6, A, G12.6)')
     >         '&EINTERACTIVE POINTS: ',
     >         '  EQ. WIDTH=', EQUI,
     >         '  LINEFLUX=',FLUX
          CMODUS = 'P1BIG'
          CALL PLOTMESS(B, C,
     >            KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >            BINSEX,
     >            MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
     >            WIDBUTT, HEIBUTT, MESSAGE, 1, 
     >            KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >            XCMA, YCMA, NDATMAX)
          WRITE (*,'(/,A)') MESSAGE(1)(3:)

C***      Plot integrated area; add the continuum line
          XINT(NINT+1) = XINT(1)
          YINT(NINT+1) = YINT(1)
          CALL PLOTDAT (XINT, YINT, NINT+1, 5, .0, XCMA, YCMA, B, C, .0, 
     >           'UNIT', VAR, MAXVAR, NVAR, .0, 3, ' ')

C***  Eq.width: Branch with exactly 2 graphic-input points --> 
C***   integrate data curve, take g-input for continuum and boundaries
C***   The actual integration is done below (after asking which dataset)
          ELSE
            NACT = NACT + 1
            STACT(NACT) = INTACT2
            NACT = NACT + 1
            STACT(NACT) = 'SKIP'
            INTACT = INTACT2
            GOTO 2

          ENDIF

          IACT = 2
          
        ELSEIF (INTACT2( :IDX(INTACT2)) .EQ. 'CHK_INCR.') THEN
C---                                           ---------
            MESSAGE(1) = 'BRANCH IS NOT IMPLEMENTED ----------------'
            CMODUS = 'P1BIG'
            CALL PLOTMESS(B, C,
     >              KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >              BINSEX,
     >              MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
     >              WIDBUTT, HEIBUTT, MESSAGE, 1, 
     >              KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >              XCMA, YCMA, NDATMAX)
           GOTO 10

        ELSEIF (INTACT2( :IDX(INTACT2)) .EQ. 'SAVE-ND') THEN
C---                                          -------
C***  SAVE INTERACTIVE POINTS AS XY-TABLE
          NSET = NSET + 1
          IF (NSET .GT. NSETMAX) THEN
            WRITE (0,*) 'NO MORE DATASETS!'
            STOP 'ERROR IN SUBR. INTIN'
          ENDIF
          NDAT(NSET) = NINT
          ISYMBOL(NSET) = 5
          ICOLOR(NSET) = 1
          SSIZE(NSET) = 0.3
          DO I=1, NINT
C            WRITE (10, '(2(A,1P,E15.6))') '  ',XINT(I),'  ', YINT(I)
            X(I,NSET) = XINT(I)
            Y(I,NSET) = YINT(I)
          ENDDO
          WRITE (MESSAGE(1),'(I3,A,I3)') 
     >           NINT,' POINTS SAVED IN DATASET NR.', NSET
C          MESSAGE(1) = NINT,' POINTS SAVED IN DATASET NR.', NSET
          CMODUS = 'P1BIG'
          CALL PLOTMESS(B, C,
     >            KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >            BINSEX,
     >            MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
     >            WIDBUTT, HEIBUTT, MESSAGE, 1, 
     >            KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >            XCMA, YCMA, NDATMAX)


        ELSEIF (INTACT2( :IDX(INTACT2)) .EQ. 'SAVE-XY') THEN
C---                                          -------
C***  SAVE INTERACTIVE POINTS AS XY-TABLE
          OPEN (UNIT=10, FILE='wrplot.xy', STATUS='UNKNOWN', ERR=97)
ccc     >          RECL=132)
          DO I=1, NINT
            WRITE (10, '(2(A,1P,E15.6))') '  ',XINT(I),'  ', YINT(I)
          ENDDO
          CLOSE (10)
          MESSAGE(1) = 'POINTS SAVED IN FILE XY-TABLE'
          CMODUS = 'P1BIG'
          CALL PLOTMESS(B, C,
     >            KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >            BINSEX,
     >            MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
     >            WIDBUTT, HEIBUTT, MESSAGE, 1, 
     >            KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >            XCMA, YCMA, NDATMAX)


        ELSE
C---    ----
          CALL CENSYMO (XCM, YCM, 2, 0.4, 1, ' ')
          NINT2 = NINT2 + 1

C***  END OF IF, ELSE IF, ENDIF
        ENDIF

        IF (NINT2 .GT. 1) THEN
          IF (XINT(NINTS+NINT2) .EQ. XINT(NINTS+NINT2-1) .AND.
     >        YINT(NINTS+NINT2) .EQ. YINT(NINTS+NINT2-1)) THEN
            NINT2 = NINT2 - 1
          ENDIF
        ENDIF
        GOTO 10
      ENDIF
C---  END OF MENU BASE-POINTS ----------------------------------------

C----------------------------------------------------------------
C---  MENU : BASE-POINTS-EQUIV. ---------------------------------
C***  Eq.width: Branch for the case that two interactive points are given

      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'POINTS' .AND.
     >    STACT(3) .EQ. 'EQUIV.' .AND.
     >    STACT(4) .EQ. 'SKIP' .AND.
     >    NACT .EQ. 4) THEN
        IF (INTACT2( :IDX(INTACT2)) .EQ.      'BACK') THEN
C---                                           ----
          NACT = NACT - 2
          INTACT = STACT(NACT)
          IACT = 2
          GOTO 1
        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ.      'ABORT') THEN
C---                                                -----
          NACT = NACT - 2
          INTACT = STACT(NACT)
          IACT = 2
          GOTO 1
        ELSE IF (IDX(INTACT2) .EQ. 0) THEN
C---
          GOTO 10
        ELSE IF (INTACT2 .EQ. 'LAST') THEN
C---                           ----
            ISETOP = NSET
        ELSE
            READ (INTACT2,'(I2)',ERR=2) ISETOP
        ENDIF

C***  CHECK MONOTONIC ORDER
        ND = NDAT(ISETOP)
        CALL CHECKMONO (X(1,ISETOP), ND, IORDER, IERR)
        IF (IERR .GT. 0) THEN
           WRITE (MESSAGE(1),'(A,I3,A)') 
     >       'ERROR: Dataset', ISETOP, ' not in monotonic sequence'
        ELSE IF ((XINT(1)-X( 1,ISETOP)) * 
     >           (XINT(1)-X(ND,ISETOP)) .GT. .0) THEN
           MESSAGE(1) = 'ERROR: First interactive point outside data'
        ELSE IF ((XINT(2)-X( 1,ISETOP)) * 
     >           (XINT(2)-X(ND,ISETOP)) .GT. .0) THEN
           MESSAGE(1) = 'ERROR: Second interactive point outside data'
        ELSE
           MESSAGE(1) = 'NONE'
        ENDIF

        IF (MESSAGE(1) .NE. 'NONE') THEN
           CMODUS = 'P1BIG'
           CALL PLOTMESS(B, C,
     >        KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >        BINSEX,
     >        MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
     >        WIDBUTT, HEIBUTT, MESSAGE, 1, 
     >        KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >        XCMA, YCMA, NDATMAX)
           NACT = NACT - 2
           INTACT = STACT(NACT)
           IACT = 2
           GOTO 1
        ENDIF

        IF (XINT(1) .LT. XINT(2)) THEN
           FROM = XINT(1)
           TO   = XINT(2)
           CONTFROM = YINT(1)
           CONTTO   = YINT(2)
        ELSE
           FROM = XINT(2)
           TO   = XINT(1)
           CONTFROM = YINT(2)
           CONTTO   = YINT(1)
        ENDIF 

C***    Find indices and interpolated values at boundaries
        CALL LIPO_IND (NAF, NBF, FROM, X(1,ISETOP), ND)
        CALL LIPO_IND (NAT, NBT, TO  , X(1,ISETOP), ND)
        CALL LINPO (YFROM, FROM, Y(1,ISETOP), X(1,ISETOP), ND)
        CALL LINPO (YTO  , TO  , Y(1,ISETOP), X(1,ISETOP), ND)

C***    Copy all points (increasing order) including boundaries into X1,Y1 
        X1(1) = FROM
        Y1(1) = YFROM
        IF (IORDER .GT. 0) THEN 
           IFIRST = NBF
           LAST   = NAT
           DO I=IFIRST,LAST
              X1(I-IFIRST+2) = X(I,ISETOP) 
              Y1(I-IFIRST+2) = Y(I,ISETOP) 
           ENDDO
        ELSE
           IFIRST = NBT
           LAST   = NAF
           DO I=IFIRST,LAST
              X1(LAST+2-I) = X(I,ISETOP) 
              Y1(LAST+2-I) = Y(I,ISETOP) 
           ENDDO
        ENDIF 
        NDATX1 = LAST - IFIRST + 3
        X1(NDATX1) = TO
        Y1(NDATX1) = YTO

C***  CALCULATE EQUIVALENT WIDTHS IN ARRAY X1,Y1 :
C***     INTEGRATION FROM X1(1) TO X1(NDATX1)
          FLUX = 0.
          EQUI = 0.
          DO I=1, NDATX1
            IF (I .EQ. 1) THEN
               DWX = 0.5 * (X1(2) - X1(1))
            ELSE IF (I .EQ. NDATX1) THEN
               DWX = 0.5 * (X1(NDATX1) - X1(NDATX1-1))
            ELSE
               DWX = 0.5 * (X1(I+1) - X1(I-1))
            ENDIF
            P = (X1(I) - FROM)/(TO-FROM)
            CONT = (1.-P) * CONTFROM + P * CONTTO
            EQUI = EQUI + DWX * Y1(I) / CONT
            FLUX = FLUX + DWX * Y1(I)
          ENDDO
          EQUI = TO - FROM - EQUI
          FLUX = FLUX - 0.5*(CONTTO+CONTFROM)*(TO-FROM)

C***  PRINT EQUIVALENT WIDTH AND LINEFLUX
          WRITE (MESSAGE(1), '(A, I3, A, G12.6, A, G12.6)')
     >         '&EDATASET=', ISETOP,
     >         '  EQ. WIDTH=', EQUI,
     >         '  LINEFLUX=',FLUX
          CMODUS = 'P1BIG'
          CALL PLOTMESS(B, C,
     >            KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >            BINSEX,
     >            MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
     >            WIDBUTT, HEIBUTT, MESSAGE, 1, 
     >            KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >            XCMA, YCMA, NDATMAX)
          WRITE (*,'(/,A)') MESSAGE(1)(3:)

C***      Plot integrated area; add the continuum points
          X1(NDATX1+1) = XINT(2)
          Y1(NDATX1+1) = YINT(2)
          X1(NDATX1+2) = XINT(1)
          Y1(NDATX1+2) = YINT(1)
          CALL PLOTDAT (X1, Y1, NDATX1+2, 5, -1.0, XCMA, YCMA, B, C, .0, 
     >           'UNIT', VAR, MAXVAR, NVAR, .0, 3, ' ')

          GOTO 10
       ENDIF

C----------------------------------------------------------------
C---  MENU : BASE-BOUND ----------------------------------------
C-----------------^^^^^------------------------------------------
      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'BOUND' .AND.
     >    NACT .EQ. 2) THEN
        IF (INTACT2( :IDX(INTACT2)) .EQ.      'BACK') THEN
C---                                           ----
          NACT = NACT - 1
          INTACT = STACT(NACT)
          GOTO 1

        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'REFRESH') THEN
C---                                           -------
          CALL WIPE(B, C,
     >              KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >              BINSEX,
     >              KDLINE2, NKD2, NKDMAX2, NKDP2, XCMA, YCMA, NDATMAX)
          GOTO 20

        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'RESTORE') THEN
C---                                           -------
          CALL BSTORE (B, C, BSAVE, CSAVE, 'RESTO')
          CMODUS = 'P2NOR'
          MESSAGE(1) = 'BOUNDARIES RESTORED'
          CALL PLOTMESS(B, C,
     >            KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >            BINSEX,
     >            MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
     >            WIDBUTT, HEIBUTT, MESSAGE, 1, 
     >            KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >            XCMA, YCMA, NDATMAX)

          GOTO 10

        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'AUTO') THEN
C---                                           ----
          CALL AUTOS(B, C, X, Y, NDAT, NDATMAX, NSET, NSETMAX, 
     >               INTACT2)
          CMODUS = 'P2NOR'
          MESSAGE(1) = 'BOUNDARIES AUTOMATICALLY ADJUSTED'
          CALL PLOTMESS(B, C,
     >            KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >            BINSEX,
     >            MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
     >            WIDBUTT, HEIBUTT, MESSAGE, 1, 
     >            KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >            XCMA, YCMA, NDATMAX)

          GOTO 10

        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'TICKS') THEN
C---                                           -----
          NACT = NACT + 1
          STACT(NACT) = INTACT2
          GOTO 1

        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'GRAPHICS') THEN
C---                                           --------
          NACT = NACT + 1
          STACT(NACT) = INTACT2
          GOTO 1

        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'MAN') THEN
C---                                           ----
          NACT = NACT + 1
          STACT(NACT) = INTACT2
          GOTO 1
        ENDIF
      ENDIF

C----------------------------------------------------------------
C---  MENU : BASE-BOUND-TICKS -----------------------------------
C-----------------------^^^^^------------------------------------
      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'BOUND' .AND.
     >    STACT(3) .EQ. 'TICKS' .AND.
     >    NACT .EQ. 3) THEN

        IF (INTACT2( :IDX(INTACT2)) .EQ.      'BACK') THEN
C---                                           ----
          NACT = NACT - 1
          INTACT = STACT(NACT)
          GOTO 1

        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'REFRESH') THEN
C---                                           -------
          CALL WIPE(B, C,
     >              KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >              BINSEX,
     >              KDLINE2, NKD2, NKDMAX2, NKDP2, XCMA, YCMA, NDATMAX)
          GOTO 20

        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'AUTO_T') THEN
          CALL AUTOS(B, C, X, Y, NDAT, NDATMAX, NSET, NSETMAX, 'AUTO') 
          GOTO 1
        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'AUTO_XT') THEN 
          CALL AUTOS(B, C, X, Y, NDAT, NDATMAX, NSET, NSETMAX, 'AUTOX') 
          GOTO 1
        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'AUTO_YT') THEN
          CALL AUTOS(B, C, X, Y, NDAT, NDATMAX, NSET, NSETMAX, 'AUTOY')
          GOTO 1
        ENDIF
      ENDIF

C----------------------------------------------------------------
C---  MENU : BASE-BOUND-GRAPHICS---------------------------------
C-----------------------^^^^^^^^---------------------------------
      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'BOUND' .AND.
     >    STACT(3) .EQ. 'GRAPHICS' .AND.
     >    NACT .EQ. 3) THEN

        IF (INTACT2( :IDX(INTACT2)) .EQ.      'BACK') THEN
C---                                           ----
          NACT = NACT - 1
          INTACT = STACT(NACT)
          GOTO 1

        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'REFRESH') THEN
C---                                           -------
          CALL WIPE(B, C,
     >              KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >              BINSEX,
     >              KDLINE2, NKD2, NKDMAX2, NKDP2, XCMA, YCMA, NDATMAX)
          GOTO 20

        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'X&&Y' .OR. 
     >           INTACT2( :IDX(INTACT2)) .EQ. 'X' .OR. 
     >           INTACT2( :IDX(INTACT2)) .EQ. 'Y') THEN
C---                                           ---
          IACT = 1
          BGSAVE = INTACT2
          CMODUS = 'P2NOR'
          MESSAGE(1) = 'GRAPHIC-INPUT OF THE NEW BOUNDARIES'
          CALL PLOTMESS(B, C,
     >            KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >            BINSEX,
     >            MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
     >            WIDBUTT, HEIBUTT, MESSAGE, 1, 
     >            KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >            XCMA, YCMA, NDATMAX)

          IACT = IACT + 1
          GOTO 10
        ELSE 
          IF (IACT .EQ. 2) THEN
            XBNEW = XINT(NINTS+NINT2+1)
            YBNEW = YINT(NINTS+NINT2+1)
          ENDIF
          IF (IACT .EQ. 3) THEN
            IF (BGSAVE( :IDX(BGSAVE)) .EQ. 'X&&Y' .OR. 
     >          BGSAVE( :IDX(BGSAVE)) .EQ. 'X') THEN
              XFAKE(1) = XBNEW
              XFAKE(2) = XINT(NINTS+NINT2+1)
              CALL AUTOS (B, C, XFAKE, YFAKE, 2, 2, 1, 1, 'AUTOX')

            ENDIF
            IF (BGSAVE( :IDX(BGSAVE)) .EQ. 'X&&Y' .OR. 
     >          BGSAVE( :IDX(BGSAVE)) .EQ. 'Y') THEN
              YFAKE(1) = YBNEW
              YFAKE(2) = YINT(NINTS+NINT2+1)
              CALL AUTOS (B, C, XFAKE, YFAKE, 2, 2, 1, 1, 'AUTOY')
            ENDIF
          ENDIF
          CALL CENSYMO (XCM, YCM, 2, 0.4, 1, ' ')
            
          IACT = IACT + 1
          GOTO 10

        ENDIF
      ENDIF

C----------------------------------------------------------------
C---  MENU : BASE-BOUND-MAN--------------------------------------
C-----------------------^^^--------------------------------------
      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'BOUND' .AND.
     >    STACT(3) .EQ. 'MAN' .AND.
     >    NACT .EQ. 3) THEN

        IF (INTACT2( :IDX(INTACT2)) .EQ.      'BACK') THEN
C---                                           ----
          NACT = NACT - 1
          INTACT = STACT(NACT)
          GOTO 1

        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'REFRESH') THEN
