          CALL WIPE(B, C,
     >              KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >              BINSEX,
     >              KDLINE2, NKD2, NKDMAX2, NKDP2, XCMA, YCMA, NDATMAX)
          GOTO 20

        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'LEFT' .OR.
     >      INTACT2( :IDX(INTACT2)) .EQ.      'RIGHT' .OR.
     >      INTACT2( :IDX(INTACT2)) .EQ.      'BOTTOM' .OR.
     >      INTACT2( :IDX(INTACT2)) .EQ.      'TOP') THEN
C---                                           ----
          NACT = NACT + 1
          STACT(NACT) = INTACT2
c          NACT = NACT + 1
c          STACT(NACT) = INTACT2
          INTACT = INTACT2
          GOTO 1

        ELSE
          GOTO 10

        ENDIF

      ENDIF
C----------------------------------------------------------------
C---  MENU : BASE-BOUND-MAN-LEFT...------------------------------
C---------------------------^^^^^^^------------------------------
      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'BOUND' .AND.
     >    STACT(3) .EQ. 'MAN' .AND.
     >    (STACT(4) .EQ. 'LEFT' .OR. 
     >     STACT(4) .EQ. 'RIGHT' .OR. 
     >     STACT(4) .EQ. 'BOTTOM' .OR. 
     >     STACT(4) .EQ. 'TOP') .AND.
     >    NACT .EQ. 4) THEN
        IF (INTACT2( :IDX(INTACT2)) .EQ.      'BACK') THEN
C---                                           ----
          NACT = NACT - 1
          INTACT = STACT(NACT)
          GOTO 1

        ELSE

          IFACT = 0
          VADD = 0.
          
          IF (INTACT2(5:5) .EQ. '%') THEN
            READ (INTACT2(1:4),'(I4)') IFACT
c          write (*,*) 'ifact',ifact
          ELSE
            READ (INTACT2(1:5),'(F5.0)') VADD
c          write (*,*) 'vadd',vadd
          ENDIF

          FACT = (100. + FLOAT(IFACT)) / 100.

C***  MANIPULATE BOUNDARIES
          TX = B(1) * (B(3) - B(2))
          TY = C(1) * (C(3) - C(2))
          IF (STACT(4) .EQ. 'LEFT') THEN
            B(2) = FACT*B(2) + VADD
          ELSE IF (STACT(4) .EQ. 'RIGHT') THEN
            B(3) = FACT*B(3) + VADD
          ELSE IF (STACT(4) .EQ. 'TOP') THEN
            C(3) = FACT*C(3) + VADD
          ELSE IF (STACT(4) .EQ. 'BOTTOM') THEN
            C(2) = FACT*C(2) + VADD
          ENDIF          
          B(1) = TX / (B(3) - B(2))
          C(1) = TY / (C(3) - C(2))
C*** PRINT NEW BOUNDARIES
          CMODUS = 'P1NOR'
          WRITE(MESSAGE(1),'(4(A,F10.2))') 
     >          'L=', B(2), ' R=', B(3), ' D=',C(2), ' U=', C(3)

          CALL PLOTMESS(B, C,
     >            KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >            BINSEX,
     >            MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
     >            WIDBUTT, HEIBUTT, MESSAGE, 1, 
     >            KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >            XCMA, YCMA, NDATMAX)


          GOTO 2


        ENDIF

      ENDIF

C---  END OF BOUND POINTS ---------------------------------------

