          GOTO 2
        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'DATAINFO') THEN
C---                                           --------
          NACT = NACT + 1
          STACT(NACT) = INTACT2
          NACT = NACT + 1
          STACT(NACT) = 'SKIP'
          INTACT = INTACT2
          GOTO 1

        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'SELECT') THEN
C---                                           ------
          NACT = NACT + 1
          STACT(NACT) = INTACT2
          GOTO 1

        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'ATTRIBUTE') THEN
C---                                           --------
          NACT = NACT + 1
          STACT(NACT) = INTACT2
          INTACT = INTACT2
          IACT = 1
          GOTO 1

        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'MANIPULATE') THEN
C---                                           --------
          NACT = NACT + 1
          STACT(NACT) = INTACT2
          INTACT = INTACT2
          GOTO 1

        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'MAN_1') THEN
C---                                           -----
          NACT = NACT + 1
          STACT(NACT) = INTACT2
          INTACT = INTACT2
          GOTO 1

        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'SKIP_LD') THEN
C---                                           -------
          NSET = NSET - 1
          GOTO 2

        ELSE
          GOTO 10
        ENDIF
      ENDIF

C----------------------------------------------------------------
