          STACT(NACT) = INTACT2
          INTACT = INTACT2
          IACT = 1
          COMMLINE = ' '
          GOTO 1

        ENDIF
      ENDIF

C----------------------------------------------------------------
C---  MENU : BASE-DATASET-MANIPULATE-ARI ------------------------
C------------------------------------^^^-------------------------
      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'DATASETS' .AND.
     >    STACT(3) .EQ. 'MANIPULATE' .AND.
     >    STACT(4) .EQ. 'ARI' .AND.
     >    NACT .EQ. 4) THEN
        IF (INTACT2( :IDX(INTACT2)) .EQ.      'ABORT') THEN
C---                                           -----
          IACT = 1
          NACT = NACT - 1
          INTACT = STACT(NACT)
          GOTO 1

        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'EXE') THEN
C---                                           ---
          IACT = 1
          NACT = NACT - 1
          INTACT = STACT(NACT)
          SCMD2(1) = 'COMMAND ARI ' // COMMLINE
          MESSAGE(1) = COMMLINE
            CMODUS = 'P2NOR'
            CALL PLOTMESS(B, C,
     >              KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >              BINSEX,
     >              MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
     >              WIDBUTT, HEIBUTT, MESSAGE, 1, 
     >              KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >              XCMA, YCMA, NDATMAX)

          NCMD2 = 1
          CALL EXCMD (NCMD2, NCMDMAX2, SCMD2, X, Y, X1, Y1, ISET, 
     >                NDAT, NDATMAX, NSET, NSETMAX, ISYMBOL, NPEN, 
     >                ICOLOR, B, C, MPACTIVE, VAR, MAXVAR, NVAR, STRIP,
     >                ISETXERR, ISETYERR, XERRTYPE, YERRTYPE, SETNAME)
          GOTO 1

        ELSE 
C---
          IACT = IACT + 1
          COMMLINE = COMMLINE( :IDX(COMMLINE)) // 
     >               ' ' // INTACT2 // ' '
          MESSAGE(1) = COMMLINE
            CMODUS = 'P2NOR'
            CALL PLOTMESS(B, C,
     >              KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >              BINSEX,
     >              MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
     >              WIDBUTT, HEIBUTT, MESSAGE, 1, 
     >              KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >              XCMA, YCMA, NDATMAX)

          GOTO 1
        ENDIF

      ENDIF
     
C----------------------------------------------------------------
C---  MENU : BASE-DATASET-MAN_1 ---------------------------------
C-------------------------^^^^^----------------------------------
      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'DATASETS' .AND.
     >    STACT(3) .EQ. 'MAN_1' .AND.
     >    NACT .EQ. 3) THEN
        IF (INTACT2( :IDX(INTACT2)) .EQ.      'BACK') THEN
C---                                           ----
          NACT = NACT - 1
          INTACT = STACT(NACT)
          GOTO 1

        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'REFRESH') THEN
C---                                           -------
          CALL WIPE(B, C,
     >              KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >              BINSEX,
     >              KDLINE2, NKD2, NKDMAX2, NKDP2, XCMA, YCMA, NDATMAX)
          GOTO 20

        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'XLOG' .OR.
     >           INTACT2( :IDX(INTACT2)) .EQ. 'YLOG' .OR. 
     >           INTACT2( :IDX(INTACT2)) .EQ. '10**X' .OR. 
     >           INTACT2( :IDX(INTACT2)) .EQ. '10**Y' .OR. 
     >           INTACT2( :IDX(INTACT2)) .EQ. 'SIGN(X)' .OR. 
     >           INTACT2( :IDX(INTACT2)) .EQ. 'SIGN(Y)') THEN
C---                                           -----
          NACT = NACT + 1
          STACT(NACT) = INTACT2
          INTACT = INTACT2
          IACT = 1
          COMMLINE = INTACT2( :IDX(INTACT2)) // ' DATASET '
          MESSAGE(1) = COMMLINE( :IDX(COMMLINE)) // ' ?'
          CMODUS = 'P2NOR'
          CALL PLOTMESS(B, C,
     >            KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >            BINSEX,
     >            MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
     >            WIDBUTT, HEIBUTT, MESSAGE, 1, 
     >            KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >            XCMA, YCMA, NDATMAX)

          GOTO 1

        ENDIF
      ENDIF

C----------------------------------------------------------------
C---  MENU : BASE-DATASET-MAN_1-??? -----------------------------
C-------------------------------^^^------------------------------
      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'DATASETS' .AND.
     >    STACT(3) .EQ. 'MAN_1' .AND.
     >    (STACT(4) .EQ. 'XLOG' .OR.
     >     STACT(4) .EQ. 'YLOG' .OR.
     >     STACT(4) .EQ. '10**X' .OR.
     >     STACT(4) .EQ. '10**Y' .OR.
     >     STACT(4) .EQ. 'SIGN(X)' .OR.
     >     STACT(4) .EQ. 'SIGN(Y)') .AND. 
     >    NACT .EQ. 4) THEN
        IF (INTACT2( :IDX(INTACT2)) .EQ.      'ABORT') THEN
C---                                           -----
          IACT = 1
          NACT = NACT - 1
          INTACT = STACT(NACT)
          GOTO 1

        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'EXE') THEN
C---                                           ---
          IACT = 1
          NACT = NACT - 1
          INTACT = STACT(NACT)
          SCMD2(1) = 'COMMAND ' // COMMLINE
          MESSAGE(1) = COMMLINE
            CMODUS = 'P2NOR'
            CALL PLOTMESS(B, C,
     >              KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >              BINSEX,
     >              MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
     >              WIDBUTT, HEIBUTT, MESSAGE, 1, 
     >              KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >              XCMA, YCMA, NDATMAX)

          NCMD2 = 1
          CALL EXCMD (NCMD2, NCMDMAX2, SCMD2, X, Y, X1, Y1, ISET, 
     >                NDAT, NDATMAX, NSET, NSETMAX, ISYMBOL, NPEN, 
     >                ICOLOR, B, C, MPACTIVE, VAR, MAXVAR, NVAR, STRIP,
     >                ISETXERR, ISETYERR, XERRTYPE, YERRTYPE, SETNAME)
          GOTO 1

        ELSE 
C---
          IACT = IACT + 1
          IF (INTACT2 .EQ. 'LAST') THEN
            WRITE (INTACT2, '(I3)') NSET
          ENDIF
          COMMLINE = COMMLINE( :IDX(COMMLINE)) // 
     >               ' ' // INTACT2 // ' '
          MESSAGE(1) = COMMLINE
            CMODUS = 'P2NOR'
            CALL PLOTMESS(B, C,
     >              KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >              BINSEX,
     >              MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
     >              WIDBUTT, HEIBUTT, MESSAGE, 1, 
     >              KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >              XCMA, YCMA, NDATMAX)

          GOTO 1
        ENDIF

      ENDIF
     
C----------------------------------------------------------------
C---  MENU : BASE-DATASET-SELECT --------------------------------
C-------------------------^^^^^^---------------------------------
      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'DATASETS' .AND.
     >    STACT(3) .EQ. 'SELECT' .AND.
     >    NACT .EQ. 3) THEN
        IF (INTACT2( :IDX(INTACT2)) .EQ.      'BACK') THEN
C---                                           ----
          NACT = NACT - 1
          INTACT = STACT(NACT)
          GOTO 1

        ELSE IF (INTACT2( :IDX(INTACT2)) .EQ. 'SET_1' .OR.
     >           INTACT2( :IDX(INTACT2)) .EQ. 'SET_2' .OR.
     >           INTACT2( :IDX(INTACT2)) .EQ. 'SET_3') THEN
C---                                           -----
          NACT = NACT + 1
          STACT(NACT) = INTACT2
          INTACT = INTACT2
          GOTO 1

        ENDIF
      ENDIF

C----------------------------------------------------------------
C---  MENU : BASE-DATASET-SELECT-SET-. --------------------------
C--------------------------------^^^^^---------------------------
      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'DATASETS' .AND.
     >    STACT(3) .EQ. 'SELECT' .AND.
     >    (STACT(4) .EQ. 'SET_1' .OR.
     >     STACT(4) .EQ. 'SET_2' .OR.
     >     STACT(4) .EQ. 'SET_3') .AND.
     >    NACT .EQ. 4) THEN
        IF (INTACT2( :IDX(INTACT2)) .EQ.      'BACK') THEN
C---                                           ----
          NACT = NACT - 1
          INTACT = STACT(NACT)
          GOTO 1

        ELSE 
          READ (INTACT2,'(I2)',ERR=2) IINTACT2
          IF (STACT(4) .EQ. 'SET_1') THEN
            ISELSET(1) = IINTACT2
          ELSE IF (STACT(4) .EQ. 'SET_2') THEN
            ISELSET(2) = IINTACT2
          ELSE IF (STACT(4) .EQ. 'SET_3') THEN
            ISELSET(3) = IINTACT2
          ENDIF
          WRITE (MESSAGE(1),'(A)')
     >           'SELECTED SETS : '
          WRITE (MESSAGE(2),'(3(1X,I2))')
     >           ISELSET(1), ISELSET(2), ISELSET(3)
          CMODUS = 'SELSET'
          CALL PLOTMESS(B, C,
     >            KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >            BINSEX,
     >            MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
     >            WIDBUTT, HEIBUTT, MESSAGE, 2, 
     >            KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >            XCMA, YCMA, NDATMAX)

          GOTO 2

        ENDIF
      ENDIF

C---  END OF BOUND POINTS ---------------------------------------

C*** ERROR EXIT
      MESSAGE(1) = 'DEAD END'
      CMODUS = 'P1BIG'
      CALL PLOTMESS(B, C,
     >        KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >        BINSEX,
     >        MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, INTACT,
     >        WIDBUTT, HEIBUTT, MESSAGE, 1, 
     >        KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >        XCMA, YCMA, NDATMAX)


c      CALL SLEEP(1)
      GOTO 1

   20 CONTINUE    

      RETURN

   97 WRITE (6,*) 'ERROR IN OPENING FILE FOR XY-TABLE'
      STOP

      END
intman.f/       1553528659  5006  320   100644  14067     `
      SUBROUTINE INTMAN (FNAME, XINT, YINT, NINTMAX, NINT, NINT2, 
     >                   X, Y, NDAT, ISET, NDATMAX, NSETMAX, B, C, 
     >                   BINTER, BSINGLE)

      DIMENSION NDAT(ISET)
      DIMENSION X(NDATMAX,NSETMAX), Y(NDATMAX,NSETMAX)
      DIMENSION XINT(NINTMAX), YINT(NINTMAX)
      DIMENSION B(6), C(6)
      LOGICAL BMONO, BINTER, BSINGLE, BKAS
      CHARACTER FNAME*255, NAMENEW*255, LINE*132, ACTPAR*60, ICHAR*2
      PARAMETER (KASLINM=100)
      CHARACTER*132 KASLIN(KASLINM)

C**********************************************************************
C***   MANIPULATION OF INTERACTIVE POINTS                           ***
C**********************************************************************

  405   WRITE(6,*) 'MANIPULATION OF INTERACTIVE POINTS'
        WRITE(6,*) 'IQ = QUIT INTERAKTIVE MODUS'
        WRITE(6,*) 'I = IGNORE NEW POINTS'
        WRITE(6,*) 'L = LIST POINTS'
        WRITE(6,*) 'A = APPEND NEW POINTS'
        WRITE(6,*) 'D = DELETE OLD POINTS BY NEW POINTS'
        WRITE(6,*) 'DN = DELETE OLD POINTS BY NUMBER'
        WRITE(6,*) 'DA = DELETE ALL OLD POINTS'
        WRITE(6,*) 'S = SORT POINTS'
        WRITE(6,*) 'C = CHECK OF INCREASING DATA-POINTS IN DATASET'
        WRITE(6,*) 'E = EQUIVALENT WIDTH'
        WRITE(6,*) 'X = SAVE XY-TABLE'
        WRITE(6,*) 'B = SET NEW BOUNDARIES'
        WRITE(6,*) 'N = NEXT MENU'
        WRITE(6,'(''$'',A)') 'INPUT: '
        READ(5,'(A)',END=99) ICHAR      


C-----
        IF (ICHAR .EQ. 'I' .OR. ICHAR .EQ. 'i') THEN
          NINT2 = 0

C-----
        ELSE IF (ICHAR .EQ. 'IQ' .OR. ICHAR .EQ. 'iq') THEN
          BINTER = .FALSE.
          WRITE (6,*) 'QUIT INTERACTIVE MODUS'
          GOTO 490

C-----
        ELSE IF (ICHAR .EQ. 'A' .OR. ICHAR .EQ. 'a') THEN
          DO 400 I = 1, NINT2
            XINT(NINT+I) = XINT(NINTMAX-I+1)
            YINT(NINT+I) = YINT(NINTMAX-I+1)
  400     CONTINUE
          NINT = NINT + NINT2
          NINT2 = 0

C-----
        ELSE IF (ICHAR .EQ. 'L' .OR. ICHAR .EQ. 'l') THEN
          WRITE(6,*)
          WRITE(6,*) 'OLD POINTS'
          DO 410 I=1, NINT
            WRITE(6,'(2X,A,I4,2X,2G12.4)') 
     >           'I,   X,Y :    ', I, XINT(I), YINT(I)
  410     CONTINUE
          WRITE(6,*)
          WRITE(6,*) 'NEW POINTS'
          DO 420 I=1, NINT2
            WRITE(6,'(2X,A,I4,2X,2G12.4)') 'I,   X,Y :    ', 
     >                  I, XINT(NINTMAX-I+1), YINT(NINTMAX-I+1)
  420     CONTINUE
          WRITE(6,'(''$'',A)') 'CONTINUE: PRESS RETURN'
          READ(5,'(A)') ICHAR      

C-----
        ELSE IF (ICHAR .EQ. 'D' .OR. ICHAR .EQ. 'd') THEN
          DO 422 I=1, NINT2
            XCM1 = (XINT(NINTMAX+1-I) - B(2)) / B(1)
            YCM1 = (YINT(NINTMAX+1-I) - C(2)) / C(1)
             J = 0
  424        J = J + 1
              XCM2 = (XINT(J) - B(2)) / B(1)
              YCM2 = (YINT(J) - C(2)) / C(1)
              IF (ABS(XCM1-XCM2) .LT. 0.3 .AND.
     >            ABS(YCM1-YCM2) .LT. 0.3) THEN
                NINT = NINT - 1
                DO 426 K=J, NINT
                  XINT(K) = XINT(K+1)
                  YINT(K) = YINT(K+1)
  426           CONTINUE
              ENDIF
            IF (J .LT. NINT) GOTO 424
  422     CONTINUE

C-----
        ELSE IF (ICHAR .EQ. 'DN' .OR. ICHAR .EQ. 'dn') THEN
  423     CONTINUE
          WRITE (6,*) 'GIVE THE NUMBER OF POINT YOU WANT TO DELETE', 
     >                '   0 : EXIT'
          READ (5, '(A)') LINE
          CALL SARGV (LINE, 1, ACTPAR)
          READ (ACTPAR, '(BN,I4)', ERR=96) ID1
          ID2 = ID1
          IF (ID1 .EQ. 0) GOTO 425
          IF (ID1 .LT. 0 .OR. ID1 .GT. NINT) THEN
            WRITE (6,*) 'NUMBER NOT ALLOWED'
            GOTO 423
          ENDIF
          CALL SARGC (LINE, NARG)
          IF (NARG .GT. 1) THEN
            CALL SARGV (LINE, 2, ACTPAR)
            READ (ACTPAR, '(BN,I4)', ERR=96) ID2
            IF (ID2 .LT. ID1 .OR. ID2 .GT. NINT) THEN
              WRITE (6,'(A,I4)') 
     >             'SECOND NUMBER NOT IN VALID RANGE AND SET TO ', ID1
              ID2 = ID1
            ENDIF
          ENDIF

          DO 427 J2 = ID1, ID2
            NINT = NINT - 1
            DO 427 J=J2, NINT
              XINT(J) = XINT(J+1)
              YINT(J) = YINT(J+1)
  427       CONTINUE
          WRITE (6,*)
          GOTO 423
  425     CONTINUE


C-----
        ELSE IF (ICHAR .EQ. 'DA' .OR. ICHAR .EQ. 'da') THEN
          NINT = 0

C-----
        ELSE IF (ICHAR .EQ. 'S' .OR. ICHAR .EQ. 's') THEN
C***  SORT POINTS
          DO 430 I=1, NINT
            DO 430 J=1, NINT-1
              IF (XINT(J) .GT. XINT(J+1)) THEN
                TEMP = XINT(J)
                XINT(J) = XINT(J+1)
                XINT(J+1) = TEMP
                TEMP = YINT(J)
                YINT(J) = YINT(J+1)
                YINT(J+1) = TEMP
               ENDIF
  430     CONTINUE
C***  DELETE CONSECUTIVE SIMILAR POINTS
          IF (NINT .GT. 1) THEN
            I = 0
  432       I = I + 1
              IF (XINT(I) .EQ. XINT(I+1) .AND. 
     >            YINT(I) .EQ. YINT(I+1)) THEN
                DO 434 J=I+1, NINT - 1
                  XINT(J) = XINT(J+1)
                  YINT(J) = YINT(J+1)
  434           CONTINUE
                I = I - 1
                NINT = NINT - 1
              ENDIF
            IF (I .LT. NINT-1) GOTO 432
          ENDIF


C-----
        ELSE IF (ICHAR .EQ. 'C' .OR. ICHAR .EQ. 'c') THEN
C***  CHECK INCREASING ORDER OF DATASET
          BMONO = .TRUE. 
          IF (ISET .GT. 1) THEN
  449        WRITE (6,'(''$'',A)') 'WHICH DATASET DO YOU WANT ?'
             READ (5, '(I4)', ERR=449) ISETOP
             IF (ISETOP .LT. 1 .OR. ISETOP .GT. ISET) GOTO 449
          ELSE
             ISETOP = 1
          ENDIF
          N = NDAT(ISETOP)
          DO 445 I=1, N-1
            IF (X(I,ISETOP) .GT. X(I+1,ISETOP)) THEN
              WRITE (6,*) 'DECREASING DATA-POINTS IN DATASET : ',
     >                     X(I,ISETOP), X(I+1,ISETOP)
              BMONO = .FALSE.
            ENDIF
  445     CONTINUE
          IF (BMONO) THEN
            WRITE (6,*) 'DATA-POINTS IN DATASET INCREASING'
          ENDIF

C-----
        ELSE IF (ICHAR .EQ. 'E' .OR. ICHAR .EQ. 'e') THEN
C***  COMPUTE EQUIVALENT WIDTH
          IF (NINT .LT. 2) THEN
            WRITE(6,*) 'NOT ENOUGH DATAPOINTS'
            GOTO 405
          ENDIF
C***  CHECK MONOTONIC ORDER
          BMONO = .TRUE. 
          DO 440 I=1, NINT-1
            IF (XINT(I) .GT. XINT(I+1)) THEN
              BMONO = .FALSE.
            ENDIF
  440     CONTINUE
          IF (.NOT. BMONO) THEN
            WRITE(6,*) ' INTERACTIVE POINTS NOT IN INCREASING ORDER'
            WRITE(6,*) ' OPTION ABORTED'
            WRITE(6,*)
            GOTO 405
          ENDIF
          EQUI = 0
C***  DISTINGUISH TWO CASES
C***    A) TWO DATA POINTS :          TAKE DATA PROFILE
C***    B) MORE THAN TWO DATAPOINTS : TAKE FIT PROFILE
          IF (NINT .GT. 2) THEN
            DO 442 I=2, NINT-1
              DX = 0.5 * (XINT(I+1) - XINT(I-1))
              WEIGHT = (XINT(I) - XINT(1)) / (XINT(NINT) - XINT(1))
              CONT = (1. - WEIGHT) * YINT(1) + WEIGHT * YINT(NINT)
              EQUI = EQUI + (YINT(I) / CONT - 1.) * DX
  442       CONTINUE
          ELSE
            IF (ISET .GT. 1) THEN
  443         WRITE (6,'(''$'',A)') 'WHICH DATASET DO YOU WANT ?'
              READ (5, '(I4)', ERR=443) ISETOP
              IF (ISETOP .LT. 1 .OR. ISETOP .GT. ISET) GOTO 443
            ELSE
              ISETOP = 1
            ENDIF
            N = NDAT(ISETOP)
C***  CHECK MONOTONIC ORDER OF DATASET
          BMONO = .TRUE. 
          DO 444 I=1, N-1
            X1 = X(I,ISETOP)
            X2 = X(I+1,ISETOP)
            IF (X1 .GT. X2 .AND. X1 .GE. XINT(1) .AND.
     >          X1 .LE. XINT(NINT) .AND. X2 .GE. XINT(1) .AND.
     >          X2 .LE. XINT(NINT)) THEN
              BMONO = .FALSE.
            ENDIF
  444     CONTINUE
          IF (.NOT. BMONO) THEN
            WRITE(6,*) 'DATAPOINTS IN DATASET NOT IN MONOTONIC ORDER'
            GOTO 405
          ENDIF
C***  FIND OUT START AND END INDEX
          IND1 = 1
          IND2 = N
          DO 446 I=1, N
            IF (X(I,ISETOP) .LT. XINT(1)) THEN
              IND1 = I + 1
            ENDIF
            IF (X(I,ISETOP) .LT. XINT(2)) THEN
              IND2 = I
            ENDIF
  446     CONTINUE
C***  CALCULATE EQUIVALENT WIDTH
C***  TREATMENT OF INNER POINTS
          DO 448 I=IND1, IND2
            IF (I .EQ. IND1) THEN
              DX = 0.5 * (X(IND1,ISETOP) - XINT(1))
            ELSE IF (I .EQ. IND2) THEN
              DX = 0.5 * (XINT(2) - X(IND2,ISETOP))
            ELSE
              DX = 0.5 * (X(I+1,ISETOP) - X(I-1,ISETOP))
            ENDIF
            WEIGHT = (X(I,ISETOP) - XINT(1)) / (XINT(2) - XINT(1))
            CONT = (1. - WEIGHT) * YINT(1) + WEIGHT * YINT(2)
            EQUI = EQUI + (Y(I,ISETOP) / CONT - 1.) * DX
  448     CONTINUE
C***  TREATMENT OF BOUNDARY POINTS
C***  LEFT BOUNDARY
          DX = 0.5 * (X(IND1,ISETOP) - XINT(1))
          WEIGHT = (XINT(1) - X(IND1-1,ISETOP)) / 
     >             (X(IND1,ISETOP) - X(IND1-1,ISETOP))
          YT = (1. - WEIGHT) * Y(IND1-1,ISETOP) + 
     >         WEIGHT * Y(IND1,ISETOP)
          EQUI = EQUI + (YT - 1.) * DX
C***  RIGHT BOUNDARY
          DX = (XINT(2) - X(IND2,ISETOP))
          WEIGHT = (XINT(2) - X(IND2,ISETOP)) / 
     >             (X(IND2+1,ISETOP) - X(IND2,ISETOP))
          YT = (1. - WEIGHT) * Y(IND2,ISETOP) + 
     >         WEIGHT * Y(IND2+1,ISETOP)
          EQUI = EQUI + (YT - 1.) * DX

          ENDIF
          WRITE(6,*) 'EQUIVALENT WIDTH=',EQUI

          WRITE(6,*) 'STORE MEASURED EQUIVALENT WIDTH ?'
          READ (5,'(A)') ICHAR
          IF (ICHAR .EQ. 'Y' .OR. ICHAR .EQ. 'y') THEN
            WRITE(6,*) 'STORE WHOLE FILE OR ONLY KASDEFS (F/K) ?'
            READ (5,'(A)') ICHAR
            IF (ICHAR .EQ. 'F' .OR. ICHAR .EQ. 'f') THEN
              BKAS = .FALSE.
            ELSE
              BKAS = .TRUE.
            ENDIF
            IF (.NOT. BSINGLE .AND. .NOT. BKAS) THEN
              WRITE(*,'(A)') 'STORAGE OF WHOLE FILE NOT POSSIBLE'
              BKAS = .TRUE.
            ENDIF
            IF (BKAS) THEN            
              WRITE(6,*) ' NAME OF NEW FILE :'
              READ(5,'(A)') NAMENEW
            ELSE
              WRITE(6,'(A)') ' CREATE NEW PLOTFILE WITH OLD NAME? /Y/'
              READ (5,'(A)') ICHAR
              IF (ICHAR .EQ. 'N' .OR. ICHAR .EQ. 'n') THEN
                WRITE(6,*) ' NAME OF NEW FILE :'
                READ(5,'(A)') NAMENEW
              ELSE
                NAMENEW = FNAME
C***  SEARCH BACKWARDS IN FNAME FOR ";"
                I = IDX(NAMENEW)
 455            CONTINUE
                  IF (NAMENEW(I:I) .NE. ';') THEN
                    I = I - 1
                    GOTO 455
                  ENDIF
                NAMENEW = NAMENEW( :I)
              ENDIF
            ENDIF

            IKAS = 1
            WRITE (KASLIN(IKAS), '(A)') '*'
            IKAS  = IKAS + 1
            IF (IKAS .GT. KASLINM) GOTO 95
            WRITE (KASLIN(IKAS), '(A, F8.2, 2A, 2(F8.2, A), F7.2)')
     >        'KASDEF LUN  ', XINT(1),' 0.5  -5.0 0.0  0.3 ',
     >        ' EQUIVALENT WIDTH (', XINT(1), ' - ', XINT(NINT), 
     >        ')  =  ', EQUI
C***  CONNECT INTERACTIVE POINT BY LINES
            DO 452 I=1, NINT
              IKAS = IKAS + 1
              IF (IKAS .GT. KASLINM) GOTO 95
              WRITE (KASLIN(IKAS), '(A, 2F8.2, A)')
     >          'KASDEF SYM ', XINT(I), YINT(I), ' 0. 0. 0.3 2'
              IF (I .LT. NINT) THEN
                IKAS = IKAS + 1
                IF (IKAS .GT. KASLINM) GOTO 95
                WRITE (KASLIN(IKAS), '(A, 4F8.2, A)')
     >            'KASDEF LINUN ', XINT(I), YINT(I), XINT(I+1), 
     >                             YINT(I+1), '  0. 0.'
              ENDIF
  452       CONTINUE
C***  DRAW CONTINUUM, WHEN MORE THAN TWO INTERACTIVE POINTS ARE GIVEN
            IF (NINT .GT. 2) THEN
              IKAS = IKAS + 1
              IF (IKAS .GT. KASLINM) GOTO 95
              WRITE (KASLIN(IKAS), '(A, 4F10.4, A)')
     >          'KASDEF LINUN ', XINT(1), YINT(1), XINT(NINT), 
     >                           YINT(NINT), '  0. 0.'
            ENDIF
            CALL INTSAVE (FNAME, NAMENEW, KASLIN, KASLINM, IKAS,
     >                    BKAS, ISETOP)
          ENDIF
C-----
        ELSE IF (ICHAR .EQ. 'X' .OR. ICHAR .EQ. 'x') THEN
C***  SAVE INTERACTIVE POINTS AS XY-TABLE
        WRITE(6,*) 'INTERACTIVE DATAPOINTS SAVE IN FILE wrplot.xy'
        OPEN (UNIT=10, FILE='wrplot.xy', STATUS='UNKNOWN', ERR=97, 
     >        RECL=132)
        DO 456 I=1, NINT
          WRITE (10, '(2(A, E15.6))')
     >      '  ',XINT(I),'  ', YINT(I)
  456   CONTINUE
        CLOSE (10)


C-----
        ELSE IF (ICHAR .EQ. 'B' .OR. ICHAR .EQ. 'b') THEN
          WRITE (6,*) 'CHANGE X- OR Y-BOUNDARIES  /X/'
          READ (5,'(A)') ICHAR
          IF (ICHAR .NE. 'Y' .AND. ICHAR .NE. 'y') THEN
            WRITE (6,*) 'GIVE X-START :'
            READ (5,*) B(2)
            WRITE (6,*) 'GIVE X-END :'
            READ (5,*) B(3)
            B(1) = 20. / (B(3) - B(2))
            WRITE (6,*) 'GIVE X-TICKS :'
            READ (5,*) B(4)
            WRITE (6,*) 'GIVE X-MARKS :'
            READ (5,*) B(5)
          ELSE
            WRITE (6,*) 'GIVE Y-START :'
            READ (5,*) C(2)
            WRITE (6,*) 'GIVE Y-END :'
            READ (5,*) C(3)
            C(1) = 15. / (C(3) - C(2))
            WRITE (6,*) 'GIVE Y-TICKS :'
            READ (5,*) C(4)
            WRITE (6,*) 'GIVE Y-MARKS :'
            READ (5,*) C(5)
          ENDIF

C-----
        ELSE IF (ICHAR .EQ. 'N' .OR. ICHAR .EQ. 'n') THEN
          GOTO 490
        ENDIF
        GOTO 405
  490   CONTINUE

      RETURN

C***  ERROR BRANCHES
   95 WRITE (6,*) 'MORE NEW KASDEF LINES THAN DIMENSIONED'
      GOTO 405




   96 WRITE (6,*) 'ILLEGAL INPUT'
      GOTO 423


   97 WRITE (6,*) 'ERROR IN OPENING FILE FOR XY-TABLE'
      STOP

   99 WRITE (6,*) 'E-O-F in input channel'
      STOP 'OK in SUBR. INTMAN'
      END

intsave.f/      1553528659  5006  320   100644  1648      `
      SUBROUTINE INTSAVE (FNAME, NAMENEW, KASLIN, KASLINM, IKAS, 
     >                    BKAS, ISET)

      CHARACTER*255 FNAME, NAMENEW
      CHARACTER*132 KASLIN(KASLINM), LINE, ACTPAR
      LOGICAL BKAS

C***  SEARCH BACKWARDS IN FNAME FOR ";"
      I = IDX(FNAME)
 455  CONTINUE
        IF (FNAME(I:I) .NE. ';') THEN
          I = I - 1
          GOTO 455
        ENDIF
      FNAME = FNAME( :I)

C***  STORE MEASURED EQUIVALENT WIDTH
      OPEN (UNIT=10, FILE=FNAME,   STATUS='OLD', ERR=98, RECL=132)
      OPEN (UNIT=11, FILE=NAMENEW, STATUS='NEW', ERR=99, RECL=132)
            I = ISET
            IF (.NOT. BKAS) THEN
  450         CONTINUE
                READ(10,'(A)', END=454) LINE
                CALL SARGV (LINE, 1, ACTPAR)
                IF (ACTPAR .EQ. 'N') THEN
                  I = I - 1
                ENDIF
                IF (I .EQ. 0) GOTO 451
                WRITE(11,'(A)') LINE( :IDX(LINE))
              GOTO 450
            ENDIF
  451       CONTINUE
C***  WRITE KASLIN
            DO 452 I=1, IKAS
              WRITE (11,'(A)') KASLIN(I)( :IDX(KASLIN(I)))
  452      CONTINUE

            IF (.NOT. BKAS) THEN
              WRITE(11,'(A)') LINE( :IDX(LINE))
  453         CONTINUE
                READ(10,'(A)', END=454) LINE
                WRITE(11,'(A)') LINE( :IDX(LINE))
              GOTO 453
            ENDIF
  454       CONTINUE
          CLOSE (10)
          CLOSE (11)

      RETURN

   98 WRITE (6,*) 'ERROR IN OPENING READFILE : ',
     >             FNAME( :IDX(FNAME))
      STOP

   99 WRITE (6,*) 'ERROR IN OPENING WRITEFILE : ',
     >             NAMENEW( :IDX(NAMENEW))
      STOP

      END
isoex.f/        1643641498  5006  320   100644  3482      `
      SUBROUTINE ISOEX
C****************************************************
C***
C***  Creating an isoplot file from all .out files in the present directory
C***
C****************************************************

      CHARACTER LINE*120, ACTPAR*10, ACTPAR2*10, MODEL*50, 
     >     TOLD*10, KEYWORD*10
      LOGICAL BPEAK, OBGRID

C     abanisk: Mit dieser Abfrage wird geklaert, ob die Equivalentbreite oder
C              die Peakhoehe gewuenscht ist. Standard ist Equiv-w..
      BPEAK = .FALSE.
      KEYWORD = 'TOTAL'
      OBGRID = .FALSE.

1001  format(A)
      OPEN(101,FILE='iso.part1',status='old')
110   READ (101, 1001, ERR=980, END=113) LINE
      CALL SARGV (LINE,1,ACTPAR)
      IF (ACTPAR .EQ. 'PEAK') THEN
         BPEAK = .TRUE.
      ELSEIF (ACTPAR .EQ. 'EMISSION') THEN
         KEYWORD = ACTPAR
      ELSEIF (ACTPAR .EQ. 'ABSORPTION') THEN
         KEYWORD = ACTPAR
      ELSEIF (ACTPAR .EQ. 'OBGRID') THEN
         OBGRID = .TRUE.
      ELSE
         GOTO 110
      ENDIF
 113  CONTINUE
      LINE = ' '
      CLOSE(101)

C***  The following "grep" should extract 3 lines from each formal.out, 
C***  containing the lines with
C***    1) T*
C***    2) Rt
C***    3) Equiv. width
C***  The extracted lines are written to file iso.dat and can be checked there!
      IF (.NOT. BPEAK) THEN
         CALL SYSTEM 
     >('grep -e "T\*" -e Rt -e EQUIV ??-??.out | cut -c1-120 > iso.dat')
      
c     This "grep" gives the peak intensity instead of the line width
      ELSEIF (BPEAK) THEN
         CALL SYSTEM 
     >     ('grep -e "T\*" -e Rt -e PEAK *.out | cut -c1-120 > iso.dat')
      ELSE
         GOTO 998
      ENDIF

      CALL SYSTEM ('cat iso.part1 > isoex.iso')


C***  Now iso.dat is read, the parameters are parsed from the lines 
C***   and the table is written to isoex.iso 
C***   in the proper input format for isopro 

C***  Special feature added for OB-Grids: 
C***      If iso.part1 contains the keyword OBGRID, 
C***      the value of 'log g' is constructed from the model-index  

      OPEN (10, FILE='iso.dat', STATUS='OLD')
      TOLD = ' '

    1 READ (10, '(A)', END=100) LINE
      CALL SARGV (LINE,3,ACTPAR)
      IF (ACTPAR .NE. TOLD) WRITE (20,'(A)') 'T=' // ACTPAR
      TOLD = ACTPAR

      READ (10, '(A)', END=999) LINE
      CALL SARGV (LINE,3,ACTPAR)

      READ (10, '(A)', END=999) LINE
      IF (BPEAK) THEN
         CALL SARGV (LINE,4,ACTPAR2)
      ELSE
         IF (KEYWORD .EQ. 'TOTAL') THEN
            CALL SARGV (LINE,5,ACTPAR2)
         ELSEIF (KEYWORD .EQ. 'EMISSION') THEN
            CALL SARGV (LINE,8,ACTPAR2)
         ELSEIF (KEYWORD .EQ. 'ABSORPTION') THEN
            CALL SARGV (LINE,11,ACTPAR2)
         ELSE
            print *, keyword
            STOP '*** INTERNAL ERROR IN ISOEX'
         ENDIF
      ENDIF
      CALL SARGV (LINE,1,MODEL)

      IF (OBGRID) THEN
         READ (MODEL(4:5), '(I2)') MODINDEX2 
         WRITE (ACTPAR, '(F6.1)') MODINDEX2/10.
      ENDIF

      WRITE (20,'(2X,A,2X,A,2X,A)') ACTPAR, ACTPAR2, MODEL

      GOTO 1


  100 CONTINUE

      WRITE (20,'(A)') 'END'
      CLOSE (20)
      CLOSE (10)

      CALL SYSTEM ('cat fort.20 >> isoex.iso')
      CALL SYSTEM ('rm -f fort.20')

      STOP 'O.K.'

C***  Errors
 998  CONTINUE
      STOP 'ERROR: DO NOT KNOW WHICH LINE-CHARACTERISTIC IS WISHED:
     > PEAK OR EQUIV!'
999   CONTINUE
      STOP 'ERROR: EOF reached before line-triple completed' 

980   PRINT *, 'Datenfile Lesefehler'
      STOP 'ERROR'

      END

isomix.f/       1553528659  5006  320   100644  5188      `
      SUBROUTINE ISOMIX

      PARAMETER (MAX=100)

      CHARACTER LINE*132, ACTPAR*60
      CHARACTER*255 ISO(2), ISOOUT
      DIMENSION T(3,MAX), RT(3,MAX), WERT(3,MAX)
      LOGICAL BINS(3,MAX), BTEMP
      DIMENSION N(3)

C***  EINGABE DER FILE-NAMEN
      WRITE (*,*) 'FILE 1 :'
C***      CALL GETNAM(ISO(1),'[]')
      READ (*, '(A)') ISO(1)
      WRITE (*,*)
      WRITE (*,*) 'FILE 2 :'
C***      CALL GETNAM(ISO(2),'[]')
      READ (*, '(A)') ISO(2)

      N(1) = 0
      N(2) = 0

C***  EINLESEN DER DATEN
      DO 100 I=1, 2
        OPEN (UNIT=I, FILE=ISO(I), STATUS='OLD', ERR=99)

C***  SUCHE BIS ZUR ERSTEN "T=" ZEILE
  200   CONTINUE
          READ (I, '(A)', END=300) LINE
          CALL SARGV (LINE, 1, ACTPAR)
        IF (ACTPAR .NE. 'T') GOTO 200
  210   CALL SARGV (LINE, 2, ACTPAR)
        READ (ACTPAR, '(F10.0)') TEFF
  220   CONTINUE
          READ (I, '(A)', END=300) LINE
          CALL SARGV (LINE, 1, ACTPAR)
          IF (ACTPAR .EQ. 'T') GOTO 210
          CALL SARGV (LINE, 2, ACTPAR)
          IF (ACTPAR(1:1) .EQ. '?') THEN
            BTEMP = .TRUE.
          ELSE
            BTEMP = .FALSE.
          ENDIF
          IF (LINE .EQ. 'END') GOTO 300
          N(I) = N(I) + 1
          IF (N(I) .GT. MAX) THEN
            WRITE(*,*) 'MORE DATA THAN DIMENSIONED'
            STOP
          ENDIF
          T(I,N(I)) = TEFF
          IF (.NOT. BTEMP) THEN
            READ (ACTPAR, '(F10.0)') WERT(I,N(I))
            BINS(I,N(I)) = .FALSE.
          ELSE
            BINS(I,N(I)) = .TRUE.
          ENDIF
          CALL SARGV (LINE, 1, ACTPAR)
          READ (ACTPAR, '(F10.0)') RT(I,N(I))
        GOTO 220
  300   CONTINUE

  100 CONTINUE

C***      DO 500 I=1, 2
C***      DO 500 J=1,N(I)
C***500      WRITE(*,*) I,J,T(I,J),RT(I,J),WERT(I,J),bins(I,J)

C***  KOMBINATION BEIDER WERTE-TABELLEN
      N(3) = 0
      DO 400 I=1, N(1)
C***  SUCHE NACH GEGENSTUECK
        J = 0
  410   CONTINUE
          J = J + 1
          IF (J .GT. N(2) .OR. 
     >        T(1,I) .NE. T(2,J) .OR. RT(1,I) .NE. RT(2,J)) GOTO 420
          N(3) = N(3) + 1
          T(3,N(3)) = T(1,I)
          RT(3,N(3)) = RT(1,I)
          BINS(3,N(3)) = BINS(1,I) .OR. BINS(2,J)
C***  HIER DIE MANIPULATION EINGEBEN
          IF (.NOT. BINS(3,N(3))) THEN
            WERT(3,N(3)) = WERT(1,I) / WERT(2,J)
          ENDIF

  420     CONTINUE
        IF (J .LT. N(2)) GOTO 410
  400 CONTINUE

C***      write(*,*) 'vor dem sortieren'
C***      DO 505 J=1,N(3)
C***505      WRITE(*,*) I,T(3,J),RT(3,J),WERT(3,J),BINS(3,J)

C***  SORTIEREN DER DATEN
      DO 450 I=1, N(3)
        DO 450 J=1, N(3) - 1
          IF (T(3,J) .GT. T(3,J+1) .OR.
     >       (T(3,J) .EQ. T(3,J+1) .AND. RT(3,J) .LT. RT(3,J+1))) THEN
            TEMP = T(3,J)
            T(3,J) = T(3,J+1)
            T(3,J+1) = TEMP
            TEMP = RT(3,J)
            RT(3,J) = RT(3,J+1)
            RT(3,J+1) = TEMP
            TEMP = WERT(3,J)
            WERT(3,J) = WERT(3,J+1)
            WERT(3,J+1) = TEMP
            BTEMP = BINS(3,J)
            BINS(3,J) = BINS(3,J+1)
            BINS(3,J+1) = BTEMP
          ENDIF
  450 CONTINUE

C*** SCHREIBEN DES OUTPUTFILES

C***  OUTPUT-FILE = FNOUT
      ISOOUT = 'isomix.iso'

C***  SCHREIBEN DES ERSTEN TEILS DES ISO-FILES
      OPEN (UNIT=1, FILE='iso.part1', STATUS='OLD', ERR=99, RECL=132)
      OPEN (UNIT=2, FILE='iso.part2', STATUS='OLD', ERR=99, RECL=132)
      WRITE(*,'(2A)') ' OUTPUT-FILE = ', ISOOUT( :IDX(ISOOUT))
      OPEN (UNIT=3, FILE=ISOOUT, STATUS='NEW', ERR=99, RECL=132)
      READ (1, '(A)', END=72) LINE
      LINE = LINE(: ISTRL(LINE))//'   '//ISO(1)( :IDX(ISO(1)))//
     >       '  '//ISO(2)( :IDX(ISO(2)))
      WRITE (3, '(A)') LINE
   70 READ (1, '(A)', END=72) LINE
      WRITE (3, '(A)') LINE( :ISTRL(LINE))
      GOTO 70
   72 CONTINUE
      CLOSE (1)

C***  SCHREIBEN DES ZWEITEN TEILS DES ISO-FILES
      READ (2, '(A)', END=75) LINE
      WRITE (3, '(A)') LINE( :ISTRL(LINE))
      READ (2, '(A)', END=75) LINE
      WRITE (3, '(A)') 'ISOMIX'
      READ (2, '(A)', END=75) LINE
      WRITE (3, '(A)') LINE( :ISTRL(LINE))
      READ (2, '(A)', END=75) LINE

C***  VERKUERZEN DER FILENAMEN
      DO 80 I=1, 2
   83   IF (ISO(I)(1:1) .NE. ']') THEN
          ISO(I) = ISO(I)(2: )
          GOTO 83
        ENDIF
        ISO(I) = ISO(I)(2: )
   80 CONTINUE

      WRITE(3,'(A)') 'HEADER: '//ISO(1)( :IDX(ISO(1)))//'   '//
     >               ISO(2)( :IDX(ISO(2)))
   74 READ (2, '(A)', END=75) LINE
      WRITE (3, '(A)') LINE( :ISTRL(LINE))
      GOTO 74
   75 CONTINUE
      CLOSE (2)

C*** SCHREIBEN DER ISOWERTE
      TE = -10.
      DO 82 I=1, N(3)
        IF (TE .LT. T(3,I)) THEN
          IF (T(3,I) .GT. 0.) THEN
            WRITE (3, '(A,F10.3)') 'T=',T(3,I)
            TE = T(3,I)
          ENDIF
        ENDIF
        IF (T(3,I) .GT. 0.) THEN
          IF (.NOT. BINS(3,I)) THEN
            WRITE (3, '(F10.2,3X,F10.3)') RT(3,I), WERT(3,I)
          ELSE
            WRITE (3, '(F10.2,3X,A3)') RT(3,I), '???'
          ENDIF
        ENDIF
   82 CONTINUE
      WRITE(3, '(A)') 'END'
      WRITE(3, '(A)') '==================================='
      CLOSE(3)


      GOTO 1000

   99 WRITE(*,*) 'FILE OPEN FAILED'

 1000 END
isoplo.f/       1553528659  5006  320   100644  7740      `
C**************************************************************************
C*    Subroutine Isoplo:  Iso-linien FOLGEN und plotten                *
C**************************************************************************
      SUBROUTINE ISOPLO(R,F,T,IMAX,JMAX,FMIN,FMAX,PPCM,
     >                   IFELD,IXDIM, IYDIM, ILEV,FLEV,SSIZE,
     >                   MONO, XKAST, YKAST, STEP, ISOFOR, SLOPE,
     >                   MAXT, MAXR, IWRSYM, WRSYMS)

      DIMENSION IFELD(0:IXDIM,0:IYDIM)
      CHARACTER HTEXT*20, ISOFOR*12
      LOGICAL GETBIT, MONO, SPUNKT
      DIMENSION XKAST(6), YKAST(6), FLEV(50)
      COMMON /ISOCOM/ IXMAX,IXMIN,IYMAX,IYMIN,SCALEX,SCALEY

C***  TEST-OUTPUT DES GESETZTEN BITMUSTERS
      IF (.FALSE.) THEN
      DO 300 IY=IYMIN, IYMAX
      DO 300 IX=IXMIN, IXMAX
      IF (GETBIT(IX,IY,IFELD, IXDIM, IYDIM)) THEN
         CALL GPLOT ((IX-0.5)/PPCM, (IY-0.5)/PPCM, 3) 
         CALL GPLOT ((IX+0.5)/PPCM, (IY-0.5)/PPCM, 2) 
         CALL GPLOT ((IX+0.5)/PPCM, (IY+0.5)/PPCM, 2) 
         CALL GPLOT ((IX-0.5)/PPCM, (IY+0.5)/PPCM, 2) 
         CALL GPLOT ((IX-0.5)/PPCM, (IY-0.5)/PPCM, 2) 
         ENDIF
 300  CONTINUE
      ENDIF


C***  SUCHE NACH DEM LINKESTEN GESETZTEN BIT IN DER UNTERSTEN NOCH NICHT 
C***      ABGEARBEITETEN ZEILE
       IYBEG = IYMIN
99     DO 110 IYHELP=IYBEG,IYMAX
       IY = IYHELP
       DO 100 IXHELP=IXMIN,IXMAX
       IY = IYHELP
       IX = IXHELP
       IF (GETBIT(IX,IY,IFELD, IXDIM, IYDIM)) GOTO 120
C***  ACHTUNG: RAUSSPRINGEN AUS DER LOOP, RUECKSPRUNG ERFOLGT!
100    continue
       iybeg=iy+1
110    continue

C*******************************************
C***   keine isobits mehr gesetzt; fertig
       RETURN
C*******************************************

C***  PUNKT EINER ISOLINIE GEFUNDEN: (IX,IY)
120   CONTINUE

C***  GIBT ES NOCH GESETZTE PUNKTE RECHTS DAVON?
      IXR = IX
  121 IF (IXR .LT. IXMAX) THEN
         IF (GETBIT(IXR+1, IY,IFELD, IXDIM, IYDIM)) THEN
            IXR = IXR + 1
            GOTO 121
            ENDIF
         ENDIF

C***  NORMALFALL: (IX,IY) IST ANFANGSPUNKT UND KEIN SCHEITELPUNKT
      SPUNKT = .FALSE.

C***  Zahl der Nachbarn bei IX und IXR
      NBIX = NACHB(IX, IY, IFELD, IXDIM, IYDIM)
      IF (IXR .NE. IX) NBIXR = NACHB(IXR, IY, IFELD, IXDIM, IYDIM)
C***  IXR IST ANFANGSPUNKT?
      IF (NBIXR .LE. 1) IX = IXR
C***  IX IST SCHEITELPUNKT?
      IF (NBIX .GE. 2  .AND.  NBIXR .GE. 2) THEN
         SPUNKT = .TRUE.
         IXSCH  = IX
         IYSCH  = IY
         ENDIF

C*******************************************************************
C***   Beschriftung der Isolinien
C*******************************************************************
C***  NICHT BESCHRIFTEN, WENN SSIZE=0
       IF (SSIZE .EQ. 0.) GOTO 219
       Y = YKAST(2) + (IY-IYMIN)*SCALEY
       X = XKAST(2) + (IX-IXMIN)*SCALEX
       CALL INPO2D(FINTE,INSIDE,X,Y,SLOPE
     >             ,R,F,T,IMAX,JMAX,MONO,MAXT,MAXR)
C***  Beschriftungs-String: 
      IF (ILEV .EQ. 0) THEN
C***     Gleichmaessige Steps:  ...ganzzahliges Vielfaches von Step
         FINTE=FINTE/STEP
         FINTE=ANINT(FINTE)
         FINTE=FINTE*STEP
        ELSE
C***     Vorgegebene Levels: ... naechstliegender Wert
         DIFF=ABS(FLEV(1)-FLEV(ILEV))
         LMIN=1
         DO 78 L=1,ILEV
            IF (ABS(FINTE-FLEV(L)).LT.DIFF) LMIN=L
78          IF (ABS(FINTE-FLEV(L)).LT.DIFF) DIFF=ABS(FINTE-FLEV(L))
         FINTE=FLEV(LMIN)
        ENDIF
      WRITE (HTEXT,ISOFOR) FINTE
      IF (HTEXT(IDX(HTEXT):IDX(HTEXT)) .EQ. '.') 
     >    HTEXT(IDX(HTEXT):IDX(HTEXT))=' '       


C***  BERECHNEN DES OFFSETS GEGENUEBER DEM ANFANGSPUNKT DER ISOLINIE
C***  - LAENGE DES TEXTSTRINGS:
C***     -  FIND THE FIRST NON-BLANK CHARACTER
      DO 80 I=1, 20
      IFIRST = I
      IF (HTEXT(I:I) .NE. ' ') GOTO 81
   80 CONTINUE
   81 TEXLEN = 0.8 * SSIZE * (1 + IDX(HTEXT) - IFIRST) 

      IF (SPUNKT) THEN
C***  SCHEITELPUNKT IM INNERN
         DXCM = -0.5 * TEXLEN
         DYCM = -1.7 * SSIZE
C***  LINKER RAND
        ELSE IF (IXMAX-IX  .GT. IYMAX-IY) THEN
         DXCM = -TEXLEN - 0.7 * SSIZE
         DYCM = -0.5 * SSIZE
        ELSE IF (IXMAX-IX  .LT.  IY-IYMIN) THEN
C***  RECHTER RAND
         DXCM =  0.7 * SSIZE
         DYCM = -0.5 * SSIZE
        ELSE
C***  UNTERER RAND
         DXCM = -0.5 * TEXLEN
         DYCM = -1.7 * SSIZE
        ENDIF

      XSCM = FLOAT(IX)/PPCM + DXCM
      YSCM = FLOAT(IY)/PPCM + DYCM

      WRITE (2,'(A10, 2X, 4(F8.3,2X), A6, 1X, A20)') 
     >        'KASDEF LUN', XSCM / XKAST(1) + XKAST(2),
     >                      YSCM / YKAST(1) + YKAST(2),
     >                      0.0, 0.0, '$SIZEL', HTEXT(IFIRST:)

C*******************************************************************
C***   ZEICHNEN DER ISOLINIE
C*******************************************************************

C***   An den anfang der Isolinie gehen
219       WRITE (2,'(A,I2,A,F10.4,A)') 
     >          'N=?  PLOTSYMBOL=',IWRSYM,'  SYMBOLSIZE=',
     >          WRSYMS,'  XYTABLE'
          WRITE (2,'(G15.7, 4X, G15.7)') 
     >          IX / PPCM / XKAST(1) + XKAST(2),
     >          IY / PPCM / YKAST(1) + YKAST(2)

       IDIR=0
220    CALL SETBIT(IX,IY,.FALSE.,IFELD, IXDIM, IYDIM)       

C****  Kodierung der Richtungen
C****  X= aktuelle Position
C****
C****           6 7 8
C****      
C****           4 X 5
C****            
C****           1 2 3
      IF (GETBIT(IX-1,IY-1,IFELD, IXDIM, IYDIM)) then
          IX=IX-1
          IY=IY-1
          IDIR=1
      ELSE if (GETBIT(IX,IY-1,IFELD, IXDIM, IYDIM)) then
          IY=IY-1
          IDIR=2
      ELSE if (GETBIT(IX+1,IY-1,IFELD, IXDIM, IYDIM)) then
          IX=IX+1
          IY=IY-1
          IDIR=3
      ELSE if (GETBIT(IX-1,IY,IFELD, IXDIM, IYDIM)) then
          IX=IX-1
          IDIR=4
      ELSE if (GETBIT(IX+1,IY,IFELD, IXDIM, IYDIM)) then
          IX=IX+1
          IDIR=5
      ELSE if (GETBIT(IX-1,IY+1,IFELD, IXDIM, IYDIM)) then
          IX=IX-1
          IY=IY+1
          IDIR=6
      ELSE if (GETBIT(IX,IY+1,IFELD, IXDIM, IYDIM)) then
          IX=IX
          IY=IY+1
          IDIR=7
      ELSE if (GETBIT(IX+1,IY+1,IFELD, IXDIM, IYDIM)) then
          IX=IX+1
          IY=IY+1
          IDIR=8

      ELSE

C***  Kein ISOBIT mehr gefunden - erst mal die Linie zu ende ziehen      
          WRITE (2,'(G15.7, 4X, G15.7)') 
     >           IX / PPCM / XKAST(1) + XKAST(2),
     >           IY / PPCM / YKAST(1) + YKAST(2)
          WRITE (2, '(A6)') 'FINISH'
C***  FALLS ISOLINIE MIT SCHEITELPUNKT BEGANN: an den Aufsatzpunkt zurueckgehen
      IF (SPUNKT) THEN
         SPUNKT=.false.
C***     FALLS DER LETZTE GEZEICHNETE PUNKT DEM AUFSATZPUNKT BENACHBART WAR
C***      --> GESCHLOSSENE KURVE, ZUM AUFSETZPUNKT ZEICHNEN, FERTIG.
         IF (IABS(IX-IXSCH) .LE. 1  .OR. IABS(IY-IYSCH) .LE. 1) THEN
C**         ZURUECKNEHMEN DES SCHON GESCHRIEBENEN "FINISH"
               BACKSPACE (2)
               WRITE (2,'(G15.7, 4X, G15.7)') 
     >           IXSCH / PPCM / XKAST(1) + XKAST(2),
     >           IYSCH / PPCM / YKAST(1) + YKAST(2)
               WRITE (2, '(A6)') 'FINISH'
            GOTO 100
            ENDIF  
         IX = IXSCH
         IY = IYSCH
         GOTO 219
         ELSE
C**   Sonst: RUECKSPRUNG IN DIE LOOP: NEUE ISOLINIE AUFSUCHEN
         GOTO 100
         ENDIF

      ENDIF

C***  Normalfall: naechster Punkt war gefunden: 
C***    --> zeichnen, falls sich die Richtung geaendert hat
      if (IDIR .NE. IDIRALT) then
         if (idir .ne. 0) THEN
               WRITE (2,'(G15.7, 4X, G15.7)') 
     >              IX / PPCM / XKAST(1) + XKAST(2),
     >              IY / PPCM / YKAST(1) + YKAST(2)
            ENDIF
         IDIRALT=IDIR
         ENDIF

      GOTO 220
C***  RUECKSPRUNG: NAECHSTES BIT, BITTE!

       END
isopro.f/       1553528659  5006  320   100644  3479      `
C      PROGRAM ISOPRO
      SUBROUTINE ISOPRO
C**********************************************************************
C***  ISOLINE CONTOUR PLOTS
C**********************************************************************

      PARAMETER (MAXT=70, MAXR=70, MAXINS=30)
      PARAMETER (IXDIM = 40)
      PARAMETER (IYDIM = 1000)

      DIMENSION T(MAXT),R(MAXT,MAXR), F(MAXT,MAXR), JMAX(MAXT)
      DIMENSION T2(MAXT), R2(MAXT,MAXR), F2(MAXT,MAXR), JMAX2(MAXT)
      DIMENSION RINS(MAXINS), FINS(MAXINS), TINS(MAXINS)

      COMMON / COMACT / ACTDRIV
      CHARACTER ACTDRIV*7



C***  ATTENTION! The following COMMON BLOCK is also dimensioned in:
C***  - SUBROUTINE INPO1D
C***  - SUBROUTINE INSERT
      COMMON /COEF/ COP(4,70,70)

      LOGICAL MONO, BPORTRAIT

      DIMENSION IFELD(0:IXDIM,0:IYDIM)

      DIMENSION FLEV(50)

      REAL XKAST(6),YKAST(6)

      CHARACTER*255 INPNAME
      CHARACTER*72 IHEAD, LETTX, LETTY
      CHARACTER*80 ISOFOR*12, NAME
      CHARACTER*80 KASDEFLINES(100)

      ACTDRIV = 'PSOWN'

      WRITE (6,10)
   10 FORMAT (//, 40('*'), /, 
     >        10X,'P R O G R A M    I S O P R O', /, 40('*'))

      WRITE (6,'(A)') 'NAME OF INPUT DATA FILE (END= CTRL D)'
      WRITE (6,'(A)') 'Present directory is:'
      CALL SYSTEM ('pwd')
      WRITE (6,'(A)') 'Press <ENTER> for default filename: isoex.iso'
    9 READ (*, '(A)', END=100) INPNAME
      IF (IDX(INPNAME) .EQ. 0) THEN
         INPNAME = 'isoex.iso'
      ENDIF
      OPEN (100, FILE=INPNAME, STATUS='OLD', ERR=90)

C***  Loop fuert jeden Isoplot
20    CALL INDAT (R, F, T, RINS, FINS, TINS, IMAXINS,
     >            JMAX, IMAX, FMIN, FMAX, 
     >            PPCM, ISYMB, GRSIZE, SXMIN, SYMIN, 
     >            ILEV,FLEV,XKAST,YKAST,IHEAD,LETTX,LETTY,SSIZE,MONO,
     >            STEP, ISOFOR, SLOPE, MAXT, MAXR, MAXINS, 
     >            IWRSYM, WRSYMS, NAME, INPNAME, KASDEFLINES, NKDLINES, 
     >            BPORTRAIT)

C***  INTERPOLATE THE INSERTED GRIDPOINTS
      CALL INSERT(R,F,T,R2,F2,T2,RINS,FINS,TINS,IMAXINS,
     >               JMAX,JMAX2,IMAX,SLOPE,MONO, MAXT, MAXR, MAXINS)

C***  RESET ARRAY COP
      DO 502  J=1,MAXR
      DO 502  I=1,MAXT
      DO 502  L=1,4
502   COP(L,I,J) = 0.

       CALL ISOREC (R, F, T, IMAX, JMAX, FMIN, FMAX, PPCM, 
     >              XKAST, YKAST, IFELD, IXDIM, IYDIM, ILEV, FLEV, MONO, 
     >              STEP, SLOPE, MAXT, MAXR)

C***  "WRPLOT ADAPTER": ASCI FILE OUTPUT IN WRPLOT FORMAT
C========================================================
      WRITE (6,*) 'PLOT WRITTEN TO FILE: isopro.plot'
      OPEN (2, FILE='isopro.plot', STATUS='UNKNOWN')

C***  PLOT BOX
      CALL KASTEN (XKAST, YKAST, LETTX, LETTY, IHEAD, KASDEFLINES,
     >             NKDLINES, BPORTRAIT)

C***  PLOT CONTOUR LINES
       CALL ISOPLO (R, F, T, IMAX, JMAX, FMIN, FMAX, PPCM,
     >             IFELD, IXDIM, IYDIM, ILEV, FLEV, SSIZE, 
     >             MONO, XKAST, YKAST, STEP, ISOFOR, SLOPE, 
     >             MAXT, MAXR, IWRSYM, WRSYMS)

C***  PLOT GRID POINTS, IF NOT SUPPRESSED
       IF (GRSIZE .NE. 0.0)
     > CALL GRID (R, T, JMAX, IMAX, PPCM, ISYMB, GRSIZE, 
     >            XKAST, YKAST, MAXT, MAXR)

C***     WRITE 'END' ON WRPLOT-FILE
         WRITE (2,'(A, /, 50(''*''))') 'END'

C***  NEXT INTERACTIVE COMMAND INPUT:
      IF (NAME .NE. '0') GOTO 20
  100 STOP 'O.K.'

C***  ERROR BRANCHES
   90 WRITE (*,'(A)') '****** ERROR: INPUT DATAFILE NOT FOUND'
      WRITE (*,'(A)') 'ENTER FILENAME:'
      GOTO 9

      END 

isorec.f/       1553528659  5006  320   100644  3008      `
C**************************************************************************
C*    Subroutine Isorec:  Iso-linien pixelweise berechnen
C**************************************************************************
      SUBROUTINE ISOREC(R, F, T, IMAX, JMAX, FMIN, FMAX, PPCM,
     >         XKAST, YKAST, IFELD, IXDIM, IYDIM, ILEV, FLEV, MONO,
     >         STEP, SLOPE, MAXT, MAXR)

      INTEGER*2 LASTIY(1024)
      LOGICAL GETBIT,MONO
      DIMENSION FLEV(50)
      DIMENSION XKAST(6), YKAST(6)

      DIMENSION IFELD(0:IXDIM,0:IYDIM)

      COMMON /ISOCOM/ IXMAX,IXMIN,IYMAX,IYMIN,SCALEX,SCALEY

C***  Mindest-Level-index soll>0 sein
      LMIN = FMIN/STEP-10

C***  Umrechnen Pixelkoordinaten auf Parameterwerte
      SCALEX = 1. / (XKAST(1) * PPCM)
      SCALEY = 1. / (YKAST(1) * PPCM)

      IXMIN = 0
      IYMIN = 0
      IXMAX = INT( (XKAST(3) - XKAST(2)) / SCALEX)
      IYMAX = INT( (YKAST(3) - YKAST(2)) / SCALEY)

      IF (IXMAX/32 .GT. IXDIM) THEN
         PRINT *, '*** DIMENSION IXDIM INSUFFICIENT'
         PRINT *, '*** PRESENT  DIMENSION: ', IXDIM
         PRINT *, '*** REQUIRED DIMENSION: ', IXMAX/32
         STOP '*** ERROR DETECTED IN ISOREC (ISOPRO)'
      ENDIF
      IF (IYMAX .GT. IYDIM) THEN
         PRINT *, '*** DIMENSION IYDIM INSUFFICIENT'
         PRINT *, '*** PRESENT  DIMENSION: ', IYDIM
         PRINT *, '*** REQUIRED DIMENSION: ', IYMAX
         STOP '*** ERROR DETECTED IN ISOREC (ISOPRO)'
      ENDIF

C***  Isolinien pixelweise aufbauen und IM ARRAY IFELD AUFHEBEN
C***  Loop ueber den Zeilenindex
      DO 10 IY=IYMIN, IYMAX
       Y = YKAST(2) + (IY-IYMIN) * SCALEY

C**    Schleife ueber den spaltenindex
       DO 20 IX=IXMIN, IXMAX
       X = XKAST(2) + (IX-IXMIN)*SCALEX

C***   Funktionswert interpolieren
       CALL SETBIT(IX,IY,.FALSE.,IFELD, IXDIM, IYDIM)
       CALL INPO2D(FINTE,INSIDE,X,Y,SLOPE
     >             ,R,F,T,IMAX,JMAX,mono,MAXT,MAXR)
       LEVEL = 0
       IF (INSIDE .EQ. 0) GOTO 30

C***   Berechnen von Hoehenstufen
       IF (ILEV .NE. 0) GOTO 41
       LEVEL = FINTE/STEP-LMIN
       GOTO 43
41     CONTINUE
       LEVEL = 10
       DO 42 L=1, ILEV
       IF (FINTE .GE. FLEV(L)) LEVEL=LEVEL+1
42     CONTINUE
43     CONTINUE

C***   ISO-Bit setzen
       IF (IX .NE. IXMIN) 
     >     CALL SETBIT(IX,IY,
     >           (LASTIX.NE.LEVEL) .AND. (LASTIX .NE. 0),
     >           IFELD, IXDIM, IYDIM)
       IF (IY.NE.IYMIN)
     >  CALL SETBIT(IX,IY,
     >      (GETBIT(IX,IY,IFELD, IXDIM, IYDIM) .OR. 
     >       (LEVEL .NE. LASTIY(IX))) .AND. LASTIY(IX) .NE. 0,
     >              IFELD, IXDIM, IYDIM)
       IF (IX .EQ. IXMIN) GOTO 30
       IF (GETBIT(IX-1,IY,IFELD, IXDIM, IYDIM) .AND. 
     >     GETBIT(IX,  IY,IFELD, IXDIM, IYDIM) .AND.
     >     GETBIT(IX-1,IY-1,IFELD, IXDIM, IYDIM))
     >       CALL SETBIT(IX-1,IY,.FALSE.,IFELD, IXDIM, IYDIM)

C***   Alte werte aufheben
30     LASTIY(IX) = LEVEL
       LASTIX = LEVEL

20     CONTINUE

10    CONTINUE



C      ======
       return
C      ======

       end
istrl.f/        1553528659  5006  320   100644  442       `
      FUNCTION ISTRL (LINE)
C********************************************************************
C***  BESTIMMT DIE LAENGE EINES STRINGS OHNE DIE BLANKS, DIE AM   ***
C***    ENDE DES STRINGS EVTL. AUFTRETEN, ZU BERUECKSICHTIGEN.    ***
C********************************************************************

      CHARACTER*132 LINE

      I = 133
    1 I = I - 1
      IF(LINE(I:I) .EQ. ' ') GOTO 1

      ISTRL = I

      RETURN
      END
itolvek.f/      1553528659  5006  320   100644  612       `

C***********************************************************
C**  Subroutine ItoLVEK : zerlegt ein Integer*4-Wort in    *
C**                       31 einzelne logicals             *
C***********************************************************

      Subroutine ItoLVEK(IV,LV)

C In:
      Integer*4 IV

C Out:
      logical LV(31)

C local:
      Integer*4 I
C     Damit kann er auf I arbeiten, ohne das IV veraendert wird
C     (Wegen Call by Reference)

      I=IV
C     lokale Kopie von IV

      Do 10  IB=1,31

      LV(IB)=((I/2)*2) .ne. I

10    I=I/2

C     ======
      return
C     ======

      end
iuedat.f/       1553528659  5006  320   100644  4064      `
	subroutine iuedat

C***    IUE Datenkonvertierung fuer UNIX-Files ohne CR
C***    Bytes werden nicht geswapt

	integer*2 buf0(1024),buf(1024,7)
        character fname*20
        logical expt

        expt = .false.

        write(*,*) ' Input file :'
        read(5,'(a)') fname

  12    write(*,*) ' Record length : (1) 1204 Bytes for HIRES, old',
     >                                               ' LORES'
        write(*,*) '                 (2) 2048 Bytes for new LORES'
        read(5,*) khelp

        if (khelp .eq. 1) then
          lenrec = 1204
          open (10,file=fname,status='OLD',access='direct',recl=1204,
     >           form='UNFORMATTED')
        else if (khelp .eq. 2) then
          lenrec = 2048
          open (10,file=fname,status='OLD',access='direct',recl=2048,
     >           form='UNFORMATTED')
        else
          goto 12
        endif

        open (9,file='IUE_CONV.DAT',form='FORMATTED',status='NEW')

        iacc=1
	read (10,rec=iacc) (buf0(i),i=1,lenrec/2)
        iacc=iacc+1

	write(9,*) '* Lambda min : ',buf0(3)
	write(9,*) '* Lambda max : ',buf0(4)
	write(9,*) '* # of orders: ',buf0(5)
	write(9,*) '* # of Camera: ',buf0(6)
	write(9,*) '* # of Image : ',buf0(7)
	write(9,*) '* # rec per order : ',buf0(8)
	write(9,*) '* Aperture   : ',buf0(17)
	write(9,*) '* J for gross: ',buf0(23)
	write(9,*) '* K for gross: ',buf0(24)
	write(9,*) '* J for back : ',buf0(27)
	write(9,*) '* K for back : ',buf0(28)
	write(9,*) '* J for net  : ',buf0(31)
	write(9,*) '* K for net  : ',buf0(32)
	write(9,*) '* J for abs. : ',buf0(35)
	write(9,*) '* K for abs. : ',buf0(36)
	write(9,*) '* lambda0 1.order : ',buf0(103)

        if ((buf0(59) .ne. 5) .and. (buf0(59) .ne. 500)) then
           write(*,*) 'What resolution ?'
           write(*,*) '  1 = low    2 = high'
    3      read(*,*) ireso
           if ((ireso .ne. 1) .and. (ireso .ne. 2)) goto3
           if (ireso .eq. 1) buf0(59)=5
           if (ireso .eq. 2) buf0(59)=500
        endif

        write(*,*) ' Art of spectrum :'
        if (buf0(59) .eq. 5) then
           write(*,*) '       1=GROSS  2=BACKGR  3=NET  4=ABS FLUX'
           else
           write(*,*) '       1=GROSS  2=BACKGR  3=NET  4=RIP NET'
        endif
    5   read(*,*) art
        if ((art .lt. 1).or.(art .gt. 4)) goto5
        iart=int(art)

        exptime = float(60*buf0(42) + buf0(43)) + float(buf0(44))/1000.

        if (exptime .gt. 0.) goto20

        if ((buf0(59) .eq. 5).and.(iart .eq. 4)) then
           write(*,*) ' Exposure time in seconds: '
   15      read(*,*) exptin
           if (exptin .le. 0) goto 15
           exptime = exptin
           expt = .true.
        endif

   20   continue

C**  read all orders

	do 40 norder=1,buf0(5)
	write(*,*)'++++++++++++++++++++++++++++'
	write(*,*)'order #: ',norder
	write(*,*)'Data for this order:'
	write(*,*)'Lambda-0: ',buf0(102+norder)
	write(*,*)'++++++++++++++++++++++++++++'
	write(9,*)'* ++++++++++++++++++++++++++++',norder

C**  read a group of 6 records per order

         if ((buf0(8) .ne. 6).and.(buf0(8) .ne. 7)) then
            write(*,*) 'SORRY, UNKNOWN NUMBER OF RECORDS PER ORDER.'
            write(*,*) 'INPUT (TRY 6 OR 7):'
            read(5,*) buf0(8)
         endif

	do 35 nr=1,buf0(8)
	read (10,rec=iacc) (buf(i,nr),i=1,lenrec/2)
        iacc=iacc+1
   35   continue

C** end loop for records of one order
         jhelp=iart+2
         fll1= float(buf0(59))
         fll2= float(buf0(102+norder))
         khelp=19+4*iart  
         if (buf0(khelp) .eq. 0) then
            write(*,*) 'SORRY, ERROR ON IMAGE (SCALE FACTOR J).'
            goto99
         endif
         fli1=float(buf0(khelp))
         fli2=float(buf0(khelp+1))

	 do 45 i=3,buf(2,1)
	 xl=buf(i,1)
	 xl=xl/fll1 + fll2
	 xi=buf(i,jhelp)
	 xi=xi*fli1*(2**(-fli2))
         if (expt) xi = xi/exptime
	 write (9,*) xl,xi
  45	continue

  40	continue

        write(*,*)' '
        write(*,*)'Converted spectrum saved in IUE_CONV.DAT .'

C** end loop over all orders

  99    continue
        close(9)
        close(10)
  100	end

ivar.f/         1553528659  5006  320   100644  917       `
      FUNCTION IVAR (ACTPAR, VAR, MAXVAR, NVAR, CIVAR)
C*********************************************************
C***  Bestimmt die Index-Nummer einer Variablen
C***  CIVAR ist Output (OLD, NEW) je nachdem, 
C***    ob die Variable schon bekannt ist
C*********************************************************


      CHARACTER*(*) VAR(MAXVAR,2)
      CHARACTER*(*) ACTPAR
      CHARACTER*3 CIVAR

      I = 1
    5 CONTINUE
        IF (ACTPAR .EQ. VAR(I,1)) THEN
          CIVAR = 'OLD'
          GOTO 100
        ENDIF
        I = I + 1
      IF (I .LE. NVAR) GOTO 5
      NVAR = I
      VAR(I,1) = ACTPAR
      VAR(I,2) = ' '
      CIVAR = 'NEW'
      IF (NVAR .GT. MAXVAR) THEN
        WRITE (*,*) 'Variable ',ACTPAR( :IDX(ACTPAR)),
     >              ' can not be adressed'
        WRITE (*,*) 'More variables used than dimensioned'
        STOP 'IVAR'
      ENDIF

  100 IVAR = I
      
      RETURN
      END

kasex.f/        1653499910  5006  320   100644  6923      `
      SUBROUTINE KASEX

      CHARACTER*255, TABIN, KASOUT
      CHARACTER*60 ACTPAR, ACTPAR2, ACTPAR3
      CHARACTER*60 KO, SX, VX, SY, VY, SS, SS2, SSB, SS3, SSY, SB
      CHARACTER*132 LINE
      LOGICAL BSTART

      KASOUT = 'wrplot.kasdef'

      WRITE(*,*) 'GEBEN SIE DEN NAMEN DER TABELLE EIN:'
      WRITE (6,'(A)') 'Present directory is:'
      CALL SYSTEM ('pwd')
      READ (*, '(A)') TABIN
      OPEN (UNIT=1, FILE=TABIN, STATUS='OLD', ERR=99, ACTION='READ', 
     >      RECL=132)
      WRITE (6,*) 'FILE OPENED: ', TABIN(:IDX(TABIN))

      OPEN (UNIT=2,FILE=KASOUT, STATUS='UNKNOWN',ERR=98)

      WRITE(*,*) 'GEBEN SIE DIE SPALTE MIT DEN X-KOORDINATEN AN:'
      READ (5,*) IX
      WRITE(*,*) 'GEBEN SIE DIE VORSILBE AN: (z.B. LOG oder DEX)'
      READ (5,'(A)') VX

      WRITE(*,*) 'GEBEN SIE DIE SPALTE MIT DEN Y-KOORDINATEN AN:'
      READ (5,*) IY
      WRITE(*,*) 'GEBEN SIE DIE VORSILBE AN: (z.B. LOG oder DEX)'
      READ (5,'(A)') VY

      WRITE(*,*) 'SPALTE DER BESCHRIFTUNG? 0:IGNORE'
      READ (5,*) IB

      WRITE(*,*) 'GEBEN SIE DIE BESCHRIFTUNGSGROESSE AN: '
      READ (5,'(A)') SSB

      READ (SSB, '(BN,F10.0)', ERR=96) SIZE
      SIZE3 = -SIZE / 2.
      WRITE (SS3, '(F10.5)', ERR=95) SIZE3
      CALL SARGV(SS3, 1, ACTPAR)
      SS3 = ACTPAR
      ID = IDX(SS3)
      I = ID + 1
4     I = I - 1
      IF (SS3(I:I) .EQ. '0') GOTO 4
      SS3 = SS3(:I)     

      WRITE(*,*) 'SPALTE DER KOMMENTARS? 0:IGNORE'
      READ (5,*) IK

      WRITE(*,*) 'GEBEN SIE DIE SPALTE DES SYMBOLS AN: O:EXIT'
      READ(*,*) ISSG
      IF (ISSG .EQ. 0) THEN
        WRITE(*,*) 'GEBEN SIE DAS SYMBOL DIREKT EIN:'
        READ (5,'(A)') SSY
      ENDIF

      WRITE(*,*) 'GEBEN SIE DIE SPALTE DER SYMBOLGROESSE AN: 0:(EXIT)'
      READ (5,*) ISG
      IF (ISG .EQ. 0) THEN
        WRITE(*,*) 'GEBEN SIE DIE SYMBOLGROESSE DIREKT EIN:'
        READ (5,'(A)') SS
      ENDIF

      WRITE(2,'(2A)') '*INPUT-FILE : ',TABIN(:IDX(TABIN))
      WRITE(2,'(A)') '*'
C***  INFO
      WRITE (2,'(A)') 'KASDEF LUN XMAX YMAX  0.2 -7.0  0.2 Info :'
      WRITE(2,'(A1,A23,I2,A23,A6)') '*', 'SPALTE X: ', IX,
     >           '   VORSILBE: ', VX(:IDX(VX))
      WRITE(2,'(A,A,I2,A,A)') 'KASDEF NEXTLUN &E', 'SPALTE X: ',IX,
     >           '   VORSILBE: ', VX(:IDX(VX))

      WRITE(2,'(A1,A23,I2,A23,A6)') '*', 'SPALTE Y: ', IY,
     >           '   VORSILBE: ', VY(:IDX(VY))
      WRITE(2,'(A,A,I2,A,A)') 'KASDEF NEXTLUN &E', 'SPALTE Y: ',IY,
     >           '   VORSILBE: ', VY(:IDX(VY))

      WRITE(2,'(A1,A23,I2,A23,A6)') '*', 'SPALTE BESCHRIFTUNG: ', IB,
     >           '  GROESSE: ', SSB(:IDX(SSB))
      WRITE(2,'(A,A,I2,A,A)') 'KASDEF NEXTLUN &E', 
     >           'SPALTE BESCHRIFTUNG: ', IB,
     >           '  GROESSE: ', SSB(:IDX(SSB))

      WRITE(2,'(A1,A23,I2)') '*', 'SPALTE KOMMENTAR: ',IK
      WRITE(2,'(A,A,I2)') 'KASDEF NEXTLUN &E','SPALTE KOMMENTAR: ',IK

      IF (ISSG .GT. 0) THEN
        WRITE(2,'(A1,A23,I2)') '*', 'SPALTE SYMBOL: ', ISSG
        WRITE(2,'(A,A,I2)') 'KASDEF NEXTLUN &E','SPALTE SYMBOL: ',ISSG
      ELSE
        WRITE(2,'(A1,2(A23))') '*', 'SYMBOL: ', SSY(:IDX(SSY))
        WRITE(2,'(A,2(A))') 'KASDDEF NEXTLUN &E', 
     >                         'SYMBOL: ', SSY(:IDX(SSY))
      ENDIF
      IF (ISG .GT. 0) THEN
        WRITE(2,'(A1,A23,I2)') '*', 'SPALTE SYMBOLGROESSE: ', ISG
        WRITE(2,'(A,A,I2)') 'KASDEF NEXTLUN &E', 
     >                         'SPALTE SYMBOLGROESSE: ', ISG
      ELSE
        WRITE(2,'(A1,2(A23))') '*', 'SYMBOLGROESSE: ', SS(:IDX(SS))
        WRITE(2,'(A,2(A))') 'KASDEF NEXTLUN &E', 
     >                         'SYMBOLGROESSE: ', SS(:IDX(SS))
      ENDIF
      WRITE(2,'(A1)') '*'

      BSTART = .FALSE.

10    CONTINUE
C***  ZEILE LESEN
      READ (1, '(A)', END=20, ERR=97) LINE
      CALL SARGV (LINE, 1, ACTPAR)
      CALL SARGV (LINE, 2, ACTPAR2)
      CALL SARGV (LINE, 3, ACTPAR3)
      IF (.NOT. BSTART .AND. ACTPAR .EQ. '*' .AND. 
     >    ACTPAR2 .EQ. 'KASEX' .AND. ACTPAR3 .EQ. 'START') THEN
          BSTART = .TRUE.
          GOTO 10
      ENDIF
      IF (.NOT. BSTART) GOTO 10
      IF (ACTPAR .EQ. '*' .AND. 
     >    ACTPAR2 .EQ. 'KASEX' .AND. ACTPAR3 .EQ. 'END') THEN
        BSTART = .FALSE.
        GOTO 10
      ENDIF
      IF (ACTPAR(1:1) .EQ. '*') THEN
        WRITE (2, '(A)') LINE(:IDX(LINE))
        GOTO 10
      ENDIF

      CALL SARGC (LINE, NPAR)
      IF (IX .GT. NPAR .OR. IY .GT. NPAR .OR. IB .GT. NPAR) THEN
        WRITE(*,*) 'NICHT GENUG SPALTEN'
        WRITE(*,*) 'LINE IGNORED:'
        WRITE(*,*) LINE(:IDX(LINE))
        GOTO 10
      ENDIF

C***  ZEILE AUSWERTEN

      CALL SARGV (LINE, IX, ACTPAR)
      READ (ACTPAR, '(A)', ERR=96) SX
      SX = VX(:IDX(VX)) // SX

      CALL SARGV (LINE, IY, ACTPAR)
      READ (ACTPAR, '(A)', ERR=96) SY
      SY = VY(:IDX(VY)) // SY

      IF (IB .GT. 0) THEN
        CALL SARGV (LINE, IB, ACTPAR)
        READ (ACTPAR, '(A)', ERR=96) SB
      ENDIF

      IF (IK .GT. 0) THEN
        CALL SARGV (LINE, IK, ACTPAR)
        READ (ACTPAR, '(A)', ERR=96) KO
      ENDIF

      IF (ISG .GT. 0) THEN
        CALL SARGV (LINE, ISG, ACTPAR)
        READ (ACTPAR, '(A)', ERR=96) SS
      ENDIF
      READ (SS, '(BN,F10.0)', ERR=96) SIZE
      SIZE2 = ABS(SIZE) /2. + 0.05
      WRITE (SS2, '(F10.5)', ERR=95) SIZE2
      CALL SARGV(SS2, 1, ACTPAR)
      SS2 = ACTPAR
      ID = IDX(SS2)
      I = ID + 1
2     I = I - 1
      IF (SS2(I:I) .EQ. '0') GOTO 2
      SS2 = SS2(:I)     

      IF (ISSG .GT. 0) THEN
        CALL SARGV (LINE, ISSG, ACTPAR)
        READ (ACTPAR, '(A)', ERR=96) SSY
      ENDIF

C***  INS OUTPUTFILE SCHREIBEN
      IDSX = IDX(SX)
      IDSY = IDX(SY)
      IDSS = IDX(SS)
      IDSS2 = IDX(SS2)
      IDSSB = IDX(SSB)
      IDSS3 = IDX(SS3)
      IDSSY = IDX(SSY)
      IDSB = IDX(SB)
      IDKO = IDX(KO)

      IF (IK .GT. 0) THEN
        LINE = '*  '//SB(:IDSB)//'  '//KO(:IDKO)
        WRITE (2, '(A)') LINE(:IDX(LINE))
      ENDIF

C***  SYMBOL-ZEILE
      LINE = 'KASDEF SYM  '//SX(:IDSX)//'  '//SY(:IDSY)//
     >       '  0. 0.  '//SS(:IDSS)//'  '//SSY(:IDSSY)
      WRITE (2, '(A)') LINE(:IDX(LINE))
      IF (IB .GT. 0) THEN

C***  BESCHRIFTUNGSZEILE
        LINE = 'KASDEF LUN  '//SX(:IDSX)//'  '//SY(:IDSY)//
     >         '  L'//SS2(:IDSS2)//'  M0.  '//
     >         SSB(:IDSSB)//'  '//SB(:IDSB)
      WRITE (2, '(A)') LINE(:IDX(LINE))
      ENDIF
      GOTO 10

20    WRITE(*,*) 'FINISHED'
      WRITE(*,*) 'OUTPUT-FILE:'
      WRITE(*,*) KASOUT(:IDX(KASOUT))
      STOP

95    WRITE(*,*) 'ERROR WHEN WRITING -SIZE/2'
      STOP

96    WRITE(*,*) 'ERROR WHEN READING ACTPAR:'
      WRITE(*,*) LINE
      WRITE(*,*) ACTPAR
      STOP

97    WRITE(*,*) 'ERROR WHEN READING INPUT-FILE:'
      WRITE(*,*) TABIN
      STOP


98    WRITE(*,*) 'ERROR WHEN OPENING OUTPUT-FILE:'
      WRITE(*,*) KASOUT
      STOP

99    WRITE(*,*) 'ERROR WHEN OPENING INPUT-FILE:'
      WRITE(*,*) TABIN
      STOP

      END

kasten.f/       1553528659  5006  320   100644  1232      `
      SUBROUTINE KASTEN (B, C, XTEXT, YTEXT, HEADER, KASDEFLINES,
     >                   NKDLINES, BPORTRAIT)
C********************************************************
C***  Zeichnet Kasten fuer ISOPLOT  (called from: ISOPRO)
C********************************************************
      
      CHARACTER*72 XTEXT, YTEXT, HEADER
      CHARACTER*80 KASDEFLINES(100)
      REAL B(6), C(6)
      LOGICAL BPORTRAIT
      IF (BPORTRAIT) THEN
         WRITE (2, '(A)') 'PAPERFORMAT A4H'
         WRITE (2, '(A)') 'FORMATFACTOR 0.8'
      ENDIF

         WRITE (2, '(A)') 'PLOT   :' // HEADER
         WRITE (2, '(A)') 'KASDEF VAR SIZEL=0.2'
         WRITE (2, '(A)') 'KASDEF VAR SIZES=0.2'
         WRITE (2, '(A)') 'KASDEF INBOX'
         DO I=1, NKDLINES
            WRITE (2, '(A)') KASDEFLINES(I)
         ENDDO
         WRITE (2, '(A)') 'HEADER :' // HEADER
         WRITE (2, '(A)') 'X-ACHSE:' // XTEXT
         WRITE (2, '(A)') 'Y-ACHSE:' // YTEXT
         WRITE (2, '(9X, 2A)') 
     >           'MASSTAB    MINIMUM    MAXIMUM    TEILUNG ',
     >           'BESCHRIFT. DARUNTER'
         WRITE (2, '(A2,4X,6(2X,F8.4))') 'X:',(B(I), I=1,6)
         WRITE (2, '(A2,4X,6(2X,F8.4))') 'Y:',(C(I), I=1,6)

      RETURN  
      END
kdplot.f/       1553528659  5006  320   100644  30154     `
      SUBROUTINE KDPLOT (B, C, KDLINE, NKD, NKDMAX, NKDP, KDPAUSE, 
     >                   IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >                   BINSEX, XCMA, YCMA, NDATMAX)

C***********************************************************************
C***  WRPLOT PROGRAM:
C***  PLOTTING OF KASDEF OPTIONS
C***  THIS SUBROUTINE IS CALLED FROM MAIN PROGRAM WRPLOT
C***     and from PLOTBUTT, PLOTMESS and PLOTPOINT !
C***********************************************************************

      PARAMETER (MULTMAX = 20)
      PARAMETER (KDMAXLEN = 400)
      DIMENSION B(6),C(6)
      DIMENSION XCMA(NDATMAX), YCMA(NDATMAX)
      LOGICAL   KDPAUSE
      LOGICAL   BBGR, BINSEX, BLUNINC, BTAB, BCOMPAT, BHATCH
      LOGICAL   BBLOCK, ITEM, CHRINSTR, GLATEX
      LOGICAL   IDNORM, IDMCOMB, BIDLOG, IDCON, ID_INBOX
      LOGICAL   BTEXTLINESKIP
      CHARACTER*(*) VAR(MAXVAR,2)
      CHARACTER FNAME*255, LINE1*132 
      CHARACTER EXNAM*255
      CHARACTER LINE*(KDMAXLEN), TLAB*144, TLUN*(KDMAXLEN), 
     >          TTRA*144, LINEOLD*(KDMAXLEN), BGRLINE*(KDMAXLEN)
      CHARACTER KDLINE(NKDMAX)*132
      CHARACTER ACTPAR*20, ACTPAR2*20, CFILL*2
      CHARACTER*1 PPX, PPY, CC, BACKSLASH
      CHARACTER ITEMSTRING*30, SLEEP*20

C***  ACTIVE GRAPHIC DRIVER
      COMMON / COMACT / ACTDRIV
      CHARACTER ACTDRIV*7

C***  Postscript Font select
      COMMON / COMFONT / FONT
      CHARACTER FONT*6

C***  Linewidth parameters
      COMMON / COMPEN /IDUMMY, HALFLINW

C***  Conversion factor cm -> pt defined in PS_PLOTS
      COMMON / COMCMPT / CMPT 

C***  LAST COLOR
      COMMON / COMCOLOR / LASTCOLOR

C***  Limits for the number of colors (X11, DEFINECOLOR)
      COMMON /LIMITCOLOR/ LIMCOL_ON, LIMCOLR, LIMCOLG, LIMCOLB

C***  Limits for the number of colors (X11) in one COLORTABLE
      COMMON /COMNCOLSTEP/ NCOLSTEP

C***  Blocktext and SQUEEZE-Parameter for ps_symbl and x_symbl
      COMMON / COMBLOCK / BBLOCK, SQUEEZE

C***  GLATEX style for SUBR. MYSYMBL and MYTLEN
      COMMON / COMGLATEX / GLATEX

C***  SCALING FOR LaTex strings (SUBR. KD_LATEXAND INLATEX)
      COMMON / COM_LATEX / SCALE_LATEX

C***  Compatibility switch if non-INSTRUCTIONS found in EXPORT block
C***  The switch is set in KDSET
      COMMON / COMCOMPAT / BCOMPAT

      DATA PI / 3.14159 /

      SAVE 

      BACKSLASH = CHAR(92)

C**********************************************************
C***  PLOTTING OF "KASDEF" OPTIONS
C**********************************************************

C***  DEFAULT PEN:
      LASTPEN=1
      CALL PEN (LASTPEN, IDEV)

C***  DEFAULT COLOR:
      ICOLOR = 1 
      CALL COLOR ('DATA', 'DUMMY', ICOLOR, IDEV)

C***  DEFAULT FOR TABULATOR ENVIRONMENT
      BTAB = .FALSE.

C***  NO RESET IF DELAYED KASDEF 
      IF (.NOT. KDPAUSE) THEN

C***  Default lettersize for LUN and related output
      SIZELUN = 0.4

C***  DEFAULT IDENT SIZE
        SIZEID = 0.4
        SIZEFAC = 1.5
        SIZEID2 = SIZEID * SIZEFAC

C***  RESET IDENT COUNTER, YID AND OFFSET IN X-DIRECTION
        IID = 0
        YID = 8.
        XOFFID = 0.
        XFACID = 1.
        IDNORM = .TRUE.
        XLENGID = 1.4
        IDMCOMB = .FALSE.     
        XIDMLEN1 = 0.43
        XIDMLEN2 = 0.43
        XIDMLEN3 = 0.14
        IDDIR = 1
        IDCON = .FALSE.
        BIDLOG = .FALSE.
        ID_INBOX = .FALSE.

C***  DEFAULT VALUES FOR ERROR BARS
        BARLN = 0.
        BARLW = 0.
        BARLS = 0.
        BARLO = 0.
        BARSP = 0.
        BAREDGE = 0.

C***  DEFAULT VALUES FOR BGRLUN
        BGRL_R = 0.5
        BGRR_R = 0.5
        BGRU_R = 0.5
        BGRD_R = 0.5
        BGRL = BGRL_R
        BGRR = BGRR_R
        BGRU = BGRU_R
        BGRD = BGRD_R
        IBGRCOL = 0
        BBGR = .FALSE.

C***  Default Character Font 
        FONT = 'WRPLOT'
      ENDIF

C***  Default baselineskip fur LUN and TEXT
      DYSIZELUN = 2.
      DYCMLUN   = .0
C***  ERROR if YLUNOFS used but never initialized:
      YLUNOFS = -9999.

C***  Default: Rechter textrand, von links gemessen
      RIGHTMARG = 18.   

C***  Running text as block (default = OFF)
      BBLOCK = .FALSE.

C***  GLatex style ("a for a Umlaut etc.) - default = OFF
      GLATEX = .FALSE.

C***  Itemize for LUN and TEXT (default=OFF)
      ITEM = .FALSE.
      SQUEEZE = 1.
      SEPITEMCM = .0
      SEPITEMSZ = .0

C***  Number of colors not limited
      LIMCOL_ON = 0

C***  Number of color steps in a Color Table
      NCOLSTEP = 200

C***  Scaling factor of LaTex parts (COMMON BLOCK COM_LATEX) 
      SCALE_LATEX = 1.0

C***  Seperate LINESKIP for text given?
      BTEXTLINESKIP = .FALSE.

C***  INSTRUCTION NO-EXPORT is default at start
      BINSEX = .FALSE.

      IKD = NKDP 

C***  Loop for each KASDEF Option **************************************
    4 CONTINUE

C***  exit, if there are no KASDEF lines after a PAUSE
      IF (IKD .GT. NKD) GOTO 5

      LINE = KDLINE(IKD)

ccc   test output!!
ccc      write (*,'(A,I5,2A)') 'KDPLOT LINE', IKD, ':', LINE( :IDX(LINE))

C***  Append possible continuation lines KASDEF >
      NCONTLINES = 0
    1 IF (IKD+NCONTLINES .LT. NKD) THEN
         CALL SARGREST (KDLINE(IKD+1+NCONTLINES), NPAR, 2, IFIRST,ILAST)
         IF (NPAR .GT. 1 .AND. 
     >       KDLINE(IKD+1+NCONTLINES)(IFIRST:IFIRST) .EQ. '>') THEN
            NCONTLINES = NCONTLINES + 1
            LINE1 = KDLINE(IKD+NCONTLINES)(IFIRST+1:ILAST)
            LAST = IDX(LINE)
            IF (LAST+IDX(LINE1)-1 .GT. KDMAXLEN) GOTO 95
            LINE(LAST+1:) = LINE1
            GOTO 1
         ENDIF
      ENDIF

C***  EXPAND ALL VARIABLES
      CALL EXPANDVAR (LINE, VAR, MAXVAR, NVAR)

C***  Extract second parameter
      CALL SARGV(LINE,2,ACTPAR)

C***  KASDEF PAUSE  (STOP PLOTTING KASDEFS HERE, GO ON AFTER PLOTDAT)
C-----------------------
      IF (ACTPAR .EQ. 'PAUSE' .AND. .NOT. KDPAUSE) THEN
        KDPAUSE = .TRUE.
        NKDP = IKD + 1 + NCONTLINES
        GOTO 5

C***  KASDEF PEN  (IMMEDIATE SETTING OF CURRENT PEN) ***
C-----------------------
      ELSE IF (ACTPAR .EQ. 'PEN') THEN
         CALL SARGVR (LINE, 3, ACTPAR)
         READ (ACTPAR,'(10X,I10)', ERR=96) KPEN
         CALL PEN (KPEN, IDEV)
         LASTPEN = KPEN
C***     RESTORE COLOR (Calcomp only)      
         IF (ACTDRIV .EQ. 'CALCOMP') 
     >      CALL COLOR ('DATA', 'DUMMY', ICOLOR, IDEV)


C***  KASDEF LAB  ***
C-----------------------
      ELSE IF (ACTPAR .EQ. 'LAB') THEN
          CALL SARGVR (LINE, 3, ACTPAR)
          READ (ACTPAR, '(F20.0)', ERR=96) XLAB
          CALL SARGVR (LINE, 4, ACTPAR)
          READ (ACTPAR, '(F20.0)', ERR=96) YLAB
          CALL SARGVR (LINE, 5, ACTPAR)
          READ (ACTPAR, '(F20.0)', ERR=96) SLAB
          CALL SARGREST (LINE, N, 6, NSTART, NN)
          TLAB = LINE(NSTART:)
          CALL MYSYMBL (XLAB, YLAB, SLAB, TLAB, .0)    
             
C***  KASDEF RIGHTMARGIN  ***
C-----------------------
      ELSE IF (ACTPAR(:9) .EQ. 'RIGHTMARG') THEN
          CALL SARGVR (LINE, 3, ACTPAR)
          READ (ACTPAR, '(F20.0)', ERR=96) RIGHTMARG

C***  KASDEF BGRLUN  ***
C-----------------------
      ELSE IF (ACTPAR .EQ. 'BGRLUN') THEN
         BBGR = .TRUE.
         CALL SARGC (LINE, N)
	 I = 3
  161      IF (I .GT. N) GOTO 162
           CALL SARGV (LINE, I, ACTPAR)
           IF (ACTPAR .EQ. 'OFF') THEN
              BBGR = .FALSE.
           ELSE IF (ACTPAR .EQ. 'ON') THEN
           ELSE IF (ACTPAR .EQ. 'RESET') THEN
            BGRL = BGRL_R
            BGRR = BGRR_R
            BGRU = BGRU_R
            BGRD = BGRD_R
            IBGRCOL = 0
           ELSE IF (ACTPAR .EQ. 'COLOR') THEN
              I = I + 1
              IF (I .GT. N) GOTO 162
              CALL SARGVR (LINE, I, ACTPAR2)
              READ (ACTPAR2, '(18X,I2)', ERR=96) IBGRCOL
           ELSE IF (ACTPAR .EQ. 'L') THEN
              I = I + 1
              IF (I .GT. N) GOTO 162
              CALL SARGVR (LINE, I, ACTPAR2)
              READ (ACTPAR2, '(F20.0)', ERR=96) BGRL
           ELSE IF (ACTPAR .EQ. 'R') THEN
              I = I + 1
              IF (I .GT. N) GOTO 162
              CALL SARGVR (LINE, I, ACTPAR2)
              READ (ACTPAR2, '(F20.0)', ERR=96) BGRR
           ELSE IF (ACTPAR .EQ. 'U') THEN
              I = I + 1
              IF (I .GT. N) GOTO 162
              CALL SARGVR (LINE, I, ACTPAR2)
              READ (ACTPAR2, '(F20.0)', ERR=96) BGRU
           ELSE IF (ACTPAR .EQ. 'D') THEN
              I = I + 1
              IF (I .GT. N) GOTO 162
              CALL SARGVR (LINE, I, ACTPAR2)
              READ (ACTPAR2, '(F20.0)', ERR=96) BGRD
           ELSE IF (ACTPAR .EQ. 'HATCHED' .OR. ACTPAR .EQ.'HTYPE') THEN
              BHATCH = .TRUE.
              BGRLINE = LINE
           ENDIF
           I = I + 1
           GOTO 161
  162       CONTINUE
             
C***  KASDEF HLINE
C-----------------------
      ELSE IF (ACTPAR .EQ. 'HLINE') THEN
        CALL KD_HLINE (XLUNOFS, YLUNOFS, DYCMLUN, DYSIZELUN, 
     >           SIZELUN, XUNITS, YUNITS, B, C, YO2, BTAB, 
     >           RIGHTMARG, TABLEFTMARGIN, TABRIGHTMARGIN)

C***  KASDEF LUN / NEXTLUN / SAMELUN / LUNINC ***
C-----------------------
      ELSE IF (ACTPAR .EQ. 'LUN' .OR. 
     >         ACTPAR .EQ. 'NEXTLUN' .OR. 
     >         ACTPAR .EQ. 'SAMELUN' .OR. 
     >         ACTPAR .EQ. 'LUNINC') THEN
          IF (ITEM) THEN
	     IF (ACTPAR .NE. 'SAMELUN') 
     >          YLUNOFS = YLUNOFS - SEPITEMCM - SEPITEMSZ*SIZELUN
          ENDIF
          CALL KD_LUN (LINE, ACTPAR, XLUNOFS, YLUNOFS, DYCMLUN, 
     >         DYSIZELUN, SIZELUN, B, C, XUNITS, YUNITS, 
     >         TLUN, ITEM, BBGR, SIZEITEM, PPX, PPY, YO2, IBGRCOL,
     >         LASTCOLOR, BGRL, BGRR, BGRD, BGRU, ITEMSTRING, XINDENT,
     >         BGRLINE)
C         Provide a variable with the NEXTLUN position
          WRITE (ACTPAR2, '(F20.10)') YLUNOFS
          CALL FLUSHLEFT (ACTPAR2)
          CALL PUTVAR ('NEXT_YOFS', ACTPAR2, VAR, MAXVAR, NVAR)
 

C***  KASDEF BLOCK   ***
C-----------------------
      ELSE IF (ACTPAR .EQ. 'BLOCK') THEN
            CALL SARGC (LINE, N)
         IF (N .LE. 2) THEN
            BBLOCK = .TRUE. 
         ELSE
            CALL SARGV (LINE, 3, ACTPAR)
            IF (ACTPAR .EQ. 'ON') THEN 
               BBLOCK = .TRUE.
            ELSE IF (ACTPAR .EQ. 'OFF') THEN 
               BBLOCK = .FALSE.
            ELSE
               GOTO 96
            ENDIF
         ENDIF

C***  KASDEF ITEMIZE  ***
C-----------------------
      ELSE IF (ACTPAR .EQ. 'ITEMIZE') THEN
         CALL SARGC (LINE, N)
         IF (N .LE. 2) THEN
            WRITE (*,*) 'KASDEF ITEM: NOT ENOUGH PARAMETERS'
            GOTO 96
         ENDIF
         CALL SARGV (LINE, 3, ACTPAR)
         IF (ACTPAR .EQ. 'OFF') THEN 
            IF (ITEM) YLUNOFS = YLUNOFS - SEPITEMCM - SEPITEMSZ*SIZELUN
            ITEM = .FALSE.
         ELSE
            IF (ACTPAR(:4) .EQ. 'SAME') THEN
               SIZEITEM = SIZELUN
               ELSE
               READ (ACTPAR, '(F20.0)', ERR=96) SIZEITEM
            ENDIF
            CALL SARGREST (LINE, N, 4, NSTART, NN)
            ITEMSTRING = LINE(NSTART:NN)
            CALL MYTLEN (XINDENT, SIZEITEM, ITEMSTRING, IDX(ITEMSTRING))
            XINDENT = XINDENT + 0.7 * SIZEITEM
            ITEM = .TRUE.
         ENDIF

C***  KASDEF ITEMSEP   ***
C-----------------------
      ELSE IF (ACTPAR .EQ. 'ITEMSEP') THEN
          CALL SARGV (LINE, 3, ACTPAR)
          ID = IDX(ACTPAR)
          IF (ACTPAR(ID:ID) .EQ. 'S') THEN
            READ (ACTPAR(:ID-1), '(F20.0)', ERR=96) SEPITEMSZ
            SEPITEMCM = .0
          ELSE
	    READ (ACTPAR, '(F20.0)', ERR=96) SEPITEMCM
	    SEPITEMSZ = .0
	  ENDIF

C***  KASDEF TEXT   ***
C-----------------------
      ELSE IF (ACTPAR .EQ. 'TEXT') THEN
         IF (ITEM) YLUNOFS = YLUNOFS - SEPITEMCM - SEPITEMSZ*SIZELUN
         IF (.NOT. BTEXTLINESKIP) THEN
	    DYCMTEXT   = DYCMLUN
            DYSIZETEXT = DYSIZELUN
         ENDIF
         CALL KD_TEXT (LINE, KDLINE, IKD, NKD, NKDMAX, 
     >   DYCMTEXT, DYSIZETEXT, SIZELUN, B, C, XUNITS, YUNITS,
     >   XLUNOFS, YLUNOFS, 
     >   TLUN, ITEM, SIZEITEM, PPX, YO2, KDMAXLEN, 
     >   ITEMSTRING, XINDENT, RIGHTMARG)
C***  Make baselineskip for the following line
      IF (DYSIZELUN .GT. .0) 
     >    YLUNOFS = YLUNOFS - (DYSIZELUN -1.) * SIZELUN
      IF (DYCMLUN .GT. .0) YLUNOFS = YLUNOFS - DYCMLUN + SIZELUN
C        Provide a variable with the NEXTLUN position
         WRITE (ACTPAR2, '(F20.10)') YLUNOFS
         CALL FLUSHLEFT (ACTPAR2)
         CALL PUTVAR ('NEXT_YOFS', ACTPAR2, VAR, MAXVAR, NVAR)


C***  KASDEF LATEX   ***
C-----------------------
      ELSE IF (ACTPAR .EQ. 'LATEX') THEN
         CALL KD_LATEX (LINE, KDLINE, IKD, NKD, NKDMAX, 
     >             B, C, XUNITS, YUNITS, XLUNOFS, YLUNOFS, DYCMLUN, 
     >             PPX, PPY, VAR, MAXVAR, NVAR, DYSIZELUN, SIZELUN,
     >             BBGR, IBGRCOL, BGRL, BGRR, BGRD, BGRU, BGRLINE)

C***  KASDEF SCALE_LATEX   ***
C-----------------------
      ELSE IF (ACTPAR .EQ. 'SCALE_LATEX') THEN
         CALL DECFPNUM (LINE, 3, SCALE_LATEX)

C***  KASDEF MEDSKIP  ***
C-----------------------
      ELSE IF (ACTPAR .EQ. 'MEDSKIP') THEN
         YLUNOFS = YLUNOFS -  0.5 * (DYCMLUN + DYSIZELUN * SIZELUN)
C        Provide a variable with the NEXTLUN position
         WRITE (ACTPAR2, '(F20.10)') YLUNOFS
         CALL FLUSHLEFT (ACTPAR2)
         CALL PUTVAR ('NEXT_YOFS', ACTPAR2, VAR, MAXVAR, NVAR)

C***  KASDEF YSKIP  alias VSPACE ***
C-----------------------
      ELSE IF (ACTPAR .EQ. 'YSKIP' .OR. ACTPAR .EQ. 'VSPACE') THEN
        CALL SARGV (LINE, 3, ACTPAR)
        ID = IDX(ACTPAR)
        IF (ACTPAR(ID:ID) .EQ. 'U') THEN
          READ (ACTPAR( :ID-1), '(F20.0)', ERR=96) YSKIP
          YSKIP = YSKIP * C(1)
        ELSE IF (ACTPAR(ID:ID) .EQ. 'S') THEN
          READ (ACTPAR( :ID-1), '(F20.0)', ERR=96) YSKIP
          YSKIP = 2. * YSKIP * SIZELUN
        ELSE
          CALL SARGV (LINE, 3, ACTPAR)
          READ (ACTPAR, '(F20.0)', ERR=96) YSKIP
        ENDIF
        YLUNOFS = YLUNOFS - YSKIP
C        Provide a variable with the NEXTLUN position
         WRITE (ACTPAR2, '(F20.10)') YLUNOFS
         CALL FLUSHLEFT (ACTPAR2)
         CALL PUTVAR ('NEXT_YOFS', ACTPAR2, VAR, MAXVAR, NVAR)

C***  KASDEF NEWSIZELUN  ***
C-----------------------
      ELSE IF (ACTPAR .EQ. 'NEWSIZELUN') THEN
        CALL SARGV (LINE, 3, ACTPAR)
        READ (ACTPAR, '(F20.0)', ERR=96) XNEWSLUN
c        YLUNOFS = YLUNOFS + DYSIZELUN * 0.8 * (SIZELUN - XNEWSLUN)
        IF (DYSIZELUN .GT. .0) 
     >    YLUNOFS = YLUNOFS + (DYSIZELUN -1.) * (SIZELUN-XNEWSLUN)*.5
C       Provide a variable with the NEXTLUN position
        WRITE (ACTPAR2, '(F20.10)') YLUNOFS
        CALL FLUSHLEFT (ACTPAR2)
        CALL PUTVAR ('NEXT_YOFS', ACTPAR2, VAR, MAXVAR, NVAR)
        SIZELUN = XNEWSLUN


C***  KASDEF LINESKIP   ***
C-----------------------
      ELSE IF (ACTPAR .EQ. 'LINESKIP') THEN
          CALL SARGV (LINE, 3, ACTPAR)
          ID = IDX(ACTPAR)
          IF (ACTPAR(ID:ID) .EQ. 'U') THEN
            READ (ACTPAR(:ID-1), '(F20.0)', ERR=96) DYCMLUN
ccc bugfix ?? wrh 17-Jul-2013
ccc            DYCMLUN = (DYCMLUN-B(2)) * B(1)
            DYCMLUN = DYCMLUN * C(1)
            DYSIZELUN = .0
          ELSE IF (ACTPAR(ID:ID) .EQ. 'S') THEN
            READ (ACTPAR(:ID-1), '(F20.0)', ERR=96) DYSIZELUN
            DYCMLUN = .0
          ELSE
            READ (ACTPAR, '(F20.0)', ERR=96) DYCMLUN
            DYSIZELUN = .0
          ENDIF            

C***  KASDEF TEXTLINESKIP   ***
C-----------------------
      ELSE IF (ACTPAR .EQ. 'TEXTLINESKIP') THEN
          BTEXTLINESKIP = .TRUE.
          CALL SARGV (LINE, 3, ACTPAR)
          ID = IDX(ACTPAR)
          IF (ACTPAR(ID:ID) .EQ. 'U') THEN
            READ (ACTPAR(:ID-1), '(F20.0)', ERR=96) DYCMTEXT
            DYCMTEXT = (DYCMTEXT-B(2)) * B(1)
            DYSIZETEXT = .0
          ELSE IF (ACTPAR(ID:ID) .EQ. 'S') THEN
            READ (ACTPAR(:ID-1), '(F20.0)', ERR=96) DYSIZETEXT
            DYCMTEXT = .0
          ELSE
            READ (ACTPAR, '(F20.0)', ERR=96) DYCMTEXT
            DYSIZETEXT = .0
          ENDIF            



C***  KASDEF TABLUN ***
C-----------------------
      ELSE IF (ACTPAR .EQ. 'TABLUN') THEN
          CALL SARGV (LINE, 3, ACTPAR)
          CC = ACTPAR(1:1)
          IF ( CHRINSTR (CC, 'LMR') ) THEN
             PPX = CC
	     ACTPAR = ACTPAR(2:)
	  ENDIF
          ID = IDX(ACTPAR)
          IF (ACTPAR(ID:ID) .EQ. 'U') THEN
            READ (ACTPAR(:ID-1), '(F20.0)', ERR=96) TABLUN
            TABLUN = (TABLUN-B(2)) * B(1)
          ELSE
            READ (ACTPAR, '(F20.0)', ERR=96) TABLUN
          ENDIF            
          XLUNOFS = XLUNOFS + TABLUN

C***  KASDEF LUNA   ***
C-----------------------
      ELSE IF (ACTPAR .EQ. 'LUNA') THEN
          CALL KD_LUNA (LINE, SIZELUN, B, C, XUNITS, YUNITS, 
     >    TLUN, BBGR, IBGRCOL, LASTCOLOR, BGRL, BGRR, BGRD, BGRU,
     >    BGRLINE)

C***  KASDEF DATE   ***
C-----------------------
      ELSE IF (ACTPAR .EQ. 'DATE') THEN
         CALL KD_DATE (LINE, B, C, XUNITS, YUNITS, SAMEOFSX, SAMEOFSY) 

C***  KASDEF FILE   ***
C-----------------------
      ELSE IF (ACTPAR .EQ. 'FILE') THEN
         CALL KD_FILE (LINE, B, C, XUNITS, YUNITS, SAMEOFSX, SAMEOFSY,
     >                 FNAME) 
 
C***  KASDEF ARR (DRAWING OF ARROWS) ******************   
C-----------------------
      ELSE IF (ACTPAR .EQ. 'ARR') THEN
         CALL KD_ARR (B, C, LINE, XUNITS, YUNITS, SAMEOFSX, SAMEOFSY)

C***  KASDEF ARC (PLOTTING PART OF A CIRCLE)
C--------------------------------------------
      ELSE IF (ACTPAR .EQ. 'ARC') THEN
         CALL KD_ARC (B, C, LINE, XUNITS, YUNITS, SAMEOFSX, SAMEOFSY)

C***  KASDEF SYM (PLOTTING OF SINGLE SYMBOL) ***********
C-----------------------
      ELSE IF (ACTPAR .EQ. 'SYM') THEN
         CALL KD_SYM (LINE, XUNITS, YUNITS, B, C, VAR, MAXVAR, NVAR, 
     >                ICOLOR, SAMEOFSX, SAMEOFSY)

C***  KASDEF ELLI (PLOTTING OF AN ELLIPSE) ***********
C-----------------------
      ELSE IF (ACTPAR .EQ. 'ELLI') THEN
         CALL KD_ELLI (B, C, LINE, IDEV, VAR, MAXVAR, NVAR, 
     >       XUNITS, YUNITS, XCMA, YCMA, NDATMAX, SAMEOFSX, SAMEOFSY)

C***  KASDEF RECT (PLOTTING OF AN RECTANGLE) ***********
C-----------------------
      ELSE IF (ACTPAR .EQ. 'RECT') THEN
         CALL KD_RECT (B, C, LINE)

C***  KASDEF RECTLUN (PLOTTING OF AN RECTANGLE, PARAMETERS EXCHANGE WITH LUN) *
C-----------------------
      ELSE IF (ACTPAR .EQ. 'RECTLUN') THEN
         CALL KD_RECTLUN (B, C, LINE, XUNITS, YUNITS, PPX, PPY, 
     >                    XLUNOFS, YLUNOFS)

C***  KASDEF LIN (DRAWING A LINE IN CM)       
C-----------------------
      ELSE IF (ACTPAR .EQ. 'LIN') THEN
         CALL SARGV (LINE,3,ACTPAR)
         IF (ACTPAR(:4) .NE. 'SAME') 
     >         READ (ACTPAR, '(F20.0)', ERR=96) X1LINE
         CALL SARGV (LINE,4,ACTPAR)
         IF (ACTPAR(:4) .NE. 'SAME') 
     >    READ (ACTPAR, '(F20.0)', ERR=96) Y1LINE
         CALL SARGV (LINE,5,ACTPAR)
         IF (ACTPAR(:4) .NE. 'SAME') 
     >    READ (ACTPAR, '(F20.0)', ERR=96) X2LINE
         CALL SARGV (LINE,6,ACTPAR)
         IF (ACTPAR(:4) .NE. 'SAME') 
     >    READ (ACTPAR, '(F20.0)', ERR=96) Y2LINE
         CALL GPLOT (X1LINE, Y1LINE, 3)
         CALL GPLOT (X2LINE, Y2LINE, 2)

C***  KASDEF LINUN (DRAWING A LINE IN UNITS, PLUS OFFSET IN CM) 
C-----------------------
      ELSE IF (ACTPAR .EQ. 'LINUN') THEN
         CALL KD_LINUN (LINE, VAR, MAXVAR, NVAR, B, C,
     >                  SAMEOFSX, SAMEOFSY) 

C***  KASDEF LINREL (DRAWING A LINE: STARTING POINT IN UNITS, LENGTHS IN CM) 
C-----------------------
      ELSE IF (ACTPAR .EQ. 'LINREL') THEN
         CALL KD_LINREL (B, C, LINE, XUNITS, YUNITS,
     >                  SAMEOFSX, SAMEOFSY, VAR, MAXVAR, NVAR) 

C***  KASDEF LINUNLAB (DRAWING A LINE, INTERRUPTED BY A LABEL) 
C-------------------------------------------------------------
      ELSE IF (ACTPAR .EQ. 'LINUNLAB') THEN
         CALL KD_LINUNLAB (LINE, B, C, SAMEOFSX, SAMEOFSY, BBGR, 
     >                     IBGRCOL, BGRL, BGRR, BGRD, BGRU,
     >                     LASTCOLOR, BGRLINE)
          
C***  KASDEF TRA (WRITE LABEL IN TRANSVERSAL ORIENTATION) ****
C-----------------------
      ELSE IF (ACTPAR .EQ. 'TRA') THEN
         CALL SARGV (LINE,3,ACTPAR)
         READ (ACTPAR,'(F20.0)', ERR=96) XTRA
         CALL SARGV (LINE,4,ACTPAR)
         READ (ACTPAR,'(F20.0)', ERR=96) YTRA
         CALL SARGV (LINE,5,ACTPAR)
         READ (ACTPAR,'(F20.0)', ERR=96) STRA
         CALL SARGREST (LINE,N,6,NSTART,NN)
         TTRA = LINE(NSTART:)
         XPTRA = (XTRA - B(2)) * B(1)
         CALL MYSYMBL (XPTRA, YTRA, STRA, TTRA, 90.)
             
C***  KASDEF LAM (DRAW VERTICAL LINE, POSITION IN X IN UNITS)  ******
C-----------------------
      ELSE IF (ACTPAR .EQ. 'LAM') THEN
         CALL SARGV(LINE,3,ACTPAR)
         READ (ACTPAR,'(F20.0)', ERR=96) XLAM
         CALL SARGV(LINE,4,ACTPAR)
         READ (ACTPAR,'(F20.0)', ERR=96) YLAM
         CALL SARGV(LINE,5,ACTPAR)
         READ (ACTPAR,'(F20.0)', ERR=96) DLAM
         XPLAM = (XLAM - B(2)) * B(1)
         CALL GPLOT(XPLAM, YLAM, 3)
         CALL GPLOT(XPLAM, YLAM + DLAM, 2)
             
C***  KASDEF CON (DRAW HORIZONTAL LINE, POSITION IN X IN UNITS)  ******
C-----------------------
      ELSE IF (ACTPAR .EQ. 'CON') THEN
         CALL SARGV (LINE,3,ACTPAR)
         READ (ACTPAR,'(F20.0)', ERR=96) X1CON
         CALL SARGV (LINE,4,ACTPAR)
         READ (ACTPAR,'(F20.0)', ERR=96) X2CON
         CALL SARGV (LINE,5,ACTPAR)
         READ (ACTPAR,'(F20.0)', ERR=96) YCON
         XP1CON = (X1CON - B(2)) * B(1)
         XP2CON = (X2CON - B(2)) * B(1)
         CALL GPLOT (XP1CON, YCON, 3)
         CALL GPLOT (XP2CON, YCON, 2)

C-----------------------
      ELSE IF (ACTPAR(:2) .EQ. 'ID') THEN
         CALL KD_IDENT (ACTPAR, LINE, B, C, 
     >   SIZEID, SIZEFAC, SIZEID2, IID, YID, XOFFID, XFACID, IDNORM, 
     >   XLENGID, IDMCOMB, XIDMLEN1, XIDMLEN2, XIDMLEN3, 
     >   IDDIR, IDCON, BIDLOG, ID_INBOX )

C***  KASDEF BARPAR
C-----------------------
      ELSE IF (ACTPAR .EQ. 'BARPAR') THEN
         CALL SARGV (LINE,3,ACTPAR)
         READ (ACTPAR,'(BN, F20.0)', ERR=96) BARSP
         CALL SARGV (LINE,4,ACTPAR)
         READ (ACTPAR,'(BN, F20.0)', ERR=96) BAREDGE

C***  KASDEF BARLEN
C-----------------------
      ELSE IF (ACTPAR .EQ. 'BARLEN') THEN
         CALL SARGV (LINE,3,ACTPAR)
         READ (ACTPAR,'(BN, F20.0)', ERR=96) BARLN
         CALL SARGV (LINE,4,ACTPAR)
         READ (ACTPAR,'(BN, F20.0)', ERR=96) BARLS
         CALL SARGV (LINE,5,ACTPAR)
         READ (ACTPAR,'(BN, F20.0)', ERR=96) BARLO
         CALL SARGV (LINE,6,ACTPAR)
         READ (ACTPAR,'(BN, F20.0)', ERR=96) BARLW

C***  KASDEF BAR
C-----------------------
      ELSE IF (ACTPAR .EQ. 'BAR') THEN
         CALL SARGV (LINE,3,ACTPAR)
         IF (ACTPAR(:4) .NE. 'SAME') 
     >        CALL READPAR (ACTPAR, B, C, XUNITS, VAR, MAXVAR, NVAR)
         CALL SARGV (LINE,4,ACTPAR)
         IF (ACTPAR(:4) .NE. 'SAME') 
     >        CALL READPAR (ACTPAR, B, C, YUNITS, VAR, MAXVAR, NVAR)
         CALL SARGV (LINE,5,ACTPAR)
         READ (ACTPAR,'(BN, F20.0)', ERR=96) BARXOFF
         CALL SARGV (LINE,6,ACTPAR)
         READ (ACTPAR,'(BN, F20.0)', ERR=96) BARYOFF
C***     CONVERT INTO CM
         XCM = (XUNITS-B(2)) * B(1) + BARXOFF
         YCM = (YUNITS-C(2)) * C(1) + BARYOFF

         XCMLN = BARLN * C(1)
         XCMLS = BARLS * C(1)
         XCMLO = BARLO * B(1)
         XCMLW = BARLW * B(1)

         IF (XCMLN .GT. BARSP) THEN
           CALL GCPLOT (XCM, YCM+BARSP, 3)
           CALL GCPLOT (XCM, YCM+XCMLN, 2)
           CALL GCPLOT (XCM-0.5*BAREDGE, YCM+XCMLN, 3)
           CALL GCPLOT (XCM+0.5*BAREDGE, YCM+XCMLN, 2)
         ENDIF

         IF (XCMLS .GT. BARSP) THEN
           CALL GCPLOT (XCM, YCM-BARSP, 3)
           CALL GCPLOT (XCM, YCM-XCMLS, 2)
           CALL GCPLOT (XCM-0.5*BAREDGE, YCM-XCMLS, 3)
           CALL GCPLOT (XCM+0.5*BAREDGE, YCM-XCMLS, 2)
         ENDIF

         IF (XCMLW .GT. BARSP) THEN
           CALL GCPLOT (XCM+BARSP, YCM, 3)
           CALL GCPLOT (XCM+XCMLW, YCM, 2)
           CALL GCPLOT (XCM+XCMLW, YCM-0.5*BAREDGE, 3)
           CALL GCPLOT (XCM+XCMLW, YCM+0.5*BAREDGE, 2)
         ENDIF

         IF (XCMLO .GT. BARSP) THEN
           CALL GCPLOT (XCM-BARSP, YCM, 3)
           CALL GCPLOT (XCM-XCMLO, YCM, 2)
           CALL GCPLOT (XCM-XCMLO, YCM-0.5*BAREDGE, 3)
           CALL GCPLOT (XCM-XCMLO, YCM+0.5*BAREDGE, 2)
         ENDIF

C***  KASDEF COLOR
C***  ------------
      ELSE IF (ACTPAR .EQ. 'COLOR') THEN
         CALL COLOR ('KASDEF', LINE, ICOLOR, IDEV)

C***  KASDEF DEFINECOLOR
C***  ------------------
      ELSE IF (ACTPAR .EQ. 'DEFINECOLOR') THEN
         CALL COLOR ('DEFINE', LINE, IDUMMY, IDEV)

C***  KASDEF RESETCOLOR
C***  -----------------
      ELSE IF (ACTPAR .EQ. 'RESETCOLOR') THEN
         CALL COLOR ('INIT', LINE, IDUMMY, IDEV)

C***  KASDEF LIMITCOLOR
C***  -----------------
      ELSE IF (ACTPAR .EQ. 'LIMITCOLOR') THEN
         CALL SARGC (LINE, NPAR)
         IF (NPAR .LT. 5) THEN
	    WRITE (*,'(/A)') '*** ERROR: NOT ENOUGH PARAMETERS GIVEN!' 
            GOTO 96
	 ENDIF
         CALL SARGV (LINE, 3, ACTPAR2)
         READ (ACTPAR2,'(I10)') LIMCOLR
         CALL SARGV (LINE, 4, ACTPAR2)
         READ (ACTPAR2,'(I10)') LIMCOLG
         CALL SARGV (LINE, 5, ACTPAR2)
         READ (ACTPAR2,'(I10)') LIMCOLB
         IF (LIMCOLR .LE. 0 .OR. LIMCOLG .LE. 0 .OR. 
     >       LIMCOLB .LE. 0) THEN
	    WRITE (*,'(/A)') '*** ERROR: NUMBER OF COLORS INVALID!' 
            GOTO 96
	 ENDIF
         LIMCOL_ON = 1

C***  KASDEF NCOLORSTEP
C***  -----------------
      ELSE IF (ACTPAR .EQ. 'NCOLORSTEP') THEN
         CALL SARGV (LINE, 3, ACTPAR2)
         READ (ACTPAR2,'(I10)') NCOLSTEP
         IF (NCOLSTEP .LE. 0 ) THEN
	    WRITE (*,'(/A)') '*** ERROR: NCOLORSTEP INVALID!' 
            GOTO 96
	 ENDIF

C***  KASDEF FONT
C***  -----------
      ELSE IF (ACTPAR .EQ. 'FONT') THEN
         CALL SARGV (LINE, 3, ACTPAR)
         IF (ACTPAR( :6) .EQ. 'WRPLOT') THEN
            FONT = 'WRPLOT'
         ELSE IF (ACTPAR( :5) .EQ. 'TIMES') THEN 
            FONT = 'TIMES'
         ELSE IF (ACTPAR( :6) .EQ. 'HELVET') THEN 
            FONT = 'HELVET'
         ELSE IF (ACTPAR( :6) .EQ. 'COURIE') THEN 
            FONT = 'COURIE'
         ELSE IF (ACTPAR( :4) .EQ. 'ZAPF') THEN 
            FONT = 'ZAPF  '
         ELSE
            GOTO 96
         ENDIF

C***  KASDEF TABON or TAB (if TAB was interrupted by normal KASDEF statement)
C***  -----------
      ELSE IF (ACTPAR .EQ. 'TABON' .OR. 
     >         ACTPAR .EQ. 'TAB'   .OR. 
     >         ACTPAR .EQ. 'TABOFF'     ) THEN
         CALL KD_TAB (KDLINE, NKD, NKDMAX, IKD, TABLEFTMARGIN, 
     >     TABRIGHTMARGIN, 
     >     LINE, XLUNOFS, YLUNOFS, DYCMLUN, DYSIZELUN, PPX, PPY, 
     >     SIZELUN, BTAB, B, C, XUNITS, YUNITS, VAR, MAXVAR, 
     >     NVAR, TLUN, IBGRCOL, BBGR, BGRL, BGRR, BGRD, BGRU, XINDENT,
     >     BGRLINE)
C         Provide a variable with the NEXTLUN position
          WRITE (ACTPAR2, '(F20.10)') YLUNOFS
          CALL FLUSHLEFT (ACTPAR2)
          CALL PUTVAR ('NEXT_YOFS', ACTPAR2, VAR, MAXVAR, NVAR)

C***  KASDEF OFF
C***  --------------------------
      ELSE IF (ACTPAR .EQ. 'OFF') THEN
         GOTO 5

C***  KASDEF EPSF
C***  --------------------------
      ELSE IF (ACTPAR .EQ. 'EPSF') THEN
        CALL EPSF (LINE, B, C, XUNITS, YUNITS, XLUNOFS, YLUNOFS,  
     >       DYCMLUN, PPX, PPY, VAR, MAXVAR, NVAR, DYSIZELUN, SIZELUN,
     >        BBGR, IBGRCOL, BGRL, BGRR, BGRD, BGRU, BBXWIDTH, 'PRINT',
     >       BGRLINE)

C***  KASDEF INSTRUCTION
C-----------------------
      ELSE IF (ACTPAR .EQ. 'INSTRUCTION') THEN
         CALL SARGV(LINE,3,ACTPAR)
         IF (ACTPAR .EQ. 'EXPORT') THEN
           BINSEX = .TRUE.
         ELSE IF (ACTPAR .EQ. 'NO-EXPORT') THEN
           BINSEX = .FALSE.
         ELSE
           GOTO 96
         ENDIF

C***  KASDEF GLATEX
C------------------
       ELSE IF (ACTPAR .EQ. 'GLATEX') THEN
            CALL SARGC (LINE, N)
         IF (N .LE. 2) THEN
            GLATEX = .TRUE. 
         ELSE
            CALL SARGV (LINE, 3, ACTPAR)
            IF (ACTPAR .EQ. 'ON') THEN 
               GLATEX = .TRUE.
            ELSE IF (ACTPAR .EQ. 'OFF') THEN 
               GLATEX = .FALSE.
            ELSE
               GOTO 96
            ENDIF
         ENDIF

C***  KASDEF SETTINGS already decoded in KDSET -> no operation
      ELSE IF (ACTPAR .EQ. 'executed_by_KDSET') THEN

C***  Illegal KASDEF commands removed by KDSET -> no operation
      ELSE IF (ACTPAR .EQ. 'removed_by_KDSET') THEN

      ELSE

C***  CHECK FOR INSTRUCTIONS
C***  ----------------------
C***    Instructions are only executed by KDPLOT if they were not
C***     exported, i.e. executed before by KDSET
        IF (.NOT. BINSEX .OR. BCOMPAT) THEN
          CALL EXINST (KDLINE, NKDMAX, NKD, IKD, 'KASDEF', IERR, 
     >                 VAR, MAXVAR, NVAR)
        ENDIF

        IF (IERR .EQ. 1) THEN
	  WRITE(*,*)
          WRITE(*,*) 'NON-FATAL ERROR: UNRECOGNIZED KASDEF OPTION -'
          WRITE(*,*) 'THE ERROR OCCURED IN THE FOLLOWING LINE:'
          WRITE(*,*) LINE(:IDX(LINE))
cc          WRITE(*,*) 
cc     >        KDLINE(IKDNOCONTLINES)(:IDX(KDLINE(IKDNOCONTLINES)))
        ENDIF

      ENDIF


C***  Now increment counter, jumping over continuation lines       
      IKD = IKD + 1 + NCONTLINES
      IF (IKD .LE. NKD) GOTO 4
C***  END OF INTERPRETATION OF KASDEF OPTIONS  ************************

    5 CONTINUE
      RETURN

C**********************************************************************
C***  EROR BRANCH
C**********************************************************************

95    WRITE (*,'(/A)') '*** ERROR: CONTINUATION LINE TRUNCATED'
      WRITE (*,'(A)') '*** THE ERROR OCCURED IN THE FOLLOWING LINES:'
      WRITE (*,'(A)') LINE (:IDX(LINE ))
      WRITE (*,'(A)') LINE1(:IDX(LINE1))
      STOP 'ERROR IN KDPLOT'

96    WRITE(*,'(A)') 'ERROR OCCURED IN KDPLOT'
      WRITE(*,'(A)') 'THE ERROR OCCURED IN THE FOLLOWING LINE:'
      WRITE(*,'(A)') LINE(:IDX(LINE))
      STOP 'ERROR IN KDPLOT'

99    WRITE(*,'(A)') 'KASDEF ENDTEXT MISSING'
      STOP 'ERROR IN KDPLOT'

      END
kdset.f/        1553528659  5006  320   100644  15044     `
      SUBROUTINE KDSET  (IPENDEF, ICOLDEF, PLOTSKAL, OFSX, OFSY, INBOX,
     >             KDLINE, NKD, NKDMAX, CPRGHT, NOBOX, SIZELET, LATEBOX,
     >             VAR, MAXVAR, NVAR, BINSEX, BINTER, 
     >            NSETMAX, NSETMAXMAX, NSETMAXDEFAULT, 
     >            NDATMAX, NDATMAXMAX, NDATMAXDEFAULT, NDATTOT, SIZETIC,
     >            BPREDEF_VAR, FNAME)

C***********************************************************************
C***  WRPLOT PROGRAM:
C***  INTERPRETATION OF KASDEF SETTINGS, 
C***    AND EXECUTION OF "EXPORTED" INSTRUCTIONS
C***  THIS SUBROUTINE IS CALLED FROM SUBROUTINE READDATA.
C***********************************************************************

      PARAMETER (KDMAXLEN = 400)
      CHARACTER*(*) VAR(MAXVAR,2), FNAME
      CHARACTER CDATE*9, CTIME*8
      CHARACTER LINE*(KDMAXLEN), LINE1*132
      CHARACTER KDLINE(NKDMAX)*132, INCKEY*60, EXNAM*255
      CHARACTER ACTPAR*20, ACTPAR2*20, BACKSLASH*1
      LOGICAL INBOX, CPRGHT, NOBOX, LATEBOX, BINSEX, BINTER, BINCKEY
      LOGICAL BALL, BPREDEF_VAR, BCOMPAT, BTICKSIZE

C***  Compatibility switch if non-INSTRUCTIONS found in EXPORT block
C***  The switch is applied in KDPLOT
      COMMON / COMCOMPAT / BCOMPAT

      BACKSLASH = CHAR(92)

C***  DEFAULT VALUES:
      IPENDEF = 1
      ICOLDEF = 1
      PLOTSKAL= 1.0
      OFSX=4.0
      OFSY=3.0
      INBOX = .FALSE.
      NOBOX = .FALSE.
      SIZELET = 0.4
      SIZETIC = SIZELET
      LATEBOX = .FALSE. 
      BINTER = .FALSE.
      NSETMAX = 0
      NDATMAX = 0
      BINSEX = .FALSE.
      BPREDEF_VAR = .FALSE.
      BCOMPAT = .FALSE.
      BTICKSIZE = .FALSE.

C***  Loop for each KASDEF Option **************************************
      IKD = 1

    4 CONTINUE

      LINE = KDLINE(IKD)

C***  Append possible continuation lines KASDEF >
      NCONTLINES = 0
    1 CALL SARGREST (KDLINE(IKD+1+NCONTLINES), NPAR, 2, IFIRST, ILAST)
      IF (NPAR .GT. 1 .AND. 
     >   KDLINE(IKD+1+NCONTLINES)(IFIRST:IFIRST) .EQ. '>') THEN
         NCONTLINES = NCONTLINES + 1
         LINE1 = KDLINE(IKD+NCONTLINES)(IFIRST+1:ILAST)
         LAST = IDX(LINE)
         IF (LAST+IDX(LINE1)-1 .GT. KDMAXLEN) GOTO 95
         LINE(LAST+1:) = LINE1
         GOTO 1
      ENDIF

C***  Extract second parameter
      CALL SARGV(LINE,2,ACTPAR)

C***  EXPAND ALL VARIABLES (attention, only for setting commands!)
      IF (
     >         ACTPAR .EQ. 'SKL'  
     >    .OR. ACTPAR .EQ. 'OFS'  
     >    .OR. ACTPAR .EQ. 'PENDEF'  
     >    .OR. ACTPAR .EQ. 'DEFAULTCOLOR'  
     >    .OR. ACTPAR .EQ. 'LETTERSIZE'  
     >    .OR. ACTPAR .EQ. 'TICKSIZE'  
     >    .OR. ACTPAR .EQ. 'INCLUDE'  
     >     ) CALL EXPANDVAR (LINE, VAR, MAXVAR, NVAR)

C***  KASDEF SKL  ***
C-----------------------
      IF (ACTPAR .EQ. 'SKL') THEN
         CALL SARGVR (LINE, 3, ACTPAR)
         READ (ACTPAR, '(F20.0)', ERR=96) PLOTSKAL
         KDLINE(IKD) = 'KASDEF executed_by_KDSET'

C***  KASDEF OFS (OFFSET SHIFT OF TOTAL PLOT) ***************************
C-----------------------
      ELSE IF (ACTPAR .EQ. 'OFS') THEN
         CALL SARGVR (LINE, 3, ACTPAR)
         READ (ACTPAR, '(F20.0)') OFSX
         CALL SARGVR (LINE, 4, ACTPAR)
         READ (ACTPAR, '(F20.0)') OFSY
         KDLINE(IKD) = 'KASDEF executed_by_KDSET'

C***  KASDEF PENDEF  (DEFAULT PEN FOR DATASETS)  ***
C-----------------------
      ELSE IF (ACTPAR .EQ. 'PENDEF') THEN
         CALL SARGVR (LINE, 3, ACTPAR)
         READ (ACTPAR,'(10X,I10)', ERR=96) IPENDEF
         KDLINE(IKD) = 'KASDEF executed_by_KDSET'

C***  KASDEF DEFAULTCOLOR (DEFAULT COLOR FOR DATASETS)  ***
C-----------------------
      ELSE IF (ACTPAR .EQ. 'DEFAULTCOLOR') THEN
         CALL SARGVR (LINE, 3, ACTPAR)
         READ (ACTPAR,'(10X,I10)', ERR=96) ICOLDEF
         IF (ICOLDEF .LT. 1 .OR. ICOLDEF .GT. 9) THEN
           ICOLDEF = 1
           PRINT *, 
     >      '*** NON-FATAL ERROR: DEFAULT COLOR OUTSIDE (1...9) IGNORED'
           ENDIF
         KDLINE(IKD) = 'KASDEF executed_by_KDSET'

C***  KASDEF INBOX  ***
C-----------------------
      ELSE IF (ACTPAR .EQ. 'INBOX') THEN
         INBOX = .TRUE.
         KDLINE(IKD) = 'KASDEF executed_by_KDSET'

C***  KASDEF NOBOX  ***
C-----------------------
      ELSE IF (ACTPAR .EQ. 'NOBOX') THEN
         NOBOX = .TRUE.
         KDLINE(IKD) = 'KASDEF executed_by_KDSET'

C***  KASDEF LATEBOX  ***
C------------------------
      ELSE IF (ACTPAR(:7) .EQ. 'LATEBOX') THEN
         LATEBOX = .TRUE.
         KDLINE(IKD) = 'KASDEF executed_by_KDSET'

C***  KASDEF COPYRIGHT ***
C-------------------------
      ELSE IF (ACTPAR .EQ. 'COPYRIGHT') THEN
         CPRGHT = .TRUE.
         KDLINE(IKD) = 'KASDEF executed_by_KDSET'

C***  KASDEF INTERACTIVE ***
C-------------------------
      ELSE IF (ACTPAR .EQ. 'INTERACTIVE') THEN
         BINTER = .TRUE.
         KDLINE(IKD) = 'KASDEF executed_by_KDSET'

C***  KASDEF COPYRIGHT ***
C-------------------------
      ELSE IF (ACTPAR .EQ. 'NOCOPYRIGHT') THEN
         CPRGHT = .FALSE.
         KDLINE(IKD) = 'KASDEF executed_by_KDSET'

C***  KASDEF LETTERSIZE 
C-----------------------
      ELSE IF (ACTPAR .EQ. 'LETTERSIZE') THEN
         CALL SARGV(LINE,3,ACTPAR)
         READ (ACTPAR,'(F10.0)') SIZELET
C***     Do not overwrite SIZETICK if set explicitely
         IF (.NOT. BTICKSIZE) SIZETIC = SIZELET
         KDLINE(IKD) = 'KASDEF executed_by_KDSET'

C***  KASDEF TICKSIZE 
C-----------------------
      ELSE IF (ACTPAR .EQ. 'TICKSIZE') THEN
         CALL SARGV(LINE,3,ACTPAR)
         READ (ACTPAR,'(F10.0)') SIZETIC
         BTICKSIZE = .TRUE.
         KDLINE(IKD) = 'KASDEF executed_by_KDSET'

C***  KASDEF INSTRUCTION
C-----------------------
      ELSE IF (ACTPAR .EQ. 'INSTRUCTION') THEN
         CALL SARGV(LINE,3,ACTPAR)
         IF (ACTPAR .EQ. 'EXPORT') THEN
          BINSEX = .TRUE.
         ELSE IF (ACTPAR .EQ. 'NO-EXPORT') THEN
          BINSEX = .FALSE.
         ELSE
          GOTO 96
         ENDIF

C***  KASDEF SET_NDATMAX
C-----------------------
      ELSE IF (ACTPAR .EQ. 'SET_NDATMAX') THEN
         CALL SARGV (LINE, 3, ACTPAR)
         READ (ACTPAR, '(I10)', ERR=96) NDATMAX
         IF (NDATMAX .LE. 0) THEN
            WRITE (*, '(/,A)') 'FATAL ERROR: INVALID CHOICE OF NDATMAX' 
            GOTO 96
	 ENDIF
         IF (NDATMAX .GT. NDATMAXMAX) THEN
            WRITE (*, '(/,A)') 'FATAL ERROR: INVALID CHOICE OF NDATMAX' 
            WRITE (*, '(A,I8)') 'MAXIMUM POSSIBLE VALUE IS:', NDATMAXMAX 
            GOTO 96
	 ENDIF
         KDLINE(IKD) = 'KASDEF executed_by_KDSET'
	
C***  KASDEF SET_NSETMAX
C-----------------------
      ELSE IF (ACTPAR .EQ. 'SET_NSETMAX') THEN
         CALL SARGV (LINE, 3, ACTPAR)
         READ (ACTPAR, '(I10)', ERR=96) NSETMAX
         IF (NSETMAX .LE. 0) THEN
            WRITE (*, '(/,A)') 'FATAL ERROR: INVALID CHOICE OF NSETMAX' 
            GOTO 96
	 ENDIF
         IF (NSETMAX .GT. NSETMAXMAX) THEN
            WRITE (*, '(/,A)') 'FATAL ERROR: INVALID CHOICE OF NSETMAX' 
            WRITE (*, '(A,I8)') 'MAXIMUM POSSIBLE VALUE IS:', NSETMAXMAX 
            GOTO 96
	 ENDIF
         KDLINE(IKD) = 'KASDEF executed_by_KDSET'

C******************************
C***  Reading from include-file
C******************************

      ELSE IF (ACTPAR .EQ. 'INCLUDE') THEN
C***     The line with the INCLUDE statement is now removed
         DO LKD=IKD, NKD-1
            KDLINE(LKD) = KDLINE(LKD+1)
         ENDDO
         NKD=NKD-1
         IKD=IKD-1
C***     First Line of Include-File will follow the INCLUDE Statement
         ISTART = IKD + 1
         BINCKEY = .FALSE.
         CALL SARGV (LINE, 3, EXNAM)
         CALL MY_OPEN (9, EXNAM, IERR)
	 IF (IERR .NE. 0) GOTO 97
         CALL SARGC (LINE, NPAR)
         IF (NPAR .GT. 3) THEN 
             CALL SARGV (LINE, 5, INCKEY)
             BINCKEY = .TRUE.
  405        READ (9, '(A)', END=401) LINE
             IF (LINE(1:IDX(INCKEY)) .NE. INCKEY) GOTO 405
         ENDIF

         BALL = .FALSE. 
  410    READ (9, '(A)', END=400) LINE
C***  Omit leading blanks  
         IF (IDX(LINE) .EQ. 0) GOTO 410
  402    CONTINUE
         IF (LINE(1:1) .EQ. ' ') THEN
           LINE = LINE(2: ) // ' '
           GOTO 402
         ENDIF

C***     Copy all KASDEF lines, and all lines in TEXT and LATEX
         IF (BALL) THEN
C***        Check for \ENDTEXT or \ENDLATEX or KASDEF ENDTEXT or ...
            IF (LINE(1:1) .EQ. BACKSLASH) THEN
               ACTPAR = 'KASDEF'
               CALL SARGV (LINE(2:), 1, ACTPAR2)
            ELSE 
	       CALL SARGV (LINE, 1, ACTPAR)
	       IF (ACTPAR .EQ. 'KASDEF') THEN
	          CALL SARGV (LINE, 2, ACTPAR2)
               ELSE
                  ACTPAR2 = ' '
               ENDIF
            ENDIF
	    IF (LINE(1:1) .EQ. BACKSLASH .OR. ACTPAR .EQ. 'KASDEF') THEN
               IF (ACTPAR2 .EQ. 'ENDTEXT') THEN 
	          LINE = 'KASDEF ENDTEXT'
                  BALL=.FALSE.
                ELSE IF (ACTPAR2 .EQ. 'ENDLATEX') THEN 
	          LINE = 'KASDEF ENDLATEX'
                  BALL=.FALSE.
               ENDIF
	   ENDIF
         ELSE
            IF (BINCKEY .AND. LINE(1:3) .EQ. 'END') GOTO 400
C***        Expand \ to KASDEF	
            IF (LINE(1:1) .EQ. BACKSLASH) LINE = 'KASDEF ' // LINE(2:)
            CALL SARGV (LINE, 1, ACTPAR)
            IF (ACTPAR .EQ. 'KASDEF') THEN 
               CALL SARGV (LINE, 2, ACTPAR2)
	       IF (ACTPAR2 .EQ. 'TEXT' .OR. ACTPAR2 .EQ. 'LATEX') THEN
	          BALL=.TRUE.
               ENDIF
            ENDIF
	 ENDIF
         IF (ACTPAR .NE. 'KASDEF' .AND. .NOT. BALL) GOTO 410

C***     LINE now contains the current line which was read from Include-File 
C***     Shift the following KD-lines to create space for insertion
         NKD = NKD + 1
         IF (NKD .GT. NKDMAX) GOTO 98    
         DO LKD=NKD, ISTART+1, -1
           KDLINE(LKD) = KDLINE(LKD-1)
           ENDDO
         KDLINE(ISTART) = LINE
         ISTART = ISTART + 1
         GOTO 410

C***     INCKEY not found: error stop
  401    WRITE (*,*) '!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!'
         WRITE (*,*) '>>>>>>>> ERROR: INCLUDE KEY NOT FOUND'
         WRITE (*,*) '>>>>>>>> KEYWORD : ', INCKEY(:IDX(INCKEY))
         WRITE (*,*) '>>>>>>>> FILENAME: ', EXNAM(:IDX(EXNAM))
         STOP        '>>>>>>>> ERROR IN KDPLOT'

C***     'END' or E-O-F reached
  400    CONTINUE
         CLOSE (9)

C***  KASDEF PREDEFINE-VARIABLES
C***  --------------------------
      ELSE IF (ACTPAR .EQ. 'PREDEFINE-VARIABLES') THEN
         BPREDEF_VAR = .TRUE.
         ACTPAR = 'FILENAME'
         CALL PUTVAR(ACTPAR, FNAME, VAR, MAXVAR, NVAR)

         ACTPAR = 'DATE'
         CALL DATE(CDATE)
         CALL PUTVAR(ACTPAR, CDATE, VAR, MAXVAR, NVAR)

         ACTPAR = 'TIME'
         CALL TIME(CTIME)
         CALL PUTVAR(ACTPAR, CTIME, VAR, MAXVAR, NVAR)
C***     The other variables will be written later 
C***     by Subr. PREVAR called from WRPLOT
         KDLINE(IKD) = 'KASDEF executed_by_KDSET'

      ELSE

         IF (BINSEX) THEN
          CALL EXINST (KDLINE, NKDMAX, NKD, IKD, 'KDSET', IERR, 
     >                 VAR, MAXVAR, NVAR)

C***      Test if the statement was neither a setting nor an instruction 
          IF (IERR .EQ. 1) THEN
C***       Strict version! Remove plotting actions! 
           IF (.false.) THEN
C***        Check if it was a continuation line 
            NCONTLINES = 0
   20       IF (IKD-NCONTLINES .GT. 1) THEN 
              CALL SARGV (KDLINE(IKD-NCONTLINES),2,ACTPAR)
	      IF (ACTPAR .EQ. '>') THEN
	        NCONTLINES = NCONTLINES + 1
                GOTO 20
              ENDIF
            ENDIF

            DO II = IKD-NCONTLINES, IKD
              KDLINE(II) = 'KASDEF removed_by_KDSET'
            ENDDO
	    WRITE(*,*)
            WRITE(*,*) 'NON-FATAL ERROR: UNRECOGNIZED INSTRUCTION'
     >                 // ' INSIDE EXPORT BLOCK -'
     >                 // ' POSSIBLY A PLOTTING ACTION -'
            WRITE(*,*) 'PLOTTING ACTIONS ARE NOT POSSIBLE HERE' 
     >                 // ' --> THE COMMAND IS REMOVED!' 
            IF(NCONTLINES .GT. 0) WRITE (*,'(3X,A, I2,A)') 
     >          '(INCLUDING', NCONTLINES, ' CONTINUATION LINES)'
            WRITE(*,*) 'THE ERROR OCCURED IN THE FOLLOWING LINE:'
            WRITE(*,*) LINE(:IDX(LINE))

C***   Tolerant version: do not remove lines, but execute all 
C***    INSTRUCTION EXPORT blocks a second time when plotting 
           ELSE
	    IF (.NOT. BCOMPAT) THEN
             WRITE(*,*) 'NON-FATAL ERROR: UNRECOGNIZED INSTRUCTION'
     >                  // ' INSIDE EXPORT BLOCK -'
             WRITE(*,*) 'POSSIBLY THIS IS A PLOTTING ACTION?'
             WRITE(*,*) 'PLOTTING ACTIONS ARE NOT POSSIBLE HERE!' 
             WRITE(*,*) ' --> WRplot switches into COMPATIBILITY mode' 
             WRITE(*,*) 'i.e. the EXPORT blocks will be executed a'
     >                 // ' second time when the plot is issued'
             WRITE(*,*) 'THIS MAY CAUSE SPURIOUS EFFECTS!'
             WRITE(*,*) 'THE ERROR OCCURED IN THE FOLLOWING LINE(S):'
             BCOMPAT = .TRUE.
            ENDIF
            WRITE(*,*) LINE(:IDX(LINE))

           ENDIF
          ENDIF

         ENDIF

      ENDIF

C***  Now increment counter, jumping over continuation lines       
      IKD = IKD + 1 + NCONTLINES
      IF (IKD .LE. NKD) GOTO 4
C***  END of the loop over all KASDEF lines ***************************


C***  Checking for missing end of INSTRUCTION EXPORT
      IF (BINSEX) THEN
         WRITE (*, '(/, A)') 
     >      '***** WARNING: MISSING "INSTRUCTION NO-EXPORT"' 
      ENDIF

C***  Checking the dimensioning
      IF (NDATMAX * NSETMAX .GT. NDATTOT) THEN
         WRITE (*, '(/, A)') '***** FATAL ERROR *******' 
         WRITE (*, '(A)') 'TOO MUCH DATASPACE REQUESTED' 
         WRITE (*, '(A,I10)') 'NDATMAX * NSETMAX =', NDATMAX*NSETMAX 
         WRITE (*, '(A,I10)') 'Maximum available is NDATTOT =', NDATTOT 
         STOP 'ERROR detected by KDSET' 
      ENDIF
 
      IF (NSETMAX .EQ. 0 .AND. NDATMAX .EQ. 0) THEN
         NSETMAX = NSETMAXDEFAULT
         NDATMAX = NDATMAXDEFAULT
      ELSE IF (NSETMAX .EQ. 0) THEN 
         NSETMAX = NDATTOT / NDATMAX
      ELSE IF (NDATMAX .EQ. 0) THEN 
         NDATMAX = NDATTOT / NSETMAX
      ENDIF

      RETURN

C**********************************************************************
C***  EROR BRANCH
C**********************************************************************

95    WRITE (*,'(/A)') '*** ERROR: CONTINUATION LINE TRUNCATED'
      WRITE (*,'(A)') '*** THE ERROR OCCURED IN THE FOLLOWING LINES:'
      WRITE (*,'(A)') LINE (:IDX(LINE ))
      WRITE (*,'(A)') LINE1(:IDX(LINE1))
      STOP 'ERROR IN KDSET'

96    WRITE(*,*) 
      WRITE(*,*) 'ERROR OCCURED IN KDSET'
      WRITE(*,*) 'THE ERROR OCCURED IN THE FOLLOWING LINE:'
      WRITE(*,*) LINE
      STOP

97    WRITE(*,*) '*** ERROR: FILE ',EXNAM(1:IDX(EXNAM)),
     >           ' NOT FOUND'
      STOP '*** ERROR detected by KDSET (KASDEF INCLUDE)'

98    WRITE (*,*) 'ERROR: MORE KASDEF OPTIONS THAN ALLOWED:', NKDMAX
      WRITE (*,*) 'WHILE INCLUDING FILE: ', EXNAM(:IDX(EXNAM))
      STOP 'ERROR IN KDSET'



      END
libdiff.f/      1553528659  5006  320   100644  2904      `
      SUBROUTINE LIBDIFF
C************************************************************
C***  VERGLEICHT INDEX-LISTEN VON DER VAX UND DER SATURN
C************************************************************

      CHARACTER*80 LINE1, LINE2
      CHARACTER*20 NAME1, NAME2, GROSSB, KLEINB
      CHARACTER*20 DAT1, DAT2, HELP
      CHARACTER YEAR1*4, MONTH1*3, NMONTH1*2, DAY1*2, HOUR1*2, MINU1*2
      CHARACTER YEAR2*4, MONTH2*3, NMONTH2*2, DAY2*2, HOUR2*2, MINU2*2

      OPEN (1, FILE='index.saturn')
      OPEN (2, FILE='index.vax')
      OPEN (3, FILE='index.diff')
      OPEN (4, FILE='REFRESH.COM')
      OPEN (5, FILE='libdiff.routines')
    1 FORMAT (A)

    2 CONTINUE
      READ (1,1, END=99) LINE1
      CALL SARGV (LINE1, 8, NAME1)
      L1 = IDX(NAME1)
      NAME1(L1-1:L1) = '  '
      NAME1 = GROSSB(NAME1)

C***  Bekannte Ausnahmen: Routinen, die nicht an die VAX gehoeren
      IF (NAME1 .EQ. 'DATE') GOTO 2
      IF (NAME1 .EQ. 'TIME') GOTO 2
      IF (NAME1 .EQ. 'LIBDIFF') GOTO 2
      IF (NAME1 .EQ. 'MONTHNUM') GOTO 2
      IF (NAME1 .EQ. 'ACC_XDRIVER') GOTO 2

    3 READ (2,1, END=88) LINE2
      CALL SARGV (LINE2, 1, NAME2)
      IF (NAME1 .EQ. NAME2) THEN
C***     GEGENSTUECK GEFUNDEN: Vergleiche Datum
C***     File 1:
         CALL SARGV (LINE1, 7, YEAR1)
         CALL SARGV (LINE1, 3, MONTH1)
         CALL MONTHNUM (MONTH1, NMONTH1)
         CALL SARGV (LINE1, 4, DAY1)
         IF (DAY1(2:2) .EQ. ' ') THEN 
            DAY1(2:2) = DAY1(1:1)
            DAY1(1:1) = '0'
            ENDIF
         CALL SARGV (LINE1, 5, HOUR1)
         CALL SARGV (LINE1, 6, MINU1)
         DAT1=YEAR1//'-'//NMONTH1//'-'//DAY1//' '//HOUR1//':'//MINU1
C***     File 2:
         CALL SARGV (LINE2, 3, DAT2)
         L2 = IDX (DAT2)
         IF (L2 .LT. 11) THEN
           HELP(:1) = '0'
           HELP(2:) = DAT2
           DAT2 = HELP
           ENDIF 
         YEAR2 = DAT2(8:11)
         MONTH2 = DAT2(4:6)
         CALL MONTHNUM (MONTH2, NMONTH2)
         DAY2 = DAT2(1:2)
         CALL SARGV (LINE2, 4, HOUR2)
         CALL SARGV (LINE2, 5, MINU2)
         DAT2=YEAR2//'-'//NMONTH2//'-'//DAY2//' '//HOUR2//':'//MINU2

C***   Vergleich: saturn juenger als VAX?
         IF (DAT1 .GT. DAT2) THEN
           WRITE (3,'(2A)') NAME2, 'Older on VAX'
           GOTO 89
         ELSE
           REWIND 2
           GOTO 2
         ENDIF
      ENDIF
      GOTO 3

   88 CONTINUE
      WRITE (3,'(2A)') NAME1, 'Missing on VAX'

   89 CONTINUE
      HELP = KLEINB(NAME1)
      L = IDX (HELP)
      WRITE (5,'(A)') HELP(:L) // '.f'
      WRITE (4,1) '$ @REPSAT "'//HELP(:L)//'"'
      WRITE (4,1) '$ REPL '//NAME1(:L)//'/NOPRI'
      REWIND 2
      GOTO 2

   99 CONTINUE
      PRINT *, 'Differences written into file "index.diff"'
      PRINT *, 'VAX procedure written into file "REFRESH.COM"'
      PRINT *, '> execute "get.diff" in order to extract Fortran-Files'
      STOP 'O.K.'
      END
lidat.f/        1553528659  5006  320   100644  3172      `
C**********************************************************************
C***  LESEN DES FILES "LIDAT." (LITERATURDATEI)
C***  AUSDRUCK
C***    A) ALLER REFERENZEN
C***    B) DER REFERENZEN UND TITEL, NACH FAECHERN GEORDNET 
C**********************************************************************
      SUBROUTINE LIDAT

C***  MAXIMUM NUMBER OF LINES PER SINGLE ENTRY
      PARAMETER (MAXLINE = 10)
C***  MAXIMUM NUMBER OF GROUPS
      PARAMETER (MAXF = 30)

      CHARACTER*64 REF(MAXLINE),TITEL(MAXLINE),LINE,GROUP(MAXF)
      CHARACTER SWITCH*1,FCHAR*10

      OPEN (UNIT=1,FILE='lidat.source',STATUS='OLD')
CCCCCC      OPEN (UNIT=2,FILE='lidat.out',STATUS='NEW')

C***  READ THE GROUP HEADLINES
      NF=0
   20 READ (1,'(A)',ERR=98) LINE
      IF (LINE(1:1) .EQ. '*') GOTO 20
      IF (LINE(1:3) .EQ. 'END') GOTO 21
      NF=NF+1
      GROUP(NF)=LINE
      GOTO 20

C***  ERROR EXIT:
   98 PRINT *,'END-OF-DATA REACHED BEFORE "END" OF GROUP HEADLINES'
      PRINT *,'WAS ENCOUNTERED'
      STOP 'ERROR'

C***  PRINTOUT OF HEADER PAGE
  21  CONTINUE
      LINE=' '
      CALL DATE (LINE(1:9))
      CALL TIME (LINE(11:18))
      WRITE (6,22) LINE(1:18)
   22 FORMAT (1H1,15(/),10X,65('*'),/,10X,
     $ 'Literatur-Datei   Wolf-Rainer Hamann    Stand: ',A18,/,
     $ 10X,65('*'),//,10X,'Faecher:')
      DO 23 I=1,NF
   23 WRITE (6,'(13X,A)') GROUP(I)

C***  READ THE DATA FILE REPEATEDLY, ONCE FOR EACH GROUP
      DO 30 J=0,NF
      SWITCH=' '

C***  PRINT GROUP HEADER
      IF (J .EQ. 0) WRITE (6,32)
   32 FORMAT (1H1,//,1X,64('-'),/,' Liste aller Referenzen',
     $ /,1X,64('-'),//)
      IF (J .NE. 0) WRITE (6,31) GROUP(J)
   31 FORMAT (1H1,//,1X,64('-'),/,1X,A64,/,1X,64('-'),//)

    1 READ (1,'(A)',END=99) LINE

C***  RECOGNISE SWITCHES
      IF (LINE(1:1) .EQ. '*') GOTO 1
      IF (LINE  .EQ. 'R=') THEN
         SWITCH='R'
         NR=0
         GOTO 1
         ENDIF
      IF (LINE  .EQ. 'T=') THEN
         SWITCH='T'
         NT=0
         GOTO 1
         ENDIF
      IF (LINE(1:2)  .EQ. 'F=') THEN
         FCHAR=LINE(3:12)
         READ (FCHAR,*) IF
         IF (J .EQ. 0 ) GOTO 40
         IF (J .EQ. IF) GOTO 10
         GOTO 1
         ENDIF
C***  LINE IS NO SWITCH- OR COMMENT LINE:
      IF (SWITCH .EQ. 'R') THEN
         IF (NR .EQ. MAXLINE) GOTO 1
         NR=NR+1
         REF(NR)=LINE
         ENDIF
      IF (SWITCH .EQ. 'T') THEN
         IF (NT .EQ. MAXLINE) GOTO 1
         NT=NT+1
         TITEL(NT)=LINE
         ENDIF
      GOTO 1

C***  PRINTOUT, WHENEVER AN 'F' SWITCH WAS ENCOUNTERED
   10 MAXPRI=MAX0(NR,NT)
      DO 11 I=1,MAXPRI
      IF (I .GT. NR) REF(I)=' '
      IF (I .GT. NT) TITEL(I)=' '
      WRITE (6,12) REF(I),TITEL(I)
   12 FORMAT (1X,A,1X,A)
   11 CONTINUE
      WRITE (6,*) ' '
      GOTO 1

C***  LIST OF ALL REFERNCES
   40 DO 41 II=1,(NR+1)/2
      III=MIN0(2,NR-2*(II-1))
   41 WRITE (6,42) IF, (REF(2*(II-1)+I),I=1,III)
   42 FORMAT (1X,I2,1X,2A)
      GOTO 1

C***  END-OF-DATA REACHED:
   99 REWIND 1
   30 CONTINUE
C***  END-OF-LOOP FOR EACH GROUP **************************************


C***  ALL GROUPS FINISHED:
      PRINT *,'PRINT FILE GENERATED: "lidat.out"'
      STOP 'O.K.'
      END         
lvektoi.f/      1553528659  5006  320   100644  645       `
      

C***************************************************************
C**    Subroutine LVEKtoI : komprimiert einen Vektor von 31    *
C**                         logicals in ein INTEGER*4-Wort     *
C***************************************************************

      Subroutine LVEKtoI(LV,IV)
C  In:
      logical LV(31)

C  out:
      integer*4 IV


      IV=0
C     Startwert, um keine Bits mitzuschieben

      do 10  ib=1,31

      IV=IV*2
C     Dies schiebt die Bits nach links

      if (LV(32-ib)) IV=IV+1
C     Der kaputte Index, um die Bits richtig zu schieben

10    continue

C     ======
      return
C     ======

      end

maeder.f/       1553528659  5006  320   100644  803       `
C*** PROGRAEMMCHEN ZUM RUECKGAENGIGMACHEN DER RADIUS-KORREKTUR
C*** IN MAEDER'S ENTWICKLUNGSTRACKS [MAEDER(1990), A&A SUPPL. 84-1]
      SUBROUTINE MAEDER
      OPEN (UNIT=5, FILE='HRT20.MASSLOSS', STATUS='OLD')
      OPEN (UNIT=7, FILE='HRT20.RSTAR', STATUS='NEW')

    1 READ (5,*, END=99) XLOGTEFF, XLOGL, XLOGMDOT
C***      Write(7,*) 'logteff=',xlogteff,'  logl=',xlogl,' logmdot=',
C***     >            xlogmdot
      XLOGREFF = 0.5 * (XLOGL - 4. * XLOGTEFF + 15.05)
      REFF = 10.**XLOGREFF
C***      Write(7,*) 'reff=',reff

      DELTAR = 0.72E5 * 10.**XLOGMDOT
C***      Write(7,*) 'deltar=',deltar

      XLOGTS = 0.5 * (XLOGREFF + 2. * XLOGTEFF - ALOG10(REFF-DELTAR))

      WRITE (7,2) XLOGTS, XLOGL
    2 FORMAT (1X,4F15.4)
C***      Write(7,*)
      GOTO 1

   99 STOP
      END      

makefont.f/     1653499884  5006  320   100644  3912      `
CCC      PROGRAM MAKEFONT
      SUBROUTINE MAKEFONT
C***********************************************************************
C***  ERZEUGT AUS EINEM WRPLOT3.PSC-FILE TABELLEN FUER MEINEN PS-TREIBER
C***********************************************************************

      CHARACTER LINE*80, ACTPAR*20, ONECHAR*1, STYLE*10
      DIMENSION X(5000), Y(5000)

      CHARACTER*2 TS1
      PARAMETER (TS1 = CHAR(92) // CHAR(124))

    5 PRINT *, 'Welcher Satz: ASCII, &, ', TS1, ' or GREEK ?'
      READ (*,'(A1)') ONECHAR
      IF (ONECHAR .EQ. 'A' .OR. ONECHAR .EQ. 'a') THEN 
         STYLE = 'ASCII'
      ELSE IF (ONECHAR .EQ. 'S' .OR. ONECHAR .EQ. '&') THEN
         STYLE = 'AMPERSAND'
      ELSE IF (ONECHAR .EQ. 'S' .OR. ONECHAR .EQ. TS1) THEN
         STYLE = 'BACKSLASH'
      ELSE IF (ONECHAR .EQ. 'G' .OR. ONECHAR .EQ. 'g') THEN 
         STYLE = 'GREEK'
      ELSE
         GOTO 5
      ENDIF

      OPEN (1, FILE='WRPLOTFONT_'//STYLE(:IDX(STYLE))//'.PLOT', 
     >           STATUS='OLD', ACTION='READ')
      OPEN (2, FILE='WRPLOT3.PSC', STATUS='OLD', ACTION='READ')
      OPEN (3, FILE='WRPLOTFONT_'//STYLE(:IDX(STYLE))//'.DAT', 
     >          STATUS='NEW')

      II = 1

C***  find starting point in WRPLOT3.psc 
    3 READ (2, '(A)', END=99) LINE
      IF (LINE(:12) .NE. '28.3 510.2 D') GOTO 3

C***  READ NEXT CHARACTER 
    1 CONTINUE
      XMIN = 1000. 
      YMIN = 1000. 
      XMAX = .0
      YMAX = .0
      I = 0

C***  ... AND IN WRPLOT-INPUT (FIRST KASDEF LUN)
    2 CONTINUE
      READ (1, '(A)', END=99) LINE
      CALL SARGV (LINE, 1, ACTPAR)
      IF (ACTPAR .NE. 'KASDEF') GOTO 2
      CALL SARGV (LINE, 2, ACTPAR)
      IF (ACTPAR .NE. 'LUN') GOTO 2
C***  DECODE SIZE FROM THE FIRST KASDEF LUN
      IF (II .EQ. 1) THEN
          CALL SARGV (LINE, 7, ACTPAR)
          WRITE (3, '(A)') '% STYLE: ' // STYLE
          WRITE (3, '(A)') '% SIZE(CM): ' // ACTPAR
          II = 0
          ENDIF
      CALL SARGREST (LINE, N, 8, NFIRST, NLAST)
C*** SPEZIALBEHANDLUNG FUER STRINGS IN "", oder beginnend mit #, \ oder @
      IF (LINE(NFIRST:NFIRST) .EQ. '"' .AND.
     >    LINE(NFIRST+3:NFIRST+3) .EQ. '"' ) NFIRST = NFIRST+1
      IF (LINE(NFIRST:NFIRST) .EQ. '#' .OR.
     >    LINE(NFIRST:NFIRST) .EQ. TS1 .OR.
     >    LINE(NFIRST:NFIRST) .EQ. '&')  NFIRST = NFIRST+1
      ONECHAR = LINE(NFIRST:NFIRST)
      WRITE (3, '(A)') '*' // ONECHAR

C***  ... AND THE CORRESPONDING BLOCK IN WRPLOT3.PSC
    4 READ (2, '(A)', END=99) LINE
      IF (LINE(:6) .EQ. 'stroke') GOTO 4 
      IF (LINE(:12) .NE. '28.3 481.9 M') THEN
         I=I+1
         CALL SARGV (LINE, 1, ACTPAR) 
         READ (ACTPAR(:IDX(ACTPAR)), '(F10.0)', ERR=4) X(I) 
         CALL SARGV (LINE, 2, ACTPAR) 
         READ (ACTPAR(:IDX(ACTPAR)), '(F10.0)', ERR=4) Y(I) 
         CALL SARGV (LINE, 3, ACTPAR) 
         READ (ACTPAR, '(A1)') ONECHAR 
         X(i) = X(i) - 28.3
         Y(I) = Y(I) - 170.2
         WRITE (3, '(F6.1, 1X, F6.1, 1X, A2)') X(I), Y(I), ONECHAR
         GOTO 4

         ELSE
C***     end of this character
         BACKSPACE (3)
         READ (3, '(A)', END=99) LINE
         READ (LINE, *, ERR=10) XWIDTH
         GOTO 11
   10       BACKSPACE(3)
            BACKSPACE(3)
           PRINT *, 'ERROR:', LINE
            READ (3, '(A)', END=99) LINE
            READ (LINE, *) XWIDTH

   11    CONTINUE
         BACKSPACE (3)
         BACKSPACE (3)
         DO L=1, I-2
            XMIN = AMIN1 (XMIN, X(L))
            YMIN = AMIN1 (YMIN, Y(L))
            XMAX = AMAX1 (XMAX, X(L))
            YMAX = AMAX1 (YMAX, Y(L))
            ENDDO
         WRITE (3, '(A, 1X, F7.1)') '% BBOX', XMAX 
         WRITE (3, '(A, F5.1)') '% XWIDTH ', XWIDTH 
   12    READ (2, '(A)', END=99) LINE
         IF (LINE(:6) .EQ. 'stroke') GOTO 12 

         GOTO 1
         ENDIF
C***************************************

   99 CLOSE (1)
      CLOSE (2)
      CLOSE (3)

      STOP 'O.K.'
      END
makegi.f/       1553528659  5006  320   100644  1863      `
      SUBROUTINE MAKEGI
C********************************************************************
C***  SCHREIBT IN DIE FILES GITTER_(6,2,62)_(LINE).PLOT
C***  DIE IN DEM INPUTFILE MAKEGI.INPUT_(6,2,62) SPEZIFIZIERTEN
C***  LEVELKARTEN
C********************************************************************

      CHARACTER*255 FINPUT, FGITTER
      CHARACTER*132 LINE
      CHARACTER*60 ACTPAR, CLINE, CLEVEL
      CHARACTER*2 CGIT, CGITDAT(3)

      CGITDAT(1) = '62'
      CGITDAT(2) = '2'
      CGITDAT(3) = '6'
      FINPUT = 'MAKEGI.INPUT'

      OPEN (UNIT=4, FILE='AUTOSPAWN.COM', STATUS='NEW')

      DO 50 K=1, 3
      CGIT = CGITDAT(K)

      OPEN (UNIT=1, FILE=FINPUT, STATUS='OLD', ERR=99)
C***  LOOP UEBER ALLE EINTRAEGE
1     CONTINUE
        READ (1, '(A)', END=98) LINE
        CALL SARGV (LINE, 1, CLINE)
        IF (CLINE(1:1) .EQ. '*') GOTO 1
        CALL SARGV (LINE, 2, CLEVEL)
        IF (CLEVEL .EQ. '-') GOTO 1
        WRITE (4,'(A)') 'SPAWN/INPUT=ISOPRO_' // CGIT( :IDX(CGIT)) //
     >                  '.INPUT_' // CLINE( :IDX(CLINE)) // ' ISOPRO'
        FGITTER = 'ISOEX_' // CGIT( :IDX(CGIT)) // '.' //
     >            CLINE( :IDX(CLINE))
        OPEN (UNIT=2, FILE=FGITTER, STATUS='OLD', ERR=100)
        OPEN (UNIT=3, FILE=FGITTER, STATUS='NEW', ERR=100)
2       CONTINUE
          READ (2, '(A)', END=3) LINE
          CALL SARGV (LINE, 1, ACTPAR)
          IF (ACTPAR .EQ. 'level') THEN
            WRITE (3, '(A)') 'level 1 ' // CLEVEL( :IDX(CLEVEL))
          ELSE
            WRITE (3, '(A)') LINE ( :IDX(LINE))
          ENDIF
        GOTO 2
3       CONTINUE
        CLOSE (2)
        CLOSE (3)
      GOTO 1     

98    CLOSE (1)

50    CONTINUE

      CLOSE (4)
      STOP

99    WRITE (6,*) 'ERROR WHEN OPENING INPUT FILE ',FINPUT
      STOP

100   WRITE (6,*) 'ERROR WHEN OPENING GITTER FILE ',FGITTER
      STOP

      END

makepl.f/       1553528659  5006  320   100644  4353      `
      SUBROUTINE MAKEPL
C********************************************************************
C***  ERGAENZT DAS FILE MAKEPL.RAW UND HAENGT ALL FILES DES NAMENS
C***  ISOEX_?.WRPLOT;* (MAXIMAL 8 FILES) HINTEN AN
C********************************************************************

      CHARACTER*132 LINE
      CHARACTER*60 ACTPAR, FINPUT, FINPUT2, OUTFILE
      CHARACTER*10 CINFO(8,2), CID(8)
      CHARACTER*2 CGIT, CTEMP
      CHARACTER*8 CWR

C***  NAME OF INPUT FILE
      WRITE (6,*) 'WELCHES GITTER SOLL BENUTZT WERDEN?'
      WRITE (6,*) '6, 2, 62'
      READ (5,'(A)') CGIT
      FINPUT = 'ISOEX_' // CGIT( :IDX(CGIT)) // '.WRPLOT;-'

C***  NAME OF WR STAR
      WRITE (6,*) 'NUMMER DES WR STERNS?'
      READ (5, '(A)') CWR

      DO 20 I=1, 8
        DO 20 J=1, 2
          CINFO (I,J) = '-'
20    CONTINUE

      CID(1) = '5696'
      CID(2) = '4441'
      CID(3) = '5017'
      CID(4) = '5470'
      CID(5) = '4860'
      CID(6) = '5412'
      CID(7) = '10830'
      CID(8) = '5876'

C***  LOOP OVER ALL PLOT FILES TO EXTRACT INFORMATIONS
      N = 0
1     CONTINUE
        WRITE (CTEMP, '(I2)') N
        IF (CTEMP(1:1) .EQ. ' ') CTEMP = CTEMP(2:2)
        IF (N .GT. 0) THEN
          FINPUT2 = FINPUT( :IDX(FINPUT)) // CTEMP( :IDX(CTEMP))
        ELSE
          FINPUT2 = FINPUT( :IDX(FINPUT)-1)
        ENDIF
      WRITE(*,*) 'FINPUT2=',FINPUT2
        OPEN (UNIT=1, FILE=FINPUT2, STATUS='OLD', ERR=2)
        READ (1, '(A)') LINE
        CALL SARGC (LINE, M)
        CALL SARGV (LINE, M, CINFO(N+1,1))
        DO 5 J=1,8
5       READ (1, '(A)') LINE
        CALL SARGC (LINE, M)
        CALL SARGV (LINE, M, CINFO(N+1,2))
        IF (N .EQ. 7) GOTO 2
        N = N + 1
        CLOSE (1)
      GOTO 1
2     CONTINUE
      CLOSE (1)

C***  CONVERT RAW FILE
      OPEN (UNIT=1, FILE='MAKEPL.RAW', STATUS='OLD', ERR=99)
      OUTFILE = 'WR' // CWR( :IDX(CWR)) // '.PLOT'
      OPEN (UNIT=2, FILE=OUTFILE, STATUS='NEW')
      READ (1, '(A)') LINE
      LINE = LINE( :IDX(LINE)) // '  ' // OUTFILE( :IDX(OUTFILE)) // 
     >       '   C=0.' // CGIT( :IDX(CGIT))
      WRITE (2, '(A)') LINE( :IDX(LINE))
      READ (1, '(A)') LINE
      WRITE (2, '(A)') LINE( :IDX(LINE))
      READ (1, '(A)') LINE
      LINE = LINE( :IDX(LINE)) // OUTFILE( :IDX(OUTFILE)-5)
      WRITE (2, '(A)') LINE( :IDX(LINE))
      READ (1, '(A)') LINE
      LINE = LINE( :IDX(LINE)) // CGIT
      WRITE (2, '(A)') LINE( :IDX(LINE))
C***  SEARCH FOR * 5696
10    CONTINUE
        READ (1, '(A)', END=15) LINE
        IF (LINE .EQ. '* 5696') THEN
          DO 11 I=1, 8
            J = 0
40          CONTINUE
              J = J + 1
              IF (CINFO(J,1) .NE. CID(I) .AND.
     >            J .LE. 7) GOTO 40
            WRITE (2, '(A)') LINE ( :IDX(LINE))               
            READ (1, '(A)') LINE
            LINE = LINE( :IDX(LINE)) // '  ' // CINFO(J,1)         
            WRITE (2, '(A)') LINE ( :IDX(LINE))               
            READ (1, '(A)') LINE
            LINE = LINE( :IDX(LINE)) // '  ' // CINFO(J,2)         
            WRITE (2, '(A)') LINE ( :IDX(LINE))               
            READ (1, '(A)', END=15) LINE
11        CONTINUE
        ENDIF
        WRITE (2, '(A)') LINE( :IDX(LINE))
      GOTO 10

15    CONTINUE
      CLOSE (1)

C***  APPEND ALL INPUT-FILES
      DO 50 I=0, N-1
        WRITE (CTEMP, '(I2)') I
        IF (CTEMP(1:1) .EQ. ' ') CTEMP = CTEMP(2:2)
        IF (I .GT. 0) THEN
          FINPUT2 = FINPUT( :IDX(FINPUT)) // CTEMP( :IDX(CTEMP))
        ELSE
          FINPUT2 = FINPUT( :IDX(FINPUT)-1)
        ENDIF
      WRITE(*,*) 'FINPUT2=',FINPUT2
        OPEN (UNIT=1, FILE=FINPUT2, STATUS='OLD', ERR=98)
55      CONTINUE
          READ (1, '(A)', END=70) LINE
          CALL SARGV (LINE, 2, ACTPAR)
          LINE = '*' // LINE
          WRITE (2, '(A)') LINE ( :IDX(LINE))
        IF (ACTPAR .NE. 'LUN') GOTO 55
60      CONTINUE
          READ (1, '(A)', END=70) LINE
          CALL SARGV (LINE, 1, ACTPAR)
          IF (ACTPAR(1:3) .EQ. 'END' .OR. ACTPAR .EQ. 'KASDEF') THEN
            LINE = '*' // LINE
          ENDIF
          WRITE (2, '(A)') LINE ( :IDX(LINE))
        GOTO 60
70      CONTINUE
        CLOSE (1)
50    CONTINUE

      WRITE (2, '(A)') 'END'
      STOP

98    WRITE (*,*) 'ERROR WHEN OPENING APPEND FILES'
      STOP

99    WRITE(*,*) 'NO RAW FILE: MAKEPL.RAW'
      STOP

      END

mdotl.f/        1553528659  5006  320   100644  1010      `
      SUBROUTINE MDOTL
C**************************************************************
C***  Programm zum Erstellen einer Tabelle M-Dot versus L
C***      nach dem Gesetz M-Dot (M) nach Langer
C***      sowie der Masse-Leuchtkraft-Beziehung
C**************************************************************

C***  ERSTER WERT
      XLOGLSTART = 6.5
C***  SCHRITTWEITE
      DLOGL = -0.1
C***  ENDWERT
      XLOGLEND = 4.3

      OPEN (2, FILE='MDOTL.OUT', STATUS='NEW')
      WRITE (2,'(A)') '*  log L   log M-Dot     log M'

      XLOGL = XLOGLSTART
    1 CONTINUE
C***  N. LANGER, 1989, A&A 210, 93 --- EQ. 18
      XLOGM = -0.158206 + XLOGL * (- 0.053868 + 0.055467 * XLOGL)
C***  N. LANGER, 1989, A&A 210, 135 -- EQ. 8 MIT 0.6
      XLOGMDOT = -7.222 + 2.5 * XLOGM
C!!   Doppelter Wert:
      XLOGMDOT = XLOGMDOT + 0.301

      WRITE (2,2) XLOGL, XLOGMDOT, XLOGM
    2 FORMAT (3F10.3)

      XLOGL = XLOGL + DLOGL
      IF ((XLOGL-XLOGLEND)*(XLOGLSTART-XLOGLEND) .GE. .0) GOTO 1

      STOP 'O.K.'
      END
modcodat.f/     1553528659  5006  320   100644  3148      `
      SUBROUTINE MODCODAT

C**********************************************************************
C***  INPUT: MODCOMP DATA FILE
C***                                  
C***  OUTPUT: FILE FOR PROGRAM WRPLOT
C***          NOTE: YOU HAVE TO COPY THIS OUTPUT FILE TO "PLOT DIRECTORY"
C**********************************************************************

      PARAMETER (MAXPOINTS= 5000)

      DIMENSION FLAM(MAXPOINTS), FNUE(MAXPOINTS), XLAM(MAXPOINTS)
      CHARACTER FILEIN*64, FILEOUT*64, OUTLINE*100
      CHARACTER LINE1*100, LINE2*100, LINE3*100, LINE4*100

1     WRITE(6,'(''$'',A)') 'NAME OF MODCOMP FILE: '
      READ(5,'(A)',END=101) FILEIN
      OPEN (UNIT=1,FILE=FILEIN,STATUS='OLD',ERR=99)
      WRITE(6,*) 'FILE OPENED: ',FILEIN

      WRITE(6,'(''$'',A)') 'NAME OF OUTPUT FILE: '
      READ (5,'(A)') FILEOUT      
      OPEN (UNIT=2,FILE=FILEOUT,STATUS='NEW')

C***  READ DATA FROM INPUT FILE            

2     READ(1,'(A)',END=101) LINE1
      IF (LINE1(1:6) .NE. 'RECORD') GOTO 2
      READ (1,900) LINE2
900   FORMAT(A100)
      READ (LINE2,901) NMAX
901   FORMAT(67X,I4)
      IF (NMAX .GT. MAXPOINTS) THEN
        WRITE(6,*) 'ERROR: TOO MANY FREQUENZ POINTS'
        GOTO 100
      ENDIF     
      DO 3 I=1,NMAX,5
        J=MIN0(5,NMAX-I+1)
        READ(1,*) (FNUE(I+L-1), L=1,J)
3     CONTINUE
      READ (LINE2,902) XLAM(1),DELTA
902   FORMAT(7X,F10.0,33X,F10.0)
      DO 4 I=2,NMAX
4       XLAM(I)=XLAM(1)+FLOAT(I)*DELTA
      IMIN=XLAM(1)/50
      IMIN=IMIN*50
      IMAX=(XLAM(NMAX)+49.999)/50
      IMAX=IMAX*50
      WRITE(LINE3,903) 20./(FLOAT(IMAX-IMIN)),FLOAT(IMIN),FLOAT(IMAX),
     $                 FLOAT(IMAX-IMIN)/20.,FLOAT(IMAX-IMIN)/5.
903   FORMAT(' X:',F8.3,5X,F8.3,3X,F8.3,3X,F8.3,3X,F8.3,'  0.00')
      YMAX=0.
      DO 55 I=1,NMAX
55      IF (FNUE(I) .GT. YMAX) YMAX=FNUE(I)
      IMAX=INT(YMAX+1.)
      IMIN=0
      WRITE(LINE4,904) 15./(FLOAT(IMAX-IMIN)),FLOAT(IMIN),FLOAT(IMAX),
     $                 FLOAT(IMAX-IMIN)/20.,FLOAT(IMAX-IMIN)/5.
904   FORMAT(' X:',F8.3,5X,F8.3,3X,F8.3,3X,F7.4,4X,F7.4,'   0.00')

C***  HEADER IN PLOT FILE

      WRITE(2,'(A)') '2$$$$$$$$='
      WRITE(2,'(A)') ' PLOT   :          MODCOMP - DATEN               '
      WRITE(2,'(A)') ' HEADER :          MODCOMP - DATEN               '
      WRITE(2,'(A)') ' X-ACHSE:                 LAMBDA/ANGSTROEM       '
      WRITE(2,'(A)') ' Y-ACHSE:                   FNUE                 '
      WRITE(2,'(A)') 
     *'     MASSTAB    MINIMUM    MAXIMUM    TEILUNGEN  BESCHRIFT. DAR'
      WRITE(2,'(A)') LINE3
C     *' X: 20.000      3.000      4.000      0.1000     0.5000    0.00'
      WRITE(2,'(A)') LINE4
C     *' Y: 5.0000      -25.2      -22.2      0.1000     0.5000    0.00'
      WRITE(2,201) NMAX
201   FORMAT(' N=',I4,'  PLOTSYMBOL 5')

C***  WRITE NEW DATA TO OUTFILE

      DO 5 I=1,NMAX,5
        J=MIN0(5,NMAX-I+1)
        WRITE(2,202) (XLAM(I+L-1), L=1,J)
        WRITE(2,202) (FNUE(I+L-1), L=1,J)
202     FORMAT (1X,5(F9.4,3X))
5     CONTINUE

      WRITE(2,'(A)') ' ENDE'
100   GOTO 2
101   CLOSE(2)
      CLOSE(1)
      STOP 'OK'

99    WRITE(6,*) 'ERROR: INPUT FILE NOT FOUND'
      GOTO 1

      END
monaco.f/       1553528659  5006  320   100644  2112      `
C**********************************************************************
C***  MONTE-CARLO SOLUTION OF RADIATION TRANSFER PROBLEMS             *
C***     - AN EXAMPLE: LIMB DARKENING IN A GREY, PLANE-PARALLEL SLAB  *
C**********************************************************************

      SUBROUTINE MONACO

C***  NUMBER OF ANGLE POINTS
      PARAMETER (NA = 40)

      DIMENSION NMU(NA)
      IDUMMY = 0    ! START VARIABLE FOR RANDOM FUNCTION

      PRINT *, 'NUMBER OF PHOTONS:'
      READ *, NPHOT

      PRINT *, 'OPTICAL DEPTH:'
      READ *, TAUMAX

C***  INITIALIZE COUNTING REGISTERS
      DO 1 I=1, NA
    1 NMU(I) = 0

C***  LOOP OVER ALL PHOTONS  ---------------------------------------
      DO 2 L=1, NPHOT

C***  PHOTON STARTS FROM INNER BOUNDARY WITH RANDOM (OUTWARD) DIRECTION
      TAU = TAUMAX
      XMU = SQRT(RAND(IDUMMY))

C***  RANDOM PATH LENGTH ( .LT. INFINITY!)
    3 X = RAND(IDUMMY)
      IF (X .LE. 0) GOTO 3
      DTAU = -ALOG(X)
      TAU = TAU - DTAU * XMU

      IF (TAU .LE. .0) THEN
C***     PHOTON ESCAPED VIA OUTER BOUNDARY: COUNT IT!
         I = INT (NA*XMU) + 1
         NMU(I) = NMU(I) + 1

      ELSE IF (TAU .LT. TAUMAX) THEN
C***     PHOTON IS SCATTERED IN A RANDOM DIRECTION (-1,+1)
         XMU = -1. + 2. * RAND(IDUMMY)
         GOTO 3
      ENDIF
C*** ( ... ELSE: PHOTON ESCAPED VIA INNER BOUNDARY)

    2 CONTINUE   !---  END-OF-LOOP ---------------------------

C*** OUTPUT: PRINTER GRAPHIC 
      OPEN (1, FILE='MONACO.LIS', STATUS='NEW')

      WRITE (1,10) NMU(NA), TAUMAX, NPHOT
   10 FORMAT (1H1, //, 10X, 'NORMALIZED INTENSITY = ',
     $        'COUNTS PER ANGLE INTERVAL / MUE',
     $        ' (100 SYMBOLS = ', I6, ' PHOTONS)',//,
     $        10X, '-- TAUMAX=', F4.1, 
     $        10X, 'NUMBER OF PHOTONS:', I7, '   --', //)

C***  NORMALIZE TO 100 AT INTENSITY AT MUE = 1
      DO 4 I=1, NA
    4 NMU(I) = NINT ( FLOAT(NMU(I)*100) / FLOAT(NMU(NA)) *
     *           FLOAT(NA)/(FLOAT(I)-0.5) )

      DO 5 I=1, NA
    5 WRITE (1,11) (FLOAT(I)-0.5)/NA,(L-L/10*10, L=1, NMU(I) )
   11 FORMAT (1X, F5.3, 2X, 120I1)

      STOP 'O.K.'
      END
monthnum.f/     1553528659  5006  320   100644  1193      `
      SUBROUTINE MONTHNUM (MONTHPAR, NMONTH)
C************************************************************
C***  Converth month (3-Character abbreviation) into month-number
C************************************************************
      CHARACTER MONTH*3, MONTHPAR*3, GROSSB*3, NMONTH*2
      
C***  CONVERT INTO CAPITALS
      MONTH = GROSSB (MONTHPAR)

      IF (MONTH .EQ. 'JAN') THEN
         NMONTH = '01'
      ELSE IF (MONTH .EQ. 'FEB') THEN
         NMONTH = '02'
      ELSE IF (MONTH .EQ. 'MAR') THEN
         NMONTH = '03'
      ELSE IF (MONTH .EQ. 'APR') THEN
         NMONTH = '04'
      ELSE IF (MONTH .EQ. 'MAY') THEN
         NMONTH = '05'
      ELSE IF (MONTH .EQ. 'JUN') THEN
         NMONTH = '06'
      ELSE IF (MONTH .EQ. 'JUL') THEN
         NMONTH = '07'
      ELSE IF (MONTH .EQ. 'AUG') THEN
         NMONTH = '08'
      ELSE IF (MONTH .EQ. 'SEP') THEN
         NMONTH = '09'
      ELSE IF (MONTH .EQ. 'OCT') THEN
         NMONTH = '10'
      ELSE IF (MONTH .EQ. 'NOV') THEN
         NMONTH = '11'
      ELSE IF (MONTH .EQ. 'DEC') THEN
         NMONTH = '12'
      ELSE
         STOP 'ERROR: INVALID MONTH NAME IN SUBR. MONTHNUM'
      ENDIF

      RETURN
      END

mysymbl.f/      1553528659  5006  320   100644  3364      `
      SUBROUTINE MYSYMBL (XCM, YCM, SIZE, STRPAR, ANGLE)
C*************************************************************************
C***  Prints a character string
C***  Called from various places!
C*************************************************************************

      EXTERNAL FRACTION
      COMMON / COMIDEV / IDEV
      CHARACTER FONT*1 

      COMMON / COMGLATEX / GLATEX

C***  Test characters
      CHARACTER*1 TC1, TC2, GLATEXCHRS*9
      LOGICAL CHRINSTR, GLATEX

C***  Backslash-Combinations for Fractions
      CHARACTER*2 TS3, LS3

C***  active graphic driver
      COMMON / COMACT / ACTDRIV
      CHARACTER ACTDRIV*7

C***  Last text attribute status (for special use by WRPLOT)
      COMMON / COMATT / ATTCOLOR, ATTINCL, ATTWIDTH, ATTSUB, ATTBOLD, 
     >                  ALLATT
      CHARACTER*2 ATTCOLOR, ATTINCL, ATTWIDTH, ATTSUB, ATTBOLD 
      CHARACTER   ALLATT*8

      PARAMETER (N = 144)
      CHARACTER STRPAR*(*), STR*(N)
      DATA PI / 3.1415927 /

C***  Backslash-{ fuer Anfang eines Fractions
      TS3 = CHAR(92) // CHAR(123)
C***  Backslash-( fuer Anfang einer Latex-Formel
      LS3 = CHAR(92) // '('
C***  Single quote added to german-latex characters
      GLATEXCHRS = 'AOUaous`' // CHAR(39)
C***  All old text attributes are initialized
      NATT = 0
      ATTCOLOR = '  '
      ATTINCL  = '  '
      ATTWIDTH = '  '
      ATTSUB   = '  '
      ATTBOLD  = '  '
      ALLATT   = '        '

      XPOS = XCM
      YPOS = YCM
    4 CONTINUE
      LENGTH = IDX(STRPAR)
      IF (LENGTH .EQ. 0) RETURN
      LAST = LENGTH

C***  STYLE GLATEX: Replace " by & fur Umlaut etc.
      IF (GLATEX) THEN 
         DO I=1, LENGTH-1
            TC1= STRPAR(I:I)
            IF ( TC1 .EQ. '"') THEN
               TC2 = STRPAR(I+1:I+1)
               IF ( CHRINSTR (TC2, GLATEXCHRS))  STRPAR(I:I) = '&'
            ENDIF
	 ENDDO
      ENDIF
      
C***  recognize FRACTIONS
      CALL STRPOS (TS3, STRPAR, IPOSF)
      IF (IPOSF .NE. 0) LAST = IPOSF - 1

C***  recognize inline-latex
      CALL STRPOS (LS3, STRPAR, IPOSL)
      IF (IPOSL .NE. 0) LAST = IPOSL - 1

C********** PSOWN BRANCH ******************************************
      IF (ACTDRIV .EQ. 'PSOWN') THEN
      CALL PS_SYMBL (XPOS, YPOS, SIZE, STRPAR(:LAST), ANGLE)
      CALL PS_TEXTLEN (XADD, SIZE, STRPAR(:LAST))
      
C********** X11OWN BRANCH ******************************************
      ELSE IF (ACTDRIV .EQ. 'X11OWN') THEN
      CALL X_SYMBL (XPOS, YPOS, SIZE, STRPAR(:LAST), ANGLE)
      CALL X_TEXTLEN (XADD, SIZE, STRPAR(:LAST))
      
      ELSE
      STOP 'ERROR IN MYSYMBL: UNKNOWN DRIVER'
      ENDIF

C***  Insert fraction
      IF (IPOSF .GT. 0) THEN
         XPOS = XPOS + 0.2 * SIZE
         IF (STRPAR(LAST:LAST) .EQ. ' ') XPOS = XPOS + 0.5 * SIZE
         STRPAR = STRPAR(IPOSF+2:)
         XPOS = XPOS + XADD
         CALL FRACTION (XPOS, YPOS, SIZE, STRPAR, ANGLE)
         GOTO 4
      ENDIF

C***  Insert inline-latex
      IF (IPOSL .GT. 0) THEN
ccc         XADD = XADD + 0.2 * SIZE
         IF (STRPAR(LAST:LAST) .EQ. ' ') XADD = XADD + 0.5 * SIZE
         STRPAR = STRPAR(IPOSL+2:)
          CALL TURN (DX, DY, XADD, 0., ANGLE)
         YPOS = YPOS + DY 
         XPOS = XPOS + DX
         CALL INLATEX (XPOS, YPOS, SIZE, STRPAR, ANGLE, BBXWIDTH, 
     >                 'PRINT')
         GOTO 4
      ENDIF

      RETURN

      END
mytlen.f/       1553528659  5006  320   100644  3416      `
      SUBROUTINE MYTLEN (TEXLEN, SIZE, STRPAR, ILAST) 
C**********************************************************************
C***  This subroutine is for determination 
C***  of the plot length of a character string.
C***  Called from: SUBROUTINE MYSYMBL (WRPLOT System)
C**********************************************************************

      PARAMETER (NSTR = 144)
      PARAMETER (MAXLEN = 512)
      CHARACTER STR*(NSTR), TEXT*(MAXLEN), STRPAR*(*)
      CHARACTER*2 TS3, LS3

C***  Last text attribute status (for special use by WRPLOT)
      COMMON / COMATT / ATTCOLOR, ATTINCL, ATTWIDTH, ATTSUB, ATTBOLD, 
     >                  ALLATT
      CHARACTER*2 ATTCOLOR, ATTINCL, ATTWIDTH, ATTSUB, ATTBOLD
      CHARACTER   ALLATT*8

C***  Active graphic driver
      COMMON / COMACT / ACTDRIV
      CHARACTER ACTDRIV*7

      COMMON / COMGLATEX / GLATEX

C***  Test characters
      CHARACTER*1 TC1, TC2, GLATEXCHRS*9
      LOGICAL CHRINSTR, GLATEX

C***  Backslash-{ fuer Anfang eines Fractions
      TS3 = CHAR(92) // CHAR(123)
C***  Backslash-( fuer Anfang einer Latex-Formel
      LS3 = CHAR(92) // '('
C***  Single quote added to german-latex characters
      GLATEXCHRS = 'AOUaous`' // CHAR(39)

C***  All old text attributes are initialized
      NATT = 0
      ATTCOLOR = '  '
      ATTINCL  = '  '
      ATTWIDTH = '  '
      ATTSUB   = '  '
      ATTBOLD  = '  '

C***  Check maximum string length
      LENGTH = IDX(STRPAR(:ILAST))
      IF (LENGTH .GT. MAXLEN) THEN
         PRINT *, 'The following string is too long:'
         PRINT *, STRPAR(:LENGTH)
         STOP 'ERROR IN SUBROUTINE MYTLEN'
      ENDIF
      TEXT = STRPAR(:LENGTH)

      TEXLEN = .0
    4 CONTINUE
      LENGTH = IDX(TEXT)
      IF (LENGTH .EQ. 0) RETURN
      LAST = LENGTH

C***  STYLE GLATEX: Replace " by & fur Umlaut etc.
      IF (GLATEX) THEN 
         DO I=1, LENGTH-1
            TC1= TEXT(I:I)
            IF ( TC1 .EQ. '"') THEN
               TC2 = TEXT(I+1:I+1)
               IF ( CHRINSTR (TC2, GLATEXCHRS))  TEXT(I:I) = '&'
            ENDIF
	 ENDDO
      ENDIF

C***  recognize FRACTIONS
      CALL STRPOS (TS3, TEXT, IPOS)
      IF (IPOS .NE. 0) LAST = IPOS - 1
C***  recognize inline-latex
      CALL STRPOS (LS3, TEXT, IPOSL)
      IF (IPOSL .NE. 0) LAST = IPOSL - 1


C********** PS Driver ********************************************
      IF (ACTDRIV .EQ. 'PSOWN') THEN
         CALL PS_TEXTLEN (ADDLEN, SIZE, TEXT(:LAST)) 

C********** X11 Driver *******************************************
      ELSE IF (ACTDRIV .EQ. 'X11OWN') THEN
         CALL X_TEXTLEN  (ADDLEN, SIZE, TEXT(:LAST)) 

      ELSE
      STOP 'ERROR IN MYTLEN: UNKNOWN DRIVER'
      ENDIF

      TEXLEN = TEXLEN + ADDLEN

C***  Special branch for Fractions
      IF (IPOS .GT. 0) THEN
         TEXLEN = TEXLEN + 0.2 * SIZE
         IF (TEXT(LAST:LAST) .EQ. ' ') TEXLEN = TEXLEN + 0.5 * SIZE
         TEXT = TEXT(IPOS+2:)
         CALL FRACLEN (SIZE, TEXT, XFRACLEN)
         TEXLEN = TEXLEN + XFRACLEN
         GOTO 4
      ENDIF

C***  Measure width of EPS-object for INLATEX
      IF (IPOSL .GT. 0) THEN
         TEXLEN = TEXLEN + 0.2 * SIZE
         IF (TEXT(LAST:LAST) .EQ. ' ') TEXLEN = TEXLEN + 0.5 * SIZE
         TEXT = TEXT(IPOSL+2:)
         XPOS = .0
	 YCM  = .0
         CALL INLATEX (XPOS, YCM, SIZE, TEXT, 0., BBXWIDTH, 'LEN')
         TEXLEN = TEXLEN + BBXWIDTH
         GOTO 4
      ENDIF

      RETURN
      END
nachb.f/        1553528659  5006  320   100644  1511      `
      FUNCTION NACHB (IX, IY, IFELD, IXDIM, IYDIM)
C*********************************************************************
C***  CALLED FROM SUBR. ISOPLO (PROG. ISOPRO)
C***  ERMITTELT DIE ZAHL DER GESETZTEN NACHBAR-BITS DES PUNKTES IX, IY
C*********************************************************************

      LOGICAL GETBIT
      COMMON / ISOCOM / IXMAX, IXMIN, IYMAX, IYMIN, SCALEX, SCALEY
      DIMENSION IFELD(0:IXDIM,0:IYDIM)

      NACHB = 0

C***  LINKS BENACHBARTE SPALTE
      IF (IX .GT. IXMIN) THEN
        IF (GETBIT(IX-1, IY    , IFELD, IXDIM, IYDIM)) NACHB = NACHB + 1 
        IF (IY .GT. IYMIN) THEN 
          IF (GETBIT(IX-1, IY-1, IFELD, IXDIM, IYDIM)) NACHB = NACHB + 1
        ENDIF
        IF (IY .LT. IYMAX) THEN
          IF (GETBIT(IX-1, IY+1, IFELD, IXDIM, IYDIM)) NACHB = NACHB + 1
            ENDIF
         ENDIF

C***  SELBE SPALTE
      IF (IY .GT. IYMIN) THEN
         IF (GETBIT(IX  , IY-1, IFELD, IXDIM, IYDIM)) NACHB = NACHB + 1
         ENDIF
      IF (IY .LT. IYMAX) THEN
         IF (GETBIT(IX  , IY+1, IFELD, IXDIM, IYDIM)) NACHB = NACHB + 1
         ENDIF

C***  RECHTS BENACHBARTE SPALTE
      IF (IX .LT. IXMAX) THEN
        IF (GETBIT(IX+1, IY  , IFELD, IXDIM, IYDIM)) NACHB = NACHB + 1
        IF (IY .GT. IYMIN) THEN
          IF (GETBIT(IX+1, IY-1, IFELD, IXDIM, IYDIM)) NACHB = NACHB + 1
        ENDIF
        IF (IY .LT. IYMAX) THEN
          IF (GETBIT(IX+1, IY+1, IFELD, IXDIM, IYDIM)) NACHB = NACHB + 1
        ENDIF
      ENDIF

      RETURN
      END

nolf.f/         1553528659  5006  320   100644  893       `
      SUBROUTINE NOLF (FORMSTR)
C********************************************************************
C***  Der Format-String FORMSTR wird so manipuliert, dass nach seiner 
C***  Ausgabe das Lineffed unterdrueckt wird. Dies geschieht mit den
C***  spezifischen nicht-Standard-Mitteln unter VMS bzw. Unix.
C***  VMS branch entfernt! wrh,  4-Mar-1998 14:19:35
C********************************************************************
      COMMON / COMOS / OPSYS
      CHARACTER*8 OPSYS
      CHARACTER*(*) FORMSTR

      LAST = IDX(FORMSTR)
      IF (LAST .EQ. 0) THEN
         PRINT *, '**** ERROR IN SUBR. NOLF:'
         PRINT *, '**** ZERO FORMAT STRING ENCOUNTERED'
         STOP 'ERROR'
         ENDIF

      DO 1 I=1, LAST
         IFIRST = I
         IF (FORMSTR(I:I) .NE. ' ') GOTO 2
    1 CONTINUE

    2 CONTINUE

      FORMSTR = FORMSTR(IFIRST:LAST-1) // ', $)'

      RETURN
      END

pen.f/          1553528659  5006  320   100644  1463      `
      SUBROUTINE PEN (I, IDEV)
C**********************************************************************
C***  SELECTION OF LINE WIDTH, DEPENDING ON THE SELECTED DEVICE IDEV:
C***    LASERJET (HPG; IDEV=8): WITH NEWPEN
C***    DESKJET  (POSTSCRIPT; IDEV=3) : WITH SPECIAL COMMAND
C***  THIS SUBROUTINE BELONGS TO THE WRPLOT SYSTEM
C**********************************************************************

      DATA LASTPEN /0/

C***  Active graphic driver
      COMMON / COMACT / ACTDRIV
      CHARACTER ACTDRIV*7 

      IF (I .LE. 0) THEN
         I=1
         PRINT *, 'WARNING: ILLEGAL CHOICE OF PEN=0 replaced by 1'
      ENDIF




C************ CALCOMP BRANCH ************************
      IF (ACTDRIV .EQ. 'CALCOMP') THEN
         STOP 'ERROR IN SUBR. PEN: CALCOMP DRIVER DISABLED'
c      IF (IDEV .EQ. 8) THEN
c         CALL NEWPEN (I)
c       ELSE IF (IDEV .EQ. 3  .AND. I .NE. LASTPEN) THEN
c         LASTPEN = I
C*** First: dummy call
c         CALL NEWPEN (1)
c         CALL NEWPEN (3)
c         WRITE (3, '(A)'          )         'stroke'
c         WRITE (3, '(F5.2, 1X, A)') I*0.20, 'setlinewidth'
c       ENDIF

C************ PSOWN BRANCH ************************
      ELSE IF (ACTDRIV .EQ. 'PSOWN') THEN
      CALL PS_NEWPEN (I)

C************ X11OWN BRANCH ************************
      ELSE IF (ACTDRIV .EQ. 'X11OWN') THEN
      CALL X_NEWPEN (I)

      ELSE
      STOP 'ERROR IN SUBR. PEN: UNKNOWN DRIVER'
      ENDIF


      RETURN
      END

plotbox.f/      1553528659  5006  320   100644  10606     `
      SUBROUTINE PLOTBOX (HEADER,XTEXT,YTEXT,B,C, NOTICKX, NOTICKY, 
     >                    NOTICK2X, NOTICK2Y, ALTX, ALTY,
     >                    NOLABX, NOLABY, NOBOX, SIZELET, LASTPEN, IDEV,
     >                    VAR, MAXVAR, NVAR, NOMINMAX, SIZETIC)
C**************************************************************************
C*** PLOT BOX FRAME / CALLED FROM MAIN PROGRAM WRPLOT
C**************************************************************************

      DIMENSION B(6), C(6)
      CHARACTER*144 HEADER, XTEXT, YTEXT, TICKSTR
      CHARACTER NUMSTR*9, FORMSTR*60, CENTER*8,RIGHT*7,UP*4
      LOGICAL NOTICKX, NOTICKY, NOLABX, NOLABY, NOBOX
      LOGICAL NOTICK2X, NOTICK2Y, NOMINMAX(10), ALTX, ALTY
      CHARACTER*(*) VAR(MAXVAR,2)

C***  String fuer \CENTER\  :
      CENTER = CHAR(92) // 'CENTER' // CHAR(92)
C***  String for \RIGHT\ :
      RIGHT   = CHAR(92) // 'RIGHT' // CHAR(92)
C***  String for \UP\ :
      UP   = CHAR(92) // 'UP' // CHAR(92)

C***  SIZE OF THE LETTERS (HEIGHT IN CM)
      SIZEDEF  = 0.4
      SIZEFAC  = SIZELET / SIZEDEF
C***  SIZE OF THE TICKS  (LENGTH IN CM)    
      TICFAC   = SIZETIC / SIZEDEF 
      
C***  PLOT BOXLINES
      PX=(B(3)-B(2))*B(1)
      PY=(C(3)-C(2))*C(1)
C***  NO BOXLINES, TICKMARKS AND THEIR DESCRIPTIONS IF NOBOX = TRUE
      IF (NOBOX) GOTO 100
C***  Box is drawn with thicker line
      CALL PEN (LASTPEN+2, IDEV)
      CALL GPLOT (0., 0., 3)
      CALL GPLOT (0., PY, 2)
      CALL GPLOT (PX, PY, 2)
      CALL GPLOT (PX, 0., 2)
      CALL GPLOT (0., 0., 2)
      CALL PEN (LASTPEN, IDEV)

C***  PLOT TICK MARKS  *************************************************
      EPS=1.E-3
      IF (NOTICK2Y) GOTO 10

C***  LEFT Y-AXIS ...............................
      L1=NINT((C(2)-C(6))/C(4))
      L2=NINT((C(3)-C(6))/C(4))

C***  NDEC GIVES THE NUMBER OF NON-ZERO DECIMALS WHICH MAY OCCUR BEHIND
C***     THE DECIMAL POINT
      CALL FINDNDEC (C(5), C(6), NDEC)
      TLMAX = .0

      DO 1 L=L1,L2
      VALUE=C(6)+L*C(4)
      Y1=(VALUE-C(2))*C(1)
C***  TICK MARK OUTSIDE BOX?
      IF (Y1. LT. -EPS .OR. Y1 .GT. PY+EPS) GOTO 1
      X1=0.2
C*** IS THIS A LONG TICK MARK?
      DIFF=L*C(4)/C(5)
      IF (ABS(DIFF-FLOAT(NINT(DIFF))) .LT. EPS) THEN
         X1=0.4

C***     VALUE DESCRIPTION - DEFINE FORMAT STRING
         VMIN = ABS(C(6) + L1 * C(4))
         VMAX = ABS(C(6) + L2 * C(4))
         IF (VMIN .GE. 1.E5 .OR. VMAX .GE. 1.E5 .OR.
     >       VMIN .LE. 1.E-5 .AND. VMAX .LE. 1.E-5) THEN
               FORMSTR='(1PG9.2)'
            ELSE
               WRITE (FORMSTR, '(A,I1,A)') '(F9.', NDEC, ')'
            ENDIF

      WRITE (NUMSTR,FORMSTR) VALUE

C***  POSITIONING OF THE DESCRIPTIVE STRINGS

C***  OMIT DECIMAL POINT AT THE LAST DIGIT
      IF (NUMSTR(9:9) .EQ. '.') NUMSTR(9:9) = ' '
C***  Flushleft
      DO I=1, 8
         IF (NUMSTR(1:1) .EQ. ' ') NUMSTR = NUMSTR(2:)
      ENDDO

C***  ESTIMATE LENGTH OF THE STRING
      CALL MYTLEN (TEXLEN, SIZELET, NUMSTR, IDX(NUMSTR))

C***  KEEP MAXIMUM VALUE
      TLMAX = AMAX1(TLMAX, TEXLEN)

C         WRITE (NUMSTR,FORMSTR) VALUE

c     if MAXIND (y) set: extra indent
      if ( L .EQ. L2 .AND. NOMINMAX(8)) then
       yoffset = 0.45
c     if MINDIND (y) set: extra indent
      elseif (L .EQ. L1 .AND. NOMINMAX(7)) then
        yoffset = -.05 
      else
       yoffset = 0.2
      endif
 
c     don't plot YMIN label if NOYMIN set
c     don't plot YMAX label if NOYMAX set
      IF (.NOT. NOLABY) THEN
        IF ((L .NE. L1 .OR. .NOT. NOMINMAX(3))
     >        .AND. (L .NE. L2 .OR. .NOT. NOMINMAX(4)) ) then
           IF (ALTY) THEN
              XPOS = 0.5 * SIZEFAC + PX
           ELSE
              XPOS = -TEXLEN-0.5*SIZEFAC
           ENDIF
           if (L .EQ. L2 .AND. NOMINMAX(10)) then
              CALL MYSYMBL (XPOS, Y1-yoffset*SIZEFAC, 
     >                SIZELET, NUMSTR, 0.)
           else
              CALL MYSYMBL (XPOS, MIN(Y1-yoffset*SIZEFAC, 
     >               (C(3)-C(2))*C(1)-SIZELET), SIZELET, NUMSTR, 0.)
           endif
          endif
         ENDIF
         
      ENDIF

      IF (ABS(Y1) .LT. EPS .OR. ABS(Y1-PY) .LT. EPS) GOTO 1
      IF (.NOT. (NOTICKY .AND. ALTY)) THEN
        CALL GPLOT (0., Y1, 3)
        CALL GPLOT (X1*TICFAC, Y1, 2)
      ENDIF
    1 CONTINUE

C***  RIGHT Y-AXIS  ...................................
C***    TICK MARKS MAY BE SUPPRESSED:
      IF ((NOTICKY .AND. .NOT. ALTY) .OR. NOTICK2Y) GOTO 10

      L1=NINT((C(2)-C(6))/C(4))
      L2=NINT((C(3)-C(6))/C(4))
      DO 2 L=L1,L2
      VALUE=C(6)+L*C(4)
      Y1=(VALUE-C(2))*C(1)
C***  TICK MARK OUTSIDE BOX?
      IF (Y1. LT. -EPS .OR. Y1 .GT. PY+EPS) GOTO 2
      X1=0.2
C***  IS THIS A LONG TICK MARK?
      DIFF=L*C(4)/C(5)
      IF (ABS(DIFF-FLOAT(NINT(DIFF))) .LT. EPS) THEN
         X1=0.4
      ENDIF

      IF (ABS(Y1) .LT. EPS .OR. ABS(Y1-PY) .LT. EPS) GOTO 2
      CALL GPLOT (PX, Y1, 3)
      CALL GPLOT (PX-X1*TICFAC, Y1, 2)
    2 CONTINUE
   10 CONTINUE
   
C***  L0WER X-AXIS  ................................
      L1=NINT((B(2)-B(6))/B(4))
      L2=NINT((B(3)-B(6))/B(4))

C***  NDEC GIVES THE NUMBER OF NON-ZERO DECIMALS WHICH MAY OCCUR BEHIND
C***     THE DECIMAL POINT
      CALL FINDNDEC (B(5), B(6), NDEC)

      DO 3 L=L1,L2
      VALUE=B(6)+L*B(4)
      X1=(VALUE-B(2))*B(1)
C***  TICK MARK OUTSIDE BOX?
      IF (X1. LT. -EPS .OR. X1 .GT. PX+EPS .OR. NOTICK2X) GOTO 3
      Y1=0.2
C***  IS THIS A LONG TICK MARK?
      DIFF=L*B(4)/B(5)
      IF (ABS(DIFF-FLOAT(NINT(DIFF))) .LT. EPS) THEN
         Y1=0.4

C***     VALUE DESCRIPTION - DEFINE FORMAT STRING
         VMIN = ABS(B(6) + L1 * B(4))
         VMAX = ABS(B(6) + L2 * B(4))
         IF (VMIN .GE. 1.E5 .OR. VMAX .GE. 1.E5 .OR.
     >       VMIN .LE. 1.E-5 .AND. VMAX .LE. 1.E-5) THEN
            FORMSTR='(1PG9.2)'
         ELSE
            WRITE (FORMSTR, '(A,I1,A)') '(F9.', NDEC, ')'
         ENDIF

         WRITE (NUMSTR,FORMSTR) VALUE

C***     CENTERING OF THE DESCRIPTIVE STRINGS

C***     OMIT DECIMAL POINT AT THE LAST DIGIT
         IF (NUMSTR(9:9) .EQ. '.') NUMSTR(9:9) = ' '
C***     Flushleft
         DO I=1, 8
            IF (NUMSTR(1:1) .EQ. ' ') NUMSTR = NUMSTR(2:)
         ENDDO

C***     ESTIMATE LENGTH OF THE STRING
         CALL MYTLEN (TEXLEN, SIZELET, NUMSTR, IDX(NUMSTR))

C***     ESTIMATE OFFSET IN X RELATIVE TO THE TICK MARK
         OFFSET = 0.5 * TEXLEN
C***     AT THE RIGHT Y-AXIS, THE DESCRIPTION SHALL NOT STAND OUT
         if (NOMINMAX(6)) then
            IF (X1 + TEXLEN - OFFSET .GT. PX) 
     >         OFFSET = X1 - PX + 1.25*TEXLEN
         elseif (.NOT. NOMINMAX(9)) then 
            IF (X1 + TEXLEN - OFFSET  .GT. PX) 
     >         OFFSET = X1 - PX + TEXLEN
         endif

c        at the left y-axis, the description shall not stand out
         if (NOMINMAX(5) .AND. X1 .LE. 0) OFFSET = -0.25*TEXLEN

c     don't plot XMIN label if NOXMIN set
c     don't plot XMAX label if NOXMAX set
         IF (.NOT. NOLABX ) THEN
            IF (ALTX) THEN
               YPOS = 0.3*SIZEFAC + PY
            ELSE 
               YPOS = -0.7*SIZEFAC
            ENDIF
            if ((L .NE. L1 .OR. .NOT. NOMINMAX(1))
     >           .AND.(L .NE. L2 .OR. .NOT. NOMINMAX(2)) ) 
     >         CALL MYSYMBL (X1-OFFSET, YPOS, SIZELET, NUMSTR, 0.)
         ENDIF     
      ENDIF

      IF (ABS(X1) .LT. EPS .OR. ABS(X1-PX) .LT. EPS) GOTO 3
      IF (.NOT. (NOTICKX .AND. ALTX)) THEN
         CALL GPLOT (X1, 0., 3)
         CALL GPLOT (X1, Y1*TICFAC, 2)
      ENDIF
    3 CONTINUE

C***  UPPER X-AXIS  .........................................
C***  TICK MARKS MAY BE SUPPRESSED
      IF ((NOTICKX .AND. .NOT. ALTX) .OR. NOTICK2X) GOTO 11

      L1=NINT((B(2)-B(6))/B(4))
      L2=NINT((B(3)-B(6))/B(4))
      DO 4 L=L1,L2
      VALUE=B(6)+L*B(4)
      X1=(VALUE-B(2))*B(1)
C***  TICK MARK OUTSIDE BOX?
      IF (X1. LT. -EPS .OR. X1 .GT. PX+EPS) GOTO 4
      Y1=0.2
C***  IS THIS A LONG TICK MARK?
      DIFF=L*B(4)/B(5)
      IF (ABS(DIFF-FLOAT(NINT(DIFF))) .LT. EPS) THEN
         Y1=0.4
         ENDIF

      IF (ABS(X1) .LT. EPS .OR. ABS(X1-PX) .LT. EPS) GOTO 4
      CALL GPLOT (X1, PY, 3)
      CALL GPLOT (X1, PY-Y1*TICFAC, 2)
    4 CONTINUE
   11 CONTINUE

C***  ENTRY IF THE BOX IS SUPRESSED : NOBOX = TRUE
  100 CONTINUE

C***  Write plot HEADER
      CALL EXPANDVAR (HEADER, VAR, MAXVAR, NVAR)
      IF (ALTX) THEN
         YPOS = PY+ 2.0*SIZEFAC
      ELSE 
         YPOS = PY+0.8*SIZEFAC
      ENDIF
      IF (HEADER(1:8) .EQ. CENTER) THEN
        NCHAR = IDX(HEADER(9:)) 
        IF (NCHAR .EQ. 0) GOTO 20 
        CALL MYTLEN (TEXLEN, SIZELET, HEADER(9:), NCHAR) 
        PX2 = (PX - TEXLEN) / 2.
        CALL MYSYMBL (PX2, YPOS, SIZELET, HEADER(9:), 0.)
      ELSEIF (HEADER(1:7) .EQ. RIGHT) THEN
        NCHAR = IDX(HEADER(8:))
        IF (NCHAR .EQ. 0) GOTO 20
        CALL MYTLEN (TEXLEN, SIZELET, HEADER(8:), NCHAR)
        PX2 = PX - TEXLEN 
        CALL MYSYMBL (PX2, YPOS, SIZELET, HEADER(8:) , 0.)
      ELSE
        CALL MYSYMBL (0., YPOS, SIZELET, HEADER, 0.)
      ENDIF
   20 CONTINUE

C***  X-AXIS DESCRIPTION
      CALL EXPANDVAR (XTEXT, VAR, MAXVAR, NVAR)
      IF (ALTX) THEN
         YPOS = 1.2*SIZEFAC + PY
      ELSE 
         YPOS = -1.5*SIZEFAC
      ENDIF

      IF (XTEXT(1:8) .EQ. CENTER) THEN
        NCHAR = IDX(XTEXT(9:)) 
        IF (NCHAR .EQ. 0) GOTO 21
        CALL MYTLEN (TEXLEN, SIZELET, XTEXT(9:), NCHAR) 
        PX2 = (PX - TEXLEN) / 2.
        CALL MYSYMBL (PX2, YPOS, SIZELET, XTEXT(9:), 0.)
      ELSEIF (XTEXT(1:7) .EQ. RIGHT) THEN
        NCHAR = IDX(XTEXT(8:))
        IF (NCHAR .EQ. 0) GOTO 21
        CALL MYTLEN (TEXLEN, SIZELET, XTEXT(8:), NCHAR)
        PXE=PX - TEXLEN 
        CALL MYSYMBL (PXE, YPOS, SIZELET, XTEXT(8:) , 0.)
      ELSE
        CALL MYSYMBL (0.,  YPOS, SIZELET, XTEXT , 0.)
      ENDIF
   21 CONTINUE

C***  Y-AXIS DESCRIPTION
      CALL EXPANDVAR (YTEXT, VAR, MAXVAR, NVAR)
      IF (ALTY) THEN
         XPOS = TLMAX +1.2*SIZEFAC + PX
      ELSE 
         XPOS = -TLMAX-0.8*SIZEFAC   
      ENDIF
      IF (YTEXT(1:8) .EQ. CENTER) THEN
        NCHAR = IDX(YTEXT(9:)) 
        IF (NCHAR .EQ. 0) GOTO 22
        CALL MYTLEN (TEXLEN, SIZELET, YTEXT(9:), NCHAR) 
        PY2 = (PY - TEXLEN) / 2.
        CALL MYSYMBL (XPOS, PY2, SIZELET, YTEXT(9:), 90.)
      ELSEIF (YTEXT(1:4) .EQ. UP) THEN
        NCHAR = IDX(YTEXT(5:))
        IF (NCHAR .EQ. 0) GOTO 22
        CALL MYTLEN (TEXLEN, SIZELET, YTEXT(5:), NCHAR)
        PYE = PY - TEXLEN 
        CALL MYSYMBL (XPOS, PYE , SIZELET, YTEXT(5:), 90.)
      ELSE
        CALL MYSYMBL (XPOS, 0.  , SIZELET, YTEXT , 90.)
      ENDIF

   22 CONTINUE

      RETURN

      END
plotdat.f/      1558086570  5006  320   100644  17580     `
      SUBROUTINE PLOTDAT (X, Y, NDAT, ISYMBOL, SSIZE, XCM, YCM, B, C, T, 
     >                    COORD, VAR, MAXVAR, NVAR, STRIP, ICOLOR
     >                    , DATASETLINE)
C*******************************************************************
C***  PLOT OF ONE SET OF X-Y-DATA
C***  CALLED BY MAIN PROGRAMM WRPLOT AND
C***  FROM SUBROUTINE KDPLOT (SYMBOL 1, 2, 3, 4, 8, 11 ... 17)
C*******************************************************************

      LOGICAL FSTEP, SAMEDAT, EXISTVAR
      CHARACTER COORD*4
      DIMENSION X(NDAT), Y(NDAT), XCM(NDAT), YCM(NDAT), T(NDAT)
      DIMENSION B(6), C(6)
      DIMENSION STRIP(2)
      COMMON / COMIDEV / IDEV 

      CHARACTER*(*) VAR(MAXVAR,2)
      CHARACTER*80 ACTPAR
      CHARACTER*80 ACTPAR2
      CHARACTER*(*) DATASETLINE
      LOGICAL BHATCH

C***  ACTIVE GRAPHIC DRIVER
      COMMON / COMACT / ACTDRIV
      CHARACTER ACTDRIV*7

      DATA PI / 3.1415927 /

C***  Sanity check for number of data in current dataset
      IF (NDAT .LT. 0) THEN
         WRITE (*,*) '*** NDAT NEGATIVE!' 
         STOP '*** INTERNAL FATAL ERROR in SUBR. PLOTDAT'
      ENDIF 

C***  IF DATASET IS EMPTY, SKIP THE REST OF THIS SUBROUTINE 
      IF (NDAT .EQ.  0) RETURN    

C***  SYMBOL=0 : Dataset not plotted at all
      IF (ISYMBOL .EQ. 0) RETURN

C***  CHECK DATASETLINE FOR HATCHING OPTIONS:
      BHATCH=.FALSE.      
      CALL SARGC (DATASETLINE, NARG)
      DO I=1, NARG
         CALL SARGV (DATASETLINE, I, ACTPAR) 
         IF (ACTPAR .EQ. 'HATCHED' .OR. ACTPAR .EQ. 'HTYPE') THEN
            BHATCH=.TRUE.
         ENDIF
      ENDDO


C**********************************************************************
C***           CONVERSION INTO CENTIMETER UNITS                     ***
C***             - IGNORE CONSECUTIVE IDENTICAL DATA-POINTS         ***
C**********************************************************************
      N = 0
      DO 19 I = 1, NDAT
      SAMEDAT= .FALSE.
      IF (I .GT. 1) 
     >   SAMEDAT = X(I) .EQ. X(I-1) .AND. Y(I) .EQ. Y(I-1)
      IF (.NOT. SAMEDAT) THEN
          N = N + 1
          IF (COORD .EQ. 'UNIT') THEN
            XCM(N) = (X(I)-B(2)) * B(1)
            YCM(N) = (Y(I)-C(2)) * C(1)
          ELSE IF (COORD .EQ. 'CM') THEN
            XCM(N) = X(I)
            YCM(N) = Y(I)
          ELSE
            WRITE (*,*) 'SUBROUTINE PLOTDAT: COORD=',COORD
            STOP 'ERROR IN PLOTDAT'
          ENDIF
      ENDIF
   19 CONTINUE

C*** IF POSTSCRIPT: Option to fill Areas (if SYMBOLSIZE .lt. .0)
      IF ((ISYMBOL .EQ. 5 .OR. ISYMBOL .EQ. 6)
     >     .AND. IDEV .EQ. 3 .AND. (SSIZE .LT. .0 .OR. BHATCH)) THEN
        IF (ACTDRIV .EQ. 'CALCOMP') THEN
           STOP 'ERROR IN PLOTDAT: CALCOMP DRIVER DISABLED'
c           CALL NEWPEN (1)
c           CALL NEWPEN (3)
c           WRITE (3, '(A)') 'stroke'
c           WRITE (3, '(A)') 'newpath'
           ENDIF
        ENDIF

   77 CONTINUE


C***  SYMBOLS SUPPLIED BY OUR OWN
      IF ((ISYMBOL .GT. 0 .AND. ISYMBOL .LE. 4) .OR. 
     >     ISYMBOL .EQ. 8
     >    .OR. (ISYMBOL .GE. 11 .AND. ISYMBOL .LE. 18) 
     >    .OR. (ISYMBOL .GE. 26 .AND. ISYMBOL .LE. 27)
     >    .OR. ISYMBOL .EQ. 29
     >    .OR. ISYMBOL .EQ. 30
     >    .OR. ISYMBOL .EQ. 33
     >    ) THEN
        CALL CENSYMO (XCM, YCM, ISYMBOL, SSIZE, N, DATASETLINE)

C***  CUBIC INTERPOLATION (LAGRANGE POLYNOMIAL) ************************
      ELSE IF (ISYMBOL .EQ. 6 .OR. ISYMBOL .EQ. 7 .OR. 
     >         ISYMBOL .EQ. 19) THEN

C***     IF ONLY ONE DATA-POINT GOTO PLOTSYMBOL 0
         IF (N .EQ. 1) THEN
           ISYMBOL = 0
           GOTO 77
         ENDIF

C***     IF ONLY TWO DATA-POINTS, THEN INSERT A THIRD ONE
         IF (N .EQ. 2) THEN
           N = N + 1
           XCM(3) = XCM(2)
           YCM(3) = YCM(2)
           XCM(2) = 0.5 * (XCM(1) + XCM(3))
           YCM(2) = 0.5 * (YCM(1) + YCM(3))
         ENDIF

C***     CHECK OF MONOTONIC ORDER
         IF (ISYMBOL .EQ. 19) GOTO 55
         DO 6 I=2,N-1
         IF ((XCM(I)-XCM(I-1))*(XCM(I+1)-XCM(I)) .LE. .0) GOTO 55
    6    CONTINUE
C***  NOTE: Interpolation for Curves is now standard ==> GOTO 55
         GOTO 55

         IDOWN=3
         STEP = ABS(SSIZE)
C***  To avoid too small steps
         IF (STEP .LT. 1.E-4) THEN
           STEP = 1.E-4
         ENDIF
         IF (XCM(N) .LE. XCM(1)) STEP=-STEP
         XX=XCM(1)
         I=2
         CALL GCPLOT (XX, YCM(1), 3)

C***     LOOP ***
    7    CONTINUE
C***     Estimate the derivative at xx (old point)
C***     First find the index intervall (i-1, i)
    8    IF ((XX-XCM(I-1))*STEP .GT. .0 .AND. I.LT.N) THEN
            I=I+1
            GOTO 8
            ENDIF

         DFDX = (YCM(I)-YCM(I-1))/(XCM(I)-XCM(I-1))
         DX = STEP/SQRT(1.+DFDX*DFDX)

         XX=XX+DX
         IF ((XX-XCM(N))*STEP .GT. .0) XX=XCM(N)
C***     NOTE: LAGRANGE INTERPOLATION REPLACED BY QUASI-SPLINES (19-JULY-90)
C!!!        CALL FCUBIC (FX,XX,YCM,XCM,N)
         CALL FSPLINE (FX, XX, YCM, XCM, N)
C ***    WARNING: MISTERY MISTAKE!!!  ( 2-JUN-1992 14:48:12 )
C!!!         CALL CUBIC (FX, XX, YCM, XCM, I, N, .TRUE.)
         IF (IDOWN .EQ. 2 .AND. ISYMBOL .EQ. 7) THEN
            IDOWN=3
            ELSE
            IDOWN=2
            ENDIF
         CALL GCPLOT (XX,FX,IDOWN)
C        XX=XX+STEP
         IF ((XX-XCM(N))*STEP .LT. .0) GOTO 7
         GOTO 56

C***  BRANCH FOR CUBIC INTERPOLATION OF CURVES (NOT FUNCTIONS!)
   55    CONTINUE
C***  DEFINE PARAMETER VECTOR (PATH LENGTH)
      T(1) = .0
      DXX = 0.
      DYY = 0.
      DO I=2, N
        DX = XCM(I) - XCM(I-1)
        DY = YCM(I) - YCM(I-1)
        XL = SQRT (DX*DX + DY*DY)
        T(I) = T(I-1) + XL
      ENDDO
      IF (ISYMBOL .EQ. 19) THEN
c        ACTPAR = '$DS_WIDTHS19'
c        CALL INQVAR(ACTPAR, VAR, MAXVAR, NVAR)
c        IF (ACTPAR .EQ. 'TRUE') THEN
c          ACTPAR = '$DS_WIDTHS19'
c          CALL DECVAR(ACTPAR, VAR, MAXVAR, NVAR)
c          READ (ACTPAR,'(F20.0)') OMEGA
c          OMEGA = 2. * PI / OMEGA
c        ELSE
c          OMEGA = 2. * PI / 0.5
c        ENDIF

         OMEGA = 0.6 * PI / ABS(SSIZE)
c         SSIZE = ABS(SSIZE)/ 12
         SSIZE = SSIZE / 12
      ENDIF

      IDOWN=3
      STEP = ABS(SSIZE)
C***  To avoid too small steps
      IF (STEP .LT. 1.E-4) THEN
        STEP = 1.E-4
      ENDIF
      TT = .0
      CALL GCPLOT (XCM(1), YCM(1), 3)
      I = 1
   61 TT = TT + STEP
C***  Find valid Intervall I,I+1
      IF (TT .GT. T(I)) THEN
        I = I + 1
      ENDIF
      IF (TT .LE. T(N)) THEN
         CALL FSPLINE (XX, TT, XCM, T, N)
         CALL FSPLINE (YY, TT, YCM, T, N)
         IF (IDOWN .EQ. 2 .AND. ISYMBOL .EQ. 7) THEN
            IDOWN=3
         ELSE
            IDOWN=2
         ENDIF
         IF (ISYMBOL .EQ. 19) THEN
           CALL FSPLINE(DXDT, TT-STEP, XCM, T, N)
           DXDT = (XX - DXDT) / STEP
           CALL FSPLINE(DYDT, TT-STEP, YCM, T, N)
           DYDT = (YY - DYDT) / STEP
c           write (*,*) 'ableitung:', dxdt, dydt, step
           XL = SQRT (DXDT*DXDT + DYDT*DYDT)
           DXDT = DXDT / XL
           DYDT = DYDT / XL
           DXX = 1./OMEGA * (-DYDT) * SIN(OMEGA*TT)
           DYY = 1./OMEGA *   DXDT  * SIN(OMEGA*TT)
c           write (*,*) '=======', xnx(2), dxx, dyy
         ENDIF
         CALL GCPLOT (XX+DXX, YY+DYY, IDOWN)
         GOTO 61
        ELSE
         IF (IDOWN .EQ. 2 .AND. ISYMBOL .EQ. 7) THEN
            IDOWN=3
         ELSE
            IDOWN=2
         ENDIF
         IF (ISYMBOL .NE. 19) THEN
           CALL GCPLOT (XCM(N), YCM(N), IDOWN)
         ENDIF
        ENDIF
      
   56    CONTINUE

C***  LINEAR INTERPLOATION DASHED PLOTSYMBOL 9 AND 10  *****************
CMARKE
      ELSE IF (ISYMBOL .EQ. 9 .OR. ISYMBOL .EQ. 10 .OR.
     >         ISYMBOL .EQ. 20) THEN
         IF (SSIZE .GT. 0.) THEN
           STEP = SSIZE
         ELSE
           STEP = 0.2
         ENDIF
C***    RSTEP IS THE REAL STEP WHICH IS DONE
C***    RSTEP CHANGES BETWEEN STEP STEP/4 (IYMBOL=10) AND 
C***      2*STEP (ISYMBOL=20)
           RSTEP = STEP
           XL = 0.
           IDOWN = 2
           FSTEP = .FALSE.
           CALL GCPLOT (XCM(1), YCM(1), 3)
C***    XX AND YY : POSITION OF THE PLOTTER
           XX = XCM(1)
           YY = YCM(1)
           I = 1
C***     LOOP -----------------------------------
    9    CONTINUE
C***     D : DISTANCE TO NEXT POINTS OF THE DATA-SET
             D = SQRT ( (XX - XCM(I))**2 + (YY - YCM(I))**2 )
             IF (XL + D .LT. RSTEP) THEN
C***     POSSIBLE TO REACH NEXT POINTS OF DATASET WITHOUT CHANGING IDOWN
                XX = XCM(I)
                YY = YCM(I)
                IF (ISYMBOL .NE. 20) THEN
                  CALL GCPLOT (XX, YY, IDOWN)
                ELSE
C***  Only the short lines are plotted for dotted line
                  IF (.NOT. FSTEP) THEN
                    CALL GCPLOT (XX, YY, IDOWN)
                  ELSE
                    CALL GCPLOT (XX, YY, 3)
                  ENDIF
                ENDIF
                XL = XL + D
                I = I + 1
             ELSE
C***     CHANGE OF IDOWN IS NECESSARY
                D1 = SQRT ( (XCM(I-1) - XCM(I))**2 
     >                    + (YCM(I-1) - YCM(I))**2 )
                XX = XX + (XCM(I) - XCM(I-1)) * (RSTEP - XL)/D1
                YY = YY + (YCM(I) - YCM(I-1)) * (RSTEP - XL)/D1
                XL = 0.
                IF (ISYMBOL .NE. 20) THEN
                  CALL GCPLOT (XX, YY, IDOWN)
                ELSE
C***  Only the short lines are plotted for dotted line
                  IF (.NOT. FSTEP) THEN
                    CALL GCPLOT (XX, YY, IDOWN)
                  ELSE
                    CALL GCPLOT (XX, YY, 3)
                  ENDIF
                ENDIF
                IF ( IDOWN .EQ. 2 ) THEN
                   IDOWN = 3
                   RSTEP = STEP
                ELSE
                   IDOWN = 2
                   IF (ISYMBOL .EQ. 10 .OR. ISYMBOL .EQ. 20) THEN
                     IF (FSTEP) THEN
                         RSTEP = STEP 
                       ELSE
                         IF (ISYMBOL .EQ. 10) THEN
                           RSTEP = STEP / 4.
                         ELSE
                           RSTEP = STEP * 2.
                         ENDIF
                     ENDIF               
                     FSTEP = .NOT. FSTEP
                   ENDIF
                ENDIF
             ENDIF
         IF ( I .LE. N ) GOTO 9

C***  POLYGON WITH TRIANGLES, CIRCLES ETC
      ELSE IF (ISYMBOL .GE. 21 .AND. ISYMBOL .LE. 25 .OR. 
     >         ISYMBOL .EQ. 28 .OR.
     >         ISYMBOL .GE. 31 .AND. ISYMBOL .LE. 32) THEN

C***  TRANSLATE ISYMBOL
        IF (ISYMBOL .EQ. 25) THEN
          ISY = 11
        ELSE
          ISY = ISYMBOL - 20
        ENDIF

        IDUMMY = 1

C***  CALCULATE DISTANCE BETWEEN TWO SYMBOLS (STEP) AND THEIR SIZE (SSIZE2)
        IF (SSIZE .EQ. 0.) THEN
          SSIZE = 1.0
        ENDIF
        STEP = ABS (SSIZE)
        SSIZE2 = SSIZE / 3.
        IF (ISYMBOL .EQ. 23) THEN
          SSIZE2 = SSIZE2 * 1.2
        ENDIF

C***  PLOT SOLID LINE AND CALCULATE TOTAL LENGTH
C***  LENGTH OF LINE IS STORED IN XL
        XL = 0.
        CALL GCPLOT (XCM(1), YCM(1), 3)
        DO 40 I=2,N
          D = SQRT ( (XCM(I-1) - XCM(I))**2 + (YCM(I-1) - YCM(I))**2 )
          XL = XL + D
          CALL GCPLOT (XCM(I), YCM(I), 2)
   40   CONTINUE

C***  SET FIRST SYMBOL WETHER LENGTH OF LINE IS GREATER THAN DISTANCE
C***  BETWEEN TWO SYMBOLS OR NOT
        IF (XL .LT. STEP) THEN
          XL = STEP - XL/2.
        ELSE
          XL = STEP/2.
        ENDIF

        XX = XCM(1)
        YY = YCM(1)
        I = 1

C***  LOOP --------------------
   45   CONTINUE
          D = SQRT ( (XX - XCM(I))**2 + (YY - YCM(I))**2 )
          IF (XL+D .LT. STEP) THEN
C***  NEXT SYMBOL NOT BETWEEN POINT I AND POINT I-1
            XX = XCM(I)
            YY = YCM(I)
            XL = XL + D
            I = I + 1
          ELSE
            D1 = SQRT ( (XCM(I-1) - XCM(I))**2 
     >                + (YCM(I-1) - YCM(I))**2 )
            XX = XX + (XCM(I) - XCM(I-1)) * (STEP - XL)/D1
            YY = YY + (YCM(I) - YCM(I-1)) * (STEP - XL)/D1
            XL = 0.
            CALL CENSYMO (XX, YY, ISY, SSIZE2, IDUMMY,' ')
          ENDIF
        IF (I .LE. N) GOTO 45

C***  Color-Coding of the Y-Value
C***  The Y-position must be specified by COMMAND STRIP y1 y2 
      ELSE IF (ISYMBOL .EQ. 40) THEN
         Y1CM = (STRIP(1)-C(2)) * C(1)
         Y2CM = (STRIP(2)-C(2)) * C(1)
C***  Minimum and Maximum Value may be defined by global variables
C***    MIN_COL, MAX_COL
         ACTPAR='$MIN_COL'
         CALL CHECKVAR(ACTPAR, VAR, MAXVAR, NVAR, EXISTVAR)
         IF (EXISTVAR) THEN
            CALL DECVAR(ACTPAR, VAR, MAXVAR, NVAR)
            READ (ACTPAR,'(F20.0)') COLMIN
            COLMIN = (COLMIN-C(2)) * C(1)
         ELSE
            COLMIN = YCM(1)
            DO I=2, N
              COLMIN = AMIN1 (COLMIN, YCM(I))
            END DO
         ENDIF
         ACTPAR='$MAX_COL'
         CALL CHECKVAR(ACTPAR, VAR, MAXVAR, NVAR, EXISTVAR)
         IF (EXISTVAR) THEN
            CALL DECVAR(ACTPAR, VAR, MAXVAR, NVAR)
            READ (ACTPAR,'(F20.0)') COLMAX
            COLMAX = (COLMAX-C(2)) * C(1)
         ELSE
            COLMAX = YCM(1)
            DO I=2, N
              COLMAX = AMAX1 (COLMAX, YCM(I))
            END DO
         ENDIF
C***  Code Y-Value into RGB-Colors
         DO I=1, N
            CALL COLORTABLE (RCOLOR, GCOLOR, BCOLOR, YCM(I), 
     >                       COLMIN, COLMAX, ICOLOR)
            IF (ACTDRIV .EQ. 'PSOWN') THEN
               CALL PS_NEWCOLOR (RCOLOR, GCOLOR, BCOLOR)
            ELSE IF (ACTDRIV .EQ. 'X11OWN') THEN
               CALL X_NEWCOLOR (RCOLOR, GCOLOR, BCOLOR)
            ENDIF
            IF (I .EQ. 1) THEN 
              X1CM = XCM(1)
            ELSE
              X1CM = 0.5 * (XCM(I-1)+XCM(I))
            ENDIF
            IF (I .EQ. N) THEN 
              X2CM = XCM(N)
            ELSE
              X2CM = 0.5 * (XCM(I+1)+XCM(I))
            ENDIF
            CALL GCPLOT (X1CM, Y1CM, 3)
            CALL GCPLOT (X2CM, Y1CM, 2)
            CALL GCPLOT (X2CM, Y2CM, 2)
            CALL GCPLOT (X1CM, Y2CM, 2)
            CALL GCPLOT (X1CM, Y1CM, 2)
            CALL GFILL
         END DO

      ELSE IF (ISYMBOL .EQ. 35) THEN
C***  HISTOGRAM (FULL LINE)
C***     Monotonic order recommended 
         IF (X(N)-X(1) .GT. .0) THEN
            XSIGN = 1.
         ELSE IF (X(N)-X(1) .LT. .0) THEN
            XSIGN = -1.
         ENDIF
         DO I=2,N
            IF ((XCM(I)-XCM(I-1)) * XSIGN .LT. .0) THEN 
               WRITE (*, '(/,A)') '***  WARNING: NON-MONOTONIC '
     >              // 'ORDER MIGHT CAUSE SPURIOUS HISTOGRAM!'
              EXIT
            ENDIF
         ENDDO
 
         CALL GCPLOT (XCM(1), YCM(1), 3)
         DO I=2, N
            XM = 0.5 * (XCM(I-1) + XCM(I))         
            CALL GCPLOT (XM, YCM(I-1), 2)
            CALL GCPLOT (XM, YCM(I  ), 2)
         ENDDO 
         CALL GCPLOT (XCM(N), YCM(N), 2)

      ELSE IF (ISYMBOL .EQ. 36) THEN
C***  HISTOGRAM (DASHED LINE) ***************************************
C***     Monotonic order recommended 
         IF (X(N)-X(1) .GT. .0) THEN
           XSIGN = 1.
         ELSE IF (X(N)-X(1) .LT. .0) THEN
           XSIGN = -1.
         ENDIF
         DO I=2,N
            IF ((XCM(I)-XCM(I-1)) * XSIGN .LT. .0) THEN 
               WRITE (*, '(/,A)') '***  WARNING: NON-MONOTONIC '
     >              // 'ORDER MIGHT CAUSE SPURIOUS HISTOGRAM!'
              EXIT
            ENDIF
         ENDDO
 
         IF (SSIZE .NE. 0.) THEN
            STEP = AMAX1(ABS(SSIZE), 0.001)
         ELSE
            STEP = 0.2
         ENDIF
         IDOWN = 2
         REST = STEP
         XLAST = XCM(1)
         CALL GCPLOT (XLAST, YCM(1), 3) 
         DO I=2, N
            XM = 0.5 * (XCM(I-1) + XCM(I))         
   60       IF (XSIGN*XLAST + REST .LT. XSIGN*XM) THEN 
               XLAST = XLAST + XSIGN*REST
               CALL GCPLOT (XLAST, YCM(I-1), IDOWN) 
               IDOWN = IDOWN - NINT(2*(FLOAT(IDOWN)-2.5))
               REST=STEP
               GOTO 60
            ENDIF
            CALL GCPLOT (XM, YCM(I-1), IDOWN)
            REST = REST - XSIGN*(XM-XLAST)
            XLAST = XM
ccc senkrechter Strich
            IF (YCM(I) .GT. YCM(I-1)) THEN
              YSIGN=1.
            ELSE
              YSIGN=-1.
            ENDIF
            YLAST = YCM(I-1)
   62       IF (YSIGN*YLAST+REST .LT. YSIGN*YCM(I)) THEN 
               YLAST = YLAST + YSIGN*REST
cc               IF (REST .EQ. STEP) 
               CALL GCPLOT (XM, YLAST, IDOWN) 
               IDOWN = IDOWN - NINT(2*(FLOAT(IDOWN)-2.5))
              REST=STEP
              GOTO 62
            ENDIF
            CALL GCPLOT (XM, YCM(I  ), IDOWN)
            REST = REST - YSIGN*(YCM(I)-YLAST)
         ENDDO 
         CALL GCPLOT (XCM(N), YCM(N), 2)

C***  LINEAR INTERPOLATION CURVE  (DEFAULT FOR INVALID ISYMBOL!) ******
      ELSE 
      IF (ISYMBOL .NE. 5) WRITE (6,'(/,A)') 
     >          'INVALID CHOICE OF PLOTSYMBOL REPLACED BY SYMBOL=5'
         CALL GCPLOT (XCM(1), YCM(1), 3)
         DO 5 I=2,N
    5    CALL GCPLOT (XCM(I), YCM(I), 2)
      ENDIF

C*** IF POSTSCRIPT: Option to fill Areas (if SYMBOLSIZE .lt. .0)
      IF ((ISYMBOL .EQ. 5 .OR. ISYMBOL .EQ. 6 .OR. ISYMBOL .EQ. 35
     >     .OR. ISYMBOL .EQ. 19)
     >     .AND. (IDEV .EQ. 3 .OR. ACTDRIV .EQ. 'X11OWN') ) THEN
          IF (SSIZE .LT. .0) THEN
             CALL GFILL
          ELSEIF (BHATCH) THEN
             CALL HFILL(DATASETLINE)
          ENDIF
      ENDIF

      RETURN
      END
ppp.f/          1553528659  5006  320   100644  4349      `
      SUBROUTINE PPP 
C******************************************************************
C***  PRAEZISIONS-PRAEZESSIONS-PROGRAMM 
C***  (new, interactive version)
C******************************************************************

      DATA PI,P,Q /3.141592654, 46.085, 20.047 /
      CHARACTER*80 LINE, ACTPAR, IDGCHAR*3
      LOGICAL BSOUTH, CHRINSTR

C***  INQUIRE INTERACTIVELY THE EPOCHS:

      PRINT 10
   10 FORMAT (/////, 1X, 60('*'), /, 
     >        ' Praezisions-Praezessions-Programm:', /, 1X, 60('*'), //, 
     >        'ENTER EPOCH IN WHICH COORDINATES ARE GIVEN:')
   11 READ (*,*,ERR=90) E1

      PRINT *, 'ENTER EPOCH FOR WHICH COORDINATES SHALL BE CALCULATED:'
   12 READ (*,*,ERR=91) E2

      DE = E2 - E1

   13 PRINT *, ' GIVE COORDINATES:  RA, DECL' 
      PRINT *, ' h m s   deg arcmin arcsec'  
     >         ,'   --- 6 values, arbitrary separators'  
      READ (*, '(A)') LINE

      CALL SARGC (LINE, NPAR)
      IF (NPAR .LT. 6) GOTO 92 

      CALL SARGV (LINE, 1, ACTPAR)

C***  input line is assumed to contain coordinates
      CALL SARGV (LINE, 1, ACTPAR)
      READ (ACTPAR(1:IDX(ACTPAR)), '(I3)', ERR=93) IRAH
      IF (IRAH .LT. 0 .OR. IRAH .GT. 24) GOTO 93

      CALL SARGV (LINE, 2, ACTPAR)
      READ (ACTPAR(1:IDX(ACTPAR)), '(I3)', ERR=94) IRAM
      IF (IRAM .LT. 0 .OR. IRAM .GT. 60) GOTO 94

      CALL SARGV (LINE, 3, ACTPAR)
      READ (ACTPAR(1:IDX(ACTPAR)), '(F6.0)', ERR=95) RAS
      IF (RAS .LT. .0 .OR. RAS .GT. 60.) GOTO 95

      CALL SARGV (LINE, 4, ACTPAR)
      READ (ACTPAR(1:IDX(ACTPAR)), '(I3)', ERR=96) IDG
      IF (IDG .LT. -90. .OR. IDG .GT. 90) GOTO 96
      IDGCHAR = ACTPAR
      BSOUTH = CHRINSTR ('-', ACTPAR) 

      CALL SARGV (LINE, 5, ACTPAR)
      READ (ACTPAR(1:IDX(ACTPAR)), '(I3)', ERR=97) IDM
      IF (IDM .LT. 0 .OR. IDM .GT. 60) GOTO 97

      CALL SARGV (LINE, 6, ACTPAR)
      READ (ACTPAR(1:IDX(ACTPAR)), '(F6.0)', ERR=98) DS
      IF (DS .LT. .0 .OR. DS .GT. 60.) GOTO 98

C**   Print input coordinates:
      WRITE (*,'(50(1H-))')
      IF (IDGCHAR(3:3) .EQ. ' ') IDGCHAR = ' ' // IDGCHAR(1:2)
      WRITE (*,6) E1, IRAH, IRAM, RAS, IDGCHAR, IDM, DS

C***  Vorzeichenuebertrag der Deklination
      IF (BSOUTH) IDM = -IDM
      IF (BSOUTH) DS  = -DS

C***  Umwandlung von Alpha und Delta in Bogenmass 
      ALPHA = (FLOAT(IRAH * 3600 + IRAM * 60) + RAS) * PI/ 12./3600.
      DELTA = (FLOAT(IDG  * 3600 + IDM  * 60) + DS ) * PI/180./3600.
  
C***  PRECESSION FORMULA (FROM VOIGT, ABRISS DER ASTRONOMIE)
      DA = DE*(P+Q*TAN(DELTA)*SIN(ALPHA))/15.
      DD = DE*Q*COS(ALPHA)
 
C RUECKWANDLUNG IN SEKUNDEN BZW. BOGENSEKUNDEN
      ALPHA = ALPHA*43200./PI
      DELTA = DELTA*648000./PI
 
C***  Addition der Praezessions-Korrektur
      ALPHA = ALPHA+DA
      DELTA=DELTA+DD

C***  Rueckwandlung RA in Stunden und Minuten
      IRAM  = INT(ALPHA/60)
      RAS = ALPHA - 60.*IRAM
      IRAH = IRAM/60
      IRAM = IRAM-60*IRAH
 
C***  Rueckwandlung DEC in Grad und Minuten
      IDM=INT(DELTA/60)
      DS= DELTA - 60.*IDM
      IDG = IDM / 60
      IDM = IDM - 60*IDG
 
      IF (IDG .EQ. 0 .AND. BSOUTH) THEN
         IDGCHAR = ' -0'
      ELSE
         WRITE (IDGCHAR, '(I3)') IDG
      ENDIF
 
      IDM = IABS(IDM)
       DS =  ABS(DS)

C***  OUTPUT OF RESULTING COORDINATES
      WRITE (*,6) E2, IRAH, IRAM, RAS, IDGCHAR, IDM, DS
    6 FORMAT (F7.1,':  ',I2,':',I2,':',F5.2,  4X, A3, ':',I2, 
     >         ':',F4.1)
      WRITE (*,'(50(1H-))')

      STOP 'O.K.'

C**** ERROR BRANCHES *************************************
   90 PRINT *, '*** ERROR: EPOCH MUST BE A NUMBER!'
      WRITE (*,'(A,$)') ' ENTER EPOCH: '
      GOTO 11

   91 PRINT *, '*** ERROR: EPOCH MUST BE A NUMBER!'
      WRITE (*,'(A,$)') ' ENTER EPOCH: '
      GOTO 12

   92 PRINT *, '*** ERROR: COORDINATES MUST CONSIST OF 6 VALUES'
      WRITE (*,'(A)') ' TRY ONCE MORE: '
      GOTO 13

   93 PRINT *, '*** ERROR: RA hours must be integer in range 0-24'
      GOTO 13

   94 PRINT *, '*** ERROR: RA minutes must be integer 0-59'
      GOTO 13

   95 PRINT *, '*** ERROR: RA seconds must be in range 0-59'
      GOTO 13

   96 PRINT *, '*** ERROR: DEC degrees must be integer < 90'
      GOTO 13

   97 PRINT *, '*** ERROR: DEC arcmins must be non-negative integer <60'
      GOTO 13

   98 PRINT *, '*** ERROR: DEC arcsins must be non-negative <60'
      GOTO 13

      END

preattrib.f/    1553528659  5006  320   100644  766       `
      SUBROUTINE PREATTRIB (STRING)
C********************************************************************
C***  The given string is prefixed with the actual text attributes 
C**   as provided by PSX_ATTRIB in the special COMMON-Block
C********************************************************************
C***  Last text attribute status (for special use by WRPLOT)
      COMMON / COMATT / ATTCOLOR, ATTINCL, ATTWIDTH, ATTSUB, ATTBOLD, 
     >                  ALLATT
      CHARACTER*2 ATTCOLOR, ATTINCL, ATTWIDTH, ATTSUB, ATTBOLD 
      CHARACTER   ALLATT*8
      CHARACTER STRING*(*), HELPSTR*512
      
      NATT = IDX(ALLATT)
      IF (NATT .GT. 0) THEN
         HELPSTR = ALLATT(:NATT) // STRING
         STRING = HELPSTR
         ENDIF

      RETURN
      END
ps_cplot.f/     1553528659  5006  320   100644  475       `
      SUBROUTINE PS_CPLOT (X, Y, ISWITCH)
C***************************************************************
C***  OWN PS DRIVER: Clipped Move/draw
C***************************************************************

C***  Clipping Path (Double: 1=Full Paper, 2= special clipping)
      COMMON / COMCLIP / ICLIP, CXMIN(2), CXMAX(2), CYMIN(2), CYMAX(2)

C***  Switch to special clipping, then call move/draw
      ICLIP = 2
      CALL PS_PLOT (X,Y,ISWITCH)

      RETURN
      END

ps_factor.f/    1553528659  5006  320   100644  322       `
      SUBROUTINE PS_FACTOR (SCALE)
C***************************************************************
C***  PSOWN and X11OWN DRIVER: DEFINE SCALING FACTOR
C***************************************************************
      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA

      FORMATFA = SCALE

      RETURN
      END
