ps_movedraw.f/  1553528659  5006  320   100644  2768      `
      SUBROUTINE PS_MOVEDRAW (X, Y, ISWITCH)
C***************************************************************
C***  OWN PS DRIVER: Auxiliary subroutine
C***    which issues the Move/Draw Command
C***  Called from: SUBROUTINE PS_PLOT
C***  Optimization (suppressing identical Draws) 
C***    and updating of the BoundingBox done here as well
C***************************************************************

C***  Transformation coefficients 
      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA

C***  Bounding Box
      COMMON / COMBBOX / BBXMIN, BBXMAX, BBYMIN, BBYMAX 

C***  Counter of points in the active path
      COMMON / COMICOUNT / ICOUNT

C***  Linewidth parameters
      COMMON / COMPEN /LASTPEN, HALFLINW

C***  Current color index
      COMMON / COMCOLOR / LASTCOLOR

      CHARACTER*15 THISDRAW, LASTDRAW
      SAVE LASTDRAW, XLASTMOVE, YLASTMOVE
      DATA LASTDRAW / ' '/

      CHARACTER FORMSTR*30

C***  FORMAT SWITCH FOR LARGE COORDINATES (ONLY ON DIN-A3 PLOTS)
      IF (X .LT. 999. .AND. Y .LT. 999.) THEN
         FORMSTR = '(F5.1, 1X, F5.1, A)'
         LENGSTR = 13
         ELSE
         FORMSTR = '(F6.1, 1X, F6.1, A)'
         LENGSTR = 15
         ENDIF

C***  Draw
      IF (ISWITCH .EQ. 2) THEN
         WRITE (THISDRAW, FORMSTR) X, Y, ' D'
C***     Suppress identical points (optimization)
         IF (ICOUNT .EQ. 1 .OR. LASTDRAW .NE. THISDRAW) THEN
            WRITE (KPS, '(A)') THISDRAW(:LENGSTR)
            ICOUNT = ICOUNT + 1
            LASTDRAW = THISDRAW
C***        Update Bounding Box
C***        If drawing color is 0 (assumed to mean white), 
C***                the bounding box is not updated!
            IF (LASTCOLOR .EQ. 0) GOTO 9
            BBXMIN = AMIN1 (BBXMIN, X-HALFLINW)
            BBYMIN = AMIN1 (BBYMIN, Y-HALFLINW)
            BBXMAX = AMAX1 (BBXMAX, X+HALFLINW)
            BBYMAX = AMAX1 (BBYMAX, Y+HALFLINW)
C***        If this is the first Draw after Move, the last Move 
C***           accounts for the Bounding Box as well 
            IF (ICOUNT .EQ. 2) THEN
               BBXMIN = AMIN1 (BBXMIN, XLASTMOVE-HALFLINW)
               BBYMIN = AMIN1 (BBYMIN, YLASTMOVE-HALFLINW)
               BBXMAX = AMAX1 (BBXMAX, XLASTMOVE+HALFLINW)
               BBYMAX = AMAX1 (BBYMAX, YLASTMOVE+HALFLINW)
               ENDIF
    9       CONTINUE
            ENDIF

C***  Move 
      ELSE IF (ISWITCH .EQ. 3) THEN
         WRITE (KPS, '(A)') 'stroke'
         WRITE (KPS, '(A)') 'newpath'
         WRITE (KPS, FORMSTR) X, Y, ' M'
         ICOUNT = 1
         XLASTMOVE = X
         YLASTMOVE = Y

C***  wrong choice of ISWITCH:
      ELSE
         CALL PS_PLTEND
         WRITE (*, *) '>>> ISWITCH=', ISWITCH, ' NOT ALLOWED <<<'
         STOP 'ERROR IN PS_MOVEDRAW'
      ENDIF

      RETURN
      END
ps_newcolor.f/  1553528659  5006  320   100644  784       `
      SUBROUTINE PS_NEWCOLOR (R, G, B)
C***************************************************************
C***  OWN PS DRIVER: SET NEW COLOR
C***************************************************************
C***  Transformation coefficients 
      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA
C***  Flag for Color Plot (otherwise: black-and-white)
      COMMON / COMCOLORFLAG/ COLORFLAG
      LOGICAL COLORFLAG
      
C***  Counter of points in the active path
      COMMON / COMICOUNT / ICOUNT

      ICOUNT = 0

      WRITE (KPS, '(A)') 'stroke'

      IF (R .NE. G .OR. G .NE. B) THEN
         COLORFLAG = .TRUE.
         WRITE (KPS, '(3(F5.3,1X), A)') R, G, B, 'setrgbcolor'
         ELSE
         WRITE (KPS, '(F5.3,1X, A)') R, 'setgray'
         ENDIF

      RETURN
      END
ps_newpen.f/    1553528659  5006  320   100644  1022      `
      SUBROUTINE PS_NEWPEN (I)
C***************************************************************
C***  OWN PS DRIVER: DEFINE new linewidth
C***************************************************************
      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA

C***  Counter of points in the active path
      COMMON / COMICOUNT / ICOUNT

C***  Unit width in pt: 1/300 inch = standard resolution
      PARAMETER (WIDTH1 = 0.24)

C***  Linewidth parameters
      COMMON / COMPEN /LASTPEN, HALFLINW

C***  Reset counter, i.e. a MOVE action is necessary after Pen change
      ICOUNT = 0

C***  Suppress repeated setting of unchanged linewidth
      IF (I .NE. LASTPEN) THEN 
C***         WIDTHPT = I * WIDTH1
C***  Changed to skale linewidth with FORMATFACTOR, wrh 03-Sep-2008
         WIDTHPT = I * WIDTH1 * FORMATFA
         WRITE (KPS, '(A)')        'stroke'
         WRITE (KPS, '(F5.1, A)') WIDTHPT, ' setlinewidth % Newpen'
         LASTPEN = I 
         HALFLINW = WIDTHPT * 0.5
         ENDIF

      RETURN
      END
ps_opepsfont.f/ 1553528659  5006  320   100644  4003      `
      SUBROUTINE PS_OPEPSFONT (ACTSIZE, FONT)
C*************************************************************************
C***  PSOWN driver: Generating Postscript Fonts
C***       The corresponding Data files are read into internal arrays
C***  ACTSIZE koennte dazu dienen, bei grossen Buchstaben einen
C***    groesseren Font zu generieren zwecks Qualitaet (not yet implemented)
C*************************************************************************

C***  Conversion factor cm -> pt
      COMMON / COMCMPT / CMPT

C***  PS Channel Number
      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA

      CHARACTER FONT*6 

C***  Path to the font files
      COMMON / COMFOPA / FONTPATH
      CHARACTER FONTPATH*255, STATUS*10,FILENAME*255
      SAVE STATUS
C***  NEWPLOT defined by PS_PLOTS
      COMMON / NEWPLOT / NEWPLOT
      LOGICAL NEWPLOT

C***  Note: The same dimensions appear in PSX_READ
      PARAMETER (MAXASCPS = 400)
      PARAMETER (MAXGREPS = 400)
      PARAMETER (MAXAMPPS = 200)
      PARAMETER (MAXSLAPS = 200)
      PARAMETER (MAXITAPS = 400)
      CHARACTER*16 PS_ASCII(MAXASCPS), PS_GREEK(MAXGREPS)
      CHARACTER*16 PS_AMPER(MAXAMPPS), PS_SLASH(MAXSLAPS)
      CHARACTER*16 PS_ITALI(MAXITAPS)
      COMMON / PSFONTDAT / PS_ASCII, PS_GREEK, PS_AMPER, PS_SLASH, 
     >                     PS_ITALI



      IF (STATUS .EQ. FONT .AND. .NOT. NEWPLOT) RETURN
      NEWPLOT = .FALSE. 

C***  Issue PS Command for generating the font
      IF (FONT .EQ. 'TIMES') THEN
         WRITE (KPS, '(A)') '/Times-Roman findfont'
      ELSE IF (FONT .EQ. 'HELVET') THEN
         WRITE (KPS, '(A)') '/Helvetica findfont'
      ELSE IF (FONT .EQ. 'COURIE') THEN
         WRITE (KPS, '(A)') '/Courier findfont'
      ELSE IF (FONT .EQ. 'ZAPF  ') THEN
         WRITE (KPS, '(A)') '/ZapfChancery-MediumItalic findfont'
      ELSE
         WRITE (*,'(2A)') '>>> Illegal Font Name: ', FONT
         STOP 'ERROR IN PS_OPEPSFONT'
      ENDIF

      SIZEPT = CMPT * 1.5 
      WRITE (KPS, '(F8.2, A)') SIZEPT, ' scalefont setfont'

C***  Font tables must only be loaded if not yet in memory!
      IF (STATUS .EQ. FONT) RETURN
      STATUS = FONT


      LENFP = IDX(FONTPATH)


C***  Read Font Data into internal arry
      FILENAME=FONTPATH(:LENFP)//FONT(:IDX(FONT))//'_ASCII.DAT'
      OPEN (31, STATUS='OLD', ERR=99, FILE=FILENAME)
      DO I=1, MAXASCPS
      READ (31, '(A)', END=31) PS_ASCII(I)
      END DO
      WRITE (*,'(A)') '>>> DIMENSION MAXASCPS INSUFFICIENT <<<'
      STOP 'ERROR IN PS_OPEPSFONT'
   31 CLOSE (31)

      FILENAME=FONTPATH(:LENFP)//'SYMBOL.DAT'
      OPEN (32, STATUS='OLD', ERR=99, FILE=FILENAME)
      DO I=1, MAXGREPS
      READ (32, '(A)', END=32) PS_GREEK(I)
      END DO
      WRITE (*,'(A)') '>>> DIMENSION MAXGREPS INSUFFICIENT <<<'
      STOP 'ERROR IN PS_OPEPSFONT'
   32 CLOSE (32)

      FILENAME=FONTPATH(:LENFP)//FONT(:IDX(FONT))//'_AMPERSAND.DAT'
      OPEN (33, STATUS='OLD', ERR=99, FILE=FILENAME)
      DO I=1, MAXAMPPS
      READ (33, '(A)', END=33) PS_AMPER(I)
      END DO
      WRITE (*,'(A)') '>>> DIMENSION MAXAMPPS INSUFFICIENT <<<'
      STOP 'ERROR IN PS_OPEPSFONT'
   33 CLOSE (33)

      FILENAME=FONTPATH(:LENFP)//FONT(:IDX(FONT))//'_BACKSLASH.DAT'
      OPEN (34, STATUS='OLD', ERR=99, FILE=FILENAME)
      DO I=1, MAXSLAPS
      READ (34, '(A)', END=34) PS_SLASH(I)
      END DO
      WRITE (*,'(A)') '>>> DIMENSION MAXSLAPS INSUFFICIENT <<<'
      STOP 'ERROR IN PS_OPEPSFONT'
   34 CLOSE (34)

      FILENAME=FONTPATH(:LENFP)//'TIMES_ITALIC.DAT'
      OPEN (35, STATUS='OLD', ERR=99, FILE=FILENAME)
      DO I=1, MAXITAPS
      READ (35, '(A)', END=35) PS_ITALI(I)
      END DO
      WRITE (*,'(A)') '>>> DIMENSION MAXITAPS INSUFFICIENT <<<'
      STOP 'ERROR IN PS_OPEPSFONT'
   35 CLOSE (35)

C***  Set Read pointer at the beginning of data
      CALL PSX_REWIND 


      RETURN


C***  Error Branches
   99 WRITE (*, '(A)') '>>> CANNOT OPEN FONT FILE:'
      write (*, '(A)') FILENAME
      STOP 'ERROR IN PS_OPEPSFONT'
 
      END

ps_plot.f/      1553532978  5006  320   100644  3903      `
      SUBROUTINE PS_PLOT (X, Y, ISWITCH)
C***************************************************************
C***  OWN PS DRIVER: X, Y in cm (absolute)
C***       ISWITCH = 3: Move
C***                 2: Draw
C***                -2: Define offset
C***                -3: Define Offset
C***               997: Define Clipping Minima
C***               998: Define Clipping Maxima
C***************************************************************

C***  Transformation coefficients 
      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA

C***  Conversion factor cm -> pt defined in PS_PLOTS
      COMMON / COMCMPT / CMPT 

C***  Clipping Path (ICLIP=1: Full Paper; 2: special clipping)
      COMMON / COMCLIP / ICLIP, CXMIN(2), CXMAX(2), CYMIN(2), CYMAX(2)

C***  Counter of points in the active path
      COMMON / COMICOUNT / ICOUNT

      LOGICAL THISOUT, LASTOUT
      SAVE LASTOUT, XLAST, YLAST
      DATA LASTOUT / .TRUE. /

      XPT = (X * FORMATFA + XOFFSET) * CMPT
      YPT = (Y * FORMATFA + YOFFSET) * CMPT

      GOTO 1
C***  Entry point used from PS_SYM1WR
      ENTRY PS_PLOT_ENTRY (XENTRY, YENTRY, ISWITCH)
      XPT = XENTRY
      YPT = YENTRY
    1 CONTINUE

      THISOUT = ( XPT - CXMIN(ICLIP) ) * ( XPT - CXMAX(ICLIP) ) .GT. .0 
     >     .OR. ( YPT - CYMIN(ICLIP) ) * ( YPT - CYMAX(ICLIP) ) .GT. .0 

C***  Draw
      IF (ISWITCH .EQ. 2) THEN
         IF (ICOUNT .EQ. 0 .AND. .NOT. LASTOUT) THEN
            CALL PS_PLTEND
            WRITE (6,*) '>>>  Draw action without preceeding Move <<<'
            STOP 'ERROR IN PS_PLOT'
            ENDIF

C***     Last and this point inside clipping path
         IF (.NOT. LASTOUT .AND. .NOT. THISOUT) THEN
            CALL PS_MOVEDRAW (XPT, YPT, 2)

C***     Last point outside, this point inside clipping path
         ELSE IF (LASTOUT .AND. .NOT. THISOUT) THEN
C***        Find intersection with clipping path, insert move
            CALL PSX_CLIPAUX 
     >          (XLAST, YLAST, XPT, YPT, XS1, YS1, XS2, YS2, NS)
            CALL PS_MOVEDRAW (XS1, YS1, 3)
            CALL PS_MOVEDRAW (XPT, YPT, 2)

C***     Last point inside, this point outside clipping path
         ELSE IF (.NOT. LASTOUT .AND. THISOUT) THEN
C***        Find intersection with clipping path, 
C***        then draw to that point 
            CALL PSX_CLIPAUX 
     >          (XLAST, YLAST, XPT, YPT, XS1, YS1, XS2, YS2, NS)
            CALL PS_MOVEDRAW (XS1, YS1, 2)

C***     Both points outside clipping path
         ELSE IF (LASTOUT .AND. THISOUT) THEN
C***        Find zero or two intersection points
            CALL PSX_CLIPAUX 
     >          (XLAST, YLAST, XPT, YPT, XS1, YS1, XS2, YS2, NS)
            IF (NS .EQ. 2) THEN
               CALL PS_MOVEDRAW (XS1, YS1, 3)
               CALL PS_MOVEDRAW (XS2, YS2, 2)
               ENDIF
         ENDIF

C***  Interrupt too long polylines (prevent PS stack overflow)
         IF (ICOUNT .GT. 10000) CALL PS_MOVEDRAW (XPT, YPT, 3)

C***  Move (only if point inside clipping path)
      ELSE IF (ISWITCH .EQ. 3) THEN
         IF (.NOT. THISOUT) CALL PS_MOVEDRAW (XPT, YPT, 3)

C***  Define Offsets
      ELSE IF (ISWITCH .EQ. -3 .OR. ISWITCH .EQ. -2) THEN
          XOFFSET = X * FORMATFA + XOFFSET
          YOFFSET = Y * FORMATFA + YOFFSET

C***  Define Clipping path (never larger than full paper)
      ELSE IF (ISWITCH .EQ. 997) THEN
          CXMIN(2) = AMAX1(CXMIN(1), XPT)
          CYMIN(2) = AMAX1(CYMIN(1), YPT)
      ELSE IF (ISWITCH .EQ. 998) THEN
          CXMAX(2) = AMIN1(CXMAX(1), XPT)
          CYMAX(2) = AMIN1(CYMAX(1), YPT) 

C***  wrong or un-implemented choice if ISWITCH:
      ELSE
         CALL PS_PLTEND
         WRITE (*, *) '>>> ISWITCH=', ISWITCH, ' NOT ALLOWED <<<'
         STOP 'ERROR IN PS_PLOT'
      ENDIF

C***  Reset Clipping switch
      ICLIP = 1

C***  Keep last point in mind
      XLAST = XPT
      YLAST = YPT
      LASTOUT = THISOUT

      RETURN
      END

ps_plots.f/     1714146304  5006  320   100644  4988      `
      SUBROUTINE PS_PLOTS (KANAL, IDEV, PSIZEX, PSIZEY)
C**********************************************************
C***  OWN POSTSCRIPT DRIVER: OPEN PS-FILE
C**********************************************************

C***  Conversion factor cm -> pt
      COMMON / COMCMPT / CMPT

C***  Transformation coefficients 
      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA
      
C***  Bounding Box
      COMMON / COMBBOX / BBXMIN, BBXMAX, BBYMIN, BBYMAX

C***  Linewidth parameters
      COMMON / COMPEN /LASTPEN, HALFLINW

C***  Clipping Path (ICLIP=1: Full Paper; 2: special clipping)
      COMMON / COMCLIP / ICLIP, CXMIN(2), CXMAX(2), CYMIN(2), CYMAX(2)

C***  Counter of points in the active path
      COMMON / COMICOUNT / ICOUNT

C***  NEWPLOT information for Subr. PS_OPEPSFONT
      COMMON / NEWPLOT / NEWPLOT
      LOGICAL NEWPLOT

C***  Translation vector for BBrotate option, used in PS_PLTEND
      COMMON / COMXTRANS / XTRANS
C***  Special common block transferring the BBROT option from READDATA
      COMMON / COMBBROT / BBROT
      LOGICAL BBROT

C***  Flag for Color Plot (otherwise: black-and-white)
C***  Modified in PS_NEWCOLOR, finally used in PS_PLTEND
      COMMON / COMCOLORFLAG/ COLORFLAG
      LOGICAL COLORFLAG

C***  NAME OF THE SCRATCH-FILE; TO BE USED AND REMOVED IN PS_PLTEND
      COMMON / COMFSNAME / FSNAME

      CHARACTER DAT*9, TIM*8, FSNAME*28

C***  Paper format descriptor
C***  provided by subr. READDATA via COMMON-BLOCK
      CHARACTER*7 FDESACT
      COMMON /COMFORMAT/ FDESACT

      KPS = KANAL

C***  Conversion factor cm -> pt (theoretical value: 28.34)
      CMPT = 28.34

C***  Flag for Color Plot: default = black-and-white
      COLORFLAG = .FALSE.

C***  Prevent later FORMAT overflows
      IF ( CMPT * PSIZEX .GT. 9999. .OR. CMPT * PSIZEY .GT. 9999.) 
     >   STOP 'ERROR IN PSPLOTS: PAPERSIZE TOO LARGE!'

C***  test output
ccc      WRITE (*,*) '*** PAPERFORMAT ' // FDESACT

C***  Initalize OFFSET values AND SCALEFACTOR
      XOFFSET = .0
      YOFFSET = .0
      FORMATFA = 1. 

C***  Initialize Bounding Box
      BBXMIN = CMPT * PSIZEX
      BBYMIN = CMPT * PSIZEY
      BBXMAX = .0
      BBYMAX = .0

C***  Initialize clipping path (full paper)
      ICLIP = 1 
      CXMIN(1) = .0
      CXMIN(2) = .0
      CYMIN(1) = .0
      CYMIN(2) = .0
      CXMAX(1) = CMPT * PSIZEX
      CXMAX(2) = CMPT * PSIZEX
      CYMAX(1) = CMPT * PSIZEY
      CYMAX(2) = CMPT * PSIZEY

C***  Initialize active-path point counter
      ICOUNT = 0

C***  INITIALIZE LASTPEN 
      LASTPEN = 0

C***  Initialize Graphic State Matrix
      CALL GS_INIT

C***  Initialize NEWPLOT 
      NEWPLOT = .TRUE.

C***  Writing of (preliminary) PostScript File starts after BoundingBox
      CALL DATE (DAT)
      CALL TIME (TIM)
      FSNAME = 'wrplot_scratch_' // TIM // '.ps'
      OPEN (KANAL, FILE=FSNAME, STATUS='UNKNOWN')
ccc   Die folgende Option scheitert unter linux 8.0, ist aber offenbar
ccc   entbehrlich (wrh 1.1.2003):
ccc     >      CARRIAGECONTROL='LIST')
      WRITE (6, '(A)') ' PostScript file opened' 

      WRITE (KANAL, '(A)') '%%CreationDate:' // DAT // '  ' // TIM 
      WRITE (KANAL, '(A)') '%%Pages: 999'
      WRITE (KANAL, '(A)') '%%PS Driver written by Wolf-Rainer Hamann'
      WRITE (KANAL, '(A)') '%%EndComments'
      WRITE (KANAL, '(A)') '/D { lineto } bind def'
      WRITE (KANAL, '(A)') '/M { moveto } bind def'
      WRITE (KANAL, '(A)') '/RD { rlineto } bind def'
      WRITE (KANAL, '(A)') '/RM { rmoveto } bind def'
      WRITE (KANAL, '(A)') '%%EndProlog'
      WRITE (KANAL, '(A)') '%%Page: 1 100'
C***  No Landscape rotation for screen formats 
      IF (PSIZEX .LT. PSIZEY .OR. 
     >    FDESACT .EQ. 'SCREEN2' .OR. 
     >    FDESACT .EQ. 'SCREEN3' .OR. 
     >    FDESACT .EQ. 'SCREEN4' ) THEN
         WRITE (KANAL, '(A)') '% 0 0 translate % Portrait format'
         WRITE (KANAL, '(A)') '% 0 rotate      % Portrait format'
         BBROT = .FALSE.
      ELSE
         XTRANS = CMPT * PSIZEY
         WRITE (KANAL, '(F6.1, A)') 
     >                XTRANS, ' 0 translate      % Landscape format'  
         WRITE (KANAL, '(A)') '90 rotate         % Landscape format'
      ENDIF 
C***  Extra line for SCREEN formats needed for ps2pdf
      IF (FDESACT .EQ. 'SCREEN2' ) WRITE (KANAL, '(A)')
     >  '<< /PageSize [864 648] >> setpagedevice'
      IF (FDESACT .EQ. 'SCREEN3' ) WRITE (KANAL, '(A)')
     >  '<< /PageSize [1152 648] >> setpagedevice'
      IF (FDESACT .EQ. 'SCREEN4' ) WRITE (KANAL, '(A)')
     >  '<< /PageSize [1037 648] >> setpagedevice'
ccc   Orientation wirkt nicht oder unterschiedlich auf verschiedene
ccc    gs-Versionen!! Kann man vermeiden durch Definition eines
ccc    Formates, das ohne Drehung auskommt. 
ccc     >  '<< /Orientation 3 /PageSize [864 648] >> setpagedevice'
      WRITE (KANAL, '(A)') '1 setlinecap'
      WRITE (KANAL, '(A)') '1 setlinejoin' 
      CALL PS_NEWPEN (1)
      WRITE (KANAL, '(A)') '% End of Header generated by PSPLOTS'

      RETURN
      END
ps_pltend.f/    1730807480  5006  320   100640  7148      `
      SUBROUTINE PS_PLTEND
C**********************************************************
C***  OWN POSTSCRIPT DRIVER: CLOSE PS-FILE
C**********************************************************

C***  Bounding Box
      COMMON / COMBBOX / BBXMIN, BBXMAX, BBYMIN, BBYMAX 

C***  Operating System
      COMMON / COMOS / OPSYS
      CHARACTER OPSYS*8, FNAME*255

C***  Unix Commad 'cat' available?
      COMMON / COMBC / BCAT
      LOGICAL BCAT

C***  Special common block transferring the BBROT option from READDATA
      COMMON / COMBBROT / BBROT, EPS
      LOGICAL BBROT, EPS

C***  Translation vector for BBrotate option, calculated in PS_PLOTS
      COMMON / COMXTRANS / XTRANS

C***  Channel Number
      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA

C***  Flag for Color Plot (if false: black-and-white)
      COMMON / COMCOLORFLAG/ COLORFLAG
      LOGICAL COLORFLAG

C***  Flag for hatching prologue (only inserted if set by PS_HFILL)
      COMMON / COMHATCHFLAG / HATCHFLAG
      LOGICAL HATCHFLAG

C***  NAME OF THE SCRATCH-FILE; TO BE USED AND REMOVED IN PS_PLTEND
      COMMON / COMFSNAME / FSNAME

      CHARACTER FSNAME*28
      CHARACTER SLINE*132

      CHARACTER*80 LINE

      WRITE (KPS, '(A)') 'stroke % terminate last polyline'

C***  Test: show Bounding Box
      IF (.FALSE.) THEN
C      IF (.TRUE.) THEN
        WRITE (KPS, '(F6.1, 1X, F6.1, A)') BBXMIN, BBYMIN, ' M'
        WRITE (KPS, '(F6.1, 1X, F6.1, A)') BBXMAX, BBYMIN, ' D'
        WRITE (KPS, '(F6.1, 1X, F6.1, A)') BBXMAX, BBYMAX, ' D'
        WRITE (KPS, '(F6.1, 1X, F6.1, A)') BBXMIN, BBYMAX, ' D'
        WRITE (KPS, '(F6.1, 1X, F6.1, A)') BBXMIN, BBYMIN, ' D'
        WRITE (KPS, '(A)') 'stroke'
      ENDIF

      WRITE (KPS, '(A)') 'showpage'
      WRITE (KPS, '(A)') '%%EOF'
      CLOSE (KPS)

C***  Define PS file name
      KANAL = 50
      IF (OPSYS .EQ. 'UNIX') THEN
        FNAME = 'wrplot.ps.1'
   5    OPEN (KANAL, FILE=FNAME(:IDX(FNAME)), STATUS='NEW', ERR=1)
        GOTO 2

C***    FILE ALREADY EXISTS
   1    CONTINUE
        LAST = IDX(FNAME)
        DO 3 I=LAST-1, 1, -1
           ISTOP = I
           IF (FNAME(I:I) .EQ. '.') GOTO 4
   3    CONTINUE
   4    CONTINUE
        READ (FNAME(ISTOP+1:LAST), '(I3)') IVERSION
        IVERSION = IVERSION + 1
        IF (IVERSION .LT. 10) THEN
           WRITE (FNAME(ISTOP+1:ISTOP+1), '(I1)') IVERSION
           ELSE IF (IVERSION .LT. 100) THEN
           WRITE (FNAME(ISTOP+1:ISTOP+2), '(I2)') IVERSION
           ELSE IF (IVERSION .LT. 1000) THEN
           WRITE (FNAME(ISTOP+1:ISTOP+3), '(I3)') IVERSION
           ELSE
           STOP 'ERROR IN PS_PLTEND: IVERSION > 999'
           ENDIF
        GOTO 5

   2    CONTINUE
        ELSE
        STOP 'ERROR IN PS_PLTEND: UNKNOWN OPERATING SYSTEM'
        ENDIF


C***  Write Prolog of PostScript File
      WRITE (6, '(A)') ' File finished: ' // FNAME(:IDX(FNAME))
      IF (EPS) THEN
         WRITE (KANAL, '(A)') '%!PS-Adobe-1.0 EPSF-1.0'
      ELSE
         WRITE (KANAL, '(A)') '%!PS-Adobe-1.0'
      ENDIF
      WRITE (KANAL, '(A)') '%%Filename: ' // FNAME(:IDX(FNAME))
      IF (BBROT) THEN 
         WRITE (KANAL, '(A, 4(1X,I7))') '%%BoundingBox: ',
     >    INT(XTRANS-BBYMAX), INT(BBXMIN), 
     >    1+INT(XTRANS-BBYMIN), 1+INT(BBXMAX)
         WRITE (KANAL, '(A, 4(1X,F7.1))') '%%HiResBoundingBox: ',
     >    XTRANS-BBYMAX, BBXMIN, XTRANS-BBYMIN, BBXMAX
      ELSE
         WRITE (KANAL, '(A, 4(1X,I7))') '%%BoundingBox: ',
     >    INT(BBXMIN), INT(BBYMIN), 1+INT(BBXMAX), 1+INT(BBYMAX)
         WRITE (KANAL, '(A, 4(1X,F7.1))') '%%HiResBoundingBox: ',
     >    BBXMIN, BBYMIN, BBXMAX, BBYMAX
      ENDIF

      IF (COLORFLAG) THEN 
         WRITE (KANAL, '(A)') '%%WRPLOT:Color'
      ELSE
         WRITE (KANAL, '(A)') '%%WRPLOT:Black-and-white'
      ENDIF

      IF (HATCHFLAG) THEN

       WRITE (KANAL, '(A)') '%%WRPLOT: Hatching by these defs:'
       WRITE (KANAL, '(A)') '/ED { exch def } bind def'
       WRITE (KANAL, '(A)') '/SLW /setlinewidth load def'
       WRITE (KANAL, '(A)') '/CLW /currentlinewidth load def'
       WRITE (KANAL,'(A,A)') '/Div { dup 0 eq { pop } { div } ifelse } '
     > , 'def'     
       WRITE (KANAL, '(A,A)') '/Atan { /atan load stopped { pop pop 0 }'
     > , ' if } def' 
       WRITE (KANAL, '(A)')'/LineFill { % Patch for hatch from PSTRICKS'
       WRITE (KANAL, '(A)') '  gsave '
       WRITE (KANAL, '(A)') '  abs /hatchWidthInc ED'
       WRITE (KANAL, '(A)') '  abs /hatchSepInc ED'
       WRITE (KANAL, '(A)') '  abs CLW add /a ED '
       WRITE (KANAL, '(A)') '  a 0 dtransform round exch round exch'
       WRITE (KANAL, '(A)') '  2 copy idtransform' 
       WRITE (KANAL, '(A)') '  exch Atan rotate '
       WRITE (KANAL, '(A)') '  idtransform pop /a ED '
       WRITE (KANAL, '(A)') '  .25 .25 itransform pathbbox' 
       WRITE (KANAL, '(A)') '  /y2 ED '
       WRITE (KANAL, '(A)') '  a Div ceiling cvi /x2 ED /y1 ED '
       WRITE (KANAL, '(A)') '  a Div cvi /x1 ED /y2 y2 y1 sub def' 
       WRITE (KANAL, '(A)') '  clip '
       WRITE (KANAL, '(A)') '  newpath '
       WRITE (KANAL, '(A)') '  2 setlinecap' 
       WRITE (KANAL, '(A)') '  systemdict'
       WRITE (KANAL, '(A,A)') '  /setstrokeadjust known { true '
     > , 'setstrokeadjust } if' 
       WRITE (KANAL, '(A)') '  x2 x1 sub 1 add { '
       WRITE (KANAL, '(A)')'    x1 a mul y1 moveto 0 y2 rlineto stroke '
       WRITE (KANAL, '(A)') '    /x1 x1 1 add '
       WRITE (KANAL, '(A)') '      hatchWidthInc 0 gt { CLW add } if' 
       WRITE (KANAL, '(A)') '    def '
       WRITE (KANAL, '(A,A)') '    hatchSepInc 0 gt hatchWidthInc 0 gt'
     > , ' or {' 
       WRITE (KANAL, '(A)') '      /a a hatchSepInc add def'
       WRITE (KANAL, '(A)') '      CLW hatchWidthInc add SLW' 
       WRITE (KANAL, '(A)') '    } if'
       WRITE (KANAL, '(A)') '  } repeat' 
       WRITE (KANAL, '(A)') '  grestore' 
       WRITE (KANAL, '(A)') '  pop pop } def'

      ENDIF

      CLOSE (KANAL)   

      IF (BCAT) THEN
           LINE = 'cat ' // FSNAME // ' >> '// FNAME(:IDX(FNAME))
ccc           ISTAT = SYSTEM (LINE)
ccc           IF (ISTAT .NE. 0) STOP 'ERROR WITH cat IN PS_PLTEND'
ccc       Verzicht auf den Error code (wg portabilitaet)
          CALL SYSTEM (LINE)
      ELSE
           OPEN(1, FILE=FNAME(:IDX(FNAME)), STATUS='OLD', ERR=101)
           OPEN(2, FILE=FSNAME(:IDX(FSNAME)),STATUS='OLD', ERR=102)
   10      CONTINUE
             READ (1, '(A)', END=20) SLINE
           GOTO10       
   20      CONTINUE
             READ (2, '(A)', END=30) SLINE
             WRITE (1, '(A)') SLINE( :IDX(SLINE))
           GOTO 20
   30      CONTINUE
      ENDIF

ccc      LINE = '/bin/rm -f ' // FSNAME
      LINE = 'rm -f ' // FSNAME
ccc      ISTAT = SYSTEM (LINE)
ccc      IF (ISTAT .NE. 0) STOP 'ERROR WITH rm IN PS_PLTEND'
      CALL SYSTEM (LINE)

      RETURN

C******* Errors ***********************************

  101 WRITE (0,*) 'ERROR: FILE FNAME NOT OPENED'
      WRITE (0,'(2A)') 'FNAME=', FNAME( :IDX(FNAME))
      STOP 'ERROR IN PS_PLTEND'

  102 WRITE (0,*) 'ERROR: FILE FSNAME NOT OPENED'
      WRITE (0,'(2A)') 'FSNAME=', FSNAME( :IDX(FSNAME))
      STOP 'ERROR IN PS_PLTEND'

      END
ps_sym1ps.f/    1553528659  5006  320   100644  3984      `
      SUBROUTINE PS_SYM1PS (ONECHAR, GREEK, SPECIAL, ITALIC, XWIDTH)
C************************************************************************
C***  PSOWN DRIVER: - Transfers one character (PS Fonts) to the PS File
C***                - makes subsequent translate 
C***                - returns XWIDTH (in pt)
C************************************************************************

      COMMON / COMCMPT / CMPT

C***  Bounding Box
      COMMON / COMBBOX / BBXMIN, BBXMAX, BBYMIN, BBYMAX 

      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA
      LOGICAL GREEK, EOF, ITALIC
      CHARACTER LINE*16, ONECHAR*1, STYLE*5, SPECIAL*1, ACTPAR*10
      CHARACTER BSL*1
      DIMENSION XBB(4), YBB(4)

C***  Postscript Font select
      COMMON / COMFONT / FONT
      CHARACTER FONT*6

C***  Backslash Character
      BSL = CHAR(92)

C***  New (03.03.2007): Individual BBox for different fonts
C***  Provide higher BoundingBox for HELVET font
C***    ZAPF needs more space for under-length and to the right (ADDWIDTH) 
      IF (FONT .EQ. 'HELVET') THEN
         FONTHEIGHT = 1.1
         FONTUNDERLENGTH = -0.33
         ADDWIDTH = .0
      ELSEIF (FONT .EQ. 'ZAPF') THEN
         FONTHEIGHT = 1.04
         FONTUNDERLENGTH = -0.4
         ADDWIDTH = .2
      ELSE
         FONTHEIGHT = 1
         FONTUNDERLENGTH = -0.33
         ADDWIDTH = .0
      ENDIF

      IF (SPECIAL .EQ. BSL .AND. ONECHAR .EQ. 'A') 
     >    FONTHEIGHT = FONTHEIGHT * 1.42 

C***  Channel Numbers for Font Data: 30+KFONT
C***    with KFONT: 1=Normal, 2=Greek, 3=Ampersand, 4=Backslash, 5=Italic
      KFONT = 31
      IF (GREEK) KFONT = 32
      IF (SPECIAL .EQ. '&') KFONT = 33 
      IF (SPECIAL .EQ. BSL) KFONT = 34 
      IF (ITALIC) KFONT = 35

C***  SEARCH FOR CHARACTER
    1 CALL PSX_READ (KFONT, LINE, EOF)
      IF (EOF) GOTO 99
      IF (LINE(1:2) .NE. '*'//ONECHAR) GOTO 1

C***  Move to starting point
      WRITE (KPS, '(A)') '0 0 M' 

C***  TRANFER LINES (only 16 characters!!)
    2 CALL PSX_READ (KFONT, LINE, EOF)
      IF (EOF) GOTO 90
      IF (LINE(1:1) .EQ. '%') GOTO 3
      WRITE (KPS, '(A)') LINE
      GOTO 2

C***  read xwidth, translate by xwidth
    3 CALL SARGV (LINE, 3, ACTPAR)
      READ (ACTPAR, '(F10.0)', ERR=96) XWIDTH
C***  Factor 1.5 for definition of unit size in ps
      XWIDTH = XWIDTH * 1.5
      BBWIDTH = XWIDTH - 0.05 + ADDWIDTH

C***  Update Bounding Box
C***  Transform 4 corners of Character-BB into absolute Coordinates
      XBB(1) = .0
      YBB(1) = FONTUNDERLENGTH
      XBB(2) = BBWIDTH
      YBB(2) = FONTUNDERLENGTH
      XBB(3) = BBWIDTH
      YBB(3) = FONTHEIGHT
      XBB(4) = .0
      YBB(4) = FONTHEIGHT
      DO I=1, 4
      XBB(I) = XBB(I) * CMPT
      YBB(I) = YBB(I) * CMPT
      CALL GS_TRANSFORM (XBB(I), YBB(I), XS, YS)
      BBXMIN = AMIN1 (BBXMIN, XS)
      BBYMIN = AMIN1 (BBYMIN, YS)
      BBXMAX = AMAX1 (BBXMAX, XS)
      BBYMAX = AMAX1 (BBYMAX, YS)
      END DO      

C***  Add some additional space between letters
      ADDSPACE = 0.05
      XWIDTH = XWIDTH + ADDSPACE
      XWIDTH = XWIDTH * CMPT 
      CALL PSX_TRANSLAT (XWIDTH, .0, 2, DUMMY1, DUMMY2)

   10 CONTINUE
      CALL PSX_REWIND 
      SPECIAL = ' '
      RETURN

C***  THIS CHARACTER NOT FOUND
   99 CONTINUE
      XWIDTH = .0

      IF (KFONT .EQ. 31) THEN 
         STYLE = 'ASCII'
      ELSE IF (KFONT .EQ. 32) THEN 
         STYLE = 'GREEK'
      ELSE IF (KFONT .EQ. 33) THEN 
         STYLE = '& ...'
      ELSE IF (KFONT .EQ. 34) THEN 
         STYLE = BSL // ' ...'
      ELSE IF (KFONT .EQ. 35) THEN 
         STYLE = 'Italic'
      ENDIF

      WRITE (6, '(A)') '>>> WARNING: Print character <' // ONECHAR 
     >    // '> (Style: ' // STYLE // ') not found'
      GOTO 10

C***  Error Branches
   96 WRITE (*,'(A)') 
     > '>>> Illegal Format in WRPLOT Font File; decoding XWIDTH <<<'
      WRITE (*, '(A)') LINE
      GOTO 100

   90 WRITE (*,'(A)') 
     > '>>> Unexpected E-O-F in WRPLOT Font File <<<'

  100 STOP 'ERROR in PS_SYM1PS'

      END
ps_sym1wr.f/    1553528659  5006  320   100644  2841      `
      SUBROUTINE PS_SYM1WR (ONECHAR, GREEK, SPECIAL, XWIDTH)
C********************************************************************
C***  PSOWN DRIVER: 
C***    - Transfers one character from the WRPLOT Font to the PS-File
C***    - Makes subsequent translate (internal Graphic State)
C***    - Returns XWIDTH (in pt)
C********************************************************************

      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA
      LOGICAL GREEK, EOF
      CHARACTER LINE*16, ONECHAR*1, STYLE*5, SPECIAL*1, ACTPAR*10
      CHARACTER BSL*1

C***  Backslash Character
      BSL = CHAR(92)

C***  Channel Numbers for WRPLOT Font Data: 20+KFONT
C***    with KFONT: 1=Normal, 2=Greek, 3=Ampersand, 4=Backslash
      KFONT = 21
      IF (GREEK) KFONT = 22
      IF (SPECIAL .EQ. '&') KFONT = 23 
      IF (SPECIAL .EQ. BSL) KFONT = 24 

C***  SEARCH FOR CHARACTER
    1 CALL PSX_READ (KFONT, LINE, EOF)
      IF (EOF) GOTO 99
      IF (LINE(1:3) .NE. '*'//ONECHAR) GOTO 1

C***  TRANFER LINES (only 16 characters!!)
      WRITE (KPS, '(A)') '% show (' // onechar // ')'
    2 CALL PSX_READ (KFONT, LINE, EOF)
      IF (EOF) GOTO 90
      IF (LINE(1:1) .EQ. '%') GOTO 3
      CALL SARGV (LINE, 1, ACTPAR)
      READ (ACTPAR, '(F10.0)', ERR=98) X
      CALL SARGV (LINE, 2, ACTPAR)
      READ (ACTPAR, '(F10.0)', ERR=98) Y
      CALL SARGV (LINE, 3, ACTPAR)
      IF (ACTPAR(1:1) .EQ. 'M') THEN
         ISWITCH = 3
      ELSE IF (ACTPAR(1:1) .EQ. 'D') THEN
         ISWITCH = 2
      ELSE
         GOTO 98
      ENDIF

C***  Transformation into absolute coordinates
      CALL GS_TRANSFORM (X, Y, XS, YS)

      CALL PS_PLOT_ENTRY (XS, YS, ISWITCH)
      GOTO 2

    3 WRITE (KPS, '(A)') 'stroke'

C***  read xwidth, translate by xwidth
      CALL PSX_READ (KFONT, LINE, EOF)
      IF (EOF) GOTO 90
      READ (LINE, '(9X, F5.0)', ERR=96) XWIDTH
      CALL GS_TRANSLATE (XWIDTH, .0)

   10 CONTINUE
      CALL PSX_REWIND 
      SPECIAL = ' '
      RETURN

C***  THIS CHARACTER NOT FOUND
   99 CONTINUE
      XWIDTH = .0

      IF (KFONT .EQ. 21) THEN 
         STYLE = 'ASCII'
      ELSE IF (KFONT .EQ. 22) THEN 
         STYLE = 'GREEK'
      ELSE IF (KFONT .EQ. 23) THEN 
         STYLE = '& ...'
      ELSE IF (KFONT .EQ. 24) THEN 
         STYLE = BSL // ' ...'
      ENDIF

      WRITE (6, '(A)') '>>> WARNING: Print character <' // ONECHAR 
     >    // '> (Style: ' // STYLE // ') not found'
      GOTO 10

C***  Error Branches
   98 WRITE (*,'(A)') 
     > '>>> Illegal line in WRPLOT Font File; Move/Draw expected! <<<'
      WRITE (*, '(A)') LINE
      GOTO 100

   96 WRITE (*,'(A)') 
     > '>>> Illegal Format in WRPLOT Font File; decoding XWIDTH <<<'
      WRITE (*, '(A)') LINE
      GOTO 100

   90 WRITE (*,'(A)') 
     > '>>> Unexpected E-O-F in WRPLOT Font File <<<'

  100 STOP 'ERROR in PS_SYM1WR'

      END

ps_symbl.f/     1553528659  5006  320   100644  8797      `
      SUBROUTINE PS_SYMBL (XCM, YCM, SIZE, STRPAR, ANGLE)
C*************************************************************************
C***  PSOWN driver: printing a character string
C*************************************************************************

C***  Transformation coefficients 
      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA
      
C***  Clipping Path (ICLIP=1: Full Paper; 2: special clipping)
      COMMON / COMCLIP / ICLIP, CXMIN(2), CXMAX(2), CYMIN(2), CYMAX(2)

C***  Conversion factor cm -> pt
      COMMON / COMCMPT / CMPT

C***  Current color
      COMMON / COMCOLOR / LASTCOLOR

C***  Default Font set by KASDEF Option
      COMMON / COMFONT / FONT 
      CHARACTER FONT*6, ACTFONT*6

C***  Blocktext and SQEEZE-Parameter from KDPLOT (TEXT option)
      COMMON / COMBLOCK / BLOCK, SQEEZE
                                 
      CHARACTER STRPAR*(*), ONECHAR*1, SPECIAL*1, NEXTCHAR*1, BSL*1
      LOGICAL GREEK, CHRINSTR, ITALIC, BLOCK, BOLD

C***  Backslash Character
      BSL = CHAR(92)

C***  Skip zero string
      LAST = IDX(STRPAR)
      IF (LAST .LE. 0) RETURN

C***  Skip zero SIZE
      IF (SIZE .LE. .0) THEN 
       WRITE (6, '(A)') '>>> WARNING: String with zero SIZE skipped <<<'
       RETURN
       ENDIF

C***  Defaults
      SIZEPT = CMPT * 1.5
      ACTSIZE = SIZE * FORMATFA
      GREEK  = .FALSE. 
      ITALIC = .FALSE. 
      BOLD   = .FALSE.
      SPECIAL = ' '
      DXHT = .0
      DY = 0.
      SH = 0.
      SCX = 1. 
      ACTFONT = 'WRPLOT'
      IF (FONT .EQ. 'TIMES' .OR. FONT .EQ. 'HELVET' .OR.
     >    FONT .EQ. 'COURIE' .OR. FONT .EQ. 'ZAPF  ') ACTFONT = FONT

C***  Local Font select
      IF (STRPAR(:3) .EQ. '&PT') THEN
         ACTFONT = 'TIMES'
         STRPAR = STRPAR(4:)
      ELSE IF (STRPAR(:3) .EQ. '&PH') THEN
         ACTFONT = 'HELVET'
         STRPAR = STRPAR(4:)
      ELSE IF (STRPAR(:3) .EQ. '&PC') THEN
         ACTFONT = 'COURIE'
         STRPAR = STRPAR(4:)
      ELSE IF (STRPAR(:3) .EQ. '&PW') THEN
         ACTFONT = 'WRPLOT'
         STRPAR = STRPAR(4:)
         ENDIF

      IF (ACTFONT .EQ. 'WRPLOT') THEN
         MODE = 1 
      ELSE
         MODE = 2
      ENDIF

C***  Add some additional space between the letters in PS-Fonts (in pt)
      ADDSPACE = 0.4 + 0.4 * ACTSIZE 

C***  Store old color
      IOLDCOLOR = LASTCOLOR

C***  Transform coordinates
      XPT = (XCM * FORMATFA + XOFFSET) * CMPT
      YPT = (YCM * FORMATFA + YOFFSET) * CMPT

C***  Open Fonts
      IF (ACTFONT .EQ. 'WRPLOT') THEN 
         CALL PSX_OPEWRFNT (ACTSIZE)
      ELSE 
         CALL PS_OPEPSFONT (ACTSIZE, ACTFONT)
      ENDIF


C**************************************************************
C*** Koordinate transformation to the beginning of the string
C**************************************************************

C***  Save graphic state
      CALL PSX_GSAVE (MODE)
C***  Translate to start position
      CALL PSX_TRANSLAT (XPT, YPT, MODE)
C***  Rotate
      IF (ANGLE .NE. .0) CALL PSX_ROTATE (ANGLE, MODE)
C***  Scale for Fontsize
      IF (BLOCK) THEN
         CALL PSX_SCALE (ACTSIZE*SQEEZE, ACTSIZE, MODE, DUMMY)
      ELSE
         CALL PSX_SCALE (ACTSIZE, ACTSIZE, MODE, DUMMY)
      ENDIF

C********************************************************************
C***  Write string Character by Character (and as a whole as comment)
C********************************************************************

      WRITE (KPS, '(2A)') '% String: ', STRPAR(:LAST) 

C***  Begin Loop I=1 ... LAST
      I = 1
   10 CONTINUE
      ONECHAR = STRPAR(I:I)
      IF (ONECHAR .EQ. '#' .AND. SPECIAL .NE. '&') THEN 
         GREEK = .NOT. GREEK
C***     PS Fonts: Issue PS Command for generating the font
         IF (ACTFONT .NE. 'WRPLOT') THEN
            IF (ACTFONT .EQ. 'TIMES' .AND. .NOT. GREEK) THEN
               WRITE (KPS, '(A)') '/Times-Roman findfont'
            ELSE IF (ACTFONT .EQ. 'HELVET' .AND. .NOT. GREEK) THEN
               WRITE (KPS, '(A)') '/Helvetica findfont'
            ELSE IF (ACTFONT .EQ. 'COURIE' .AND. .NOT. GREEK) THEN
               WRITE (KPS, '(A)') '/Courier findfont'
            ELSE IF (ACTFONT .EQ. 'ZAPF  ' .AND. .NOT. GREEK) THEN
               WRITE (KPS, '(A)') '/ZapfChancery-MediumItalic findfont'
            ELSE IF (GREEK) THEN
               WRITE (KPS, '(A)') '/Symbol findfont'
            ENDIF
            WRITE (KPS, '(F8.2, A)') SIZEPT, ' scalefont setfont'
         ENDIF

         GOTO 1
         ENDIF
C***  Decode Ampersand-Switches for Text Attributes
      IF (ONECHAR .EQ. '&' .AND. I .LT. LAST .AND. SPECIAL .EQ. ' ') 
     >   THEN
         NEXTCHAR = STRPAR(I+1:I+1)
C***     Switch for Italic font
         IF (NEXTCHAR .EQ. 'I' .AND. .NOT. GREEK .AND. 
     >       ACTFONT .NE. 'WRPLOT') THEN
            ITALIC = .TRUE. 
            WRITE (KPS, '(A)') '/Times-Italic findfont'
            WRITE (KPS, '(F8.2, A)') SIZEPT, ' scalefont setfont'
            I = I + 1
            GOTO 1
            ENDIF
C***     Switch back from Italic font
         IF (NEXTCHAR .EQ. 'N' .AND. ITALIC) THEN 
            ITALIC = .FALSE. 
            IF (ACTFONT .EQ. 'TIMES' .AND. .NOT. GREEK) THEN
               WRITE (KPS, '(A)') '/Times-Roman findfont'
               ELSE IF (ACTFONT .EQ. 'HELVET' .AND. .NOT. GREEK) THEN
               WRITE (KPS, '(A)') '/Helvetica findfont'
               ELSE IF (ACTFONT .EQ. 'COURIE' .AND. .NOT. GREEK) THEN
               WRITE (KPS, '(A)') '/Courier findfont'
               ELSE IF (ACTFONT .EQ. 'ZAPF  ' .AND. .NOT. GREEK) THEN
               WRITE (KPS, '(A)') '/ZapfChancery-MediumItalic findfont'
               ELSE IF (GREEK) THEN
               WRITE (KPS, '(A)') '/Symbol findfont'
               ENDIF
            WRITE (KPS, '(F8.2, A)') SIZEPT, ' scalefont setfont'
         ENDIF

C***     Switch for Boldface font ("Fett")
         IF (NEXTCHAR .EQ. 'F') THEN 
	  IF (.NOT. GREEK .AND. ACTFONT .NE. 'WRPLOT') THEN
            BOLD = .TRUE. 
            IF (ACTFONT .EQ. 'TIMES' .AND. .NOT. GREEK) THEN
               WRITE (KPS, '(A)') '/Times-Bold findfont'
               ELSE IF (ACTFONT .EQ. 'HELVET' .AND. .NOT. GREEK) THEN
               WRITE (KPS, '(A)') '/Helvetica-Bold findfont'
               ELSE IF (ACTFONT .EQ. 'COURIE' .AND. .NOT. GREEK) THEN
               WRITE (KPS, '(A)') '/Courier-Bold findfont'
C***    No boldface font existing for ZAPF
               ELSE IF (ACTFONT .EQ. 'ZAPF  ' .AND. .NOT. GREEK) THEN
               WRITE (KPS, '(A)') '/ZapfChancery-MediumItalic findfont'
            ENDIF
            WRITE (KPS, '(F8.2, A)') SIZEPT, ' scalefont setfont'
          ENDIF
         ENDIF
C***     Switch back from Boldface font
         IF (NEXTCHAR .EQ. 'f') THEN
	  IF (BOLD .AND. .NOT. GREEK) THEN 
            BOLD = .FALSE. 
            IF (ACTFONT .EQ. 'TIMES' .AND. .NOT. GREEK) THEN
               WRITE (KPS, '(A)') '/Times-Roman findfont'
               ELSE IF (ACTFONT .EQ. 'HELVET' .AND. .NOT. GREEK) THEN
               WRITE (KPS, '(A)') '/Helvetica findfont'
               ELSE IF (ACTFONT .EQ. 'COURIE' .AND. .NOT. GREEK) THEN
               WRITE (KPS, '(A)') '/Courier findfont'
               ELSE IF (ACTFONT .EQ. 'ZAPF  ' .AND. .NOT. GREEK) THEN
              WRITE (KPS, '(A)') '/ZapfChancery-MediumItalic findfont'
           ENDIF
            WRITE (KPS, '(F8.2, A)') SIZEPT, ' scalefont setfont'
          ENDIF
         ENDIF

         IF ( CHRINSTR(NEXTCHAR, 'FfIGHTMNLREBW0123456789') ) THEN
            CALL PSX_ATTRIB (NEXTCHAR, DY, SH, SCX, DXHT, 
     >                       MODE, DUMMY1, DUMMY2, 'PSOWN')
            I = I + 1
            GOTO 1
            ENDIF
         ENDIF
      IF ( (SPECIAL .NE. '&' .AND. ONECHAR .EQ. '&') .OR.
     >     (SPECIAL .NE. BSL .AND. ONECHAR .EQ. BSL) ) THEN 
         SPECIAL = ONECHAR
         GOTO 1
         ENDIF

C***  Postscript Fonts *******************
C***  Preliminary:
      IF (ACTFONT .NE. 'WRPLOT') THEN
         CALL PS_SYM1PS (ONECHAR, GREEK, SPECIAL, ITALIC, XWIDTH) 

C***  WRPLOT Fonts *******************
      ELSE
         CALL PS_SYM1WR (ONECHAR, GREEK, SPECIAL, XWIDTH) 
      ENDIF
         DXHT = DXHT + XWIDTH

    1 I = I + 1
      IF (I .LE. LAST) GOTO 10
C***  End-of-Loop over the single characters ********************

C***  At End of String, in any case swith back to normal text attributes
C***     after saving the present state for special WRPLOT use
         CALL PSX_SAVEATT
          CALL PSX_ATTRIB ('N', DY, SH, SCX, DXHT, 
     >                       MODE, DUMMY1, DUMMY2, 'PSOWN')
        CALL PSX_ATTRIB ('M', DY, SH, SCX, DXHT, 
     >                       MODE, DUMMY1, DUMMY2, 'PSOWN')


C***  Restore graphic state 
      CALL PSX_GRESTORE (MODE)

C***  Restore color
      CALL COLOR ('DATA', ' ', IOLDCOLOR, IDUMMY)

      RETURN
      END

ps_textlen.f/   1553528659  5006  320   100644  350       `
      SUBROUTINE PS_TEXTLEN (TEXTLEN, SIZE, STRPAR)
C********************************************************************
C***  PSOWN DRIVER: DETERMINE LENGTH OF A STRING
C********************************************************************

      CHARACTER STRPAR*(*)

      CALL PSX_TEXTLEN (TEXTLEN, SIZE, STRPAR, 'PSOWN')

      RETURN
      END
ps_tlen1ps.f/   1553528659  5006  320   100644  2082      `
      SUBROUTINE PS_TLEN1PS (ONECHAR, GREEK, SPECIAL, ITALIC, XWIDTH, 
     >                     BBCXMAX)
C********************************************************************
C***  PSOWN DRIVER: Measure XWIDTH (in pt, for unit-SIZE) 
C***                of one character (PS Font)
C***                 Called from: PSX_TEXTLEN
C********************************************************************

      COMMON / COMCMPT / CMPT
      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA
      LOGICAL GREEK, EOF, ITALIC
      CHARACTER LINE*22, ONECHAR*1, SPECIAL*1, ACTPAR*10
      CHARACTER BSL*1

C***  Backslash Character
      BSL = CHAR(92)

C***  Channel Numbers for PS Font Data: 30+KFONT
C***    with KFONT: 1=Normal, 2=Greek, 3=Ampersand, 4=Backslash
      KFONT = 31
      IF (GREEK) KFONT = 32
      IF (SPECIAL .EQ. '&') KFONT = 33 
      IF (SPECIAL .EQ. BSL) KFONT = 34 
      IF (ITALIC) KFONT = 35 

C***  SEARCH FOR CHARACTER
    1 CALL PSX_READ (KFONT, LINE, EOF)
      IF (EOF) GOTO 99
      IF (LINE(1:3) .NE. '*'//ONECHAR) GOTO 1

C***  SKIP show- or other lines
    2 CALL PSX_READ (KFONT, LINE, EOF)
      IF (EOF) GOTO 90
      IF (LINE(1:1) .EQ. '%') GOTO 3
      GOTO 2

C***  Decode XWIDTH which actually serves as BBCXMAX;
    3 CONTINUE
      CALL SARGV (LINE, 3, ACTPAR)
      READ (ACTPAR, '(F10.0)', ERR=97) BBCXMAX
C***  Factor 1.5 refers to definition of unit size for PS fonts
      BBCXMAX = BBCXMAX * 1.5

C***  Add some additional space between the letters in PS-Fonts (in cm)
      ADDSPACE = 0.05
      XWIDTH = BBCXMAX + ADDSPACE
      XWIDTH = XWIDTH * CMPT
      BBCXMAX = BBCXMAX * CMPT

   10 CONTINUE
      CALL PSX_REWIND 
      SPECIAL = ' '
      RETURN

C***  THIS CHARACTER NOT FOUND
   99 CONTINUE
      XWIDTH = 0. 
      BBCXMAX = 0.
      GOTO 10

C***  Error branches
   97 WRITE (*,'(A)') 
     > '>>> Illegal Format in WRPLOT Font File; decoding XWIDTH <<<'
      WRITE (*, '(A)') LINE
      GOTO 100

   90 WRITE (*,'(A)') 
     > '>>> Unexpected E-O-F in PSfont Data File <<<'

  100 STOP 'ERROR in PS_TLEN1PS'

      END
psx_attrib.f/   1553528659  5006  320   100644  8721      `
      SUBROUTINE PSX_ATTRIB (NEXTCHAR, DY, SH, SCX, DXHT, 
     >                       MODE, XSHIFT, ACTSCALE, ACTDRIV)
C*************************************************************************
C***  OWN PS and X11 driver: Interpretation of Text attributes
C***     coded by an Ampersand and subsequent NEXTCHAR;
C***  MODE = 0 : only XSHIFT (in pt) and ACTSCALE are determined 
C***             (for PSX_TEXTLEN)
C***  MODE = 1 : the internal graphic state matrix of is updated
C***  MODE = 2 : graphic-state commands are written to the PS file
C***  Called from: X_SYMBL, PS_SYMBL, PSX_TEXTLEN
C*************************************************************************

C***  PS-File channel number
      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA

C***  Communication with NEWPEN Routine
      COMMON / COMPEN / LASTPEN, HALFLINW

C***  Last text attribute status (for special use by WRPLOT)
      COMMON / COMATT / ATTCOLOR, ATTINCL, ATTWIDTH, ATTSUB, ATTBOLD, 
     >                  ALLATT
      CHARACTER*2 ATTCOLOR, ATTINCL, ATTWIDTH, ATTSUB, ATTBOLD
      CHARACTER   ALLATT*8

C***  Conversion factor cm -> pt
      COMMON / COMCMPT / CMPT

      CHARACTER NEXTCHAR*1, ACTDRIV*(*)

C***  Note: This 'Bold' is only for WRPLOT font via linewidth
      LOGICAL BOLD, CHRINSTR 
      SAVE BOLD

      DATA BOLD  /.FALSE./

      DX = .0 

C************************
C***  Hoch 
C************************
      IF (NEXTCHAR .EQ. 'H') THEN
         ATTSUB = '&H'
C***     Von M auf H
         IF (DY .EQ. .0) THEN 
            DXHT = .0 
            DY = 0.7 * CMPT
            CALL PSX_TRANSLAT (DX, DY, MODE)
            SC = 0.6
            CALL PSX_SCALE (SC, SC, MODE, ACTSCALE)
            IF (MODE .EQ. 1) THEN
               IF (ACTDRIV .EQ. 'X11OWN') THEN
                  CALL acc_xsetlinewidth (SC*2.*HALFLINW)
                  ELSE
                  WRITE (KPS, '(F5.1, A)') SC*2.*HALFLINW, 
     >                ' setlinewidth % Superscript'
                  ENDIF
               ENDIF
C***     Von T auf H
         ELSE IF (DY .LT. .0) THEN 
            DX = -DXHT
            DY = CMPT 
            DYSCALED = DY / 0.6
            CALL PSX_TRANSLAT (DX, DYSCALED, MODE)
            DY = 0.7 * CMPT
            ENDIF
C************************
C***  Tief 
C************************
      ELSE IF (NEXTCHAR .EQ. 'T') THEN
         ATTSUB = '&T'
C***     Von M auf T
         IF (DY .EQ. .0) THEN 
            DXHT = .0 
            DY = -0.3 * CMPT
            CALL PSX_TRANSLAT (DX, DY, MODE)
            SC = 0.6
            CALL PSX_SCALE (SC, SC, MODE, ACTSCALE)
            IF (MODE .EQ. 1) THEN
               IF (ACTDRIV .EQ. 'X11OWN') THEN
                  CALL acc_xsetlinewidth (SC*2.*HALFLINW)
                  ELSE
                  WRITE (KPS, '(F5.1, A)') SC*2.*HALFLINW, 
     >                ' setlinewidth % Subscript'
                  ENDIF
               ENDIF
C***     Von H auf T
         ELSE IF (DY .GT. .0) THEN 
            DX = -DXHT
            DY = -CMPT 
            DYSCALED = DY / 0.6
            CALL PSX_TRANSLAT (DX, DYSCALED, MODE)
            DY = -0.3 * CMPT
            ENDIF
C************************
C***  Mitte
C************************
      ELSE IF (NEXTCHAR .EQ. 'M') THEN
         ATTSUB = '  '
         IF (DY .NE. .0) THEN 
            SC = 1. / 0.6 
            CALL PSX_SCALE (SC, SC, MODE, ACTSCALE)
            DX = 0.2 * CMPT
            DY = -DY
            CALL PSX_TRANSLAT (DX, DY, MODE)
            DY = 0.
            DXHT = DXHT + DX
            IF (MODE .EQ. 1) THEN
               IF (ACTDRIV .EQ. 'X11OWN') THEN
                  CALL acc_xsetlinewidth (2.*HALFLINW)
                  ELSE
                  WRITE (KPS, '(F5.1, A)') 2.*HALFLINW, 
     >                ' setlinewidth % Middle'
                  ENDIF
               ENDIF
            ENDIF
C************************
C***  Rechtsgeneigt 
C************************
      ELSE IF (NEXTCHAR .EQ. 'R' .OR. NEXTCHAR .EQ. 'I') THEN
         ATTINCL = '&'//NEXTCHAR
C***     vorher gerade
         IF (SH .EQ. .0) THEN 
            SH = 0.25
            CALL PSX_SHEER (SH, MODE)
C***     vorher Linksgeneigt
         ELSE IF (SH .LT. .0) THEN 
            SH = 0.5
            CALL PSX_SHEER (SH, MODE)
            SH = 0.25
            ENDIF
C************************
C***  Linksgeneigt 
C************************
      ELSE IF (NEXTCHAR .EQ. 'L') THEN
         ATTINCL = '&'//NEXTCHAR
C***     vorher gerade
         IF (SH .EQ. .0) THEN 
            SH = -0.25
C***        Italian Increment 
            DX = -SH * CMPT
            DY = 0. 
            CALL PSX_TRANSLAT (DX, DY, MODE)
            DXHT = DXHT + DX
            CALL PSX_SHEER (SH, MODE)
C***     vorher Rechtsgeneigt
         ELSE IF (SH .GT. .0) THEN 
            SH = -0.5
C***        Italian Increment 
            DX = -SH * CMPT
            DY = 0.
            CALL PSX_TRANSLAT (DX, DY, MODE)
            DXHT = DXHT + DX
            CALL PSX_SHEER (SH, MODE)
            SH = -0.25
            ENDIF
C************************
C***  Eng 
C************************
      ELSE IF (NEXTCHAR .EQ. 'E') THEN
         ATTWIDTH = '&'//NEXTCHAR
C***     Vorher normal
         IF (SCX .EQ. 1.) THEN 
            SCX = 0.7
            SCY = 1.
            CALL PSX_SCALE (SCX, SCY, MODE, ACTSCALE)
C***     Vorher weit
         ELSE IF (SCX .GT. 1.) THEN 
            SCX = 0.5 
            SCY = 1.
            CALL PSX_SCALE (SCX, SCY, MODE, ACTSCALE)
            SCX = 0.7
            ENDIF
C************************
C***  Breit 
C************************
      ELSE IF (NEXTCHAR .EQ. 'B') THEN
         ATTWIDTH = '&'//NEXTCHAR
C***     Vorher normal
         IF (SCX .EQ. 1.) THEN 
            SCX = 1.4
            SCY = 1. 
            CALL PSX_SCALE (SCX, SCY, MODE, ACTSCALE)
            ELSE IF (SCX .LT. 1.) THEN 
            SCX = 2. 
            SCY = 1. 
            CALL PSX_SCALE (SCX, SCY, MODE, ACTSCALE)
            SCX = 1.4
            ENDIF
C************************
C***  Fett (Historisch: "W" fuer Wiederholt zeichnen)
C***  Bei WRPLOT-Fonts: B=Breit und dickerer Stift
C************************
      ELSE IF (NEXTCHAR .EQ. 'W') THEN
         ATTWIDTH = '&'//NEXTCHAR
         IF (MODE .EQ. 1) THEN 
            IF (ACTDRIV .EQ. 'X11OWN') THEN
               CALL acc_xsetlinewidth (2.8*HALFLINW)
               ELSE
               WRITE (KPS, '(F5.1, A)') 2.8*HALFLINW, 
     >                ' setlinewidth % Bold'
               ENDIF
            BOLD = .TRUE.
            ENDIF
C***     Vorher normal-weit
         IF (SCX .EQ. 1.) THEN 
            SCX = 1.4
            SCY = 1. 
            CALL PSX_SCALE (SCX, SCY, MODE, ACTSCALE)
C***     Vorher eng
         ELSE IF (SCX .LT. 1.) THEN 
            SCX = 2. 
            SCY = 1. 
            CALL PSX_SCALE (SCX, SCY, MODE, ACTSCALE)
            SCX = 1.4
            ENDIF
C************************
C***  Normal 
C************************
      ELSE IF (NEXTCHAR .EQ. 'N' .OR. NEXTCHAR .EQ. 'G') THEN
         ATTINCL = '&G'
C***     Beseitige Neigung 
         IF (SH .NE. .0) THEN 
C***        Vorher rechts geneigt: Italian Increment 
            IF (SH .GT. .0) THEN
               DX = SH * CMPT
               DY = 0.
               CALL PSX_TRANSLAT (DX, DY, MODE)
               DXHT = DXHT + DX
               ENDIF
            SH = -SH
            CALL PSX_SHEER (SH, MODE)
            SH = 0.
            ENDIF
C***  Beseitige Eng/Weit/Fett
         IF (NEXTCHAR .EQ. 'N') THEN
            ATTWIDTH = '&N'
            IF (SCX .NE. 1.) THEN 
               IF (MODE .EQ. 1 .AND. BOLD) THEN 
                  IF (ACTDRIV .EQ. 'X11OWN') THEN
                     CALL acc_xsetlinewidth (2.*HALFLINW)
                     ELSE
                     WRITE (KPS, '(F5.1, A)') 2.*HALFLINW, 
     >                      ' setlinewidth % End Bold'
                     ENDIF
                  BOLD = .FALSE.
                  ENDIF
               SCX = 1. / SCX
               SCY = 1. 
               CALL PSX_SCALE (SCX, SCY, MODE, ACTSCALE)
               SCX = 1.
               ENDIF
            ENDIF
C************************
C***  Boldface PS fonts ("FETT") 
C************************
      ELSE IF (NEXTCHAR .EQ. 'F') THEN
         ATTBOLD = '&F'
      ELSE IF (NEXTCHAR .EQ. 'f') THEN
         ATTBOLD = '  '
C********************************
C***   Change color within string
C********************************
      ELSE IF ( CHRINSTR(NEXTCHAR, '0123456789') ) THEN
         ATTCOLOR = '&'//NEXTCHAR
         IF (MODE .NE. 0) THEN
            READ (NEXTCHAR, '(I1)') ICOLOR
            CALL COLOR ('DATA', ' ', ICOLOR, IDUMMY)
            ENDIF
      ENDIF

      XSHIFT = DX

      RETURN
      END

psx_clipaux.f/  1553528659  5006  320   100644  2232      `
      SUBROUTINE PSX_CLIPAUX (X1, Y1, X2, Y2, XS1, YS1, XS2, YS2, NS)
C*********************************************************************
C***  Auxiliary subroutine for PS driver (clipping formalism, PSPLOT):
C***  The NS = 0, 1 or 2 intersection points (XS1,YS1) and (XS2,YS2) 
C***  of the line from (X1,Y1) to (X2,Y2) are determined
C*********************************************************************

C***  Clipping Path (ICLIP=1: Full Paper; 2: special clipping)
      COMMON / COMCLIP / ICLIP, CXMIN(2), CXMAX(2), CYMIN(2), CYMAX(2)

      XMIN = CXMIN(ICLIP)
      XMAX = CXMAX(ICLIP)
      YMIN = CYMIN(ICLIP)
      YMAX = CYMAX(ICLIP)
      NS = 0

      DX = X2 - X1
      DY = Y2 - Y1

C***  Vertical line: never intersects XMIN or XMAX
      IF (DX .EQ. .0) GOTO 1

C***  INTERSECTION WITH XMIN = CONSTANT
      YS = Y1 + DY * (XMIN-X1) / DX
      IF (     (YS-YMIN) * (YS-YMAX) .LE. 0.
     >   .AND. (XMIN-X1) * (XMIN-X2) .LE. 0. ) THEN
         NS = 1
         XS1 = XMIN
         YS1 = YS
         ENDIF

C***  INTERSECTION WITH XMAX = CONSTANT
      YS = Y1 + DY * (XMAX-X1) / DX
      IF (     (YS-YMIN) * (YS-YMAX) .LE. 0.
     >   .AND. (XMAX-X1) * (XMAX-X2) .LE. 0. ) THEN
         NS = NS + 1
         IF (NS .EQ. 1) THEN
           XS1 = XMAX
           YS1 = YS
           ELSE
           XS2 = XMAX
           YS2 = YS
           ENDIF
         ENDIF

C***  Horizontal line: never intersects YMIN or YMAX
    1 CONTINUE
      IF (DY .EQ. .0) GOTO 2

C***  INTERSECTION WITH YMIN = CONSTANT
      XS = X1 + DX * (YMIN-Y1) / DY
      IF (     (XS-XMIN) * (XS-XMAX) .LE. 0.
     >   .AND. (YMIN-Y1) * (YMIN-Y2) .LE. 0. ) THEN
         NS = NS + 1
         IF (NS .EQ. 1) THEN
           XS1 = XS
           YS1 = YMIN
           ELSE
           XS2 = XS
           YS2 = YMIN
           ENDIF
         ENDIF

C***  INTERSECTION WITH YMAX = CONSTANT
      XS = X1 + DX * (YMAX-Y1) / DY
      IF (     (XS-XMIN) * (XS-XMAX) .LE. 0.
     >   .AND. (YMAX-Y1) * (YMAX-Y2) .LE. 0. ) THEN
         NS = NS + 1
         IF (NS .EQ. 1) THEN
           XS1 = XS
           YS1 = YMAX
           ELSE
           XS2 = XS
           YS2 = YMAX
           ENDIF
         ENDIF

    2 CONTINUE

      RETURN
      END
psx_grestore.f/ 1553528659  5006  320   100644  753       `
      SUBROUTINE PSX_GRESTORE (MODE)
C*************************************************************************
C***  OWN PS and X11 driver: Restore Graphic State
C***  MODE = 1 : the internal graphic state matrix of is updated
C***  MODE = 2 : graphic-state commands are written to the PS file
C*************************************************************************

C***  Output Channel Number
      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA
      
      IF (MODE .EQ. 0) THEN 
C***     No action
      ELSE IF (MODE .EQ. 1) THEN 
         CALL GS_RESTORE
      ELSE IF (MODE .EQ. 2) THEN 
         CALL GS_RESTORE
         WRITE (KPS, '(A)') 'grestore' 
      ELSE
         STOP 'ERROR IN PSX_GRESTORE'
      ENDIF

      RETURN
      END

psx_gsave.f/    1553528659  5006  320   100644  735       `
      SUBROUTINE PSX_GSAVE (MODE)
C*************************************************************************
C***  OWN PS and X11 driver: Save Graphic State
C***  MODE = 1 : the internal graphic state matrix of is updated
C***  MODE = 2 : graphic-state commands are written to the PS file
C*************************************************************************

C***  Output Channel Number
      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA
      
      IF (MODE .EQ. 0) THEN 
C***     No action
      ELSE IF (MODE .EQ. 1) THEN 
         CALL GS_SAVE
      ELSE IF (MODE .EQ. 2) THEN 
         CALL GS_SAVE
         WRITE (KPS, '(A)') 'gsave' 
      ELSE
         STOP 'ERROR IN PSX_GSAVE'
      ENDIF

      RETURN
      END

psx_read.f/     1553528659  5006  320   100644  2481      `
      SUBROUTINE PSX_READ (KFONT, LINE, EOF)
C******************************************************************
C***  Own PS and X11 Driver: Reads next line from the Font File 
C***      which has been written to the Memory (Character Array)
C******************************************************************

C***  Note: The same Parameters occur in SUBR. PSX_OPEWRFONT
      PARAMETER (MAXASCII = 2000)
      PARAMETER (MAXGREEK = 2500)
      PARAMETER (MAXAMPER = 400)
      PARAMETER (MAXSLASH = 300)
      CHARACTER*16 WR_ASCII(MAXASCII), WR_GREEK(MAXGREEK)
      CHARACTER*16 WR_AMPER(MAXAMPER), WR_SLASH(MAXSLASH)
      COMMON / WRFONTDAT / WR_ASCII, WR_GREEK, WR_AMPER, WR_SLASH

      PARAMETER (MAXASCPS = 400)
      PARAMETER (MAXGREPS = 400)
      PARAMETER (MAXAMPPS = 200)
      PARAMETER (MAXSLAPS = 200)
      PARAMETER (MAXITAPS = 400)
      CHARACTER*16 PS_ASCII(MAXASCPS), PS_GREEK(MAXGREPS)
      CHARACTER*16 PS_AMPER(MAXAMPPS), PS_SLASH(MAXSLAPS)
      CHARACTER*16 PS_ITALI(MAXITAPS) 
      COMMON / PSFONTDAT / PS_ASCII, PS_GREEK, PS_AMPER, PS_SLASH, 
     >                     PS_ITALI

      CHARACTER LINE*(*)

      COMMON / POINTER / IPOINT
      
      LOGICAL EOF

      IF (KFONT .EQ. 21) THEN
         EOF = IPOINT .GT. MAXASCII
         IF (EOF) RETURN
         LINE = WR_ASCII(IPOINT)
      ELSE IF (KFONT .EQ. 22) THEN
         EOF = IPOINT .GT. MAXGREEK
         IF (EOF) RETURN
         LINE = WR_GREEK(IPOINT)
      ELSE IF (KFONT .EQ. 23) THEN
         EOF = IPOINT .GT. MAXAMPER
         IF (EOF) RETURN
         LINE = WR_AMPER(IPOINT)
      ELSE IF (KFONT .EQ. 24) THEN
         EOF = IPOINT .GT. MAXSLASH
         IF (EOF) RETURN
         LINE = WR_SLASH(IPOINT)
      ELSE IF (KFONT .EQ. 31) THEN
         EOF = IPOINT .GT. MAXASCPS
         IF (EOF) RETURN
         LINE = PS_ASCII(IPOINT)
      ELSE IF (KFONT .EQ. 32) THEN
         EOF = IPOINT .GT. MAXGREPS
         IF (EOF) RETURN
         LINE = PS_GREEK(IPOINT)
      ELSE IF (KFONT .EQ. 33) THEN
         EOF = IPOINT .GT. MAXAMPPS
         IF (EOF) RETURN
         LINE = PS_AMPER(IPOINT)
      ELSE IF (KFONT .EQ. 34) THEN
         EOF = IPOINT .GT. MAXSLAPS
         IF (EOF) RETURN
         LINE = PS_SLASH(IPOINT)
      ELSE IF (KFONT .EQ. 35) THEN
         EOF = IPOINT .GT. MAXITAPS
         IF (EOF) RETURN
         LINE = PS_ITALI(IPOINT)
      ELSE
         STOP 'ILLEGAL VALUE OF KFONT IN PSX_READ'
      ENDIF

      IPOINT = IPOINT + 1


      RETURN
      END

psx_rewind.f/   1553528659  5006  320   100644  377       `
      SUBROUTINE PSX_REWIND
C******************************************************************
C***  Own PS and X11 Driver: Sets pointer at the beginning of font data
C***      which have been written to the Memory (Character Array)
C******************************************************************

      COMMON / POINTER / IPOINT

      IPOINT = 1

      RETURN
      END

psx_rotate.f/   1553528659  5006  320   100644  905       `
      SUBROUTINE PSX_ROTATE (ANGLE, MODE)
C*************************************************************************
C***  OWN PS and X11 driver: Rotation
C***  MODE = 0 : only TEXTLEN is determined (for PS_TEXTLEN)
C***  MODE = 1 : the internal graphic state matrix of is updated
C***  MODE = 2 : graphic-state commands are written to the PS file
C***             AND the internal graphic state matrix of is updated
C*************************************************************************

C***  Transformation coefficients 
      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA
      
      IF (MODE .EQ. 0) THEN 
C***     No action
      ELSE IF (MODE .EQ. 1) THEN 
         CALL GS_ROTATE (ANGLE)
      ELSE IF (MODE .EQ. 2) THEN 
         WRITE (KPS, '(F5.1, A)') ANGLE, ' rotate'
         CALL GS_ROTATE (ANGLE)
      ELSE
         STOP 'ERROR IN PSX_ROTATE'
      ENDIF

      RETURN
      END

psx_saveatt.f/  1553528659  5006  320   100644  1165      `
      SUBROUTINE PSX_SAVEATT
C********************************************************************
C***  Constructs a string with the actual text attributes 
C**   as provided by PSX_ATTRIB in the special COMMON-Block
C********************************************************************
C***  Last text attribute status (for special use by WRPLOT)
      COMMON / COMATT / ATTCOLOR, ATTINCL, ATTWIDTH, ATTSUB, ATTBOLD, 
     >                  ALLATT
      CHARACTER*2 ATTCOLOR, ATTINCL, ATTWIDTH, ATTSUB, ATTBOLD 
      CHARACTER   ALLATT*10
      
      ALLATT = ' '
      NATT = 0
      IF (ATTCOLOR .NE. '  ') THEN
         ALLATT = ATTCOLOR
         NATT = 2
         ENDIF
      IF (ATTWIDTH .NE. '  ' .AND. ATTWIDTH .NE. '&N') THEN
         ALLATT(NATT+1:) = ATTWIDTH
         NATT = NATT + 2
         ENDIF
      IF (ATTINCL .NE. '  ') THEN
         ALLATT(NATT+1:) = ATTINCL
         NATT = NATT + 2
         ENDIF
      IF (ATTSUB .NE. '  ') THEN
         ALLATT(NATT+1:) = ATTSUB
         NATT = NATT + 2
         ENDIF
      IF (ATTBOLD .NE. '  ') THEN
         ALLATT(NATT+1:) = ATTBOLD
         NATT = NATT + 2
         ENDIF
 
      RETURN
      END

psx_scale.f/    1553528659  5006  320   100644  898       `
      SUBROUTINE PSX_SCALE (SX, SY, MODE, ACTSCALE)
C*************************************************************************
C***  OWN PS and X11 driver: translation (called from: PSX_ATTRIB
C***  MODE = 0 : only TEXTLEN is determined (for PS_TEXTLEN)
C***  MODE = 1 : the internal graphic state matrix of is updated
C***  MODE = 2 : graphic-state commands are written to the PS file
C*************************************************************************

C***  Transformation coefficients 
      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA
      
      IF (MODE .EQ. 0) THEN 
         ACTSCALE = ACTSCALE * SX
      ELSE IF (MODE .EQ. 1) THEN 
         CALL GS_SCALE (SX, SY)
      ELSE IF (MODE .EQ. 2) THEN 
         CALL GS_SCALE (SX, SY)
         WRITE (KPS, '(F8.4, 1X, F8.4, A)') SX, SY, ' scale'
      ELSE
         STOP 'ERROR IN PSX_SCALE'
      ENDIF

      RETURN
      END
psx_sheer.f/    1553528659  5006  320   100644  879       `
      SUBROUTINE PSX_SHEER (SH, MODE)
C*************************************************************************
C***  OWN PS and X11 driver: translation (called from: PSX_ATTRIB
C***  MODE = 0 : only TEXTLEN is determined (for PS_TEXTLEN)
C***  MODE = 1 : the internal graphic state matrix of is updated
C***  MODE = 2 : graphic-state commands are written to the PS file
C*************************************************************************

C***  Transformation coefficients 
      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA
      
      IF (MODE .EQ. 0) THEN 
C***     No effect on TEXTLEN
      ELSE IF (MODE .EQ. 1) THEN 
         CALL GS_SHEER (SH)
      ELSE IF (MODE .EQ. 2) THEN 
         CALL GS_SHEER (SH)
         WRITE (KPS, '(A, F6.3,  A)') '[1 0 ', SH, ' 1 0 0] concat'
      ELSE
         STOP 'ERROR IN PSX_SHEER'
      ENDIF

      RETURN
      END

psx_textlen.f/  1553528659  5006  320   100644  4433      `
      SUBROUTINE PSX_TEXTLEN (TEXTLEN, SIZE, STRPAR, ACTDRIV)
C********************************************************************
C***  PS and X11 Driver: determine length TEXTLEN (in cm) 
C***                     of string STRPAR for actual SIZE
C***  Called from: PS_TEXTLEN and X_TEXTLEN
C********************************************************************

C***  Transformation coefficients 
      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA
      
C***  Conversion factor cm -> pt
      COMMON / COMCMPT / CMPT

C***  Blocktext and SQUEEZE-Parameter from KDPLOT (TEXT option)
      COMMON / COMBLOCK / BBLOCK, SQUEEZE

C***  Default Font set by KASDEF Option
      COMMON / COMFONT / FONT 
      CHARACTER FONT*6, ACTFONT*6, BSL*1

      CHARACTER STRPAR*(*), ONECHAR*1, SPECIAL*1, NEXTCHAR*1
      CHARACTER ACTDRIV*(*)
      LOGICAL GREEK, CHRINSTR, ITALIC, BBLOCK

      SAVE

C***  Backslash Character
      BSL = CHAR(92)

C***  Starting Value
      TEXTLEN = .0

C***  Zero string or Zero size --> Zero length
      LAST = IDX(STRPAR)
      IF (LAST .LE. 0 .OR. SIZE .LE. .0) RETURN

C***  Defaults
      ACTSIZE = SIZE * FORMATFA
      GREEK  = .FALSE. 
      ITALIC = .FALSE. 
      SPECIAL = ' '
      DXHT = .0
      DY = 0.
      SH = 0.
      SCX = 1. 
      ACTSCALE = 1. 
      ACTFONT = 'WRPLOT'
      ISTART = 1
      IF (FONT .EQ. 'TIMES' .OR. FONT .EQ. 'HELVET' .OR.
     >    FONT .EQ. 'COURIE' .OR. FONT .EQ. 'ZAPF  ') ACTFONT = FONT

C***  Local Font select
      IF (STRPAR(:3) .EQ. '&PT') THEN
         ACTFONT = 'TIMES'
         ISTART = 4
      ELSE IF (STRPAR(:3) .EQ. '&PH') THEN
         ACTFONT = 'HELVET'
         ISTART = 4
      ELSE IF (STRPAR(:3) .EQ. '&PC') THEN
         ACTFONT = 'COURIE'
         ISTART = 4
      ELSE IF (STRPAR(:3) .EQ. '&PW') THEN
         ACTFONT = 'WRPLOT'
         ISTART = 4
         ENDIF

      IF (ACTDRIV . EQ. 'X11OWN') ACTFONT = 'WRPLOT'

C***  Open Fonts
      IF (ACTFONT .EQ. 'WRPLOT') THEN 
         CALL PSX_OPEWRFNT (ACTSIZE)
      ELSE 
         CALL PS_OPEPSFONT (ACTSIZE, ACTFONT)
      ENDIF

C********************************************************************
C***  Examine string Character by Character 
C********************************************************************

C***  Begin Loop I=1 ... LAST
      I = ISTART
   10 CONTINUE
      ONECHAR = STRPAR(I:I)
      IF (ONECHAR .EQ. '#') THEN 
         GREEK = .NOT. GREEK
         GOTO 1
         ENDIF
C***  Decode Ampersand-Switches for Text Attributes
      IF (ONECHAR .EQ. '&' .AND. I .LT. LAST .AND. SPECIAL .EQ. ' ') 
     >   THEN
         NEXTCHAR = STRPAR(I+1:I+1)
C***     Switch for Italic font
         IF (NEXTCHAR .EQ. 'I' .AND. .NOT. GREEK .AND. 
     >       ACTFONT .NE. 'WRPLOT') THEN
            ITALIC = .TRUE. 
            I = I + 1
            GOTO 1
            ENDIF
C***     Switch back from Italic font
         IF (NEXTCHAR .EQ. 'N' .AND. ITALIC) THEN 
            ITALIC = .FALSE. 
            ENDIF

         IF ( CHRINSTR(NEXTCHAR, 'IGHTMNLREBW0123456789') ) THEN
             MODE = 0
             CALL PSX_ATTRIB (NEXTCHAR, DY, SH, SCX, DXHT, 
     >                        MODE, XSHIFT, ACTSCALE, ACTDRIV)
             TEXTLEN = TEXTLEN + XSHIFT * ACTSCALE
             I = I + 1
             GOTO 1
             ENDIF
          ENDIF
ccc      IF (ONECHAR .EQ. '&' .OR. ONECHAR .EQ. BSL) THEN 
      IF ( (SPECIAL .NE. '&' .AND. ONECHAR .EQ. '&') .OR.
     >     (SPECIAL .NE. BSL .AND. ONECHAR .EQ. BSL) ) THEN
         SPECIAL = ONECHAR
         GOTO 1
         ENDIF

C***  Postscript Fonts *******************
      IF (ACTFONT .NE. 'WRPLOT') THEN
         CALL PS_TLEN1PS (ONECHAR, GREEK, 
     >                     SPECIAL, ITALIC, XWIDTH, BBCXMAX) 

C***  WRPLOT Fonts *******************
      ELSE
         CALL PSX_TLEN1WR (ONECHAR, GREEK, 
     >                     SPECIAL, XWIDTH, BBCXMAX) 
      ENDIF

      DXHT = DXHT + XWIDTH
      TEXTLEN = TEXTLEN + XWIDTH * ACTSCALE

    1 I = I + 1
      IF (I .LE. LAST) GOTO 10
C***  End-of-Loop over the single characters ********************


C***  Subract last XWIDTH and replace it by BBCXMAX
      TEXTLEN = TEXTLEN + ACTSCALE * (BBCXMAX - XWIDTH)
C***  Scale for Fontsize, convert pt --> cm
      TEXTLEN = TEXTLEN * SIZE / CMPT

      TEXTLEN = TEXTLEN * SQUEEZE

C***  Save actual text attributes (for optional use outside driver)
      CALL PSX_SAVEATT

      RETURN
      END

psx_tlen1wr.f/  1553528659  5006  320   100644  2003      `
      SUBROUTINE PSX_TLEN1WR (ONECHAR, GREEK, SPECIAL, XWIDTH, 
     >                     BBCXMAX)
C********************************************************************
C***  PSOWN DRIVER: Measure XWIDTH (in pt, for unit-SIZE) 
C***                of one character (WRPLOT Font)
C***                 Called from: PSX_TEXTLEN
C********************************************************************

      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA
      LOGICAL GREEK, EOF

      CHARACTER LINE*22, ONECHAR*1, SPECIAL*1, ACTPAR*10
      CHARACTER*1 BSL

C***  Backslash-Character
      BSL = CHAR(92)

C***  Channel Numbers for WRPLOT Font Data: 20+KFONT
C***    with KFONT: 1=Normal, 2=Greek, 3=Ampersand, 4=Backslash
      KFONT = 21
      IF (GREEK) KFONT = 22
      IF (SPECIAL .EQ. '&') KFONT = 23 
      IF (SPECIAL .EQ. BSL) KFONT = 24 

C***  SEARCH FOR CHARACTER
    1 CALL PSX_READ (KFONT, LINE, EOF)
      IF (EOF) GOTO 99
      IF (LINE(1:3) .NE. '*'//ONECHAR) GOTO 1

C***  SKIP Move/Draw lines
    2 CALL PSX_READ (KFONT, LINE, EOF)
      IF (EOF) GOTO 90
      IF (LINE(1:1) .EQ. '%') GOTO 3
      GOTO 2

C***  Decode BBCXMAX (BoundingBox width, for last character in string)
    3 CONTINUE
      CALL SARGV (LINE, 3, ACTPAR)
      READ (ACTPAR, '(F10.0)', ERR=96) BBCXMAX
C***  read xwidth
      CALL PSX_READ (KFONT, LINE, EOF)
      IF (EOF) GOTO 90
      CALL SARGV (LINE, 3, ACTPAR)
      READ (ACTPAR, '(F10.0)', ERR=97) XWIDTH

   10 CONTINUE
      CALL PSX_REWIND 
      SPECIAL = ' '
      RETURN

C***  THIS CHARACTER NOT FOUND
   99 CONTINUE
      XWIDTH = 0. 
      GOTO 10

   96 WRITE (*,'(A)') 
     > '>>> Illegal Format in WRPLOT Font File; decoding BBCMAX <<<'
      WRITE (*, '(A)') LINE
      GOTO 100

   97 WRITE (*,'(A)') 
     > '>>> Illegal Format in WRPLOT Font File; decoding XWIDTH <<<'
      WRITE (*, '(A)') LINE
      GOTO 100

   90 WRITE (*,'(A)') 
     > '>>> Unexpected E-O-F in WRPLOT Font File <<<'

  100 STOP 'ERROR in PSX_TLEN1WR'

      END

readbox.f/      1555515443  5006  320   100644  10339     `
      SUBROUTINE READBOX (NRUNIT, HEADER, XTEXT, YTEXT, B, C, 
     $                    NOTICKX, NOTICKY, 
     >                    NOTICK2X, NOTICK2Y, KDLINE, NKD, NKDMAX, 
     >                    NOLABX, NOLABY, VAR, MAXVAR, NVAR, AUTOSCALE,
     >                    NOMINMAX, ALTX, ALTY)
 
C***********************************************************************
C***  WRPLOT PROGRAM: 
C***  THIS SUBROUTINE IS ENTERED AFTER A "PLOT" OPTION HAS INDICATED
C***     THE BEGINNING OF A NEW PLOT.
C***     FIRST, ANY "KASDEF" OPTIONS ARE DECODED.
C***     AFTER A "HEADER" LINE HAS BEEN DETECTED, THE AXIS DATA ARE 
C***     EXPECTED.
C***  THIS SUBROUTINE IS CALLED FROM SUBROUTINE READDATA.
C***********************************************************************

      CHARACTER*(*) VAR(MAXVAR,2)
      CHARACTER*(*) HEADER, XTEXT, YTEXT, AUTOSCALE
      DIMENSION B(6),C(6)
      CHARACTER KDLINE(NKDMAX)*132 
      CHARACTER ACTION*100, ACTPAR*40, LINE*132
      LOGICAL NOTICKX, NOTICKY, NOLABX, NOLABY, BDEFAULTS
      LOGICAL NOTICK2X, NOTICK2Y, ALTX, ALTY
      LOGICAL NOMINMAX(10)
c     NOMINMAX: 1 - NOMIN (x) | 2 - NOMAX (x) | 3 - NOMIN (y) | 4 - NOMAX (y)
c     removes the according labels (usefull for MULTIPLOT - stacking)
c     NOMINMAX: 5 - MININD (x) | 6 - MAXIND (x) | 7 - MININD (y) | 8 - MAXIND (y)
C     indents deeper the according labels (usefull for MULTIPLOT - stacking)
c     NOMINMAX: 9 - MAXNOIND (x) | 10 - MAXNOIND (y)
c     turns off the usual indent for x_max and y_max

      NOTICKX = .FALSE.
      NOTICKY = .FALSE.
      NOTICK2X = .FALSE.
      NOTICK2Y = .FALSE.
      NOLABX = .FALSE.
      NOLABY = .FALSE.
      ALTX   = .FALSE.
      ALTY   = .FALSE.
      DO I=1,10
       NOMINMAX(I) = .FALSE.
      ENDDO
      AUTOSCALE = 'NONE'
      ACTION = 'NONE'
      BDEFAULTS = .FALSE.

C***  NUMBER OF KASDEF OPTIONS DETECTED:
      NKD = 0

C***  READ BOX DESCRIPTION
20    READ (NRUNIT,'(A)',END=99) LINE

C***  SKIP COMMENT LINES
      IF (LINE(1:1) .EQ. '*' .OR. IDX(LINE) .EQ. 0) GOTO 20

C***  SKIP LEADING BLANKS
      IF (LINE(1:1) .EQ. ' ') THEN 
         CALL SARGP (LINE, NDUMMY, 1, IFIRST, ILAST)
         LINE = LINE (IFIRST:)
      ENDIF

      IF (LINE(:3) .EQ. 'END') THEN
         IF (BDEFAULTS) THEN
            BACKSPACE (NRUNIT)
            RETURN
	 ELSE
	    GOTO 97
	 ENDIF
      ENDIF
      
C***  SKIP REDUNDANT "PLOT" LINE (PURPOSE: IF PLOT ALREADY OPENED FOR KASDEF'S)
      IF (LINE(1:4) .EQ. 'PLOT') GOTO 20
      
C***  Start reading Plot header
      IF (LINE(1:6) .EQ. 'HEADER') GOTO 21

C***  Reading of "KASDEF" options

C***  Substitute leading backslash
      IF (LINE(1:1) .EQ. CHAR(92)) THEN
        LINE = 'KASDEF ' // LINE(2: )
      ENDIF

      IF (LINE(1:6) .EQ. 'KASDEF') THEN
C***     Check for DEFAULTS option, ignore empty KASDEF commands
         CALL SARGC (LINE, NPAR)
	 IF (NPAR .GE. 2) THEN
	    CALL SARGV (LINE, 2, ACTPAR)
            IF (ACTPAR .EQ. 'DEFAULTS') THEN
               BDEFAULTS = .TRUE.
            WRITE (*,*)  'DEFAULTS APPLY!'
            LINE = 'KASDEF NOBOX'
            CALL READKD (LINE, KDLINE, NKD, NKDMAX, VAR, MAXVAR, NVAR)
            LINE = 'KASDEF OFS .0 .0'
            CALL READKD (LINE, KDLINE, NKD, NKDMAX, VAR, MAXVAR, NVAR) 
            B(1) = 1.
            B(2) = 0.
            B(3) = 10.
            C(1) = 1.
            C(2) = 0.
            C(3) = 10.
            HEADER = ' '
            XTEXT  = ' '
            YTEXT  = ' '
            ELSE
               CALL READKD 
     >              (LINE, KDLINE, NKD, NKDMAX, VAR, MAXVAR, NVAR)
            ENDIF
         ENDIF

      ELSEIF (BDEFAULTS) THEN 
C***     Datasets may occur at any time if DEFAULTS was chosen
         CALL SARGV (LINE, 1, ACTPAR)
         IF (ACTPAR .EQ. 'N') THEN
            CALL SARGC (LINE, NPAR)
	    IF (NPAR .GE. 2) THEN
               BACKSPACE (NRUNIT)
               RETURN
            ELSE
               WRITE (6,*) '*** WARNING ******************'
               WRITE (6,*) '*** Line with first argument "N" detected,'
               WRITE (6,*) '*** but more arguments are needed '
               WRITE (6,*) '*** to start a dataset. The line was:'
               WRITE (6,*) LINE
            ENDIF 
         ELSE
	    GOTO 19 
         ENDIF
C***  Error message
      ELSE
   19    WRITE (6,*) '**************  WARNING ***********************'
         WRITE (6,*) 'UNEXPECTED LINE IN PLACE OF KASDEF OPTION:'
         WRITE (6,*) LINE
      ENDIF
      
      GOTO 20

C***********************************************************************

   21 CONTINUE
      IF (BDEFAULTS) GOTO 95
      ACTION = 'READING HEADER'
      HEADER = LINE(9:)

      ACTION = 'READING XTEXT'
  221 READ (NRUNIT,'(A)', END=97) LINE
C***  SKIP ONE LEADING BLANK
      CALL SARGV (LINE, 1, ACTPAR)
      IF (ACTPAR(1:1) .EQ. '*') GOTO 221
      IF (LINE(1:1) .EQ. ' ') LINE = LINE (2:)
      CALL EXPANDVAR (LINE, VAR, MAXVAR, NVAR)
      XTEXT = LINE(9:)

      ACTION = 'READING YTEXT'
  222 READ (NRUNIT,'(A)', END=97) LINE
C***  SKIP ONE LEADING BLANK
      CALL SARGV (LINE, 1, ACTPAR)
      IF (ACTPAR(1:1) .EQ. '*') GOTO 222
      IF (LINE(1:1) .EQ. ' ') LINE = LINE (2:)
      CALL EXPANDVAR (LINE, VAR, MAXVAR, NVAR)
      YTEXT = LINE(9:)

C     ... COMMENT LINE
      ACTION = 'READING COMMENT LINE'
      IXSHIFT=0
  223 READ (NRUNIT,'(A)', END=97) LINE
      CALL SARGV (LINE, 1, ACTPAR)
      IF (ACTPAR(1:1) .EQ. '*') GOTO 223

C     ...  X-AXIS DATA
      ACTION = 'READING X-AXIS DATA'

  201 READ (NRUNIT,'(A)', END=97) LINE
      CALL SARGV (LINE, 1, ACTPAR)
      IF (ACTPAR(1:1) .EQ. '*') GOTO 201
      CALL EXPANDVAR (LINE, VAR, MAXVAR, NVAR)
      CALL SARGC(LINE,NARG)
C***  CHECK FOR AUTOSCALE
      DO IARG = 2, NARG
         CALL SARGV (LINE, IARG, ACTPAR)
         IF (ACTPAR .EQ. 'AUTO') THEN
            AUTOSCALE = 'AUTO'
         ELSE IF (ACTPAR .EQ. 'AUTOX') THEN
            AUTOSCALE = 'AUTOX'        
         ELSE
            NOTICKX = (ACTPAR .EQ. 'NOTICK') .OR. NOTICKX     
            NOTICK2X = (ACTPAR .EQ. 'NOTICK-BOTH') .OR. NOTICK2X     
            NOLABX  = (ACTPAR(1:5) .EQ. 'NOLAB') .OR. NOLABX
            NOMINMAX(1) = (ACTPAR .EQ. 'NOMIN') .OR. NOMINMAX(1)
            NOMINMAX(2) = (ACTPAR .EQ. 'NOMAX') .OR. NOMINMAX(2) 
            NOMINMAX(5) = (ACTPAR .EQ. 'MININD') .OR. NOMINMAX(5)
            NOMINMAX(6) = (ACTPAR .EQ. 'MAXIND') .OR. NOMINMAX(6)
            NOMINMAX(9) = (ACTPAR .EQ. 'MAXNOIND') .OR. NOMINMAX(9)
            ALTX = (ACTPAR .EQ. 'ALT') .OR. ALTX
         ENDIF  
      ENDDO 
      IF (AUTOSCALE .NE. 'AUTO' .AND.
     >    AUTOSCALE .NE. 'AUTOX') THEN
         DO I=6, 1, -1
            CALL SARGV (LINE, I+1, ACTPAR)
***         ALLOW FOR DATA IN CM
            IF (I .EQ. 1) THEN
               ID = IDX (ACTPAR)
               IF (ACTPAR(ID-1:ID) .EQ. 'CM') THEN
                  ACTPAR(ID-1:ID) = '  '
                  READ (ACTPAR, '(BN,F20.0)', ERR=96) B(I)
                  B(I) = B(I) / (B(3) - B(2))
               ELSE
                  READ (ACTPAR, '(BN,F20.0)', ERR=96) B(I)
               ENDIF
            ELSE
               READ (ACTPAR, '(BN,F20.0)', ERR=96) B(I)
            ENDIF
         ENDDO

C***     IF MASSTAB = 0. THEN PLOT-WIDTH = 20.CM
         IF (B(1) .EQ. 0.) B(1) = 20. / (B(3) - B(2))
      ENDIF


C     ...  Y-AXIS DATA
      ACTION = 'READING Y-AXIS DATA'
  202 READ (NRUNIT,'(A)', END=97) LINE
      CALL SARGV (LINE, 1, ACTPAR)
      IF (ACTPAR(1:1) .EQ. '*') GOTO 202
      CALL EXPANDVAR (LINE, VAR, MAXVAR, NVAR)
      CALL SARGC(LINE,NARG)
C***  Check for AUTOSCALE
      DO IARG = 2, NARG
         CALL SARGV (LINE, IARG, ACTPAR)
         IF (ACTPAR .EQ. 'AUTO' .OR. ACTPAR .EQ. 'AUTOY') THEN
            IF (AUTOSCALE .EQ. 'AUTOX') AUTOSCALE = 'AUTO' 
            IF (AUTOSCALE .NE. 'AUTO') AUTOSCALE = 'AUTOY' 
         ELSE
            NOTICKY = (ACTPAR .EQ. 'NOTICK') .OR. NOTICKY
            NOTICK2Y = (ACTPAR .EQ. 'NOTICK-BOTH') .OR. NOTICK2Y
            NOLABY  = (ACTPAR(1:5) .EQ. 'NOLAB') .OR. NOLABY
            NOMINMAX(3) = (ACTPAR .EQ. 'NOMIN') .OR. NOMINMAX(3)
            NOMINMAX(4) = (ACTPAR .EQ. 'NOMAX') .OR. NOMINMAX(4) 
            NOMINMAX(7) = (ACTPAR .EQ. 'MININD') .OR. NOMINMAX(7)
            NOMINMAX(8) = (ACTPAR .EQ. 'MAXIND') .OR. NOMINMAX(8)
            NOMINMAX(10) = (ACTPAR .EQ. 'MAXNOIND') .OR. NOMINMAX(10)
            ALTY = (ACTPAR .EQ. 'ALT') .OR. ALTY
         ENDIF
      ENDDO
      IF (AUTOSCALE .NE. 'AUTO' .AND.
     >    AUTOSCALE .NE. 'AUTOY') THEN
          DO I=6, 1, -1
             CALL SARGV (LINE, I+1, ACTPAR)
C***         ALLOW FOR DATA IN CM
             IF (I .EQ. 1) THEN
                ID = IDX (ACTPAR)
                IF (ACTPAR(ID-1:ID) .EQ. 'CM') THEN
                   ACTPAR(ID-1:ID) = '  '
                   READ (ACTPAR, '(BN,G20.0)', ERR=96) C(I)
                   C(I) = C(I) / (C(3) - C(2))
                ELSE
                   READ (ACTPAR, '(BN,G20.0)', ERR=96) C(I)
                ENDIF
             ELSE
                READ (ACTPAR, '(BN,G20.0)', ERR=96) C(I)
             ENDIF
          ENDDO

C***      IF MASSTAB = 0. THEN PLOT-HEIGHT = 15.CM
          IF (C(1) .EQ. 0.) C(1) = 15. / (C(3) - C(2))

      ENDIF

C***  NORMAL EXIT after having read the box description
      RETURN

C***********************************************************
C***  ERROR HANDLING ***************************************
C***********************************************************

95    WRITE(*,*) '*** HEADER-Line encountered after DEFAULTS were set'
      WRITE(*,*) '*** Double definition of the coordinates ***'
      STOP '*** FATAL ERROR detected by READBOX'  

98    WRITE(*,*) '*** MORE KASDEF OPTIONS THAN ALLOWED:', NKDMAX
      STOP '*** FATAL ERROR detected by READBOX'  

97    WRITE(*,*) '*** E-O-F OF INPUT FILE REACHED BEFORE HAVING'
      WRITE(*,*) '*** FOUND NEITHER A "DEFAULTS" NOR "HEADER" LINE'
      STOP '*** FATAL ERROR detected by READBOX'  

96    WRITE(*,*) '*** ERROR OCCURED IN READBOX'
      WRITE(*,*) 'THE ERROR OCCURED IN THE FOLLOWING LINE:'
      WRITE(*,*) LINE(:IDX(LINE))
      WRITE(*,*) 'CURRENT ACTION: ', ACTION
      STOP '*** FATAL ERROR detected by READBOX'  

99    WRITE(*,*) 'END statament missing in input file'
      STOP '*** FATAL ERROR detected by READBOX'  

      END

readdata.f/     1755115541  5006  320   100644  23355     `
      SUBROUTINE READDATA (FNAME, NRUNIT, X, Y, X1, Y1, NDAT, NSET, 
     $                    NSETMAX, B, C, ISYMBOL, HEADER, XTEXT, 
     $                    YTEXT, K, NPEN, ICOLOR, PLOTSKAL, OFSX, OFSY,
     $                    MPSTART, MPENDE, MPACTIVE, PSIZEX, PSIZEY,
     $                    FORMATFA, SSIZE, NOTICKX, NOTICKY, 
     >                    NOTICK2X, NOTICK2Y, INBOX,     
     $                    KDLINE, NKD, NKDMAX, NDATMAX, IDEV, CPRGHT, 
     >                    NOLABX, NOLABY, NOBOX, SIZELET, LATEBOX, 
     >                    VAR, MAXVAR, NVAR, BINSEX, AUTOSCALE, BINTER, 
     >                    NDATMAXIM, NSETMAXIM, IMPARMAX, ZIM, XIMPAR, 
     >                    ISETIM, NSETIM, STRIP, 
     >                    ISETXERR, ISETYERR, XERRTYPE, YERRTYPE, 
     >              SETNAME, NSETMAXMAX, NSETMAXDEFAULT, NDATMAXMAX,
     >              NDATMAXDEFAULT, NDATTOT, NOMINMAX, SIZETIC,
     >              BPREDEF_VAR, ALTX, ALTY, DATASETLINE, 
     >              XKIND4, YKIND4, YKIND4HELP)

C****************************************************************************
C***  READING DATA FROM PLOT FILE "FNAME"                                 ***
C***  Note : The length of ACTPAR has changed to from 20 to 40 characters ***
C****************************************************************************

      PARAMETER (NCMDMAX=200)

      DIMENSION X(NDATTOT), Y(NDATTOT)
      DIMENSION X1(NDATMAX), Y1(NDATMAX)
      DIMENSION B(6), C(6)
      DIMENSION NDAT(NSETMAX), ISYMBOL(NSETMAX), NPEN(NSETMAX)
      DIMENSION SSIZE(NSETMAX), ICOLOR(NSETMAX)
      DIMENSION ISETXERR(NSETMAX), ISETYERR(NSETMAX)
      CHARACTER*(*) XERRTYPE(NSETMAX), YERRTYPE(NSETMAX)
      CHARACTER*(*) VAR(MAXVAR,2), AUTOSCALE
      CHARACTER*(*) SETNAME(NSETMAX)
      CHARACTER KDLINE(NKDMAX)*132, SCMD(NCMDMAX)*132
      CHARACTER*(*) FNAME
      CHARACTER XLINE*132, YLINE*132 
C!!!      CHARACTER LINE*132 
C!!!  Special length for Goetz,  11-Dec-1996 18:03:49
      CHARACTER*900 LINE, LINE1
C     DATASETLINE is dimensioned in wrplot.f 
      CHARACTER*(*) DATASETLINE(NSETMAX)
      CHARACTER*144 HEADER, XTEXT, YTEXT, LONGPAR
      CHARACTER FITSNAM*255, FITSCOM*240
      CHARACTER*1 BACKSLASH, DOLLAR, CHAR13

      LOGICAL MPSTART, MPENDE, MPACTIVE, EXDATA, BSKEY
      LOGICAL XYTABLE, FLEXXY, NFLEXI, BWRPF 
      LOGICAL BXRANG, BYRANG, BSELECT, BFITS, BIMAGE
      LOGICAL CPRGHT, BINSEX, BPREDEF_VAR
      LOGICAL BINTER, BFAIL
      LOGICAL NOMINMAX(10)
      LOGICAL ALTX, ALTY
      LOGICAL NOTICKX, NOTICKY, NOTICK2X, NOTICK2Y, NOLABX, NOLABY
      LOGICAL INBOX

      CHARACTER ACTPAR*40, ACTPAR_FORMAT*40, MESSAGE*20
      CHARACTER MESS1*2, MESS2*2
      CHARACTER*80 SKEY

C***  32bit vectors for INFITS
      REAL*4 XKIND4(NDATMAXMAX), YKIND4(NDATMAXMAX)
      REAL*4 YKIND4HELP(NDATMAXMAX)

      DIMENSION ZIM(NDATMAXIM, NSETMAXIM)
      DIMENSION XIMPAR(NSETMAXIM, IMPARMAX)

C***  Special Common Block for transferring the Bounding Box rotate option
C***     to subroutine PS-PLTEND
      COMMON / COMBBROT/ BBROT, EPS
      LOGICAL BBROT, EPS

C***  PAPER FORMATS
      PARAMETER (NFORM = 14 )
      CHARACTER*7 FDES(NFORM), FDESACT
      DIMENSION FORMX(NFORM),FORMY(NFORM)
C***  Subr. PS_PLOTS is informed of actual PAPERFORMAT via COMMON-BLOCK
      COMMON /COMFORMAT/ FDESACT

C***  SCREEN2 = 4:3, SCREEN3 = 16:9, SCREEN4 = 16:10
      DATA FDES / 'A4Q', 'A4H', 'A3Q', 'A3H', 'A2Q', 'A2H',
     >     'A1Q', 'A1H', 'A0Q', 'A0H', 'SCREEN', 'SCREEN2',
     > 'SCREEN3', 'SCREEN4' /
      DATA FORMX/ 29.73, 21.02, 42.04, 29.73, 59.46, 42.04,
     >     84.09, 59.46,118.92, 84.09, 28.03, 30.48, 40.64,
     >     36.576 /
      DATA FORMY/ 21.02, 29.73, 29.73, 42.04, 42.04, 59.46,
     >     59.46, 84.09, 84.09,118.92, 21.02, 22.86, 22.86,
     >     22.86 /

      DOLLAR    = CHAR(36) 
      BACKSLASH = CHAR(92)
      CHAR13    = CHAR(13)

C***  DEFAULT PAPER FORMAT: DIN A4 LANDSCAPE, SCALE=1
      IF (.NOT. MPACTIVE) THEN
         FORMATFA = 1.
         PSIZEX = FORMX(1)
         PSIZEY = FORMY(1)
         BBROT = .TRUE.
         EPS   = .FALSE.
         ENDIF

C*** READING AN INTERPRETING LINES BEFORE LINE ' PLOT'
1     READ (NRUNIT,'(A)', END=98) LINE

      CALL SARGV (LINE,1,ACTPAR)

C***  A LINE PLOT WILL START SPECIAL READ IN
      IF (ACTPAR .EQ. 'PLOT') GOTO 2

C***  DECODE MULTIPLOT OPTION
      IF (ACTPAR. EQ. 'MULTIPLOT') THEN
         CALL SARGV (LINE, 2, ACTPAR)
         IF (ACTPAR .EQ. 'START') THEN
            MPSTART  = .TRUE.
            MPACTIVE = .TRUE.
            WRITE (*,*) 'MULTIPLOT START DETECTED'
         ELSE IF (ACTPAR(1:3) .EQ. 'END') THEN
            MPENDE = .TRUE.
            GOTO 100
         ELSE
            WRITE (*,*) 'MULTIPLOT OPTION: SECOND KEYWORD INVALID'
         ENDIF
         GOTO 1
         ENDIF

C*    DECODE FORMATFACTOR
      IF (ACTPAR .EQ. 'FORMATFACTOR') THEN
         CALL SARGV (LINE, 2, ACTPAR)
         READ (ACTPAR,'(F10.0)') FORMATFA
         GOTO 1
         ENDIF

C**   DECODE PAPERFORMAT
      IF (ACTPAR .EQ. 'PAPERFORMAT') THEN
         CALL SARGV (LINE,2,ACTPAR)
         PSIZEX=0.0
C*       Allow alias names
         IF (ACTPAR .EQ. 'SCREEN4TO3'  ) ACTPAR = 'SCREEN2' 
         IF (ACTPAR .EQ. 'SCREEN16TO9' ) ACTPAR = 'SCREEN3' 
         IF (ACTPAR .EQ. 'SCREEN16TO10') ACTPAR = 'SCREEN4' 

         DO 200 IFO=1,NFORM
           IF (FDES(IFO) .EQ. ACTPAR) THEN
              PSIZEX=FORMX(IFO)
              PSIZEY=FORMY(IFO)
              FDESACT = FDES(IFO)
C***          Default for landscape formats is BBROTATE
              BBROT = PSIZEX .GT. PSIZEY 
           ENDIF
200      CONTINUE
         IF (PSIZEX.EQ.0.0) THEN
           WRITE (0,'(A)') '*** WARNING: INVALID PAPERFORMAT: '//ACTPAR
           WRITE (0,'(A)') '*** WARNING: PAPERFORMAT A4Q used (default)'
            PSIZEX=FORMX(1)
            PSIZEY=FORMY(1)
	    BBROT = .TRUE.
            FDESACT = 'A4Q'
         ENDIF
C***  Decode option for rotation of the bounding box
         CALL SARGC (LINE, NPAR)
         DO I=3, NPAR
            CALL SARGV (LINE, I, ACTPAR)
            IF (ACTPAR .EQ. 'BBROTATE') THEN
               BBROT = .TRUE.
            ELSE IF (ACTPAR .EQ. 'BBNOROTATE') THEN
               BBROT = .TRUE.
            ELSE IF (ACTPAR .EQ. 'EPS') THEN
               EPS = .TRUE.
            ELSE
               PRINT *, 'UNRECOGNIZED 3rd PARAMETER IN FOLLOWING LINE:'
               PRINT *, LINE
            ENDIF
         ENDDO
         GOTO 1
         ENDIF

C**   IGNORE UNRECOGNIZED LINES
      GOTO 1

2     CONTINUE
C***  CONTINUE HERE WHEN "PLOT" OPTION WAS DETECTED
      IF (.NOT. MPACTIVE .OR. MPSTART .OR. IDEV .NE. 5) 
     > WRITE (*,*) LINE(1:79)

C***  READ BOXDATA
      CALL READBOX (NRUNIT ,HEADER, XTEXT, YTEXT, B, C,
     $             NOTICKX, NOTICKY, 
     >             NOTICK2X, NOTICK2Y, KDLINE, NKD, NKDMAX, 
     >             NOLABX, NOLABY, VAR, MAXVAR, NVAR, AUTOSCALE,
     >             NOMINMAX, ALTX, ALTY)

C***  KASDEF SETTINGS
      CALL KDSET (IPENDEF, ICOLDEF, PLOTSKAL, OFSX, OFSY, INBOX, 
     >            KDLINE, NKD, NKDMAX, CPRGHT, NOBOX, SIZELET, LATEBOX,
     >            VAR, MAXVAR, NVAR, BINSEX, BINTER,
     >            NSETMAX, NSETMAXMAX, NSETMAXDEFAULT, 
     >            NDATMAX, NDATMAXMAX, NDATMAXDEFAULT, NDATTOT,SIZETIC, 
     >            BPREDEF_VAR, FNAME)


C**********************************************************************
C*** LOOP FOR EACH (X,Y)-DATA TABLE (MAX. = NSETMAX)                ***
C**********************************************************************

      ISET = 0
      NSET = 0
      ISETIM = 0
      NSETIM = 0

10    CONTINUE
c      write (*,*) '------------number of images : ',nsetim

      ISELX = 1
      ISELY = 2
      BSELECT = .FALSE.
      BIMAGE = .FALSE.

C***  the only allowed lines are now: 
C***     *... (Comment), KASDEF ..., END, or the Data-Table-Header N=...
C***     or empty Lines
C***     ODD STATEMENTS 'FINISH' ARE IGNORED
15    READ (NRUNIT, '(A)', END=97) LINE
      IF (LINE(1:1) .EQ. '*' .OR. IDX(LINE) .EQ. 0) GOTO 15
C                         =
      CALL SARGV (LINE,1,ACTPAR)

      IF (ACTPAR(1:3) .EQ. 'END') GOTO 20
C                           ===

82    IF (LINE(1:1) .EQ. ' ') THEN
        LINE = LINE (2: )
        GOTO 82
      ENDIF

      IF (LINE(1:1) .EQ. CHAR(92)) THEN
        LINE = 'KASDEF ' // LINE(2: )
        ACTPAR = 'KASDEF'
      ENDIF
      IF (ACTPAR(1:6) .EQ. 'KASDEF') THEN
C                           ======
         CALL READKD (LINE, KDLINE, NKD, NKDMAX, VAR, MAXVAR, NVAR)
         GOTO 15
      ENDIF
      IF (ACTPAR(1:6) .EQ. 'FINISH') THEN
         GOTO 15
      ENDIF


      ISET = ISET + 1
      IF (ISET .GT. NSETMAX) THEN
         WRITE (*,'(A,I6)') 
     >   'Warning: More Datasets than dimensioned: NSETMAX=', NSETMAX
         GOTO 10          
         ENDIF

      NSET = ISET

C***  Parse Data-Set Header Line
C**   Preset defaults
      XYTABLE = .FALSE.
      FLEXXY  = .FALSE.
      BWRPF   = .FALSE.
      NPEN(ISET) = IPENDEF
      ICOLOR(ISET) = ICOLDEF
      ISYMBOL(ISET) = 5
      IPAR=1
      SSIZE(ISET)=0.3
      EXDATA = .FALSE.
      IEXDATA = 0
      BSKEY = .FALSE.
      SETNAME(ISET) = 'UNDEFINED'
      ISETXERR(ISET) = 0
      ISETYERR(ISET) = 0
     
C----------------------------------
C**********************************************************************
C***  EXPAND ALL VARIABLES
C**********************************************************************

C***  Option is disabled as long as no variables have been defined
      IF (NVAR .LE. 0) GOTO 195

C***  LINE is first copied into LINE1, then LINE is built up again piecewise  
      LINE1 = LINE
      LINE = ' '
      LAST = 0

C***  Begin of loop over all variables in that line
  190 CONTINUE
      CALL STRPOS (DOLLAR, LINE1, IPOS)

C***  If no variable left in the string: copy rest of string
      IF (IPOS .LE. 0) THEN
         LINE(LAST+1:) = LINE1
         GOTO 195
      
C***  If variable starts at position IPOS
      ELSE 
C***     Dollar might have been masked with backslash
         IF (IPOS .GT. 1) THEN
            IF (LINE1(IPOS-1:IPOS-1) .EQ. BACKSLASH) THEN
               LINE(LAST+1:) = LINE1(:IPOS-2)
               LAST = LAST + IPOS - 1
               LINE(LAST:) = DOLLAR
               LINE1 = LINE1(IPOS+1:)
               GOTO 190
               ENDIF
            ENDIF
         LINE(LAST+1:) = LINE1(:IPOS-1)
         LAST = LAST + IPOS - 1
         LINE1 = LINE1(IPOS:)

C***     Decode and replace variable 
         CALL SARGV (LINE1, 1, LONGPAR)
         CALL SARGP (LINE1, NDUMMY, 1, IFI, ILA)
         CALL DECVAR (LONGPAR, VAR, MAXVAR, NVAR)
         LINE(LAST+1:) = LONGPAR
         LAST = LAST + IDX(LONGPAR)
         LINE1 = LINE1(ILA+1:)
         GOTO 190
      ENDIF


  195 CONTINUE

C----------------------------------

C**  Get number of arguments
      CALL SARGC(LINE,NPAR)     

33    CONTINUE
C**    Loop over all Arguments
      CALL SARGV (LINE,IPAR,ACTPAR)
      IF (ACTPAR .EQ. 'N') THEN
           CALL SARGV (LINE,IPAR+1,ACTPAR)
           IPAR=IPAR+2
           NFLEXI = ACTPAR(1:1) .EQ. '?'
           IF (NFLEXI) GOTO 32
           CALL SARGVR (LINE,IPAR-1,ACTPAR)
           READ (ACTPAR, '(30X,I10)', ERR=96) NDAT(ISET)
      ELSE IF (ACTPAR .EQ. 'PLOTSYMBOL' .OR.
     >         ACTPAR .EQ. 'SYMBOL'    ) THEN
           CALL SARGVR (LINE, IPAR+1, ACTPAR)
           IPAR = IPAR + 2
           READ (ACTPAR, '(30X, I10)', ERR=96) ISYMBOL(ISET)
      ELSE IF (ACTPAR .EQ. 'SYMBOLSIZE' .OR. 
     >         ACTPAR .EQ. 'SIZE'       ) THEN
           CALL SARGVR (LINE, IPAR+1, ACTPAR)
           IPAR = IPAR + 2
           READ (ACTPAR,'(30X, F10.0)', ERR=96) SSIZE(ISET)
      ELSE IF (ACTPAR .EQ. 'PEN') THEN
           CALL SARGVR (LINE, IPAR+1, ACTPAR)
           IPAR = IPAR + 2
           READ (ACTPAR, '(30X,I10)', ERR=96) NPEN(ISET)
      ELSE IF (ACTPAR .EQ. 'COLOR') THEN
           CALL SARGVR (LINE, IPAR+1, ACTPAR)
           IPAR = IPAR + 2
           READ (ACTPAR,'(30X,I10)', ERR=96) ICOLOR(ISET)
      ELSE IF (ACTPAR.EQ.'XYTABLE') THEN
           XYTABLE = .TRUE.
           FLEXXY = .FALSE.
           IPAR=IPAR+1
      ELSE IF (ACTPAR .EQ. 'SELECT') THEN
           BSELECT = .TRUE.
           CALL SARGVR (LINE, IPAR+1, ACTPAR)
           READ (ACTPAR,'(30X,I10)', ERR=96) ISELX
           CALL SARGVR (LINE, IPAR+2, ACTPAR)
           READ (ACTPAR,'(30X,I10)', ERR=96) ISELY
           IPAR = IPAR + 3
      ELSE IF (ACTPAR .EQ. 'FLEX-XYTABLE') THEN
           FLEXXY = .TRUE.
           XYTABLE = .FALSE.
           IPAR = IPAR + 1
      ELSE IF (ACTPAR .EQ. 'WRPF') THEN
           BWRPF = .TRUE.
           IPAR = IPAR + 1
      ELSE IF (ACTPAR .EQ. 'IMAGE') THEN
           BIMAGE = .TRUE.
           ISET = ISET - 1
           NSET = ISET
           ISETIM = ISETIM + 1
           NSETIM = ISETIM
           IF (ISETIM .GT. NSETMAXIM) THEN
             WRITE (0,*) 'NO MORE SPACE LEFT FOR ARRAYS'
             WRITE (0,'(A,I3)') 'NSETMAXIM=', NSETMAXIM
             STOP 'ERROR IN SUBR. READDATA'
           ENDIF
           IPAR=IPAR+1
      ELSE IF (ACTPAR .EQ. 'HTYPE' .OR.
     >         ACTPAR .EQ. 'HATCHED'    ) THEN
           IPAR = IPAR + 2
           DATASETLINE(ISET)=LINE
      ELSE IF (ACTPAR .EQ. 'HW' .OR. ACTPAR .EQ. 'HSEP') THEN
           IPAR=IPAR+2
      ELSE 
           WRITE (6,*) ' UNRECOGNIZED PARAMETER: ',ACTPAR
           IPAR=IPAR+1     
      ENDIF

   32 IF (IPAR .LE. NPAR) GOTO 33

C***  CHECK FOR RIGHT USE OF SELECT
      IF (BSELECT .AND. .NOT. XYTABLE) THEN
        WRITE (6,*) 'DO NOT USE SELECT WITHOUT XYTABLE!'
        WRITE (6,*) 'SELECT OPTION ABORTED'
        BSELECT = .FALSE.
      ENDIF

      IF (XYTABLE) THEN 
        MESSAGE = 'XYTABLE'
        IF (BSELECT) THEN
          WRITE (MESS1, '(BN,I2)') ISELX
          IF (MESS1( :1) .EQ. ' ') MESS1 = MESS1(2:2)
          WRITE (MESS2, '(BN,I2)') ISELY
          IF (MESS2( :1) .EQ. ' ') MESS2 = MESS2(2:2)
          MESSAGE = MESSAGE( :IDX(MESSAGE)) // '(' //
     >              MESS1( :IDX(MESS1)) // ':' // MESS2(:IDX(MESS2))
     >              // ')'
        ENDIF
      ELSE IF (FLEXXY) THEN
        MESSAGE = 'FLEX-XYTABLE'
      ELSE
        MESSAGE = ' '
      ENDIF

      IF (.NOT. MPACTIVE) THEN
         IF (NFLEXI) THEN
            WRITE (6,9) ISET, ISYMBOL(ISET), NPEN(ISET), ICOLOR(ISET), 
     >                  MESSAGE( :IDX(MESSAGE))
    9       FORMAT (/,'#', I3, ' N=  ???  SYMBOL=', I3,
     >             ' PEN=',I2, ' COLOR=', I1, 1X, A, $)
            ELSE
            WRITE (6,4) ISET, NDAT(ISET), ISYMBOL(ISET), NPEN(ISET), 
     >                  ICOLOR(ISET), MESSAGE( :IDX(MESSAGE))
    4       FORMAT (/,'#', I3, ' N=',I6,' SYMBOL=',I3, 
     >             ' PEN=',I2, ' COLOR=', I1, 1X, A, $)
            IF (NDAT(ISET) .GT. NDATMAX) GOTO 95
            ENDIF
         ENDIF

      I=1
      ISKIP = 0
      NARGX = 0
      NARG = 0
      IARG = 0
      BXRANG = .FALSE.
      BYRANG = .FALSE.
      NCMD = 0
C***  DEFAULT: NO FITS-INCLUDE
      BFITS = .FALSE.

   19 CONTINUE
      IF (.NOT. EXDATA) THEN
         READ (NRUNIT,'(A)',END=97) LINE
         ELSE
         READ (9 + IEXDATA, '(A)',END=94) LINE
      ENDIF
C***  SKIP COMMENT LINES
      IF (LINE(1:1) .EQ. '*') GOTO 19
      IF (LINE(1:1) .EQ. '#') GOTO 19
      IF (LINE(1:1) .EQ. '!') GOTO 19
     
C***  The following statement was intruduced because Lida had WIN-generated
C***  files in which each line had an ascii=13 character as last sign
      IDXL = IDX(LINE)
      IF ( LINE(IDXL:IDXL) .EQ. CHAR13 ) LINE = LINE(:IDXL-1)

      CALL SARGC (LINE, NARG)
      CALL SARGV (LINE, 1, ACTPAR)
      IF (BIMAGE .AND. ACTPAR .NE. 'COMMAND' .AND. 
     .    ACTPAR .NE. 'FINISH') GOTO 19
      IF (ACTPAR(1:1) .EQ. '*') GOTO 19
      IF ( (NFLEXI .AND. ACTPAR      .EQ. 'FINISH')  .OR. 
     >          (EXDATA .AND. ACTPAR(1:3) .EQ. 'END'   )  .OR. 
     >          (EXDATA .AND. ACTPAR      .EQ. 'FINISH')  .OR. 
     >          (EXDATA .AND. ACTPAR      .EQ. 'N'     ) ) THEN
         NDAT(ISET) = I-1
C***  ENTRY-POINT WHEN END-OF-FILE HAS OCCURED IN EXTERNAL DATASET
  666    CONTINUE
         IF (.NOT. MPACTIVE) WRITE (6, 66) 
     >                       ' (N=', NDAT(ISET), ')'
   66       FORMAT (A,I6,A,$)
         GOTO 18
         ENDIF 
C***  BRANCH FOR ADDITIONAL COMMANDS IN THE DATASET
      IF (ACTPAR .EQ. 'COMMAND') THEN
         CALL DECCMD (LINE, BXRANG, XRANG1, XRANG2, BYRANG, YRANG1, 
     >                YRANG2, EXDATA, IEXDATA, IERR, K, MPACTIVE, 
     >                MPSTART, NCMD, NCMDMAX, SCMD, 
     >                X, Y, NDAT, NDATMAX, ISET, NSET, NSETMAX, I, 
     >                BFITS, FITSNAM, FITSCOM, VAR, MAXVAR, NVAR, FNAME, 
     >                BSKEY, SKEY, IDX_SKEY, SETNAME)
         IF (IERR .GT. 0) GOTO 100

         IF (.NOT. BFITS) THEN
           GOTO 19
         ELSE
C***  READ THE FITS-FILE NAMED FITSNAM
           CALL INFITS (FITSNAM, FITSCOM, X, Y, NDAT, NDATMAX, 
     >                  NSETMAX, ISET, BIMAGE, 
     >                  NDATMAXIM, NSETMAXIM, IMPARMAX, ZIM, XIMPAR, 
     >                  ISETIM, XKIND4, YKIND4, YKIND4HELP)
           IF (.NOT. MPACTIVE) WRITE (6, 66) 
     >                       ' (N=', NDAT(ISET), ')'
           GOTO 18
         ENDIF
       ENDIF


   60 CONTINUE
      INDEX = NDATMAX * (ISET-1) + I
      IF (XYTABLE) THEN
C***  NON-STANDARD FORMAT: X-Y-TABLE
         IF (BSKEY) THEN
           IF (LINE( :IDX_SKEY) .NE. SKEY( :IDX_SKEY)) THEN
             GOTO 19
           ENDIF
         ENDIF
         IF (ISELX .EQ. -1) THEN
           XBUFFER = FLOAT(I)
         ELSE
           IF (ISELX .NE. 1) THEN
             CALL SARGV (LINE, ISELX, ACTPAR)
           ENDIF
           CALL DOUBREAD (ACTPAR, XBUFFER, BFAIL)
         ENDIF
         IF (BFAIL) GOTO 96
         CALL SARGV (LINE, ISELY, ACTPAR)
         CALL DOUBREAD (ACTPAR, YBUFFER, BFAIL)
         IF (BFAIL) GOTO 96
      ELSE IF (FLEXXY) THEN
         IARG = IARG + 1
         IF (IARG .GT. NARG) GOTO 70
         CALL SARGV (LINE, IARG, ACTPAR)
C***     READ NEXT LINE IF '*' OCCURS IN LINE
         IF (ACTPAR(1:1) .EQ. '*') THEN
            IARG = 0
            NARG = 0
            GOTO 70
         ENDIF
         CALL DOUBREAD (ACTPAR, XBUFFER, BFAIL)
         IF (BFAIL) GOTO 96
         IARG = IARG + 1
         IF (IARG .GT. NARG) GOTO 96
         CALL SARGV (LINE, IARG, ACTPAR)
         CALL DOUBREAD (ACTPAR, YBUFFER, BFAIL)
         IF (BFAIL) GOTO 96
      ELSE
         BWRPF = .TRUE.
         IARG = IARG + 1
         IF (IARG .GT. NARGX) THEN
            XLINE = LINE
   50       CONTINUE
            IF (.NOT. EXDATA) THEN
   51          READ (NRUNIT,'(A)',END=97) YLINE
               IF (LINE(1:1) .EQ. '*') GOTO 51
               ELSE
   52          READ (9 + IEXDATA,'(A)',END=92) YLINE
               IF (LINE(1:1) .EQ. '*') GOTO 52
               ENDIF
            IF (LINE(1:1) .EQ. '*') GOTO 50
            CALL SARGC (XLINE, NARGX)
            CALL SARGC (YLINE, NARGY)
            IF (NARGX .NE. NARGY) GOTO 96
            IARG = 1
            ENDIF
         CALL SARGV (XLINE, IARG, ACTPAR)
         CALL DOUBREAD (ACTPAR, XBUFFER, BFAIL)
         IF (BFAIL) GOTO 96
         CALL SARGV (YLINE, IARG, ACTPAR)
         CALL DOUBREAD (ACTPAR, YBUFFER, BFAIL)
         IF (BFAIL) GOTO 96
      ENDIF

      IF ( (XBUFFER .GE. XRANG1 .AND. XBUFFER .LE. XRANG2
     >         .OR. .NOT. BXRANG) .AND. 
     >          (YBUFFER .GE. YRANG1 .AND. YBUFFER .LE. YRANG2
     >         .OR. .NOT. BYRANG) ) THEN
       X(INDEX) = XBUFFER
       Y(INDEX) = YBUFFER
       IF (NFLEXI) THEN
         IF (I .GT. NDATMAX) GOTO 95
       ENDIF           
         I = I + 1
      ELSE
        IF (.NOT. NFLEXI) THEN
          NDAT(ISET) = NDAT(ISET) - 1
        ENDIF
      ENDIF
380   continue

 70   CONTINUE
      IF (.NOT. NFLEXI) THEN
         IF (I .GT. NDAT(ISET)) GOTO 18
      ENDIF

C***  XYTABLE : MORE X- AND Y- DATA IN XLINE AND YLINE  ==>  GOTO 60
      IF (.NOT. XYTABLE .AND. IARG .LT. NARGX) GOTO 60

C***  FLEX-XYTABLE : MORE DATA IN THE LINE
      IF (FLEXXY) THEN
         IF (IARG .LT. NARG) THEN
            GOTO 60
            ELSE
            IARG = 0
            NARG = 0
            ENDIF
         ENDIF

      GOTO 19
C***  --------- ENDLOOP ---------

   18 CONTINUE
      IF (EXDATA) THEN
        DO I=1, IEXDATA
          CLOSE (9 + I)
        ENDDO
        IEXDATA = 0
      ENDIF

C***  EXECUTE COMMAND INSTRUCTIONS IF REQUIRED
      IF (NCMD .GT. 0) THEN
         CALL EXCMD (NCMD, NCMDMAX, SCMD, X, Y, X1, Y1, ISET, NDAT, 
     >              NDATMAX, NSET, NSETMAX, ISYMBOL, NPEN, ICOLOR,
     >              B, C, MPACTIVE, VAR, MAXVAR, NVAR, STRIP, ISKIP,
     >              ISETXERR, ISETYERR, XERRTYPE, YERRTYPE, SETNAME,
     >              DATASETLINE, SSIZE)
      ENDIF

C***  IGNORE DATASETS IF NO DATA-POINTS ARE DECODED OR 
C***                  IF COMMAND SKIP IS DECODED
      IF (NDAT(ISET) .EQ. 0 .AND. ISKIP .EQ. 0) THEN
        ISKIP = 1
      ENDIF
      IF (ISKIP .GT. 0) THEN
        NSET = NSET - ISKIP
        ISET = ISET - ISKIP
        IF (.NOT. MPACTIVE) THEN
          IF (ISKIP .GT. 0) THEN
            WRITE (6, '(A,I1,$)') ' SKIP ', ISKIP
          ENDIF
        ENDIF
      ENDIF

      IF (.NOT. MPACTIVE) THEN
          IF (SETNAME(ISET) .NE. 'UNDEFINED') THEN
            WRITE (6, '(1X, A, $)') SETNAME(ISET)(:IDX(SETNAME(ISET)))
          ENDIF
        ENDIF

      GOTO 10

20    IF (.NOT. MPACTIVE)
     $    WRITE(6,'(/,A)') 'READING OF DATA TABLES COMPLETED'
      K=0
      GOTO 100

C**********************************************************************
C***                  ERROR BRANCHES                                ***
C**********************************************************************

C***  NOTE: CLOSE HPG-PLOT IF IT IS ALREADY OPEN (MPACTIVE .AND. .NOT. MPSTART) 
C***        BEFORE ISSUING AN ERROR MESSAGE

92    CONTINUE
      IF (MPACTIVE .AND. .NOT. MPSTART) CALL GPLTEND
      WRITE(6,*) 'WRPLOT-FORMAT : LAST LINE WITH Y-DATA IS MISSING IN ',
     >           'EXTERNAL DATASET --  THIS PLOT SKIPPED!'
      K = 1
      DO 93 I=1, IEXDATA
        CLOSE (9 + IEXDATA)
93    CONTINUE
      GOTO 100

94    CONTINUE
      NDAT(ISET) = I - 1
      CLOSE (9 + IEXDATA)
      IEXDATA = IEXDATA - 1
      IF (IEXDATA .EQ. 0) EXDATA = .FALSE.
      GOTO 666

95    CONTINUE
      IF (MPACTIVE .AND. .NOT. MPSTART) CALL GPLTEND
      WRITE (*,'(/,A,I6)') 'FATAL ERROR IN DATASET ', ISET 
      WRITE (*,'(A,I6)') 'MORE DATA THAN NDATMAX=', NDATMAX
      WRITE (*,'(A)')    '*** THIS PLOT SKIPPED! ***'
      K=1
      GOTO 100

96    CONTINUE
      IF (MPACTIVE .AND. .NOT. MPSTART) CALL GPLTEND
      WRITE (6,*) 'ERROR: INVALID DATA FORMAT ON FILE - ',
     *            'THIS PLOT SKIPPED!'
      WRITE (6,*) 'The error occured in the following line:'
      WRITE (6,*) LINE
      K=1
      GOTO 100

97    CONTINUE
      IF (MPACTIVE .AND. .NOT. MPSTART) CALL GPLTEND
      WRITE (6,*) 'ERROR: E-O-F ENCOUNTERED BEFORE READING COMPLETED'
      K=2
      GOTO 100

98    CONTINUE
      IF (MPACTIVE .AND. .NOT. MPSTART) CALL GPLTEND
      WRITE (6,*) 'INPUT FILE ',FNAME(:IDX(FNAME)),' HAS NO MORE PLOTS'
      IF (MPACTIVE) MPENDE=.TRUE.
      K=2
      GOTO 100

100   RETURN
      END

readkd.f/       1553528659  5006  320   100644  2524      `
      SUBROUTINE READKD (LINE, KDLINE, NKD, NKDMAX, VAR, MAXVAR, NVAR)
C***********************************************************************
C***  WRPLOT PROGRAM:
C***  This subroutine is entered when LINE contains a KASDEF option.
C***  Included files are not yet inserted here. 
C***  This option is stored in the array KDLINE. 
C***  Called from: READDATA and READBOX
C***********************************************************************


      CHARACTER*(*) VAR(MAXVAR,2)
      CHARACTER KDLINE(NKDMAX)*(*), LINE*(*)
      CHARACTER ACTPAR*40 

      CALL SARGV (LINE, 2, ACTPAR)


C*************************************
C***  Reading from standard input file
C*************************************
         NKD = NKD + 1
         IF (NKD .GT. NKDMAX) GOTO 98    
         KDLINE(NKD) = LINE
C***  Read floating text into KDLINE buffer
         IF (ACTPAR .EQ. 'TEXT') THEN
    1       READ (1, '(A)', END=96) LINE
            NKD = NKD + 1
            IF (NKD .GT. NKDMAX) GOTO 98    
            KDLINE(NKD) = LINE
	    CALL FLUSHLEFT (LINE)
            IF (LINE(1:1) .EQ. CHAR(92)) THEN
               LINE = 'KASDEF ' // LINE(2: )
               ENDIF
            CALL SARGV (LINE, 1, ACTPAR)
            IF (ACTPAR .NE. 'KASDEF') THEN
               GOTO 1
               ELSE
               CALL SARGV (LINE, 2, ACTPAR)
               IF (ACTPAR .NE. 'ENDTEXT') GOTO 1
            ENDIF
C***  Read latex text into KDLINE buffer
         ELSE IF (ACTPAR .EQ. 'LATEX') THEN
   11       READ (1, '(A)', END=97) LINE
            NKD = NKD + 1
            IF (NKD .GT. NKDMAX) GOTO 98    
            KDLINE(NKD) = LINE
            CALL FLUSHLEFT (LINE)
            IF (LINE(1:1) .EQ. CHAR(92)) THEN
               LINE = 'KASDEF ' // LINE(2: )
               ENDIF
            CALL SARGV (LINE, 1, ACTPAR)
            IF (ACTPAR .NE. 'KASDEF') THEN
               GOTO 11
               ELSE
               CALL SARGV (LINE, 2, ACTPAR)
               IF (ACTPAR .NE. 'ENDLATEX') GOTO 11
            ENDIF
         ENDIF

C***  NORMAL EXIT
      RETURN

C***********************************************************
C***  ERROR HANDLING ***************************************
C***********************************************************
   96 WRITE (*,*) 'ERROR: "KASDEF ENDTEXT" MISSING' 
      STOP 'ERROR IN READKD'

   97 WRITE (*,*) 'ERROR: "KASDEF ENDLATEX" MISSING' 
      STOP 'ERROR IN READKD'

   98 WRITE(*,*) 'ERROR: MORE KASDEF OPTIONS THAN ALLOWED:', NKDMAX
      STOP 'ERROR IN READKD'

      END
readpar.f/      1553528659  5006  320   100644  2613      `
      SUBROUTINE READPAR (ACTPAR, B, C, VALUE, VAR, MAXVAR, NVAR)
C**********************************************************************
C***  CALLED FROM: SUBR. KDPLOT (WRPLOT-PROGRAM)
C***  DECODING PARAMETER ACTPAR; ALLOWS THE USE OF THE "VARIABLES"
C***  XMIN, XMAX, YMIN, YMAX INSTEAD OF NUMERICAL VALUES
C**********************************************************************

      CHARACTER*(*) VAR(MAXVAR,2)
      CHARACTER ACTPAR*20
      DIMENSION B(6), C(6)
      DATA DEG /0.017453293/

      COMMON / COMCMPT / CMPT
      COMMON / COMCLIP / ICLIP, CXMIN(2), CXMAX(2), CYMIN(2), CYMAX(2)
      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA

C***  DECODE VARIABLES
CCC**  passiert jetzt vorab zentral!! W-R      CALL DECVAR (ACTPAR, VAR, MAXVAR, NVAR)

c!!!      write (*,*) 'readpar: actpar=', actpar

      IF (ACTPAR .EQ. 'XMIN') THEN
         VALUE = B(2)
      ELSE IF (ACTPAR .EQ. 'XMAX') THEN
         VALUE = B(3)
      ELSE IF (ACTPAR .EQ. 'YMIN') THEN
         VALUE = C(2)
      ELSE IF (ACTPAR .EQ. 'YMAX') THEN
         VALUE = C(3)
      ELSE IF (ACTPAR .EQ. 'PXMIN') THEN
         XPT = 1.
         VALUE = (XPT/CMPT - XOFFSET) / (FORMATFA * B(1)) + B(2)
      ELSE IF (ACTPAR .EQ. 'PXMAX') THEN
         XPT = CXMAX(1) - 1.
         VALUE = (XPT/CMPT - XOFFSET) / (FORMATFA * B(1)) + B(2)
      ELSE IF (ACTPAR .EQ. 'PYMIN') THEN
         YPT = 1.
         VALUE = (YPT/CMPT - YOFFSET) / (FORMATFA * C(1)) + C(2)
      ELSE IF (ACTPAR .EQ. 'PYMAX') THEN
         YPT = CYMAX(1) - 1.
         VALUE = (YPT/CMPT - YOFFSET) / (FORMATFA * C(1)) + C(2)
      ELSE IF (ACTPAR(1:3) .EQ. 'LOG') THEN
         CALL DECVAR (ACTPAR(4:), VAR, MAXVAR, NVAR)
         READ (ACTPAR(4: ), '(F10.0)') VALUE
         VALUE = ALOG10 (VALUE)
      ELSE IF (ACTPAR(1:3) .EQ. 'DEX') THEN
         CALL DECVAR (ACTPAR(4:), VAR, MAXVAR, NVAR)
         READ (ACTPAR(4: ), '(F10.0)') VALUE
         VALUE = 10. ** (VALUE)
      ELSE IF (ACTPAR(1:3) .EQ. 'SIN') THEN
         CALL DECVAR (ACTPAR(4:), VAR, MAXVAR, NVAR)
         READ (ACTPAR(4: ), '(F10.0)') VALUE
         VALUE = SIN(DEG*VALUE)
      ELSE IF (ACTPAR(1:3) .EQ. 'COS') THEN
         CALL DECVAR (ACTPAR(4:), VAR, MAXVAR, NVAR)
         READ (ACTPAR(4: ), '(F10.0)') VALUE
         VALUE = COS(DEG*VALUE)
      ELSE
         READ (ACTPAR, '(F20.0)', ERR=99) VALUE
      ENDIF

      RETURN

   99 PRINT *, '*** ERROR IN KASDEF OPTION: ************'
      PRINT *, '>>>>', ACTPAR, '<<<< CANNOT BE DECODED AS FLOATING ',
     >         'POINT NUMBER!'
      PRINT *, '**** ERROR STOP IN SUBROUTINE READPAR *****'
      STOP 'ERROR'

      END

sargvr.f/       1553528659  5006  320   100644  824       `
      SUBROUTINE SARGVR (TEXT, I, ARGTEXT)
C**************************************************************************
C**   ... ermittelt das i-te Argument in einem String und schreibt dieses
C***  RECHTSBUENDIG (!) in ARGTEXT.
C**   Die Regeln zur Argumenttrennung sind in sargp beschrieben.
C**   Ist das i-te Argument nicht vorhanden, wird argtext nicht veraendert.
C**************************************************************************

      CHARACTER*(*) TEXT, ARGTEXT
      INTEGER I
      INTEGER N,AS,AE

      CALL SARGP (TEXT, N, I, AS, AE)

      IF (AS .EQ. -1) GOTO 10
      IF (AS .EQ. 0) THEN
             ARGTEXT=' '
      ELSE
             LAST = LEN (ARGTEXT)
             ARGTEXT = ' '
             IDIFF = AE - AS
             ARGTEXT(LAST-IDIFF:)=TEXT(AS:AE)
      ENDIF

10    RETURN

      END
saveset.f/      1553528659  5006  320   100644  1527      `
      SUBROUTINE SAVESET (X, Y, N, ISYMBOL, NPEN, FNAME, BINQ)
C************************************************************
C***  STORES DATASET AFTER MANUPULATION OF THE DATA
C***  CALLED FROM: SUBROUTINES ARI, CONVOL, EXTINCT, WRPLOT
C***               (WRPLOT-PROGRAM SYSTEM)
C************************************************************

      DIMENSION X(N), Y(N)
      CHARACTER ICHAR*1, FNAME*255, FNAMENEW*255
      LOGICAL BINQ

C***  Operating system
      COMMON / COMOS / OPSYS
      CHARACTER*8 OPSYS

      IF (.NOT. BINQ) THEN
        ICHAR = 'Y'
      ELSE
        WRITE(6,*) 'SAVE THE LAST MODIFIKATION ? /N/'
        WRITE(6,'(''$'',A)') 'INPUT: '
        READ(5,'(A)') ICHAR
      ENDIF

      IF (ICHAR .EQ. 'Y' .OR. ICHAR .EQ. 'y') THEN
C***  Find position in string FNAME where to add the suffix _new
      LEN = IDX(FNAME)
      IF (OPSYS .EQ. 'UNIX') THEN
         IPOS = LEN + 1
      ELSE
         WRITE (6,*) '>>>  Unknown Operating System <<<'
         STOP 'ERROR IN SUBROUTINE SAVESET'
      ENDIF

         FNAMENEW = FNAME
         FNAMENEW(IPOS:IPOS+3) = '_new'
         OPEN (10, FILE=FNAMENEW, STATUS='NEW')
         WRITE (10,2) N, ISYMBOL, NPEN
    2    FORMAT 
     >    (' N=', I4, '  PLOTSYMBOL=', I2, '  PEN=', I2, '  XYTABLE')
         DO 1 I=1, N
    1    WRITE (10,'(2G14.7)') X(I), Y(I)     
c    1    WRITE (10,*) X(I), Y(I)     

         WRITE (10,*) 'FINISH'

         CLOSE (10)
         WRITE(6,*) 'DATASET WRITTEN ON FILE= ', FNAMENEW
         ENDIF

      RETURN
      END

scatter.f/      1553528659  5006  320   100644  759       `
      SUBROUTINE SCATTER
C***  PROGRAEMMCHEN ZUR ERZEUGEN EINER RADIALEN PUNKTWOLKE 
C***     FUER WRPLOT-DARSTELLUNG DES ECLIPSE-MODELLS

      DATA PI /3.141592654/

C***  ZAHL DER WINKELPUNKTE
      NW = 120 

C***  ZAHL DER RADIALEN PUNKTE
      NR = 30

C***  MAXIMALER RADIUS
      RMAX = 6.

      OPEN (8,FILE='SCATTER.DAT')

C***  WINKEL-LOOP
      DW = 2. * PI / FLOAT(NW)
      DO 1 IW = 0, NW
      W = IW * DW

C***  RADIAL-LOOP
      DR = (RMAX - 1.) / FLOAT(NR)**2
      DO 2 IR = 1, NR
      R = 1. + IR**2 * DR
      X = R * COS(W)
      Y = R * SIN(W)

C*** SHADOWED REGION AUSBLENDEN

      IF (X .LE. .0 .AND. (Y .GE. 3. .AND. Y .LE. 5.)) GOTO 2

      WRITE (8,'(2F10.4)') X, Y

    2 CONTINUE
    1 CONTINUE

      STOP 'O.K.'
      END

setbit.f/       1553528659  5006  320   100644  564       `
C**********************************************************
C**  subroutine setbit : setzt/loescht ein Bit im Ifeld   *
C**********************************************************

      SUBROUTINE SETBIT(IX, IY, F, IFELD, IXDIM, IYDIM)

C In: die Bitkoordinaten
      LOGICAL F

C     Out: der neue Wert des Bits
      DIMENSION IFELD(0:IXDIM,0:IYDIM)

      IX1 = IX/32
      IX2 = IX - IX1*32 

      IF (F) THEN
         IFELD(ix1,iy) = IBSET(IFELD(ix1,iy),ix2)
      ELSE
         IFELD(ix1,iy) = IBCLR(IFELD(ix1,iy),ix2)
      ENDIF


      RETURN
      END
skip.f/         1553528659  5006  320   100644  1360      `

      SUBROUTINE SKIP (NRUNIT)
C********************************************************************
C***  SKIP PLOTS FORWARD OR BACKWARD                              ***
C********************************************************************

      CHARACTER*132 LINE, ACTPAR

      WRITE (6,*)
      WRITE (6,'(A,A)') '$How many Plots do you want to skip? ',
     >            '(negative number: absolute position): '
      READ (5, '(I4)') N

      IF (N .LT. 0) REWIND(NRUNIT)
        
C***  SKIP FORWARD
        DO 1 I=1, ABS(N)-1
    2     READ (NRUNIT, '(A)', END=99) LINE
          CALL SARGC (LINE,NPAR)
          IF (NPAR .EQ. 0) GOTO 2
          CALL SARGV (LINE, 1, ACTPAR)
          IF (ACTPAR .EQ. 'MULTIPLOT') THEN
            CALL SARGV (LINE, 2, ACTPAR)
            IF (ACTPAR .EQ. 'START') THEN
    4         READ (NRUNIT, '(A)', END=99) LINE
              CALL SARGC (LINE,NPAR)
              IF (NPAR .EQ. 0) GOTO 4
              CALL SARGV (LINE, 1, ACTPAR)
              IF (ACTPAR .NE. 'MULTIPLOT') GOTO 4
              CALL SARGV (LINE, 2, ACTPAR)
              IF (ACTPAR(1:3) .NE. 'END') GOTO 4
            ENDIF
            GOTO 1
          ENDIF
          IF (ACTPAR(1:3) .NE. 'END') GOTO 2
    1    CONTINUE

      RETURN

   99 WRITE (6,*) 'ERROR : END OF FILE DETECTED; FILE REWOUND'
      REWIND (NRUNIT)
      RETURN

      END
skymap.f/       1553528659  5006  320   100644  1679      `
	SUBROUTINE SKYMAP
C
C	Das Programm berechnet Skymap-Overlays. 
C       Die Ausgabe erfolgt als Standard-Datentabelle fuer das
C       WRPLOT-Programm. Es werden Kurven mit vorgegebener Hoehe 
C       ueber dem Horizont in Stundenwinkel-Deklination umgerechnet.
C
C	 10-APR-1991 12:00:25 
C-----------------------------------------------------------------------

	PARAMETER (PI = 3.141592654, PI2 = 1.570796327)
	PARAMETER (RAD = 57.29577951, RADH = 3.819718634)


        PRINT *, 'GEOGRAPHISCHE BREITE IN GRAD EINGEBEN'
        READ (*,*) B

        PRINT *, 'ABSTAND DER KURVEN IN GRAD: '
        READ (*,*) IDELTA

	B = B/RAD

	OPEN (1,FILE='skymap.overlay',STATUS='UNKNOWN')

C	Schleife ueber die Zenitdistanz
	DO 1000 IZ = 10, 110, IDELTA
	    Z = FLOAT(IZ) /RAD
        IF (IZ .EQ. 90) THEN 
          WRITE (1,*) 'N=? XYTABLE PEN=5'
        ELSE
          WRITE (1,*) 'N=? XYTABLE '
        ENDIF
C           Loop over Azimuth
C            - Note: Different starting point for northern/southern hemisphere
            IF (B .GT. 0) THEN
               IAMIN = -180
            ELSE
               IAMIN = 0
            ENDIF

	    DO 500 IA = IAMIN, IAMIN+360, 3
		A = FLOAT(IA) /RAD
		D = SIN(B) *COS(Z) -COS(B) *SIN(Z) *COS(A)
		D = ASIN (D)
		T1 = SIN(Z) *SIN(A) /COS(D)
		T2 = (COS(B) *COS(Z) +SIN(B) *SIN(Z) *COS(A)) /COS(D)
                T1 = AMIN1(T1, 1.)
                T1 = AMAX1(T1,-1.)
                T = ASIN (T1)

		IF (T2.LE.0.) T = PI -T
		IF (T.GE.PI) T = T -2. *PI

		WRITE (1,*) T*RADH, D*RAD
		
500	    CONTINUE
	WRITE (1,*) 'FINISH'
1000	CONTINUE

	CLOSE(1)

        PRINT *, 'DATA TABLE WRITTEN TO FILE: skymap.overlay'
        STOP 'O.K.'

	END

square.f/       1553528659  5006  320   100644  512       `
      SUBROUTINE SQUARE (X, Y, SSIZE)
C**********************************************************************
C***  PLOTTING OF A SQUARE (CLIPPED)
C**********************************************************************
      CALL GCPLOT (X-0.3333*SSIZE, Y-0.3333*SSIZE, 3)
      CALL GCPLOT (X+0.3333*SSIZE, Y-0.3333*SSIZE, 2)
      CALL GCPLOT (X+0.3333*SSIZE, Y+0.3333*SSIZE, 2)
      CALL GCPLOT (X-0.3333*SSIZE, Y+0.3333*SSIZE, 2)
      CALL GCPLOT (X-0.3333*SSIZE, Y-0.3333*SSIZE, 2)
      RETURN
      END
star.f/         1553528659  5006  320   100644  1594      `
      SUBROUTINE STAR(X, Y, SSIZE, DATASETLINE)
C**********************************************************************
C***  PLOTTING OF A STAR (CLIPPED)
C**********************************************************************
      CHARACTER*(*) DATASETLINE
      CHARACTER*80 ACTPAR
      LOGICAL BHATCH

!***  CHECK DATASETLINE FOR HATCHED OPTIONS:
      BHATCH=.FALSE.
      CALL SARGC (DATASETLINE, NARG)
      DO I=1, NARG
         CALL SARGV (DATASETLINE, I, ACTPAR) 
         IF (ACTPAR .EQ. 'HATCHED' .OR. ACTPAR .EQ. 'HTYPE') THEN
            BHATCH=.TRUE.
         ENDIF
      ENDDO      

      ASSIZE = ABS(SSIZE)
      F0 = 0.3333 * ASSIZE
      F1 = 0.5 * F0
      F2 = 0.866 * F0
      F3 = 0.5  * ASSIZE
      F4 = 0.866* ASSIZE
      CALL GCPLOT (X+F1, Y-F2, 3)
      CALL GCPLOT (X,    Y-ASSIZE, 2)
      CALL GCPLOT (X-F1, Y-F2, 2)
      CALL GCPLOT (X-F0, Y,    2)
      CALL GCPLOT (X-F4, Y+F3, 2)
      CALL GCPLOT (X-F1, Y+F2, 2)
      CALL GCPLOT (X+F1, Y+F2, 2)
      CALL GCPLOT (X+F4, Y+F3, 2)
      CALL GCPLOT (X+F0, Y,    2)
      CALL GCPLOT (X+F1, Y-F2, 2)

      IF (SSIZE .LT. .0) THEN
          CALL GFILL
      ELSEIF (BHATCH) THEN
          CALL HFILL(DATASETLINE)
      ENDIF       

C***  Inner octogon suppressed
      RETURN
      
C***  Inner octogon (drawn after symbol has been filled) 
      CALL GCPLOT (X+F1, Y+F2, 3)
      CALL GCPLOT (X+F0, Y,    2)
      CALL GCPLOT (X+F1, Y-F2, 2)
      CALL GCPLOT (X-F1, Y-F2, 2)
      CALL GCPLOT (X-F0, Y,    2)
      CALL GCPLOT (X-F1, Y+F2, 2)
      CALL GCPLOT (X+F1, Y+F2, 2)

      RETURN
      END
strpos.f/       1553528659  5006  320   100644  449       `
      SUBROUTINE STRPOS (TESTSTR, STR, IPOS)
C***  RETURNS THE POSITION IPOS OF THE TESTSTRING IN A STRING
      CHARACTER TESTSTR*(*), STR*(*)
      LAST = IDX(STR)
      L = LEN(TESTSTR)

      DO 1 I=1, LAST+1-L
      IF (STR(I:I+L-1) .EQ. TESTSTR) THEN
         IPOS = I
         GOTO 3
         ENDIF
    1 CONTINUE

C***  STRING NOT FOUND
    2 IPOS = 0
      RETURN

C***  STRING FOUND AT POSITION IPOS
    3 CONTINUE
      RETURN

      END

