swapint.f/      1553528659  5006  320   100644  222       `


	subroutine swapint(icount,buffer)
	integer*2 buffer(icount), j
 	byte bytes(2)
	equivalence( bytes, j )	
	byte b

	do 10 i=1,icount
	j=buffer(i)
	b=bytes(1)
	bytes(1)=bytes(2)
	bytes(2)=b
	buffer(i)=j
10	continue
	end	
