tsargc.f/       1553528659  5006  320   100644  446       `
      SUBROUTINE TSARGC(TEXT,N)

C**   Diese Funktion ist aequivalent zur entsprechenden C-Funktion.
C**   Sie ermittelt die Anzahl der Argumente in einem String.
C**   Das Parsen des Strings uebernimmt die Routine sargp.
C**   Dort sind auch die syntaktischen Regeln beschrieben.

      CHARACTER*(*) TEXT
      INTEGER AS,AE,N,I

      I=0 				! Do not look for any Argument
      CALL TSARGP(TEXT,N,I,AS,AE, MODESARG)

      RETURN

      END
tsargp.f/       1553528659  5006  320   100644  3858      `
      SUBROUTINE TSARGP (TEXT, N, I, AS, AE, MODESARG)

C***  Die Subroutine sargp zerlegt einen Text-String nach Worten
C***  Ermittelt werden:
C***  n : die Anzahl der Argumente und, 
C***            falls i in [1..n],
C***  as und ae : Start- und Endindex des i-ten Arguments.
C***  Geparsed wird nach folgenden Regel:
C***  Argumente werden ausschliesslich durch Leerzeichen getrennt.
C***  Interpretaion der Rueckgabewerte:
C***  n: immer die Anzahl der Argumente
C***  as=-1 -> Es wurde kein i-tes Argument gefunden (i nicht in [1..n])
C***  as=0  -> Das i-te Argument war leer (z.B. ",,")
C***  sonst : text(as:ae) = i-tes Argument
C***  MODESARG retourniert der Grund der Trennung:
C***   0 = Blank oder Zeilenende
C***   1 = - (Trennstrich)
C***   2 = \- (Silbentrennungsmoeglichkeit)
C***   3 = Zeilenende, LaTex string nicht abgeschlossen
C***  Erweiterung vom 3.1.2003: Solange ein Fraction oder LaTex-String 
C***  aktiv ist, wird jede Zerlegung unterbunden. 

      CHARACTER*(*) TEXT
      CHARACTER*1 BACKSLASH, THISCHAR, NEXTCHAR

      INTEGER N                  ! Out: Anzahl der Argumente
      INTEGER I                  ! In : gesuchtes Argument
      INTEGER AS,AE              ! Out: erste u. letzte Position des 
                                   !         Arguments im String

      INTEGER TL,TI
      INTEGER STATE

      BACKSLASH = CHAR(92)
      TL=LEN(TEXT)

      state=0
C      state=0 -> kein Argument aktiv
C      state=2 -> normales Argument aktiv

      N  = 0
      AS = -1
      AE = TL
cc      MODESARG = 0

      DO 100 TI=1,TL
      IF (MODESARG .EQ. 99) THEN
         MODESARG = 0
	 CYCLE
      ENDIF

      THISCHAR = TEXT(TI:TI)
      
C***  If a LaTex string is active, only an end is searched for      
C***  If this happens at begin of the string, the argument is the 0th
      IF (MODESARG .EQ. 3) THEN
         IF (THISCHAR .EQ. BACKSLASH) THEN
	    IF (TI .LT. TL) THEN
            NEXTCHAR = TEXT(TI+1:TI+1)
               IF (NEXTCHAR .EQ. ')' ) THEN
                  MODESARG = 99
                  IF (N .EQ. I) AE = TI + 1
                  CYCLE
               ENDIF
            ENDIF
         ENDIF
         CYCLE
      ENDIF
            
C***  There can at any time start a LaTex string      
      IF (THISCHAR .EQ. BACKSLASH) THEN
	 IF (TI .LT. TL) THEN
         NEXTCHAR = TEXT(TI+1:TI+1)
            IF (NEXTCHAR .EQ. '(' ) THEN
C***         LaTex starts while an argument is already active
             IF (STATE .EQ. 2) THEN
	       STATE = 0
               IF (N .EQ. I) AE = TI - 1
	       N = N + 1
               IF (N .EQ. I) AS = TI 
	     ELSE
               N = N + 1
               IF (N .EQ. I) AS = TI
	     ENDIF
             MODESARG = 3
             CYCLE
            ENDIF
         ENDIF
      ENDIF
            
C***  Looking for next start of an argument
      IF (STATE .EQ. 0) THEN
         IF (THISCHAR .EQ. ' ') GOTO 100
         STATE=2
         N=N+1
         IF (N .EQ. I) AS=TI
      ELSE 
C***  Looking for end of current argument
         IF (THISCHAR .EQ. ' ') THEN
            STATE=0
            IF (N .EQ. I) THEN 
               AE=TI-1
               MODESARG = 0
            ENDIF
         ELSEIF (THISCHAR .EQ. '-') THEN
            IF (TI .EQ. TL) THEN
               NEXTCHAR = ' '
              ELSE
               NEXTCHAR = TEXT(TI+1:TI+1)
            ENDIF
            IF (NEXTCHAR .NE. ' ') THEN
               STATE=0
               IF (N .EQ. I) THEN 
                  AE=TI
                  MODESARG = 1
                  IF (TI .GE. 2) THEN 
                     IF (TEXT(TI-1:TI-1) .EQ. BACKSLASH) MODESARG = 2 
                  ENDIF
               ENDIF
            ENDIF
         ENDIF
      ENDIF

100   CONTINUE

ccc   test output
c      write (49,'(5I3,1X,A)') 
c     > N, I, AS, AE, MODESARG, TEXT(AS:AE)

        RETURN
        END
tsargv.f/       1553528659  5006  320   100644  877       `
      SUBROUTINE TSARGV(TEXT,I,ARGTEXT, MODESARG)

C**   Diese Funktion ist fast aequivalent zur entsprechenden C-Funktion.
C**   Sie ermittelt das i-te Argument in einem String.
C**   Die Regeln zur Argumenttrennung sind in sargp beschrieben.
C**   Ist das i-te Argument nicht vorhanden, wird argtext nicht veraendert.
C***  MODESARG retourniert der Grund der Trennung (aus TSARGP): 
C***   0 = Blank
C***   1 = - (Trennstrich)
C***   2 = \- (Silbentrennungsmoeglichkeit)


      CHARACTER*(*) TEXT,ARGTEXT
      INTEGER I
      INTEGER N,AS,AE

      CALL TSARGP(TEXT,N,I,AS,AE,MODESARG)

      IF (AS .EQ. -1) GOTO 10
      IF (AS .EQ. 0) THEN
         ARGTEXT=' '
      ELSE
         ARGTEXT=TEXT(AS:AE)
         IF (MODESARG .EQ. 2) THEN
           ARGTEXT(AE-AS:AE-AS) = '-' 
           ARGTEXT(AE-AS+1:AE-AS+1) = ' ' 
         ENDIF
      ENDIF

10    RETURN

      END

turn.f/         1553528659  5006  320   100644  545       `
      SUBROUTINE TURN (DDX, DDY, DX, DY, ANGLE)
C**********************************************************
C***  TURNS THE VECTOR (DX, DY) BY THE ANGLE "ANGLE"
C***   - RESULT: VECTOR (DDX, DDY)
C***   - CALLED FROM SUBROUINE MYSYMBL (WRPLOT SYSTEM)
C**********************************************************

      DATA PI / 3.1415927 /

      COSA = COS(ANGLE *  PI / 180.)
      SINA = SIN(ANGLE *  PI / 180.)

      DXS = DX
      DYS = DY

      DDX =  COSA * DXS - SINA * DYS
      DDY =  SINA * DXS + COSA * DYS

      RETURN
      END

wnpar.f/        1553528659  5006  320   100644  3295      `
      SUBROUTINE WNPAR
C*********************************************************************
C***  Automatic calculation of stellar parameters
C***  from T*, Rt, v-inf, Mv-\t  (retrieved from RTT.TABLE)
C***  and  Mv               (retrieved from HRD.TABLE)
C*********************************************************************

      CHARACTER LINE*132, WR*3, CTLOG*5, CRTLOG*5, CVINF*4, CMVT*4
      CHARACTER LINE2*132, WR2*3, CMV*4, TYPE*9

      OPEN (1, FILE='RTT.TABLE', STATUS='OLD')
      OPEN (2, FILE='HRD.TABLE', STATUS='OLD')

      OPEN (10, FILE='WNPAR.OUT', STATUS='NEW')
      WRITE (10,12)
   12 FORMAT (' FILE: WNPAR.OUT', /)

C***  VIER DURCHLAEUFE:
      DO 100 I=1,4
      WRITE (10,2)
    2 FORMAT (1X, 75('-'), /, 
     >          56X, '.', 6X, '.', /
     >        ' WR   Type     log T* log Rt  V-inf Mv-t  Mv ', 
     >        '   R*   logM logL Mvc/L   M',
     >        /, 1X, 75('-') )

    1 READ (1,'(A)', END=99) LINE

      TYPE = LINE(6:14)
C***  2. DURCHLAUF: NUR WNE-s
      IF (I .EQ. 2) THEN 
         IF (TYPE(:5) .NE. 'WN3-s' .AND. 
     >       TYPE(:5) .NE. 'WN4-s' .AND. 
     >       TYPE(:5) .NE. 'WN5-s' .AND. 
     >       TYPE(:5) .NE. 'WN6-s' ) GOTO 1
         ENDIF
C***  3. DURCHLAUF: NUR WNE-w
      IF (I .EQ. 3) THEN 
         IF (TYPE(:5) .NE. 'WN3-w' .AND. 
     >       TYPE(:5) .NE. 'WN4-w' .AND. 
     >       TYPE(:7) .NE. 'WN4.5-w' .AND. 
     >       TYPE(:5) .NE. 'WN5-w' .AND. 
     >       TYPE(:6) .NE. 'WN5a-w' .AND. 
     >       TYPE(:5) .NE. 'WN6-w' ) GOTO 1
         ENDIF
C***  4. DURCHLAUF: NUR WNL
      IF (I .EQ. 4) THEN 
         IF (TYPE(:3) .NE. 'WN7' .AND. 
     >       TYPE(:3) .NE. 'WN8' .AND. 
     >       TYPE(:3) .NE. 'WN9' ) GOTO 1
         ENDIF

      WR = LINE(:3)
      CTLOG = LINE(42:46)
      CRTLOG= LINE(54:58)
      CVINF = LINE(67:70)
      CMVT  = LINE(74:77)

      IF (CTLOG .EQ. '     ' .OR. CVINF .EQ. '    ' .OR. 
     >    CRTLOG .EQ. '     ' .OR. CMVT .EQ. '     ') GOTO 1

      READ (CTLOG, '(F5.0)', ERR=1) TLOG
      IF (TLOG .EQ. .0) GOTO 1
      READ (CRTLOG, '(F5.0)', ERR=1) RTLOG
      READ (CVINF, '(I5)', ERR=1) INFV
      VINF = FLOAT(INFV)
      READ (CMVT, '(F5.0)', ERR=1) XMVT

C***  FIND CORRESPONDING LINE IN HRD.TABLE
   20 READ (2,'(A)', END=99) LINE2
      WR2 = LINE2(3:5)
      IF (WR2 .NE. WR) GOTO 20

      CMV = LINE2(28:31)
      IF (CMV .EQ. '   ') GOTO 1
      READ (CMV, '(F5.0)', ERR=1) XMV

C***  CALCULATION ... SEE WC-GRID PAPER
      R = 10**(0.2*(XMVT-XMV)+RTLOG)
      DOTM = 0.3 * (XMVT-XMV) + ALOG10(VINF/2500.) - 4.0
      XLOGL = 4. * TLOG + 2. * ALOG10(R) - 3.05
C***  RATIO OF MECHANICAL TO RADIATION FIELD MOMENTUM
      RMOM = 10.**(DOTM-XLOGL) * VINF * 0.493E8
C*** MASS-LUMINOSITY RELATION FOR WN STARS 
C***    (LANGER, 1989, A+A 210, 93, EQ. 18)
      XMASS = -0.158206 + (-0.053868 + 0.055467 * XLOGL) * XLOGL 
      XMASS = 10.**XMASS

      WRITE (10,22 ) LINE(:14), TLOG, RTLOG, VINF, XMVT, XMV, R, 
     >       DOTM, XLOGL, RMOM, XMASS
   22 FORMAT (1X, A14, F6.3, F7.3, F7.0, F5.1, F5.1, F6.1, F6.1, F5.1, 
     >        F6.1, F5.1)
      GOTO 1

   99 IF (I .NE. 4) THEN
        WRITE (10,13)
   13 FORMAT (1X, 75('-'), /,'1', //)
        REWIND (1)
        REWIND (2)
        ENDIF
  100 CONTINUE

      STOP 'O.K.'
      END

wrmult.f/       1718382206  5006  320   100644  4863      `
C***      PROGRAM WRMULT
      SUBROUTINE WRMULT

      CHARACTER*8   CKASOFS(6, 12, 2), CKASSKL(6), CFORMAT(6)
      CHARACTER*255 NAMEIN, NAMEIN2, NAMEINSEC, NAMEOUT
      CHARACTER*1024 LINE
      CHARACTER*60  ACTPAR, CKASLAB(6), USERNAME
      CHARACTER*2   CINPUT

      DATA (CFORMAT(I), I=1,6) / 'A4H',  'A4Q',  'A4H',  'A4H', 
     >                           'A4H' , 'A4H' /

      DATA (CKASSKL(I), I=1,6) / '0.75', '0.50', '0.42', '0.35', 
     >                           '0.28', '0.24' /

      DATA (CKASLAB(I), I=1,6) /
     >     '*KASDEF LAB  2.5 16.75  0.4',
     >     '*KASDEF LAB  2.5 16.5  0.4',
     >     '*KASDEF LAB  2.5 18.0  0.4', 
     >     '*KASDEF LAB  2.5 17.5  0.4', 
     >     '*KASDEF LAB  2.5 18.5  0.4',
     >     '*KASDEF LAB  2.5 18.5  0.4'/

C***  Zweier-Plot
      DATA ((CKASOFS(1, I, J), J=1, 2), I=1, 2)
     >     / '4.0', '15.5', '4.0', '1.5' /

C***  Vierer-Plot
      DATA ((CKASOFS(2, I, J), J=1, 2), I=1, 4)
     >     / '2.0', '10.75', '14.5', '10.75',
     >       '2.0', '1.5', '14.5', '1.5' /

C***  Sechser-Plot
      DATA ((CKASOFS(3, I, J), J=1, 2), I=1, 6)
     >     / '1.8', '20.0', '11.6', '20.0', '1.8', '11.0', 
     >       '11.6', '11.0', '1.8', '2.0', '11.6', '2.0' /
      
C***  Achter-Plot
      DATA ((CKASOFS(4, I, J), J=1, 2), I=1, 8)
     >     / '2.4', '22.5', '11.6', '22.5', 
     >       '2.4', '15.5', '11.6', '15.5', '2.4', '8.5', 
     >       '11.6', '8.5', '2.4', '1.5', '11.6', '1.5' /
      
C***  Zehner-Plot
      DATA ((CKASOFS(5, I, J), J=1, 2), I=1, 10)
     >     / '2.4', '23.0', '11.6', '23.0', 
     >       '2.4', '17.5', '11.6', '17.5', 
     >       '2.4', '12.0', '11.6', '12.0', '2.4', '7.0', 
     >       '11.6', '7.0', '2.4', '1.5', '11.6', '1.5' /
C***  Zwoelfer-Plot
      DATA ((CKASOFS(6, I, J), J=1, 2), I=1, 12)
     >     / '2.4', '24.0', '11.6', '24.0', 
     >       '2.4', '19.5', '11.6', '19.5', 
     >       '2.4', '15.0', '11.6', '15.0', 
     >       '2.4', '10.5', '11.6', '10.5', 
     >       '2.4', '6.0',  '11.6', '6.0', 
     >       '2.4', '1.5',  '11.6', '1.5' /
      

C***  NAME DES INPUT-FILES?
      WRITE (6,*) 'Name des INPUT-FILES = '
      WRITE (6,'(A)') 'Present directory is:'
      CALL SYSTEM ('pwd')
      READ (*, '(A)') NAMEIN
      NAMEIN = NAMEIN(:IDX(NAMEIN))

      OPEN (UNIT=1,FILE=NAMEIN, STATUS='OLD',ERR=99) 

      CALL GETENV ('USER', USERNAME)
      NAMEOUT = '/tmp/' // USERNAME(:IDX(USERNAME)) // '.' //
     >          NAMEIN(:IDX(NAMEIN)-5) // '.multi.plot'
      OPEN (UNIT=2,FILE=NAMEOUT, STATUS='UNKNOWN') 

      WRITE (6,*) 'OUTPUT-FILE = ',NAMEOUT( :IDX(NAMEOUT))
      WRITE (6,*)
      WRITE (6,*)
1     WRITE (6,'(A,A)') 
     >  'Zweier (2), Vierer(4), Sechser(6), ',
     >  'Achter(8) oder Zehner(10) Plot ?'
      READ  (5,'(A)') CINPUT
      CALL SARGV(CINPUT, 1, ACTPAR)
      IF (ACTPAR .EQ. '2') THEN
        NPLOT = 1
      ELSE IF (ACTPAR .EQ. '4') THEN
        NPLOT = 2
      ELSE IF (ACTPAR .EQ. '6') THEN
        NPLOT = 3
      ELSE IF (ACTPAR .EQ. '8') THEN
        NPLOT = 4
      ELSE IF (ACTPAR .EQ. '10') THEN
        NPLOT = 5
      ELSE IF (ACTPAR .EQ. '12') THEN
        NPLOT = 6
      ELSE
        WRITE (6,*) 'ILLEGAL INPUT : ',CINPUT
        WRITE (6,*) 'TRY AGAIN'
        WRITE (6,*)
        GOTO 1
      ENDIF

      IPLOT = 0

C***  VORSPANN
   20 CONTINUE
      WRITE (2, '(A)') 'MULTIPLOT START'
      WRITE (2, '(2A)') 'PAPERFORMAT ', CFORMAT(NPLOT)
C***  SUCHE NACH DER ERSTEN PLOT-ZEILE
2     CONTINUE
        READ (1, '(A)', END=50) LINE
        CALL SARGV (LINE, 1, ACTPAR)
      IF (ACTPAR .NE. 'PLOT') GOTO 2
C***  SCHREIBEN DER PLOT ZEILE UND DER KASDEF ANWEISUNGEN
      IPLOT = IPLOT + 1
      IF (IPLOT .GT. 2*NPLOT) THEN
        WRITE (6,*) 'MULTIPLOT has more than one page'
        WRITE (2, '(A)') 'MULTIPLOT END'
        WRITE (2, '(A)') 'MULTIPLOT START'
        WRITE (2, '(2A)') 'PAPERFORMAT ', CFORMAT(NPLOT)
        IPLOT = 1
      ENDIF

      WRITE (2, '(A)') LINE ( :IDX(LINE))
      WRITE (2, '(4A)') 'KASDEF OFS ', 
     >        CKASOFS(NPLOT, IPLOT, 1)( :IDX(CKASOFS(NPLOT, IPLOT, 1))),
     >        '  ',
     >        CKASOFS(NPLOT, IPLOT, 2)( :IDX(CKASOFS(NPLOT, IPLOT, 2)))
      WRITE (2, '(2A)') 'KASDEF SKL ',
     >                  CKASSKL(NPLOT)( :IDX(CKASSKL(NPLOT)))
      IF (IPLOT .EQ. 1) THEN
        WRITE(2,'(A)') CKASLAB(NPLOT)( :IDX(CKASLAB(NPLOT))) // '  '
      ENDIF
C***  SCHLEIFE BIS ZUM ENDE DIESES PLOTS
10    CONTINUE
        READ (1, '(A)') LINE
        CALL SARGV (LINE, 1, ACTPAR)
        WRITE (2, '(A)') LINE ( :IDX(LINE))
        IF (ACTPAR(1:3) .EQ. 'END') GOTO 2
      GOTO 10

C***  SCHREIBEN DES ENDES
50    WRITE (2, '(A)') 'MULTIPLOT END'


      CLOSE (1)
      CLOSE (2)
      STOP 'STOP OKAY'

99    WRITE (6,*) 'ERROR WHEN OPENING INPUT FILE ',NAMEIN( :IDX(NAMEIN))
      STOP

      END

wrpcross.f/     1553528659  5006  320   100644  4217      `
      SUBROUTINE WRPCROSS (X,Y,T,NDAT, NSET, NDATMAX, NSETMAX, X1, 
     >                     Y1, B, C)
C**********************************************************************
C***  CALLED FROM: WRPLOT
C***   FIND ALL CROSSING POINT BETWEEN INTERPOLATION CURVES 
C***    DEFINED BY THE DATASETS
C***  THE OUTPUT IS DISPLAYED  AND WRITTEN ON FILE "CROSSPOINTS."
C**********************************************************************

      PARAMETER (NFINEMAX = 10000)
      DIMENSION XFINE(2,NFINEMAX), YFINE(2,NFINEMAX), NFINE(2)

      DIMENSION X1(NDATMAX), Y1(NDATMAX)
      DIMENSION X(NDATMAX,NSETMAX), Y(NDATMAX,NSETMAX), T(NDATMAX) 
      DIMENSION NDAT(NSETMAX)
      DIMENSION B(6), C(6)

      OPEN (7, FILE='CROSSPOINTS.', STATUS='UNKNOWN')


C***  DEMANDED ACCURACY
      EPS = 0.05

C***  LOOP OVER ALL PAIRS OF DATASETS  ********************************
      DO 20 ISET1=1, NSET

C*** EXPAND FIRST DATASET ON FINE SCALE
C***  FIRST: CONVERSION INTO CM UNITS
      DO 19 I = 1, NDAT(ISET1)
          X1(I) = (X(I,ISET1)-B(2)) * B(1)
          Y1(I) = (Y(I,ISET1)-C(2)) * C(1)
   19 CONTINUE

C***  CUBIC INTERPOLATION OF CURVES (NOT NECESSARILY FUNCTIONS!)
C***  DEFINE PARAMETER VECTOR (PATH LENGTH)
      T(1) = .0
      DO 60 I=2, NDAT(ISET1)
      DX = X1(I) - X1(I-1)
      DY = Y1(I) - Y1(I-1)
   60 T(I) = T(I-1) + SQRT (DX*DX + DY*DY)

      STEP = 0.5 * EPS
      TT = .0
      NFINE(1) = 1
      XFINE(1,1) = X1(1)
      YFINE(1,1) = Y1(1)

   61 TT = TT + STEP
      IF (TT .LE. T(NDAT(ISET1))) THEN
         CALL FSPLINE (XX, TT, X1, T, NDAT(ISET1))
         CALL FSPLINE (YY, TT, Y1, T, NDAT(ISET1))
         NFINE(1) = NFINE(1) + 1
         IF (NFINE(1) .GE. NFINEMAX) THEN
             RETURN
             ENDIF
         XFINE(1,NFINE(1)) = XX
         YFINE(1,NFINE(1)) = YY
         GOTO 61
        ELSE
         NFINE(1) = NFINE(1) + 1
         XFINE(1,NFINE(1)) = X1(NDAT(ISET1))
         YFINE(1,NFINE(1)) = Y1(NDAT(ISET1))
        ENDIF



      DO 20 ISET2=ISET1+1, NSET

C***  EXPAND SECOND DATASET ON FINE SCALE
C***  CONVERSION INTO CENTIMETER UNITS 
      DO 18 I = 1, NDAT(ISET2)
          X1(I) = (X(I,ISET2)-B(2)) * B(1)
18        Y1(I) = (Y(I,ISET2)-C(2)) * C(1)

C***  CUBIC INTERPOLATION OF CURVES (NOT NECESSARILY FUNCTIONS!)
C***  DEFINE PARAMETER VECTOR (PATH LENGTH)
      T(1) = .0
      DO 70 I=2, NDAT(ISET2)
      DX = X1(I) - X1(I-1)
      DY = Y1(I) - Y1(I-1)
   70 T(I) = T(I-1) + SQRT (DX*DX + DY*DY)

      TT = .0
      NFINE(2) = 1
      XFINE(2,1) = X1(1)
      YFINE(2,1) = Y1(1)

   71 TT = TT + STEP
      IF (TT .LE. T(NDAT(ISET2))) THEN
         CALL FSPLINE (XX, TT, X1, T, NDAT(ISET2))
         CALL FSPLINE (YY, TT, Y1, T, NDAT(ISET2))
         NFINE(2) = NFINE(2) + 1
         IF (NFINE(2) .GE. NFINEMAX) THEN
             PRINT *, 'DIMENSION NFINEMAX INSUFFICIENT - ABORT'
             RETURN
             ENDIF
         XFINE(2,NFINE(2)) = XX
         YFINE(2,NFINE(2)) = YY
         GOTO 71
        ELSE
         NFINE(2) = NFINE(2) + 1
         XFINE(2,NFINE(2)) = X1(NDAT(ISET2))
         YFINE(2,NFINE(2)) = Y1(NDAT(ISET2))
        ENDIF
      


C***  DETERMINE CROSSING POINT AS MINIMUM DISTANCE BETWEEN DATA POINTS
C***     FROM EACH OF BOTH PLOTS
      DMIN = 1000.
      DO 10 I1 = 1, NFINE(1)
      DO 10 I2 = 1, NFINE(2)
      DIST = ABS(XFINE(1,I1) - XFINE(2,I2)) 
     >       + ABS(YFINE(1,I1) - YFINE(2,I2))
      IF (DIST .LT. DMIN) THEN
         XMIN = 0.5 * (XFINE(1,I1) + XFINE(2,I2))
         YMIN = 0.5 * (YFINE(1,I1) + YFINE(2,I2))
         DMIN = DIST
         ENDIF   
   10 CONTINUE


C***  PRINT OUTPUT TABLE
      IF (DMIN .LE. EPS) THEN
C***     CONVERT BACK INTO UNITS
         XMIN = XMIN / B(1) + B(2)
         YMIN = YMIN / C(1) + C(2)
         WRITE (*,'(2F11.4, 2(A,I3))') XMIN, YMIN, 
     >                           '  SET', ISET1, '   SET', ISET2
         WRITE (7,'(2F11.4, 2(A,I3))') XMIN, YMIN, 
     >                           '  SET', ISET1, '   SET', ISET2
         ENDIF

   20 CONTINUE
C***  END OF LOOP OVER ALL PAIRS OF DATASETS *****************************

      PRINT *, 'Search for crossing points completed'
      PRINT *, 'Table written on File "CROSSPOINTS."'
      RETURN

      END

wrssum.f/       1553528659  5006  320   100644  2819      `
C***********************************************************************
C     Prograemmchen zum Auswerten der WRPLOT.STATISTIC 
C***********************************************************************
C!!!      PROGRAM WRSSUM
      SUBROUTINE WRSSUM

      PARAMETER (MAXUSER = 20)

      CHARACTER LINE*80, DEVICE*2, FNAME*255 
      CHARACTER*8 USERI(MAXUSER), USER
      CHARACTER*18 LASTUSE(MAXUSER), FIRSTUSE
      DIMENSION NCALLS(MAXUSER), NSCREEN(MAXUSER), NPSC(MAXUSER)

C***  Absolute Filename of Statistic File
cc      FNAME = '/home/usr1/lars/wrplot/wrplot.statistic'
cc    The installation directory is now defined by a SHELL Variable:
      CALL GETENV ('PATH_WRPLOT', FNAME)
      IF (FNAME .EQ. '') THEN
         WRITE (*, '(A)') '*** Shell variable PATH_WRPLOT undefined'
         WRITE (*, '(A)') '*** give: setenv PATH_WRPLOT ... '
         STOP 'ERROR IN PROGRAM WRSSUM'
      ENDIF
      FNAME = FNAME(:IDX(FNAME)) // '/admin.dir/wrplot.statistic'
cc      print *, 'PATH_WRPLOT=', FNAME 

      FIRSTUSE = ' '

      OPEN (1, FILE=FNAME, STATUS='OLD')

      DO I=1, MAXUSER
        NCALLS(I)  = 0
        NSCREEN(I) = 0
        NPSC(I)    = 0
      ENDDO
      
      NCSUM = 0
      NPSUM = 0
      NSSUM = 0
      NUSER = 0
      ILINE = 0

    1 CONTINUE
      READ (1,'(A)', END=99) LINE
      ILINE = ILINE + 1

      IF (FIRSTUSE .EQ. ' ') FIRSTUSE = LINE(:18)

C***  FIND USER INDEX
      USER = LINE(20:27)
      DO I=1, NUSER
         IF (USER .EQ. USERI(I)) THEN
            IUSER = I
            GOTO 2
         ENDIF
      ENDDO

      NUSER = NUSER + 1
      IUSER = NUSER
      USERI(IUSER) = USER

    2 CONTINUE
      
C***  Account to the present user:
      DEVICE = LINE(29:30)
      IF      (DEVICE .EQ. '-1') THEN
         NCALLS(IUSER) = NCALLS(IUSER) + 1
      ELSE IF (DEVICE .EQ. ' 3') THEN
         NPSC(IUSER) = NPSC(IUSER) + 1
      ELSE IF (DEVICE .EQ. ' 5') THEN
         NSCREEN(IUSER) = NSCREEN(IUSER) + 1
      ELSE
         WRITE (*, '(A,I6,A)') 'LINE', ILINE, ' INVALID'
      ENDIF
      LASTUSE(IUSER) = LINE(:18)

      GOTO 1
C************* END of loop *********************

   99 CONTINUE

      WRITE (6,*) 
      WRITE (6,22) 
   22 FORMAT(50('-')) 
      WRITE (6,'(A)') 'WRPLOT user statistic since '// FIRSTUSE
      WRITE (6,22) 
      WRITE (6,'(A)') ' User     Calls   Screen    ps       Last Use'
      WRITE (6,22) 

      DO I=1, NUSER
       WRITE (6,20) USERI(I), NCALLS(I), NSCREEN(I), NPSC(I), LASTUSE(I)       
   20  FORMAT (A, I7, I7, I7, 2X, A)
       NCSUM = NCSUM + NCALLS(I)
       NPSUM = NPSUM + NPSC(I)
       NSSUM = NSSUM + NSCREEN(I)
      ENDDO
      WRITE (6,22) 
      WRITE (6,21) NUSER, NCSUM, NSSUM, NPSUM       
   21 FORMAT (I2, ' USER ', I7, I7, I7)
      WRITE (6,22) 
      WRITE (6,*) 

      STOP 'O.K.'
      END

wrstat.f/       1553528659  5006  320   100644  665       `
      SUBROUTINE WRSTAT (STATLINE, USER, IDEV)
C****************************************************************
C***  USER STATISTICS
C***  Line added to statistic file for each plot  
C****************************************************************

      COMMON / COMWRSTAT / WRSTATFIL
      CHARACTER*255 WRSTATFIL

      CHARACTER USER*8
      CHARACTER STATLINE*30, DAT*9, TIM*8, SHELLCOMMAND*255

      CALL DATE(DAT)
      CALL TIME(TIM)

C***  Create statistic line 
      WRITE (STATLINE, '(A,1X,A,1X,A,I3)') DAT, TIM, USER, IDEV 
      SHELLCOMMAND = 'echo "' // STATLINE // '" >> ' // WRSTATFIL
      CALL SYSTEM(SHELLCOMMAND)
      RETURN

      END 

