      SUBROUTINE X_GINPUT (XCM, YCM)
C***********************************************************************
C***  GRAPHIC INPUT
C***  ON MOUSECLICK, RETURNS THE CURSER POSITIONS IN CM RELATIVE TO
C***  THE LOWERLEFT CORNER OF THE BOX. GLOBAL SCALING (OFS, FORMARFACTOR)
C***  IS ACCOUNTED FOR
C***********************************************************************

C***  Transformation coefficients 
      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA

C***  FIRST ARGUMENT = CURSOR REPRESENTATION

      CALL acc_xgetposition (24, X, Y)
CCC      write (*,*) 'x_ginput: x,y=',x,y

      XCM = (X - XOFFSET) / FORMATFA 
      YCM = (Y - YOFFSET) / FORMATFA 
CCC      write (*,*) 'xoff, yoff, for=',xoffset, yoffset, formatfa
CCC      write (*,*) 'x_ginput: xcm,ycm=',xcm,ycm
CCC      write (*,*) 

      RETURN
