x_movedraw.f/   1555062890  5006  320   100644  1290      `
      SUBROUTINE X_MOVEDRAW (X, Y, ISWITCH)
C*****************************************************
C***  X11OWN DRIVER: Move or Draw, X and Y in pt
C*****************************************************

C***  Counter of points in the active path
      COMMON / COMICOUNT / ICOUNT
C***  Storage vectors of current path for possible colour filling
      PARAMETER (MAXPATH=10000)
      COMMON / COMPATH / XPATH(MAXPATH), YPATH(MAXPATH)

C***  Scale Factor (conversion pt --> cm)
      COMMON / COMCMPT / CMPT

      XCM = X / CMPT
      YCM = Y / CMPT

C***  Draw
      IF (ISWITCH .EQ. 2) THEN 
         IF (ICOUNT .LE. 0) THEN
          WRITE (*,*) '>>>    Draw before MOVE             <<<'
          STOP        '>>> FATAL ERROR IN SUBR. X_MOVEDRAW <<<'
          ENDIF
         CALL acc_xdrawline (XPATH(ICOUNT), YPATH(ICOUNT), XCM, YCM)
         ICOUNT = ICOUNT + 1
         IF (ICOUNT .GT. MAXPATH) ICOUNT=1
         XPATH(ICOUNT) = XCM
         YPATH(ICOUNT) = YCM
C***  Move 
      ELSE IF (ISWITCH .EQ. 3) THEN
         ICOUNT = 1
         XPATH(1) = XCM
         YPATH(1) = YCM
C***  wrong choice of ISWITCH:
      ELSE
         CALL X_PLTEND
         WRITE (*, *) '>>> ISWITCH=', ISWITCH, ' NOT ALLOWED <<<'
         STOP 'ERROR IN X_MOVEDRAW'
      ENDIF

      RETURN
      END
x_newcolor.f/   1553528659  5006  320   100644  762       `
      SUBROUTINE X_NEWCOLOR (R, G, B)
C***************************************************************
C***  OWN X11 DRIVER: SET NEW COLOR
C***************************************************************

C***  In order to adapt to the limits of a graphic card, the number of 
C***  colors can be restricted by the KASDEF option LIMITCOLOR
C***  This information is in the following common block

      COMMON /LIMITCOLOR/ LIMCOL_ON, LIMCOLR, LIMCOLG, LIMCOLB

      IF (LIMCOL_ON .GT. 0) THEN
        RR = FLOAT(NINT(R*LIMCOLR)) / LIMCOLR  
        GG = FLOAT(NINT(G*LIMCOLG)) / LIMCOLG  
        BB = FLOAT(NINT(B*LIMCOLB)) / LIMCOLB  
        CALL acc_xsetcolor (rr, gg, bb)
      ELSE
        CALL acc_xsetcolor (r, g, b)
      ENDIF

      RETURN
      END
x_newpen.f/     1553528659  5006  320   100644  952       `
      SUBROUTINE X_NEWPEN (I)
C***************************************************************
C***  X11OWN DRIVER: DEFINE new linewidth
C***************************************************************
      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA

C***  Counter of points in the active path
      COMMON / COMICOUNT / ICOUNT

C***  Unit width in cm: 1/300 inch = standard resolution
      PARAMETER (WIDTH1 = 0.0084)

C***  Linewidth parameters
      COMMON / COMPEN /LASTPEN, HALFLINW

C***  Reset counter, i.e. a MOVE action is necessary after Pen change
      ICOUNT = 0

C***  Suppress repeated setting of unchanged linewidth
      IF (I .NE. LASTPEN) THEN 
         WIDTHCM = I * WIDTH1
C***  Changed to skale linewidth with FORMATFACTOR, wrh 03-Sep-2008
ccc         WIDTHCM = I * WIDTH1 * FORMATFA
         CALL acc_xsetlinewidth (WIDTHCM)
         LASTPEN = I 
         HALFLINW = WIDTHCM * 0.5
         ENDIF

      RETURN
      END
x_plot.f/       1553528659  5006  320   100644  3605      `
      SUBROUTINE X_PLOT (X, Y, ISWITCH)
C***************************************************************
C***  OWN X DRIVER: X, Y in cm (absolute)
C***       ISWITCH = 3: Move
C***                 2: Draw
C***                -2: Define offset
C***                -3: Define Offset
C***               997: Define Clipping Minima
C***               998: Define Clipping Maxima
C***************************************************************

C***  Transformation coefficients 
      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA

C***  Conversion factor cm -> pt defined in X_PLOTS
      COMMON / COMCMPT / CMPT 

C***  Clipping Path (ICLIP=1: Full Paper; 2: special clipping)
      COMMON / COMCLIP / ICLIP, CXMIN(2), CXMAX(2), CYMIN(2), CYMAX(2)

C***  Counter of points in the active path
      COMMON / COMICOUNT / ICOUNT

      LOGICAL THISOUT, LASTOUT
      SAVE LASTOUT, XLAST, YLAST
      DATA LASTOUT / .TRUE. /

      XPT = (X * FORMATFA + XOFFSET) * CMPT
      YPT = (Y * FORMATFA + YOFFSET) * CMPT

      THISOUT = ( XPT - CXMIN(ICLIP) ) * ( XPT - CXMAX(ICLIP) ) .GT. .0 
     >     .OR. ( YPT - CYMIN(ICLIP) ) * ( YPT - CYMAX(ICLIP) ) .GT. .0 

C***  Draw
      IF (ISWITCH .EQ. 2) THEN
         IF (ICOUNT .EQ. 0 .AND. .NOT. LASTOUT) THEN
            CALL X_PLTEND
            WRITE (6,*) '>>>  Draw action without preceeding Move <<<'
            STOP 'ERROR IN X_PLOT'
            ENDIF

C***     Last and this point inside clipping path
         IF (.NOT. LASTOUT .AND. .NOT. THISOUT) THEN
            CALL X_MOVEDRAW (XPT, YPT, 2)

C***     Last point outside, this point inside clipping path
         ELSE IF (LASTOUT .AND. .NOT. THISOUT) THEN
C***        Find intersection with clipping path, insert move
            CALL PSX_CLIPAUX 
     >          (XLAST, YLAST, XPT, YPT, XS1, YS1, XS2, YS2, NS)
            CALL X_MOVEDRAW (XS1, YS1, 3)
            CALL X_MOVEDRAW (XPT, YPT, 2)

C***     Last point inside, this point outside clipping path
         ELSE IF (.NOT. LASTOUT .AND. THISOUT) THEN
C***        Find intersection with clipping path, 
C***        then draw to that point 
            CALL PSX_CLIPAUX 
     >          (XLAST, YLAST, XPT, YPT, XS1, YS1, XS2, YS2, NS)
            CALL X_MOVEDRAW (XS1, YS1, 2)

C***     Both points outside clipping path
         ELSE IF (LASTOUT .AND. THISOUT) THEN
C***        Find zero or two intersection points
            CALL PSX_CLIPAUX 
     >          (XLAST, YLAST, XPT, YPT, XS1, YS1, XS2, YS2, NS)
            IF (NS .EQ. 2) THEN
               CALL X_MOVEDRAW (XS1, YS1, 3)
               CALL X_MOVEDRAW (XS2, YS2, 2)
               ENDIF
         ENDIF

C***  Move (only if point inside clipping path)
      ELSE IF (ISWITCH .EQ. 3) THEN
         IF (.NOT. THISOUT) CALL X_MOVEDRAW (XPT, YPT, 3)

C***  Define Offsets
      ELSE IF (ISWITCH .EQ. -3 .OR. ISWITCH .EQ. -2) THEN
          XOFFSET = X * FORMATFA + XOFFSET
          YOFFSET = Y * FORMATFA + YOFFSET

C***  Define Clipping path (never larger than full paper)
      ELSE IF (ISWITCH .EQ. 997) THEN
          CXMIN(2) = AMAX1(CXMIN(1), XPT)
          CYMIN(2) = AMAX1(CYMIN(1), YPT)
      ELSE IF (ISWITCH .EQ. 998) THEN
          CXMAX(2) = AMIN1(CXMAX(1), XPT)
          CYMAX(2) = AMIN1(CYMAX(1), YPT) 

C***  wrong or un-implemented choice if ISWITCH:
      ELSE
         CALL X_PLTEND
         WRITE (*, *) '>>> ISWITCH=', ISWITCH, ' NOT ALLOWED <<<'
         STOP 'ERROR IN X_PLOT'
      ENDIF

C***  Reset Clipping switch
      ICLIP = 1

C***  Keep last point in mind
      XLAST = XPT
      YLAST = YPT
      LASTOUT = THISOUT

      RETURN
      END

x_plots.f/      1553528659  5006  320   100644  1408      `
      SUBROUTINE X_PLOTS (KANAL, IDEV, PSIZEX, PSIZEY)
C*****************************************************
C***  Interface for X11OWN driver: Open Xwindow
C*****************************************************

C***  Transformation coefficients 
      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA
      
C***  Linewidth parameters
      COMMON / COMPEN /LASTPEN, HALFLINW

C***  Clipping Path (ICLIP=1: Full Paper; 2: special clipping)
      COMMON / COMCLIP / ICLIP, CXMIN(2), CXMAX(2), CYMIN(2), CYMAX(2)

C***  Counter of points in the active path
      COMMON / COMICOUNT / ICOUNT

C***  Define scale 
      COMMON / COMCMPT / CMPT

C***  Position of window 
      PARAMETER (ILEFT = 10)
      PARAMETER (IUPPER = 10)
      CALL acc_xplots ('WRPLOT'//CHAR(0), PSIZEX, PSIZEY, 
     >                 ILEFT, IUPPER )

      CMPT = 28.34

C***  Initalize OFFSET values AND SCALEFACTOR
      XOFFSET = .0
      YOFFSET = .0
      FORMATFA = 1. 

C***  Initialize clipping path (full paper)
      ICLIP = 1 
      CXMIN(1) = .0
      CXMIN(2) = .0
      CYMIN(1) = .0
      CYMIN(2) = .0
      CXMAX(1) = CMPT * PSIZEX
      CXMAX(2) = CMPT * PSIZEX
      CYMAX(1) = CMPT * PSIZEY
      CYMAX(2) = CMPT * PSIZEY

C***  INITIALIZE LASTPEN 
      LASTPEN = 0

C***  Initialize active-path point counter
      ICOUNT = 0

C***  Initialize Graphic State Matrix
      CALL GS_INIT

      RETURN
      END
