rydberg.f/      1653499781  5006  320   100644  1347      `
      SUBROUTINE RYDBERG
C************************************************************************
C***  CALCULATION OF LAB WAVELENGTHS FOR HE II LINES
C***     FROM RYDBERG'S FORMULA
C***  RYDBERG CONSTANT FROM LANG: ASTROPHYSICAL FORMULAE
C***  REFRACTIVE INDEX OF AIR FROM ALLEN ASTROPHYSICAL QUANTITIES
C************************************************************************

      PARAMETER (LOWMAX=12)

      DIMENSION XLAMBDA(LOWMAX)
      CHARACTER*1 AIRKEY(LOWMAX)

      DATA RYD / 438889.2 /
      DATA REF / 1.000293 /

      KANAL=1

      OPEN (1, FILE='RYDBERG.LIS', STATUS='NEW')
      WRITE (KANAL, *) 'WAVELENGHTS OF HE II LINES (*=AIR, ELSE VACUUM)'
      WRITE (KANAL, *)
      WRITE (KANAL, '(1X,12I10)') (LOW, LOW=1,LOWMAX)
      WRITE (KANAL, *)

      DO 1 NUP=2, 32

      DO 3 LOW=1, LOWMAX
      XLAMBDA(LOW)=.0
    3 AIRKEY(LOW) = ' '

      DO 2 LOW=1, MIN(NUP-1, LOWMAX)
      XLAMBDA(LOW) = 1.E8/
     >   ((1./FLOAT(LOW*LOW) - 1./FLOAT(NUP*NUP))* RYD)
        IF (XLAMBDA(LOW) .GT. 3500.) THEN
         AIRKEY(LOW) = '*'
         XLAMBDA(LOW) = XLAMBDA(LOW) / REF
         ENDIF
        IF (XLAMBDA(LOW) .GE. 1.E5) XLAMBDA(LOW)=0.
    2 CONTINUE

      WRITE (KANAL,4) NUP, (XLAMBDA(LOW), AIRKEY(LOW), LOW=1, LOWMAX)
    4 FORMAT (I3, 1X, 12(F9.2,A1))

    1 CONTINUE

      CLOSE (1)
      STOP 'O.K.'
      END

sar.f/          1553528659  5006  320   100644  2760      `
      SUBROUTINE SAR
C********************************************************************
C***  Program zum Suchen und Ersetzen von Strings in einem File
C***  Das Such- und Ersetzungswort steht in dem File : SAR.INPUT
C**** und sieht folgendermassen aus :
C***     SEARCH=/tmp/supas019
C***     REPLACE=/perm/supas019
C********************************************************************

      CHARACTER*255 FINPUT, FFILE
      CHARACTER LINE*132, OUTLINE*132, ACTPAR*60, CSEARCH*60, CREPL*60
      LOGICAL BREPL

C***  EINLESEN DES SUCH- UND DES ERSETZUNGSWORTES
      OPEN (UNIT=1, FILE='SAR.INPUT', STATUS='OLD', ERR=99)
20    CONTINUE
        READ (1, '(A)', END=30) LINE
        CALL SARGV (LINE, 1, ACTPAR)
        IF (ACTPAR .EQ. 'SEARCH') THEN
          CALL SARGP (LINE, N, 2, IAS, IAE)
          IDS = IAE - IAS
          CSEARCH = LINE (IAS:IAE)
        ELSE IF (ACTPAR .EQ. 'REPLACE') THEN
          CALL SARGP (LINE, N, 2, IAS, IAE)
          IDR = IAE - IAS
          CREPL = LINE (IAS:IAE)
        ENDIF
      GOTO 20
30    CONTINUE
      CLOSE (1)

C***  EINLESEN UND OEFFNEN DES INPUT- UND DES OUTPUT-FILES
      WRITE(*,*) 'Bitte geben Sie den File-Namen ein!'
      CALL GETNAM(FFILE,'[]')
      IDF = IDX (FFILE)
      I = IDF
40    CONTINUE
        IF (FFILE(I:I) .EQ. ';') THEN
          GOTO 42
        ELSE
          I = I - 1
        ENDIF
      GOTO40
42    CONTINUE
      FFILE = FFILE( :I-1)

      OPEN (UNIT=2,FILE=FFILE, STATUS='OLD',RECL=132, ERR=99)
      OPEN (UNIT=3,FILE=FFILE, STATUS='NEW', RECL=132)

      WRITE (*,*)
      WRITE (*,*) 'Search for :', CSEARCH
      WRITE (*,*) 'Replace by :', CREPL
      WRITE (*,*)
      WRITE (*,*)

      NREP = 0

C***  LOOP
10    CONTINUE
        READ (2, '(A)', END=80) LINE
        BREPL = .FALSE.
        OUTLINE = ' '
        IDO = 0
        IDL = IDX(LINE)
        N = IDL
        I = 1
12      CONTINUE
          IF (I .GT. N) GOTO 14
          IF (LINE(I:I+IDS-1) .EQ. CSEARCH( :IDS)) THEN
            BREPL = .TRUE.
            OUTLINE = OUTLINE( :IDO) // CREPL( :IDR)
            I = I + IDS
            IDO = IDO + IDR
            NREP = NREP + 1
          ELSE
            OUTLINE = OUTLINE( :IDO) // LINE(I:I)
            I = I + 1
            IDO = IDO + 1
          ENDIF
        GOTO 12
14      CONTINUE
        IDO = IDX (OUTLINE)
        WRITE (3, '(A)') OUTLINE( :IDO)
        IF (BREPL) THEN
          WRITE (*,*) 'Source       :', LINE( :IDL)
          WRITE (*,*) 'Destionation :', OUTLINE( :IDO)
          WRITE (*,*)
        ENDIF
      GOTO 10
C***  ENDLOOP

80    CONTINUE
      WRITE(*,*)
      WRITE(*,*) NREP, ' Replace-Operations have been performed'

      STOP 'OKAY'

   99 WRITE(*,*) 'Oeffnen des Input-Files fehlerhaft!'
      STOP 

      END
sargc.f/        1553528659  5006  320   100644  434       `
      SUBROUTINE SARGC(TEXT,N)

C**   Diese Funktion ist aequivalent zur entsprechenden C-Funktion.
C**   Sie ermittelt die Anzahl der Argumente in einem String.
C**   Das Parsen des Strings uebernimmt die Routine sargp.
C**   Dort sind auch die syntaktischen Regeln beschrieben.

      CHARACTER*(*) TEXT
      INTEGER AS,AE,N,I

      I=0 				! Do not look for any Argument
      CALL SARGP(TEXT,N,I,AS,AE)

      RETURN

      END
