      SUBROUTINE SARGCL(TEXT,N)

C**   Diese Funktion ist aequivalent zur entsprechenden C-Funktion.
C**   Sie ermittelt die Anzahl der Argumente in einem String.
C**   Das Parsen des Strings uebernimmt die Routine sargp.
C**   Dort sind auch die syntaktischen Regeln beschrieben.

      CHARACTER*(*) TEXT
      INTEGER AS,AE,N,I

      I=0 				! Do not look for any Argument
      CALL SARGPL(TEXT,N,I,AS,AE)

      RETURN

      END
sargp.f/        1553528659  5006  320   100644  3656      `
      SUBROUTINE SARGP(TEXT,N,I,AS,AE)

C**	Die Subroutine sargp zerlegt einen String.
C**	Ermittelt werden:
C**	n : die Anzahl der Argumente und, 
C**     	falls i in [1..n],
C**	as und ae : Start- und Endindex des i-ten Arguments.
C**	Geparsed wird nach folgenden Regel:
C**	Leerzeichen werden grunsaetzlich nicht beachtet
C**	(Ausnahmen siehe unten).
C**	Argumente werden durch Leerzeichen oder Komma oder '=' oder ':'
C**     getrennt.
C**	Wird ein Argument durch Leerzeichen und Komma getrennt,
C**     so gilt dies als eine Trennung.
C**	Folgen zwei Kommata ohne Argument, also hoechstens durch
C**	Leerzeichen getrennt, gilt dies als Leerargument.
C**	Zeichen zwischen zwei doppelten Anfuehrungszeichen gelten
C**	als ein Argument, auch wenn Leerzeichen oder Kommata
C**	enthalten sind. In diesem Fall werden die Anfuehrungszeichen
C**	als nicht zum Argument gehoerig betrachtet.
C**	Interpretaion der Rueckgabewerte:
C**	n: immer die Anzahl der Argumente
C**	as=-1 -> Es wurde kein i-tes Argument gefunden (i nicht in [1..n])
C**	as=0  -> Das i-te Argument war leer (z.B. ",,")
C**	sonst : text(as:ae) = i-tes Argument

        CHARACTER*(*) TEXT
        CHARACTER*1 THISCHAR, TAB
        INTEGER N                  ! Out: Anzahl der Argumente
        INTEGER I                  ! In : gesuchtes Argument
        INTEGER AS,AE              ! Out: erste u. letzte Position des 
                                   !         Arguments im String

	INTEGER TL,TI
        INTEGER STATE

        LOGICAL ISDEL
        CHARACTER C

C***    Liste der Trennzeichen
        ISDEL(C)= C.EQ.',' .OR. C.EQ.'=' .OR. C.EQ.':' 
ccc        ISDEL(C)=C.EQ.',' .OR. C.EQ.'=' .OR. C.EQ.':' .OR. C.EQ.CHAR(9)

C***   Der TAB wird jetzt wie ein Blank behandelt. wrh 04.09.2012
        TAB = CHAR(9)
	TL=LEN(TEXT)

	state=0
C	state=0 -> kein Argument aktiv
C	state=1 -> Argumentende gefunden, naechstes Komma
C			ist   k e i n   Leerargument
C	state=2 -> normales Argument aktiv
C	state=3 -> Argument in '"' aktiv


        N=0
        AS=-1
	AE=TL

	DO 100 TI=1,TL
        THISCHAR = TEXT(TI:TI) 
C** Go here looking for next start of an argument
        IF (STATE .EQ. 0) THEN
	   IF (THISCHAR .EQ. ' ') GOTO 100
	   IF (THISCHAR .EQ. TAB) GOTO 100
           IF (ISDEL(THISCHAR)) THEN
                            N=N+1
                            IF (N .EQ. I) THEN
                                AS=0
                            ENDIF
                            GOTO 100
           ENDIF
           IF (THISCHAR .EQ. '"') THEN
                           N=N+1
			   IF (N .EQ. I) AS=TI+1
			   STATE=3
			   GOTO 100
           ENDIF
	   STATE=2
	   N=N+1
           IF (N .EQ. I) AS=TI
	   GOTO 100
        ELSEIF (STATE .EQ. 1) THEN
	   IF (THISCHAR .EQ. ' ') GOTO 100
	   IF (THISCHAR .EQ. TAB) GOTO 100
           IF (ISDEL(THISCHAR)) THEN
			   STATE=0
			   GOTO 100
           ENDIF
           IF (THISCHAR .EQ. '"') THEN
                           N=N+1
                           IF (N .EQ. I) AS=TI+1
			   STATE=3
			   GOTO 100
           ENDIF
	   STATE=2
	   N=N+1
           IF (N .EQ. I) AS=TI
	   GOTO 100
        ELSEIF (STATE .EQ. 2) THEN
           IF (THISCHAR .EQ. ' ' .OR. THISCHAR .EQ. TAB) THEN
                          STATE=1
			  IF (N .EQ. I) AE=TI-1
			  GOTO 100
	   ENDIF
	   IF (ISDEL(THISCHAR)) THEN
			  STATE=0
                          IF (N .EQ. I) AE=TI-1
			  GOTO 100
           ENDIF
           GOTO 100
        ELSE 
C***  ! IF (STATE .EQ. 3)
           IF (THISCHAR .EQ. '"') THEN
                          STATE=1
			  IF (N .EQ. I) AE=TI-1
			  GOTO 100
           ENDIF
        ENDIF

100	CONTINUE

	RETURN
        END
sargpl.f/       1553528659  5006  320   100644  2747      `
      SUBROUTINE SARGPL(TEXT,N,I,AS,AE)

C**	Die Subroutine sargp zerlegt einen String.
C**	Ermittelt werden:
C**	n : die Anzahl der Argumente und, 
C**     	falls i in [1..n],
C**	as und ae : Start- und Endindex des i-ten Arguments.
C**	Geparsed wird nach folgenden Regel:
C**	Leerzeichen werden grunsaetzlich nicht beachtet
C**	(Ausnahmen siehe unten).
C**	Argumente werden durch Leerzeichen oder Komma oder '=' oder ':'
C**     oder '/' getrennt.
C**	Wird ein Argument durch Leerzeichen und Komma getrennt,
C**     so gilt dies als eine Trennung.
C**	Folgen zwei Kommata ohne Argument, also hoechstens durch
C**	Leerzeichen getrennt, gilt dies als Leerargument.
C**     Doppelte Anfuerungszeichen werden ignoriert
C**	als nicht zum Argument gehoerig betrachtet.
C**	Interpretaion der Rueckgabewerte:
C**	n: immer die Anzahl der Argumente
C**	as=-1 -> Es wurde kein i-tes Argument gefunden (i nicht in [1..n])
C**	as=0  -> Das i-te Argument war leer (z.B. ",,")
C**	sonst : text(as:ae) = i-tes Argument

        CHARACTER*(*) TEXT
        INTEGER N                  ! Out: Anzahl der Argumente
        INTEGER I                  ! In : gesuchtes Argument
        INTEGER AS,AE              ! Out: erste u. letzte Position des 
                                   !         Arguments im String

	INTEGER TL,TI
        INTEGER STATE

        LOGICAL ISDEL
        CHARACTER C
        ISDEL(C)=( C.EQ.',' .OR. C.EQ.'=' .OR. C.EQ.':' 
     >             .OR. C.EQ.'/' )

	TL=LEN(TEXT)

	state=0
C	state=0 -> kein Argument aktiv
C	state=1 -> Argumentende gefunden, naechstes Komma
C			ist   k e i n   Leerargument
C	state=2 -> normales Argument aktiv
C	state=3 -> Argument in '"' aktiv


        N=0
        AS=-1
	AE=TL

	DO 100 TI=1,TL

C** Go here looking for next start of an argument
        IF (STATE .EQ. 0) THEN
	   IF (TEXT(TI:TI) .EQ. ' ') GOTO 100
           IF (ISDEL(TEXT(TI:TI))) THEN
                            N=N+1
                            IF (N .EQ. I) THEN
                                AS=0
                            ENDIF
                            GOTO 100
           ENDIF
	   STATE=2
	   N=N+1
           IF (N .EQ. I) AS=TI
	   GOTO 100
        ELSEIF (STATE .EQ. 1) THEN
	   IF (TEXT(TI:TI) .EQ. ' ') GOTO 100
           IF (ISDEL(TEXT(TI:TI))) THEN
			   STATE=0
			   GOTO 100
           ENDIF
	   STATE=2
	   N=N+1
           IF (N .EQ. I) AS=TI
	   GOTO 100
        ELSEIF (STATE .EQ. 2) THEN
           IF (TEXT(TI:TI) .EQ. ' ') THEN
                          STATE=1
			  IF (N .EQ. I) AE=TI
			  GOTO 100
	   ENDIF
	   IF (ISDEL(TEXT(TI:TI))) THEN
			  STATE=0
                          IF (N .EQ. I) AE=TI-1
			  GOTO 100
           ENDIF
           GOTO 100
        ENDIF

100	CONTINUE

	RETURN
        END

sargrest.f/     1553528659  5006  320   100644  1941      `
      SUBROUTINE SARGREST (TEXT, N, I, IFIRST, LAST)
C**********************************************************************
C***  Ermittelt den Beginn des i-ten Arguments und das nichtleere Ende 
C***  gesamten restlichen Strings. 
C***  Balancierte "..." am Anfang und Ende werden entfernt, sonst 
C***  bleiben " erhalten. Faengt des Argument mit einem Trennzeichen
C***  an (=,:/), so muss (!!!, sonst Fehlerabbruch!) der Reststring in 
C***  "..." eingeschlossen werden, ebenso natuerlich wenn der 
C***  Reststring mit einem Blank beginnen soll. An spaeterer Position sind
C***  Trennzeichen ohne Wirkung. 
C**********************************************************************

      CHARACTER TEXT*(*)

      CALL SARGP (TEXT, N, I, IFIRST, ILAST)
      LAST = IDX(TEXT)

C***  Leerer Reststring
      IF (IFIRST .EQ. -1) THEN
         IFIRST = 1
         LAST   = 0

C***  Der Reststring  beginnt mit einem Trennzeichen ohne " davor
      ELSE IF (IFIRST .EQ. 0) THEN
         WRITE (6, '(A)') 'Error when parsing the following string:'
         WRITE (6, '(A)') TEXT
         WRITE (6, '(A, I3, A)') 'Argument ', I, 
     >                        ' begins with delimiter -> use "..."'
         STOP '>>> ERROR IN SUBROUTINE SARGREST <<<'
      ENDIF

      IF (IFIRST .GT. 1) THEN
C***  Reststring begins with "
         IF (TEXT(IFIRST-1:IFIRST-1) .EQ. '"') THEN 
C***     Remove balanced closing quote if present, else restore leading quote 
            IF (TEXT(LAST:LAST) .EQ. '"' .AND. LAST .GT. IFIRST) THEN
               LAST = LAST - 1
               ELSE
               IFIRST = IFIRST - 1
            ENDIF
         ENDIF
      ENDIF

c      print *, '-------------------------'
c      print *, 'Test: text', text
c      print *, 'Test: ifirst', ifirst 
c      print *, 'Test: text(f,l)', text(ifirst:ifirst)
c      print *, 'Test: last', last
c      print *, 'Test: text(l,l)', text(last:last)

      RETURN
      END

sargv.f/        1553528659  5006  320   100644  771       `
      SUBROUTINE SARGV(TEXT,I,ARGTEXT)

C**   Diese Funktion ist fast aequivalent zur entsprechenden C-Funktion.
C**   Sie ermittelt das i-te Argument in einem String.
C**   Die Regeln zur Argumenttrennung sind in sargp beschrieben.
C**   Ist das i-te Argument nicht vorhanden, wird argtext nicht veraendert.
c********* versuchshalber: 
c*********   Ist das i-te Argument nicht vorhanden, wird ein leerer String 
c*********   (Blanks) zurueckgegeben

      CHARACTER*(*) TEXT,ARGTEXT
      INTEGER I
      INTEGER N,AS,AE

      CALL SARGP(TEXT,N,I,AS,AE)

ccccc      IF (AS .EQ. -1) GOTO 10
ccccc      IF (AS .EQ. 0) THEN
      IF (AS .EQ. 0 .OR. AS .EQ. -1) THEN
             ARGTEXT=' '
      ELSE
             ARGTEXT=TEXT(AS:AE)
      ENDIF

10    RETURN

      END

sargvl.f/       1553528659  5006  320   100644  580       `
      SUBROUTINE SARGVL(TEXT,I,ARGTEXT)

C**   Diese Funktion ist fast aequivalent zur entsprechenden C-Funktion.
C**   Sie ermittelt das i-te Argument in einem String.
C**   Die Regeln zur Argumenttrennung sind in sargp beschrieben.
C**   Ist das i-te Argument nicht vorhanden, wird argtext nicht veraendert.

      CHARACTER*(*) TEXT,ARGTEXT
      INTEGER I
      INTEGER N,AS,AE

      CALL SARGPL(TEXT,N,I,AS,AE)

      IF (AS .EQ. -1) GOTO 10
      IF (AS .EQ. 0) THEN
             ARGTEXT=' '
      ELSE
             ARGTEXT=TEXT(AS:AE)
      ENDIF

10    RETURN

      END
ttw.f/          1553528659  5006  320   100644  9394      `
      SUBROUTINE TTW

      LOGICAL CFMARKE, IGNORE
      CHARACTER FNAME*255, FNAME2*255, LINE*256, ACTPAR*80
      CHARACTER LINE2*132, ACTPAR2*80
      CHARACTER FTYPE*6, PFORMAT*3, BLUN*80, BSEITE*80, CH*1
      CHARACTER BFILE*80

      CFMARKE = .TRUE.
      IGNORE = .FALSE.

      WRITE (*,'(A)') ' NAME OF INPUT DATA FILE (END= CTRL D)'
      WRITE (*,'(A)') ' Present directory is:'
      CALL SYSTEM ('pwd')
      READ (*, '(A)', END=100) FNAME
      FNAME = FNAME(:IDX(FNAME))
      IF (FNAME .EQ. '.' .OR. FNAME .EQ. './' .OR.
     >    FNAME .EQ. '..' .OR. FNAME .EQ. '../' ) GOTO 97
      OPEN (UNIT=1, FILE=FNAME, STATUS='OLD', ERR=97)
 
      FNAME2 = FNAME( :IDX(FNAME)) // '.ttw'
      OPEN (UNIT=2, FILE=FNAME2, STATUS='UNKNOWN')
cc      RECL parameter removed because of PC gnu-f77 compiler, wrh 13.03.2002 
cc      correspondingly, contionuation lines must start after 80 cars 
cc          ( see changes below!!)
cc      OPEN (UNIT=2, FILE=FNAME2, STATUS='UNKNOWN')

      WRITE (*,'(A)') 
     >      ' FILE-TYPE: f77, cf77, df77, ascii, as132, wr, wr132, fax'
      READ (*,'(A)') FTYPE
      write (*,'(2A)') 'ftype=',ftype
      IF (FTYPE(: IDX(FTYPE)) .EQ. 'f77') THEN
        FTYPE = 'F77'
      ELSE IF (FTYPE(: IDX(FTYPE)) .EQ. 'cf77') THEN
        FTYPE = 'CF77'
      ELSE IF (FTYPE(: IDX(FTYPE)) .EQ. 'df77') THEN
        FTYPE = 'DF77'
      ELSE IF (FTYPE(: IDX(FTYPE)) .EQ. 'ascii') THEN
        FTYPE = 'ASCII'
      ELSE IF (FTYPE(: IDX(FTYPE)) .EQ. 'as132') THEN
        FTYPE = 'AS132'
      ELSE IF (FTYPE(: IDX(FTYPE)) .EQ. 'wr') THEN
        FTYPE = 'WR'
      ELSE IF (FTYPE(: IDX(FTYPE)) .EQ. 'wr132') THEN
        FTYPE = 'WR132'
      ELSE IF (FTYPE(: IDX(FTYPE)) .EQ. 'fax') THEN
        FTYPE = 'FAX'
      ELSE
        WRITE (*,'(2A)') ' UNKNOWN TYPE : ',FTYPE
        STOP 'ERROR in TTW'
      ENDIF

      WRITE (*,'(2A)') 'Name of the Output-File:',FNAME2

C***  setzen von Papierformat, Zeilenzahl, Schriftgroesse, usw
      IF (FTYPE(: IDX(FTYPE)) .EQ. 'F77') THEN
        MAXLINE = 82
        PFORMAT = 'A4H'
        SIZE    = 0.2
        BLUN    = 'KASDEF LUN 3.5 28.    0.0 0.0 '
        BSEITE  = 'KASDEF LUN 18. 28.5   0.0 0.0 '
        BFILE   = 'KASDEF LUN 18. 28.5 R-0.5 0.0 '
      ELSE IF (FTYPE(: IDX(FTYPE)) .EQ. 'CF77') THEN
        MAXLINE = 57
        PFORMAT = 'A4Q'
        SIZE    = 0.2
        BLUN    = 'KASDEF LUN 3.5 19.5  0.0 0.0 '
        BSEITE  = 'KASDEF LUN 27. 20.   0.0 0.0 '
        BFILE   = 'KASDEF LUN 27. 20. R-0.5 0.0 '
      ELSE IF (FTYPE(: IDX(FTYPE)) .EQ. 'DF77') THEN
        MAXLINE = 62
        PFORMAT = 'A4Q'
c        PFORMAT = 'A4H'
        SIZE    = 0.2
        BLUN    = 'KASDEF LUN 3.5 20.0  0.0 0.0 '
        BSEITE  = 'KASDEF LUN 27. 20.   0.0 0.0 '
        BFILE   = 'KASDEF LUN 27. 20. R-0.5 0.0 '
      ELSE IF (FTYPE(: IDX(FTYPE)) .EQ. 'ASCII' .OR. 
     >         FTYPE(: IDX(FTYPE)) .EQ. 'WR' ) THEN
        MAXLINE = 82
        PFORMAT = 'A4H'
        SIZE    = 0.2
        BLUN    = 'KASDEF LUN 3.5 28.    0.0 0.0 '
        BSEITE  = 'KASDEF LUN 18. 28.5   0.0 0.0 '
        BFILE   = 'KASDEF LUN 18. 28.5 R-0.5 0.0 '
      ELSE IF (FTYPE(: IDX(FTYPE)) .EQ. 'AS132' .OR. 
     >         FTYPE(: IDX(FTYPE)) .EQ. 'WR132') THEN
        MAXLINE = 57
        PFORMAT = 'A4Q'
        SIZE    = 0.2
cc        BLUN    = 'KASDEF LUN 3.5 19.5  0.0 0.0 '
        BLUN    = 'KASDEF LUN 2.0 19.5  0.0 0.0 '
        BSEITE  = 'KASDEF LUN 27. 20.   0.0 0.0 '
        BFILE   = 'KASDEF LUN 27. 20. R-0.5 0.0 '
      ELSE IF (FTYPE(: IDX(FTYPE)) .EQ. 'FAX') THEN
        MAXLINE = 55
        PFORMAT = 'A4H'
        SIZE    = 0.3
        BLUN    = 'KASDEF LUN 3.5 28.   -2.0 0.0 '
        BSEITE  = 'KASDEF LUN 17. 28.5   0.0 0.0 '
        BFILE   = 'KASDEF LUN 17. 28.5 R-0.5 0.0 '
      ENDIF

      ISEITE = 0
      XMIN = 0.
      XMAX = 1.
      YMIN = 0.
      YMAX = 1.
c      SIZE = 0.25
      XLINESKIP = 1.6

    5 CONTINUE
      ISEITE = ISEITE + 1
      ILINE = 0
      
      WRITE (2,'(A)') 'PAPERFORMAT '// PFORMAT
      WRITE (2,'(A,I3)') 'PLOT   :SEITE ', ISEITE
      WRITE (2,'(A)') 'KASDEF OFS  0.0 0.0'
      WRITE (2,'(A)') 'KASDEF NOCOPYRIGHT'
      WRITE (2,'(A)') 'KASDEF FONT=COURIER'
      WRITE (2,'(A)') 'KASDEF PEN=3'
      WRITE (2,'(A,F4.2,A)') ' KASDEF LINESKIP ',XLINESKIP,'S'
      WRITE (2,'(A)') 'KASDEF NOBOX'
      IF (FTYPE .EQ. 'F77') THEN
        WRITE (2,'(A)') 'KASDEF PEN=15'
        WRITE (2,'(A)') 'KASDEF DEFINECOLOR=2 0.8 0.8 0.8'
        WRITE (2,'(A)') 'KASDEF COLOR=2'
        WRITE (2,'(A)') 'KASDEF LIN 4.55  1.3 4.55  28.2'
        WRITE (2,'(A)') 'KASDEF LIN 17.07 1.3 17.07 28.2'
        WRITE (2,'(A)') 'KASDEF COLOR=1'
        WRITE (2,'(A)') 'KASDEF PEN=3'
      ELSE IF (FTYPE .EQ. 'CF77') THEN
        WRITE (2,'(A)') 'KASDEF PEN=15'
        WRITE (2,'(A)') 'KASDEF DEFINECOLOR=2 0.8 0.8 0.8'
        WRITE (2,'(A)') 'KASDEF COLOR=2'
        IF (CFMARKE) THEN
          WRITE (2,'(A)') 'KASDEF LIN 11.93 2.1 11.93 18.8'
          WRITE (2,'(A)') 'KASDEF LIN 25.03 2.1 25.03 18.8'
        ENDIF
        WRITE (2,'(A)') 'KASDEF COLOR=1'
        WRITE (2,'(A)') 'KASDEF PEN=3'
      ELSE IF (FTYPE .EQ. 'DF77') THEN
        WRITE (2,'(A)') 'KASDEF PEN=15'
        WRITE (2,'(A)') 'KASDEF DEFINECOLOR=2 0.8 0.8 0.8'
        WRITE (2,'(A)') 'KASDEF COLOR=2'
        IF (CFMARKE) THEN
          WRITE (2,'(A)') 'KASDEF LIN 6.07  2.1 6.07  18.8'
          WRITE (2,'(A)') 'KASDEF LIN 18.58 2.1 18.58 18.8'
        ENDIF
        WRITE (2,'(A)') 'KASDEF COLOR=1'
        WRITE (2,'(A)') 'KASDEF PEN=3'
      ENDIF
      WRITE (2,'(A)') 'HEADER :'
      WRITE (2,'(A)') 'X-ACHSE:'
      WRITE (2,'(A)') 'Y-ACHSE:'
      WRITE (2,'(A)') '     MASSTAB    MINIMUM    MAXIMUM  TEILUNGEN '
     >           // 'BESCHRIFT. DARUNTER'
      WRITE (2,'(A,F4.1,A,2(F4.1,A),A)') 
     >      'X: ', XMAX, 'CM ', XMIN, ' ', XMAX, ' 1. 1. 0.'
      WRITE (2,'(A,F4.1,A,2(F4.1,A),A)') 
     >      'Y: ', YMAX, 'CM ', YMIN, ' ', YMAX, ' 1. 1. 0.'

   10 CONTINUE
        ILINE = ILINE + 1
        READ (1, '(A)', END=100) LINE

C***  Replace Umlaute etc. (nur im 'wr'-Style) 	
      IF (FTYPE(: IDX(FTYPE)) .EQ. 'WR') THEN 
      LAST = IDX(LINE)
      I = 1
   7  CONTINUE
        IC = ICHAR(LINE(I:I))
	IF (IC .EQ. 228) LINE(I:) = '&a' // LINE(I+1:) 
	IF (IC .EQ. 246) LINE(I:) = '&o' // LINE(I+1:) 
	IF (IC .EQ. 252) LINE(I:) = '&u' // LINE(I+1:) 
	IF (IC .EQ. 196) LINE(I:) = '&A' // LINE(I+1:) 
	IF (IC .EQ. 214) LINE(I:) = '&O' // LINE(I+1:) 
	IF (IC .EQ. 220) LINE(I:) = '&U' // LINE(I+1:) 
	IF (IC .EQ. 223) LINE(I:) = '&s' // LINE(I+1:) 
	IF (IC .EQ.  38) LINE(I:) = '&&' // LINE(I+1:) 
        IF (IC .EQ. 228 .OR. IC .EQ. 246 .OR. IC .EQ. 252 
     > .OR. IC .EQ. 196 .OR. IC .EQ. 214 .OR. IC .EQ. 220 
     > .OR. IC .EQ. 223 .OR. IC .EQ.  38) THEN 
          LAST = LAST + 1
	  I = I + 1
        ENDIF 
        I = I + 1
        IF (I .LE. LAST) GOTO 7
      ENDIF
	
        IF (ILINE .EQ. 1) THEN
          IF (LINE(5:11) .EQ. 'PAGE 1 ') THEN
            IGNORE = .TRUE.
            GOTO 100
          ENDIF
        ENDIF
        IF (LINE( :40) .EQ. '               V E C T O R I Z A T I O N')
     >      CFMARKE = .FALSE.
C***  Maskieren von \ und &
        IF (FTYPE(: IDX(FTYPE)) .NE. 'WR' .AND. 
     >      FTYPE(: IDX(FTYPE)) .NE. 'WR123' .AND. 
     >      FTYPE(: IDX(FTYPE)) .NE. 'FAX') THEN
          ID = IDX (LINE)
          I = 0
   40     I = I + 1
            CH = LINE(I:I)
            IF (CH .EQ. CHAR(92) .OR. CH .EQ. '&' .OR. CH .EQ. '#') THEN
              IF (CH .NE. '#') THEN
                LINE = LINE( :I) // LINE(I: )
              ELSE
                LINE = LINE( :I-1) // '&' // LINE(I: )
              ENDIF
              I = I + 1
            ENDIF
          IF (I .LT. ID) GOTO 40
        ENDIF
        
        IF (IDX(LINE) .EQ. 0) LINE = '&F'
        IF (LINE(1:1) .EQ. CHAR(12)) THEN
          IF (ILINE .NE. 1) THEN
            BACKSPACE 1
            GOTO 25
          ENDIF
          LINE = LINE(2: )
        ENDIF

        IF (ILINE .EQ. 1) THEN
          WRITE (ACTPAR,'(F4.2)') SIZE

          WRITE (ACTPAR2,'(I4)') ISEITE
          LINE2 = BSEITE( :IDX(BSEITE)) // ' ' // ACTPAR( :4) // 
     >           ' &FSEITE ' // ACTPAR2
          WRITE (2,'(A)') LINE2( :IDX(LINE2))
          WRITE (2,'(A)') BFILE( :IDX(BFILE)) // ' ' // ACTPAR( :4) // 
     >                ' &FFile: ' // FNAME( :IDX(FNAME))

          LINE = BLUN( :IDX(BLUN)) // ' ' // ACTPAR( :4) // 
     >           ' &F' // LINE
        ELSE
          LINE = 'KASDEF NEXTLUN &F' // LINE
        ENDIF
        ID = IDX(LINE)
cc        IF (ID .LE. 80) THEN
        IF (ID .LE. 130) THEN
c          write (0,*) line( :idx(line))
          WRITE (2,'(A)') LINE( :IDX(LINE))
        ELSE
cc          ID2 = IDX(LINE( :130))
          ID2 = IDX(LINE( :80))
          WRITE (2,'(A)') LINE ( :ID2)
          LINE = LINE (ID2+1: )
          WRITE (2,'(A)') 'KASDEF >' // LINE( :IDX(LINE))
        ENDIF

      IF (ILINE .LT. MAXLINE) GOTO 10

   25 CONTINUE
      WRITE (2,'(A)') 'END'
      GOTO 5


   97 WRITE (6,96) FNAME(:IDX(FNAME))
   96 FORMAT (/, 1X, 70('*'), /, ' ERROR: CANNOT OPEN FILE: ', A, /,
     >        ' POSSIBLE REASONS: FILE NOT FOUND OR',
     >        ' READ PERMISSION DENIED',
     >        /, 1X, 70('*'), /)

  100 CONTINUE
      IF (.NOT. IGNORE) WRITE (2,'(A)') 'END'
      CLOSE (1)
      CLOSE (2)
 
      END
