fconv.f/        1553528659  5006  320   100644  1426      `
      SUBROUTINE FCONV

      DIMENSION Z(2880)
      INTEGER*2 I(5760)
      DIMENSION IBIT(16),NEWBIT(16)

      OPEN (UNIT=1, FILE='tmpuni1.at1', FORM='UNFORMATTED', RECL=2880, 
     >      STATUS='OLD')

      OPEN (UNIT=3, FILE='mod.at1', FORM='UNFORMATTED', RECL=2880, 
     >      STATUS='NEW')

c      OPEN(2,FILE='TEMP.DAT',STATUS='NEW')

      IMAX = 0
      
      DO K=1,100
c        write (*,*) 'k=',k
        READ(1,REC=k,err=99) i

        DO J=1,5760
          IF (K .GT. 1 .OR. J .GT. 3200) THEN
            ITOP = 2**15
            DO L=1,16
              IBIT(L) = 0
              IF (I(J) .GE. ITOP) THEN
                IBIT(L) = 1
                I(J) = I(J) - ITOP
              ENDIF
              ITOP = ITOP / 2
            ENDDO

            I(J) = 127
C            DO L=1,8
C              NEWBIT(L) = IBIT(L+8)
C              NEWBIT(L+8) = IBIT(L)
C            ENDDO

            NEW = 0
C            DO L=1,16
c              if (l .ne. 1) then
C                NEW = NEW + 2**(16-L) * NEWBIT(L)
c              endif
C            ENDDO
c            if (newbit(1) .eq. 1) new = -new
C
c          new=-20000 + 40000*ibit(16)

          ENDIF
        ENDDO
        WRITE (3, REC=K) I

c        WRITE (2,'(I6,2X,I6)') J,new
            



      ENDDO

      

      CLOSE (1)
c      CLOSE (2)
      CLOSE (3)

      return

   99 write (*,*) 'error erreicht'
      write (*,*) 'max0=',imax

      END
