c              endif
C            ENDDO
c            if (newbit(1) .eq. 1) new = -new
C
c          new=-20000 + 40000*ibit(16)

          ENDIF
        ENDDO
        WRITE (3, REC=K) I

c        WRITE (2,'(I6,2X,I6)') J,new
            



      ENDDO

      

      CLOSE (1)
