      write (*,*) 'max0=',imax

      END

iuerdaf.f/      1553528659  5006  320   100644  3618      `
	subroutine iuerdaf

C***    IUE Datenkonvertierung fuer UNIX-Files ohne CR
C***    Bytes werden nicht geswapt

	integer*2 buf0(1024),buf(1024,7)
        character fname*20
        logical expt

        expt = .false.

        write(*,*) ' Input file :'
        read(5,'(a)') fname

        lenrec = 2044
        open (10,file=fname,status='OLD',access='direct',recl=2044,
     >           form='UNFORMATTED')

        open (9,file='IUE_CONV.DAT',form='FORMATTED', status='UNKNOWN')

        iacc=1
	read (10,rec=iacc,err=99) (buf0(i),i=0,lenrec/2-1)
        iacc=iacc+1

        call swapint(lenrec/2,buf0)

	write(9,*) '* # of orders: ',buf0(2)
	write(9,*) '* # of Camera: ',buf0(3)
	write(9,*) '* # of Image : ',buf0(4)
	write(9,*) '* # rec per order : ',buf0(5)
	write(9,*) '* Aperture   : ',buf0(14)
	write(9,*) '* J for gross: ',buf0(20)
	write(9,*) '* K for gross: ',buf0(21)
	write(9,*) '* J for back : ',buf0(24)
	write(9,*) '* K for back : ',buf0(25)
	write(9,*) '* J for net  : ',buf0(28)
	write(9,*) '* K for net  : ',buf0(29)
	write(9,*) '* J for abs. : ',buf0(32)
	write(9,*) '* K for abs. : ',buf0(33)
	write(9,*) '* lambda0 1.order : ',buf0(100)

        if ((buf0(56) .ne. 5) .and. (buf0(56) .ne. 500)) then
           write(*,*) 'What resolution ?'
           write(*,*) '  1 = low    2 = high'
    3      read(*,*) ireso
           if ((ireso .ne. 1) .and. (ireso .ne. 2)) goto3
           if (ireso .eq. 1) buf0(56)=5
           if (ireso .eq. 2) buf0(56)=500
        endif

        write(*,*) ' Art of spectrum :'
        if (buf0(56) .eq. 5) then
           write(*,*) '       1=GROSS  2=BACKGR  3=NET  4=ABS FLUX'
           else
           write(*,*) '       1=GROSS  2=BACKGR  3=NET  4=RIP NET'
        endif
    5   read(*,*) art
        if ((art .lt. 1).or.(art .gt. 4)) goto5
        iart=int(art)

        exptime = float(60*buf0(39) + buf0(40)) + float(buf0(41))/1000.

        if (exptime .gt. 0.) goto20

        if ((buf0(56) .eq. 5).and.(iart .eq. 4)) then
           write(*,*) ' Exposure time in seconds: '
   15      read(*,*) exptin
           if (exptin .le. 0) goto 15
           exptime = exptin
           expt = .true.
        endif

   20   continue

C**  read all orders

	do 40 norder=1,buf0(2)
	write(*,*)'++++++++++++++++++++++++++++'
	write(*,*)'order #: ',norder
	write(*,*)'Data for this order:'
	write(*,*)'Lambda-0: ',buf0(99+norder)
	write(*,*)'++++++++++++++++++++++++++++'
	write(9,*)'* ++++++++++++++++++++++++++++',norder

C**  read a group of 6 records per order

         if ((buf0(5) .ne. 6).and.(buf0(5) .ne. 7)) then
            write(*,*) 'SORRY, UNKNOWN NUMBER OF RECORDS PER ORDER.'
            write(*,*) 'INPUT (TRY 6 OR 7):'
            read(5,*) buf0(5)
         endif

	do 35 nr=1,buf0(5)
	read (10,rec=iacc,err=99) (buf(i,nr),i=1,lenrec/2)
        iacc=iacc+1

        call swapint(lenrec/2,buf(1,nr))

   35   continue

C** end loop for records of one order
         jhelp=iart+2
         fll1= float(buf0(56))
         fll2= float(buf0(99+norder))
         khelp=16+4*iart  
         if (buf0(khelp) .eq. 0) then
            write(*,*) 'SORRY, ERROR ON IMAGE (SCALE FACTOR J).'
            goto99
         endif
         fli1=float(buf0(khelp))
         fli2=float(buf0(khelp+1))

	 do 45 i=1,lenrec/2
	 xl=buf(i,1)
	 xl=xl/fll1 + fll2
	 xi=buf(i,jhelp)
	 xi=xi*fli1*(2**(-fli2))
         if (expt) xi = xi/exptime
	 write (9,*) xl,xi
  45	continue

  40	continue

        write(*,*)' '
        write(*,*)'Converted spectrum saved in IUE_CONV.DAT .'

C** end loop over all orders

  99    continue
        close(9)
        close(10)
  100	end

autos.f/        1553528659  5006  320   100644  4139      `
      SUBROUTINE AUTOS(B, C, X, Y, NDAT, NDATMAX, NSET, NSETMAX,
     >                 AUTOSCALE)
C**********************************************************************
C***  SUBROUTINE TO DETERMINE THE SCALING OF THE X- AND THE Y-AXIS 
C***    AUTOMATICALLY. AT THE MOMENT FOUR KEYWORDS ARE RECOGNIZED
C***    AUTO    : SCALE BOTH AXES AND THE TICKS
C***    AUTO_T  : SCALE THE TICKS OF BOTH AXES
C***    AUTO_XT : SCALE THE TICKS OF THE X AXIS
C***    AUTO_YT : SCALE THE TICKS OF THE Y AXIS
C***  CALLED BY MAIN PROGRAM WRPLOT
C**********************************************************************

      DIMENSION X(NDATMAX,NSETMAX), Y(NDATMAX,NSETMAX)
      DIMENSION NDAT(NSETMAX)
      DIMENSION B(6), C(6)
      CHARACTER AUTOSCALE*(*)

      DOUBLE PRECISION FNORM

      SAVE XMIN, XMAX, YMIN, YMAX

      IF (AUTOSCALE .EQ. 'AUTO' .OR. AUTOSCALE .EQ. 'AUTOX') THEN
C***  X AXIS ***********************************************
C***  FIND XMIN, XMAX
      IF (NSET .EQ. 0) THEN
         XMIN = -0.5
         XMAX =  0.5
      ELSE 
         XMIN = X(1,1)
         XMAX = XMIN
         DO ISET=1, NSET
            DO I=1, NDAT(ISET)
               XT = X(I, ISET)
               XMIN = AMIN1 (XMIN,XT)
               XMAX = AMAX1 (XMAX,XT)
            END DO
         END DO
      ENDIF

      IF (XMIN .EQ. XMAX) THEN
        XMIN = XMIN - 0.5
        XMAX = XMAX + 0.5
      ENDIF

      D = XMAX - XMIN
      ALOGD = ALOG10(D)
      MAG = INT (ALOGD)
      IF (ALOGD .LT. .0) MAG = MAG - 1
      FNORM = 10.**MAG
      DNORM = D / FNORM
      IF (DNORM .LE. 2.) THEN 
         TICK = 0.1
	 ABST = 0.5
      ELSE IF (DNORM .LE. 5.) THEN
         TICK = 0.2
	 ABST = 1.
      ELSE
         TICK = 0.5
	 ABST = 2.
      ENDIF
      TICK = TICK * FNORM
      ABST = ABST * FNORM
      
      NTICK = INT (XMIN / TICK)
c      IF (XMIN .LT. .0) 
       NTICK = NTICK - 1  
      XMIN = NTICK * TICK     
      NTICK = INT (XMAX / TICK)
c      IF (XMAX .GT. .0) 
       NTICK = NTICK + 1  
      XMAX = NTICK * TICK     

      B(1) = 20. / (XMAX - XMIN)
      B(2) = XMIN
      B(3) = XMAX
      B(4) = TICK
      B(5) = ABST
      B(6) = .0
      ENDIF

      IF (AUTOSCALE .EQ. 'AUTO' .OR. AUTOSCALE .EQ. 'AUTOY') THEN
C***  Y-AXIS  **************************************************** 
C***  FIND YMIN, YMAX
      IF (NSET .EQ. 0) THEN
         YMIN = -0.5
         YMAX =  0.5
      ELSE 
         YMIN = Y(1,1)
         YMAX = YMIN
         DO ISET=1, NSET
            DO I=1, NDAT(ISET)
               YT = Y(I, ISET)
               YMIN = AMIN1 (YMIN,YT)
               YMAX = AMAX1 (YMAX,YT)
            END DO
         END DO
      ENDIF

      IF (YMIN .EQ. YMAX) THEN
        YMIN = YMIN - 0.5
        YMAX = YMAX + 0.5
      ENDIF

      D = YMAX - YMIN
      ALOGD = ALOG10(D)
      MAG = INT (ALOGD)
      IF (ALOGD .LT. .0) MAG = MAG - 1
      FNORM = 10.**MAG
      DNORM = D / FNORM
      IF (DNORM .LE. 2.) THEN 
         TICK = 0.1
	 ABST = 0.5
      ELSE IF (DNORM .LE. 5.) THEN
         TICK = 0.2
	 ABST = 1.
      ELSE
         TICK = 0.5
	 ABST = 2.
      ENDIF
      TICK = TICK * FNORM
      ABST = ABST * FNORM
      
      NTICK = INT (YMIN / TICK)
c      IF (YMIN .LT. .0) 
       NTICK = NTICK - 1  
      YMIN = NTICK * TICK     
      NTICK = INT (YMAX / TICK)
c      IF (YMAX .GT. .0) 
       NTICK = NTICK + 1  
      YMAX = NTICK * TICK     

      C(1) = 15. / (YMAX - YMIN)
      C(2) = YMIN
      C(3) = YMAX
      C(4) = TICK
      C(5) = ABST
      C(6) = .0
      ENDIF 
      
      IF (AUTOSCALE .NE. 'AUTO' .AND.
     >    AUTOSCALE .NE. 'AUTOX' .AND.
     >    AUTOSCALE .NE. 'AUTOY') THEN 
        WRITE (6,'(//,A,A)') 'NO SUCH AUTOSCALE OPTION: ', AUTOSCALE
        WRITE (6,'(A)') 'FATAL ERROR DETECTED BY SUBR. AUTOSCALE'
	STOP 'ERROR'
      ENDIF

c      write (*,*) 
c      write (*,*) 'AUTOSCALE INFORMATION'
c      write (*,'(4a12)') 'xmin', 'xmax', 'ymin', 'ymax'
c      write (*,'(4f12.5)') xmin, xmax, ymin, ymax
c
c      WRITE (*,'(a,6(f8.3,2x))') 
c     >      'X:', (B(I), I=1,6)
c      WRITE (*,'(a,6(f8.3,2x))') 
c     >      'Y:', (C(I), I=1,6)

      RETURN
      END

fitsmod.f/      1553528659  5006  320   100644  2324      `
C***  Program to reorder header lines in FITS files
C***  This program is necessary for making Kiel-MODCOMP output readable 
C***  with standard fits routines
      SUBROUTINE FITSMOD

      CHARACTER LINE(36)*80, LINEACT*80, LINETOT*2880

C***  OPEN FITS FILE (RANDOM ACCESS)
      OPEN (UNIT=1, FILE='input.fits', STATUS='OLD', ACCESS='DIRECT', 
     >      RECL=720)
      OPEN (UNIT=2, FILE='output.fits', STATUS='NEW', ACCESS='DIRECT', 
     >      RECL=720)

C***  READ FIRST RECORD AND DE-COMPOSE LINE-BY-LINE
      READ (1, REC=1) LINETOT
      DO I=1,36
      ISTART = 1 + (I-1)*80
      IEND   = ISTART + 79
      LINE(I) = LINETOT(ISTART:IEND)
      ENDDO


C***  testoutput
      WRITE (*,'(A)') 'vorher ......'
      DO I=1,36
      WRITE (*,'(A)') LINE(I)
      IF (LINE(I)(:3) .EQ.'END') GOTO 1
      ENDDO
    1 WRITE (*,'(A)') '-- END REACHED --'


C***  RE-ARRANGE LINES
C*********************

C***  FIND LINE INDICES
      DO I=1,36
      IF (LINE(I)(:6) .EQ. 'BITPIX') IBITPIX = I
      IF (LINE(I)(:6) .EQ. 'NAXIS ') INAXIS = I
      IF (LINE(I)(:6) .EQ. 'NAXIS1') INAXIS1 = I
      ENDDO

C***  Put BITPIX in Line 2
      LINEACT = LINE(IBITPIX)
      NEWPOS = 2
      DO I=IBITPIX-1, NEWPOS, -1
      LINE(I+1) = LINE(I)
      ENDDO
      LINE(NEWPOS) = LINEACT

C***  Put NAXIS in Line 3
      NEWPOS = 3
      LINEACT = LINE(INAXIS)
      DO I=INAXIS-1, NEWPOS, -1
      LINE(I+1) = LINE(I)
      ENDDO
      LINE(NEWPOS) = LINEACT

C***  Put NAXIS1 in Line 4
      NEWPOS = 4
      LINEACT = LINE(INAXIS1)
      DO I=INAXIS1-1, NEWPOS, -1
      LINE(I+1) = LINE(I)
      ENDDO
      LINE(NEWPOS) = LINEACT

C***  testoutput
      WRITE (*,'(A)') 'nachher ......'
      DO I=1,36
      WRITE (*,'(A)') LINE(I)
      IF (LINE(I)(:3) .EQ.'END') GOTO 2
      ENDDO
    2 WRITE (*,'(A)') '-- END REACHED --'



C***  WRITE ONE RECORD AFTER COMPOSING IT FROM THE LINES
      DO I=1,36
      ISTART = 1 + (I-1)*80
      IEND   = ISTART + 79
      LINETOT(ISTART:IEND) = LINE(I)
      ENDDO
      WRITE(2, REC=1) LINETOT


C***  LOOP OVER THE OTHER RECORDS
      IREC = 2
   10 CONTINUE
      READ (1, REC=IREC, ERR=100) LINETOT
      WRITE(2, REC=IREC) LINETOT
      IREC = IREC + 1
      GOTO 10


C***  ERROR = LAST RECORD FINISHED
  100 CONTINUE

      CLOSE (1)
      CLOSE (2)

      STOP
      END
modcheck.f/     1653499856  5006  320   100644  2969      `
      SUBROUTINE MODCHECK

      CHARACTER LINE*132, OUTLINE*132
      CHARACTER ACTPAR*40, ACTPAR2*40, STRING*40

C***  EINGABE DER BEREICHE
      WRITE (*,*) 'T1='
      READ (*,'(F10.0)') T1
      WRITE (*,*) 'T2='
      READ (*,'(F10.0)') T2

      WRITE (*,*) 'Rt1='
      READ (*,'(F10.0)') RT1
      WRITE (*,*) 'Rt2='
      READ (*,'(F10.0)') RT2

      WRITE (*,*) 'R*1='
      READ (*,'(F10.0)') RS1
      WRITE (*,*) 'R*2='
      READ (*,'(F10.0)') RS2

      WRITE (*,*) 'Mdot1='
      READ (*,'(F10.0)') MDOT1
      WRITE (*,*) 'Mdot2='
      READ (*,'(F10.0)') MDOT2

      WRITE (*,*) 'V81='
      READ (*,'(F10.0)') V81
      WRITE (*,*) 'V82='
      READ (*,'(F10.0)') V82

      WRITE (*,*) 'STRING='
      READ (*,'(A)') STRING

C***  DURCHFORSTEN DES FILES temp.doc
      OPEN (UNIT=1, FILE='temp.doc', STATUS='OLD')

C***  LESEN BIS ZUM NAECHSTEN 'MODEL START'
    1 CONTINUE
        READ (1,'(A)',END=99) LINE
        CALL SARGV(LINE, 1, ACTPAR)
        CALL SARGV(LINE, 2, ACTPAR2)
      IF (ACTPAR .NE. 'MODEL' .OR. ACTPAR2 .NE. 'START') GOTO 1

C***  PRUEFEN
      OUTLINE = LINE
C***  T*
      READ (1,'(A)',END=98) LINE
      CALL SARGV(LINE, 2, ACTPAR)
      READ (ACTPAR, '(F15.5)', ERR=10) T
      IF (T1 .NE. 0. .AND. T2. NE. 0. .AND. 
     >    (T .LT. T1 .OR. T .GT. T2)) THEN
        GOTO 1
      ENDIF
   10 CONTINUE

C***  Rt
      READ (1,'(A)',END=98) LINE
      CALL SARGV(LINE, 2, ACTPAR)
      READ (ACTPAR, '(F15.5)', ERR=20) RT
      IF (RT1 .NE. 0. .AND. RT2. NE. 0. .AND. 
     >    (RT .LT. RT1 .OR. RT .GT. RT2)) THEN
        GOTO 1
      ENDIF
   20 CONTINUE

C***  R*
      READ (1,'(A)',END=98) LINE
      CALL SARGV(LINE, 2, ACTPAR)
      READ (ACTPAR, '(F15.5)', ERR=30) RS
      IF (RS1 .NE. 0. .AND. RS2. NE. 0. .AND. 
     >    (RS .LT. RS1 .OR. RS .GT. RS2)) THEN
        GOTO 1
      ENDIF
   30 CONTINUE

C***  Mdot
      READ (1,'(A)',END=98) LINE
      CALL SARGV(LINE, 2, ACTPAR)
      READ (ACTPAR, '(F15.5)', ERR=40) MDOT
      IF (MDOT1 .NE. 0. .AND. MDOT2. NE. 0. .AND. 
     >    (MDOT .LT. MDOT1 .OR. MDOT .GT. MDOT2)) THEN
        GOTO 1
      ENDIF
   40 CONTINUE

C***  V8
      READ (1,'(A)',END=98) LINE
      CALL SARGV(LINE, 2, ACTPAR)
      READ (ACTPAR, '(F15.5)', ERR=50) V8
      IF (V8 .LT. 10.) THEN
        CALL SARGV(LINE, 3, ACTPAR)
        READ (ACTPAR, '(F15.5)', ERR=50) V8
      ENDIF
      IF (V81 .NE. 0. .AND. V82. NE. 0. .AND. 
     >    (V8 .LT. V81 .OR. V8 .GT. V82)) THEN
        GOTO 1
      ENDIF
   50 CONTINUE

C***  UEBERPRUEFEN, OB STRING IN LINE ENTHALTEN
      I1 = IDX(OUTLINE)
      I2 = IDX(STRING)
      DO I=1, I1-I2+1
        IF (OUTLINE(I:I+I2-1) .EQ. STRING) THEN
          GOTO 5
        ENDIF
      ENDDO
      GOTO 1

    5 CONTINUE

C***  AUSGABE VON OUTLINE
      WRITE (*,'(A)') OUTLINE( :IDX(OUTLINE))

      GOTO 1

   98 CONTINUE
      WRITE (*,*) 'WRONG EXIT'
      STOP 'ERROR'

   99 CONTINUE
      STOP 'MODCHECK HAS WORKED CORRECTLY'

      END

plotbutt.f/     1553528659  5006  320   100644  4285      `
      SUBROUTINE PLOTBUTT (B, C,
     >              IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >              BINSEX,
     >              MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, 
     >              WIDBUTT, HEIBUTT, 
     >              KDLINE2, NKD2, NKDMAX2, NKDP2, STACT, NACT, 
     >              XCMA, YCMA, NDATMAX)

      COMMON /COMACT/ ACTDRIV
      CHARACTER ACTDRIV*7

      DIMENSION B(6), C(6)

      CHARACTER KDLINE2(NKDMAX2)*132
      CHARACTER*(*) VAR(MAXVAR,2)
      DIMENSION POSBUTT(MAXBUTT,MAXRBUTT,2)
      CHARACTER*(*) TEXTBUTT(MAXBUTT,MAXRBUTT)
      CHARACTER*132 LINE, LINE2, ACTPAR*20, ACTPAR2*20
      CHARACTER FNAME*255
                                 
      CHARACTER*20 STACT(NACT)

      LOGICAL KDPAUSE, BINSEX, BTRUE, BFALSE
      LOGICAL NOBUTT

c      write (*,*) 'in plotbutt : nact=',nact
c      do i=1, nact
c      write (*,*) 'i, stact=', i,stact(i)
c      enddo

      BTRUE = .TRUE.
      BFALSE = .FALSE.
                                 
C***  PLOT BUTTONS

      DX = WIDBUTT
      DY = HEIBUTT
      DX2 = DX / 2.
      DY2 = DY / 2.
c      write (*,*) 'PLOTBUTT : NBUTT=', nbutt
      DO J=1, NBUTT
        NOBUTT = (J .GT. NACT .AND. .NOT. 
     >            (NACT .EQ. 4))
c     >            .OR. STACT(J+1) .EQ. 'SKIP')
c        nobutt = .false.
        DO K=1, 10
          IF (TEXTBUTT(K,J)( :IDX(TEXTBUTT(K,J))) .EQ. ' ') THEN
            NOBUTT = .TRUE.
          ENDIF
          XU1 = (POSBUTT(K,J,1)-DX2) / B(1) + B(2)
          YU1 = (POSBUTT(K,J,2)-DY2) / C(1) + C(2)
          XU2 = (POSBUTT(K,J,1)+DX2) / B(1) + B(2)
          YU2 = (POSBUTT(K,J,2)+DY2) / C(1) + C(2)
          XUM = POSBUTT(K,J,1)       / B(1) + B(2)
          YUM = POSBUTT(K,J,2)       / C(1) + C(2)

          IF (NOBUTT) THEN
C***  SWEEP POSITIONS OF BUTTON
            WRITE (KDLINE2(1),'(A)') 'KASDEF COLOR=0'
            WRITE (KDLINE2(2),'(A,4(E14.8,1X),A)') 'KASDEF RECT ',
     >           XU1, YU1, XU2, YU2, ' 0. 0. FILLED'
            NKDP2 = 1
            NKD2 = 2
            CALL KDPLOT (B, C, KDLINE2, NKD2, NKDMAX2, NKDP2, BFALSE,
     >                   IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >                   BINSEX, XCMA, YCMA, NDATMAX)

          ELSE IF (TEXTBUTT(K,J) .EQ. ' ') THEN
C***  PLOT EMPTY BUTTON
            WRITE (KDLINE2(1),'(A)') 'KASDEF COLOR=0'
            WRITE (KDLINE2(2),'(A,4(E14.8,1X),A)') 'KASDEF RECT ',
     >           XU1, YU1, XU2, YU2, ' 0. 0. FILLED'
            WRITE (KDLINE2(3),'(A)') 'KASDEF COLOR=1'
            WRITE (KDLINE2(4),'(A,4(E14.8,1X),A)') 'KASDEF RECT ',
     >           XU1, YU1, XU2, YU2, ' 0. 0.'
            NKDP2 = 1
            NKD2 = 4
            CALL KDPLOT (B, C, KDLINE2, NKD2, NKDMAX2, NKDP2, BFALSE,
     >                   IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >                   BINSEX, XCMA, YCMA, NDATMAX)

          ELSE
C***  PLOT BUTTON
            IF (J .LT. NACT) THEN
              JJ = J
  200         CONTINUE
                JJ = JJ + 1
                ACTPAR = STACT(JJ)
              IF (ACTPAR .EQ. 'SKIP') GOTO 200
            ELSE
              ACTPAR = 'DUMMY'
            ENDIF
C***  SELECT COLOR
            IF (TEXTBUTT(K,J) .EQ. ACTPAR) THEN
              WRITE (KDLINE2(1),'(A)') 'KASDEF COLOR=2'
            ELSE
              IF (J .LT. NACT) THEN
                WRITE (KDLINE2(1),'(A)') 'KASDEF COLOR=7'
              ELSE
                WRITE (KDLINE2(1),'(A)') 'KASDEF COLOR=5'
              ENDIF
            ENDIF

            WRITE (KDLINE2(2),'(A,4(E14.8,1X),A)') 'KASDEF RECT ',
     >           XU1, YU1, XU2, YU2, ' 0. 0. FILLED'
            WRITE (KDLINE2(3),'(A)') 'KASDEF PEN=3'
            WRITE (KDLINE2(4),'(A)') 'KASDEF COLOR=1'
            WRITE (KDLINE2(5),'(A,4(E14.8,1X),A)') 'KASDEF RECT ',
     >           XU1, YU1, XU2, YU2, ' 0. 0.'
            WRITE (KDLINE2(6),'(A,2(E14.8,1X),A,A)') 'KASDEF LUN ',
     >             XUM, YUM, ' M0. M0. 0.3 &E', TEXTBUTT(K,J)
            NKDP2 = 1
            NKD2 = 6
            CALL KDPLOT (B, C, KDLINE2, NKD2, NKDMAX2, NKDP2, BFALSE,
     >                   IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >                   BINSEX, XCMA, YCMA, NDATMAX)
          ENDIF

   20     CONTINUE

        ENDDO
      ENDDO

      RETURN
      END

recbutt.f/      1553528659  5006  320   100644  824       `
      SUBROUTINE RECBUTT(MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT,
     >             WIDBUTT, HEIBUTT, XCM, YCM, ACTION, NACT)

C***  RECOGNIZES BUTTON-ACTION

      DIMENSION POSBUTT(MAXBUTT,MAXRBUTT,2)
      CHARACTER*(*) TEXTBUTT(MAXBUTT,MAXRBUTT)
      CHARACTER*(*) ACTION

      ACTION = ' '

      WID = WIDBUTT / 2.
      HEI = HEIBUTT / 2.

      ISTART =  NACT
      IF (NACT .EQ. 4) THEN
        IEND   =  ISTART + 1
      ELSE
        IEND = ISTART
      ENDIF

      DO I=ISTART, IEND
        DO J=1, MAXBUTT
          X = POSBUTT(J,I,1)
          Y = POSBUTT(J,I,2)
          IF ((XCM .LE. X+WID) .AND. (XCM .GE. X-WID) .AND.
     >        (YCM .LE. Y+HEI) .AND. (YCM .GE. Y-HEI)) THEN
            ACTION = TEXTBUTT(J,I)
            RETURN
          ENDIF
        ENDDO
      ENDDO

      RETURN
      END
plotmess.f/     1553528659  5006  320   100644  3201      `
      SUBROUTINE PLOTMESS(B, C,
     >                KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >                BINSEX,
     >                MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, 
     >                TEXTBUTT, INTACT,
     >                WIDBUTT, HEIBUTT, MESSAGE, NMESS, 
     >                KDLINE2, NKD2, NKDMAX2, NKDP2, CMODUS, 
     >                XCMA, YCMA, NDATMAX)

      COMMON /COMACT/ ACTDRIV
      CHARACTER ACTDRIV*7

      DIMENSION B(6), C(6)

      CHARACTER KDLINE2(NKDMAX2)*132
      CHARACTER*(*) VAR(MAXVAR,2)
      DIMENSION POSBUTT(MAXBUTT,MAXRBUTT,2)
      CHARACTER*(*) TEXTBUTT(MAXBUTT,MAXRBUTT), MESSAGE(5)
      CHARACTER*80 LINE(4), LINE2, ACTPAR*40, ACTPAR2*40, INTACT*20
      CHARACTER FNAME*255, CMODUS*20
      CHARACTER CLUN*23, CPEN*5, COFFX*4, COFFY*4, CSIZE*6, CCOLOR*7

      LOGICAL BFIRST, BINSEX, BTRUE, BFALSE

      BTRUE = .TRUE.
      BFALSE = .FALSE.

C***  PLOT MESSAGE

      IF (CMODUS .EQ. 'P1BIG') THEN
        XUM = B(2)
        YUM = C(3)
        CLUN = 'L=0.1 R=0.1 U=0.1 D=0.1'
        CPEN = 'PEN=5'
        CCOLOR = 'COLOR=2'
        CSIZE = ' 0.6  '
        COFFX = ' 0.0'
        COFFY = ' 0.3'
      ELSE IF (CMODUS .EQ. 'P1NOR') THEN
        XUM = B(2)
        YUM = 15.4 / C(1) + C(2)
        CLUN = 'L=0.1 R=0.1 U=0.1 D=0.1'
        CPEN = 'PEN=3'
        CCOLOR = 'COLOR=2'
        CSIZE = ' 0.25 '
        COFFX = ' 0.0'
        COFFY = ' 0.3'
      ELSE IF (CMODUS .EQ. 'P2NOR') THEN
        XUM = B(2)
        YUM = 14.9 / C(1) + C(2)
        CLUN = 'L=0.1 R=0.1 U=0.1 D=0.1'
        CPEN = 'PEN=3'
        CCOLOR = 'COLOR=2'
        CSIZE = ' 0.25 '
        COFFX = ' 0.0'
        COFFY = ' 0.3'
      ELSE IF (CMODUS .EQ. 'SELSET') THEN
        XUM = 20.2  / B(1) + B(2)
        YUM = 15.4 / C(1) + C(2)
        CLUN = 'L=0.1 R=0.1 U=0.1 D=0.1'
        CPEN = 'PEN=3'
        CCOLOR = 'COLOR=2'
        CSIZE = ' 0.25 '
        COFFX = ' 0.0'
        COFFY = ' 0.3'
      ENDIF


        WRITE (KDLINE2(1),'(A)') 'KASDEF BGRLUN ON'
        KDLINE2(2) = 'KASDEF BGRLUN ' // CLUN
        KDLINE2(3) = 'KASDEF ' // CPEN
        KDLINE2(4) = 'KASDEF ' // CCOLOR
        WRITE (KDLINE2(5),'(A,2(1X,E14.8),4A)') 'KASDEF LUN ',
     >         XUM, YUM, COFFX, COFFY, CSIZE, 
     >         '&N------------------------------------&N'
        DO I=2, NMESS
          WRITE (KDLINE2(4+I),'(A,A)') 'KASDEF NEXTLUN ',
     >           '&N                                            &N'
        ENDDO
        WRITE (KDLINE2(5+NMESS),'(A,2(1X,E14.8),4A)') 'KASDEF LUN ',
     >         XUM, YUM, COFFX, COFFY, CSIZE, 
     >         MESSAGE(1)( :IDX(MESSAGE(1)))
        DO I=2, NMESS
          WRITE (KDLINE2(4+NMESS+I),'(A,A)') 'KASDEF NEXTLUN ',
     >           MESSAGE(I)( :IDX(MESSAGE(I)))
        ENDDO
        WRITE (KDLINE2(4+2*NMESS+1),'(A)') 'KASDEF COLOR=1'
        WRITE (KDLINE2(4+2*NMESS+2),'(A)') 'KASDEF PEN=1'
        WRITE (KDLINE2(4+2*NMESS+3),'(A)') 'KASDEF BGRLUN OFF'
        NKDP2 = 1
        NKD2 = 4+2*NMESS+3
        CALL KDPLOT (B, C, KDLINE2, NKD2, NKDMAX2, NKDP2, BFALSE,
     >               IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >               BINSEX, XCMA, YCMA, NDATMAX)

      END

wipe.f/         1553528659  5006  320   100644  896       `
      SUBROUTINE WIPE(B, C,
     >               KDPAUSE, IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >               BINSEX,
     >               KDLINE2, NKD2, NKDMAX2, NKDP2, XCMA, YCMA, NDATMAX)

      COMMON /COMACT/ ACTDRIV
      CHARACTER ACTDRIV*7

      DIMENSION B(6), C(6)

      CHARACTER KDLINE2(NKDMAX2)*132
      CHARACTER*(*) VAR(MAXVAR,2)
      CHARACTER FNAME*255

      LOGICAL KDPAUSE, BINSEX, BTRUE, BFALSE

      BTRUE = .TRUE.
      BFALSE = .FALSE.

      WRITE (KDLINE2(1),'(A)') 'KASDEF COLOR=0'
      WRITE (KDLINE2(2),'(A)') 
     >       'KASDEF RECT PXMIN PYMIN PXMAX PYMAX 0. 0. FILLED'
      WRITE (KDLINE2(3),'(A)') 'KASDEF COLOR=1'
      NKDP2 = 1
      NKD2 = 3
      CALL KDPLOT (B, C, KDLINE2, NKD2, NKDMAX2, NKDP2, BFALSE,
     >             IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >             BINSEX, XCMA, YCMA, NDATMAX)

      RETURN
      END

plotpoint.f/    1553528659  5006  320   100644  1325      `
      SUBROUTINE PLOTPOINT (B, C,
     >              IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >              BINSEX,
     >              MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT, 
     >              WIDBUTT, HEIBUTT, 
     >              KDLINE2, NKD2, NKDMAX2, NKDP2, XINT, YINT, NINT, 
     >              XCMA, YCMA, NDATMAX)

      COMMON /COMACT/ ACTDRIV
      CHARACTER ACTDRIV*7

      DIMENSION B(6), C(6)
      DIMENSION XINT(NINT), YINT(NINT)

      CHARACTER KDLINE2(NKDMAX2)*132
      CHARACTER*(*) VAR(MAXVAR,2)
      DIMENSION POSBUTT(MAXBUTT,MAXRBUTT,2)
      CHARACTER*(*) TEXTBUTT(MAXBUTT,MAXRBUTT)
      CHARACTER*132 LINE, LINE2, ACTPAR*40, ACTPAR2*40
      CHARACTER FNAME*255

      LOGICAL KDPAUSE, BINSEX, BTRUE, BFALSE

      BTRUE = .TRUE.
      BFALSE = .FALSE.
                                 
C***  PLOT POINTS
      WRITE (KDLINE2(1),'(A)') 'KASDEF COLOR=4'
      DO I=1, NINT
        WRITE (KDLINE2(I+1),'(A,2(G14.6,1X),A)') 'KASDEF SYM ',
     >       XINT(I), YINT(I), '0. 0. 0.4 1'
      ENDDO
      WRITE (KDLINE2(NINT+2),'(A)') 'KASDEF COLOR=1'
      NKDP2 = 1
      NKD2 = NINT + 2
      CALL KDPLOT (B, C, KDLINE2, NKD2, NKDMAX2, NKDP2, BFALSE,
     >             IDEV, FNAME, LASTPEN, VAR, MAXVAR, NVAR,
     >             BINSEX, XCMA, YCMA, NDATMAX)

      RETURN
      END

setbutt.f/      1553528659  5006  320   100644  11268     `
      SUBROUTINE SETBUTT(MAXBUTT, MAXRBUTT, NBUTT, POSBUTT, TEXTBUTT,
     >                   WIDBUTT, HEIBUTT, STACT, NACT, IACT, NSCRBUTT, 
     >                   NSET)

C***  SET POSITION OF THE BUTTONS
C***  PRESETS TEXTBUTT

      DIMENSION POSBUTT(MAXBUTT,MAXRBUTT,2), NSCRBUTT(MAXRBUTT)
      CHARACTER*(*) TEXTBUTT(MAXBUTT,MAXRBUTT)
      CHARACTER*(*) STACT(NACT)

c      write (*,*) 'in setbutt : nact=',nact
c      do i=1, nact
c      write (*,*) 'i, stact=', i,stact(i)
c      enddo
c      write (*,*) 'SETBUTT : NBUTT=', nbutt

C*** FIRST RESET OF TEXTBUTT
      DO I=1, NBUTT
        DO J=1, MAXBUTT
          TEXTBUTT(J,I) = ' '
        ENDDO
      ENDDO

      IF (STACT(1) .EQ. 'START') THEN
C*** PRESET POSITIONS OF BUTTONS
        WIDBUTT = 2.0
        HEIBUTT = 0.5
        DO I=1, NBUTT
          DO J=1, MAXBUTT
            IF (I .LE. 3) THEN
              IF (I .LE. 1) THEN
                POSBUTT(J,I,1) = 1.0 + FLOAT(J-1)*2.2
                POSBUTT(J,I,2) = 17.6
              ELSE IF (I .LE. 2) THEN
                POSBUTT(J,I,1) = 1.0 + FLOAT(J-1)*2.2
                POSBUTT(J,I,2) = 17.0
              ELSE
                POSBUTT(J,I,1) = 1.0 + FLOAT(J-1)*2.2
                POSBUTT(J,I,2) = 16.4
              ENDIF
            ELSE
              POSBUTT(J,I,1) = 21.5
              POSBUTT(J,I,2) = 14.75 - FLOAT(J-1+(I-4)*10)*0.75
            ENDIF
          ENDDO
          NSCRBUTT(I) = 0
        ENDDO
      ENDIF

C---  MENU FIRST ORDER ---------------------------------------
      IF (STACT(1) .EQ. 'BASE' .AND.
     >    NACT .GE. 1) THEN
        TEXTBUTT(1,1)  = 'QUIT'
        TEXTBUTT(2,1)  = 'POINTS'
        TEXTBUTT(3,1)  = 'BOUND'
        TEXTBUTT(4,1)  = 'DATASETS'
      ENDIF

      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'POINTS' .AND.
     >    NACT .GE. 2) THEN
        INOSCR = 2
        TEXTBUTT(1,2)  = 'BACK'
        TEXTBUTT(2,2)  = 'REFRESH'
        TEXTBUTT(3,2)  = 'ADD_POINTS'
        TEXTBUTT(4,2)  = 'DEL_POINTS'
        TEXTBUTT(5,2)  = 'DEL_ALL_P'
        TEXTBUTT(6,2)  = 'SORT_POI.'
        TEXTBUTT(7,2)  = 'EQUIV.'
        TEXTBUTT(8,2)  = 'CHK_INCR.'
        TEXTBUTT(9,2)  = 'SAVE-ND'
        TEXTBUTT(10,2) = 'SAVE-XY'
        TEXTBUTT(11,2) = '...'
      ENDIF

      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'POINTS' .AND.
     >    STACT(3) .EQ. 'EQUIV.' .AND.
     >    NACT .GE. 4) THEN
c        INOSCR = 2
          TEXTBUTT(1,4)  = 'BACK'
          TEXTBUTT(2,4)  = 'ABORT'
          TEXTBUTT(3,4)  = 'LAST'
          DO I=1, NSET
            WRITE (TEXTBUTT(I+3,4), '(I2)') I
          ENDDO
      ENDIF

      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'BOUND' .AND.
     >    NACT .GE. 2) THEN
        TEXTBUTT(1,2)  = 'BACK'
        TEXTBUTT(2,2)  = 'REFRESH'
        TEXTBUTT(3,2)  = 'RESTORE'
        TEXTBUTT(4,2)  = 'AUTO'
        TEXTBUTT(5,2)  = 'TICKS'
        TEXTBUTT(6,2)  = 'GRAPHICS'
        TEXTBUTT(7,2)  = 'MAN'
      ENDIF

      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'BOUND' .AND.
     >    STACT(3) .EQ. 'TICKS' .AND.
     >    NACT .GE. 3) THEN
        TEXTBUTT(1,3)  = 'BACK'
        TEXTBUTT(2,3)  = 'REFRESH'
        TEXTBUTT(3,3)  = 'AUTO_T'
        TEXTBUTT(4,3)  = 'AUTO_XT'
        TEXTBUTT(5,3)  = 'AUTO_YT'
      ENDIF

      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'BOUND' .AND.
     >    STACT(3) .EQ. 'GRAPHICS' .AND.
     >    NACT .GE. 3) THEN
        TEXTBUTT(1,3)  = 'BACK'
        TEXTBUTT(2,3)  = 'REFRESH'
        TEXTBUTT(3,3)  = 'X&&Y'
        TEXTBUTT(4,3)  = 'X'
        TEXTBUTT(5,3)  = 'Y'
      ENDIF

      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'BOUND' .AND.
     >    STACT(3) .EQ. 'MAN' .AND.
     >    NACT .GE. 3) THEN
        TEXTBUTT(1,3)  = 'BACK'
        TEXTBUTT(2,3)  = 'REFRESH'
        TEXTBUTT(3,3)  = 'LEFT'
        TEXTBUTT(4,3)  = 'RIGHT'
        TEXTBUTT(5,3)  = 'BOTTOM'
        TEXTBUTT(6,3)  = 'TOP'
      ENDIF

      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'BOUND' .AND.
     >    STACT(3) .EQ. 'MAN' .AND.
     >    (STACT(4) .EQ. 'LEFT' .OR.
     >     STACT(4) .EQ. 'RIGHT' .OR.
     >     STACT(4) .EQ. 'BOTTOM' .OR.
     >     STACT(4) .EQ. 'TOP') .AND.
     >    NACT .GE. 4) THEN
        INOSCR = 1
        TEXTBUTT(1,4)  = 'BACK'
        TEXTBUTT(2,4)  = '+100%'
        TEXTBUTT(3,4)  = '+50 %'
        TEXTBUTT(4,4)  = '+10 %'
        TEXTBUTT(5,4)  = '+1  %'
        TEXTBUTT(6,4)  = '-1  %'
        TEXTBUTT(7,4)  = '-10 %'
        TEXTBUTT(8,4)  = '-10 %'
        TEXTBUTT(9,4)  = '-50 %'
        TEXTBUTT(10,4) = '-80 %'
        TEXTBUTT(11,4)  = '+100.'
        TEXTBUTT(12,4)  = '+10. '
        TEXTBUTT(13,4)  = '+1.  '
        TEXTBUTT(14,4)  = '+0.1 '
        TEXTBUTT(15,4)  = '-0.1 '
        TEXTBUTT(16,4)  = '-1.  '
        TEXTBUTT(17,4)  = '-10. '
        TEXTBUTT(18,4)  = '-100.'
        
      ENDIF

      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'DATASETS' .AND.
     >    NACT .GE. 2) THEN
        TEXTBUTT(1,2)  = 'BACK'
        TEXTBUTT(2,2)  = 'REFRESH'
        TEXTBUTT(3,2)  = 'NUMBER'
        TEXTBUTT(4,2)  = 'DATAINFO'
        TEXTBUTT(5,2)  = 'SELECT'
        TEXTBUTT(6,2)  = 'ATTRIBUTE'
        TEXTBUTT(7,2)  = 'MANIPULATE'
        TEXTBUTT(8,2)  = 'MAN_1'
        TEXTBUTT(9,2)  = 'SKIP_LD'
      ENDIF

      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'DATASETS' .AND.
     >    STACT(3) .EQ. 'DATAINFO' .AND. 
     >    STACT(4) .EQ. 'SKIP' .AND.
     >    NACT .GE. 4) THEN
        INOSCR = 1
        TEXTBUTT(1,4)  = 'BACK'
        DO I=1, NSET
          WRITE (TEXTBUTT(I+1,4), '(I2)') I
        ENDDO
      ENDIF

      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'DATASETS' .AND.
     >    STACT(3) .EQ. 'SELECT' .AND. 
     >    NACT .GE. 3) THEN
        TEXTBUTT(1,3)  = 'BACK'
        TEXTBUTT(2,3)  = 'SET_1'
        TEXTBUTT(3,3)  = 'SET_2'
        TEXTBUTT(4,3)  = 'SET_3'
      ENDIF

      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'DATASETS' .AND.
     >    STACT(3) .EQ. 'ATTRIBUTE' .AND. 
     >    NACT .GE. 3) THEN
        IF (IACT .EQ. 1) THEN
          TEXTBUTT(1,3)  = 'BACK'
          TEXTBUTT(2,3)  = 'REFRESH'
          TEXTBUTT(3,3)  = 'DATASET'
        ELSE
          TEXTBUTT(1,3)  = 'BACK'
          TEXTBUTT(2,3)  = 'REFRESH'
          TEXTBUTT(3,3)  = 'SYMBOL'
          TEXTBUTT(4,3)  = 'SIZE'
          TEXTBUTT(5,3)  = 'COLOR'
        ENDIF
      ENDIF

      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'DATASETS' .AND.
     >    STACT(3) .EQ. 'ATTRIBUTE' .AND. 
     >    (STACT(4) .EQ. 'DATASET' .OR. STACT(4) .EQ. 'SYMBOL' .OR.
     >     STACT(4) .EQ. 'COLOR' ) .AND. 
     >    NACT .GE. 4) THEN
        TEXTBUTT(1,4)  = 'ABORT'
        TEXTBUTT(2,4)  = ' 1'
        TEXTBUTT(3,4)  = ' 2'
        TEXTBUTT(4,4)  = ' 3'
        TEXTBUTT(5,4)  = ' 4'
        TEXTBUTT(6,4)  = ' 5'
        TEXTBUTT(7,4)  = ' 6'
        TEXTBUTT(8,4)  = ' 7'
        TEXTBUTT(9,4)  = ' 8'
        TEXTBUTT(10,4)  = ' 9'
      ENDIF

      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'DATASETS' .AND.
     >    STACT(3) .EQ. 'ATTRIBUTE' .AND. 
     >    STACT(4) .EQ. 'SIZE' .AND. 
     >    NACT .GE. 4) THEN
        TEXTBUTT(1,4)  = 'ABORT'
        TEXTBUTT(2,4)  = '0.1'
        TEXTBUTT(3,4)  = '0.2'
        TEXTBUTT(4,4)  = '0.3'
        TEXTBUTT(5,4)  = '0.4'
        TEXTBUTT(6,4)  = '0.5'
        TEXTBUTT(7,4)  = '0.6'
        TEXTBUTT(8,4)  = '0.7'
        TEXTBUTT(9,4)  = '0.8'
        TEXTBUTT(10,4)  = '0.9'
        TEXTBUTT(1,5)  = '1.0'
      ENDIF

      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'DATASETS' .AND.
     >    STACT(3) .EQ. 'MANIPULATE' .AND. 
     >    NACT .GE. 3) THEN
        TEXTBUTT(1,3)  = 'BACK'
        TEXTBUTT(2,3)  = 'REFRESH'
        TEXTBUTT(3,3)  = 'ARI'
      ENDIF

      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'DATASETS' .AND.
     >    STACT(3) .EQ. 'MANIPULATE' .AND. 
     >    STACT(4) .EQ. 'ARI' .AND. 
     >    NACT .GE. 4) THEN
        IF (IACT .EQ. 1 .OR. IACT .EQ. 3) THEN
          TEXTBUTT(1,4)  = 'ABORT'
          DO I=1, NSET
            WRITE (TEXTBUTT(I+1,4), '(I2)') I
          ENDDO
        ELSE IF (IACT .EQ. 2) THEN
          TEXTBUTT(1,4)  = 'ABORT'
          TEXTBUTT(2,4)  = ' +'
          TEXTBUTT(3,4)  = ' -'
          TEXTBUTT(4,4)  = ' *'
          TEXTBUTT(5,4)  = ' /'
        ELSE
          TEXTBUTT(1,4)  = 'ABORT'
          TEXTBUTT(2,4)  = 'EXE'
        ENDIF
      ENDIF

      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'DATASETS' .AND.
     >    STACT(3) .EQ. 'MAN_1' .AND. 
     >    NACT .GE. 3) THEN
        INOSCR = 2
        TEXTBUTT(1,3)  = 'BACK'
        TEXTBUTT(2,3)  = 'REFRESH'
        TEXTBUTT(3,3)  = 'XLOG'
        TEXTBUTT(4,3)  = 'YLOG'
        TEXTBUTT(5,3)  = '10**X'
        TEXTBUTT(6,3)  = '10**Y'
        TEXTBUTT(7,3)  = 'SIGN(X)'
        TEXTBUTT(8,3)  = 'SIGN(Y)'
        TEXTBUTT(9,3)  = 'X+'
        TEXTBUTT(10,3)  = 'bbb'
        TEXTBUTT(11,3)  = 'c'
        TEXTBUTT(12,3)  = 'd'
        TEXTBUTT(13,3)  = 'eee'
        TEXTBUTT(14,3)  = 'ff'
      ENDIF

      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'DATASETS' .AND.
     >    STACT(3) .EQ. 'MAN_1' .AND. 
     >    (STACT(4) .EQ. 'XLOG' .OR.
     >     STACT(4) .EQ. 'YLOG' .OR.
     >     STACT(4) .EQ. '10**X' .OR.
     >     STACT(4) .EQ. '10**Y' .OR.
     >     STACT(4) .EQ. 'SIGN(X)' .OR.
     >     STACT(4) .EQ. 'SIGN(Y)')
     >    .AND. NACT .GE. 4) THEN
        IF (IACT .EQ. 1) THEN
          TEXTBUTT(1,4)  = 'ABORT'
          TEXTBUTT(2,4)  = 'LAST'
          TEXTBUTT(3,4)  = ' 1'
          TEXTBUTT(4,4)  = ' 2'
          TEXTBUTT(5,4)  = ' 3'
          TEXTBUTT(6,4)  = ' 4'
          TEXTBUTT(7,4)  = ' 5'
          TEXTBUTT(8,4)  = ' 6'
          TEXTBUTT(9,4)  = ' 7'
        ELSE
          TEXTBUTT(1,4)  = 'ABORT'
          TEXTBUTT(2,4)  = 'EXE'
        ENDIF
      ENDIF

      IF (STACT(1) .EQ. 'BASE' .AND.
     >    STACT(2) .EQ. 'DATASETS' .AND.
     >    STACT(3) .EQ. 'SELECT' .AND. 
     >    (STACT(4) .EQ. 'SET_1' .OR. 
     >     STACT(4) .EQ. 'SET_2' .OR. 
     >     STACT(4) .EQ. 'SET_3') .AND. 
     >    NACT .GE. 4) THEN
        TEXTBUTT(1,4)  = 'BACK'
        TEXTBUTT(2,4)  = ' 1'
        TEXTBUTT(3,4)  = ' 2'
        TEXTBUTT(4,4)  = ' 3'
        TEXTBUTT(5,4)  = ' 4'
        TEXTBUTT(6,4)  = ' 5'
        TEXTBUTT(7,4)  = ' 6'
        TEXTBUTT(8,4)  = ' 7'
        TEXTBUTT(9,4)  = ' 8'
        TEXTBUTT(10,4)  = ' 9'
        TEXTBUTT(1,5)  = '10'
        TEXTBUTT(2,5)  = '11'
        TEXTBUTT(3,5)  = '12'
        TEXTBUTT(4,5)  = '13'
        TEXTBUTT(5,5)  = '14'
      ENDIF

C***  DO BUTTON SCROLLING
C***  FIRST : FIND INDEX OF LAST BUTTON WHICH IS NOT ' ' IN ACTUAL ROW
      DO I=MAXBUTT, 1, -1
        IF (TEXTBUTT(I,NACT) .NE. ' ') GOTO 40
      ENDDO
   40 CONTINUE
        IF (I .LE. 10) THEN
          NSCRBUTT(NACT) = 0
        ELSE
C***  DO SCROLLING
        DO J=INOSCR+1, 10
          TEXTBUTT(J,NACT) = TEXTBUTT(J+NSCRBUTT(NACT),NACT)
        ENDDO
        IF (NSCRBUTT(NACT) .GT. 0) THEN
          TEXTBUTT(INOSCR+1,NACT) = '<<'
        ENDIF
        IF (I .GT. 10+NSCRBUTT(NACT)) THEN
          TEXTBUTT(10,NACT) = '>>'
        ENDIF
      ENDIF


      RETURN
      END
plotdatim.f/    1553528659  5006  320   100644  2902      `
      SUBROUTINE PLOTDATIM (NDATMAXIM, NSETMAXIM, IMPARMAX, ZIM, XIMPAR, 
     >                      ISETIM, B, C)
C*******************************************************************
C***  PLOT OF ONE SET OF IMAGE-DATA
C***  CALLED BY MAIN PROGRAMM WRPLOT
C*******************************************************************

      DIMENSION ZIM(NDATMAXIM, NSETMAXIM)
      DIMENSION XIMPAR(NSETMAXIM, IMPARMAX)

      DIMENSION B(6), C(6)
      COMMON / COMIDEV / IDEV 

C***  ACTIVE GRAPHIC DRIVER
      COMMON / COMACT / ACTDRIV
      CHARACTER ACTDRIV*7

C***  Scale Factor (conversion pt --> cm)
      COMMON / COMCMPT / CMPT

      write (*,*) 'PLOTDATIM START -----------------'

      hcut = 36000.

      NAXIS1 = INT(XIMPAR(ISETIM, 2))
      NAXIS2 = INT(XIMPAR(ISETIM, 3))
      IBINX = INT(XIMPAR(ISETIM, 4))
      IBINY = INT(XIMPAR(ISETIM, 5))
      ibinx = 1
      ibiny = 1

      write (*,*) 'isetim=', isetim
      write (*,*) 'marke ',naxis1, naxis2, ibinx, ibiny

      do ii=1, naxis1*naxis2
        zim(ii,isetim) = zim(ii,isetim) / hcut
        if (zim(ii,isetim) .gt. 1.) zim(ii,isetim)=1.
        if (zim(ii,isetim) .lt. 0.) zim(ii,isetim)=0.
c!!!        write (*,*) zim(ii,isetim)
      enddo

      call acc_xdrawarray (zim(1,isetim), naxis1, naxis2)
      return
      stop 'test'

      DO I=1, NAXIS2, IBINY
        INDY = (I-1) * NAXIS1
        Y1U = FLOAT(I)
        Y1CM = (Y1U-C(2))*C(1)
        Y1PT = Y1CM * CMPT
        CALL X_MOVEDRAW (1., Y1PT, 3)
        DO J=1, NAXIS1, IBINX
        INDX = (J-1) * IBINX + 1
          ZV = 0.
          DO II=1, IBINY
            DO JJ=1, IBINX
             INDEX = INDY + INDX + (II-1)*NAXIS1 + (JJ-1)
             ZV = ZV + ZIM(INDEX, ISETIM)
c             write (*,*) ii,jj,index,zv
            ENDDO
          ENDDO
          ZV = ZV / (IBINX*IBINY)
c       open (unit=22, name='temp.plot')
c       write (22,'(i,5x,i,5x,f10.5)') i,j,zv
c        write (*,*) 'zv=', zv
          GREY = ZV/HCUT
c          write (*,*) 'zv,grey=', zv,grey
          if (grey .gt. 1.) then grey = 1.
          grey = 1. - grey
c        if (zv .gt. hcut) then
c          grey = 0.
c        else
c          grey = 1.
c        endif
c          CALL X_NEWCOLOR (GREY, GREY, GREY)
c         write (*,*) 'grey=',grey
c          CALL X_NEWCOLOR (1., GREY, GREY)
          CALL acc_xsetcolor (1., GREY, GREY)
          CALL acc_xdrawpoint (j, i)
          X1U = FLOAT(J)
c          X2U = X1U + IBINX - 1.
c          Y2U = Y1U + IBINY - 1.
          X2U = X1U + IBINX
          Y2U = Y1U + IBINY
          X1CM = (X1U-B(2))*B(1)
          X2CM = (X2U-B(2))*B(1)
          Y2CM = (Y2U-C(2))*C(1)
          X1PT = X1CM * CMPT
c          write (*,*) 'cm=', x1cm, y1cm, x2cm, y2cm
c          CALL RECTA (X1CM, X2CM, Y1CM, Y2CM)
c           CALL X_MOVEDRAW (X1PT, Y1PT, 2)
        ENDDO
      ENDDO

      CALL X_NEWCOLOR (0, 0, 0)

      RETURN
      END
putvar.f/       1553528659  5006  320   100644  1059      `
      SUBROUTINE PUTVAR (ACTPAR, ACTPAR2, VAR, MAXVAR, NVAR)
C***************************************************
C***  STORING OF VARIABLES:
C***  ACTPAR IS THE NAME OF THE VARIABLE, 
C***  ACTPAR2 IS THE VALUE (COULD BE ALSO A VARIABLE)
C***************************************************

      CHARACTER*(*) VAR(MAXVAR,2)
      CHARACTER*(*) ACTPAR, ACTPAR2

      CALL DECVAR (ACTPAR2, VAR, MAXVAR, NVAR)
        I = 1
    5   IF (I .LE. NVAR) THEN
          IF (ACTPAR( :IDX(ACTPAR)) .EQ. 
     >        VAR(I,1)( :IDX(VAR(I,1)))) THEN
            VAR(I,2) = ACTPAR2
            GOTO 10
          ENDIF
          I = I + 1
        GOTO 5
        ENDIF
        IF (NVAR .LT. MAXVAR) THEN
          NVAR = NVAR + 1
          VAR(NVAR,1) = ACTPAR
          VAR(NVAR,2) = ACTPAR2
        ELSE
          WRITE (*,*) 
     >          '*** ERROR: MORE VARIABLES DEFINED THAN DIMENSIONED'
          WRITE (*,*) '*** VARIABLE CAUSING THE OVERFLOW: ', ACTPAR
          STOP '*** ERROR IN SUBROUTINE PUTVAR'
        ENDIF
   10   CONTINUE

      RETURN
      END

prevar.f/       1553528659  5006  320   100644  2940      `
      SUBROUTINE PREVAR (FNAME, B, C, OFSX, OFSY, FORMATFA, PLOTSKAL, 
     >                   PSIZEX, PSIZEY, VAR, MAXVAR, NVAR)
C**********************************************************************
C***  CALLED FROM: SUBR. KDPLOT (WRPLOT-PROGRAM)
C***  Writing the constants in variables of the same name
C***  Constants are XMIN, XMAX, YMIN, YMAX, 
C***                PXMIN, PXMAX, PYMIN, PYMAX, 
C***                XMASS, YMASS
C**********************************************************************

      CHARACTER*(*) VAR(MAXVAR,2), FNAME
      CHARACTER ACTPAR*20, ACTPAR2*20
      DIMENSION B(6), C(6)

      COMMON / COMCMPT / CMPT
      COMMON / COMCLIP / ICLIP, CXMIN(2), CXMAX(2), CYMIN(2), CYMAX(2)

C***  One point in cm
      ONEPT = 1./28.34

      ACTPAR = 'XMIN'
      VALUE = B(2)
      WRITE (ACTPAR2, '(F20.10)') VALUE
      CALL PUTVAR(ACTPAR, ACTPAR2, VAR, MAXVAR, NVAR)

      ACTPAR = 'XMAX'
      VALUE = B(3)
      WRITE (ACTPAR2, '(F20.10)') VALUE
      CALL PUTVAR(ACTPAR, ACTPAR2, VAR, MAXVAR, NVAR)

      ACTPAR = 'XMID'
      VALUE = (B(2) + B(3)) / 2.
      WRITE (ACTPAR2, '(F20.10)') VALUE
      CALL PUTVAR(ACTPAR, ACTPAR2, VAR, MAXVAR, NVAR)

      ACTPAR = 'YMIN'
      VALUE = C(2)
      WRITE (ACTPAR2, '(F20.10)') VALUE
      CALL PUTVAR(ACTPAR, ACTPAR2, VAR, MAXVAR, NVAR)

      ACTPAR = 'YMAX'
      VALUE = C(3)
      WRITE (ACTPAR2, '(F20.10)') VALUE
      CALL PUTVAR(ACTPAR, ACTPAR2, VAR, MAXVAR, NVAR)

      ACTPAR = 'YMID'
      VALUE = (C(2) + C(3)) / 2.
      WRITE (ACTPAR2, '(F20.10)') VALUE
      CALL PUTVAR(ACTPAR, ACTPAR2, VAR, MAXVAR, NVAR)

      ACTPAR = 'PXMIN'
      PXMIN = (B(2) - (OFSX) / B(1)) / PLOTSKAL
      WRITE (ACTPAR2, '(F20.10)') PXMIN
      CALL PUTVAR(ACTPAR, ACTPAR2, VAR, MAXVAR, NVAR)

      ACTPAR = 'PXMAX'
      PXMAX = (B(2) + (PSIZEX/FORMATFA-OFSX-ONEPT)/ B(1)) / PLOTSKAL 
      WRITE (ACTPAR2, '(F20.10)') PXMAX
      CALL PUTVAR(ACTPAR, ACTPAR2, VAR, MAXVAR, NVAR)

      ACTPAR = 'PYMIN'
      PYMIN = (C(2) - (OFSY-ONEPT) / C(1)) / PLOTSKAL
      WRITE (ACTPAR2, '(F20.10)') PYMIN
      CALL PUTVAR(ACTPAR, ACTPAR2, VAR, MAXVAR, NVAR)

      ACTPAR = 'PYMAX'
      PYMAX = (C(2) + (PSIZEY/FORMATFA-OFSY-ONEPT)/ C(1)) / PLOTSKAL 
      WRITE (ACTPAR2, '(F20.10)') PYMAX
      CALL PUTVAR(ACTPAR, ACTPAR2, VAR, MAXVAR, NVAR)

      ACTPAR = 'XSCALE'
      VALUE = B(1)
      WRITE (ACTPAR2, '(F20.10)') VALUE
      CALL PUTVAR(ACTPAR, ACTPAR2, VAR, MAXVAR, NVAR)

      ACTPAR = 'YSCALE'
      VALUE = C(1)
      WRITE (ACTPAR2, '(F20.10)') VALUE
      CALL PUTVAR(ACTPAR, ACTPAR2, VAR, MAXVAR, NVAR)

      ACTPAR = 'PXCENTER'
      VALUE = ( PXMIN + PXMAX ) * 0.5
      WRITE (ACTPAR2, '(F20.10)') VALUE
      CALL PUTVAR(ACTPAR, ACTPAR2, VAR, MAXVAR, NVAR)

      ACTPAR = 'PYCENTER'
      VALUE = ( PYMIN + PYMAX ) * 0.5
      WRITE (ACTPAR2, '(F20.10)') VALUE
      CALL PUTVAR(ACTPAR, ACTPAR2, VAR, MAXVAR, NVAR)

      RETURN
      END
bstore.f/       1553528659  5006  320   100644  967       `
      SUBROUTINE BSTORE (B, C, BSAVE, CSAVE, ACTION)

      DIMENSION B(6), C(6)
      DIMENSION BSAVE(6), CSAVE(6)
      CHARACTER*5 ACTION

      IF (ACTION .EQ. 'STORE') THEN
        BSAVE(1) = B(1)
        BSAVE(2) = B(2)
        BSAVE(3) = B(3)
        BSAVE(4) = B(4)
        BSAVE(5) = B(5)
        BSAVE(6) = B(6)
        CSAVE(1) = C(1)
        CSAVE(2) = C(2)
        CSAVE(3) = C(3)
        CSAVE(4) = C(4)
        CSAVE(5) = C(5)
        CSAVE(6) = C(6)
      ELSE IF (ACTION .EQ. 'RESTO') THEN
        B(1) = BSAVE(1)
        B(2) = BSAVE(2)
        B(3) = BSAVE(3)
        B(4) = BSAVE(4)
        B(5) = BSAVE(5)
        B(6) = BSAVE(6)
        C(1) = CSAVE(1)
        C(2) = CSAVE(2)
        C(3) = CSAVE(3)
        C(4) = CSAVE(4)
        C(5) = CSAVE(5)
        C(6) = CSAVE(6)
      ELSE
        WRITE (*,*) 'ACTION NOT KNOWN'
        WRITE (*,'(A,A5)') 'ACTION WAS ', ACTION
        STOP 'ERROR IN SUBR. BSTORE'
      ENDIF

      RETURN
      END

epsf.f/         1553528659  5006  320   100644  17217     `
      SUBROUTINE EPSF (TEXT, B, C, XUNITS, YUNITS, XLUNOFS, YLUNOFS, 
     >     DYCMLUN, PPXL, PPYL, VAR, MAXVAR, NVAR, DYSIZELUN, SIZELUN, 
     >           BBGR, IBGRCOL, BGRL, BGRR, BGRD, BGRU, BBXWIDTH, MODE,
     >      BGRLINE)
C******************************************************************
C***   CALLED FROM: KDPLOT, INLATEX, KD_LATEX
C***
C***  liest ein PS-file ein (FORTRAN-Kanal 25), 
C***  eliminiert ueberfluessige Zeilen und passt den epsf-teil
C***  mit 'translate' und 'scale' in das Gesamtbild ein.
C***  
C***  MODE = 'LEN' -> only length is measured (BBXWIDTH), no drawing action
C***  ACTDRIV = 'PSOWN' -> Include the EPS-File into the PS output
C***  ACTDRIV = 'X11'   -> draw BBox in X11-Window
C***
C* gs_init.f       gs_rotate.f     gs_scale.f      gs_transform.f
C* gs_restore.f    gs_save.f       gs_sheer.f      gs_translate.f
C*
C******************************************************************
      CHARACTER*(*) TEXT, BGRLINE
      CHARACTER*80 PFAD, KURZPFAD
C*** for the ticking-clock file the line length is drastically increased
ccc      CHARACTER*256 ZEILE
      CHARACTER*5000 ZEILE
      CHARACTER*20 PARSE, ACTPAR, ACTPAR2, ACTPAR3, ACTPAR4
      DIMENSION B(6), C(6)
      CHARACTER*1 CSCALE, CC, PPX, PPY, PPXL, PPYL
      LOGICAL BCOORD, BNEXTLUN, BLATEX, BBGR, BNOSHOW, BBFOUND, BHATCH
      LOGICAL BLATEXorig
      CHARACTER*(*) VAR(MAXVAR,2)
      CHARACTER MODE*(*), LMODE*7
      CHARACTER ACTPAR5*80

      CHARACTER NIMBUSTEST*100

C***  Conversion factor cm -> pt defined in PS_PLOTS
      COMMON / COMCMPT / CMPT

C***  Transformation coefficients
      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA

C***  Active plot driver
      COMMON / COMACT / ACTDRIV
      CHARACTER ACTDRIV*7

C***  Communication of Devive Nr. to Subr. CENSYMO
      COMMON / COMIDEV / IDEV

C***  Bounding Box
      COMMON / COMBBOX / BBXMIN, BBXMAX, BBYMIN, BBYMAX

C***  LAST COLOR
      COMMON / COMCOLOR / LASTCOLOR
C***  LAST PEN
      COMMON / COMPEN /LASTPEN, HALFLINW


C***  Bugfix for the NimbusFont problem
C***  Preparations:
C***  Line to test for the NimbusFont bug with pdfTeX
      NIMBUSTEST='%!PS-AdobeFont-1.0: NimbusRomNo9L'
      NTL = IDX(NIMBUSTEST)
      BLATEXorig = .FALSE.
C***  Identify if EPSF-call refers to internal LaTaX code
      CALL SARGC (TEXT, NPAR)
      DO I=4, NPAR
         CALL SARGV (TEXT, I, ACTPAR)
         IF (ACTPAR .EQ. 'LATEX') BLATEXorig=.TRUE.
      ENDDO

C***  Scan for 'showpage' in whole epsf file (as generated from dvips)
      BLATEX = .FALSE.

C***  NOSHOW makes the ps driver not to show the included file, but only
C***         a placeholder like the X11 driver does
      BNOSHOW = .FALSE.

C***  Test if BoundingBox has been found in the file
      BBFOUND = .FALSE. 

      BHATCH = .FALSE. 
      CALL SARGC (BGRLINE, NARG5)
      DO I=1, NARG5
         CALL SARGV (BGRLINE, I, ACTPAR5)
         IF (ACTPAR5 .EQ. 'HATCHED' .OR. ACTPAR5 .EQ. 'HTYPE') THEN
            BHATCH = .TRUE.
            EXIT
         ENDIF
      ENDDO
      
      IF (ACTDRIV .NE. 'PSOWN' .AND. ACTDRIV .NE. 'X11OWN') THEN
        WRITE (0,*) 'DRIVER UNKNOWN'
        WRITE (0,*) 'ACTDRIV=', ACTDRIV
      ENDIF

      IF (MODE(:3) .EQ. 'LEN') THEN
         LMODE = MODE
      ELSE
         LMODE = ACTDRIV
      ENDIF

C*** HeaderInfos in das wrplotfile.ps schreiben
      call sargv(text, 3, pfad)
      IF (LMODE .EQ. 'PSOWN') THEN
        write (3,'(a)') 'stroke'
        write (3,'(a,a)') '% -----> EPSF:',pfad(:IDX(pfad))
        write (3,'(a)') 'gsave'
C!!!        write (3,'(a)') 'initgraphics'
      ENDIF

C***  Preset Koordinates and scaling factors
        XPT = 0.
        YPT = 0.
        SCALE = 1.
        CSCALE = ' '
        BCOORD = .FALSE.
        BNEXTLUN = .FALSE.
        PPX = ' '
        PPY = ' '
        EPSROT = 0.

C***  Oeffnen des Include-files
cc      OPEN (25, FILE=PFAD, ERR=960, STATUS='OLD')
      CALL MY_OPEN (25, PFAD, IERR)
      IF (IERR .NE. 0) GOTO 960
C***  Begin loop: reading of the next line from the include-file
  200 READ (25,'(A)',ERR=950, END=500) ZEILE

      IF (BLATEX) THEN
         DO I = 1, IDX(ZEILE)-7
            IF (ZEILE(I:I+7) .EQ. 'showpage') THEN
               ZEILE = ZEILE(:I-1) // ZEILE(I+8:)
c               print *, '******* ersetzte Zeile: ***********'
c               print *, ZEILE
               BLATEX = .FALSE.
	       EXIT
	    ENDIF
	 END DO
      ENDIF
         CALL SARGV(ZEILE, 1, PARSE)
C        Werfe ueberfluessige Zeilen raus
         IF ( PARSE .EQ. 'showpage') GOTO 200
         IF ( PARSE .EQ. 'quit') GOTO 200
C*** skip line with setpagedevice! Used by me for paperformat SCREEN2
         IF (ZEILE(:39) .EQ. '<< /PageSize [864 648] >> setpagedevice') 
     >      GOTO 200      
C***  Behandlung der Bounding Box
      IF (PARSE(1:13) .EQ. '%%BoundingBox' .AND. .NOT. BBFOUND) THEN
        BBFOUND = .TRUE.
        CALL SARGV(ZEILE, 2, PARSE)
        READ (PARSE, '(F20.0)',ERR=980) BX1
        CALL SARGV(ZEILE, 3, PARSE)
        READ (PARSE, '(F20.0)',ERR=980) BY1
        CALL SARGV(ZEILE, 4, PARSE)
        READ (PARSE, '(F20.0)',ERR=980) BX2
        CALL SARGV(ZEILE, 5, PARSE)
        READ (PARSE, '(F20.0)',ERR=980) BY2
C***  decoding the KASDEF EPSF line ...
        CALL SARGC (TEXT, NPAR)

        DO I=4, NPAR
          CALL SARGV (TEXT, I, ACTPAR)

          IF (ACTPAR .EQ. 'COORD') THEN
            IF (BNEXTLUN) THEN
              WRITE (0,*) 'COORD DOES NOT MATCH WITH NEXTLUN'
              STOP 'ERROR IN EPSF'
            ENDIF
            BCOORD = .TRUE.

C***        Decode Coorddinates
            CALL DECXYUNITS  (TEXT, I+1, B, C, CX)
            CALL DECXYUNITS  (TEXT, I+2, B, C, CY)
            CALL DECFPNUMPRE (TEXT, I+3, CXCM, PPX)
            CALL DECFPNUMPRE (TEXT, I+4, CYCM, PPY)

          ELSE IF (ACTPAR .EQ. 'SCALE') THEN
            IF (CSCALE .NE. ' ') THEN
              WRITE (*,*) '*** NOW SCALING WITH "SCALE"'
              GOTO 930
            ENDIF
            CALL DECFPNUM    (TEXT, I+1, SCALE)
            CSCALE = 'F'
          ELSE IF (ACTPAR .EQ. 'EPSFXSIZE') THEN
            IF (CSCALE .NE. ' ') THEN
              WRITE (*,*) '*** NOW SCALING WITH "EPSFXSIZE"'
              GOTO 930
            ENDIF
            CALL SARGV (TEXT, I+1, ACTPAR)
            ID = IDX(ACTPAR)
            IF (ACTPAR(ID:ID) .NE. 'U') THEN
              READ (ACTPAR, '(F20.0)', ERR=970) EPSFX
              SCALE = EPSFX / ((BX2 - BX1) / CMPT)
            ELSE
              ACTPAR = ACTPAR( :ID-1)
              READ (ACTPAR, '(F20.0)',ERR=970) EPSFX
              SCALE = EPSFX * B(1) / ((BX2 - BX1) / CMPT)
            ENDIF
            CSCALE = 'X'
          ELSE IF (ACTPAR .EQ. 'EPSFYSIZE') THEN
            IF (CSCALE .NE. ' ') THEN
              WRITE (*,*) '*** NOW SCALING WITH "EPSFYSIZE"'
              GOTO 930
            ENDIF
            CALL SARGV (TEXT, I+1, ACTPAR)
            ID = IDX(ACTPAR)
            IF (ACTPAR(ID:ID) .NE. 'U') THEN
              READ (ACTPAR, '(F20.0)',ERR=970) EPSFY
              SCALE = EPSFY / ((BY2 - BY1) / CMPT)
            ELSE
              ACTPAR = ACTPAR( :ID-1)
              READ (ACTPAR, '(F20.0)',ERR=970) EPSFY
              SCALE = EPSFY * C(1) / ((BY2 - BY1) / CMPT)
            ENDIF
            CSCALE = 'Y'
          ELSE IF (ACTPAR .EQ. 'NEXTLUN') THEN
            IF (BCOORD) THEN
              WRITE (0,*) 'NEXTLUN DOES NOT MATCH WITH COORD'
              STOP 'ERROR IN EPSF'
            ENDIF
            BNEXTLUN = .TRUE.
          ELSE IF (ACTPAR .EQ. 'ROTATE') THEN
            CALL SARGV (TEXT, I+1, ACTPAR)
            READ (ACTPAR, '(F20.0)',ERR=970) EPSROT
          ELSE IF (ACTPAR .EQ. 'LATEX') THEN
            BLATEX = .TRUE.
          ELSE IF (ACTPAR .EQ. 'NOSHOW') THEN
            BNOSHOW = .TRUE.
          ENDIF
        ENDDO

C***    Special for INLATEX: reduce BBOX till the baseline
        IF (PPX .EQ. 'o') THEN 
           BY1      = BY1 + 7
           BX1ORIG  = BX1
           BY1ORIG  = BY1
           BBXWIDTH = BX2 - BX1
	ENDIF

C***  Rotate the Bounding Box
        IF (EPSROT .NE. 0.) THEN
            CALL TURN(BX11, BY11, BX1, BY1, EPSROT)
            CALL TURN(BX12, BY12, BX1, BY2, EPSROT)
            CALL TURN(BX22, BY22, BX2, BY2, EPSROT)
            CALL TURN(BX21, BY21, BX2, BY1, EPSROT)
            BX1ORIG = BX11
	    BY1ORIG = BY11
            BX1 = AMIN1 (BX11, BX12, BX21, BX22)
            BX2 = AMAX1 (BX11, BX12, BX21, BX22)
            BY1 = AMIN1 (BY11, BY12, BY21, BY22)
            BY2 = AMAX1 (BY11, BY12, BY21, BY22)
        ENDIF

C***    Lower edge = upper edge - height of epsf
        YLUNOFS = YLUNOFS - (BY2 - BY1) * SCALE / CMPT

C***    SPECIAL BRANCH FOR EPSF-USE IN NEXTLUN-CONTEXT
        IF (BNEXTLUN) THEN
	  PPY = 'U'
          CX = XUNITS
          CY = YUNITS
          CXCM = XLUNOFS
          CYCM = YLUNOFS 
          PPX = PPXL
          PPY = PPYL
        ENDIF

C***  Add line spacing below figure --> NEXTLUN position
        IF (DYSIZELUN .GT. 0) 
     >       YLUNOFS = YLUNOFS - (DYSIZELUN - 1.) * SIZELUN
        IF (DYCMLUN .GT. 0) YLUNOFS = YLUNOFS - DYCMLUN + SIZELUN 

C***  EXECUTE CENTERING IN X-DIRECTION
        IF (PPX .EQ. 'M') THEN
          CXCM2 = -(BX2 - BX1) * SCALE / CMPT / 2.
        ELSE IF (PPX .EQ. 'R') THEN
          CXCM2 = -(BX2 - BX1) * SCALE / CMPT
        ELSE IF (PPX .EQ. 'o') THEN
	  CXCM2 = (BX1 - BX1ORIG) * SCALE / CMPT
        ELSE
          CXCM2 = 0.
        ENDIF

C***  DO CENTERING IN Y-DIRECTION
        IF (PPY .EQ. 'M') THEN
          CYCM2 = -(BY2 - BY1) * SCALE / CMPT / 2.
        ELSE IF (PPY .EQ. 'U') THEN
          CYCM2 = -(BY2 - BY1) * SCALE / CMPT
        ELSE IF (PPY .EQ. 'o') THEN
	  CYCM2 = (BY1 - BY1ORIG) * SCALE / CMPT
        ELSE
          CYCM2 = 0.
        ENDIF

C!!!  NOTE: THIS FORMULA IS EMPIRICALLY FOUND AND NOT FULLY UNDERSTOOD
C!!!  DO NOT TOUCH!!!
        XPT = (((CX - B(2)) * B(1) + CXCM + CXCM2) + 
     >        XOFFSET/FORMATFA) * CMPT 
        YPT = (((CY - C(2)) * C(1) + CYCM + CYCM2) + 
     >        YOFFSET/FORMATFA) * CMPT

        XPTR = (XPT - BX1 * SCALE) * FORMATFA
        YPTR = (YPT - BY1 * SCALE) * FORMATFA
        SCALER = SCALE * FORMATFA

C***  POSITION OF THE EPS-FRAME IN CM
        XCM = ((CX - B(2)) * B(1) + CXCM)
        YCM = ((CY - C(2)) * C(1) + CYCM)
        XCMUL = XCM + CXCM2
	YCMUL = YCM + CYCM2
        DX = (BX2 - BX1) * SCALE / CMPT
        DY = (BY2 - BY1) * SCALE / CMPT
        XCMOR = XCMUL + DX
        YCMOR = YCMUL + DY
        XM = (XCMUL + XCMOR ) * 0.5
        YM = (YCMUL + YCMOR ) * 0.5

        BBXWIDTH = BBXWIDTH * SCALE / CMPT 

C***  Length measurement done - do not spoil the BBox, but exit!
      IF (LMODE(:3) .EQ. 'LEN') GOTO 600

C***  SET VARIABLES EPS_X1, EPS_XM, EPS_Y1, EPS_Y1, EPS_YM, EPS_Y2
        WRITE (ACTPAR2, '(F20.10)') XCMUL / B(1) + B(2)
        CALL PUTVAR ('EPS_X1', ACTPAR2, VAR, MAXVAR, NVAR)
        WRITE (ACTPAR2, '(F20.10)') XM / B(1) + B(2)
        CALL PUTVAR ('EPS_XM', ACTPAR2, VAR, MAXVAR, NVAR)
        WRITE (ACTPAR2, '(F20.10)') XCMOR / B(1) + B(2)
        CALL PUTVAR ('EPS_X2', ACTPAR2, VAR, MAXVAR, NVAR)
        WRITE (ACTPAR2, '(F20.10)') YCMUL / C(1) + C(2)
        CALL PUTVAR ('EPS_Y1', ACTPAR2, VAR, MAXVAR, NVAR)
        WRITE (ACTPAR2, '(F20.10)') YM / C(1) + C(2)
        CALL PUTVAR ('EPS_YM', ACTPAR2, VAR, MAXVAR, NVAR)
        WRITE (ACTPAR2, '(F20.10)') YCMOR / C(1) + C(2)
        CALL PUTVAR ('EPS_Y2', ACTPAR2, VAR, MAXVAR, NVAR)

        WRITE (ACTPAR2, '(F20.10)') XCMUL
        CALL PUTVAR ('EPS_X1CM', ACTPAR2, VAR, MAXVAR, NVAR)
        WRITE (ACTPAR2, '(F20.10)') XM
        CALL PUTVAR ('EPS_XMCM', ACTPAR2, VAR, MAXVAR, NVAR)
        WRITE (ACTPAR2, '(F20.10)') XCMOR
        CALL PUTVAR ('EPS_X2CM', ACTPAR2, VAR, MAXVAR, NVAR)
        WRITE (ACTPAR2, '(F20.10)') YCMUL
        CALL PUTVAR ('EPS_Y1CM', ACTPAR2, VAR, MAXVAR, NVAR)
        WRITE (ACTPAR2, '(F20.10)') YM
        CALL PUTVAR ('EPS_YMCM', ACTPAR2, VAR, MAXVAR, NVAR)
        WRITE (ACTPAR2, '(F20.10)') YCMOR
        CALL PUTVAR ('EPS_Y2CM', ACTPAR2, VAR, MAXVAR, NVAR)

C***    Provide a variable with the NEXTLUN position
        WRITE (ACTPAR2, '(F20.10)') YLUNOFS
        CALL FLUSHLEFT (ACTPAR2)
        CALL PUTVAR ('NEXT_YOFS', ACTPAR2, VAR, MAXVAR, NVAR)
 


C***  HIER DIE BOUNDINGBOX
        BBXUL = XPTR + BX1 * SCALER
        BBXOR = XPTR + BX2 * SCALER
        BBYUL = YPTR + BY1 * SCALER
        BBYOR = YPTR + BY2 * SCALER

        BBXMIN = AMIN1 (BBXMIN, BBXUL)
        BBXMAX = AMAX1 (BBXMAX, BBXOR)
        BBYMIN = AMIN1 (BBYMIN, BBYUL)
        BBYMAX = AMAX1 (BBYMAX, BBYOR)

        IF (LMODE .EQ. 'PSOWN') THEN
          IF (BBGR) THEN
	  X1CM = XM - 0.5 * DX - BGRL
          X2CM = XM + 0.5 * DX + BGRR
          Y1CM = YM - 0.5 * DY - BGRD
          Y2CM = YM + 0.5 * DY + BGRU
C***      open box:
          LC2 = LASTCOLOR
          CALL COLOR ('DATA', 'DUMMY', ABS(IBGRCOL), IDEV)
          CALL RECTA (X1CM, X2CM, Y1CM, Y2CM)
C***      Filling Command 
          IF (IBGRCOL .GE. 0 .AND. .NOT. BHATCH) THEN
             CALL GFILL
          ELSEIF (BHATCH) THEN
             CALL HFILL(BGRLINE)
          ENDIF
          CALL COLOR ('DATA', 'DUMMY', LC2, IDEV)

	  ENDIF
          WRITE (3,'(2(1X,F12.2),A)') XPTR, YPTR, ' translate'
          WRITE (3,'(F12.8,1X,F12.8,A)')  SCALER, SCALER, ' scale'
          WRITE (3,'(F12.8,A)')  EPSROT, ' rotate'
        ELSE IF (LMODE .EQ. 'X11OWN') THEN
C***  X11 Branch: Plot black FILLED RECTANGLE, write filename inside
          X1CM = XM - 0.5 * DX
          X2CM = XM + 0.5 * DX
          Y1CM = YM - 0.5 * DY
          Y2CM = YM + 0.5 * DY
          ICOLORSAVE = LASTCOLOR
          IPENSAVE   = LASTPEN
	  IDEV = 5
          ICOLOR=1
          CALL COLOR ('DATA', 'DUMMY', ICOLOR, IDEV)
          CALL RECTA (X1CM, X2CM, Y1CM, Y2CM)
          CALL GFILL
          ICOLOR=0
          CALL COLOR ('DATA', 'DUMMY', ICOLOR, IDEV)

C***      Estimate suitable scale for the string with filename
          IDXPFAD = IDX(PFAD)
C***      Minimum Textsize (left end will be truncated!)
          TEXTSIZE = 0.3
          DO IPOS = 1, IDXPFAD
             KURZPFAD = PFAD(IPOS:)
	     IDXKURZPFAD = IDXPFAD+1-IPOS
	     CALL MYTLEN (TEXTLEN, 1., KURZPFAD, IDXKURZPFAD)
             IF (TEXTLEN  .LE. (3. * DX)) EXIT
	  END DO
          TEXTSIZE = 0.9 * DX / TEXTLEN

	  XBEG = XCMOR - 0.05 * DX - TEXTLEN * TEXTSIZE
	  YBEG = YM - 0.5 * TEXTSIZE
          CALL X_NEWPEN (3)
          CALL MYSYMBL (XBEG, YBEG, TEXTSIZE, KURZPFAD, 0.)
          CALL COLOR ('DATA', 'DUMMY', ICOLORSAVE, IDEV)
          CALL X_NEWPEN (IPENSAVE)
        ENDIF

C***  For the X11 branch or LEN-Mode, the file can be closed now!
        IF (LMODE .EQ. 'PSOWN' .AND. .NOT. BNOSHOW) THEN
           GOTO 200
        ELSE
           GOTO 600
	ENDIF
      ENDIF
C***  Hier erst Ende des IF ... BoundingBox      
      
      IF ( ZEILE(:2) .EQ. '%%') GOTO 200
  
      IF (LMODE .EQ. 'PSOWN') THEN
C***  Attempt to fix the bug with the NimbusFont in pdflatex     
C***  added by wrh 30 Dec 2014
        IF (.NOT. BLATEXorig .OR. ZEILE(:NTL) .NE. NIMBUSTEST) THEN
C***    normal case: line is just copied
           WRITE (3,'(A)') ZEILE( :IDX(ZEILE))
        ELSE
C***    For internally created LaTeX files, the blocks defining the
C***    Nimbus font are not copied
	   PRINT *, '============================================'
	   PRINT *, 'WARNING: Nimbus font removed from LaTaX code'
	   PRINT *, '============================================'
400        READ (25,'(A)',ERR=950, END=500) ZEILE
           IF (ZEILE .NE. 'cleartomark') GOTO 400
        ENDIF 
      ENDIF
      GOTO 200

C*** das FileEnde des einzukapselnden Files wurde erkannt
500   CONTINUE
      IF (LMODE .EQ. 'PSOWN') THEN
        WRITE (3,'(A)') 'grestore'
        WRITE (3,'(A)') '% -------> EPSF:Ende'
      ENDIF


  600 CONTINUE
      IF (BNOSHOW) WRITE (3,'(A)') 'grestore'
      CLOSE(25)
      IF (.NOT. BBFOUND) GOTO 940
      RETURN

C***  ERROR STOPS *************************************

930   CONTINUE
      IF (CSCALE .EQ. 'F') 
     >   WRITE (*,*) '*** PREVIOUSLY SCALED WITH "SCALE"' 
      IF (CSCALE .EQ. 'X') 
     >   WRITE (*,*) '*** PREVIOUSLY SCALED WITH "EPSFXSIZE"' 
      IF (CSCALE .EQ. 'Y') 
     >   WRITE (*,*) '*** PREVIOUSLY SCALED WITH "EPSFYSIZE"' 
      WRITE (*,*) '*** TWO SCALINGS ARE NOT ALLOWED'
      GOTO 990

940   CONTINUE
      WRITE (*,'(//,A)') 'No BoundingBox found in EPSF file'
      WRITE (*,'(A)') PFAD(:IDX(PFAD)) // 
     >      ' is possibly not a PostScript file'
      GOTO 990
      
950   CONTINUE
      WRITE (*,'(//,A)') 'Read error on file: ' // PFAD(:IDX(PFAD))
      GOTO 990
      
960   CONTINUE
      WRITE (*,'(//,A)') 'Cannot open file: ' // PFAD(:IDX(PFAD))
      GOTO 990
      
970   WRITE (*,'(//,A)') '*** Error when decoding '
     >      //ACTPAR(:IDX(ACTPAR))// 
     >      ' as floating-point number'
      GOTO 990

980   WRITE (*,'(//,A)') '*** Error when reading BoundingBox'
      WRITE (*,'(A)') '*** from included EPSF file'
      GOTO 990
      
990   WRITE (*,*) 'The error occured in the following line:'
      WRITE (*,*) TEXT(:IDX(TEXT))
      STOP 'ERROR in SUBROUTINE EPSF'

      END

exprvar.f/      1553528659  5006  320   100644  4030      `
      SUBROUTINE EXPRVAR (ACTPAR2, ACTPAR3, ACTPAR4, ACTPAR5, 
     >                    VAR, MAXVAR, NVAR)
C***************************************************
C***  STORING OF VARIABLES:
C***  ACTPAR IS INPUT
C***************************************************

      CHARACTER*(*) VAR(MAXVAR,2)
      CHARACTER*(*) ACTPAR2, ACTPAR3, ACTPAR4, ACTPAR5
      CHARACTER*3 CIVAR

c      write (*,'(5(A,1X))')
c     >  'exprvar: ', actpar2(:idx(actpar2)), actpar3(:idx(actpar3)), 
c     >               actpar4(:idx(actpar4)), actpar5(:idx(actpar5))


C***    CALCULATE INDEX-NUMBER OF VARIABLE LEFT FROM THE = SIGN
        I1 = IVAR (ACTPAR2, VAR, MAXVAR, NVAR, CIVAR)          
C***    DECODE VARIABLES RIGHT FROM THE = SIGN
        CALL EXPANDVAR (ACTPAR3, VAR, MAXVAR, NVAR)
        CALL EXPANDVAR (ACTPAR5, VAR, MAXVAR, NVAR)
        IF (ACTPAR4 .EQ. '//') THEN
          VAR(I1,2) = ACTPAR3( :IDX(ACTPAR3)) // ACTPAR5( :IDX(ACTPAR5))
        ELSE IF (ACTPAR3 .EQ. 'LOG' .OR. ACTPAR3 .EQ. 'INT' .OR. 
     >           ACTPAR3 .EQ. '10**' .OR. ACTPAR3 .EQ. 'DEX' .OR. 
     >           ACTPAR3 .EQ. 'SIN'  .OR. ACTPAR3 .EQ. 'ASIN' .OR. 
     >           ACTPAR3 .EQ. 'COS'  .OR. ACTPAR3 .EQ. 'ACOS' .OR. 
     >           ACTPAR3 .EQ. 'TAN'  .OR. ACTPAR3 .EQ. 'ATAN' 
     >          ) THEN
          CALL DECVAR (ACTPAR4, VAR, MAXVAR, NVAR) 
          IF (ACTPAR3 .EQ. 'LOG') THEN            
            CALL READPAR (ACTPAR4, B, C, EX1, VAR, MAXVAR, NVAR)
            EX = ALOG10(EX1)
            WRITE (VAR(I1,2), '(F20.8)') EX
          ELSE IF (ACTPAR3 .EQ. 'INT') THEN
            CALL READPAR (ACTPAR4, B, C, EX1, VAR, MAXVAR, NVAR)
            WRITE (VAR(I1,2), '(I20)') INT(EX1)
          ELSE IF (ACTPAR3 .EQ. '10**') THEN
            CALL READPAR (ACTPAR4, B, C, EX1, VAR, MAXVAR, NVAR)
            EX = 10.**(EX1)
            WRITE (VAR(I1,2), '(F20.8)') EX
          ELSE IF (ACTPAR3 .EQ. 'SIN') THEN
            CALL READPAR (ACTPAR4, B, C, EX1, VAR, MAXVAR, NVAR)
            EX = SIN(EX1)
            WRITE (VAR(I1,2), '(F20.8)') EX
          ELSE IF (ACTPAR3 .EQ. 'ASIN') THEN
            CALL READPAR (ACTPAR4, B, C, EX1, VAR, MAXVAR, NVAR)
            EX = ASIN(EX1)
            WRITE (VAR(I1,2), '(F20.8)') EX
          ELSE IF (ACTPAR3 .EQ. 'COS') THEN
            CALL READPAR (ACTPAR4, B, C, EX1, VAR, MAXVAR, NVAR)
            EX = COS(EX1)
            WRITE (VAR(I1,2), '(F20.8)') EX
          ELSE IF (ACTPAR3 .EQ. 'ACOS') THEN
            CALL READPAR (ACTPAR4, B, C, EX1, VAR, MAXVAR, NVAR)
            EX = ACOS(EX1)
            WRITE (VAR(I1,2), '(F20.8)') EX
          ELSE IF (ACTPAR3 .EQ. 'TAN') THEN
            CALL READPAR (ACTPAR4, B, C, EX1, VAR, MAXVAR, NVAR)
            EX = TAN(EX1)
            WRITE (VAR(I1,2), '(F20.8)') EX
          ELSE IF (ACTPAR3 .EQ. 'ATAN') THEN
            CALL READPAR (ACTPAR4, B, C, EX1, VAR, MAXVAR, NVAR)
            EX = ATAN(EX1)
            WRITE (VAR(I1,2), '(F20.8)') EX
          ENDIF
        ELSE IF (ACTPAR4 .EQ. '+' .OR.
     >           ACTPAR4 .EQ. '-' .OR.   
     >           ACTPAR4 .EQ. '*' .OR.   
     >           ACTPAR4 .EQ. '/') THEN
          CALL READPAR (ACTPAR3, B, C, EX1, VAR, MAXVAR, NVAR)
          CALL READPAR (ACTPAR5, B, C, EX2, VAR, MAXVAR, NVAR)
          IF (ACTPAR4 .EQ. '+') THEN
            EX = EX1 + EX2
          ELSE IF (ACTPAR4 .EQ. '-') THEN
            EX = EX1 - EX2
          ELSE IF (ACTPAR4 .EQ. '*') THEN
            EX = EX1 * EX2
          ELSE IF (ACTPAR4 .EQ. '/') THEN
            EX = EX1 / EX2
          ENDIF 
          IF (EX .EQ. INT(EX)) THEN
            WRITE (VAR(I1,2), '(I20)') INT(EX)
          ELSE
            WRITE (VAR(I1,2), '(F20.8)') EX
          ENDIF
   35     CONTINUE
          IF (VAR(I1,2)(1:1) .EQ. ' ') THEN
            VAR(I1,2) = VAR(I1,2)(2: )
            GOTO 35
          ENDIF

        ELSE
          WRITE (*,*) 'Expression ',ACTPAR4( :IDX(ACTPAR4)),
     >                ' can not be interpretated'
          STOP 'EXPRVAR'
        ENDIF

      RETURN
      END
boolvar.f/      1553528659  5006  320   100644  1716      `
      SUBROUTINE BOOLVAR(BOOL, ACTPAR2, ACTPAR3, ACTPAR4, 
     >                   VAR, MAXVAR, NVAR, IERR)

C****************************************************************
C***  CALCULATES LOGICAL EXPRESSION:
C***  BOOL = ACTPAR2 .operand. ACTPAR4
C***  the operand is given in ACTPAR3
C***  .EQ. and .NE.: comparison of strings 
C***  other operators: Operands are extracted as real numbers
C****************************************************************

      CHARACTER*(*) ACTPAR2, ACTPAR3, ACTPAR4
      CHARACTER*(*) VAR(MAXVAR,2)
      LOGICAL BOOL
      IERR = 0

      CALL DECVAR (ACTPAR2, VAR, MAXVAR, NVAR)
      CALL DECVAR (ACTPAR3, VAR, MAXVAR, NVAR)
      CALL DECVAR (ACTPAR4, VAR, MAXVAR, NVAR)

      IF (ACTPAR3 .EQ. '.EQ.' .OR. ACTPAR3 .EQ. '.NE.') THEN
        IF (ACTPAR3 .EQ. '.EQ.') THEN
          BOOL = (ACTPAR2 .EQ. ACTPAR4)
        ELSE IF (ACTPAR3 .EQ. '.NE.') THEN
          BOOL = (ACTPAR2 .NE. ACTPAR4)
        ENDIF
      ELSE IF (ACTPAR3 .EQ. '.GT.' .OR. ACTPAR3 .EQ. '.GE.' .OR. 
     >         ACTPAR3 .EQ. '.LT.' .OR. ACTPAR3 .EQ. '.LE.') THEN
        CALL READPAR (ACTPAR2, B, C, EX1, VAR, MAXVAR, NVAR)
        CALL READPAR (ACTPAR4, B, C, EX2, VAR, MAXVAR, NVAR)
        IF (ACTPAR3 .EQ. '.GT.') THEN
          BOOL = (EX1 .GT. EX2)
        ELSE IF (ACTPAR3 .EQ. '.GE.') THEN
          BOOL = (EX1 .GE. EX2)
        ELSE IF (ACTPAR3 .EQ. '.LT.') THEN
          BOOL = (EX1 .LT. EX2)
        ELSE IF (ACTPAR3 .EQ. '.LE.') THEN
          BOOL = (EX1 .LE. EX2)
        ENDIF
      ELSE
        WRITE (*,*) 
     >      '*** Subr. BOOLVAR: UNRECOGNIZED LOGICAL OPERATOR: ', 
     >               ACTPAR3( :IDX(ACTPAR3))
        IERR = 1
      ENDIF

      RETURN
      END
exinst.f/       1658432719  5006  320   100600  22186     `
      SUBROUTINE EXINST (INSTLINE, INSTMAX, NINST, IINST, 
     >                   CPREFIX, IERR, VAR, MAXVAR, NVAR)
C******************************************************************
C***  EXECUTE THE INSTRUCTIONS
C***  CALLED FROM KDPLOT, KDSET and EXCMD
C******************************************************************

      CHARACTER*(*) VAR(MAXVAR,2)
      CHARACTER*132 INSTLINE(INSTMAX), LINE1, LINE2
      PARAMETER (KDMAXLEN = 400)
      CHARACTER LINE*(KDMAXLEN), LINE_UNEXPANDED*(KDMAXLEN), CTIME*8
      CHARACTER*8 CPREFIX
      CHARACTER*132 ACTPAR, ACTPAR2, ACTPAR3, ACTPAR4, ACTPAR5, VARNAME
      CHARACTER*4 SHORTVAR
      CHARACTER*3 CIVAR
      CHARACTER*1 DOLLAR
      LOGICAL BOOL, CALC_DEBUG, CHRINSTR
      SAVE

C***  MAXIMUM OF NESTED DO-LOOPS
      PARAMETER (MAXLOOP = 20)
C***  LOOP PARAMETERS ARE STORED FOR EACH LOOP:
C***  (1) 'DO'  (i.e. unused!)
C***  (2) label of loop end
C***  (3) name of loopindex-variable
C***  (4) loopindex start
C***  (5) loopindex end
C***  (6) increment
      CHARACTER*20 CLOOP(6,MAXLOOP)
C***  Line index
C***  (1) of DO statement
C***  (2) of ENDDO label
      DIMENSION INDLOOP(2,MAXLOOP)

C***  MAXIMUM of nested IFs
      PARAMETER (MAXIF = 20)
C***  Control whether IF (or ELSEIF) has already been .true.
      LOGICAL BIF(MAXIF)

C***  NO NESTED LOOP AT THE BEGINNING
      DATA NLOOP / 0 /

C***  NO NESTED IFs AT THE BEGINNING
      DATA IIF / 0 /

C***  Debug option for arithmetic expressions (KASDEF CALC)
      DATA CALC_DEBUG  /.FALSE./

      DOLLAR    = CHAR(36)

      IERR = 0

      LINE = INSTLINE(IINST)

C***  Append possible continuation lines KASDEF >
      NCONTLINES = 0
    1 IF (IINST+NCONTLINES .LT. INSTMAX) THEN
         CALL SARGREST (INSTLINE(IINST+1), NPAR, 2, IFIRST, ILAST)
         IF (NPAR .GT. 1 .AND. 
     >      INSTLINE(IINST+1+NCONTLINES)(IFIRST:IFIRST) .EQ. '>') THEN
            NCONTLINES = NCONTLINES + 1
            LINE1 = INSTLINE(IINST+NCONTLINES)(IFIRST+1:ILAST)
            LAST = IDX(LINE)
            IF (LAST+IDX(LINE1)-1 .GT. KDMAXLEN) GOTO 95
            LINE(LAST+1:) = LINE1
            GOTO 1
         ENDIF
      ENDIF

C***  EXPAND ALL VARIABLES
      LINE_UNEXPANDED = LINE
      CALL EXPANDVAR (LINE, VAR, MAXVAR, NVAR)

C***  Extract second parameter
      CALL SARGV(LINE, 2, ACTPAR)

      IF (ACTPAR .EQ. 'VAR-LIST') THEN
C***                   --------
        WRITE (*,*) '>'
        WRITE (*,*) '>'
        WRITE (*,*) 'VARIABLEN LISTE'
        WRITE (*,*) 'ZAHL DER VARIABLEN: ',NVAR
        DO 2 I=1, NVAR
          WRITE (*,*) VAR(I,1)( :IDX(VAR(I,1))), '  ', 
     >                VAR(I,2)( :IDX(VAR(I,2)))
    2   CONTINUE
        WRITE (*,*) 'VARIABLEN LISTE ENDE'
        WRITE (*,*) '>'
        WRITE (*,*) '>'

      ELSE IF (ACTPAR .EQ. 'VAR') THEN
C***                        ---
        CALL SARGV(LINE, 3, ACTPAR)
        CALL VARLEGAL (LINE, ACTPAR, 'VAR')
        CALL SARGV(LINE_UNEXPANDED, 4, ACTPAR2)
        CALL EXPANDVAR (ACTPAR2, VAR, MAXVAR, NVAR)
        CALL PUTVAR(ACTPAR, ACTPAR2, VAR, MAXVAR, NVAR)

      ELSE IF (ACTPAR .EQ. 'FITSVAR') THEN
C***                        -------
        CALL FITSVAR (LINE, VAR, MAXVAR, NVAR)

      ELSE IF (ACTPAR .EQ. 'CALC') THEN
C***                        ----
        CALL KD_CALC (LINE, B, C, VAR, MAXVAR, NVAR, CALC_DEBUG)

C***  KASDEF CALC_DEBUG
C----------------------
       ELSE IF (ACTPAR .EQ. 'CALC_DEBUG') THEN
            CALL SARGC (LINE, N)
         IF (N .LE. 2) THEN
            CALC_DEBUG = .TRUE. 
         ELSE
            CALL SARGV (LINE, 3, ACTPAR)
            IF (ACTPAR .EQ. 'ON') THEN 
               CALC_DEBUG = .TRUE.
            ELSE IF (ACTPAR .EQ. 'OFF') THEN 
               CALC_DEBUG = .FALSE.
            ELSE
               GOTO 983
            ENDIF
         ENDIF

      ELSEIF (ACTPAR .EQ. 'IF') THEN
C***                       --
         IIF = IIF + 1
         IF (IIF .GT. MAXIF) GOTO 998
C***     None of the (ELSE)IFs has been .true. so far
         BIF(IIF) = .FALSE.
         CALL SARGV(LINE_UNEXPANDED, 3, ACTPAR2)
         CALL SARGV(LINE_UNEXPANDED, 4, ACTPAR3)
         CALL SARGV(LINE_UNEXPANDED, 5, ACTPAR4)
C***     Variables cannot be expanded earlier since strings may break 
C****    -> Unless they appear to be indexed variables! in this case,
C***        read args 3 and 5 once more (bugfix by Martin Steinke Jul2015)
         IF (CHRINSTR('[',ACTPAR2).AND.CHRINSTR(']',ACTPAR2)
     >      .AND. CHRINSTR('$',ACTPAR2).AND.
     >      .NOT.CHRINSTR('"',ACTPAR2)) THEN
           CALL SARGV(LINE,3,ACTPAR2)
         ENDIF
         IF (CHRINSTR('[',ACTPAR4).AND.CHRINSTR(']',ACTPAR4)
     >      .AND. CHRINSTR('$',ACTPAR4) .AND.
     >      .NOT. CHRINSTR('"',ACTPAR4)) THEN
           CALL SARGV(LINE,5,ACTPAR4)
         ENDIF
         CALL DECVAR (ACTPAR2, VAR, MAXVAR, NVAR) 
         CALL DECVAR (ACTPAR4, VAR, MAXVAR, NVAR) 
C***     Evaluate logical expression   
         CALL BOOLVAR(BOOL, ACTPAR2, ACTPAR3, ACTPAR4, 
     >                VAR, MAXVAR, NVAR, IERR1)
         IF (IERR1 .GT. 0) GOTO 970
         BIF(IIF) = BOOL

         IF (.NOT. BOOL) THEN
C***     SKIP TO THE NEXT ELSE or ELSEIF or ENDIF of the same nesting level
            NESTL = 0
   15       IINST = IINST + 1
            IF (IINST .GT. NINST) GOTO 995
            CALL SARGV (INSTLINE(IINST), 2, ACTPAR)
            IF (ACTPAR .EQ. 'IF') NESTL = NESTL + 1
            IF (NESTL .EQ. 0 .AND. 
     >         (ACTPAR .EQ. 'ENDIF' .OR. ACTPAR .EQ. 'ELSE' .OR.  
     >          ACTPAR .EQ. 'ELSEIF')) THEN
	       IINST = IINST-1
            ELSEIF (ACTPAR .EQ. 'ENDIF') THEN 
	       NESTL = NESTL - 1
	       GOTO 15
            ELSE
               GOTO 15
            ENDIF
         ENDIF

      ELSEIF (ACTPAR .EQ. 'ELSEIF') THEN
C***                       ------
         IF (BIF(IIF)) THEN
C***  There was already a .true. (ELSE)IF --> skip to next ENDIF
C***     of same nesting level
            NESTL = 0
   18       IINST = IINST + 1
            IF (IINST .GT. NINST) GOTO 995
            CALL SARGV (INSTLINE(IINST), 2, ACTPAR)
            IF (ACTPAR .EQ. 'IF') NESTL = NESTL + 1
            IF (NESTL .EQ. 0 .AND. ACTPAR .EQ. 'ENDIF') THEN
	       IINST = IINST-1
            ELSEIF (ACTPAR .EQ. 'ENDIF') THEN
               NESTL = NESTL - 1
               GOTO 18
            ELSE
               GOTO 18
            ENDIF
         ELSE
C***     Test this ELSEIF
            CALL SARGV(LINE_UNEXPANDED, 3, ACTPAR2)
            CALL SARGV(LINE_UNEXPANDED, 4, ACTPAR3)
            CALL SARGV(LINE_UNEXPANDED, 5, ACTPAR4)
C***     Variables cannot be expanded earlier since strings may break 
C****    -> Unless they appear to be indexed variables! in this case,
C***        read args 3 and 5 once more (bugfix by Martin Steinke Jul2015)
         IF (CHRINSTR('[',ACTPAR2).AND.CHRINSTR(']',ACTPAR2)
     >      .AND. CHRINSTR('$',ACTPAR2).AND.
     >      .NOT.CHRINSTR('"',ACTPAR2)) THEN
           CALL SARGV(LINE,3,ACTPAR2)
         ENDIF
         IF (CHRINSTR('[',ACTPAR4).AND.CHRINSTR(']',ACTPAR4)
     >      .AND. CHRINSTR('$',ACTPAR4) .AND.
     >      .NOT. CHRINSTR('"',ACTPAR4)) THEN
           CALL SARGV(LINE,5,ACTPAR4)
         ENDIF
            CALL DECVAR (ACTPAR2, VAR, MAXVAR, NVAR) 
            CALL DECVAR (ACTPAR4, VAR, MAXVAR, NVAR) 
C***     Evaluate logical expression   
            CALL BOOLVAR(BOOL, ACTPAR2, ACTPAR3, ACTPAR4, 
     >                VAR, MAXVAR, NVAR, IERR1)
            IF (IERR1 .GT. 0) GOTO 970
            BIF(IIF) = BOOL

            IF (.NOT. BOOL) THEN
C***           SKIP TO THE NEXT ELSE or ELSEIF or ENDIF of the same 
C***              nesting level
               NESTL = 0
   17          IINST = IINST + 1
               IF (IINST .GT. NINST) GOTO 995
               CALL SARGV (INSTLINE(IINST), 2, ACTPAR)
               IF (ACTPAR .EQ. 'IF') NESTL = NESTL + 1
               IF (NESTL .EQ. 0 .AND. 
     >            (ACTPAR .EQ. 'ENDIF' .OR. ACTPAR .EQ. 'ELSE' .OR.  
     >             ACTPAR .EQ. 'ELSEIF')) THEN
	          IINST = IINST-1
               ELSEIF (ACTPAR .EQ. 'ENDIF') THEN
	          NESTL = NESTL - 1
		  GOTO 17
               ELSE
                  GOTO 17
               ENDIF
	    ENDIF
         ENDIF

      ELSEIF (ACTPAR .EQ. 'ELSE') THEN
C***                       ----
         IF (BIF(IIF)) THEN
C***        SKIP TO THE NEXT ENDIF of same nesting level
            NESTL = 0
   16       IINST = IINST + 1
            IF (IINST .GT. NINST) GOTO 995
            CALL SARGV (INSTLINE(IINST), 2, ACTPAR)
            IF (ACTPAR .EQ. 'IF') NESTL = NESTL + 1
            IF (NESTL .EQ. 0 .AND. ACTPAR .EQ. 'ENDIF') THEN
	       IINST = IINST-1
            ELSEIF (ACTPAR .EQ. 'ENDIF') THEN
               NESTL = NESTL - 1
               GOTO 16
            ELSE
               GOTO 16
            ENDIF
	 ENDIF

      ELSEIF (ACTPAR .EQ. 'ENDIF') THEN
C***                       -----
         IIF = IIF - 1
         IF (IIF .LT. 0) GOTO 996

      ELSE IF (ACTPAR .EQ. 'EXPR') THEN
C***                        ----
        CALL SARGC (LINE_UNEXPANDED, N)
C***    PARSE LINE
        CALL SARGV(LINE_UNEXPANDED, 3, ACTPAR2)

        CALL SARGV(LINE_UNEXPANDED, 4, ACTPAR3)
        CALL SARGV(LINE_UNEXPANDED, 5, ACTPAR4)
        CALL SARGV(LINE_UNEXPANDED, 6, ACTPAR5)

        CALL EXPANDVAR (ACTPAR2, VAR, MAXVAR, NVAR)
        CALL VARLEGAL (LINE, ACTPAR2, 'EXPR')

        CALL EXPRVAR (ACTPAR2, ACTPAR3, ACTPAR4, ACTPAR5,
     >                VAR, MAXVAR, NVAR)

      ELSE IF (ACTPAR .EQ. 'LABEL') THEN
C***                        ------
C***  Decode name of the label
        CALL SARGV(LINE, 3, ACTPAR5)
C***  Is this label the ENDDO for the latest DO-loop?
C***    If not, the LABEL card makes no action
        IF (ACTPAR5 .EQ. CLOOP(2,NLOOP)) THEN
C***    Is the loop index decreasing or increasing ?
          IF (CLOOP(6,NLOOP)(1:1) .EQ. '-') THEN
            ACTPAR2 = '.GE.'
          ELSE
            ACTPAR2 = '.LE.'
          ENDIF
C***  ADD INCREMENT TO LOOP-INDEX:
C***      loopindex = loopindex + increment
          ACTPAR = DOLLAR // CLOOP(3,NLOOP)
          CALL EXPRVAR(CLOOP(3,NLOOP), ACTPAR, 
     >                 '+', CLOOP(6,NLOOP), VAR, MAXVAR, NVAR)
C***      Check if loopindex .LE. endindex (.GE. for neg. increment)
          ACTPAR = DOLLAR // CLOOP(3,NLOOP)
          CALL BOOLVAR(BOOL, ACTPAR, ACTPAR2, 
     >                 CLOOP(5, NLOOP), VAR, MAXVAR, NVAR, IERR1)
          IF (IERR1 .GT. 0) GOTO 970
          IF (BOOL) THEN
C***         Repeat the loop: jump back to the DO statement
	     IINST = INDLOOP(1,NLOOP) 
          ELSE
C***         Loop finished 
C***         Set the loop counter to its last value (important for indices)
ccc             ACTPAR = DOLLAR // CLOOP(3,NLOOP)
             CALL EXPRVAR(CLOOP(3,NLOOP), ACTPAR, 
     >                 '-', CLOOP(6,NLOOP), VAR, MAXVAR, NVAR)
C***         remove this loop from stack
             NLOOP = NLOOP - 1
C***         If the same label is used for the next-outer nested loops:	     
             IF (NLOOP .GT. 0) THEN
                IF (ACTPAR5 .EQ. CLOOP(2,NLOOP)) IINST = IINST - 1
	     ENDIF
          ENDIF
        ENDIF

      ELSE IF (ACTPAR .EQ. 'GOTO') THEN
C***                        ----
        CALL SARGV(LINE, 3, ACTPAR2)
  205   CONTINUE
        DO ITEST = 1, NINST
          LINE2 = INSTLINE(ITEST)
          CALL SARGV(LINE2, 2, ACTPAR)
          IF (ACTPAR .EQ. 'LABEL') THEN
            CALL SARGV(LINE2, 3, ACTPAR)
            IF (ACTPAR( :IDX(ACTPAR)) .EQ. ACTPAR2( :IDX(ACTPAR2))) THEN
               IINST_JUMPSTART = IINST
               IINST = ITEST - 1
               GOTO 210
            ENDIF
          ENDIF
        ENDDO
        GOTO 994
  210   CONTINUE

C*      Check if jump leaves an IF block
        IFCOUNT = 0
	ISTART = MIN0(IINST_JUMPSTART,IINST+1)
        IEND   = MAX0(IINST_JUMPSTART,IINST+1)
        DO ITEST= ISTART, IEND
          LINE2 = INSTLINE(ITEST)
          CALL SARGV(LINE2, 2, ACTPAR)
          IF (ACTPAR .EQ. 'IF') THEN
            IFCOUNT = IFCOUNT + 1
          ELSEIF (ACTPAR .EQ. 'ENDIF') THEN
            IFCOUNT = IFCOUNT - 1
          ENDIF
        ENDDO

        IF (IINST .LT. IINST_JUMPSTART) THEN 
C*      Backward jump
           IIF = IIF - IFCOUNT
           IF (IFCOUNT .LT. 0) PRINT *, 
     >       'WARNING: backward jump into IF-block'
        ELSE 
C*      Forward jump
           IIF = IIF + IFCOUNT
           IF (IFCOUNT .GT. 0) PRINT *, 
     >       'WARNING: forward jump into IF-block'
        ENDIF

        IF (IIF .LT. 0) THEN
           IIF = 0
           PRINT *, 'WARNING: IF-block level negative after GOTO'
           PRINT *, '*** this should actually never happen!'
        ENDIF

      ELSE IF (ACTPAR .EQ. 'DO') THEN
C***                        --
        NLOOP = NLOOP + 1
        IF (NLOOP .GT. MAXLOOP) GOTO 997
C***    Store loop parameters
        CALL SARGV(LINE,3,CLOOP(2,NLOOP))
        CALL SARGV(LINE,4,CLOOP(3,NLOOP))
        CALL SARGV(LINE,5,CLOOP(4,NLOOP))
        CALL SARGV(LINE,6,CLOOP(5,NLOOP))
        CALL SARGC (LINE, NPAR)
        IF (NPAR .GT. 6) THEN
          CALL SARGV(LINE,7,CLOOP(6,NLOOP))
        ELSE
          CLOOP(6,NLOOP) = '1'
        ENDIF

C***    Store present line number
        INDLOOP(1,NLOOP) = IINST
C***    Find line number of the enddo label
        DO ITEST = IINST+1, NINST
           CALL SARGV(INSTLINE(ITEST),2,ACTPAR2)
	   IF (ACTPAR2 .EQ. 'LABEL') THEN
              CALL SARGV(INSTLINE(ITEST),3,ACTPAR2)
	      IF (ACTPAR2 .EQ. CLOOP(2,NLOOP)) THEN
                 INDLOOP(2,NLOOP) = ITEST
	         GOTO 300
	      ENDIF
	   ENDIF
	ENDDO
        GOTO 993
  300   CONTINUE
        CALL PUTVAR(CLOOP(3,NLOOP), CLOOP(4,NLOOP), VAR, MAXVAR, NVAR)

C***    The following check prevents execution of "empty" loops
C***    Is the loop index decreasing or increasing ?
        IF (CLOOP(6,NLOOP)(1:1) .EQ. '-') THEN
          ACTPAR2 = '.GE.'
        ELSE
          ACTPAR2 = '.LE.'
        ENDIF
C***      Check if startindex .LE. endindex (.GE. for neg. increment)
          CALL BOOLVAR(BOOL, CLOOP(4,NLOOP), ACTPAR2, 
     >                 CLOOP(5, NLOOP), VAR, MAXVAR, NVAR, IERR1)
          IF (IERR1 .GT. 0) GOTO 970
          IF (.NOT. BOOL) THEN
C***         Loop immediately finished: goto endloop label
             IINST = INDLOOP(2,NLOOP)
C***         remove this loop from stack
             NLOOP = NLOOP - 1
C***         If the same label is used for the next-outer nested loops:	     
             IF (NLOOP .GT. 0) THEN
                IF (ACTPAR5 .EQ. CLOOP(2,NLOOP)) IINST = IINST - 1
	     ENDIF
          ENDIF

      ELSE IF (ACTPAR .EQ. 'FORMAT') THEN
C                           ------
        CALL SARGC (LINE_UNEXPANDED, NARG)
	    IF (NARG .LT. 4) THEN
	       WRITE (*,'(/,A)') 'ERROR: FORMAT requires a value'
           GOTO 999
        ENDIF

        CALL SARGV (LINE, 3, ACTPAR3)
        CALL SARGV (LINE_UNEXPANDED, 4, ACTPAR4)
        I1 = IVAR (ACTPAR4(2:), VAR, MAXVAR, NVAR, CIVAR)
        CALL SARGV (LINE, 4, ACTPAR4)
        READ  (ACTPAR4,*,ERR=990) XVAR
        WRITE (VAR(I1,2), ACTPAR3, ERR=992) XVAR

      ELSE IF (ACTPAR .EQ. 'FORMATI') THEN
C                           ------
        CALL SARGC (LINE_UNEXPANDED, NARG)
	    IF (NARG .LT. 4) THEN
	       WRITE (*,'(/,A)') 'ERROR: FORMATI requires a value'
           GOTO 999
        ENDIF
        CALL SARGV (LINE, 3, ACTPAR3)
        CALL SARGV (LINE_UNEXPANDED, 4, ACTPAR4)
        I1 = IVAR (ACTPAR4(2:), VAR, MAXVAR, NVAR, CIVAR)
        CALL SARGV (LINE, 4, ACTPAR4)
        READ  (ACTPAR4,*,ERR=991) IVALUE
        WRITE (VAR(I1,2), ACTPAR3, ERR=992) IVALUE

      ELSE IF (ACTPAR .EQ. 'FORMATA') THEN
C                           ------
        CALL SARGC (LINE_UNEXPANDED, NARG)
	    IF (NARG .LT. 4) THEN
	       WRITE (*,'(/,A)') 'ERROR: FORMATA requires a value'
           GOTO 999
        ENDIF
        CALL SARGV (LINE, 3, ACTPAR3)
        CALL SARGV (LINE_UNEXPANDED, 4, ACTPAR4)
        I1 = IVAR (ACTPAR4(2:), VAR, MAXVAR, NVAR, CIVAR)
        CALL SARGV (LINE, 4, ACTPAR4)
        WRITE (VAR(I1,2), ACTPAR3, ERR=992) ACTPAR4

      ELSE IF (ACTPAR .EQ. 'CUTVAR') THEN
C                           ------
        CALL SARGC (LINE_UNEXPANDED, N)
        IF (N .LT. 4) THEN
           WRITE (*,*) '*** ERROR: CUTVAR HAS NOT ENOUGH PARAMETERS'
           GOTO 999
        ENDIF
        CALL SARGV (LINE_UNEXPANDED, 3, ACTPAR3)
C***    Input is flexible: variable may come with or without Dollar
        IF (ACTPAR3(1:1) .EQ. DOLLAR) THEN 
           VARNAME = ACTPAR3(2:)
        ELSE
           VARNAME = ACTPAR3
           ACTPAR3 = DOLLAR // VARNAME
        ENDIF
cc        CALL DECVAR (ACTPAR3, VAR,MAXVAR,NVAR)
        CALL EXPANDVAR (VARNAME, VAR,MAXVAR,NVAR)
        CALL EXPANDVAR (ACTPAR3, VAR,MAXVAR,NVAR)
	IA = 1
	ILENG = IDX(ACTPAR3)
	IE = ILENG
        CALL SARGV (LINE_UNEXPANDED, 4, SHORTVAR)
        IF (SHORTVAR .NE. '') READ (SHORTVAR, '(I4)', ERR=984) IA
        IF (IA .EQ. 0) GOTO 985
        IF (IA .LT. 0) IA = ILENG + IA
        IF (N .GE. 5) THEN
           CALL SARGV (LINE_UNEXPANDED, 5, SHORTVAR)
           IF (SHORTVAR .NE. '') READ (SHORTVAR, '(I4)', ERR=984) IE
           IF (IE .LT. 0) IE = ILENG + IE
        ENDIF
        IF (IE .LT. IA) GOTO 986 
        IA = MAX(1,IA)
	IE = MIN(ILENG,IE)
        CALL PUTVAR (VARNAME, ACTPAR3(IA:IE), VAR, MAXVAR, NVAR)

      ELSE IF (ACTPAR .EQ. 'PARSEVAR') THEN
C                           --------
        CALL SARGC (LINE_UNEXPANDED, N)
        IF (N .LT. 4) THEN
           WRITE (*,*) '*** ERROR: PARSEVAR HAS NOT ENOUGH PARAMETERS'
           GOTO 999
        ENDIF
        CALL SARGV (LINE_UNEXPANDED, 3, ACTPAR3)
C***    Input is flexible: variable may come with or without Dollar
        IF (ACTPAR3(1:1) .EQ. DOLLAR) THEN 
           VARNAME = ACTPAR3(2:)
        ELSE
           VARNAME = ACTPAR3
           ACTPAR3 = DOLLAR // VARNAME
        ENDIF
        CALL EXPANDVAR (VARNAME, VAR,MAXVAR,NVAR)
        CALL EXPANDVAR (ACTPAR3, VAR,MAXVAR,NVAR)

        CALL SARGV (LINE_UNEXPANDED, 4, SHORTVAR)
        IF (SHORTVAR .NE. '') READ (SHORTVAR, '(I4)', ERR=984) IARG
        IF (IARG .LE. 0) THEN
           WRITE (*,*) '*** PARSEVAR: Argument number must be > 0'
           GOTO 999           
        ENDIF
        CALL SARGV (ACTPAR3, IARG, ACTPAR4)
        CALL PUTVAR (VARNAME, ACTPAR4, VAR, MAXVAR, NVAR)

      ELSE IF (ACTPAR .EQ. 'OPEN') THEN
C***                        ====
        CALL SARGC (LINE, NARG)
	IF (NARG .LT. 3) GOTO 980
        CALL SARGV (LINE, 3, ACTPAR4)
        OPEN (50, FILE=ACTPAR4(:IDX(ACTPAR4)), STATUS='UNKNOWN',ERR=981)
 
      ELSE IF (ACTPAR .EQ. 'WRITE') THEN
        CALL SARGREST (LINE, NPAR, 3, IFIRST, ILAST)
        WRITE (50, '(A)', ERR=982) LINE(IFIRST:ILAST)

      ELSE IF (ACTPAR .EQ. 'READ') THEN
        CALL SARGC (LINE, NARG)
	IF (NARG .LT. 3) THEN
	   WRITE (*,'(/,A)') 'ERROR: READ requires name of variable'
           GOTO 999
        ENDIF
        CALL SARGV (LINE, 3, VARNAME)
        READ (50, '(A)', END=70) LINE
        GOTO 71
   70   LINE = 'E-O-F'
   71   CALL PUTVAR (VARNAME, LINE, VAR, MAXVAR, NVAR)
   
      ELSE IF (ACTPAR .EQ. 'CLOSE') THEN
        CLOSE (50)

C***  Pass any command to the shell 
      ELSE IF (ACTPAR .EQ. 'SYSTEM') THEN
C***                        -----
         CALL SARGREST (LINE, NPAR, 3, IFIRST, ILAST)
	 IF (NPAR .LE. 2) THEN
	    WRITE (*,*) 'Non-fatal error: empty SYSTEM call' 
            WRITE(*,'(A)') 'THE ERROR OCCURED IN THE FOLLOWING LINE:'
            WRITE(*,'(A)') LINE(:IDX(LINE))
         ELSE
	    CALL SYSTEM (LINE(IFIRST:ILAST))
	 ENDIF

C***  KASDEF ECHO
C***  --------------------------
      ELSE IF (ACTPAR .EQ. 'ECHO') THEN
         CALL SARGREST (LINE, NPAR, 3, IFIRST, ILAST)
         WRITE (*,*) LINE(IFIRST:ILAST)

C***  KASDEF GETTIME
C***  --------------------------
      ELSE IF (ACTPAR .EQ. 'GETTIME') THEN
         CALL TIME(CTIME)
         CALL PUTVAR('TIME', CTIME, VAR, MAXVAR, NVAR)

      ELSE

        IERR = 1

      ENDIF
      RETURN

C******************************************************************

95    WRITE (*,'(/A)') '*** ERROR: CONTINUATION LINE TRUNCATED'
      WRITE (*,'(A)') '*** THE ERROR OCCURED IN THE FOLLOWING LINES:'
      WRITE (*,'(A)') LINE (:IDX(LINE ))
      WRITE (*,'(A)') LINE1(:IDX(LINE1))
      STOP 'ERROR IN EXINST'

  970 WRITE (*,*) 'Line before the variables were expanded:'
      WRITE (*,*) LINE_UNEXPANDED(:IDX(LINE_UNEXPANDED))
      WRITE (*,*) 'Line after the variables were expanded:'
      WRITE (*,*) LINE(:IDX(LINE))
      GOTO 999

  980 WRITE (*,*) 'OPEN command requires filename'
      GOTO 999

  981 WRITE (*,*) 'Could not open file for writing!'
      GOTO 999

  982 WRITE (*,*) 'WRITE command failed'
      GOTO 999

  983 WRITE (*,*) 'Illegal parameter of CALC_DEBUG: use only ON or OFF'
      GOTO 999

  984 WRITE (*,*) 'Parameter could not be decoded as integer number'
      GOTO 999

  985 WRITE (*,*) 'ZERO not allowed as parameter'
      GOTO 999

  986 WRITE (*,*) 'Invalid string cut (', IA, ':', IE,')'
      GOTO 999



  990 WRITE (*,'(//,4A,/,A)') 'Fourth Parameter ', 
     >            VAR(I1,1)(:IDX(VAR(I1,1))), 
     >            ' = ',  ACTPAR4(:IDX(ACTPAR4)), 
     >            ' is not readable as floating point number'
      GOTO 999

  991 WRITE (*,'(//,4A,/,A)') 'Fourth Parameter ', 
     >            VAR(I1,1)(:IDX(VAR(I1,1))), 
     >            ' = ',  ACTPAR4(:IDX(ACTPAR4)), 
     >            ' is not readable as integer number'
      GOTO 999

  992 WRITE (*,'(//,A)') 'Troubles when writing with the FORMAT string'
      GOTO 999

  993 WRITE (*,'(//,A)') 'ENDDO-LABEL not found'
      GOTO 999

  994 WRITE (*,*) 'GOTO-LABEL not found'
      GOTO 999 

  995 WRITE (*,*) 'Unmatched IF, ENDIF is missing'
      GOTO 999

  996 WRITE (*,*) 'ENDIF without matching IF'
      GOTO 999
      
  997 WRITE (0,*) 'TOO MANY NESTED LOOPS'
      GOTO 999

  998 WRITE (0,*) 'TOO MANY NESTED IFs'
      GOTO 999

  999 WRITE (*,*) 'THE ERROR OCCURED IN THE FOLLOWING LINE:'
      WRITE (*,*) LINE(:IDX(LINE))
      STOP 'FATAL ERROR IN SUBR. EXINST'

      END
