C***      PROGRAM LOADHELP
      SUBROUTINE LOADHELP
C***  Hilfsroutine, um anhand der loadmap die Fortran-Routinen aus einer  
C***  Quellbibliothek zu extrahieren

      CHARACTER*132 LINE, MODULE

      OPEN (2, FILE='loadmap', STATUS='OLD')
      OPEN (3, FILE='load_opt.scratch', STATUS='NEW')

CF*** Over-read first line which gives the library
      READ  (2, '(A)', END=99) LINE

    1 CONTINUE
      READ  (2, '(A)', END=99) LINE
      MODULE = LINE(2:)
      WRITE (3, '(A)') 'ar x libscratch.tlb ''' //  
     >                  MODULE(:IDX(MODULE)-2) // '.f'''
      GOTO 1

   99 CONTINUE

      CLOSE (2)
      CLOSE (3)
      STOP
      END
loadhelp1.f/    1553528659  5006  320   100644  2084      `
ccc      PROGRAM LOADHELP1
      SUBROUTINE LOADHELP1
C***  For starting a new installation on a system, it might be necessary
C***  to make "loadhelp1" a main program and compile it, giving 
C***  also the standard library (libvax) to satisfy references.
C***  Auxiliary routine for link procedures:
C***    Contructs extraction commands for all libraries listed in the file
C***    "loadlibs"

      CHARACTER*132 LINE, LINE2, ACTPAR, WORDLENGTH

      OPEN (2, FILE='../loadlibs', STATUS='OLD')
      OPEN (3, FILE='extract_libs.scratch', STATUS='NEW')
      OPEN (4, FILE='compileroptions.scratch', STATUS='NEW')

      WORDLENGTH = 'UNDEFINED'

    1 CONTINUE
      READ  (2, '(A)', END=99) LINE

C***  COMMENT LINE ENCOUNTERED
      IF (LINE(1:1) .EQ. '*') GOTO 1

C***  WORDLENGTH COMMAND ENCOUNTERED
      CALL SARGV (LINE, 1, ACTPAR)
      IF (ACTPAR(:10) .EQ. 'WORDLENGTH' .OR. 
     >  ACTPAR(:10) .EQ. 'wordlength' ) THEN
        CALL SARGV (LINE, 2, ACTPAR)
        WORDLENGTH = ACTPAR
        IF (ACTPAR(:4) .EQ. 'LONG' .OR. ACTPAR(:4) .EQ. 'long') THEN
          WRITE (4, '(A)') 'long'          
        ELSEIF (ACTPAR(:5) .EQ. 'SHORT' .OR. 
     >                         ACTPAR(:5) .EQ. 'short') THEN
          WRITE (4, '(A)') 'short'          
        ELSE
          WRITE (3, '(A)') 'echo FATAL ERROR:'
          WRITE (3, '(A)') 
     >     'echo Invalid WORDLENGTH instruction in file "loadlibs"'
          WRITE (3, '(A)') 'exit'          
          GOTO 99
        ENDIF
        GOTO 1
      ENDIF

C***  LIBRARY NAME ENCOUNTERED        
      WRITE (3, '(A)') 'ar x ' // ACTPAR(:IDX(ACTPAR)) // '.a'
      WRITE (3, '(A)') 'chmod u+w ________64ELEL_'

      GOTO 1

C***  E-O-F REACHED
   99 CONTINUE

C***  Check if WORDLENGTH IS DEFINED
      IF (WORDLENGTH(:9) .EQ. 'UNDEFINED') THEN
        WRITE (3, '(A)') 'echo FATAL ERROR:'
        WRITE (3, '(A)') 
     >   'echo WORDLENGTH never defined in instruction file "loadlibs"'
        WRITE (3, '(A)') 'exit'          
        ENDIF

      CLOSE (2)
      CLOSE (3)
      CLOSE (4)
      STOP
      END
loadhelp2.f/    1553528659  5006  320   100644  1948      `
C***      PROGRAM LOADHELP2
      SUBROUTINE LOADHELP2
C***  Auxiliary routine for link procedures:
C***    Contructs extraction commands for all libraries listed in the file
C***    "loadlibs"

      CHARACTER*132 LINE, LINE2, ACTPAR, WORDLENGTH

      OPEN (2, FILE='../loadlibs', STATUS='OLD')
      OPEN (3, FILE='extract_libs.scratch', STATUS='NEW')
      OPEN (4, FILE='compileroptions.scratch', STATUS='NEW')

      WORDLENGTH = 'UNDEFINED'

    1 CONTINUE
      READ  (2, '(A)', END=99) LINE

C***  COMMENT LINE ENCOUNTERED
      IF (LINE(1:1) .EQ. '*') GOTO 1

C***  WORDLENGTH COMMAND ENCOUNTERED
      CALL SARGV (LINE, 1, ACTPAR)
      IF (ACTPAR(:10) .EQ. 'WORDLENGTH' .OR. 
     >  ACTPAR(:10) .EQ. 'wordlength' ) THEN
        CALL SARGV (LINE, 2, ACTPAR)
        WORDLENGTH = ACTPAR
        IF (ACTPAR(:4) .EQ. 'LONG' .OR. ACTPAR(:4) .EQ. 'long') THEN
          WRITE (4, '(A)') 'long'          
        ELSEIF (ACTPAR(:5) .EQ. 'SHORT' .OR. 
     >                         ACTPAR(:5) .EQ. 'short') THEN
          WRITE (4, '(A)') 'short'          
        ELSE
          WRITE (3, '(A)') 'echo FATAL ERROR:'
          WRITE (3, '(A)') 
     >     'echo Invalid WORDLENGTH instruction in file "loadlibs"'
          WRITE (3, '(A)') 'exit'          
          GOTO 99
        ENDIF
        GOTO 1
      ENDIF

C***  LIBRARY NAME ENCOUNTERED        
      WRITE (3, '(A)') 'ar x ' // ACTPAR(:IDX(ACTPAR)) // '.tlb'
      WRITE (3, '(A)') 'ar x ' // ACTPAR(:IDX(ACTPAR)) // '.a'
      WRITE (3, '(A)') 'chmod u+w ________64ELEL_'

      GOTO 1

C***  E-O-F REACHED
   99 CONTINUE

C***  Check if WORDLENGTH IS DEFINED
      IF (WORDLENGTH(:9) .EQ. 'UNDEFINED') THEN
        WRITE (3, '(A)') 'echo FATAL ERROR:'
        WRITE (3, '(A)') 
     >   'echo WORDLENGTH never defined in instruction file "loadlibs"'
        WRITE (3, '(A)') 'exit'          
        ENDIF

      CLOSE (2)
      CLOSE (3)
      CLOSE (4)
      STOP
      END
acards.f/       1553528659  5006  320   100644  3002      `
      SUBROUTINE ACARDS
C******************************************************************
C***  Liest im File FNAME TEFF, RSTAR, MDOT und VFIN
C***    errechnet daraus RT
C***  Mit der neuen Endgeschwindigkeit VNEW wird MDOTNEW ausgerechnet
C***    und in das File geschrieben. Der Output landet in FNAME4
C******************************************************************

      CHARACTER*132 LINE, LINE2
      CHARACTER*80 ACTPAR, ACTPAR2, ACTPAR3, ACTPAR4, S1, S2, S3
      CHARACTER*255 FNAME, FNAME2, FNAME3, FNAME4, FNAME5

      VNEW = 1600.

      FNAME = 'temp.doc'
      FNAME2 = 'temp2.doc'
      FNAME3 = 'temp3.doc'
      FNAME4 = 'temp4.doc'
      S3 = ' '
C***  LESE acards.inp
      OPEN (UNIT=20, FILE='acards.inp', STATUS='OLD')
 1000 CONTINUE
        READ (20, '(A)', END=99) LINE
        IF (LINE(1:1) .EQ. '*') GOTO 1000
        CALL SARGC(LINE, NPAR)
        CALL SARGV(LINE, 1, FNAME)
        IF (NPAR .GT. 1) THEN
          CALL SARGV(LINE, 2, FNAME4)
        ELSE
          FNAME4 = FNAME
        ENDIF

C***  LESE T, RT, R*, MDOT, V8 aus dem Input (HEADLINE-Zeile)
      OPEN (UNIT=1, FILE=FNAME, STATUS='OLD')
      DENSCON = 1.
  100 CONTINUE
        READ (1, '(A)', END=110) LINE
        IF (LINE( :4) .EQ. 'TEFF') THEN
          READ (LINE(6:13), '(F20.0)') TEFF
        ELSE IF (LINE( :5) .EQ. 'RSTAR') THEN
          READ (LINE(23:29), '(F20.0)') RSTAR
        ELSE IF (LINE( :4) .EQ. 'MDOT') THEN
          READ (LINE(7:12), '(F20.0)') XMDOT
        ELSE IF (LINE( :6) .EQ. 'VELPAR') THEN
          READ (LINE(24:28), '(F20.0)') VFIN
        ELSE IF (LINE( :7) .EQ. 'DENSCON') THEN
          READ (LINE(9:11), '(F20.0)') DENSCON
        ENDIF
      GOTO 100
  110 CONTINUE
      CLOSE (1)

      RT = RSTAR * 
     >  (VFIN/2500. /(SQRT(DENSCON)*10**(XMDOT)/1.E-4))** (2./3.)
c     >  (VFIN/2500. /(10**(XMDOT)/1.E-4))** (2./3.)
      WRITE (*,*) TEFF, RT, RSTAR, XMDOT, VFIN, DENSCON

      XMDOTNEW = 
     >  ALOG10(1. / (2500. * (RT/RSTAR)**1.5 / VNEW / 1.E-4) / 
     >  SQRT(DENSCON))
      WRITE (*,*) 'XMODTNEW=', XMDOTNEW

      WRITE (S1, '(F5.0)') VFIN
      S1 = S1( :4)
      WRITE (S2, '(F5.0)') VNEW
      S2 = S2( :4)
      WRITE (*,*) 'S=', S1, S2
      CALL SUBST (FNAME, FNAME2, S1, S2, S3)

      WRITE (S1, '(F6.3)') XMDOT
      WRITE (S2, '(F6.3)') XMDOTNEW
      WRITE (*,*) 'S=', S1, S2
      CALL SUBST (FNAME2, FNAME3, S1, S2, S3)

c      S1 = 'SERVATION= 10.'
c      S2 = 'SERVATION=0.25 0.25 0.01 1.0'
c      S1 = 'NO TEMPERATURE CORRE'
c      S2 = '-NO TEMPERATURE CORRE'
c      S1 = '--NO TEMPERATURE CORRE'
c      S2 = '-NO TEMPERATURE CORRE'
c      S1 = 'EXTEND  195. 330.'
c      S2 = 'EXTEND 100. 8000.'
c      S1 = '4MOD'
c      S2 = '1MOD'
      S1 = '-OLD TEMPERATURE STRATIFICAT'
      S2 = 'OLD TEMPERATURE STRATIFICAT'
C***  S3 = delete, Nachfolgende Zeile wird geloescht, sonst einfuegen
      S3 = ' '

      WRITE (*,*) 'S=', S1, S2
      CALL SUBST (FNAME3, FNAME4, S1, S2, S3)

      GOTO 1000

   99 CONTINUE

      END
subst.f/        1553528659  5006  320   100644  1491      `
      SUBROUTINE SUBST(FNAME, FNAME2, S1, S2, S3)
C**************************************************************
C***  Ersetzt im File FNAME den String S1 durch S2 und schreibt das
C***    Ergebnis nach FNAME2
C**************************************************************

      CHARACTER*132 LINE, LINE2
      CHARACTER*80 ACTPAR, ACTPAR2, ACTPAR3, ACTPAR4, S1, S2, S3
      CHARACTER*255 FNAME, FNAME2

      IDS1 = IDX (S1)
      IDS2 = IDX (S2)

C***  ERSETZE S1 DURCH S2
      OPEN (UNIT=1, FILE=FNAME, STATUS='OLD')
      OPEN (UNIT=2, FILE=FNAME2, STATUS='UNKNOWN')

C***  LOOP
    1 CONTINUE
        READ (1, '(A)', END=10) LINE
        ID = IDX(LINE)
        IF (ID .EQ. 0) THEN
          J = 1
          GOTO 20
        ENDIF
        I = 1
        J = 1
    5   CONTINUE
        IF (LINE(I:I+IDS1-1) .NE. S1) THEN
          LINE2(J:J) = LINE(I:I)
          I = I + 1
          J = J + 1
        ELSE
          LINE2 = LINE( :J-1) // S2
          I = I + IDS1
          J = J + IDS2
        ENDIF
      IF (I .LE. ID) GOTO 5
   20 CONTINUE
      DO K = J, 132
        LINE2(K:K) = ' '
      ENDDO
      WRITE (2, '(A)') LINE2( :IDX(LINE2))
      IF (LINE( :IDX(LINE)) .NE. LINE2( :IDX(LINE2)) .AND.
     >    IDX(S3) .GT. 0) THEN
        IF (S3( :IDX(S3)) .EQ. 'delete') then
          READ (1, '(A)', END=10) LINE
        ELSE
          WRITE (2, '(A)') S3( :IDX(S3))
        ENDIF
      ENDIF
      GOTO 1

   10 CONTINUE

      CLOSE(1)
      CLOSE(2)

      RETURN
      END

inqvar.f/       1553528659  5006  320   100644  715       `
      SUBROUTINE INQVAR (ACTPAR, VAR, MAXVAR, NVAR)
C***************************************************
C***  INQUIRES VARIABLES:
C***  ACTPAR IS INPUT AND OUTPUT
C***  ACTPAR HAS THE OUTPUT-VALUE 'TRUE' OR 'FALSE'
C***************************************************

      CHARACTER*(*) VAR(MAXVAR,2)
      CHARACTER*(*) ACTPAR
      CHARACTER*80 ACTPAR2

      IF (ACTPAR(1:1) .NE. '$') THEN
        ACTPAR = '$_IS_MISSING'
        GOTO 100
      ENDIF

      ACTPAR2 = ACTPAR(2: )
      ACTPAR = 'FALSE'
      I = 1
    5 IF (I .LE. NVAR) THEN
        IF (ACTPAR2 .EQ. VAR(I,1)) THEN
          ACTPAR = 'TRUE'
          GOTO 100
        ENDIF
        I = I + 1
      GOTO 5
      ENDIF

  100 RETURN
      END

doubread.f/     1557914887  5006  320   100644  712       `
      SUBROUTINE DOUBREAD (ACTPAR, X, BFAIL)

      CHARACTER*(*) ACTPAR
      LOGICAL BFAIL
      DOUBLE PRECISION VALUE, ONE
      PARAMETER ( ONE = 1. )

C***  Largest possible (standard precision) floating point number
C***  prepared by subr. INSTALL
      COMMON / COMFPMAX / FPMAX
      
      BFAIL = .FALSE.

      READ (ACTPAR, '(BN,F40.0)', ERR=100) VALUE
      IF (ABS(VALUE) .GT. FPMAX) THEN
        VALUE = SIGN(ONE, VALUE) * FPMAX
        WRITE (*,'(/,A,A,A,E9.1)') 
     >    'Too large number in data: ', ACTPAR( :IDX(ACTPAR)), 
     >    '  --> reduced to  ',         VALUE
      ENDIF
      X = VALUE

      GOTO 200

  100 CONTINUE
      BFAIL = .TRUE.

  200 CONTINUE

      RETURN
      END
rtcalc.f/       1553528659  5006  320   100644  627       `
      SUBROUTINE RTCALC
C***  PROGRAMM ZUM AUSRECHNEN DES TRANSFORMIERTEN RADIUS

      WRITE (*,*) 'EINGABE V-INFTY [km/s]:'
      READ  (*,*) VMAX

      WRITE (*,*) 'EINGABE log M-dot:'
      READ  (*,*) XLOGMDOT
      WRITE (*,*) 'EINGABE R* [in R_sun]:'
      READ  (*,*) RSTAR

      RT = RSTAR * ( (VMAX / 2500.) / 10.**(XLOGMDOT+4.0) )**(2./3.)

      WRITE (*,'(4(/,A,F9.3))') ' V-INFTY [km/s] = ', VMAX, 
     >                          ' log M-dot      = ', XLOGMDOT,
     >                          ' R* [R_sun]     = ', RSTAR,
     >                          ' Rt [R_sun]     = ', RT

      STOP 'O.K.'
      END


mdotcalc.f/     1553528659  5006  320   100644  652       `
      SUBROUTINE MDOTCALC
C***  PROGRAMM ZUM AUSRECHNEN VON M-DOT BEI GEGEBENEM TRANSFORMIERTEN RADIUS

      WRITE (*,*) 'EINGABE V-INFTY [km/s]:'
      READ  (*,*) VMAX

      WRITE (*,*) 'EINGABE Rt [in R_sun]:'
      READ  (*,*) RT

      WRITE (*,*) 'EINGABE R* [in R_sun]:'
      READ  (*,*) RSTAR

      XLOGMDOT = ALOG10(VMAX / 2500.) - 4.0 + (3./2.) * ALOG10(RSTAR/RT)

      WRITE (*,'(4(/,A,F9.3))') ' V-INFTY [km/s] = ', VMAX, 
     >                          ' Rt [R_sun]     = ', RT,
     >                          ' R* [R_sun]     = ', RSTAR,
     >                          ' log M-dot      = ', XLOGMDOT

      STOP 'O.K.'
      END

subvar.f/       1553528659  5006  320   100644  402       `
