      RETURN
      END


polynom.f/      1553528659  5006  320   100644  173       `
      SUBROUTINE POLYNOM (Y, X, COEFF, N)

      DIMENSION COEFF(N)

      Y = COEFF(N)
      DO I=N-1, 1, -1
        Y = Y*X + COEFF(I)
      ENDDO

      RETURN
      END

skymap2.f/      1553528659  5006  320   100644  1624      `
	SUBROUTINE SKYMAP2
C
C	Das Programm berechnet Skymap-Overlays. 
C       Die Ausgabe erfolgt als Standard-Datentabelle fuer das
C       WRPLOT-Programm. Es werden Kurven mit vorgegebener Hoehe 
C       ueber dem Horizont in Stundenwinkel-Deklination umgerechnet.
C
C	 10-APR-1991 12:00:25 
C-----------------------------------------------------------------------

	PARAMETER (PI = 3.141592654, PI2 = 1.570796327)
	PARAMETER (RAD = 57.29577951, RADH = 3.819718634)


        PRINT *, 'GEOGRAPHISCHE BREITE IN GRAD EINGEBEN'
        READ (*,*) B

        PRINT *, 'ABSTAND DER KURVEN IN GRAD: '
        READ (*,*) IDELTA2

        IDELTA = 1
	B = B/RAD

	OPEN (1,FILE='skymap2.overlay',STATUS='UNKNOWN')

C	Schleife ueber die Zenitdistanz
        DO 500 IA = IAMIN, IAMIN+360, IDELTA2
	    WRITE (1,*) 'N=? XYTABLE '
C           Loop over Azimuth
C            - Note: Different starting point for northern/southern hemisphere
            IF (B .GT. 0) THEN
               IAMIN = -180
            ELSE
               IAMIN = 0
            ENDIF

            DO 1000 IZ = 5, 160, IDELTA
	      Z = FLOAT(IZ) /RAD
		A = FLOAT(IA) /RAD
		D = SIN(B) *COS(Z) -COS(B) *SIN(Z) *COS(A)
		D = ASIN (D)
		T1 = SIN(Z) *SIN(A) /COS(D)
		T2 = (COS(B) *COS(Z) +SIN(B) *SIN(Z) *COS(A)) /COS(D)
                T1 = AMIN1(T1, 1.)
                T1 = AMAX1(T1,-1.)
                T = ASIN (T1)

		IF (T2.LE.0.) T = PI -T
		IF (T.GE.PI) T = T -2. *PI

		WRITE (1,*) T*RADH, D*RAD
		
1000      CONTINUE
	WRITE (1,*) 'FINISH'
500     CONTINUE

	CLOSE(1)

        PRINT *, 'DATA TABLE WRITTEN TO FILE: skymap2.overlay'
        STOP 'O.K.'

	END
merge.f/        1553528659  5006  320   100644  5017      `
      SUBROUTINE MERGE (X, Y, I1, I2, NDAT, NDATMAX, NSETMAX, NSET)

C**********************************************************************
C***  CALLED FROM: SUBROUTINE EXCMD (WRPLOT PROGRAM)
C***     Merging of  DATASETS I1 AND I2            
C***  Dataset1 is augmented by the data of set1.   
C***  In the overlapping part, ARISET is used for adding the sets
C**********************************************************************

      DIMENSION X(NDATMAX,NSETMAX), Y(NDATMAX,NSETMAX), NDAT(NSETMAX)
      LOGICAL   B1, B2, B1OFF, B2OFF
      CHARACTER*2 ACTION

C**********************************************************************
C***    EXPLANATION OF SOME VARIABLES                               ***
C***    I1 : NUMBER OF FIRST  DATASET                               ***
C***    I2 : NUMBER OF SECOND DATASET                               ***
C***    L1 : COUNTER [1..NDAT(I1)]                                  ***
C***    L2 : COUNTER [1..NDAT(I2)]                                  ***
C**********************************************************************

      IF (NSET .EQ. NSETMAX) THEN
        WRITE (0,*) 'No scratch space for COMMAND MERGE left'
        STOP 'ERROR in Subr. MERGE'
      ENDIF
      I3 = NSETMAX

C**********************************************************************
C***      PUT X-VALUES IN INCREASING ORDER                          ***
C**********************************************************************

      IF (X(2,I1) .LT. X(1,I1)) THEN
        DO 1 I=1,NDAT(I1)
          X(I,I3)=X(NDAT(I1)-I+1,I1)
1         Y(I,I3)=Y(NDAT(I1)-I+1,I1)
        DO 2 I=1,NDAT(I1)
          X(I,I1)=X(I,I3)
2         Y(I,I1)=Y(I,I3)
      ENDIF
      IF (X(2,I2) .LT. X(1,I2)) THEN
        DO 3 I=1,NDAT(I2)
          X(I,I3)=X(NDAT(I2)-I+1,I2)
3         Y(I,I3)=Y(NDAT(I2)-I+1,I2)
        DO 4 I=1,NDAT(I2)
          X(I,I2)=X(I,I3)
4         Y(I,I2)=Y(I,I3)
      ENDIF
       
C**********************************************************************
C***         CHECK MONOTONIC ORDER
C***    Note: only INCREASING ordering is allowed !!
C**********************************************************************

      DO I=2, NDAT(I1)
         IF (X(I,I1) .LE. X(I-1,I1) ) THEN
            WRITE (6, *) 'FIRST DATASET NOT MONOTONICALLY INCREASING'
            WRITE (6, *) 'VALUES: ', X(I-1,I1), X(I,I1)
            STOP 'ERROR IN DATASET ARITHMETIC'
            ENDIF
      ENDDO

      DO I=2, NDAT(I2)
         IF (X(I,I2) .LE. X(I-1,I2) ) THEN
            WRITE (6, *) 'SECOND DATASET NOT MONOTONICALLY INCREASING'
            WRITE (6, *) 'VALUES: ', X(I-1,I2), X(I,I2)
            STOP 'ERROR IN DATASET ARITHMETIC'
            ENDIF
      ENDDO

      J1 = 1
      J2 = 1
      J3 = 1
      B1 = .FALSE.
      B2 = .FALSE.
      B1OFF = .FALSE.
      B2OFF = .FALSE.

C***  LOOP I3
   10 CONTINUE
        IF (B2OFF) THEN
          X(J3,I3) = X(J1,I1)
          B1 = .TRUE.
          ACTION = 'B1'
        ELSEIF (B1OFF) THEN
          X(J3,I3) = X(J2,I2)
          B2 = .TRUE.
          ACTION = 'B2'
        ELSEIF (X(J1,I1) .EQ. X(J2,I2)) THEN
          X(J3,I3) = X(J1,I1)
          B1 = .TRUE.
          B2 = .TRUE.
          ACTION = 'BO'
        ELSEIF (X(J1,I1) .LT. X(J2,I2)) THEN
          X(J3,I3) = X(J1,I1)
          B1 = .TRUE.
          ACTION = 'B1'
        ELSEIF (X(J1,I1) .GT. X(J2,I2)) THEN
          X(J3,I3) = X(J2,I2)
          B2 = .TRUE.
          ACTION = 'B2'
        ELSE
          STOP 'ERROR IN MERGE'
        ENDIF

        IF (B1 .AND. B2) THEN
          IF (ACTION .NE. 'BO') THEN
            Q1 = (X(J3,I3)-X(J1-1,I1)) / (X(J1,I1)-X(J1-1,I1))
            Q2 = (X(J3,I3)-X(J2-1,I2)) / (X(J2,I2)-X(J2-1,I2))
            Y(J3,I3) = 0.5 * (
     >                 Q1*Y(J1,I1) + (1.-Q1)*Y(J1-1,I1) + 
     >                 Q2*Y(J2,I2) + (1.-Q2)*Y(J2-1,I2)
     >                 )
          ELSE
            Y(J3,I3) = 0.5 * (Y(J1,I1) + Y(J2,I2))
          ENDIF
        ELSEIF (B1) THEN
          Y(J3,I3) = Y(J1,I1)
        ELSEIF (B2) THEN
          Y(J3,I3) = Y(J2,I2)
        ENDIF

        IF (ACTION .EQ. 'BO') THEN
          J1 = J1 + 1
          J2 = J2 + 1
        ELSEIF (ACTION .EQ. 'B1') THEN
          J1 = J1 + 1
        ELSEIF (ACTION .EQ. 'B2') THEN
          J2 = J2 + 1
        ENDIF

        J3 = J3 + 1
        IF (J3 .GT. NDATMAX) THEN
          WRITE (*,'(//,A)') '*** FATAL ERROR by COMMAND MERGE:'
          WRITE (*,'(A,I8)') 
     >      '*** new dataset has more points than NDATMAX=', NDATMAX
          WRITE (*,*) 'Note: use SET_NDATMAX for increasing this limit'
          STOP 'ERROR STOP in subroutine MERGE'
        ENDIF 

        IF (J1 .GT. NDAT(I1)) THEN
          B1OFF = .TRUE.
          B1 = .FALSE.
        ENDIF
        IF (J2 .GT. NDAT(I2)) THEN
          B2OFF = .TRUE.
          B2 = .FALSE.
        ENDIF

      IF (.NOT. (B1OFF .AND. B2OFF)) GOTO 10

C***  RESTORE
      DO J=1, J3-1
        X(J,I1) = X(J,I3)
        Y(J,I1) = Y(J,I3)
      ENDDO
      NDAT(I1) = J3-1

      RETURN
      END

expandvar.f/    1553528659  5006  320   100644  4652      `
      SUBROUTINE EXPANDVAR (LINE, VAR, MAXVAR, NVAR)

C***********************************************************************
C***  WRPLOT PROGRAM:
C***  EXPANDING VARIABLES IN A KASDEF LINE
C***  CALLED FROM: KDPLOT, KD_TAB
C***********************************************************************

      CHARACTER*(*) VAR(MAXVAR,2), LINE
      CHARACTER LINE1*1000, DOLLAR*1, BACKSLASH*1, LONGPAR*144
      LOGICAL CHRINSTR
      CHARACTER ACTPAR*20, DELIM*20

      IF (IDX(LINE) .GT. 1000) THEN
         WRITE (*,*) 'LENGTH OF LINE PRESENTLY LIMITED TO 1000'
	 STOP 'ERROR IN EXPANDVAR' 
      ENDIF

      DOLLAR    = CHAR(36)
      BACKSLASH = CHAR(92)

C***  Option is disabled as long as no variables have been defined
      IF (NVAR .LE. 0) GOTO 200

      CALL SARGV (LINE, 2, ACTPAR)
      IF (ACTPAR .EQ. 'CALC') THEN
         DELIM = ' ,=:+-*/^{}()"' // DOLLAR 
      ELSE
         DELIM = ' ,=:^{}()"' // DOLLAR
      ENDIF

C***  First inspection: expand only variables that are indices
C***  LINE is first copied into LINE1, then LINE is built up again piecewise  
      LINE1 = LINE
      LINE = ' '
      LAST = 0
C***  Beginning of loop over all bracket-pairs
  100 CONTINUE
      CALL STRPOS ('[', LINE1, IPOS)
C***  If no bracket left in the string: copy rest of string
      IF (IPOS .LE. 0) THEN
         LINE(LAST+1:) = LINE1
         GOTO 150
      ELSE
         CALL STRPOS (']', LINE1(IPOS:), ILA)
         IF (ILA. LE. 0) THEN
            WRITE (*,*) '*** ERROR: unmatched bracket in line:' 
            WRITE (*,'(2A)') LINE(:IDX(LINE)), LINE1(:IDX(LINE1))
            STOP '*** FATAL ERROR detected in Subr. EXPANDVAR'
         ENDIF
C***     Copy the line till '['
         LINE(LAST+1:) = LINE1(:IPOS-1)
         LAST = LAST + IPOS - 1
         LINE1 = LINE1(IPOS:)
C***     Expand the index variable, if any
         CALL STRPOS (DOLLAR, LINE1(:ILA), IDOLLAR)
         IF (IDOLLAR .EQ. 0) THEN
C***        No variable found, copy the rest of this bracket
            LINE(LAST+1:) = LINE1(:ILA)
            LINE1 = LINE1(ILA+1:)
            LAST = LAST + ILA 
         ELSE
C***        Variable found inside this brackett
C***          remove brackets first
            LONGPAR = LINE1(2:ILA-1)
            CALL DECVAR (LONGPAR, VAR, MAXVAR, NVAR)
            LINE(LAST+1:) = '[' // LONGPAR(:IDX(LONGPAR)) // ']'
            LAST = LAST + IDX(LONGPAR) + 2
            LINE1 = LINE1(ILA+1:)
         ENDIF
	 GOTO 100
      ENDIF
      
  150 CONTINUE

c      write (*,*) 'LINE=', LINE(:IDX(LINE))
c      write (*,*) 'LINE=', LINE(:LAST)

C***  After indices have been expanded, now expand remaining variables
C***  LINE is first copied into LINE1, then LINE is built up again piecewise  
      LINE1 = LINE
      LINE = ' '
      LAST = 0

C***  Begin of loop over all variables in that line
  190 CONTINUE
      CALL STRPOS (DOLLAR, LINE1, IPOS)

C***  If no variable left in the string: copy rest of string
      IF (IPOS .LE. 0) THEN
         LINE(LAST+1:) = LINE1
         GOTO 200
      
C***  If variable starts at position IPOS
      ELSE 
         IF (IPOS .GT. 1) THEN
C***        Dollar might have been masked with backslash
            IF (LINE1(IPOS-1:IPOS-1) .EQ. BACKSLASH) THEN
               LINE(LAST+1:) = LINE1(:IPOS-2)
               LAST = LAST + IPOS - 1
               LINE(LAST:) = DOLLAR
               LINE1 = LINE1(IPOS+1:)
               GOTO 190
            ENDIF
         ENDIF
         LINE(LAST+1:) = LINE1(:IPOS-1)
         LAST = LAST + IPOS - 1
         LINE1 = LINE1(IPOS:)

c***   Das Ende eines Variablennamens (Position ILA) wird 
c***   durch ein Trennzeichen aus DELIM markiert
         IDL1 = IDX(LINE1)

         DO K=2, IDL1 
            IF (CHRINSTR(LINE1(K:K),DELIM)) THEN
C**         special treatment of "-" sign in CALC for negative indices
               IF (LINE1(K:K) .EQ. "-" .AND. 
     >             LINE1(K-1:K-1) .EQ. "[") CYCLE
               ILA = K - 1
               GOTO 10
            ENDIF
         ENDDO
         ILA = IDL1
   10    CONTINUE

C***     If the variable was enclosed by double-quotes (e.g. "$a"),
C***     remove the quotes 
         IF (LAST .GT. 1 .AND. ILA .LT. IDL1) THEN
           IF (LINE(LAST:LAST) .EQ. '"' .AND. 
     >         LINE1(ILA+1:ILA+1) .EQ. '"') THEN
             LAST = LAST - 1
             LINE1(ILA+1:) = LINE1(ILA+2:)
           ENDIF
         ENDIF
         
         LONGPAR = LINE1(1:ILA)
         CALL DECVAR (LONGPAR, VAR, MAXVAR, NVAR)
         LINE(LAST+1:) = LONGPAR
         LAST = LAST + IDX(LONGPAR)
         LINE1 = LINE1(ILA+1:)
         GOTO 190
      ENDIF


  200 CONTINUE


      RETURN

      END
kd_linun.f/     1553528659  5006  320   100644  1912      `
      SUBROUTINE KD_LINUN (LINE, VAR, MAXVAR, NVAR, B, C, 
     >                     XOLIUN, YOLIUN)
C***  Drawing of a line, different styles possible

      CHARACTER*(*) VAR(MAXVAR,2), LINE
c      DIMENSION XUNA(100), YUNA(100), XCMA(100), YCMA(100),SCRATCH(100)
      DIMENSION XUNA(3), YUNA(3), XCMA(3), YCMA(3),SCRATCH(3)
      DIMENSION B(6),C(6)
      CHARACTER ACTPAR*20

C***  Default SIZE and SYMBOL
         SILIUN = 0.5
         ISYUNA = 5 

         CALL DECXYUNITS  (LINE, 3, B, C, XUNA(1) )
         CALL DECXYUNITS  (LINE, 4, B, C, YUNA(1) )
         CALL DECXYUNITS  (LINE, 5, B, C, XUNA(2) )
         CALL DECXYUNITS  (LINE, 6, B, C, YUNA(2) )
         CALL DECFPNUM    (LINE, 7,       XOLIUN )
         CALL DECFPNUM    (LINE, 8,       YOLIUN )

         CALL SARGC (LINE, N)
         DO 245 I=9, N, 2
           CALL SARGV (LINE, I, ACTPAR)
           IF (ACTPAR .EQ. 'SIZE') THEN
             CALL SARGV (LINE, I+1, ACTPAR)
             READ (ACTPAR, '(F20.0)', ERR=96) SILIUN
           ELSE IF (ACTPAR .EQ. 'SYMBOL') THEN
             CALL SARGVR (LINE, I+1, ACTPAR)
             READ (ACTPAR,'(10X,I10)', ERR=96) ISYUNA
           ENDIF
  245    CONTINUE
         
C***
         XUNA(1) = XUNA(1) + XOLIUN/B(1)
         XUNA(2) = XUNA(2) + XOLIUN/B(1)
         YUNA(1) = YUNA(1) + YOLIUN/C(1)
         YUNA(2) = YUNA(2) + YOLIUN/C(1)
         CALL PLOTDAT (XUNA, YUNA, 2, ISYUNA, SILIUN, XCMA, YCMA, 
     >                 B, C, SCRATCH, 'UNIT', VAR, MAXVAR, NVAR, 
     >                 DUMMY, IDUMMY, ' ')

      RETURN

C**********************************************************************
C***  EROR BRANCH
C**********************************************************************
96    WRITE(*,'(A)') 'ERROR WHEN DECODING A PARAMETER'
      WRITE(*,'(A)') 'THE ERROR OCCURED IN THE FOLLOWING LINE:'
      WRITE(*,'(A)') LINE(:IDX(LINE))
      STOP 'ERROR IN KD_LINUN'

      END
decfpnum.f/     1555062618  5006  320   100644  1374      `
      SUBROUTINE DECFPNUM (LINE, IARG, VALUE)
C**********************************************************************
C***  Decodes a floting-point type argument from LINE
C***  ALLOWS THE USE OF THE "SAME" KEYWORD
C***  and the prefixes LOG and DEX
C***  Note that there exists a special SUBR. DECXYUNITS for X, Y 
C**********************************************************************
      CHARACTER LINE*(*), ACTPAR*40

      CALL SARGV (LINE, IARG, ACTPAR)
      LAST = IDX(ACTPAR)

      IF (ACTPAR(:4) .EQ. 'SAME') RETURN
      
      IF (ACTPAR(1:3) .EQ. 'LOG') THEN
         READ (ACTPAR(4: ), '(F10.0)') VALUE
         VALUE = ALOG10 (VALUE)
      ELSE IF (ACTPAR(1:3) .EQ. 'DEX') THEN
         READ (ACTPAR(4: ), '(F10.0)') VALUE
         VALUE = 10. ** (VALUE)
      ELSE IF (ACTPAR(1:1) .EQ. '(' .AND. 
     >        ACTPAR(LAST:LAST) .EQ. ')' ) THEN 
C***     Arithmetic expression
         CALL ARIPAR (ACTPAR, VALUE, IERR)
         IF (IERR .NE. 0) GOTO 99
      ELSE
         READ (ACTPAR, '(F20.0)', ERR=99) VALUE
      ENDIF

      RETURN

   99 PRINT *, '*** ERROR IN KASDEF OPTION: ***'
      PRINT *, '>>> ', ACTPAR(:IDX(ACTPAR)), 
     >         ' <<<< CANNOT BE DECODED AS FLOATING POINT NUMBER!'
      PRINT *, 'THE ERROR OCCURED IN THE FOLLOWING LINE:'
      PRINT *, LINE(:IDX(LINE))
      STOP '*** ERROR IN SUBROUTINE DECFPNUM ***'

      END

decxyunits.f/   1555062618  5006  320   100644  2385      `
      SUBROUTINE DECXYUNITS (LINE, IARG, B, C, VALUE)
C**********************************************************************
C***  Decodes a floting-point type argument from LINE
C***  ALLOWS THE USE OF THE "SAME" KEYWORD, "VARIABLES"
C***  XMIN, XMAX, YMIN, YMAX INSTEAD OF NUMERICAL VALUES
C***  and the prefixes LOG and DEX and is therefore good for X, Y in units
C**********************************************************************
      CHARACTER LINE*(*), ACTPAR*40
      DIMENSION B(6), C(6)

      COMMON / COMCMPT / CMPT
      COMMON / COMCLIP / ICLIP, CXMIN(2), CXMAX(2), CYMIN(2), CYMAX(2)
      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA

      CALL SARGV (LINE, IARG, ACTPAR)
      LAST = IDX(ACTPAR)
      
      IF (ACTPAR(:4) .EQ. 'SAME') RETURN
      
      IF (ACTPAR .EQ. 'XMIN') THEN
         VALUE = B(2)
      ELSE IF (ACTPAR .EQ. 'XMAX') THEN
         VALUE = B(3)
      ELSE IF (ACTPAR .EQ. 'YMIN') THEN
         VALUE = C(2)
      ELSE IF (ACTPAR .EQ. 'YMAX') THEN
         VALUE = C(3)
      ELSE IF (ACTPAR .EQ. 'PXMIN') THEN
         XPT = 1.
         VALUE = (XPT/CMPT - XOFFSET) / (FORMATFA * B(1)) + B(2)
      ELSE IF (ACTPAR .EQ. 'PXMAX') THEN
         XPT = CXMAX(1) - 1.
         VALUE = (XPT/CMPT - XOFFSET) / (FORMATFA * B(1)) + B(2)
      ELSE IF (ACTPAR .EQ. 'PYMIN') THEN
         YPT = 1.
         VALUE = (YPT/CMPT - YOFFSET) / (FORMATFA * C(1)) + C(2)
      ELSE IF (ACTPAR .EQ. 'PYMAX') THEN
         YPT = CYMAX(1) - 1.
         VALUE = (YPT/CMPT - YOFFSET) / (FORMATFA * C(1)) + C(2)
      ELSE IF (ACTPAR(1:3) .EQ. 'LOG') THEN
         READ (ACTPAR(4: ), '(F10.0)') VALUE
         VALUE = ALOG10 (VALUE)
      ELSE IF (ACTPAR(1:3) .EQ. 'DEX') THEN
         READ (ACTPAR(4: ), '(F10.0)') VALUE
         VALUE = 10. ** (VALUE)
      ELSE IF (ACTPAR(1:1) .EQ. '(' .AND. 
     >        ACTPAR(LAST:LAST) .EQ. ')' ) THEN 
C***     Arithmetic expression
         CALL ARIPAR (ACTPAR, VALUE, IERR)
         IF (IERR .NE. 0) GOTO 99
      ELSE
         READ (ACTPAR, '(F20.0)', ERR=99) VALUE
      ENDIF

      RETURN

   99 PRINT *, '*** ERROR IN KASDEF OPTION: ***'
      PRINT *, '>>> ', ACTPAR(:IDX(ACTPAR)), 
     >         ' <<<< CANNOT BE DECODED AS FLOATING POINT NUMBER!'
      PRINT *, 'THE ERROR OCCURED IN THE FOLLOWING LINE:'
      PRINT *, LINE(:IDX(LINE))
      STOP '*** ERROR IN SUBROUTINE DECXYUNITS ***'

      END


decfpnumpre.f/  1553528659  5006  320   100644  1123      `
      SUBROUTINE DECFPNUMPRE (LINE, IARG, VALUE, PREFIX)
C**********************************************************************
C***  Decodes a floting-point type argument from LINE
C***  ALLOWS THE USE OF THE "SAME" KEYWORD
C***  and the prefixes LOG and DEX
C***  Note that there exists a special SUBR. DECXYUNITS for X, Y 
C**********************************************************************
      CHARACTER LINE*(*), ACTPAR*20, PREFIX*1, CC*1
      LOGICAL CHRINSTR

      CALL SARGV (LINE, IARG, ACTPAR)
      
      IF (ACTPAR(:4) .EQ. 'SAME') RETURN

      CC = ACTPAR(1:1)

      IF (CHRINSTR(CC, 'LMRUDo')) THEN
         PREFIX = CC
         READ (ACTPAR(2:), '(F19.0)', ERR=99) VALUE
      ELSE
         PREFIX = ' '
         READ (ACTPAR, '(F20.0)', ERR=99) VALUE
      ENDIF

      RETURN

   99 PRINT *, '*** ERROR IN KASDEF OPTION: ***'
      PRINT *, '>>> ', ACTPAR(:IDX(ACTPAR)), 
     >         ' <<<< CANNOT BE DECODED AS FLOATING POINT NUMBER!'
      PRINT *, 'THE ERROR OCCURED IN THE FOLLOWING LINE:'
      PRINT *, LINE(:IDX(LINE))
      STOP '*** ERROR IN SUBROUTINE DECFPNUMPRE ***'

      END


kd_hline.f/     1553528659  5006  320   100644  1305      `
      SUBROUTINE KD_HLINE (XLUNOFS, YLUNOFS, DYCMLUN, DYSIZELUN, 
     >           SIZELUN, XUNITS, YUNITS, B, C, YO2dummy, BTAB, 
     >           RIGHTMARG, TABLEFTMARGIN, TABRIGHTMARGIN)
C***********************************************************
C***  KASDEF HLINE
C***  DRAWING A HORIZONTAL LINE 
C***********************************************************

      DIMENSION B(6), C(6)
      LOGICAL BTAB      

      IF (YLUNOFS .EQ. -9999.) THEN
	 WRITE (*,'(/,A)') 
     >   'WARNING: HLINE ignored because Y position still undefined'
         RETURN
      ENDIF


C***  VERTICAL SPACE ADDED FOR THE HLINE IS THE TEXTHEIGHT
c      YPOS = YLUNOFS + 0.50 * (DYCMLUN + DYSIZELUN * SIZELUN)
c      YCM = (YUNITS-C(2)) * C(1) + YPOS + YO2
      YCM = (YUNITS-C(2)) * C(1) + YLUNOFS
C***  Use width of the table if Tabular environment is active
      IF (BTAB) THEN
         XSTART = TABLEFTMARGIN
         XEND   = TABRIGHTMARGIN
      ELSE
         XSTART = (XUNITS-B(2)) * B(1) + XLUNOFS 
	 XEND   = RIGHTMARG
      ENDIF

      CALL GPLOT (XSTART,  YCM, 3)
      CALL GPLOT (XEND  , YCM, 2)

C***  SHIFT THE FOLLOWING LINES IN DOWNWARDS
      IF (DYSIZELUN .GT. .0) YLUNOFS = YLUNOFS - (DYSIZELUN-1.)*SIZELUN
      IF (DYCMLUN .GT. .0) YLUNOFS = YLUNOFS - DYCMLUN + SIZELUN

      RETURN
      END

kd_tab.f/       1553528659  5006  320   100644  7888      `
      SUBROUTINE KD_TAB (KDLINE, NKD, NKDMAX, IKD, TABLEFTMARGIN, 
     >     TABRIGHTMARGIN,
     >     LINE, XLUNOFS, YLUNOFS, DYCMLUN, DYSIZELUN, PPX, PPYdummy,
     >     SIZELUN, BTAB, B, C, XUNITS, YUNITS, VAR, MAXVAR, 
     >     NVAR, TLUN, IBGRCOL, BBGR, BGRL, BGRR, BGRD, BGRU, XINDENT,
     >     BGRLINE)

C***********************************************************************
C***  TABULAR ENVIRONMENT
C***  CALLED FROM KDPLOT (PROGRAM WRPLOT)
C***********************************************************************
      PARAMETER (MAXTAB = 30)
      LOGICAL ITEM, BBGR, BTAB
      CHARACTER PRETAB*10, PPX*1, PPY*1, PPXDUMMY*1, PPYDUMMY*1
      CHARACTER*(*) TLUN, LINE, BGRLINE
      CHARACTER*(10) ITEMSTRING
      CHARACTER LINE2*132, FTXTINC*255, FNAMINC*255
      CHARACTER ACTPAR*20, LONGPAR*144, LONGPAR2*144
      CHARACTER*(MAXTAB) CTAB
      DIMENSION B(6),C(6)
      DIMENSION PTAB(MAXTAB), PTABL(MAXTAB)
      CHARACTER KDLINE(NKDMAX)*132, TABLINE*200
      CHARACTER*(*) VAR(MAXVAR,2)

C***  SAVE required because this SUBROUTINE is left intermittendly 
C***    for executing "normal" KASDEF statements
      SAVE NTAB, PRETAB, PTAB, PTABL, XLUNTAB, CTAB, LASTCOLOR
	    
C***  This subroutine is entered when the TABON option was encountered
C***  -----------
C!!!  verbesserung : erster Buchstabe in Tabon immer L + Laenge 0.
c!!!  erlaubt weiterschreiben

C***  No ITEM active in TAB environment
      ITEM = .FALSE. 

C***  Consider the present KASDEF line
      IKDTAB = IKD

C***  Special entry if BTAB = .TRUE. :
C***  Execution of TAB section has been interrupted for executing normal
C***    KASDEF statement(s) -- now it continues with the next TAB line
      IF (BTAB) GOTO 130

      
      CALL SARGV (LINE, 3, ACTPAR)
      NTAB = IDX(ACTPAR)
      IF (NTAB .GT. MAXTAB) THEN
           WRITE (*,*) ' MORE COLUMNS THAN DIMENSIONED IN ',
     >                 'TABULATOR ENVIRONMENT'
           WRITE (*,*) ' LINE=',LINE( :IDX(LINE))
           STOP 'ERROR IN SUBROUTINE KDPLOT'
      ENDIF

      CTAB = ACTPAR
      IADRTAB = IKD

      CALL SARGC (LINE, N)
      IF (N .GT. 3) THEN
         CALL SARGV (LINE, 4, PRETAB)
      ELSE
         PRETAB = ' '
      ENDIF

C***  RESET THE COLUMN WIDTH
      DO ITAB=1, NTAB
         PTAB(ITAB) = 0.
         PTABL(ITAB) = 0.
      ENDDO

C***  DECODE THE WIDTHS OF THE COLUMNS UNTIL TABOFF
C***  All lines other than TAB are ignored here
  100 IKDTAB = IKDTAB + 1
      IF (IKDTAB .GT. NKD) THEN
         WRITE (*,*) 'END OF KASDEF LINES IN TABULATOR ENVIRONMENT'
         STOP 'ERROR IN KDPLOT'
      ENDIF
      LINE = KDLINE(IKDTAB)
      CALL EXPANDVAR (LINE, VAR, MAXVAR, NVAR)
      CALL SARGV (LINE, 2, ACTPAR)
      IF (ACTPAR .EQ. 'TABOFF') GOTO 106
      IF (ACTPAR .NE. 'TAB') GOTO 100

C***  CHECK THE NUMBER OF ARGUMENTS
      CALL SARGC (LINE, NARG)
      IF (NARG .LT. NTAB+2) THEN
       WRITE (*,'(A,I2)') 'WARNING: LESS COLUMNS THAN DEFINED =', NTAB
       WRITE (*,*) 'LINE=', LINE( :IDX(LINE))
      ELSE IF (NARG .GT. NTAB+2) THEN
       WRITE (*,'(A,I2)') 'WARNING: MORE COLUMNS THAN DEFINED =', NTAB
       WRITE (*,*) 'LINE=', LINE( :IDX(LINE))
      ENDIF
         
C***  CALCULATE THE LENGTH (Loop over columns)
      DO 104 ITAB=1, NTAB
         CALL SARGV (LINE, 2+ITAB, LONGPAR)
         IF (PRETAB(1:1) .NE. ' ') THEN
            LONGPAR2 = PRETAB( :IDX(PRETAB)) // LONGPAR
            LONGPAR = LONGPAR2
         ENDIF
         CALL MYTLEN (TEXLEN, SIZELUN, LONGPAR, IDX(LONGPAR)) 
         IF (TEXLEN .GT. PTABL(ITAB)) PTABL(ITAB) = TEXLEN
  104 CONTINUE
      GOTO 100
C***  End of loop over all TAB lines

  106 CONTINUE
C***  All entries measured and maximum widths established - now:
C***  CALCULATION OF THE COLUMN POSITIONS
      DO 120 ITAB=1, NTAB
         PREV = XLUNOFS
         DO JTAB=1, ITAB-1
            PREV = PREV + PTABL(JTAB) + 2.*SIZELUN
         ENDDO
         IF (CTAB(ITAB:ITAB) .EQ. 'R') THEN
            PTAB(ITAB) = PREV + PTABL(ITAB)
         ELSE IF (CTAB(ITAB:ITAB) .EQ. 'M') THEN
            PTAB(ITAB) = PREV + PTABL(ITAB)/2.
         ELSE IF (CTAB(ITAB:ITAB) .EQ. 'L') THEN
            PTAB(ITAB) = PREV
         ELSE
            WRITE (*,*) 'COLUMN POSITIONS NOT DECODABLE'
            WRITE (*,*) 'CTAB=',CTAB( :NTAB)
            STOP 'ERROR IN KD_TAB'
         ENDIF
  120 CONTINUE

      TABLEFTMARGIN  = (XUNITS-B(2)) * B(1) + XLUNOFS
      TABRIGHTMARGIN = (XUNITS-B(2)) * B(1) + PTAB(NTAB)
      IF (CTAB(NTAB:NTAB) .EQ. 'M') 
     >  TABRIGHTMARGIN = TABRIGHTMARGIN + 0.5 * PTABL(NTAB)
      IF (CTAB(NTAB:NTAB) .EQ. 'L') 
     >  TABRIGHTMARGIN = TABRIGHTMARGIN +       PTABL(NTAB)

C***  SHIFT the whole table according to the active prefix PPX
      IF (PPX .EQ. 'M') THEN
         SHIFT = 0.5 * (TABRIGHTMARGIN - TABLEFTMARGIN) 
         TABLEFTMARGIN  = TABLEFTMARGIN  - SHIFT
         TABRIGHTMARGIN = TABRIGHTMARGIN - SHIFT
         DO ITAB=1, NTAB
            PTAB(ITAB) = PTAB(ITAB) - SHIFT
	 ENDDO  
      ELSE IF (PPX .EQ. 'R') THEN
         SHIFT =        TABRIGHTMARGIN - TABLEFTMARGIN 
         TABLEFTMARGIN  = TABLEFTMARGIN  - SHIFT
         TABRIGHTMARGIN = TABRIGHTMARGIN - SHIFT
         DO ITAB=1, NTAB
            PTAB(ITAB) = PTAB(ITAB) - SHIFT
	 ENDDO  
      ENDIF


C***  SECOND RUN OVER THE TABLE SECTION
      IKDTAB = IADRTAB

C***  Loop over all lines in the TAB section
  108 CONTINUE
      IKDTAB = IKDTAB + 1
  130 CONTINUE
      LINE = KDLINE(IKDTAB)
      CALL EXPANDVAR (LINE, VAR, MAXVAR, NVAR)
      CALL SARGV (LINE, 2, ACTPAR)
      YLUNTAB = YLUNOFS
      IF (ACTPAR .EQ. 'TABOFF') GOTO 110
C***  Other KASDEF statements are executed outside this subroutine!
         IF (ACTPAR .NE. 'TAB') THEN
            BTAB = .TRUE.
            IKD = IKDTAB - 1 
            RETURN
         ENDIF
	
C***  Loop backwards over the table columns
      DO 112 ITAB=NTAB, 1, -1
         CALL SARGV (LINE, 2+ITAB, LONGPAR)
         IF (PRETAB(1:1) .NE. ' ') THEN
            LONGPAR2 = PRETAB( :IDX(PRETAB)) // LONGPAR
            LONGPAR = LONGPAR2
         ENDIF

C*** Generate LUN line for each Table entry end execute it
         PPY= 'U'
         WRITE (TABLINE,'(A, 2(2A,F10.5,A), 2A)') 
     >          'KASDEF LUN SAME SAME ',
     >          '"',  CTAB(ITAB:ITAB), PTAB(ITAB), '"', 
     >          '"', PPY, YLUNTAB, '"', 
     >          ' SAME ', LONGPAR( :IDX(LONGPAR))
         ACTPAR = 'LUN'
         CALL KD_LUN (TABLINE, ACTPAR, DUMMY, YLUNOFS, DYCMLUN, 
     >     DYSIZELUN, SIZELUN, B, C, XUNITS, YUNITS,        
     >     TLUN, ITEM, BBGR, SIZEITEM, PPXDUMMY, PPY, YO2, IBGRCOL,
     >     LASTCOLOR, BGRL, BGRR, BGRD, BGRU, ITEMSTRING, XINDENT,
     >     BGRLINE)
  112 CONTINUE
C***  End-of-Loop over the columns
  
      GOTO 108
C***  End-of-Loop over all lines in Table -- second run

C***  End of Table reached in second run -- Table finished
  110 CONTINUE

C***  KDPLOT may proceed with the line following after the TAB section
      IKD = IKDTAB
      BTAB = .FALSE.

C***  IF the last prefix was not L, generate an empty line with L prefix
      IF (CTAB(1:1) .NE. 'L') THEN
         WRITE (TABLINE,'(A, 2F10.5, A)') 
     >          'KASDEF LUN SAME SAME ',XLUNOFS, YLUNTAB, ' SAME &N'
         ACTPAR = 'LUN'
         CALL KD_LUN (TABLINE, ACTPAR, DUMMY, YDUMMY, DYCMLUN, 
     >     DYSIZELUN, SIZELUN, B, C, XUNITS, YUNITS,        
     >     TLUN, ITEM, BBGR, SIZEITEM, PPXDUMMY, PPY, YO2, IBGRCOL,
     >     LASTCOLOR, BGRL, BGRR, BGRD, BGRU, ITEMSTRING, XINDENT,
     >     BGRLINE)
      ENDIF

      RETURN

C**********************************************************************
C***  EROR BRANCH
C**********************************************************************
96    WRITE(*,'(A)') 'ERROR OCCURED IN KDPLOT'
      WRITE(*,'(A)') 'THE ERROR OCCURED IN THE FOLLOWING LINE:'
      WRITE(*,'(A)') LINE(:IDX(LINE))
      STOP 'ERROR IN KDPLOT'

      END
kd_text.f/      1553528659  5006  320   100644  6399      `
      SUBROUTINE KD_TEXT (LINE, KDLINE, IKD, NKD, NKDMAX, 
     >   DYCMLUN, DYSIZELUN, SIZELUN, B, C, XUNITS, YUNITS,
     >   XLUNOFS, YLUNOFS, 
     >   TLUN, ITEM, SIZEITEM, PPX, YO2dummy, KDMAXLEN, 
     >   ITEMSTRING, XINDENT, RIGHTMARG )

C***********************************************************************
C***  KASDEF TEXT (writing continuous text)
C***  CALLED FROM SUBROUTINE KDPLOT (PROGRAM WRPLOT)
C***********************************************************************
      COMMON / COMIDEV / IDEV
      LOGICAL   BNEXT, ITEM, BBLOCK
      CHARACTER PPX*1, PPY*1, CC*1, BACKSLASH
      CHARACTER*(*) TLUN, LINE, ITEMSTRING
      DIMENSION B(6),C(6)
      CHARACTER LINEOLD*(400), LONGPAR*132, ACTPAR*20
      CHARACTER KDLINE(NKDMAX)*132

C***  Blocktext and SQUEEZE-Parameter for ps_symbl and x_symbl
      COMMON / COMBLOCK / BBLOCK, SQUEEZE

      SAVE PPY

      BACKSLASH = CHAR(92)

C***  Test whether new coordinates are given 
      CALL SARGC (LINE, NARG)
      IF (NARG .GT. 2) THEN
C***  Achtung : Naechst Zeile ist Pfusch!!!
ccc         YO2 = 0.
 
         CALL DECXYUNITS  (LINE, 3, B, C, XUNITS)
         CALL DECXYUNITS  (LINE, 4, B, C, YUNITS)
         CALL DECFPNUMPRE (LINE, 5, XLUNOFS, PPX)
         CALL DECFPNUMPRE (LINE, 6, YLUNOFS, PPY)
         CALL DECFPNUM    (LINE, 7, SIZELUN)
      ELSE
         PPY = 'U'
      ENDIF

C***  Starting point x-coordinate
      XCM = (XUNITS-B(2)) * B(1) + XLUNOFS
      IF (PPX .EQ. 'M') THEN
         XCM = 2. * XCM - RIGHTMARG
      ELSE IF (PPX .EQ. 'R') THEN
         TEXTWIDTH = RIGHTMARG - XCM
	 XCM = XCM - TEXTWIDTH
	 RIGHTMARG = RIGHTMARG - TEXTWIDTH
      ENDIF

      IF (PPY .EQ. 'M') THEN
         YO2 = -SIZELUN / 2.
      ELSE IF (PPY .EQ. 'U') THEN
         YO2 = -SIZELUN
      ELSE
         YO2 = 0.
      ENDIF
      

      IF (ITEM) THEN 
         YCMITEM = (YUNITS-C(2)) * C(1) + YLUNOFS + 
     +         YO2 * SIZEITEM/SIZELUN
         CALL MYSYMBL (XCM, YCMITEM, SIZEITEM, ITEMSTRING, .0)
         XCM = XCM + XINDENT
      ENDIF

      YLUNOFS = YLUNOFS + YO2 

      TEXTWIDTH = RIGHTMARG - XCM
      IF (TEXTWIDTH .LT. SIZELUN) THEN
         WRITE (*,*) 'TEXTWIDTH TOO SMALL:'
         WRITE (*,'(A,F6.2)') '   STARTPOS.   = ', XCM 
         WRITE (*,'(A,F6.2)') '   RIGHTMARGIN = ', RIGHTMARG 
         WRITE (*,'(A,F6.2)') '   SIZELUN     = ', SIZELUN
	 STOP 'ERROR IN KD_TEXT'
      ENDIF

C***  Print floating text

         TLUN = ' '
         XNEWLEN = .0
         MODESARGOLD = 0
         MODESARG    = 0

C***  Read next input line
   46    IKD = IKD + 1
         IF (IKD .GT. NKD) GOTO 99
C***     skip empty line
         IF (IDX(KDLINE(IKD)) .EQ. 0) GOTO 46

C***  Decode ENDTEXT = end of floating text
C***     Using variable LINEOLD for testing the line
         LINEOLD = KDLINE(IKD)
	 CALL SARGP(LINEOLD, NPAR, 1, NFIRST, NLAST)
         IF (LINEOLD(NFIRST:NFIRST) .EQ. BACKSLASH) THEN 
            CALL SARGV (LINEOLD(NFIRST+1:), 1, ACTPAR)
            IF (ACTPAR .EQ. 'ENDTEXT') GOTO 44
         ELSE
            CALL SARGV (LINEOLD, 1, ACTPAR)
            IF (ACTPAR .EQ. 'KASDEF') THEN
              CALL SARGV (LINEOLD, 2, ACTPAR)
              IF (ACTPAR .EQ. 'ENDTEXT') GOTO 44
            ENDIF
         ENDIF

         IF (MODESARG .EQ. 3) THEN
	 LINE = LINE(:IDX(LINE)) // KDLINE(IKD)
ccc	    print *, 'LINE   =', LINE   (:IDX(LINE   ))
	 ELSE
         LINE = KDLINE(IKD)
	 ENDIF

C***     Loop over the words of the input line  
         CALL TSARGC (LINE, NWORDS)
C***     Test, if last argument is an open LaTex string; if so, 
C***        glue the next input line
         CALL TSARGV (LINE, NWORDS, LONGPAR, MODESARG)
         IF (MODESARG .EQ. 3) GOTO 46

         DO 45 IWORD = 1, NWORDS
          CALL TSARGV (LINE, IWORD, LONGPAR, MODESARG)
C***       note: LINEOLD is misused for testing the NEW line
          IF (MODESARGOLD .EQ. 0) THEN
            LINEOLD = TLUN(:IDX(TLUN)) // ' ' // LONGPAR
          ELSEIF (MODESARGOLD .EQ. 1) THEN 
            LINEOLD = TLUN(:IDX(TLUN)) // LONGPAR
          ELSEIF (MODESARGOLD .EQ. 2) THEN 
            LINEOLD = TLUN(:IDX(TLUN)-1) // LONGPAR
          ELSE
            STOP 'ERROR with MODESARG in KD_TEXT'
          ENDIF
          HLEN = XNEWLEN
          CALL MYTLEN (XNEWLEN, SIZELUN, LINEOLD, IDX(LINEOLD)) 
          IF (BBLOCK) THEN
            BNEXT = XNEWLEN-TEXTWIDTH .GT. TEXTWIDTH-HLEN 
     >              .AND. XNEWLEN .GT. .0
          ELSE
            BNEXT = XNEWLEN .GT. TEXTWIDTH .AND. XNEWLEN .GT. .0
          ENDIF
          IF (BNEXT) THEN
C***      Line overfull -- finish present line, put current word into next line
C***         Write the completed output line
C***         Estimate squeeze factor for blocktext
             IF (BBLOCK) SQUEEZE = TEXTWIDTH / HLEN
             YCM = (YUNITS-C(2)) * C(1) + YLUNOFS 
             CALL MYSYMBL (XCM, YCM, SIZELUN, TLUN, .0)
C***         Make baselineskip for the following line
             YLUNOFS = YLUNOFS -  DYCMLUN - DYSIZELUN * SIZELUN
	     SQUEEZE = 1.
C***         First word of next output line  
             CALL PREATTRIB (LONGPAR)
             TLUN = LONGPAR
             CALL MYTLEN (XNEWLEN, SIZELUN, LONGPAR, IDX(LONGPAR)) 
          ELSE
             IF (TLUN .EQ. ' ') THEN
C***            This is the first line of a new TEXT 
                CALL PREATTRIB (LONGPAR)
                TLUN = LONGPAR
                CALL MYTLEN (XNEWLEN, SIZELUN, LONGPAR, IDX(LONGPAR)) 
             ELSE
C***            Normal case: word added to current output line  
                TLUN = LINEOLD
                HLEN = XNEWLEN
             ENDIF
          ENDIF
        MODESARGOLD = MODESARG
   45   CONTINUE  
        GOTO 46

   44 CONTINUE
      IF (MODESARG .EQ. 3) GOTO 98  
           
C***  Write the last output line
      YCM = (YUNITS-C(2)) * C(1) + YLUNOFS 
      IF (BBLOCK) THEN 
        SQUEEZE = AMIN1 (TEXTWIDTH / HLEN, 1.)
      ELSE 
        SQUEEZE = 1.
      ENDIF
      CALL MYSYMBL (XCM, YCM, SIZELUN, TLUN, .0)
      SQUEEZE = 1.

      RETURN

C**********************************************************************
C***  EROR BRANCH
C**********************************************************************
98    WRITE(*,'(A)') '*** ENDTEXT reached while LaTex string not closed'
      STOP '*** ERROR IN KD_TEXT'

99    WRITE(*,'(A)') 'KASDEF ENDTEXT MISSING'
      STOP 'ERROR IN KD_TEXT'

      END

kd_elli.f/      1553528659  5006  320   100644  3568      `
      SUBROUTINE KD_ELLI (B, C, LINE, IDEV, VAR, MAXVAR, NVAR, 
     >            XUNITS, YUNITS, XCMA, YCMA, NDATMAX, EXO, EYO)
C***********************************************************************
C***  WRPLOT PROGRAM:
C***  KASDEF OPTIONS  FOR AN ELLIPSE
C***  CALLED FROM SUBROUTINE KDPLOT
C***********************************************************************
      LOGICAL   BFILLED, BHATCH
      CHARACTER*(*) VAR(MAXVAR,2), LINE
      DIMENSION B(6),C(6), STRIP(2)
      CHARACTER ACTPAR*20      
      PARAMETER (MAXA = 1000)
      DIMENSION XUNA(MAXA), YUNA(MAXA), SCRATCH(MAXA)
      DIMENSION XCMA(NDATMAX), YCMA(NDATMAX)
      SAVE EALPHA, EHIST, EPHILEN

      BFILLED = .FALSE.
      BHATCH  = .FALSE.
      SIEL = 0.1
      ISYEL = 5

      CALL DECXYUNITS  (LINE,  3, B, C, XUNITS)
      CALL DECXYUNITS  (LINE,  4, B, C, YUNITS)
      CALL DECFPNUM    (LINE,  5, EXO)
      CALL DECFPNUM    (LINE,  6, EYO)
      CALL DECFPNUM    (LINE,  7, EA )
      CALL DECFPNUM    (LINE,  8, EB)
      CALL DECFPNUM    (LINE,  9, EALPHA)
      CALL DECFPNUM    (LINE, 10, EPHIST)
      CALL DECFPNUM    (LINE, 11, EPHILEN)
C*** CONVERT INTO CM
      XCM = (XUNITS-B(2))*B(1) + EXO
      YCM = (YUNITS-C(2))*C(1) + EYO
      EA = EA*B(1)
      EB = EB*C(1)
C***  additional options as Filling option, Size and Symbol
      CALL SARGC (LINE, N)
      DO I=10, N
         CALL SARGV (LINE, I, ACTPAR)
         IF (ACTPAR .EQ. 'SIZE') THEN
            CALL SARGV (LINE, I+1, ACTPAR)
            READ (ACTPAR, '(F20.0)', ERR=96) SIEL
         ELSE IF (ACTPAR .EQ. 'SYMBOL') THEN
            CALL SARGV (LINE, I+1, ACTPAR)
            READ (ACTPAR,'(I20)', ERR=96) ISYEL
         ELSE IF (ACTPAR .EQ. 'FILLED') THEN
            BFILLED = .TRUE.
         ELSE IF (ACTPAR .EQ. 'HATCHED' .OR. ACTPAR .EQ. 'HTYPE') THEN
            BHATCH = .TRUE.
         ENDIF
      ENDDO

      NA = 0
      CALL ELLI (XCM, YCM, EA, EB, EALPHA, EPHIST, EPHILEN, 
     >           XUNA, YUNA, NA, MAXA)

cC***  Filling Command for Postscript
c      IF (BFILLED) THEN
cC!!!     Attention: X11 driver crash if more than 100 points to be filled! 
c
c         NPART = NA / 90
c         DO IPART=0, NPART
cC***        draw a line to the center point
c	       NFIRST = IPART * 90 + 1
c	       NLAST = MIN (NFIRST+91, NA+1)
c
c            XUNASAVE = XUNA(NLAST) 
c            YUNASAVE = YUNA(NLAST) 
c            XUNA(NLAST) = XCM
c            YUNA(NLAST) = YCM
c
c            CALL PLOTDAT (XUNA(NFIRST), YUNA(NFIRST), NLAST-NFIRST+1, 
c     >                 ISYEL, SIEL, XCMA, YCMA, 
c     >                 B, C, SCRATCH, 'CM  ', VAR, MAXVAR, NVAR)
c            CALL GFILL
cC***  Restore overwritten points
c            XUNA(NLAST) = XUNASAVE
c            YUNA(NLAST) = YUNASAVE
c	 ENDDO

      IF (BFILLED) THEN
         NA = NA + 1
	 XUNA(NA) = XCM
         YUNA(NA) = YCM
      ENDIF


      CALL PLOTDAT (XUNA, YUNA, NA, ISYEL, SIEL, XCMA, YCMA, 
     >                 B, C, SCRATCH, 'CM  ', VAR, MAXVAR, NVAR,
     >                 STRIP, IDUMMY, ' ')


C***  Filling Command for Postscript
      IF (BFILLED) THEN
          CALL GFILL
      ELSEIF  (BHATCH) THEN
          CALL HFILL(LINE)
      ENDIF

      RETURN

C**********************************************************************
C***  EROR BRANCH
C**********************************************************************
96    WRITE(*,'(A)') 'ERROR WHEN DECODING A PARAMETER'
      WRITE(*,'(A)') 'THE ERROR OCCURED IN THE FOLLOWING LINE:'
      WRITE(*,'(A)') LINE(:IDX(LINE))
      STOP 'ERROR IN KD_ELLI'

      END
kd_arc.f/       1553528659  5006  320   100644  2122      `
      SUBROUTINE KD_ARC (B, C, LINE, XUNITS, YUNITS, XOFFSET, YOFFSET)
C***********************************************************************
C***  WRPLOT PROGRAM:
C***  KASDEF OPTIONS  FOR AN CIRCLE ARC
C***  CALLED FROM SUBROUTINE KDPLOT
C***********************************************************************

      DIMENSION B(6), C(6)
      CHARACTER LINE*(*), ACTPAR*40  
      SAVE RADIUS, PHISTART, PHILENG
      
      CALL SARGC (LINE, NARG)
      IF (NARG .LT. 9) GOTO 97

      CALL DECXYUNITS  (LINE,  3, B, C, XUNITS)
      CALL DECXYUNITS  (LINE,  4, B, C, YUNITS)
      CALL DECFPNUM    (LINE,  5, XOFFSET)
      CALL DECFPNUM    (LINE,  6, YOFFSET)
      CALL DECFPNUM    (LINE,  7, RADIUS)
      CALL DECFPNUM    (LINE,  8, PHISTART)
      CALL DECFPNUM    (LINE,  9, PHILENG )
      IF (NARG .GT. 9) THEN
         CALL SARGV       (LINE, 10, ACTPAR)
      ELSE
         ACTPAR = ''
      ENDIF

C*** CONVERT INTO CM
      XCM = (XUNITS-B(2))*B(1) + XOFFSET
      YCM = (YUNITS-C(2))*C(1) + YOFFSET

C***  The Arc is split for large radius in oder to avoid crashing of 
C***    the X11 driver when more than 100 points are to be filled
      N = NINT (RADIUS)
      N = MAX (N, 1)

      DO I=1, N
C***  OPEN SYMBOL:
         DPHI = PHILENG / FLOAT(N)
         PHI  = PHISTART + (I-1) * DPHI
         CALL CIRCLE (XCM, YCM, PHI, DPHI, RADIUS)
C***     Filling option   
         IF (ACTPAR .EQ. 'FILLED') THEN
C***        draw a line to the center point
            CALL GPLOT (XCM, YCM, 2)
            CALL GFILL
         ELSEIF (ACTPAR .EQ. 'HATCHED' .OR. ACTPAR .EQ. 'HTYPE') THEN
C***        draw a line to the center point
            CALL GPLOT (XCM, YCM, 2)
            CALL HFILL (LINE)
         ENDIF
      ENDDO

      RETURN

C**********************************************************************
C***  EROR BRANCH
C**********************************************************************
97    WRITE(*,'(A)') 'ERROR; NOT ENOUGH PARAMETERS FOR ARC'
      WRITE(*,'(A)') 'THE ERROR OCCURED IN THE FOLLOWING LINE:'
      WRITE(*,'(A)') LINE(:IDX(LINE))
      STOP 'ERROR IN KD_ARC'

      END
decinum.f/      1553528659  5006  320   100644  777       `
      SUBROUTINE DECINUM (LINE, IARG, IVALUE)
C**********************************************************************
C***  Decodes an INTEGER type argument from LINE
C***  ALLOWS THE USE OF THE "SAME" KEYWORD
C**********************************************************************
      CHARACTER LINE*(*), ACTPAR*10

      CALL SARGV (LINE, IARG, ACTPAR)
      
      IF (ACTPAR(:4) .EQ. 'SAME') RETURN
      
      READ (ACTPAR, '(I10)', ERR=99) IVALUE

      RETURN

   99 PRINT *, '*** ERROR IN KASDEF OPTION: ***'
      PRINT *, '>>> ', ACTPAR(:IDX(ACTPAR)), 
     >         ' <<<< CANNOT BE DECODED AS INTEGER NUMBER!'
      PRINT *, 'THE ERROR OCCURED IN THE FOLLOWING LINE:'
      PRINT *, LINE(:IDX(LINE))
      STOP '*** ERROR IN SUBROUTINE DECINUM ***'

      END


kd_sym.f/       1553528659  5006  320   100644  3839      `
      SUBROUTINE KD_SYM (LINE, XUNITS, YUNITS, B, C, VAR, MAXVAR, NVAR, 
     >                   ICOLOR, SYMXO, SYMYO)

C***********************************************************************
C***  WRPLOT PROGRAM:
C***  PLOTTING OF CENTERED SYMBOLS
C***  CALLED FROM SUBROUTINE KDPLOT
C***********************************************************************

      COMMON / COMIDEV / IDEV
      DIMENSION B(6), C(6), STRIP(2)
      CHARACTER*(*) VAR(MAXVAR,2)
      CHARACTER LINE*(*), COLORSETLINE*132
      CHARACTER ACTPAR*20, CFILL*2
      LOGICAL BHATCH

C***  LAST COLOR
      COMMON / COMCOLOR / LASTCOLOR

      SAVE SYMSIZE, ISYM
     
!***  CHECK DATASETLINE FOR HATCHED OPTIONS:
      BHATCH=.FALSE.      
      CALL SARGC (LINE, NARG)
      DO I=1, NARG
         CALL SARGV (LINE, I, ACTPAR) 
         IF (ACTPAR .EQ. 'HATCHED' .OR. ACTPAR .EQ. 'HTYPE') THEN
            BHATCH=.TRUE.
         ENDIF
      ENDDO

      CALL DECXYUNITS  (LINE, 3, B, C, XUNITS )
      CALL DECXYUNITS  (LINE, 4, B, C, YUNITS )
      CALL DECFPNUM    (LINE, 5,       SYMXO  )
      CALL DECFPNUM    (LINE, 6,       SYMYO  )
      CALL DECFPNUM    (LINE, 7,       SYMSIZE)
      CALL DECINUM     (LINE, 8,       ISYM   )
C***  KEYWORD "CFILL=i": Fill symbol with color i, then switch back to black
      CFILL = '  '         
      CALL SARGC (LINE, NLINE)
      IF (NLINE .GE. 10) THEN
          CALL SARGV (LINE, 9, ACTPAR)
          IF (ACTPAR .EQ. 'CFILL') THEN
             CALL SARGV (LINE, 10, CFILL)
          ENDIF
      ENDIF
C***  OFFSET IS GIVEN IN CM, NOW CONVERTED INTO UNITS AND ADDED:
        X = XUNITS + SYMXO / B(1)
        Y = YUNITS + SYMYO / C(1)

        IF (ISYM .LT. 0 
     >      .OR. (ISYM .GE. 5 .AND. ISYM .LE. 7)
     >      .OR. ISYM .EQ. 9 .OR. ISYM .EQ. 10
     >      .OR. (ISYM .GT. 18 .AND. ISYM .LT. 26) 
     >      .OR. ISYM .EQ. 28
     >      .OR. ISYM .EQ. 34 
     >      .OR. ISYM .EQ. 31 
     >      .OR. ISYM .EQ. 32 
     >      .OR. ISYM .GT. 35 ) THEN
           PRINT *, 'WARNING "KASDEF SYM": '
           PRINT *, 'ILLEGAL SYMBOL CHOICE REPLACED BY ISYMBOL=4'
           ISYM = 4
        ENDIF

        IF (CFILL .EQ. '  ' .AND. .NOT. BHATCH) THEN
          CALL PLOTDAT (X, Y, 1, ISYM, SYMSIZE, 
     >                  DUMMY1,DUMMY2, B, C, DUM3, 'UNIT', 
     >                  VAR, MAXVAR, NVAR, STRIP, ICOLOR, ' ')
        ELSEIF (CFILL .EQ. '  ' .AND. BHATCH) THEN
          CALL PLOTDAT (X, Y, 1, ISYM, SYMSIZE, 
     >                  DUMMY1,DUMMY2, B, C, DUM3, 'UNIT', 
     >                  VAR, MAXVAR, NVAR, STRIP, ICOLOR, LINE)
        ELSE
          ICOLOR2 = ICOLOR
          COLORSETLINE = 'KASDEF COLOR ' // CFILL
          CALL COLOR ('KASDEF', COLORSETLINE, ICOLOR, IDEV)
          IF (BHATCH) THEN
            SYMS2 = ABS(SYMSIZE)
          ELSE 
            SYMS2 = -ABS(SYMSIZE)
          ENDIF
          CALL PLOTDAT (X, Y, 1, ISYM, SYMS2, 
     >                  DUMMY1,DUMMY2, B, C, DUM3, 'UNIT', 
     >                  VAR, MAXVAR, NVAR, STRIP, ICOLOR, LINE)
          WRITE (COLORSETLINE, '(A,I2)') 'KASDEF COLOR ', ICOLOR2
C!!!    OLD VERSION : SWITCH BACK TO BLACK
C!!!          LINE = 'KASDEF COLOR ' // ' 1'
          CALL COLOR ('KASDEF', COLORSETLINE, ICOLOR, IDEV)
          SYMS2 = ABS(SYMSIZE)
          CALL PLOTDAT (X, Y, 1, ISYM, SYMS2, 
     >                  DUMMY1,DUMMY2, B, C, DUM3, 'UNIT', 
     >                  VAR, MAXVAR, NVAR, STRIP, ICOLOR, ' ')
        ENDIF

      RETURN

C**********************************************************************
C***  EROR BRANCH
C**********************************************************************
96    WRITE(*,'(A)') 'SYMBOL NUMBER NOT AN INTEGER'
      WRITE(*,'(A)') 'THE ERROR OCCURED IN THE FOLLOWING LINE:'
      WRITE(*,'(A)') LINE(:IDX(LINE))
      STOP 'ERROR IN KD_SYM'

      END

kd_rect.f/      1553528659  5006  320   100644  1673      `
      SUBROUTINE KD_RECT (B, C, LINE)

C***********************************************************************
C***  WRPLOT PROGRAM:
C***  KASDEF OPTIONS  FOR PLOTTING A RECTANGULAR BOX
C***  CALLED FROM SUBROUTINE KDPLOT
C***********************************************************************

      DIMENSION B(6), C(6)
      CHARACTER LINE*(*), ACTPAR*40, HTYPE
      SAVE X1UNITS, Y1UNITS, X2UNITS, Y2UNITS, XOFFSET, YOFFSET

      CALL DECXYUNITS  (LINE,  3, B, C, X1UNITS)
      CALL DECXYUNITS  (LINE,  4, B, C, Y1UNITS)
      CALL DECXYUNITS  (LINE,  5, B, C, X2UNITS)
      CALL DECXYUNITS  (LINE,  6, B, C, Y2UNITS)
      CALL SARGC (LINE, N)
      IF (N .GE. 7) THEN
         CALL DECFPNUM    (LINE,  7,       XOFFSET)
      ELSE
         XOFFSET = .0
      ENDIF
      IF (N .GE. 8) THEN
         CALL DECFPNUM    (LINE,  8,       YOFFSET)
      ELSE
         YOFFSET = .0
      ENDIF
      IF (N .GE. 9) THEN 
         CALL SARGV (LINE, 9, ACTPAR)
      ELSE
         ACTPAR = ' '
      ENDIF

C*** CONVERT INTO CM
      X1CM = (X1UNITS-B(2))*B(1) + XOFFSET
      Y1CM = (Y1UNITS-C(2))*C(1) + YOFFSET
      X2CM = (X2UNITS-B(2))*B(1) + XOFFSET
      Y2CM = (Y2UNITS-C(2))*C(1) + YOFFSET

C***  OPEN SYMBOL:
      CALL RECTA (X1CM, X2CM, Y1CM, Y2CM) 
C***  Filling Option
      IF (ACTPAR .EQ. 'FILLED') THEN
         CALL GFILL
      ELSEIF (ACTPAR .EQ. 'HATCHED') THEN
!         HATCHSEP = 8.0
!         IF (N .GE. 10) THEN
!            CALL DECFPNUM (LINE,  10, HATCHSEP)
!         ENDIF       
!         IF (N .GE. 11) THEN
!            CALL SARGV (LINE, 11, HTYPE)
!         ENDIF       
         CALL HFILL(LINE)
      ENDIF

      RETURN
      END





kd_lun.f/       1553528659  5006  320   100644  5231      `
      SUBROUTINE KD_LUN (LINE, ACTPAR, XLUNOFS, YLUNOFS, DYCMLUN, 
     >   DYSIZELUN, SIZELUN, B, C, XUNITS, YUNITS,
     >   TLUN, ITEM, BBGR, SIZEITEM, PPX, PPYdummy, YO2dummy, IBGRCOL,
     >   LASTCOLOR, BGRL, BGRR, BGRD, BGRU, ITEMSTRING, XINDENT, 
     >   BGRLINE)

C***********************************************************************
C***  KASDEF OPTIONS LUN / NEXTLUN / SAMELUN / LUNINC 
C***  CALLED FROM SUBROUTINE KDPLOT and KD_TAB (PROGRAM WRPLOT)
C***********************************************************************

      COMMON / COMIDEV / IDEV
      LOGICAL BLUNINC, BNEXT, ITEM, BBGR, BHATCH
      CHARACTER PPX*1, PPY*1, CC*1
C     14.02.2014 WRH, Helge: Why are PPYdummy and YO2dummy used?
      CHARACTER PPYdummy*1
      CHARACTER*(*) TLUN, ACTPAR, LINE
      CHARACTER*(*) BGRLINE
      CHARACTER ITEMSTRING*30, ACTPAR2*80
      CHARACTER LINE2*132, FTXTINC*255, FNAMINC*255
      DIMENSION B(6),C(6)

      BHATCH = .FALSE.  

      CALL SARGC (BGRLINE, NARG)
      DO I=1, NARG
         CALL SARGV (BGRLINE, I, ACTPAR2)
         IF (ACTPAR2 .EQ. 'HATCHED' .OR. ACTPAR2 .EQ. 'HTYPE') THEN
            BHATCH = .TRUE.
            EXIT
         ENDIF
      ENDDO
 
      BNEXT = (ACTPAR .EQ. 'NEXTLUN' .OR. ACTPAR .EQ. 'SAMELUN')
 
C***  Compensate for newline shift in case of SAMELUN
      IF (ACTPAR .EQ. 'SAMELUN') 
     >   YLUNOFS = YLUNOFS + DYCMLUN + DYSIZELUN * SIZELUN

      BLUNINC = (ACTPAR .EQ. 'LUNINC')

      IF (.NOT. BNEXT) THEN
         CALL DECXYUNITS  (LINE, 3, B, C, XUNITS)
         CALL DECXYUNITS  (LINE, 4, B, C, YUNITS)
         CALL DECFPNUMPRE (LINE, 5, XLUNOFS, PPX)
         CALL DECFPNUMPRE (LINE, 6, YLUNOFS, PPY)
         CALL DECFPNUM    (LINE, 7, SIZELUN)

         IF (.NOT. BLUNINC) THEN
            CALL SARGREST (LINE, N, 8, NSTART, NN)
            IF (NSTART .GT. 1) THEN
               TLUN = LINE(NSTART:NN)
            ELSE
	       TLUN = ' '
            ENDIF
         ELSE
            CALL SARGV (LINE, 8, FNAMINC)
            CALL SARGV (LINE, 9, TLUN)
            CALL SARGV (LINE, 10, FTXTINC)
            CALL MY_OPEN (50, FNAMINC, IERR)
	    IF (IERR .NE. 0) GOTO 101

  151       CONTINUE
            READ (50, '(A)', END=152) LINE2
            ID = IDX(FTXTINC)
            IF (FTXTINC( :ID) .EQ. LINE2( :ID)) THEN
               TLUN = TLUN( :IDX(TLUN)) // LINE2( :IDX(LINE2))
               GOTO 153
            ENDIF
            GOTO 151
  152       WRITE (*,*) 'Warning von KASDEF LUNINC:'
            WRITE (*,*) 'String ',FTXTINC( :IDX(FTXTINC)),' not found'
  153       CONTINUE
            CLOSE (50)
         ENDIF

C***  NEXTLUN
      ELSE
         PPY = 'U'
         CALL SARGREST (LINE, N, 3, NSTART,NN)
         IF (NSTART .GT. 1) THEN
            TLUN = LINE(NSTART:NN)
         ELSE
	    TLUN = ' '
	 ENDIF
      ENDIF

C***  CONVERT INTO CM
      IF (PPX .EQ. 'M') THEN
         CALL MYTLEN (TEXLEN, SIZELUN, TLUN, IDX(TLUN)) 
         XO2 = -TEXLEN / 2.
      ELSE IF (PPX .EQ. 'R') THEN
         CALL MYTLEN (TEXLEN, SIZELUN, TLUN, IDX(TLUN)) 
         XO2 = -TEXLEN
      ELSE
         XO2 = 0.
      ENDIF

      IF (PPY .EQ. 'M') THEN
         YO2 = -SIZELUN / 2.
      ELSE IF (PPY .EQ. 'U') THEN
         YO2 = -SIZELUN
      ELSE
         YO2 = 0.
      ENDIF
           
      XCM = (XUNITS-B(2)) * B(1) + XLUNOFS + XO2
      YCM = (YUNITS-C(2)) * C(1) + YLUNOFS + YO2

      IF (ITEM) THEN
         YCMITEM = (YUNITS-C(2)) * C(1) + YLUNOFS + 
     +             YO2 * SIZEITEM/SIZELUN
         CALL MYSYMBL (XCM, YCMITEM, SIZEITEM, ITEMSTRING, .0)
         XCM = XCM + XINDENT
      ENDIF          

C***  HINTERLEGEN DER SCHRIFT MIT EINEM FARBIG AUSGEFUELLTEN RECHTECK
      IF (BBGR) THEN
         CALL MYTLEN (TEXLEN, SIZELUN, TLUN, IDX(TLUN)) 
         BGRXL = XCM - SIZELUN*BGRL
         BGRXR = XCM + TEXLEN + SIZELUN*BGRR
         BGRYD = YCM - SIZELUN*BGRD
         BGRYU = YCM + SIZELUN*(BGRU+1)
C***     open box:
         LC2 = LASTCOLOR
         CALL COLOR ('DATA', 'DUMMY', ABS(IBGRCOL), IDEV)
         CALL RECTA (BGRXL, BGRXR, BGRYD, BGRYU)
C***     Filling Command 
         IF (IBGRCOL .GE. 0 .AND. .NOT. BHATCH) THEN
             CALL GFILL
         ELSEIF (BHATCH) THEN
             CALL HFILL(BGRLINE)
         ENDIF
         CALL COLOR ('DATA', 'DUMMY', LC2, IDEV)
      ENDIF

C***  Write output line
      CALL MYSYMBL (XCM, YCM, SIZELUN, TLUN, .0)
C***  Make newline space for next line 
C***      (Position at Upper Bound of next object)
      IF (PPY .EQ. 'U') THEN
         YLUNOFS = YLUNOFS - DYSIZELUN * SIZELUN - DYCMLUN 
      ELSE IF (PPY .EQ. 'M') THEN
         YLUNOFS = YLUNOFS - (DYSIZELUN - .5) * SIZELUN - DYCMLUN
      ELSE
         YLUNOFS = YLUNOFS - (DYSIZELUN - 1.) * SIZELUN - DYCMLUN
      ENDIF      
      
      RETURN

C**********************************************************************
C***  EROR BRANCHES
C**********************************************************************
96    WRITE(*,'(A)') 'ERROR OCCURED IN THE FOLLOWING LINE:'
      WRITE(*,'(A)') LINE(:IDX(LINE))
      STOP 'ERROR IN KD_LUN'

101   WRITE (*,*) 'Error when opening File: ',FNAMINC( :IDX(FNAMINC)),
     >            ' in Line: ',LINE( :IDX(LINE))
      STOP 'ERROR IN KD_LUN'

      END

decfpnumpost.f/ 1553528659  5006  320   100644  1451      `
      SUBROUTINE DECFPNUMPOST (LINE, IARG, BC, VALUE)
C**********************************************************************
C***  Decodes a floting-point type argument from LINE
C***  ALLOWS THE USE OF THE "SAME" KEYWORD
C***  and the prefixes LOG and DEX
C***  and the Postfix U (for Units)
C***  Note that there exists a special SUBR. DECXYUNITS for X, Y 
C**********************************************************************
      CHARACTER LINE*(*), ACTPAR*40
      DIMENSION BC(6)

      CALL SARGV (LINE, IARG, ACTPAR)
      
      IF (ACTPAR(:4) .EQ. 'SAME') RETURN
      
      ID = IDX(ACTPAR)
C***  Postfix U: Apply scaling factor for Units
      IF (ACTPAR(ID:ID) .EQ. 'U') THEN 
         ACTPAR(ID:ID) = ' '
         F = BC(1)
      ELSE
         F = 1.	
      ENDIF 

      IF (ACTPAR(1:3) .EQ. 'LOG') THEN
         READ (ACTPAR(4: ), '(F10.0)') VALUE
         VALUE = ALOG10 (VALUE)
      ELSE IF (ACTPAR(1:3) .EQ. 'DEX') THEN
         READ (ACTPAR(4: ), '(F10.0)') VALUE
         VALUE = 10. ** (VALUE)
      ELSE
         READ (ACTPAR, '(F20.0)', ERR=99) VALUE
      ENDIF

      VALUE = VALUE * F

      RETURN

   99 PRINT *, '*** ERROR IN KASDEF OPTION: ***'
      PRINT *, '>>> ', ACTPAR(:IDX(ACTPAR)), 
     >         ' <<<< CANNOT BE DECODED AS FLOATING POINT NUMBER!'
      PRINT *, 'THE ERROR OCCURED IN THE FOLLOWING LINE:'
      PRINT *, LINE(:IDX(LINE))
      STOP '*** ERROR IN SUBROUTINE DECFPNUMPOST ***'

      END


kd_linrel.f/    1553528659  5006  320   100644  2460      `
      SUBROUTINE KD_LINREL (B, C, LINE, XUNITS, YUNITS, 
     >                      XOFFSET, YOFFSET, VAR, MAXVAR, NVAR)

C***********************************************************************
C***  WRPLOT PROGRAM:
C***  KASDEF OPTIONS  FOR PLOTTING A LINE (LENGTH IN CM)
C***  CALLED FROM SUBROUTINE KDPLOT
C***********************************************************************

      DIMENSION B(6), C(6)
      DIMENSION XUNA(3), YUNA(3), XCMA(3), YCMA(3),SCRATCH(3)
      CHARACTER LINE*(*), ACTPAR*40  
      CHARACTER*(*) VAR(MAXVAR,2)
      SAVE XREL, YREL 

C***  Default SIZE and SYMBOL
      SILIUN = 0.5
      ISYUNA = 5

      CALL DECXYUNITS  (LINE,  3, B, C, XUNITS)
      CALL DECXYUNITS  (LINE,  4, B, C, YUNITS)
      CALL DECFPNUMPOST(LINE,  5, B, XREL)
      CALL DECFPNUMPOST(LINE,  6, C, YREL)
C***  Note: Offset parameters did not exist in early WRPLOT versions
      CALL SARGC (LINE, NPAR)
      IF (NPAR .GT. 7) THEN
         CALL DECFPNUM    (LINE,  7, XOFFSET)
         CALL DECFPNUM    (LINE,  8, YOFFSET)
      ELSE
         XOFFSET = .0
         YOFFSET = .0
      ENDIF

C***  Read optional specification of SYMBOL and/or SIZE
      DO 245 I=9, NPAR, 2
        CALL SARGV (LINE, I, ACTPAR)
        IF (ACTPAR .EQ. 'SIZE') THEN
           CALL SARGV (LINE, I+1, ACTPAR)
           READ (ACTPAR, '(F20.0)', ERR=96) SILIUN
        ELSE IF (ACTPAR .EQ. 'SYMBOL') THEN
           CALL SARGV (LINE, I+1, ACTPAR)
           READ (ACTPAR,'(I20)', ERR=96) ISYUNA
        ENDIF
  245 CONTINUE

C***
      XUNA(1) = XUNITS + XOFFSET/B(1)
      XUNA(2) = XUNITS + (XOFFSET+XREL)/B(1)
      YUNA(1) = YUNITS + YOFFSET/C(1)
      YUNA(2) = YUNITS + (YOFFSET+YREL)/C(1)
      CALL PLOTDAT (XUNA, YUNA, 2, ISYUNA, SILIUN, XCMA, YCMA,
     >                 B, C, SCRATCH, 'UNIT', VAR, MAXVAR, NVAR,
     >                 DUMMY, IDUMMY, ' ')

C***
c         PX1 = (XUNITS-B(2)) * B(1) + XOFFSET
c         PX2 = PX1 + XREL
c         PY1 = (YUNITS-C(2)) * C(1) + YOFFSET
c         PY2 = PY1 + YREL
c         CALL GPLOT(PX1, PY1, 3)
c         CALL GPLOT(PX2, PY2, 2)

      RETURN

C**********************************************************************
C***  EROR BRANCH
C**********************************************************************
96    WRITE(*,'(A)') 'ERROR WHEN DECODING A PARAMETER'
      WRITE(*,'(A)') 'THE ERROR OCCURED IN THE FOLLOWING LINE:'
      WRITE(*,'(A)') LINE(:IDX(LINE))
      STOP 'ERROR IN KD_LINREL'

      END
kd_arr.f/       1553528659  5006  320   100644  5395      `
      SUBROUTINE KD_ARR (B, C, LINE, XUNITS, YUNITS, ARROX, ARROY)

C***  KASDEF ARR (DRAWING OF ARROWS) ******************   
C***  DIFFERENT MODI ARE AVAILABLE
C***  MODUS              OFFSET                         DIRECTION
C***    0                OFFSET AS GIVEN                AS GIVEN
C***    1                OFFSET IN DIRECTION OF ARROW   AS GIVEN
C***    2                OFFSET AS GIVEN                ENDPOSITION = X+LENGTH
C***                                                                = Y+ANGLE
C***    3                OFFSET IN DIRECTION OF ARROW   ENDPOSITION = X+LENGTH
C***                                                                = Y+ANGLE
C***    4                AS 2                           AS2, BUT ENDPOSITION IN 
C***                                                                UNITS
C***    5                AS 3  (NOT VALID SOFAR!!!)     AS2, BUT ENDPOSITION IN 
C***                                                                UNITS

      DIMENSION B(6), C(6)
      CHARACTER LINE*(*), ACTPAR*40, ACTPAR2*40  
      LOGICAL BARRFIL, BARRBAR, BSHRCM, BHATCH
      SAVE ARRLX, ARRLY, ARRS

      COMMON / COMPEN /LASTPEN, HALFLINW

      CALL DECXYUNITS   (LINE,  3, B, C, XUNITS)
      CALL DECXYUNITS   (LINE,  4, B, C, YUNITS)
      CALL DECFPNUMPOST (LINE,  5, B,    ARRLX )
      CALL DECFPNUMPOST (LINE,  6, C,    ARRLY )
      CALL DECFPNUM     (LINE,  7,       ARRS  )
      CALL DECFPNUM     (LINE,  8,       ARROX )
      CALL DECFPNUM     (LINE,  9,       ARROY )
      CALL DECINUM      (LINE, 10,       MODARR)
      IF (MODARR .GT. 5 .OR. MODARR .LT. 0) THEN
         WRITE (*,*) 'MODARR=', MODARR, 'NOT VALID'
         STOP 'ERROR IN SUBR. KD_ARR'
      ENDIF
      CALL SARGC (LINE, N)

      I = 11
      BARRFIL = .FALSE.
      BARRBAR = .FALSE.
      ARRSHR = 1.
      BSHRCM = .FALSE.
      BHATCH = .FALSE.

  165 IF (I .GT. N) GOTO 164
         CALL SARGV (LINE, I, ACTPAR)
         CALL SARGV (LINE, I+1, ACTPAR2)
         IF (ACTPAR .EQ. 'FILLED') THEN
            BARRFIL = .TRUE.
            I = I + 1
         ELSEIF (ACTPAR .EQ. 'HATCHED' .OR. ACTPAR .EQ. 'HTYPE') THEN
            BHATCH = .TRUE.
            I = I + 1
         ELSE IF (ACTPAR .EQ. 'BAR') THEN
            BARRBAR = .TRUE.
            I = I + 1
         ELSE IF (ACTPAR .EQ. 'SHRINK') THEN
            ARRSHR = 1.0
            ID = IDX(ACTPAR2)
            IF (ACTPAR2(ID-1:ID) .EQ. 'CM') THEN
               BSHRCM = .TRUE.
               ACTPAR2 = ACTPAR2( :ID-2)
            ENDIF
            READ (ACTPAR2, '(F20.0)', ERR=96) ARRSHR
            I = I + 2
         ELSE
            I = I + 1
         ENDIF
         GOTO 165

  164    CONTINUE
C***  UMRECHNUNG VON LAENGE UND WINKEL IN DELTA-X UND DELTA-Y
        IF (MODARR .EQ. 0 .OR. MODARR .EQ. 1) THEN
          TX = ARRLX
          TY = ARRLY / 180. * 3.1415927
          ARRLX2 = TX * COS(TY) * SIGN(1., TY)
          ARRLY2 = TX * SIN(TY)
        ELSE IF (MODARR .EQ. 4 .OR. MODARR .EQ. 5) THEN
          ARRLX = ARRLX - XUNITS
          ARRLY = ARRLY - YUNITS
          ARRLX2 = ARRLX * B(1)
          ARRLY2 = ARRLY * C(1)
        ELSE
          ARRLX2 = ARRLX
          ARRLY2 = ARRLY
        ENDIF
        ARRL = SQRT(ARRLX2*ARRLX2 + ARRLY2*ARRLY2)

C***  FALLS MODARR=1 DANN VERSCHIEBUNG DES PFEILS SEINE RICHTUNG 
C***  VERSCHIEBELAENGE = ARROX
      IF (MODARR .EQ. 1 .OR. MODARR .EQ. 3) THEN
        ARROY2 = ARROX * SIN(TY)
        ARROX2 = ARROX * COS(TY)
      ELSE
        ARROX2 = ARROX
        ARROY2 = ARROY
      ENDIF
C***  UMRECHNUNG DES STARTPUNKTES VON UNITS IN CM
        PX = (XUNITS-B(2))*B(1) + ARROX2
        PY = (YUNITS-C(2))*C(1) + ARROY2

C***  APPLY SHRINK PARAMETER
        IF (BSHRCM) THEN
          F = (1. - (1. - ARRSHR/ARRL)) / 2.
        ELSE
          F = (1. - ARRSHR) / 2.
        ENDIF
        PX = PX + F*ARRLX2
        PY = PY + F*ARRLY2
        ARRLX2 = (1.-2.*F) * ARRLX2
        ARRLY2 = (1.-2.*F) * ARRLY2

      CALL GPLOT(PX,PY,3)

C***  PLOT DES GROSSEN STRICHS
C***  Make the arrow shorter in the peak
C***  28.4 = CMPT
        DL = 4. * HALFLINW / 28.4
        FL = 1. - (DL / SQRT(ARRLX2*ARRLX2 + ARRLY2*ARRLY2))
        PX2 = PX + ARRLX2 * FL
        PY2 = PY + ARRLY2 * FL
        CALL GPLOT(PX2, PY2, 2)
        PX = PX + ARRLX2
        PY = PY + ARRLY2
        CALL GPLOT(PX,PY,3)
C***  Offset der Enden der Pfeil-Striche 
        VL = SQRT (ARRLX2*ARRLX2 + ARRLY2*ARRLY2)
        VX = -ARRLX2 * ARRS / VL
        VY = -ARRLY2 * ARRS / VL
        VX2 = VY / 3.
        VY2 = -VX / 3.

      CALL GPLOT(PX+VX+VX2, PY+VY+VY2, 3)
      CALL GPLOT(PX,PY,2)
      VX2 = -VY / 3.
      VY2 = VX / 3.
      CALL GPLOT(PX+VX+VX2, PY+VY+VY2, 2)
C***  WHEN FILLED ARROW
      IF (BARRFIL) THEN
         CALL GPLOT(PX+0.9*VX, PY+0.9*VY, 2)         
         CALL GFILL
      ELSEIF (BHATCH) THEN
         CALL GPLOT(PX+0.9*VX, PY+0.9*VY, 2)         
         CALL HFILL(LINE)
        ENDIF

C***  PLOT DES FUSSES (IF REQUIRED)
        IF (BARRBAR) THEN
          CALL GPLOT(PX-ARRLX2+VY/2.,PY-ARRLY2-VX/2.,3)
          CALL GPLOT(PX-ARRLX2-VY/2.,PY-ARRLY2+VX/2.,2)
        ENDIF
      RETURN
      
C***  ERROR BRANCH
   96 CONTINUE
      WRITE (*,'(A)') 'THE FOLLOWING PARAMETER COULD NOT BE ' // 
     >                'DECODED AS A FLOATING POINT NUMBER: '
      WRITE (*,'(A)') ACTPAR 
      STOP 'ERROR IN KD_ARR'
     


      END
      

kd_rectlun.f/   1553528659  5006  320   100644  3766      `
      SUBROUTINE KD_RECTLUN (B, C, LINE, XUNITS, YUNITS, PPX, PPY, 
     >                       XLUNOFS, YLUNOFS)

C***********************************************************************
C***  WRPLOT PROGRAM:
C***  KASDEF OPTIONS  FOR PLOTTING A RECTANGULAR BOX
C***  --  second, alternative parameter version!
C***  CALLED FROM SUBROUTINE KDPLOT
C***********************************************************************

      DIMENSION B(6), C(6)
      CHARACTER LINE*(*), ACTPAR*40  
      CHARACTER PPX*1, PPY*1, PPXRECT*1, PPYRECT*1
      LOGICAL BFILLED, BCYCLE, BHATCH
      SAVE HOEHE, BREITE, XRECTOFS, YRECTOFS, PPXRECT, PPYRECT

C***  Note: OFFSET parameters als impoted with SAME, but not exported
      PPXRECT = PPX
      PPYRECT = PPY
      XRECTOFS = XLUNOFS
      YRECTOFS = YLUNOFS
      BFILLED = .FALSE.
      BCYCLE  = .FALSE.
      BHATCH  = .FALSE.
      ALPHA = .0

      CALL DECXYUNITS  (LINE,  3, B, C, XUNITS )
      CALL DECXYUNITS  (LINE,  4, B, C, YUNITS )
      CALL DECFPNUMPRE (LINE,  5, XRECTOFS, PPXRECT )
      CALL DECFPNUMPRE (LINE,  6, YRECTOFS, PPYRECT )
      CALL DECFPNUMPOST(LINE,  7, B,      BREITE )
      CALL DECFPNUMPOST(LINE,  8, C,      HOEHE  )
      CALL SARGC (LINE, N)
      DO I = 9, N
         IF (BCYCLE) THEN
            BCYCLE = .FALSE.
	    CYCLE
	 ENDIF
         CALL SARGV (LINE, I, ACTPAR)
         IF (ACTPAR .EQ. 'FILLED') THEN 
            BFILLED = .TRUE.
         ELSE IF (ACTPAR .EQ. 'HATCHED' ) THEN
            BHATCH = .TRUE.        
         ELSE IF (ACTPAR .EQ. 'HTYPE') THEN 
            BHATCH = .TRUE.
            BCYCLE = .TRUE.
         ELSE IF (ACTPAR .EQ. 'HW') THEN
            BHATCH = .TRUE.
            BCYCLE = .TRUE.
         ELSE IF (ACTPAR .EQ. 'HSEP') THEN
            BHATCH = .TRUE.
            BCYCLE = .TRUE.
         ELSE IF (ACTPAR .EQ. 'ROTATE') THEN
            IF (I+1 .GT. N) GOTO 99
            CALL SARGV (LINE, I+1, ACTPAR)
            READ (ACTPAR, '(F20.0)', ERR=99) ALPHA
            BCYCLE = .TRUE.
         ELSE 
            GOTO 99
         ENDIF
      ENDDO


C***  CONVERT INTO CM
      IF (PPXRECT .EQ. 'M') THEN
         XO1 = -BREITE / 2.
      ELSE IF (PPXRECT .EQ. 'R') THEN
         XO1 = -BREITE
      ELSE
         XO1 = 0.
      ENDIF
      IF (PPYRECT .EQ. 'M') THEN
         YO1 = -HOEHE / 2.
      ELSE IF (PPYRECT .EQ. 'U') THEN
         YO1 = -HOEHE
      ELSE
         YO1 = 0.
      ENDIF
      XO2 = XO1 + BREITE
      YO2 = YO1 + HOEHE
      CALL TURN (X1, Y1, XO1, YO1, ALPHA) 
      CALL TURN (X2, Y2, XO2, YO1, ALPHA) 
      CALL TURN (X3, Y3, XO2, YO2, ALPHA) 
      CALL TURN (X4, Y4, XO1, YO2, ALPHA) 
      X1CM = (XUNITS-B(2)) * B(1) + XRECTOFS + X1
      Y1CM = (YUNITS-C(2)) * C(1) + YRECTOFS + Y1
      X2CM = (XUNITS-B(2)) * B(1) + XRECTOFS + X2
      Y2CM = (YUNITS-C(2)) * C(1) + YRECTOFS + Y2
      X3CM = (XUNITS-B(2)) * B(1) + XRECTOFS + X3
      Y3CM = (YUNITS-C(2)) * C(1) + YRECTOFS + Y3
      X4CM = (XUNITS-B(2)) * B(1) + XRECTOFS + X4
      Y4CM = (YUNITS-C(2)) * C(1) + YRECTOFS + Y4

C***  OPEN SYMBOL:
      CALL GCPLOT (X1CM, Y1CM, 3)
      CALL GCPLOT (X2CM, Y2CM, 2)
      CALL GCPLOT (X3CM, Y3CM, 2)
      CALL GCPLOT (X4CM, Y4CM, 2)
      CALL GCPLOT (X1CM, Y1CM, 2)
C***  Filling Option
      IF (BFILLED) THEN
          CALL GFILL
      ELSEIF (BHATCH) THEN
          CALL HFILL(LINE)
      ENDIF 

      RETURN
      
C**********************************************************************
C***  EROR BRANCHES
C**********************************************************************
99    WRITE(*,'(//,A)') '*** ERROR: UNRECOGNIZED OR MISSING PARAMETER '
      WRITE(*,'(A)') 'THE ERROR OCCURED IN THE FOLLOWING LINE:'
      WRITE(*,'(A)') LINE(:IDX(LINE))
      STOP 'ERROR IN KD_RECTLUN'

      END
