flushleft.f/    1553528659  5006  320   100644  289       `
      SUBROUTINE FLUSHLEFT (STRING)
C***  Macht einen String linksbuendig
      CHARACTER STRING*(*)
      DO I=1, LEN(STRING)
         IFIRST = I
	 IF (STRING(I:I) .NE. ' ') GOTO 1
      ENDDO
      
      RETURN
      
    1 STRING = STRING(IFIRST:)
      RETURN
      END
      
      

kd_calc.f/      1553528659  5006  320   100644  12268     `
      SUBROUTINE KD_CALC (LINEORIG, B, C, VAR, MAXVAR, NVAR, CALC_DEBUG)
C**********************************************************
C***  KASDEF option to calculate an arithmetic expression
C***  KASDEF CALC var = par(1) par(2) .... par(npar) 
C**********************************************************
      CHARACTER LINEORIG*(*), LINE*1000
      CHARACTER*1 LASTCHAR, NEXTCHAR, OPER
      PARAMETER ( MAXPAR = 200 )
      CHARACTER*20 PARLEFT, PAR(MAXPAR), FUN
      CHARACTER*(*) VAR(MAXVAR,2), CIVAR*3
      LOGICAL CHRINSTR, SKIPNEXTCHAR, CALC_DEBUG
      DIMENSION IPAR(MAXPAR), LEVOP(MAXPAR), NEXTOP(MAXPAR)
      DATA DEG /0.017453293/
      DATA NEWSEED / 0 /

      IF (CALC_DEBUG) WRITE (*,'(/,A,/,A)') 'KD_CALC debugging output:',  
     >                                  LINEORIG(:IDX(LINEORIG))


C***  Entfernen aller Blanks (ab der rechten Seite = Argument 4)
C***  Gleichzeitig werden ** durch ^ ersetzt (Exponentiation), 
C***  unzulaessige Zeichen moniert 
C***  und alle Kleinbuchstaben (Funktionen!) in grosse Buchstaben umgesetzt
      CALL SARGP (LINEORIG, NARG, 4, IFIRST, ILAST)
      II = IFIRST-1
      LINE = LINEORIG(:IFIRST-1)
      DO I=IFIRST, IDX(LINEORIG)
         OPER = LINEORIG(I:I)
         IF (OPER .EQ. ' ') CYCLE
         IF (OPER .EQ. '*') THEN
            IF (LINE(II:II) .EQ. '*') THEN
               LINE(II:II) = '^'
	           CYCLE
            ENDIF
         ENDIF 
         IF (CHRINSTR(OPER,',:=')) GOTO 94
         IOPER = ICHAR(OPER)
         IF (IOPER .GE. 97 .AND. IOPER .LE. 122) OPER=CHAR(IOPER-32)
         II = II + 1
         LINE(II:II) = OPER
      END DO
      LINEORIG = LINE

      IF (CALC_DEBUG) WRITE (*,'(A)') LINE(:IDX(LINE))

      
C***  Einfuegen von Blanks zur Vorbereitung des Parse
      II = 0
      LINE = ' '
      LASTCHAR = '='
      SKIPNEXTCHAR = .FALSE. 
      DO I=1, IDX(LINEORIG)
         IF (SKIPNEXTCHAR) THEN 
            SKIPNEXTCHAR = .FALSE.
            CYCLE
         ENDIF
         II = II + 1
         OPER = LINEORIG(I:I)
         IF (CHRINSTR(OPER, '*/+-()^')) THEN
C*** +- directly behind E or e is sign of exponent - no blanks inserted 
            IF (CHRINSTR(OPER, '+-') 
     >         .AND. LASTCHAR .EQ. 'E' ) THEN
               LINE(II:II) = OPER     
C*** - directly behind [ is sign of an index - no blanks inserted 
            ELSE IF (OPER .EQ. '-' .AND. LASTCHAR .EQ. '[' ) THEN
               LINE(II:II) = OPER     
C***  +- nach */^ ist Vorzeichen - Kein Blank rechts davon 
            ELSE IF (CHRINSTR(OPER, '+-') 
     >         .AND. CHRINSTR(LASTCHAR, '*/+-^') ) THEN
               LINE(II:II) = ' '
               II = II + 1
C***           falls die nachfolgende Zahl schon ein Vorzeichen hat:
               NEXTCHAR = LINEORIG(I+1:I+1)
               IF (CHRINSTR(NEXTCHAR,'+-')) THEN  
                  SKIPNEXTCHAR = .TRUE.
                  IF (OPER .EQ. NEXTCHAR) THEN 
                     OPER = '+'
                  ELSE
                     OPER = '-'
                  ENDIF
               ENDIF
               LINE(II:II) = OPER
C***  +- nach ( oder am Beginn ist Operator --> ersetzt durch "0 + "  
            ELSE IF (CHRINSTR(OPER, '+-') 
     >         .AND. CHRINSTR(LASTCHAR, '(=') ) THEN
               LINE(II:II+2) = '0 ' // OPER // ' '
               II = II + 3
C***  Sonst: rechts und links Blank einfuegen 
            ELSE
               LINE(II:II) = ' '
               II = II + 1
               LINE(II:II) = OPER
               II = II + 1
               LINE(II:II) = ' '
            ENDIF
            LASTCHAR = OPER
            CYCLE
         ENDIF
         LINE(II:II) = OPER
         IF (OPER .NE. ' ') LASTCHAR = OPER
      ENDDO

      IF (CALC_DEBUG) WRITE (*,'(A)') LINE(:IDX(LINE))

      CALL SARGC (LINE, N)
      NPAR = N - 3
      IF (NPAR .LT. 1) GOTO 97
      IF (NPAR . GT. MAXPAR) GOTO 98

C***  STORE PARAMETERS, FIND POSITION OF OPERATORS AND DETERMINE THEIR LEVEL
      NOP = 0
      LEVEL=1
      DO I=1, NPAR
        CALL SARGV(LINE, I+3, PAR(I))
        IF (PAR(I)(1:1) .EQ. '(') THEN
	   LEVEL = LEVEL + 3
	ELSE IF (PAR(I)(1:1) .EQ. ')') THEN
	   LEVEL = LEVEL - 3
        ELSE IF (CHRINSTR(PAR(I)(1:1),'+-*/^')
     >              .AND. PAR(I)(2:2) .EQ. ' ') THEN
            NOP = NOP + 1
            IPAR(NOP) = I
            IF (CHRINSTR(PAR(I)(1:1),'*/')) THEN 
               LEVOP(NOP)= LEVEL + 1
            ELSE IF (PAR(I)(1:1) .EQ. '^') THEN
               LEVOP(NOP)= LEVEL + 2
            ELSE
	       LEVOP(NOP)= LEVEL
            ENDIF
        ENDIF
      END DO
      IF (LEVEL .NE. 1) GOTO 96

C***  FESTLEGEN DER REIHENFOLGE DER OPERATIONEN GEMAESS LEVEL 
C***  NEXTOP(INEXT) gibt die Parameter-Position der Operatoren 
C***    in der abzuarbeitenden Reihenfolge
      MAXLEVEL = LEVOP(1)
      MINLEVEL = LEVOP(1)
      DO IOP=2, NOP
         MAXLEVEL = MAX0 (MAXLEVEL, LEVOP(IOP))
         MINLEVEL = MIN0 (MINLEVEL, LEVOP(IOP))
      END DO

      INEXT = 0
      DO I = MAXLEVEL, MINLEVEL, -1
         DO IOP=1, NOP
	    IF (LEVOP(IOP) .EQ. I) THEN 
               INEXT = INEXT + 1
	       NEXTOP(INEXT) = IOP
	    ENDIF
	 END DO
      END DO


C***********  Loop over operations in appropriate order ***********
      DO 10 INEXT=0, NOP+1

      IF (CALC_DEBUG) 
     > WRITE (*,'(A,I3,41(1X,A))') 'INEXT=', INEXT, ' ... =', 
     >                             (PAR(I)(:IDX(PAR(I))),I=1,NPAR) 

c      do iinext=1, nop
c         write (*, '(4I4)') 
c     >    iinext, nextop(iinext), ipar(nextop(iinext)), 
c     >    levop(nextop(iinext))
c      enddo

C***  Entferne ueberfluessige Klammerpaare
   20 CONTINUE
      DO I=1, NPAR-2
         IF (PAR(I)(:1) .EQ. '(' .AND. PAR(I+2)(:1) .EQ. ')' ) THEN
C***        SHIFT REST OF THE PARAMETERS TO FILL THE RESULT
C***        AND CORRECT IPAR POSITIONS ACCORDINGLY
C***         ... wenn vor der Klammer ein Funktionsaufruf steht:

            IFUN = 0
            IF (I .EQ. 1) GOTO 25
	    IF (IDX(PAR(I-1)) .EQ. 1 .AND. 
     >                 CHRINSTR(PAR(I-1),'+-*/^(')) GOTO 25
            FUN = PAR(I-1)
	    FUNSIGN = 1.
            IF (FUN(1:1) .EQ. '+') THEN
               FUN = FUN(2:)
            ELSE IF (FUN(1:1) .EQ. '-') THEN
               FUN = FUN(2:)
               FUNSIGN = -1. 
            ENDIF
	    IF      (FUN .EQ. 'SIN' ) THEN
               READ  (PAR(I+1), '(F20.0)', ERR=99) VALUE1
               WRITE (PAR(I+1), '(G20.7)') FUNSIGN * SIN(DEG*VALUE1)
            ELSE IF (FUN .EQ. 'COS' ) THEN
               READ  (PAR(I+1), '(F20.0)', ERR=99) VALUE1
               WRITE (PAR(I+1), '(G20.7)') FUNSIGN * COS(DEG*VALUE1)
            ELSE IF (FUN .EQ. 'ATAN' ) THEN
               READ  (PAR(I+1), '(F20.0)', ERR=99) VALUE1
               WRITE (PAR(I+1), '(G20.7)') FUNSIGN * ATAN(VALUE1) / DEG
            ELSE IF (FUN .EQ. 'LOG' ) THEN
               READ  (PAR(I+1), '(F20.0)', ERR=99) VALUE1
               WRITE (PAR(I+1), '(G20.7)') FUNSIGN * ALOG10(VALUE1)
            ELSE IF (FUN .EQ. 'LN' ) THEN
               READ  (PAR(I+1), '(F20.0)', ERR=99) VALUE1
               WRITE (PAR(I+1), '(G20.7)') FUNSIGN * ALOG(VALUE1)
            ELSE IF (FUN .EQ. 'DEX' ) THEN
               READ (PAR(I+1), '(F20.0)', ERR=99) VALUE1
               WRITE (PAR(I+1), '(G20.7)') FUNSIGN * 10.**VALUE1
            ELSE IF (FUN .EQ. 'EXP' ) THEN
               READ (PAR(I+1), '(F20.0)', ERR=99) VALUE1
               WRITE (PAR(I+1), '(G20.7)') FUNSIGN * EXP(VALUE1)
            ELSE IF (FUN .EQ. 'SQRT' ) THEN
               READ (PAR(I+1), '(F20.0)', ERR=99) VALUE1
               WRITE (PAR(I+1), '(G20.7)') FUNSIGN * SQRT(VALUE1)
            ELSE IF (FUN .EQ. 'ABS' ) THEN
               READ (PAR(I+1), '(F20.0)', ERR=99) VALUE1
               WRITE (PAR(I+1), '(G20.7)') FUNSIGN * ABS(VALUE1)
            ELSE IF (FUN .EQ. 'RAND' ) THEN
               READ (PAR(I+1), '(F20.0)', ERR=99) VALUE1
               IF (NEWSEED .EQ. 0 .AND. VALUE1 .NE. 0) THEN
                  CALL SYSTEM_CLOCK(ICOUNT)
C                 remove all leading digits but the last 5
                  ISEED = ICOUNT - (ICOUNT/100000)*100000                  
                  CALL SRAND(ISEED)
                  NEWSEED = 1
               ENDIF
               WRITE (PAR(I+1), '(G20.7)') FUNSIGN * RAND(0)

            ELSE IF (FUN .EQ. 'INT' ) THEN
               READ (PAR(I+1), '(F20.0)', ERR=99) VALUE1
               WRITE (PAR(I+1), '(I10)') INT(FUNSIGN) * INT(VALUE1)
            ELSE IF (FUN .EQ. 'NINT' ) THEN
               READ (PAR(I+1), '(F20.0)', ERR=99) VALUE1
               WRITE (PAR(I+1), '(I10)') INT(FUNSIGN) * NINT(VALUE1)
            ELSE 
               GOTO 95
            ENDIF

	    IFUN = 1
            CALL FLUSHLEFT (PAR(I+1))


C***        No Function call
   25       CONTINUE 
            NPAR = NPAR - 2 
            PAR(I-IFUN) = PAR(I+1)
            DO II=I+1, NPAR
               PAR(II-IFUN) = PAR(II+2)
            END DO
	    NPAR = NPAR - IFUN
            DO II=1, NOP
               IF (IPAR(II) .GT. I) IPAR(II) = IPAR(II) - 2 - IFUN
            END DO
            IF (CALC_DEBUG) WRITE (*,'(41(1X,A))') 
     >        '() REMOVED:   =', (PAR(III)(:IDX(PAR(III))),III=1,NPAR) 
            GOTO 20
         END IF
      END DO 

      IF (INEXT .EQ. 0) CYCLE
      IF (INEXT .EQ. NOP+1) CYCLE

      IOP      = IPAR(NEXTOP(INEXT))

      OPER = PAR(IOP)(1:1)

C***  MAKE ONE OPERATION
      READ (PAR(IOP-1), '(F20.0)', ERR=99) VALUE1
      READ (PAR(IOP+1), '(F20.0)', ERR=99) VALUE2

      IF (OPER .EQ. '+') THEN
         EX = VALUE1 + VALUE2
      ELSE IF (OPER .EQ. '-') THEN
         EX = VALUE1 - VALUE2
      ELSE IF (OPER .EQ. '*') THEN
         EX = VALUE1 * VALUE2
      ELSE IF (OPER .EQ. '/') THEN
         EX = VALUE1 / VALUE2
      ELSE IF (OPER .EQ. '^') THEN
C***    Distinguish between integer and float exponent 
C***    (needed eg. for DEC compiler)
         IF (CHRINSTR('.',PAR(IOP+1))
     >       .OR. CHRINSTR('E',PAR(IOP+1))) THEN
            EX = VALUE1 ** VALUE2
         ELSE
            IVALUE2 = NINT(VALUE2)            
            EX = VALUE1 ** IVALUE2
         ENDIF
      ENDIF 

C*** STORE RESULT WHERE VALUE1 RESIDED AND FLUSHLEFT
      IF (EX .EQ. INT(EX)) THEN
         WRITE (PAR(IOP-1), '(I20)') INT(EX)
      ELSE
         WRITE (PAR(IOP-1), '(G20.7)') EX
      ENDIF
      CALL FLUSHLEFT (PAR(IOP-1))

C***  SHIFT REST OF THE PARAMETERS TO FILL THE RESULT
C***   AND CORRECT IPAR POSITIONS ACCORDINGLY
      NPAR = NPAR - 2
      DO I=IOP, NPAR
         PAR(I) = PAR(I+2)
      END DO 

      DO I=1, NOP
         IF (IPAR(I) .GT. IOP) IPAR(I) = IPAR(I) - 2
      END DO
            
   10 CONTINUE
C***  End-of-Loop *********************************

      IF (CALC_DEBUG) 
     > WRITE (*,'(41(1X,A))') 'Result:   ... =', 
     >                        (PAR(I)(:IDX(PAR(I))),I=1,NPAR) 

C***  STORE RESULT IN LEFT-SIDE PARAMETER
      CALL SARGV(LINEORIG, 3, PARLEFT)
      ILEFT = IVAR (PARLEFT, VAR, MAXVAR, NVAR, CIVAR)   
C***  Check if variable name is legal
      CALL VARLEGAL (LINEORIG, PARLEFT, 'CALC') 

      VAR(ILEFT,2) = PAR(1)




      RETURN

C***  ERROR BRANCHES  ******************************************

   94 PRINT *, '*** ERROR IN KASDEF OPTION: SYNTAX ERROR'
      PRINT *, '*** DELIMITER WITHIN ARITHM EXPRESSION: ', OPER
      GOTO 100 

   95 PRINT *, '*** ERROR IN KASDEF OPTION: SYNTAX ERROR'
      PRINT *, '*** THE FOLLOWING TERM IS NOT A FUNCTION: ', PAR(I-1) 
      GOTO 100

   96 PRINT *, '*** ERROR IN KASDEF OPTION: UNMATCHED PARANTHESES '
      IL = (LEVEL-1) / 3
      IF (IL .GT. 0) THEN
         WRITE (*,'(A,I3)') ' *** TOO MANY "(":', IL
      ELSE
         WRITE (*,'(A,I3)') ' *** TOO MANY ")":', -IL
      ENDIF
      GOTO 100      

   97 PRINT *, '*** ERROR IN KASDEF OPTION: NOT ENOUGH ARGUMENTS '
      GOTO 100
      
   98 PRINT *, '*** ERROR IN KASDEF OPTION: TOO MANY ARGUMENTS '
      GOTO 100
     
   99 PRINT *, '*** ERROR IN KASDEF OPTION: ************'
      PRINT *, 'PARAMETER CANNOT BE DECODED AS FLOATING ',
     >         'POINT NUMBER!'
      GOTO 100
 
 
  100 PRINT *, 'THE ERROR OCCURED IN THE FOLLOWING LINE:'
      PRINT *, LINEORIG(:IDX(LINEORIG))
      PRINT *, '**** ERROR STOP IN SUBROUTINE KD_CALC *****'
      STOP 'ERROR'
     
      END
plotcon.f/      1553528659  5006  320   100644  968       `
      SUBROUTINE PLOTCON (KANAL,X,Y,N,ISYMBOL)
C***********************************************************************
C***  DIESE ROUTINE DIENST ZUM EINTRAGEN EINER 2. ODER 3. FUNKTION IN DEN
C***  BEGONNENEN PLOT ( PLOTCON ) , BZW. AB ENTRY PLOTTAB ZUM EINTRAGEN
C***  DER ERSTEN FUNKTION
C***********************************************************************
      DIMENSION X(N),Y(N)

C*** Backspace last Line (current ENDE)
      BACKSPACE KANAL

      ENTRY PLOTTAB (KANAL,X,Y,N,ISYMBOL)

C***  CHECK FOR SMALL X- AND Y-VALUES
      DO I=1, N
        IF (ABS(X(I)) .LT. 1.E-30) X(I) = 0.
        IF (ABS(Y(I)) .LT. 1.E-30) Y(I) = 0.
      ENDDO

      WRITE (KANAL,1) N,ISYMBOL
    1 FORMAT (' N=',I5,'   PLOTSYMBOL=',I3)

      DO 3 I=1,N,5
      J=MIN0( 5,N-I+1)
      WRITE (KANAL,2) (X(I+L-1),L=1,J)
      WRITE (KANAL,2) (Y(I+L-1),L=1,J)
    2 FORMAT (1X, 5(G14.8,1X))
    3 CONTINUE

      WRITE (KANAL,4)
    4 FORMAT (' ENDE')

      RETURN
      END
plotanf.f/      1553528659  5006  320   100644  1572      `
      SUBROUTINE PLOTANF (KANAL,NPLOT,NHEAD,NX,NY,
     $ B1,B2,B3,B4,B5,B6,C1,C2,C3,C4,C5,C6,
     $ X,Y,N,ISYMBOL )
C***********************************************************************
C***  DIESE ROUTINE BEREITET EIN NEUES PLOTFILE ZUR UEBERTRAGUNG VOR
C***  DIE ANGEGEBENEN WERTE BESCHREIBEN DEN PLOTKASTEN
C***********************************************************************
      CHARACTER*(*) NPLOT,NHEAD,NX,NY

      WRITE (KANAL,1) NPLOT
      WRITE (KANAL, '(A)') 'KASDEF FONT=HELVET'
      WRITE (KANAL,2) NHEAD
      WRITE(KANAL,3) NX
      WRITE (KANAL,4) NY
    1 FORMAT (' PLOT   :',A)
    2 FORMAT (' HEADER :',A)
    3 FORMAT (' X-ACHSE:',A)
    4 FORMAT (' Y-ACHSE:',A)

C***  Special branch activating Lars' AUTO axes: set XMIN = XMAX!
      IF (B2 .EQ. B3) THEN
         WRITE (KANAL, 6)
    6   FORMAT (5X,
     $ 'MASSTAB    MINIMUM    MAXIMUM    TEILUNGEN  BESCHRIFT. DARUNTER'
     $  / ,' X: AUTO',/,' Y: ')
      ELSE IF (C2 .EQ. C3) THEN
        WRITE (KANAL,7) B1,B2,B3,B4,B5,B6
    7   FORMAT (5X,
     $ 'MASSTAB    MINIMUM    MAXIMUM    TEILUNGEN  BESCHRIFT. DARUNTER'
     $  / ,' X: ',6(G12.6,1X),/,' Y: AUTO')
      ELSE 
        WRITE (KANAL,5) B1,B2,B3,B4,B5,B6,C1,C2,C3,C4,C5,C6
    5   FORMAT (5X,
     $ 'MASSTAB    MINIMUM    MAXIMUM    TEILUNGEN  BESCHRIFT. DARUNTER'
     $  / ,' X: ',6(G12.6,1X),/,' Y: ',6(G12.6,1X))
      ENDIF

C***  No Dataset opened for Zero Length
      IF (N .GT. 0) THEN
        CALL PLOTTAB (KANAL,X,Y,N,ISYMBOL)
      ELSE
        WRITE (KANAL, '(A)') 'END'
      ENDIF

      RETURN
      END
adv_corrplot.f/ 1653500007  5006  320   100644  10225     `
      SUBROUTINE ADV_CORRPLOT
C************************************************************************
C***  ADVanced CorrPlot
C***  Plots the Corrections (based on extended Gamma History)
C************************************************************************

      PARAMETER (MAXDAT = 10000)

      CHARACTER*132 LINE, LINE2, FNAME, HEADLINE, JOBNAME, CHEAD
      CHARACTER*20 ACTPAR(100)
      CHARACTER*40 CX, CY
      CHARACTER*1 BACKSLASH
      DIMENSION YFLAT(MAXDAT)
      LOGICAL BHEADREAD, BJOBREAD

      TYPE DTD_DATA
        SEQUENCE
        INTEGER                    :: N
        REAL, DIMENSION(MAXDAT)    :: X
        REAL, DIMENSION(MAXDAT)    :: Y
        LOGICAL, DIMENSION(MAXDAT) :: BSPEC
      END TYPE DTD_DATA            
      TYPE DTD_GCHANGE
        SEQUENCE
        INTEGER :: N
        REAL, DIMENSION(MAXDAT)         :: X
        CHARACTER*16, DIMENSION(MAXDAT) :: CHAR
      END TYPE DTD_GCHANGE
      TYPE DTD_SMOOTH
        INTEGER :: N
        REAL, DIMENSION(MAXDAT)         :: X
      END TYPE DTD_SMOOTH

      TYPE(DTD_DATA) DT_CORR, DT_CORRSL, DT_SCORR, DT_EX, DT_EXSL, 
     >               DT_SEX, DT_COLIP
      TYPE(DTD_GCHANGE) DT_GCHANGE
      TYPE(DTD_SMOOTH) DT_SMOOTH

      BACKSLASH = CHAR(92)
      FNAME     = 'gahist_ext.dat'
      BHEADREAD = .FALSE.
      BJOBREAD  = .FALSE.

C***  Reset Counter
      DT_CORR%N    = 0
      DT_CORRSL%N  = 0
      DT_SCORR%N   = 0
      DT_EX%N      = 0
      DT_EXSL%N    = 0
      DT_SEX%N     = 0
      DT_GCHANGE%N = 0
      JOBNUM = -1
      JOBNUM_LAST = -1
      GAMMA_LAST = 0.
      DT_SMOOTH%N = 0
      YFLAT = 0.

      OPEN (UNIT=1, FILE=FNAME, STATUS='OLD', ERR=100)
C***  Read until Gamma History starts
      DO
        READ (1,'(A)', END=105) LINE
        DO IARG=1, 10             
          CALL SARGV(LINE, IARG, ACTPAR(IARG))
        ENDDO
C***  Store Lines which start with 'MODEL' 'START'
        IF (ACTPAR(1) .EQ. 'MODEL' .AND. ACTPAR(2) .EQ. 'START' .AND. 
     >     .NOT. BHEADREAD) THEN
          HEADLINE = LINE(14: )
          BHEADREAD = .TRUE.
        ENDIF
C***  Store Lines which start with 'JOBNAME'
        IF (ACTPAR(1) .EQ. 'JOBNAME' .AND. .NOT. 
     >      BJOBREAD) THEN
          JOBNAME = ACTPAR(2)
          BJOBREAD = .TRUE.
        ENDIF

        IF (ACTPAR(1) .EQ. 'G' .AND.
     >      ACTPAR(2) .EQ. 'A' .AND.
     >      ACTPAR(3) .EQ. 'M' .AND.
     >      ACTPAR(4) .EQ. 'M' .AND.
     >      ACTPAR(5) .EQ. 'A' .AND.
     >      ACTPAR(6) .EQ. 'H' .AND.
     >      ACTPAR(7) .EQ. 'I' .AND.
     >      ACTPAR(8) .EQ. 'S' .AND.
     >      ACTPAR(9) .EQ. 'T' .AND.
     >      ACTPAR(10) .EQ. 'O') EXIT
      ENDDO
C***  Read all line which first Parameter is an Integer
 20   CONTINUE
      READ (1,'(A)', END=10) LINE
      CALL SARGV(LINE, 1, ACTPAR(1))
      IF (IDX(LINE) .EQ. 0) GOTO 20
      READ (ACTPAR(1), '(I20)', ERR=20) JOBNUM_READ
      JOBNUM_LAST = JOBNUM
      JOBNUM = JOBNUM_READ
      DO
        IF (JOBNUM .GE. JOBNUM_LAST-10) EXIT
        JOBNUM = JOBNUM + 1000
      ENDDO
      DO IARG=2, 10
        CALL SARGV(LINE, IARG, ACTPAR(IARG))
      ENDDO

      GAMMA_LAST2 = GAMMA_LAST
      GAMMA_LAST  = GAMMA
      READ (ACTPAR(4), '(F20.0)', ERR=20) GAMMA
      READ (ACTPAR(5), '(F20.0)', ERR=20) GAMMA_NEXT 
      READ (ACTPAR(6), '(F20.0)', ERR=20) CORR
      READ (ACTPAR(7), '(F20.0)', ERR=21) CORRSL
   21 CONTINUE

      IF (ACTPAR(2) .EQ. 'PC' .OR.
     >    ACTPAR(2) .EQ. 'PC_S') THEN
        DT_CORR%N             = DT_CORR%N + 1
        DT_CORRSL%N           = DT_CORRSL%N + 1
        DT_CORR%X(DT_CORR%N)  = FLOAT(JOBNUM)
        DT_CORR%Y(DT_CORR%N)  = CORR
        DT_CORRSL%X(DT_CORR%N)  = FLOAT(JOBNUM)
        DT_CORRSL%Y(DT_CORR%N)= CORRSL
      ELSEIF (ACTPAR(2) .EQ. 'PCs' .OR.
     >        ACTPAR(2) .EQ. 'PCsS') THEN
        DT_SCORR%N             = DT_SCORR%N + 1
        DT_CORRSL%N            = DT_CORRSL%N + 1
        DT_SCORR%X(DT_SCORR%N) = FLOAT(JOBNUM)
        DT_SCORR%Y(DT_SCORR%N) = CORR
        DT_CORRSL%X(DT_SCORR%N) = FLOAT(JOBNUM)
        DT_CORRSL%Y(DT_SCORR%N) = CORRSL
      ELSEIF (ACTPAR(2) .EQ. 'EX' .OR.
     >        ACTPAR(2) .EQ. 'EX_S') THEN
        DT_EX%N                = DT_EX%N + 1
        DT_EXSL%N              = DT_EXSL%N + 1
        DT_EX%X(DT_EX%N)       = FLOAT(JOBNUM)
        DT_EX%Y(DT_EX%N)       = CORR
        DT_EXSL%X(DT_EX%N)       = FLOAT(JOBNUM)
        DT_EXSL%Y(DT_CORR%N)   = CORRSL
        GAMMA = GAMMA_LAST
      ELSEIF (ACTPAR(2) .EQ. 'EXs' .OR.
     >        ACTPAR(2) .EQ. 'EXsS') THEN
        DT_SEX%N               = DT_SEX%N + 1
        DT_EXSL%N              = DT_EXSL%N + 1
        DT_SEX%X(DT_SEX%N)     = FLOAT(JOBNUM)
        DT_SEX%Y(DT_SEX%N)     = CORR
        DT_EXSL%X(DT_SEX%N)     = FLOAT(JOBNUM)
        DT_EXSL%Y(DT_CORR%N)   = CORRSL
        GAMMA = GAMMA_LAST
      ELSE
        WRITE (0,*) 'Did not recognize second parameter :', 
     >               ACTPAR(2)( :IDX(ACTPAR(2)))
        WRITE (0,*) 'PC is assumed'
        DT_CORR%N             = DT_CORR%N + 1
        DT_CORRSL%N           = DT_CORRSL%N + 1
        DT_CORR%X(DT_CORR%N)  = FLOAT(JOBNUM)
        DT_CORR%Y(DT_CORR%N)  = CORR
        DT_CORRSL%X(DT_CORR%N)  = FLOAT(JOBNUM)
        DT_CORRSL%Y(DT_CORR%N)  = CORRSL
      ENDIF
      IF (ACTPAR(3)(1:1) .EQ. '+') THEN
        DT_COLIP%N              = DT_COLIP%N + 1
        DT_COLIP%X(DT_COLIP%N)  = FLOAT(JOBNUM)
        DT_COLIP%Y(DT_COLIP%N)  = 0.
        DT_COLIP%BSPEC(DT_COLIP%N) = .FALSE.
        IF (ACTPAR(3)(2:2) .EQ. 'c') THEN
          DT_COLIP%BSPEC(DT_COLIP%N) = .TRUE.
        ENDIF        
      ENDIF

C*** Correction smoothed?
      IF (IDX(ACTPAR(2)) .EQ. 4) THEN
        IF (ACTPAR(2)(4:4) .EQ. 'S') THEN
          DT_SMOOTH%N = DT_SMOOTH%N + 1
          DT_SMOOTH%X(DT_SMOOTH%N) = FLOAT(JOBNUM)
        ENDIF
      ENDIF

      IF (GAMMA .NE. GAMMA_LAST) THEN
        DT_GCHANGE%N = DT_GCHANGE%N + 1
        DT_GCHANGE%X(DT_GCHANGE%N) = FLOAT(JOBNUM_LAST)
        WRITE (DT_GCHANGE%CHAR(DT_GCHANGE%N), '(F6.1, A4, F6.1)')
     >    GAMMA_LAST, ' -> ', GAMMA
      ENDIF

      GOTO 20

 10   CONTINUE
      CLOSE(1)

      OPEN (UNIT=2, FILE='adv_corrplot.plot', STATUS='NEW')
      WRITE (2,'(A,I3)') 'PLOT   :CPLOT'
      
      WRITE (2, '(A)') 'KASDEF INTERACTIVE'
      WRITE (2, '(A)') 'KASDEF PEN=3'
      WRITE (2, '(A)') 'KASDEF FONT=HELVET'
      WRITE (2, '(A)') 'KASDEF COLOR=2'
      WRITE (2, '(A)') 'KASDEF SYM XMAX YMIN 1.2   0.0 -0.3 8'
      WRITE (2, '(A)') 'KASDEF COLOR=1'
      WRITE (2, '(A)') 
     >      'KASDEF LUN XMAX YMIN 1.5  M0.0 0.3 &EPCsolv skipped'
      WRITE (2, '(A)') 'KASDEF SYM XMAX YMIN 1.2   -0.5 0.3 2'
      WRITE (2, '(A)') 'KASDEF LUN XMAX YMIN 1.5  M-0.5 0.3 &EExtrap'
      WRITE (2, '(A)') 'KASDEF COLOR=2'
      WRITE (2, '(A)') 'KASDEF SYM XMAX YMIN 1.2   -1.0 0.3 2'
      WRITE (2, '(A)') 'KASDEF COLOR=1'
      WRITE (2, '(A)') 
     >      'KASDEF LUN XMAX YMIN 1.5  M-1.0 0.3 &EExtrap skipped'
      WRITE (2, '(A)') 'KASDEF COLOR=4'
      WRITE (2, '(A)') 'KASDEF SYM XMAX YMIN 1.2  -1.5 -0.1 8'
      WRITE (2, '(A)') 'KASDEF COLOR=1'
      WRITE (2, '(A)') 'KASDEF LUN XMAX YMIN 1.5  M-1.5 0.3 &ESmoothing'

      WRITE (2, '(A)') 'KASDEF COLOR=3'
      WRITE (2, '(A)') 'KASDEF LINUN XMIN -0.5 XMAX -0.5 0 0'
      WRITE (2, '(A)') 'KASDEF LINUN XMIN -1.0 XMAX -1.0 0 0'
      WRITE (2, '(A)') 'KASDEF LINUN XMIN -1.5 XMAX -1.5 0 0'
      WRITE (2, '(A)') 'KASDEF LINUN XMIN -2.0 XMAX -2.0 0 0'
      WRITE (2, '(A)') 'KASDEF LINUN XMIN -2.5 XMAX -2.5 0 0'
      WRITE (2, '(A)') 'KASDEF LINUN XMIN -3.0 XMAX -3.0 0 0'
      WRITE (2, '(A)') 'KASDEF COLOR=1'

      WRITE (2, '(A)') 'KASDEF COLOR=9'
      DO I=1, DT_COLIP%N
        IF (DT_COLIP%BSPEC(I)) THEN
          WRITE (2, '(A)') 'KASDEF COLOR=2'
        ENDIF
        WRITE (2, '(A,F6.1,A,F6.1,A)') 
     >    'KASDEF LINUN ', DT_COLIP%X(I), ' YMIN ', 
     >     DT_COLIP%X(I), ' YMAX  0. 0. SIZE=0.15 SYMBOL=9'
        IF (DT_COLIP%BSPEC(I)) THEN
          WRITE (2, '(A)') 'KASDEF COLOR=9'
        ENDIF
      ENDDO
      WRITE (2, '(A)') 'KASDEF COLOR=1'

      WRITE (2, '(A)') 'KASDEF IDSIZE=0.2'
      WRITE (2, '(A)') 'KASDEF IDY 0.0U'
      DO I=1, DT_GCHANGE%N
        WRITE (2, '(A,F6.1,A2,A16)') 
     >    'KASDEF IDENT ', DT_GCHANGE%X(I), '  ', DT_GCHANGE%CHAR(I)
      ENDDO
      CHEAD = BACKSLASH // 'CENTER' // BACKSLASH 
     >        // '&EAdvanced Corrplot : '
      CX    = BACKSLASH // 'CENTER' // BACKSLASH // 'Jobnum'
      CY    = BACKSLASH // 'CENTER' // BACKSLASH // 'log Corrmax'

      WRITE (2,'(A)') 'KASDEF LETTERSIZE= 0.3'
      WRITE (2,'(4A)') 'KASDEF LUN XMIN YMIN 0. U-1.5 0.3 &E', 
     >                   JOBNAME( :IDX(JOBNAME)), ' : ', 
     >                   HEADLINE( :IDX(HEADLINE))
      WRITE (2, '(A)') 'KASDEF PEN=1'

      CALL PLOTANF(2, 'CORR', CHEAD, CX, CY, 
     >             0., 0., FLOAT(JOBNUM_LAST+10), 10., 100., 0., 
     >             0., -3.5, 1.5, 0.1, 0.5, 0., 
     >             DT_CORR%X(1), DT_CORR%Y(1), DT_CORR%N, 5)
      CALL PLOTCONS (2, DT_CORR%X(1), DT_CORR%Y(1), DT_CORR%N, 
     >            ' SYMBOL=8 SIZE=-0.1 COLOR=1')

      CALL PLOTCONS (2, DT_CORRSL%X(1), DT_CORRSL%Y(1), DT_CORR%N, 
     >            ' SYMBOL=5 SIZE=0.1 COLOR=9')
      CALL PLOTCONS (2, DT_CORRSL%X(1), DT_CORRSL%Y(1), DT_CORR%N, 
     >            ' SYMBOL=8 SIZE=-0.1 COLOR=9')

      IF (DT_SCORR%N .GT. 0) 
     >  CALL PLOTCONS (2, DT_SCORR%X(1), DT_SCORR%Y(1), DT_SCORR%N, 
     >              ' SYMBOL=8 SIZE=-0.2 COLOR=2')
      IF (DT_EX%N .GT. 0)
     >  CALL PLOTCONS (2, DT_EX%X(1),    DT_EX%Y(1),    DT_EX%N,    
     >              ' SYMBOL=2 SIZE=0.3 COLOR=1')
      IF (DT_SEX%N .GT. 0)
     >  CALL PLOTCONS (2, DT_SEX%X(1),   DT_SEX%Y(1),   DT_SEX%N,   
     >              ' SYMBOL=2 SIZE=0.3 COLOR=2')

C***  Plot Smoothing
      IF (DT_SMOOTH%N .GT. 0)
     >  CALL PLOTCONS (2, DT_SMOOTH%X(1), YFLAT(1),   DT_SMOOTH%N,
     >              ' SYMBOL=8 SIZE=-0.1 COLOR=4')

      CLOSE(2)

      STOP 'CPLOT finished normally'
      RETURN

 100  WRITE (0,*) 'Can not open file, file=', FNAME
      STOP 'ERROR in Subr. CPLOT'

 105  WRITE (0,*) 'Did not find the start'
      STOP 'ERROR in Subr. CPLOT'

      END

plotcons.f/     1553528659  5006  320   100644  979       `
      SUBROUTINE PLOTCONS (KANAL,X,Y,N,STYLE)
C***********************************************************************
C***  DIESE ROUTINE DIENST ZUM EINTRAGEN EINER 2. ODER 3. FUNKTION IN DEN
C***  BEGONNENEN PLOT ( PLOTCON ) , BZW. AB ENTRY PLOTTAB ZUM EINTRAGEN
C***  DER ERSTEN FUNKTION
C***********************************************************************
      DIMENSION X(N),Y(N)
      CHARACTER STYLE*(*)

C*** Backspace last Line (current ENDE)
      BACKSPACE KANAL

      ENTRY PLOTTABS (KANAL,X,Y,N,STYLE)

C***  CHECK FOR SMALL X- AND Y-VALUES
      DO I=1, N
        IF (ABS(X(I)) .LT. 1.E-30) X(I) = 0.
        IF (ABS(Y(I)) .LT. 1.E-30) Y(I) = 0.
      ENDDO

      WRITE (KANAL,1) N, STYLE
    1 FORMAT (' N=', I5, 1X, A)

      DO 3 I=1,N,5
      J=MIN0( 5,N-I+1)
      WRITE (KANAL,2) (X(I+L-1),L=1,J)
      WRITE (KANAL,2) (Y(I+L-1),L=1,J)
    2 FORMAT (1X, 5(G14.8,1X))
    3 CONTINUE

      WRITE (KANAL,4)
    4 FORMAT (' ENDE')

      RETURN
      END

checkvar.f/     1553528659  5006  320   100644  488       `
      SUBROUTINE CHECKVAR (ACTPAR, VAR, MAXVAR, NVAR, EXISTVAR)
C***************************************************
C***  CHECKS IF VARIABLE ACTPAR EXISTS
C***************************************************

      CHARACTER*(*) VAR(MAXVAR,2)
      CHARACTER*(*) ACTPAR
      LOGICAL EXISTVAR

      EXISTVAR = .FALSE. 

      DO I=1, NVAR
         IF (ACTPAR(2:) .EQ. VAR(I,1) ) THEN
            EXISTVAR = .TRUE.
            GOTO 100
         ENDIF
      ENDDO

  100 RETURN
      END
colortable.f/   1553528659  5006  320   100644  2087      `
      SUBROUTINE COLORTABLE (R, G, B, Y, COLMIN, COLMAX, ICOLOR)
C**********************************************************************
C***  Codes Y into false-color RGB 
C**********************************************************************

C***  ACTIVE GRAPHIC DRIVER
      COMMON / COMACT / ACTDRIV
      CHARACTER ACTDRIV*7

C***  Limits for the number of colors (X11) in one COLORTABLE
      COMMON /COMNCOLSTEP/ NCOLSTEP

      NCOLOR = 2000
C***  Restrict number of colors for X11 (limited graphic cards!)
C***   This numer should be settable by a KDSET option!
      IF (ACTDRIV .EQ. 'X11OWN') NCOLOR = NCOLSTEP

      DCOL  = COLMAX - COLMIN
      ISTEP = NINT( NCOLOR*(Y-COLMIN)/DCOL )
      Q     = FLOAT(ISTEP)/FLOAT(NCOLOR)

      IF (ICOLOR .EQ. 2) THEN
C***  Blackbody
         R =   2  * Q
         G =   2  * Q - 1.
         IF (Q .LT. 0.2) THEN 
            B = 3 * Q + 0.2 
         ELSE
            B = -1. * Q + 0.9
         ENDIF
      ELSE IF (ICOLOR .EQ. 3) THEN
C***  Plusminus
         P =  1.5 * ABS(Q-0.5)
         R =  2 * Q - 1. + P
         G =  0          + P
         B = -2 * Q + 1. + P
      ELSE IF (ICOLOR .EQ. 4) THEN
C***  Plusminus-2
         P =  1 - 1.5 * ABS(Q-0.5)
         R =  2 * Q 
         G =      P
         B = -2 * Q + 2
      ELSE IF (ICOLOR .EQ. 5) THEN
C***  Rainbow
         IF (Q .LT. 0.6) THEN
             R =   3  * Q - 1
         ELSE
	     R = 0.5 * Q + 0.5
	 ENDIF
         IF (Q .LT. 0.2) THEN 
	    G = 0.
         ELSE IF (Q .LT. 0.4) THEN          
            G = 5 * Q - 1.0
         ELSE IF (Q .LT. 0.8) THEN          
            G = -1 * Q + 1.4
         ELSE           
            G = -3 * Q + 3.
         ENDIF
         IF (Q .LT. 0.2) THEN 
            B = 2 * Q + 0.4
         ELSE
            B = -2 * Q + 1.2
         ENDIF
      ELSE
C***  Greyscale (ICOLOR=1 or invalid choice)
         R = Q
         G = Q
         B = Q   
      ENDIF

      R = AMAX1(0.,R)
      R = AMIN1(1.,R)
      G = AMAX1(0.,G)
      G = AMIN1(1.,G)
      B = AMAX1(0.,B)
      B = AMIN1(1.,B)
      
      RETURN
      END

lipo_ind.f/     1553528659  5006  320   100644  748       `
      SUBROUTINE LIPO_IND (NA, NB, X, XI, N)
C***********************************************************************
C***  LINEAR INTERPOLATION: FOR GIVEN X, FIND F(X) FROM A TABLE FI(XI)
C ------ INDEXSUCHE DURCH BISECTION ------
C***********************************************************************

      DIMENSION XI(N)

      NA=1
      A=XI(1)
      NB=N
      B=XI(N)

      IF((X-A)*(X-B).GT..0) THEN
        WRITE (0,'(A,3(1X,G12.5))')
     >    'LIPO : ', XI(1), X, XI(N)
        STOP 'ERROR IN SUBR. LIPO_IND'
      ENDIF

    1 IF((NB-NA).EQ.1) GOTO 2
      NH=(NA+NB)/2
      H=XI(NH)
      IF((X-A)*(X-H).GT..0) GOTO 3
      NB=NH
      B=H
      GOTO 1
    3 NA=NH
      A=H
      GOTO 1
 
    2 CONTINUE

      RETURN
      END
kd_luna.f/      1553528659  5006  320   100644  3235      `
      SUBROUTINE KD_LUNA (LINE, SIZELUN, B, C, XUNITS, YUNITS,  
     >    TLUN, BBGR, IBGRCOL, LASTCOLOR, BGRL, BGRR, BGRD, BGRU,
     >    BGRLINE)

C***********************************************************************
C***  KASDEF OPTIONS LUNA (String under angle)
C***  CALLED FROM SUBROUTINE KDPLOT (PROGRAM WRPLOT)
C***********************************************************************

      COMMON / COMIDEV / IDEV
      LOGICAL BBGR, BHATCH
      CHARACTER PPX*1, PPY*1, ACTPAR*80
      CHARACTER*(*) TLUN, LINE, BGRLINE  
      DIMENSION B(6),C(6)
      DATA PI / 3.14159 /
 
      BHATCH = .FALSE. 
      CALL SARGC (BGRLINE, NARG)
      DO I=1, NARG
         CALL SARGV (BGRLINE, I, ACTPAR)
         IF (ACTPAR .EQ. 'HATCHED' .OR. ACTPAR .EQ. 'HTYPE') THEN
            BHATCH = .TRUE.
            EXIT
         ENDIF
      ENDDO


      CALL DECXYUNITS  (LINE, 3, B, C, XUNITS)
      CALL DECXYUNITS  (LINE, 4, B, C, YUNITS)
      CALL DECFPNUMPRE (LINE, 5, XLUNOFS, PPX)
      CALL DECFPNUMPRE (LINE, 6, YLUNOFS, PPY)
      CALL DECFPNUM    (LINE, 7, SIZELUN)
      CALL DECFPNUM    (LINE, 8, ANGLUN)
      CALL SARGREST    (LINE, N, 9, NSTART, NN)
      IF (NSTART .GT. 1) THEN
         TLUN = LINE(NSTART:NN)
      ELSE
	 TLUN = ' '
      ENDIF

C***  CONVERT INTO CM
      IF (PPX .EQ. 'M') THEN
         CALL MYTLEN (TEXLEN, SIZELUN, TLUN, IDX(TLUN)) 
         XO2 = -TEXLEN / 2.
      ELSE IF (PPX .EQ. 'R') THEN
         CALL MYTLEN (TEXLEN, SIZELUN, TLUN, IDX(TLUN)) 
         XO2 = -TEXLEN
      ELSE
         XO2 = 0.
      ENDIF

      IF (PPY .EQ. 'M') THEN
         YO2 = -SIZELUN / 2.
      ELSE IF (PPY .EQ. 'U') THEN
         YO2 = -SIZELUN
      ELSE
         YO2 = 0.
      ENDIF

C***  Rotation matrix of Offsets from prefixes
      ARAD = ANGLUN * PI / 180. 
      CA = COS(ARAD)
      SA = SIN(ARAD)
      RX =  XO2 * CA - YO2 * SA
      RY =  XO2 * SA + YO2 * CA
           
      XCM = (XUNITS-B(2)) * B(1) + XLUNOFS + RX
      YCM = (YUNITS-C(2)) * C(1) + YLUNOFS + RY

C***  HINTERLEGEN DER SCHRIFT MIT EINEM FARBIG AUSGEFUELLTEN RECHTECK
      IF (BBGR) THEN
         CALL MYTLEN (TEXLEN, SIZELUN, TLUN, IDX(TLUN)) 
         BGRXL = - SIZELUN*BGRL
         BGRXR = TEXLEN + SIZELUN*BGRR
         BGRYD = - SIZELUN*BGRD
         BGRYU = SIZELUN*(BGRU+1)

         X1 = BGRXL * CA - BGRYD * SA + XCM
	 Y1 = BGRXL * SA + BGRYD * CA + YCM
         X2 = BGRXR * CA - BGRYD * SA + XCM
	 Y2 = BGRXR * SA + BGRYD * CA + YCM
         X3 = BGRXR * CA - BGRYU * SA + XCM
	 Y3 = BGRXR * SA + BGRYU * CA + YCM
         X4 = BGRXL * CA - BGRYU * SA + XCM
	 Y4 = BGRXL * SA + BGRYU * CA + YCM

C***     open box:
         LC2 = LASTCOLOR
         CALL COLOR ('DATA', 'DUMMY', ABS(IBGRCOL), IDEV)
         CALL GCPLOT (X1, Y1, 3)
         CALL GCPLOT (X2, Y2, 2)
         CALL GCPLOT (X3, Y3, 2)
         CALL GCPLOT (X4, Y4, 2)
         CALL GCPLOT (X1, Y1, 2)
C***     Filling Command 
         IF (IBGRCOL .GE. 0 .AND. .NOT. BHATCH) THEN
             CALL GFILL
         ELSEIF (BHATCH) THEN
             CALL HFILL(BGRLINE)
         ENDIF
         CALL COLOR ('DATA', 'DUMMY', LC2, IDEV)
      ENDIF


C***  Write output line
      CALL MYSYMBL (XCM, YCM, SIZELUN, TLUN, ANGLUN)

      RETURN

      END

plotxerr.f/     1553528659  5006  320   100644  2419      `
      SUBROUTINE PLOTXERR (X, Y, NDAT, NDATXE, XEMIN, XEMAX, ISYMBOLXE, 
     >                     SSIZEXE, ICOLORXE, NPENXE, B, C, 
     >                     XERRTYPE)
C*******************************************************************
C***  PLOT OF ERROR BARS
C***  CALLED BY MAIN PROGRAMM WRPLOT 
C*******************************************************************

      DIMENSION X(NDAT), Y(NDAT), XEMIN(NDAT), XEMAX(NDAT)
      DIMENSION B(6), C(6)
      COMMON / COMIDEV / IDEV 
      CHARACTER XERRTYPE*(*)

C***  ACTIVE GRAPHIC DRIVER
      COMMON / COMACT / ACTDRIV
      CHARACTER ACTDRIV*7

C**********************************************************************
C***           CONVERSION INTO CENTIMETER UNITS                     ***
C***             - IGNORE CONSECUTIVE IDENTICAL DATA-POINTS         ***
C**********************************************************************

C***  Check if error-dataset is not plotted as normal data (symbol 0)
      IF (ISYMBOLXE .NE. 0) THEN
         PRINT *
	 PRINT *, '*** XERROR DATASET MUST HAVE PLOTSYMBOL=0' 
         STOP     '*** ERROR IN SUBR: PLOTXERR'
      ENDIF

C***  Check if Datasets have equal number of entries
      IF (NDATXE .NE. 1 .AND. NDAT .NE. NDATXE) THEN
         PRINT *
	 PRINT *, '*** DIFFERENT NUMBERS OF XERROR DATA AND DATAPOINTS' 
         STOP     '*** ERROR IN SUBR: PLOTXERR'
      ENDIF

      CALL PEN (NPENXE, IDEV)
      CALL COLOR ('DATA', ' ', ICOLORXE, IDEV) 

      DO 19 I = 1, NDAT
          YCM = (Y(I)-C(2)) * C(1)
	  IF (NDATXE .EQ. 1) THEN
	      II = 1
	  ELSE
	      II = I
	  ENDIF
          IF (XERRTYPE .EQ. 'PLUSMINUS') THEN 
             XEMINCM = (X(I) + XEMIN(II)-B(2)) * B(1) 
             XEMAXCM = (X(I) + XEMAX(II)-B(2)) * B(1) 
          ELSE IF (XERRTYPE .EQ. 'MINMAX') THEN
             XEMINCM = (XEMIN(II)-B(2)) * B(1) 
             XEMAXCM = (XEMAX(II)-B(2)) * B(1) 
	  ELSE
            PRINT *
	    PRINT *, '*** INVALID TYPE FOR X-ERRORBAR DATA' 
	    PRINT *, '*** THE WRONG KEYWORD WAS:', XERRTYPE 
            STOP     '*** ERROR IN SUBR: PLOTXERR'
	  ENDIF 
          CALL GCPLOT (XEMINCM, YCM, 3)
          CALL GCPLOT (XEMAXCM, YCM, 2)

          CALL GCPLOT (XEMINCM, YCM-0.3*SSIZEXE, 3)
          CALL GCPLOT (XEMINCM, YCM+0.3*SSIZEXE, 2)
          CALL GCPLOT (XEMAXCM, YCM-0.3*SSIZEXE, 3)
          CALL GCPLOT (XEMAXCM, YCM+0.3*SSIZEXE, 2)
   19 CONTINUE

      RETURN
      END

plotyerr.f/     1553528659  5006  320   100644  2419      `
      SUBROUTINE PLOTYERR (X, Y, NDAT, NDATYE, YEMIN, YEMAX, ISYMBOLYE, 
     >                     SSIZEYE, ICOLORYE, NPENYE, B, C, 
     >                     YERRTYPE)
C*******************************************************************
C***  PLOT OF ERROR BARS
C***  CALLED BY MAIN PROGRAMM WRPLOT 
C*******************************************************************

      DIMENSION X(NDAT), Y(NDAT), YEMIN(NDAT), YEMAX(NDAT)
      DIMENSION B(6), C(6)
      COMMON / COMIDEV / IDEV 
      CHARACTER YERRTYPE*(*)

C***  ACTIVE GRAPHIC DRIVER
      COMMON / COMACT / ACTDRIV
      CHARACTER ACTDRIV*7

C**********************************************************************
C***           CONVERSION INTO CENTIMETER UNITS                     ***
C***             - IGNORE CONSECUTIVE IDENTICAL DATA-POINTS         ***
C**********************************************************************

C***  Check if error-dataset is not plotted as normal data (symbol 0)
      IF (ISYMBOLYE .NE. 0) THEN
         PRINT *
	 PRINT *, '*** YERROR DATASET MUST HAVE PLOTSYMBOL=0' 
         STOP     '*** ERROR IN SUBR: PLOTYERR'
      ENDIF

C***  Check if Datasets have equal number of entries
      IF (NDATYE .NE. 1 .AND. NDAT .NE. NDATYE) THEN
         PRINT *
	 PRINT *, '*** DIFFERENT NUMBERS OF YERROR DATA AND DATAPOINTS' 
         STOP     '*** ERROR IN SUBR: PLOTYERR'
      ENDIF

      CALL PEN (NPENYE, IDEV)
      CALL COLOR ('DATA', ' ', ICOLORYE, IDEV) 

      DO 19 I = 1, NDAT
	  IF (NDATYE .EQ. 1) THEN
	      II = 1
	  ELSE
	      II = I
	  ENDIF
          XCM = (X(I)-B(2)) * B(1)
          IF (YERRTYPE .EQ. 'PLUSMINUS') THEN 
             YEMINCM = (Y(I) + YEMIN(II)-C(2)) * C(1) 
             YEMAXCM = (Y(I) + YEMAX(II)-C(2)) * C(1) 
          ELSE IF (YERRTYPE .EQ. 'MINMAX') THEN
             YEMINCM = (YEMIN(II)-C(2)) * C(1) 
             YEMAXCM = (YEMAX(II)-C(2)) * C(1) 
	  ELSE
            PRINT *
	    PRINT *, '*** INVALID TYPE FOR Y-ERRORBAR DATA' 
	    PRINT *, '*** THE WRONG KEYWORD WAS:', YERRTYPE 
            STOP     '*** ERROR IN SUBR: PLOTYERR'
	  ENDIF 
          CALL GCPLOT (XCM, YEMINCM, 3)
          CALL GCPLOT (XCM, YEMAXCM, 2)

          CALL GCPLOT (XCM-0.3*SSIZEYE, YEMINCM, 3)
          CALL GCPLOT (XCM+0.3*SSIZEYE, YEMINCM, 2)
          CALL GCPLOT (XCM-0.3*SSIZEYE, YEMAXCM, 3)
          CALL GCPLOT (XCM+0.3*SSIZEYE, YEMAXCM, 2)
   19 CONTINUE

      RETURN
      END

adv_install.f/  1553528659  5006  320   100644  4746      `
      SUBROUTINE ADV_INSTALL(USER, HOST)
C****************************************************************
C***  Advanced Installation of WRPLOT
C***    The File .wrplotrc on the users account is read
C***  Operating system is always UNIX
C****************************************************************

C***  Installierte Plotter-Treiber
      COMMON / COMDRIV / CALCOMP, X11OWN, PSOWN
      LOGICAL CALCOMP, X11OWN, PSOWN

C***  Operating system:
      COMMON / COMOS / OPSYS
      CHARACTER*8 OPSYS

C***  Unix Commad 'cat' available?      
      COMMON / COMBC / BCAT
      LOGICAL BCAT

C***  Filename des Benutzerverzeichnisses
      COMMON / COMWRUS / WRUSFIL
      CHARACTER*255 WRUSFIL

C***  Filename der WRPLOT-Statistik:
      COMMON / COMWRSTAT / WRSTATFIL
      CHARACTER*255 WRSTATFIL

C***  Path to the font files
      COMMON / COMFOPA / FONTPATH
      CHARACTER FONTPATH*255

      CHARACTER FILENAME*255, LINE*80, USER*8, ACTPAR*60, HOST*8
      CHARACTER*80 CLINE, ACTPAR1, ACTPAR2
      CHARACTER*80 DISPLAY, DHOME, RCFILE, RCFILEC
      LOGICAL BARG, BEXIST, BVERBOSE

C***  Verbose Output
      BVERBOSE = .FALSE.

C***  Standard settings
      OPSYS = 'UNIX'
      RCFILE = '.wrplotrc'

C***  Prepare Variables concerning UNIX user and file information
      CALL GETENV ('LOGNAME', USER)
      CALL GETENV ('HOSTNAME', HOST)
      CALL GETENV ('HOME', DHOME)
      DHOME = DHOME(1:IDX(DHOME)) // '/'
      RCFILEC = DHOME(1:IDX(DHOME)) // RCFILE(1:IDX(RCFILE))

C***  Interpretation of the Resource File (.wrplotrc)
      INQUIRE (FILE=RCFILEC, EXIST=BEXIST)
      IF (.NOT. BEXIST) THEN
        WRITE (0,*) 'Installation file .wrplotrc not found'
        STOP 'Fatal Error in Subr. ADV_INSTALL'
      ENDIF

      OPEN (2, FILE=RCFILEC, STATUS='OLD', ERR=99)
      DO
        READ(2,'(A)',END=40) LINE
        CALL SARGV(LINE, 1, ACTPAR1)
        IF (ACTPAR(1:1) .EQ. '*') CYCLE
        CALL SARGV(LINE, 2, ACTPAR2)
        IDX2 = IDX(ACTPAR2)
        IF (IDX2 .EQ. 1) THEN
          IF (ACTPAR2(1:1) .EQ. 'T') THEN
            BARG = .TRUE.
          ELSE
            BARG = .FALSE.
          ENDIF
        ENDIF
        IF (ACTPAR1(1:7) .EQ. 'CALCOMP') THEN
          CALCOMP = BARG
        ELSEIF (ACTPAR1(1:6) .EQ. 'X11OWN') THEN
          X11OWN  = BARG
        ELSEIF (ACTPAR1(1:5) .EQ. 'PSOWN') THEN
          PSOWN   = BARG
        ELSEIF (ACTPAR1(1:4) .EQ. 'BCAT') THEN
          BCAT    = BARG
        ELSEIF (ACTPAR1(1:7) .EQ. 'WRUSFIL') THEN
          WRUSFIL = ACTPAR2
        ELSEIF (ACTPAR1(1:9) .EQ. 'WRSTATFIL') THEN
          WRSTATFIL = ACTPAR2
        ELSEIF (ACTPAR1(1:8) .EQ. 'FONTPATH') THEN
          FONTPATH = ACTPAR2
        ENDIF
      ENDDO

C***  File .wrplotrc read
   40 CONTINUE


C***  Search for dot in HOST and remove the rest
      DO I=1, 8
        IF (HOST(I:I) .EQ. '.') THEN
          HOST = HOST( :I-1)
          EXIT
        ENDIF
      ENDDO



C***  Create Entry in file WRUSFIL
      OPEN (1, FILE=WRUSFIL, STATUS='OLD', ERR=99)
    3 READ (1, '(A)', END=10) LINE
        CALL SARGV(LINE, 1, ACTPAR)
        IF (ACTPAR .EQ. 'INFO') THEN
          CALL SARGP (LINE, N, 2, IAS, IAE)
          PRINT *, LINE(IAS: IDX(LINE))
        ENDIF
        IF (USER .EQ. LINE(1:8)) GOTO 4
      GOTO 3

   10 CONTINUE
      PRINT *, ' '
      PRINT *, '*****************************************************'
      PRINT *, '*** USER IDENTIFICATION: ', USER
      PRINT *, '*** YOU ARE NOT PERMITTED TO USE THIS PROGRAM!'
      PRINT *, '*****************************************************'
      PRINT *, ' '
      STOP 'PERMISSION DENIED'

    4 CONTINUE
      CLOSE (1)
      PRINT *, ' '
      PRINT *, '*****************************************************'
      PRINT *, '*** USER IDENTIFICATION: ', LINE( :IDX(LINE))
      PRINT *, '*****************************************************'
      PRINT *, ' '

      GOTO 100
C**** ERROR EXIT ********************************************************
   99 CONTINUE
      WRITE (*,*) 'Error when opening the User file : ', 
     >             WRUSFIL( :IDX(WRUSFIL))

  100 CONTINUE

C*** Verbose Output
      IF (BVERBOSE) THEN
        WRITE (*,*)
        WRITE (*,'(A)') 'Verbose Output of all system variables ' 
     >             // 'set in Subr. ADV_INSTALL'
        WRITE (*,'(A,L1)') 'CALCOMP :   ', CALCOMP
        WRITE (*,'(A,L1)') 'X11OWN :    ',  X11OWN
        WRITE (*,'(A,L1)') 'PSOWN :     ',   PSOWN
        WRITE (*,'(A,L1)') 'BCAT :      ',    BCAT
        WRITE (*,'(A,A)')  'WRUSFIL :   ', WRUSFIL( :IDX(WRUSFIL))
        WRITE (*,'(A,A)')  'WRSTATFIL : ', WRSTATFIL( :IDX(WRSTATFIL))
        WRITE (*,'(A,A)')  'FONTPATH :  ', FONTPATH( :IDX(FONTPATH))
        WRITE (*,*)
      ENDIF
      RETURN
      END
psx_opewrfnt.f/ 1553528659  5006  320   100644  2440      `
      SUBROUTINE PSX_OPEWRFNT (ACTSIZE)
C**************************************************************************
C***  PSOWN Driver, called from PSSYMBL
C***  The Data files for WRPLOT Fonts are read into internal arrays
C**************************************************************************

C***  Path to the font files
      COMMON / COMFOPA / FONTPATH
      CHARACTER FONTPATH*255, STATUS*10,FILENAME*255
      SAVE STATUS

C***  Note: The same dimensions appear in PSX_READ
      PARAMETER (MAXASCII = 2000)
      PARAMETER (MAXGREEK = 2500)
      PARAMETER (MAXAMPER = 400)
      PARAMETER (MAXSLASH = 300)
      CHARACTER*16 WR_ASCII(MAXASCII), WR_GREEK(MAXGREEK)
      CHARACTER*16 WR_AMPER(MAXAMPER), WR_SLASH(MAXSLASH)
      COMMON / WRFONTDAT / WR_ASCII, WR_GREEK, WR_AMPER, WR_SLASH

      LENFP = IDX(FONTPATH)

C***  Different Datasetz may be applied for diffent Size of Symbols
      IF (STATUS .EQ. 'EXISTING') RETURN
      STATUS = 'EXISTING'

C***  Set Read pointer at the beginning of data
      CALL PSX_REWIND  

      FILENAME = FONTPATH(:LENFP)//'WRPLOTFONT_ASCII.DAT'
      OPEN (21, STATUS='OLD', ERR=99, FILE=FILENAME)
      DO I=1, MAXASCII
      READ (21, '(A)', END=21) WR_ASCII(I)
      END DO
      WRITE (*,'(A)') '>>> DIMENSION MAXASCII INSUFFICIENT <<<'
      STOP 'ERROR IN PSX_OPEWRFNT'
   21 CLOSE (21)

      FILENAME=FONTPATH(:LENFP)//'WRPLOTFONT_GREEK.DAT'
      OPEN (22, STATUS='OLD', ERR=99, FILE=FILENAME) 
      DO I=1, MAXGREEK
      READ (22, '(A)', END=22) WR_GREEK(I)
      END DO
      WRITE (*,'(A)') '>>> DIMENSION MAXGREEK INSUFFICIENT <<<'
      STOP 'ERROR IN PSX_OPEWRFNT'
   22 CLOSE (22)

      FILENAME=FONTPATH(:LENFP)//'WRPLOTFONT_AMPERSAND.DAT'
      OPEN (23, STATUS='OLD', ERR=99, FILE=FILENAME) 
      DO I=1, MAXAMPER
      READ (23, '(A)', END=23) WR_AMPER(I)
      END DO
      WRITE (*,'(A)') '>>> DIMENSION MAXAMPER INSUFFICIENT <<<'
      STOP 'ERROR IN PSX_OPEWRFNT'
   23 CLOSE (23)

      FILENAME=FONTPATH(:LENFP)//'WRPLOTFONT_BACKSLASH.DAT'
      OPEN (24, STATUS='OLD', ERR=99, FILE=FILENAME) 
      DO I=1, MAXSLASH
      READ (24, '(A)', END=24) WR_SLASH(I)
      END DO
      WRITE (*,'(A)') '>>> DIMENSION MAXSLASH INSUFFICIENT <<<'
      STOP 'ERROR IN PSX_OPEWRFNT'
   24 CLOSE (24)

      RETURN

C***  Error Branches
   99 WRITE (*, '(A)') '>>> CANNOT OPEN FONT FILE:'
      write (*, '(A)') FILENAME
      STOP 'ERROR IN PSX_OPEWRFNT'

      END
psx_translat.f/ 1553528659  5006  320   100644  881       `
      SUBROUTINE PSX_TRANSLAT (DX, DY, MODE)
C*************************************************************************
C***  OWN PS and X11 driver: translation (called from: PSX_ATTRIB
C***  MODE = 0 : only TEXTLEN is determined (for PS_TEXTLEN)
C***  MODE = 1 : the internal graphic state matrix of is updated
C***  MODE = 2 : graphic-state commands are written to the PS file
C*************************************************************************

C***  Transformation coefficients 
      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA

      IF (MODE .EQ. 0) THEN 
C***  No action
      ELSE IF (MODE .EQ. 1) THEN 
         CALL GS_TRANSLATE (DX, DY)
      ELSE IF (MODE .EQ. 2) THEN
         CALL GS_TRANSLATE (DX, DY)
         WRITE (KPS, '(F7.1, 1X, F7.1, A)') DX, DY, ' translate'
      ELSE
         STOP 'ERROR IN PSX_TRANSLAT'
      ENDIF

      RETURN
      END

table_extrct.f/ 1553528659  5006  320   100644  3946      `
      SUBROUTINE TABLE_EXTRCT
C******************************************************************************
C***  Takes the Values from table.aim and searches for the nearest
C***    X-Value in table.in
C***  Output is written to table.out
C***  table.in must be sorted
C***  table.aim is automatically sorted; equal X-Values are skipped
C******************************************************************************

      PARAMETER (MAXDAT = 10000)

      DIMENSION X_IN(MAXDAT), X_AIM(MAXDAT)

      CHARACTER*132 LINES_IN(MAXDAT), LINES_OUT(MAXDAT)
      CHARACTER*132 LINE
      CHARACTER*40 ACTPAR(10)

C***  Read Lines from Input file
      WRITE (0,*) 'Read Lines from Input file'
      OPEN (UNIT=10, FILE='table.in', STATUS='OLD')
      I_IN = 0
      DO
        READ (10, '(A)', END=10) LINE
        CALL SARGV (LINE, 1, ACTPAR(1))
        IF (ACTPAR(1)(1:1) .EQ. '*') CYCLE
        I_IN = I_IN + 1
        IF (I_IN .GT. MAXDAT) THEN
          WRITE (0,*) 'Parameter MAXDAT insufficient!'
          WRITE (0,'(A,I6)') 'MAXDAT=', MAXDAT
          STOP 'Fatal Error in Subr. TABLE_EXTRCT'
        ENDIF
        LINES_IN(I_IN) = LINE
      ENDDO
   10 CONTINUE

C***  Read X-Values from Input Lines
      WRITE (0,*) 'Read X-Values from Input Lines'
      DO I=1, I_IN
        CALL SARGV (LINES_IN(I), 1, ACTPAR(1))
        READ (ACTPAR(1), '(E40.0)') X_IN(I)
      ENDDO

C***  Check for increasing (decreasing) order
      WRITE (0,*) 'Check for increasing (decreasing) order'
      IF ((X_IN(1) - X_IN(I_IN)) .GT. 0.) THEN
        ORDER = 1.
      ELSE
        ORDER = -1.
      ENDIF
      DO I=1, I_IN-1
        IF ((X_IN(I)-X_IN(I+1)) * ORDER .LT. 0.) THEN
          WRITE (0,*) 'Input Dataset is not in decreasing' 
     >            // ' (increasing) order!'
          WRITE (0,'(A,I6, 4(1X,ES20.10))') 
     >      'I, (1), (I), (I+1), (I_IN) : ', 
     >      I, X_IN(1), X_IN(I), X_IN(I+1), X_IN(I_IN)
          STOP 'Fatal Error in Subr. TABLE_EXTRCT'
        ENDIF
      ENDDO


C***  Read Table XAIM
      WRITE (0,*) 'Read Table XAIM'
      OPEN (UNIT=11, FILE='table.aim', STATUS='OLD')
      I_AIM = 0
      DO
        READ (11, '(A)', END=11) LINE
        CALL SARGV (LINE, 1, ACTPAR(1))
        IF (ACTPAR(1)(1:1) .EQ. '*') CYCLE
        I_AIM = I_AIM + 1
        IF (I_AIM .GT. MAXDAT) THEN
          WRITE (0,*) 'Parameter MAXDAT insufficient!'
          WRITE (0,'(A,I6)') 'MAXDAT=', MAXDAT
          STOP 'Fatal Error in Subr. TABLE_EXTRCT'
        ENDIF
        READ (ACTPAR(1), '(E40.0)') X_AIM(I_AIM)
      ENDDO
   11 CONTINUE

C***  Sort Table AIM
      WRITE (0,*) 'Sort Table AIM'
      DO I=1, I_AIM
        DO J=1, I_AIM-1
          IF (X_AIM(J)*ORDER .LT. X_AIM(J+1)*ORDER) THEN
            TEMP = X_AIM(J)
            X_AIM(J) = X_AIM(J+1)
            X_AIM(J+1) = TEMP
          ENDIF
        ENDDO
      ENDDO      

C***  Check for equal entries
      WRITE (0,*) 'Check for equal entries'
      I = 0
      DO 
        I = I + 1
        IF (I .GE. I_AIM) EXIT
        IF (X_AIM(I) .EQ. X_AIM(I+1)) THEN
          DO J=I+1, I_AIM-1
            X_AIM(J) = X_AIM(J+1)
          ENDDO
          I = I - 1
          I_AIM = I_AIM - 1
        ENDIF
      ENDDO

C***  Write Output file
      WRITE (0,*) 'Write Output file'
      OPEN (UNIT=12, FILE='table.out', STATUS='UNKNOWN')
      I_OUT = 0
      DO I=1, I_AIM
        X = X_AIM(I)
        IF ((X-X_IN(1)) * (X-X_IN(I_IN)) .GT. 0.) THEN
          WRITE (0,'(A,G12.5,A)') 'X-Value ', X, ' Out of range'
          WRITE (0,*) 'X-Value ignored'
          CYCLE
        ENDIF
        I_OUT = I_OUT + 1
C***  Find Indices
        CALL LIPO_IND(NA, NB, X, X_IN, I_IN)
C***  Find nearest Point
        IF (ABS(X-X_IN(NA)) .LT. ABS(X-X_IN(NB))) THEN
          INDEX = NA
        ELSE
          INDEX = NB
        ENDIF
        WRITE (12, '(A)') LINES_IN(INDEX)
      ENDDO

      CLOSE(10)
      CLOSE(11)
      CLOSE(12)


      RETURN
      END        
decsetname.f/   1553528659  5006  320   100644  1447      `
      SUBROUTINE DECSETNAME (LINE, IPOS, SETNAME, NSET, ISETOP)
C****************************************************************
C***  Parameter in Position IPOS is read from input LINE ;
C***  If an integer number, this is returned as dataset number ISETOP ;
C***  If not an integer number, the parameter is taken as dataset name
C***  and decoded into the datset number if the name is defined.
C****************************************************************

      CHARACTER*(*) SETNAME(NSET), LINE
      CHARACTER ACTPAR*60
      LOGICAL CHRINSTR
      
      CALL SARGV (LINE, IPOS, ACTPAR)

C***  Branch if Dataset quoted by number
      READ (ACTPAR, '(I10)', ERR=10) ISETOP
      IF (ISETOP .GT. NSET .OR. ISETOP .LT. 1) THEN
         WRITE (*,'(//,A,I3,A)') 
     >        'Requested Dataset Number', ISETOP, ' does not exist'
         GOTO 99
      ENDIF
      RETURN
      
C***  Branch if dataset is quoted by name      
   10 CONTINUE
      ISETOP = 0
      DO I=1, NSET
	 IF (ACTPAR .EQ. SETNAME(I)) THEN
	    ISETOP = I
            EXIT
         ENDIF
      END DO
      IF (ISETOP .EQ. 0) THEN
         WRITE (*,'(//,2A)') 'DATASET NAME NOT DEFINED: ',
     >                      ACTPAR(:IDX(ACTPAR)) 
         GOTO 99
      ENDIF

      RETURN 

C***  Error exit
   99 WRITE (*,'(A)') 'The error occured in the following line:' 
      WRITE (*,'(A)') LINE(:IDX(LINE))   
      STOP 'ERROR STOP IN DECSETNAME'

      END
      

inlatex.f/      1553528659  5006  320   100644  3688      `
      SUBROUTINE INLATEX (XPOS, YCM, SIZE, STRPAR, ANGLE, BBXWIDTH, 
     >                    MODE)
C*************************************************************************
C***  Inlining a latex formula into a string
C***  Called from SUBROUTINE MYSYMBL
C*************************************************************************
      CHARACTER EPSFLINE*400
      DIMENSION B(6), C(6)
      CHARACTER*1 PPX, PPY
      LOGICAL  BBGR, BBLOCK
      CHARACTER ACTPAR*20, MODE*7
      CHARACTER STRPAR*(*), LS1*2, STRLATEX*400, BS*1

C***  Note: VAR is only a local dummy for taking the return from EPSF 
      PARAMETER (MAXVAR=13)
      CHARACTER*(132) VAR(MAXVAR,2)

C***  Blocktext and SQUEEZE-Parameter from kd_text
      COMMON / COMBLOCK / BBLOCK, SQUEEZE
C***  SCALING FOR LaTex strings (SUBR. KD_LATEXAND INLATEX)
      COMMON / COM_LATEX / SCALE_LATEX

      B(1) = 1.
      C(1) = 1.
      B(2) = 0.
      C(2) = 0.

      NVAR = 0

      BS = CHAR(92)
      LS1 = BS // ')'

      LENGTH = IDX(STRPAR)
      IF (LENGTH .EQ. 0) RETURN
      LAST = LENGTH

C***  SEARCH FOR END OF LATEX STRING
      CALL STRPOS (LS1, STRPAR, IPOS)
      IF (IPOS .NE. 0) THEN
         LAST = IPOS - 1
	 STRLATEX = STRPAR(:LAST)
         STRPAR = STRPAR(LAST+3:)
         CALL PREATTRIB (STRPAR)
      ELSE
         WRITE (*,'(//A)') '*** ERROR IN INLINE-LATEX: MISSING: '//LS1
         GOTO 99
      ENDIF

      OPEN (14, FILE='WRplot-scratch.tex')
      WRITE (14,'(A)') BS//'documentclass[12pt]{article}'
      WRITE (14,'(A)') BS//'usepackage{color}'
cc      WRITE (14,'(A)') BS//'usepackage{times}'
      WRITE (14,'(A)') BS//'usepackage[varg]{txfonts}'
      WRITE (14,'(A)') BS//'pagestyle{empty}'
      CALL COLOR ('INLATEX', ' ', ICOLOR, IDUMMY)
      WRITE (14,'(A)') BS//'begin{document}'
  
      WRITE (14,'(A)') BS // '(' 
     >                 //BS//'color{bgcolor}'
     >                 //BS//'rule[-6pt]{0.0001mm}{0.0001mm}'
     >                 //BS//'color{fgcolor}'
      WRITE (14,'(A)') STRLATEX(:IDX(STRLATEX)) // BS // ')'
      WRITE (14,'(A)') BS//'end{document}'
      CLOSE (14)
      CALL SYSTEM ('latex WRplot-scratch.tex')
cc      IF (ISTAT .NE. 0) THEN 
cc         WRITE(*,'(//A)')  '*** ERROR CODE RETURNED FROM latex'
cc         GOTO 99
cc      ENDIF
      CALL SYSTEM ('dvips -o -E -D 600 WRplot-scratch.dvi')
cc      IF (ISTAT .NE. 0) THEN 
cc         WRITE(*,'(//A)')  '*** ERROR CODE RETURNED FROM dvips'
cc         GOTO 99
cc      ENDIF

      WRITE (EPSFLINE, '(A, F6.2, A, F7.3, 1X, F7.3, A, F7.2)') 
     >     'KASDEF EPSF WRplot-scratch.ps LATEX SCALE=',
     >     3.6*SCALE_LATEX*SIZE*SQUEEZE, 
     >     ' COORD=', XPOS, YCM, ' o0 o0 ROTATE=', ANGLE  
      XUNITS = 0
      YUNITS = .0
      XLUNOFS = 0.
      YLUNOFS = 0.
      Y02 = 0
      PPX = 'L'
      PPY = 'U'
      DYSIZELUN = .0
      DYCMLUN = .0
      SIZELUN = .0
      BBGR = .FALSE.
      IBGRCOL = 0
      BGRL = 0
      BGRR = 0
      BGRD = 0
      BGRU = 0
      CALL EPSF (EPSFLINE, B, C, XUNITS, YUNITS, XLUNOFS, YLUNOFS,  
     >      DYCMLUN, PPX, PPY, VAR, MAXVAR, NVAR, DYSIZELUN, SIZELUN,
     >         BBGR, IBGRCOL, BGRL, BGRR, BGRD, BGRU, BBXWIDTH, MODE,
     >      '')

      CALL SYSTEM ('rm WRplot-scratch.*')

      CALL TURN (DX, DY, BBXWIDTH, 0., ANGLE)
      XPOS = XPOS + DX
      YCM  = YCM  + DY
      
      RETURN


C**********************************************************************
C***  EROR BRANCH
C**********************************************************************

   99 WRITE (*,'(A)') '*** THE ERROR OCCURRED IN THE FOLLOWING STRING:'
      WRITE (*,'(A)') STRPAR(:IDX(STRPAR))
      STOP 'ERROR IN SUBROUTINE INLATEX'

      END
kd_latex.f/     1553528659  5006  320   100644  4171      `
      SUBROUTINE KD_LATEX (LINE, KDLINE, IKD, NKD, NKDMAX, 
     >             B, C, XUNITS, YUNITS, XLUNOFS, YLUNOFS, DYCMLUN, 
     >             PPX, PPY, VAR, MAXVAR, NVAR, DYSIZELUN, SIZELUN,
     >             BBGR, IBGRCOL, BGRL, BGRR, BGRD, BGRU, BGRLINE)
C***********************************************************************
C***  KASDEF LATEX :
C***   latex source text is read in, written to file, and the eps file
C***   is included
C***  CALLED FROM SUBROUTINE KDPLOT (PROGRAM WRPLOT)
C***********************************************************************
      CHARACTER*(*) LINE, BGRLINE
      CHARACTER EPSFLINE*400, TESTLINE*80
      CHARACTER KDLINE(NKDMAX)*132, BACKSLASH*1, ACTPAR*20
      CHARACTER*1 PPX, PPY
      LOGICAL  BBGR
      CHARACTER*(*) VAR(MAXVAR,2)

C***  SCALING FOR LaTex strings (from KDPLOT, used also in INLATEX)
      COMMON / COM_LATEX / SCALE_LATEX

      BACKSLASH = CHAR(92)

      
      OPEN (14, FILE='WRplot-scratch.tex')
      WRITE (14,'(A)') BACKSLASH//'documentclass[12pt]{article}'
      WRITE (14,'(A)') BACKSLASH//'usepackage{color}'
cc      WRITE (14,'(A)') BACKSLASH//'usepackage{times}'
      WRITE (14,'(A)') BACKSLASH//'usepackage[varg]{txfonts}'

C***  check for usepackage commands and insert them here 
   30 IF (KDLINE(IKD+1)(:11) .EQ. BACKSLASH//'usepackage') THEN 
         WRITE (14,'(A)') KDLINE(IKD+1)(:IDX(KDLINE(IKD+1)))
         IKD = IKD + 1
	 GOTO 30
      ENDIF

      CALL COLOR ('KD_LATEX', ' ', ICOLOR, IDUMMY)  
      WRITE (14,'(A)') BACKSLASH//'pagestyle{empty}'
      WRITE (14,'(A)') BACKSLASH//'begin{document}'
      WRITE (14,'(A)') BACKSLASH//'color{fgcolor}'
  
C***  Read next input line
   46 IKD = IKD + 1
      IF (IKD .GT. NKD) GOTO 99
C***  Decode ENDTEXT = end of floating text
      TESTLINE = KDLINE(IKD)
      CALL SARGV (TESTLINE, 1, ACTPAR)
      CALL FLUSHLEFT (TESTLINE)
      IF (TESTLINE(1:1) .EQ. BACKSLASH) THEN 
         CALL SARGV (TESTLINE(2:), 1, ACTPAR)
      ELSE IF (ACTPAR .EQ. 'KASDEF') THEN
         CALL SARGV (TESTLINE, 2, ACTPAR)
      ENDIF
      IF (ACTPAR .EQ. 'ENDLATEX') GOTO 44
      
      WRITE (14,'(A)') KDLINE(IKD)(:IDX(KDLINE(IKD)))
      GOTO 46

   44 CONTINUE
      WRITE (14,'(A)') BACKSLASH//'end{document}'
      CLOSE (14)
      CALL SYSTEM ('latex WRplot-scratch.tex')
cc      IF (ISTAT .NE. 0) THEN 
cc         WRITE(*,'(//A)')  '*** ERROR CODE RETURNED FROM latex'
cc         GOTO 98
cc      ENDIF
      CALL SYSTEM ('dvips -o -E -D 600 WRplot-scratch.dvi')
cc      IF (ISTAT .NE. 0) THEN 
cc         WRITE(*,'(//A)')  '*** ERROR CODE RETURNED FROM dvips'
cc         GOTO 98
cc      ENDIF
 
      CALL SARGREST (LINE, NPAR, 3, IFIRST, LAST)
      EPSFLINE = 'KASDEF EPSF WRplot-scratch.ps LATEX ' 
     >           // LINE(IFIRST:LAST)
C***  Default for positioning: NEXTLUN
      NPARREST = NPAR - 2
      DO I=1, NPARREST
         CALL SARGV (LINE(IFIRST:LAST), I, ACTPAR)
         IF (ACTPAR .EQ. 'COORD' .OR. ACTPAR .EQ. 'NEXTLUN') GOTO 10 
      ENDDO
      EPSFLINE = EPSFLINE(:IDX(EPSFLINE)) //' NEXTLUN'
   10 CONTINUE

C***  Default for scaling
      DO I=1, NPARREST
         CALL SARGV (LINE(IFIRST:LAST), I, ACTPAR)
         IF (ACTPAR .EQ. 'SCALE' .OR. ACTPAR .EQ. 'EPSFXSIZE'
     >                           .OR. ACTPAR .EQ. 'EPSFYSIZE') GOTO 20 
      ENDDO
      EPSFLINE = EPSFLINE(:IDX(EPSFLINE)) //' SCALE='
      IPOS = IDX(EPSFLINE) + 1
      WRITE (EPSFLINE(IPOS:),'(F6.2)') 3.6*SCALE_LATEX*SIZELUN
   20 CONTINUE

      CALL EPSF (EPSFLINE, B, C, XUNITS, YUNITS, XLUNOFS, YLUNOFS, 
     >     DYCMLUN, PPX, PPY, VAR, MAXVAR, NVAR, DYSIZELUN, SIZELUN,
     >        BBGR, IBGRCOL, BGRL, BGRR, BGRD, BGRU, BBXWIDTH, 'PRINT',
     >     BGRLINE)

      CALL SYSTEM ('rm WRplot-scratch.*')

      RETURN

C**********************************************************************
C***  EROR BRANCH
C**********************************************************************

   98 WRITE(*,'(A)') '*** THE ERROR OCCURED IN THE FOLLOWING LINE:'
      WRITE(*,'(A)') LINE(:IDX(LINE)) 
      STOP 'ERROR IN SUBR. KD_LATEX'


99    WRITE(*,'(A)') 'KASDEF ENDLATEX MISSING'
      STOP 'ERROR IN KD_LATEX'

      END

my_open.f/      1654265858  5006  320   100644  2464      `
      SUBROUTINE MY_OPEN (KANAL, FILENAME, IERR)
C********************************************************************
C***  Open an existing file
C***  If file not exists: 
C***     - try to expand ~ at beginning
C***     - try to gunzip 
C********************************************************************
      CHARACTER FILENAME*(*), LINE*255, LOCALNAME*255
      CHARACTER CCOMMAND*266, USERNAME*20
      LFN = IDX(FILENAME)
      LOCALNAME = FILENAME

      OPEN (UNIT=KANAL, FILE=FILENAME, STATUS='OLD', ERR=90)
      IERR = 0
      RETURN
      
C***  Test, if filename starts with ~ to be expanded
   90 IF (FILENAME(:1) .NE. '~') GOTO 95
C     Use of C routine c_systempopen (pipe) 
      CCOMMAND = 'echo ' // FILENAME(:LFN) // ' 2>&1' // CHAR(0)
      CALL C_SYSTEMPOPEN(CCOMMAND, LOCALNAME, ILENNAME)
      IF (ILENNAME .GT. 255) THEN
       WRITE (*,'(/,A)') "ERROR: EXPANDED FILENAME TOO LONG"
       GOTO 98
      ENDIF
      LOCALNAME=LOCALNAME(:ILENNAME)
      LFN=IDX(LOCALNAME)
C     Now open the file with expanded path name
      OPEN (UNIT=KANAL, FILE=LOCALNAME, STATUS='OLD', 
     >      ERR=95)
      IERR = 0
      RETURN
      
C***  Test, if file is gzipped      
   95 LOCALNAME = LOCALNAME(:LFN) // '.gz'
      LFN = LFN + 3
      OPEN (UNIT=KANAL, FILE=LOCALNAME, STATUS='OLD', 
     >      ERR=99)
      CLOSE(KANAL)
            
      CALL GETENV ('USER', USERNAME)
      LINE = 'gunzip -c ' // LOCALNAME(:LFN) //
     >       ' > /tmp/wrplot_scratch_gunzip_' // USERNAME 
      CALL SYSTEM (LINE(:IDX(LINE)))
C***  Debug:
c      WRITE (*,'(/,A)') '=== NOTE: input file is gzipped: ' // 
c     >            LOCALNAME(:IDX(LOCALNAME))            
c      WRITE (*,*) '-> /tmp/wrplot_scratch_gunzip_',
c     >         USERNAME(:IDX(USERNAME)), ' generated' 

      OPEN (UNIT=KANAL, FILE='/tmp/wrplot_scratch_gunzip_' 
     >     // USERNAME, STATUS='OLD', ERR=96)
      IERR = 0
      RETURN


C***  Error branch after making gunzip      
   96 IERR = 10
      WRITE (*, '(/,A)') 'Internal Error after gunzip'
      RETURN

C***  Error branch after expanding tilde      
   97 IERR = 10
      WRITE (*, '(/,A)') 'Internal Error while expanding tilde'
      RETURN
      
   98 IERR = 10
      WRITE (*, '(/,A)') 'Error when opening file after expanding ~'
      RETURN
      
C***  Exit branch after gunzip failed      
   99 IERR = 11
      WRITE (*, '(/,A)') 'Error when opening file after gunzip'
      RETURN
      
      END
my_isoex.f/     1653499815  5006  320   100644  2597      `
      SUBROUTINE MY_ISOEX
C****************************************************
C***
C***  Creating an isoplot file from all .out files in the present directory
C***
C****************************************************

      CHARACTER OLINE*80, LINE*80, ACTPAR*10, ACTPAR2*10, MODEL*50, 
     >     TOLD*10
      LOGICAL BPEAK

C     abanisk: Mit dieser Abfrage wird geklaert, ob die Equivalentbreite oder
C              die Peakhoehe gewuenscht ist. Standard ist Equiv-w..
      BPEAK = .FALSE.

1001  format(A)
      OPEN(101,FILE='iso.part1',status='old')
110   READ (101, 1001, ERR=980, END=113) LINE
      IF ((line(1:4) .eq. 'PEAK').or.(line(1:4) .eq. 'peak')) THEN
         BPEAK = .TRUE.
      ELSE
         GOTO 110
      ENDIF
 113  CONTINUE
      LINE = ' '
      CLOSE(101)

C***  The following "grep" should extract 3 lines from each formal.out, 
C***  containing the lines with
C***    1) T*
C***    2) Rt
C***    3) Equiv. width
C***  The extracted lines are written to file iso.dat and can be checked there!
      IF (.NOT. BPEAK) THEN
         CALL SYSTEM 
     >     ('grep -e "T\*" -e Rt -e EQUIV *.out | cut -c1-80 > iso.dat')
      
c     This "grep" gives the peak intensity instead of the line width
      ELSEIF (BPEAK) THEN
         CALL SYSTEM 
     >     ('grep -e "T\*" -e Rt -e PEAK *.out | cut -c1-80 > iso.dat')
      ELSE
         GOTO 998
      ENDIF

      CALL SYSTEM ('cat iso.part1 > isoex.iso')


C***  Now iso.dat is read, the parameters are parsed from the lines 
C***   and the table is written to isoex.iso 
C***   in the proper input format for isopro 
      OPEN (10, FILE='iso.dat', STATUS='OLD')
      TOLD = ' '

    1 READ (10, '(A)', END=100) LINE
      CALL SARGV (LINE,3,ACTPAR)
      IF (ACTPAR .NE. TOLD) WRITE (20,'(A)') 'T=' // ACTPAR
      TOLD = ACTPAR

      READ (10, '(A)', END=999) LINE
      CALL SARGV (LINE,3,ACTPAR)

      READ (10, '(A)', END=999) LINE
      IF (BPEAK) THEN
         CALL SARGV (LINE,4,ACTPAR2)
      ELSE
         CALL SARGV (LINE,5,ACTPAR2)
      ENDIF
      CALL SARGV (LINE,1,MODEL)

      WRITE (20,'(2X,A,2X,A,2X,A)') ACTPAR, ACTPAR2, MODEL

      GOTO 1


  100 CONTINUE

      WRITE (20,'(A)') 'END'
      CLOSE (20)
      CLOSE (10)

      CALL SYSTEM ('cat fort.20 >> isoex.iso')
      CALL SYSTEM ('rm -f fort.20')

      STOP 'O.K.'

C***  Errors
 998  CONTINUE
      STOP 'ERROR: DO NOT KNOW WHICH LINE-CHARACTERISTIC IS WISHED:
     > PEAK OR EQUIV!'
999   CONTINUE
      STOP 'ERROR: EOF reached before line-triple completed' 

980   PRINT *, 'Datenfile Lesefehler'
      STOP 'ERROR'

      END


kd_ident.f/     1553528659  5006  320   100644  11910     `
      SUBROUTINE KD_IDENT (ACTPAR, LINE, B, C, 
     >   SIZEID, SIZEFAC, SIZEID2, IID, YID, XOFFID, XFACID, IDNORM, 
     >   XLENGID, IDMCOMB, XIDMLEN1, XIDMLEN2, XIDMLEN3, 
     >   IDDIR, IDCON, BIDLOG, ID_INBOX )

C***********************************************************************
C***  WRPLOT PROGRAM:
C***  PLOTTING OF ALL KASDEF OPTIONS STARTING WITH "ID..."
C***  THIS SUBROUTINE IS CALLED FROM SUBR. KDPLOT
C***********************************************************************

      PARAMETER (MULTMAX = 20)

      DIMENSION B(6),C(6)
      DIMENSION XMULT(MULTMAX)
      LOGICAL   IDNORM, IDMCOMB, BIDLOG, IDCON, ID_INBOX
      CHARACTER LINE*(*), ACTPAR*(*), LINEID*80
 
      SAVE 

C***  EXECUTE CURRENT ID... Option **************************************

C***  KASDEF IDRESET (SETZT DEN IDENT-ZAEHLER ZURUECK) ******
C-----------------------
      IF (ACTPAR .EQ. 'IDRESET' .OR.
     >         ACTPAR .EQ. 'ID_RESET') THEN
         IID = 0

C***  KASDEF IDFORWARD ******
C-----------------------
      ELSE IF (ACTPAR .EQ. 'IDFORWARD'.OR.
     >         ACTPAR .EQ. 'ID_FORWARD') THEN
         IDDIR = 1
         IID = 0

C***  KASDEF IDBACKWARD ******
C-----------------------
      ELSE IF (ACTPAR .EQ. 'IDBACKWARD' .OR.
     >         ACTPAR .EQ. 'ID_BACKWARD') THEN
         IDDIR = -1
         IID = 0

C***  KASDEF ID_CONNECT ******
C-----------------------
      ELSE IF (ACTPAR .EQ. 'ID_CONNECT') THEN
         IDCON = .TRUE.

C***  KASDEF ID_NOCONNECT ******
C-----------------------
      ELSE IF (ACTPAR .EQ. 'ID_NOCONNECT') THEN
         IDCON = .FALSE.

C***  KASDEF IDSIZE (SETZT DIE SCHRIFTGROESSE DER IDENTIFIKATION) ******
C-----------------------
      ELSE IF (ACTPAR .EQ. 'IDSIZE') THEN
         CALL SARGV (LINE,3,ACTPAR)
         READ (ACTPAR,'(F20.0)', ERR=96) SIZEID
         SIZEID2 = SIZEID * SIZEFAC

C***  KASDEF IDSPACE (SETZT DEN PLATZ ZWISCHEN DEN IDENTIFIKATIONEN) ******
C-----------------------
      ELSE IF (ACTPAR .EQ. 'IDSPACE' .OR.
     >         ACTPAR .EQ. 'ID_SPACE') THEN
         CALL SARGV (LINE,3,ACTPAR)
         READ (ACTPAR,'(F20.0)', ERR=96) SIZEFAC
         SIZEID2 = SIZEID * SIZEFAC

C***  KASDEF IDXOFF (SETZT EINEN OFFSET IN X-RICHTUNG BEI DER IDENTIFIKATION) 
C-----------------------
      ELSE IF (ACTPAR .EQ. 'IDXOFF') THEN
         CALL SARGV (LINE,3,ACTPAR)
         READ (ACTPAR,'(F20.0)', ERR=96) XOFFID

C***  KASDEF IDXFAC (SETZT EINEN FAKTOR IN X-RICHTUNG BEI DER IDENTIFIKATION) 
C-----------------------
      ELSE IF (ACTPAR .EQ. 'IDXFAC') THEN
         CALL SARGV (LINE,3,ACTPAR)
         READ (ACTPAR,'(F20.0)', ERR=96) XFACID

C***  KASDEF IDY (LEGT DIE HOEHE DER IDENTIFIKATION IN CM ODER UNITS FEST)
C-----------------------
      ELSE IF (ACTPAR .EQ. 'IDY') THEN
         CALL SARGV (LINE,3,ACTPAR)
         ID = IDX(ACTPAR)
         IF (ACTPAR(ID:ID) .EQ. 'U') THEN 
           ACTPAR(ID:ID) = ' '
           READ (ACTPAR, '(F20.0)', ERR=96) YID
           YID = (YID - C(2)) * C(1)
         ELSE
           READ (ACTPAR, '(F20.0)', ERR=96) YID
         ENDIF

C***  KASDEF IDLENG (LEGT DIE LANGE DES IDENTIFIKATIONSSTRICHS IN CM FEST)
C-----------------------
      ELSE IF (ACTPAR .EQ. 'IDLENG' .OR.
     >         ACTPAR .EQ. 'ID_LENG') THEN
         CALL SARGV (LINE,3,ACTPAR)
         ID = IDX(ACTPAR)
         IF (ACTPAR(ID:ID) .EQ. 'U') THEN 
           ACTPAR(ID:ID) = ' '
           READ (ACTPAR, '(F20.0)', ERR=96) XLENGID
           XLENGID = (XLENGID-C(2)) * C(1)
         ELSE
           READ (ACTPAR,'(F20.0)', ERR=96) XLENGID
         ENDIF

C***  KASDEF IDHOR (HORIZONTALE IDENTIFIKATION)
C-----------------------
      ELSE IF (ACTPAR .EQ. 'IDHOR' .OR.
     >         ACTPAR .EQ. 'ID_HOR') THEN
         IDNORM = .FALSE.

C***  KASDEF IDVER (VERTIKALE IDENTIFIKATION)
C-----------------------
      ELSE IF (ACTPAR .EQ. 'IDVER' .OR.
     >         ACTPAR .EQ. 'ID_VER') THEN
         IDNORM = .TRUE.

C***  KASDEF IDENT_START (VERSCHIEBT DIE BESCHRIFTUNG AUF DEN ANGEGEBEN WERT)
C-----------------------
      ELSE IF (ACTPAR .EQ. 'IDENT_START' .OR. 
     >         ACTPAR .EQ. 'ID_START') THEN
         CALL SARGV (LINE,3,ACTPAR)
         READ (ACTPAR,'(F20.0)', ERR=96) POSXID
         IF (BIDLOG) POSXID = ALOG10(POSXID)
         CALL SARGREST (LINE, N, 4, NSTART, NN)
         LINEID = LINE(NSTART:)
         
         IID = IID + 1
         POSXID = (POSXID - B(2)) * B(1)
         POSXID = POSXID - SIZEID2 * IDDIR

C***  KASDEF IDENT (IDENTIFIZIERT LINIEN IM PLOT) ******
C-----------------------
      ELSE IF (ACTPAR .EQ. 'IDENT') THEN
         CALL SARGV (LINE,3,ACTPAR)
         READ (ACTPAR,'(F20.0)', ERR=96) X
         X = XFACID*X + XOFFID
         IF (BIDLOG) X = ALOG10(X)
         IF (ID_INBOX) THEN
            IF((X-B(2))*(X-B(3)) .GT. .0) RETURN	 
         ENDIF
         CALL SARGREST (LINE, N, 4, NSTART, NN)
         LINEID = LINE(NSTART:)
         
         IID = IID + 1
         XCM = (X - B(2)) * B(1)

         IF (IDNORM) THEN
           CALL GPLOT (XCM, YID, 3)
           CALL GPLOT (XCM, YID+XIDMLEN1*XLENGID, 2)
           IF (IID .EQ. 1 .OR. (XCM - POSXID)*IDDIR .GT. SIZEID2
     >         .AND. .NOT. IDCON) THEN
             POSXID = XCM
           ELSE
             POSXID = POSXID + SIZEID2 * IDDIR
           ENDIF
           CALL GPLOT (POSXID, YID+(XIDMLEN1+XIDMLEN2)*XLENGID, 2)
           CALL GPLOT (POSXID, YID+XLENGID, 2)

           if (XLENGID .LT. 0.) then ! IDENT downwards
            CALL MYTLEN (TEXTLEN, SIZEID, LINEID, IDX(LINEID))
            CALL MYSYMBL (POSXID+0.5*SIZEID,YID+XLENGID-0.5*SIZEID
     >                    -TEXTLEN, 
     >                  SIZEID, LINEID, 90.)
           else
            CALL MYSYMBL (POSXID+0.5*SIZEID,YID+XLENGID+0.5*SIZEID, 
     >                  SIZEID, LINEID, 90.)
           endif

         ELSE
           if (XLENGID .LT. 0.) then ! IDENT horizontal Y increment downwards
            YCM = YID + FLOAT(IID-1) * SIZEID2
           else  
            YCM = YID - FLOAT(IID-1) * SIZEID2
           endif
           IF (IDDIR .EQ. -1) THEN
             CALL MYTLEN (TEXTLEN, SIZEID, LINEID, IDX(LINEID))
             TEXTLEN = TEXTLEN + 0.1
           ELSE
             TEXTLEN = 0.
           ENDIF
           CALL GPLOT (XCM, YCM, 3)
           CALL GPLOT (XCM, YCM+(XIDMLEN1+XIDMLEN2)*XLENGID, 2)
           if (XLENGID .LT. 0.) then ! IDENT horizontal downwards
            CALL GPLOT (XCM-0.28*XLENGID*IDDIR , 
     >                 YCM+(XIDMLEN1+XIDMLEN2)*XLENGID , 2)
            CALL MYSYMBL (XCM+(-0.28*XLENGID+0.5*SIZEID)*IDDIR+TEXTLEN, 
     >              YCM+(XIDMLEN1+XIDMLEN2)*XLENGID - 0.5*SIZEID, 
     >              SIZEID, LINEID, 0.)
           else
            CALL GPLOT (XCM+0.28*XLENGID*IDDIR, 
     >                 YCM+(XIDMLEN1+XIDMLEN2)*XLENGID, 2)
            CALL MYSYMBL (XCM+(0.28*XLENGID+0.5*SIZEID)*IDDIR-TEXTLEN, 
     >              YCM+(XIDMLEN1+XIDMLEN2)*XLENGID - 0.5*SIZEID, 
     >              SIZEID, LINEID, 0.)
           endif

         ENDIF

C***  KASDEF IDMLENG (GIBT DIE LAENGE DES KAMMS AN, 
C***                  MAXIMAL DAS 0.43 FACHE VON IDLENG)
C-----------------------
      ELSE IF (ACTPAR .EQ. 'IDMLENG') THEN
        CALL SARGV(LINE,3,ACTPAR)
        IF (ACTPAR .EQ. 'RESET') THEN
          XIDMLEN1 = 0.43
          XIDMLEN2 = 0.43
          XIDMLEN3 = 1. - XIDMLEN1 -XIDMLEN2
        ELSE
          READ (ACTPAR,'(BN, F20.0)', ERR=96) XIDMLEN1
          CALL SARGV(LINE,4,ACTPAR)
          READ (ACTPAR,'(BN, F20.0)', ERR=96) XIDMLEN2
          IF (XIDMLEN1 .GT. 0. .AND. XIDMLEN1 .LT. 1 .AND.
     >        XIDMLEN2 .GT. 0. .AND. XIDMLEN2 .LT. 1 .AND.
     >        XIDMLEN1+XIDMLEN2 .LE. 1.) THEN
            XIDMLEN3 = 1. - XIDMLEN1 -XIDMLEN2
          ELSE
            WRITE (*,*) 'WRONG USE OF KASDEF IDMLENG'
            WRITE (*,*) 'LINE=',LINE( :IDX(LINE))
            STOP 'ERROR IN KDPLOT'
          ENDIF
        ENDIF

C***  KASDEF IDMCOMB (IDENTIFIZIERT LINIEN IM PLOT ALS BRACKET,
C***                  ABER OHNE BESCHRIFTUNG)
C-----------------------
      ELSE IF (ACTPAR .EQ. 'IDMCOMB') THEN
        CALL SARGV(LINE,3,ACTPAR)
        IF (ACTPAR .EQ. 'TRUE') THEN
          IDMCOMB = .TRUE.
        ELSE IF (ACTPAR .EQ. 'FALSE') THEN
          IDMCOMB = .FALSE.
        ELSE
          WRITE(*,*) 'ILLEGAL USE OF IDMCOMB'
          WRITE(*,*) 'ERROR OCCURED IN LINE :'
          WRITE (*,*) LINE
          STOP
        ENDIF

C***  KASDEF IDMULT (IDENTIFIZIERT LINIEN IM PLOT ALS BRACKET) ******
C-----------------------
      ELSE IF (ACTPAR .EQ. 'IDMULT') THEN
        IF (.NOT. IDNORM) THEN
          WRITE(*,*) 'IDMULT nur mit IDVER benutzbar'
          STOP
        ENDIF
        CALL SARGC (LINE, MARG)
        MMAX = MARG - 3
        IF (MMAX .GT. MULTMAX) THEN
          WRITE(*,*) 'Mehr Blendkomponenten als Dimensioniert'
          WRITE(*,*) 'MAX = ',MULTMAX
          STOP
        ENDIF
C*** EINLESEN DER WELLENLAENGEN
        DO 201 I=1, MMAX
          CALL SARGV (LINE, I+2, ACTPAR)
          READ (ACTPAR,'(BN, F20.0)', ERR=96) X
          X = XFACID*X + XOFFID
          IF (BIDLOG) X = ALOG10(X)
         IF (ID_INBOX) THEN
            IF((X-B(2))*(X-B(3)) .GT. .0) RETURN	 
         ENDIF
          XMULT(I) = X 
201     CONTINUE
C*** EINLESEN DES TEXT-STRINGS
        CALL SARGREST (LINE, N, MARG, NSTART, NN)
        IF (LINE(NN:NN) .EQ. '"') THEN
          N2 = NN - 1
        ELSE
          N2 = NN
        ENDIF
        LINEID = LINE(NSTART:N2)

        IID = IID + 1
C*** EINZELNE TICKS
        DO 203 I=1, MMAX
          XCM = (XMULT(I) - B(2)) * B(1)
          CALL GPLOT (XCM, YID, 3)
          CALL GPLOT (XCM, YID+XIDMLEN1*XLENGID, 2)
203     CONTINUE
C*** BALKEN
        XCM = (XMULT(1) - B(2)) * B(1)
        CALL GPLOT (XCM, YID+XIDMLEN1*XLENGID, 3)
        XCM = (XMULT(MMAX) - B(2)) * B(1)
        CALL GPLOT (XCM, YID+XIDMLEN1*XLENGID, 2)
        IF (.NOT. IDMCOMB) THEN
C*** VERBINDUNGSTRICH
          XCM = ((XMULT(1) + XMULT(MMAX)) / 2. - B(2)) * B(1)
          CALL GPLOT (XCM, YID+XIDMLEN1*XLENGID, 3)
          CALL GPLOT (XCM, YID+XIDMLEN1*XLENGID, 2)
          IF (IID .EQ. 1 .OR. (XCM - POSXID)*IDDIR .GT. SIZEID2
     >        .AND. .NOT. IDCON) THEN
            POSXID = XCM
          ELSE
            POSXID = POSXID + SIZEID2 * IDDIR
          ENDIF
          CALL GPLOT (POSXID, YID+(XIDMLEN1+XIDMLEN2)*XLENGID, 2)
          CALL GPLOT (POSXID, YID+XLENGID, 2)
          if (XLENGID .LT. 0.) then ! IDMULT downwards 
           CALL MYTLEN (TEXTLEN, SIZEID, LINEID, IDX(LINEID))
           CALL MYSYMBL (POSXID+0.5*SIZEID,YID+XLENGID-0.5*SIZEID
     >                    -TEXTLEN, 
     >                  SIZEID, LINEID, 90.)
          else
           CALL MYSYMBL (POSXID+0.5*SIZEID, YID+XLENGID+0.5*SIZEID,
     >                  SIZEID, LINEID, 90.)
          endif
        ENDIF



C***  KASDEF IDLOG  (IDENTS switched for logarithmic wavelenghts scale)
C-----------------------
      ELSE IF (ACTPAR .EQ. 'IDLOG') THEN
         BIDLOG = .TRUE.

C***  KASDEF IDNOLOG  (IDENTS switched back from logarithmic wavelenghts scale)
C-----------------------
      ELSE IF (ACTPAR .EQ. 'IDNOLOG') THEN
         BIDLOG = .FALSE.

C***  KASDEF ID_INBOX  (IDENTS restricted to box range)
C-----------------------
      ELSE IF (ACTPAR .EQ. 'ID_INBOX') THEN
         ID_INBOX = .TRUE.

      ELSE
          WRITE(*,'(/,A)') 'NON-FATAL ERROR: UNRECOGNIZED KASDEF OPTION'
          WRITE(*,*) 'THE ERROR OCCURED IN THE FOLLOWING LINE:'
          WRITE(*,*) LINE(:IDX(LINE))

      ENDIF

      RETURN

C**********************************************************************
C***  EROR BRANCH
C**********************************************************************
96    WRITE(*,'(/,A)') '*****  INPUT CONVERSION ERROR'
      WRITE(*,'(A)') 'THE ERROR OCCURED IN THE FOLLOWING LINE:'
      WRITE(*,'(A)') LINE(:IDX(LINE))
      STOP 'FATAL ERROR IN KD_IDENT'

      END
isosteal.f/     1653499937  5006  320   100644  2082      `
      SUBROUTINE ISOSTEAL
C****************************************************
C***  This is a special version of the program MY_ISOEX
C***  It creates an isoplot file from all .out files in the present directory
C***  In contrast to MY_ISOEX, it is assumed that 
C***  the .out files are from STEAL with OUTPUT ONLY and PRINT TAU
C***  In the present version, the output parameter is T* / SQRT (R2/3)
C****************************************************

      CHARACTER LINE*80, ACTPAR*10, ACTPAR2*10, MODEL*10, TOLD*10


C***  The following "grep" should extract 3 lines from each formal.out, 
C***  containing the lines with
C***    1) T*
C***    2) Rt
C***    3) R2/3
C***  The extracted lines are written to file iso.dat and can be checked there!
      CALL SYSTEM 
     > ('grep -e "T\*" -e Rt -e "ROSSELAND = 2/3" *.out ' // 
     >  '| cut -c1-80 > iso.dat')


      CALL SYSTEM ('cat iso.part1 > isoex.iso')

C***  Now iso.dat is read, the parameters are parsed from the lines 
C***   and the table is written to isoex.iso 
C***   in the proper input format for isopro 
      OPEN (10, FILE='iso.dat', STATUS='OLD')
      TOLD = ' '

    1 READ (10, '(A)', END=100) LINE

      call sargv (line, 2, actpar)
      if (actpar .ne. 'T*') goto 100

      CALL SARGV (LINE,3,ACTPAR)
      IF (ACTPAR .NE. TOLD) WRITE (20,'(A)') 'T=' // ACTPAR
      TOLD = ACTPAR

      READ (10, '(A)', END=999) LINE
      CALL SARGV (LINE,3,ACTPAR)

      READ (10, '(A)', END=999) LINE
      CALL SARGV (LINE,4,ACTPAR2)
      CALL SARGV (LINE,1,MODEL)

C***  Umrechnen von T* auf T2/3
      READ (TOLD,*) TSTAR
      READ (ACTPAR2,*) R23
      T23 = TSTAR / SQRT(R23) 
      t23 = alog10(t23)
      WRITE (ACTPAR2,'(F8.3)') T23 

      WRITE (20,'(2X,A,2X,A,2X,A)') ACTPAR, ACTPAR2, MODEL

      GOTO 1


  100 CONTINUE

      WRITE (20,'(A)') 'END'
      CLOSE (20)
      CLOSE (10)

      CALL SYSTEM ('cat fort.20 >> isoex.iso')
      CALL SYSTEM ('rm -f fort.20')

      STOP 'O.K.'

C***  Error
999   CONTINUE
      STOP 'ERROR: EOF reached before line-triple completed' 

      END

binning.f/      1553528659  5006  320   100644  1680      `
      SUBROUTINE BINNING (X, Y, NDATMAX, IDAT, W, MPACTIVE)
C**********************************************************************
C***  BINNING OF A DATASET (W = width over which points are binned
C***  CALLED FROM: SUBR. EXCMD  
C**********************************************************************
      DIMENSION X(NDATMAX), Y(NDATMAX)
      LOGICAL MPACTIVE

C**********************************************************************
C***              CHECK OF MONOTONIC SEQUENCE                       ***
C**********************************************************************

      V = X(IDAT)-X(1)
      DO 2 I=2,IDAT
        IF (V*(X(I)-X(I-1)) .LT. 0.) THEN
          WRITE(6,*) 'BINNING: DATASET NOT IN MONOTONIC SEQUENCE'
          WRITE (6,*) X(I), X(I-1)
          RETURN
        ENDIF
2     CONTINUE


C**** LOOP OVER ALL DATA POINTS *******************************
      IOLD = 1
      INEW = 1
      
      
C***  Find number of points within the binning width W      
    1 CONTINUE
      XSUM = .0
      YSUM = .0
      ISUM = 0
      DO I = IOLD, IDAT
         IF (ABS(X(IOLD)-X(I)) .GT. W) EXIT
         XSUM = XSUM + X(I)
	 YSUM = YSUM + Y(I)
	 ISUM = ISUM + 1
	 IOLDLAST = I
ccc      write (*,*) INEW, I, X(I)
      ENDDO
      
      X(INEW) = XSUM / FLOAT(ISUM)
      Y(INEW) = YSUM / FLOAT(ISUM)
      IOLD = IOLDLAST + 1
      INEW = INEW + 1    
      IF (IOLDLAST .LT. IDAT) GOTO 1

      IF (.NOT. MPACTIVE)
     >  WRITE (*,'(/,A,I6,A,I6,A)') 
     >            'INFO from BINNING: DATASET reduced from ', IDAT, 
     >            ' to ', INEW-1, ' points'

C***  Finished. New number of points is
      IDAT = INEW-1
      
      RETURN
      END
wrssum_rauch.f/ 1553528659  5006  320   100644  3396      `
      subroutine wrssum_rauch
c ***
c *** read and sum WRPLOT statistics file
c ***
c *** last modified 13-JAN-2005
c ***
c *** TR

      parameter (n=20)
      
      character*9  user(n),usertmp
      character*18 date(n),datestat
      character*80 record
      dimension ieps(n),iscreen(n),iwrplot(n)

      data idate/0/,iuser/0/,ieps/n*0/,iscreen/n*0/,iwrplot/n*0/
      data iepss/0/,iscreens/0/,iwrplots/0/
      open(1,file='~wrh/wrplot.dir/admin.dir/wrplot.statistic',
     >       form='formatted',status='old')

 1    read(1,'(a80)',end=2) record
      if(record(1:1).eq.'-')                                    then
        if(idate.eq.0)                                          then
          read(1,'(a80)',end=2) record
          datestat=record(33:50)
          idate=1
        endif
        read(1,'(a80)',end=2) record
        read(1,'(a80)',end=2) record
        read(1,'(a80)',end=2) record
        do i=1,n
          read(1,'(a80)',end=2) record
          if(record(1:1).eq.'-')                                goto  3
          user(i)=record(1:9)
          read(record(10:80),*) iwrplot(i),iscreen(i),ieps(i)
          date(i)=record(33:50)
        enddo
 3      continue
        iuser=i-1
        read(1,'(a80)',end=2) record
        read(record(10:80),*) iwrplots,iscreens,iepss
        read(1,'(a80)',end=2) record
        read(1,'(a80)',end=2) record
      else
        if(idate.eq.0)                                          then
          datestat=record(1:18)
          idate=1
        endif
      endif


      usertmp=record(20:28)      

      do i=1,iuser
        if(usertmp.eq.user(i))                                  goto  4
      enddo

      iuser=iuser+1
      user(iuser)=usertmp

 4    continue

      date(i)=record(1:18)
      read(record(29:80),*) iuse

          if(iuse.eq.-1)                                        then
        iwrplot(i)=iwrplot(i)+1
        iwrplots  =iwrplots  +1
      elseif(iuse.eq. 3)                                        then
           ieps(i)=   ieps(i)+1
           iepss  =   iepss  +1
      elseif(iuse.eq. 5)                                        then
        iscreen(i)=iscreen(i)+1
        iscreens  =iscreens  +1
      else
        stop 'WRSSUM-ERR, unknown device'
      endif

                                                                goto  1
 2    continue
         
      write(*,'(50("-"))')
      write(*,'("WRPLOT user statistic since",A23)') datestat
      write(*,'(50("-"))')
      write(*,'(" User     Calls   Screen    ps       Last Use")')
      write(*,'(50("-"))')
      do i=1,iuser
        write(*,'(A9,i6,i8,i7,a20)') 
     >            user(i),iwrplot(i),ieps(i),iscreen(i),date(i)
      enddo
      write(*,'(50("-"))')
      write(*,'(I2," USER",I8,I8,I7)') iuser,iwrplots,iscreens,iepss
      write(*,'(50("-"))')

      rewind 1

      write(1,'(50("-"))')
      write(1,'("WRPLOT user statistic since",A23)') datestat
      write(1,'(50("-"))')
      write(1,'(" User     Calls   Screen    ps       Last Use")')
      write(1,'(50("-"))')
      do i=1,iuser
        write(1,'(A9,i6,i8,i7,a20)') 
     >            user(i),iwrplot(i),ieps(i),iscreen(i),date(i)
      enddo
      write(1,'(50("-"))')
      write(1,'(I2," USER",I8,I8,I7)') iuser,iwrplots,iscreens,iepss
      write(1,'(50("-"))')

      close (1)

      stop '%WRSSUM-END; program successfully completed'

      end
checkmono.f/    1553528659  5006  320   100644  1239      `
      SUBROUTINE CHECKMONO (X, ND, IORDER, IERR)
C**************************************************************************
C***  Checks if a vector X(ND) is strictly monotonic
C***  Prints message into channel 0
C***  Returns Error flag IERR, if not monotonic
C***  Returns ORDER = +1 if ascending, ORDER=-1 if descending
C**************************************************************************
      DIMENSION X(ND)
      IERR = 0

      IF (ND .LT. 2) THEN
         WRITE (0,'(//,A)') 'ERROR: THIS TABLE IS NOT MONOTONIC'
           WRITE (0,'(A)') 'BECAUSE IT HAS LESS THAN 2 DATA POINTS'
           IERR = 1
	   IORDER = 0
	   RETURN
      ENDIF

      DX = X(2) - X(1)
      DO I=3, ND
         IF ((X(I)-X(I-1))*DX .LE. .0) THEN
            WRITE (0,'(//,A)') 'ERROR: THIS TABLE IS NOT MONOTONIC'
            WRITE (0,'(A,I5)') 'THE ERROR WAS ENCOUNTERED AT INDEX=', I
            WRITE (0,'(A)')    'THE LAST 3 X-VALUES ARE:' 
            WRITE (0,'(2X,G15.7)') X(I-2) 
 	        WRITE (0,'(2X,G15.7)') X(I-1) 
	        WRITE (0,'(2X,G15.7)') X(I)
            IERR = 1
            IORDER = 0
            RETURN
         ENDIF
      ENDDO
      
      IORDER = 1.
      IF (DX. LT. .0) IORDER = -1
      
      RETURN
      END

excf.f/         1729609023  5006  320   100644  10609     `
      SUBROUTINE EXCF (LINE, ACTPAR, VAR, MAXVAR, NVAR, X, Y, 
     >               ND, NDATMAX, ISYM,
     >               BLINREGYERR, YERR1, YERR2, YERRTYPE, NDATYERR)

C**********************************************************************
C***  EXECUTE "COMMAND FUNCTIONS" which return values into variables
C***   Their keywords must start with "CF-"
C***  CALLED FROM EXCMD
C**********************************************************************

      DIMENSION X(NDATMAX), Y(NDATMAX), XEP(2), YEP(2)
      DIMENSION YERR1(NDATMAX), YERR2(NDATMAX)
      CHARACTER*(*) LINE, ACTPAR, YERRTYPE
      CHARACTER*20 ACTPAR1, ACTPAR2
      CHARACTER*(*) VAR(MAXVAR,2)
      LOGICAL BFROM, BTO, BLINREGYERR


      CALL SARGC (LINE, NPAR)

      IF (NPAR .LT. 3) GOTO 96

C***  Dataset empty?
      IF (ACTPAR .EQ. 'CF-NDATA') THEN
C     Write number of datapoints for current dataset into variable
        CALL SARGV (LINE, 3, ACTPAR1)
        WRITE (ACTPAR2, '(I10)') ND
        CALL FLUSHLEFT (ACTPAR2)
        CALL PUTVAR (ACTPAR1, ACTPAR2, VAR, MAXVAR, NVAR)
        GOTO 95
      ENDIF
            
      IF (ND .LT. 1) GOTO 98
      
C***  CF-YEXT **********************************************************
      IF (ACTPAR .EQ. 'CF-YEXT') THEN
         CALL SARGV (LINE, 3, ACTPAR)
         READ (ACTPAR, '(BN,F20.0)',ERR=99) XTEST

         IF (ND .EQ. 1) THEN
            IF (X(1) .NE. XTEST) THEN
              WRITE (0,'(//,A)') 'WARNUNG: DATASET HAS ONLY ONE POINT'
              WRITE (0,'(7X,A, G10.3)') 'AT X(1)=', X(1)
              WRITE (0,'(7X,A)') 'WHICH IS NOT IDENTICAL WITH THE POINT'
              WRITE (0,'(7X,A, G10.3)') 'FOR EXTRACTION = ', XTEST
            ENDIF
C*          Y-value is returned in any case, without error stop
            YINPO = Y(1)
            GOTO 10 
         ENDIF 
C***  Check monotonic order
         CALL CHECKMONO (X, ND, IORDER, IERR)
         IF (IERR .GT. .0) GOTO 97
	 
         IF ((XTEST-X(1)) * (XTEST-X(ND)) .GT. .0) THEN
            WRITE (0,'(//,A)') 'ERROR: X-VALUE LIES OUTSIDE INTERVAL:'
            WRITE (0,'(A,G15.7)') 'X(1) = ', X(1) 
            WRITE (0,'(A,G15.7)') 'X(LAST) = ', X(ND)
            WRITE (0,'(A,G15.7)') 'X-TEST = ', XTEST 
            GOTO 97
         ENDIF

C***  SPLINE INTERPOLATION IF SYMBOL OF SECOND DATASET IS 6 OR 7
          IF (ISYM .NE. 6 .AND. ISYM .NE. 7) THEN
            CALL LINPO (YINPO, XTEST, Y(1), X(1), ND) 
          ELSE
            CALL FSPLINE (YINPO, XTEST, Y(1), X(1), ND)
          ENDIF

   10     CALL SARGV (LINE, 4, ACTPAR1)
          WRITE (ACTPAR2, '(G15.7)') YINPO
          CALL FLUSHLEFT(ACTPAR2)
          CALL PUTVAR (ACTPAR1, ACTPAR2, VAR, MAXVAR, NVAR)

C***    CF-XMAX  *********************************************************
C-----  Returns two variables x, y where table has maximum x-value
      ELSE IF (ACTPAR .EQ. 'CF-XMAX') THEN
      IF (NPAR .LT. 4) GOTO 96
          XMAX = X(1)
          YMAX = Y(1)
          DO II=2, ND
            IF (X(II) .GT. XMAX) THEN
              XMAX = X(II)
              YMAX = Y(II)
            ENDIF
          ENDDO
          CALL SARGV (LINE, 3, ACTPAR1)
          WRITE (ACTPAR2, '(G15.7)') XMAX
	  CALL FLUSHLEFT (ACTPAR2)
          CALL PUTVAR (ACTPAR1, ACTPAR2, VAR, MAXVAR, NVAR)
          CALL SARGV (LINE, 4, ACTPAR1)
          WRITE (ACTPAR2, '(G15.7)') YMAX
	  CALL FLUSHLEFT (ACTPAR2)
          CALL PUTVAR (ACTPAR1, ACTPAR2, VAR, MAXVAR, NVAR)

C***    CF-XMIN  *********************************************************
C-----  Returns two variables x, y where table has minimum x-value
      ELSE IF (ACTPAR .EQ. 'CF-XMIN') THEN
      IF (NPAR .LT. 4) GOTO 96
          XMIN = X(1)
          YMIN = Y(1)
          DO II=2, ND
            IF (X(II) .LT. XMIN) THEN
              XMIN = X(II)
              YMIN = Y(II)
            ENDIF
          ENDDO
          CALL SARGV (LINE, 3, ACTPAR1)
          WRITE (ACTPAR2, '(G15.7)') XMIN
	  CALL FLUSHLEFT (ACTPAR2)
          CALL PUTVAR (ACTPAR1, ACTPAR2, VAR, MAXVAR, NVAR)
          CALL SARGV (LINE, 4, ACTPAR1)
          WRITE (ACTPAR2, '(G15.7)') YMIN
	  CALL FLUSHLEFT (ACTPAR2)
          CALL PUTVAR (ACTPAR1, ACTPAR2, VAR, MAXVAR, NVAR)

C***    CF-YMAX  *********************************************************
C-----  Returns two variables x, y where table has maximum y-value
      ELSE IF (ACTPAR .EQ. 'CF-YMAX') THEN
      IF (NPAR .LT. 4) GOTO 96
          XMAX = X(1)
          YMAX = Y(1)
          DO II=2, ND
            IF (Y(II) .GT. YMAX) THEN
              XMAX = X(II)
              YMAX = Y(II)
            ENDIF
          ENDDO
          CALL SARGV (LINE, 3, ACTPAR1)
          WRITE (ACTPAR2, '(G15.7)') XMAX
	  CALL FLUSHLEFT (ACTPAR2)
          CALL PUTVAR (ACTPAR1, ACTPAR2, VAR, MAXVAR, NVAR)
          CALL SARGV (LINE, 4, ACTPAR1)
          WRITE (ACTPAR2, '(G15.7)') YMAX
	  CALL FLUSHLEFT (ACTPAR2)
          CALL PUTVAR (ACTPAR1, ACTPAR2, VAR, MAXVAR, NVAR)

C***    CF-YMIN  *********************************************************
C-----  Returns two variables x, y where table has minimum y-value
      ELSE IF (ACTPAR .EQ. 'CF-YMIN') THEN
      IF (NPAR .LT. 4) GOTO 96
          XMIN = X(1)
          YMIN = Y(1)
          DO II=2, ND
            IF (Y(II) .LT. YMIN) THEN
              XMIN = X(II)
              YMIN = Y(II)
            ENDIF
          ENDDO
          CALL SARGV (LINE, 3, ACTPAR1)
          WRITE (ACTPAR2, '(G15.7)') XMIN
	  CALL FLUSHLEFT (ACTPAR2)
          CALL PUTVAR (ACTPAR1, ACTPAR2, VAR, MAXVAR, NVAR)
          CALL SARGV (LINE, 4, ACTPAR1)
          WRITE (ACTPAR2, '(G15.7)') YMIN
	  CALL FLUSHLEFT (ACTPAR2)
          CALL PUTVAR (ACTPAR1, ACTPAR2, VAR, MAXVAR, NVAR)

C***    CF-YSUM   *************************************************
C-----  Returns the sum of all y-values
      ELSE IF (ACTPAR .EQ. 'CF-YSUM') THEN
          YSUM = .0
          DO II=1, ND
             YSUM = YSUM + Y(II)
          ENDDO
          CALL SARGV (LINE, 3, ACTPAR1)
          WRITE (ACTPAR2, '(G15.7)') YSUM
	  CALL FLUSHLEFT (ACTPAR2)
          CALL PUTVAR (ACTPAR1, ACTPAR2, VAR, MAXVAR, NVAR)

C***  CF-INT  *************************************************
C**** Integration
      ELSE IF (ACTPAR .EQ. 'CF-INT') THEN
         CALL CHECKMONO (X, ND, IORDER, IERR)
C**      Decoding the optional parameters (integration boundaries)
         BFROM = .FALSE.
         BTO = .FALSE.
         DO I=4, NPAR
	    CALL SARGV (LINE, I, ACTPAR1)
	    IF (ACTPAR1 .EQ. 'FROM') THEN
               BFROM = .TRUE.
	       CALL SARGV (LINE, I+1, ACTPAR2)
               READ (ACTPAR2, '(F20.0)') FROM
               IF ((FROM-X(1)) * (FROM-X(ND)) .GT. .0) THEN
                WRITE (0,'(//,A)') 
     >            'ERROR: INTEGRATION BOUNDARY OUTSIDE INTERVAL:'
                WRITE (0,'(A,G15.7)') 'X(1) = ', X(1) 
                WRITE (0,'(A,G15.7)') 'X(LAST) = ', X(ND)
                WRITE (0,'(A,G15.7)') 'FROM = ', FROM 
                GOTO 97
               ENDIF
	    ELSE IF (ACTPAR1 .EQ. 'TO') THEN
               BTO = .TRUE.
	       CALL SARGV (LINE, I+1, ACTPAR2)
               READ (ACTPAR2, '(F20.0)') TO
               IF ((TO-X(1)) * (TO-X(ND)) .GT. .0) THEN
                WRITE (0,'(//,A)') 
     >            'ERROR: INTEGRATION BOUNDARY OUTSIDE INTERVAL:'
                WRITE (0,'(A,G15.7)') 'X(1) = ', X(1) 
                WRITE (0,'(A,G15.7)') 'X(LAST) = ', X(ND)
                WRITE (0,'(A,G15.7)') 'TO = ', TO 
                GOTO 97
               ENDIF
	    ENDIF
	 ENDDO

         IF (BFROM .NEQV. BTO) THEN
	    WRITE (0,'(//,A)') 'ERROR: You must give either both or no'
	    WRITE (0,'(A)') '       integration boundaries FROM, TO'
            GOTO 97
         ENDIF

C**      Boundaries explicitely given
         IF (BFROM) THEN

            IF (FROM .LT. TO) THEN
               VORZEICH = 1.
	    ELSE
               VORZEICH = -1.
               XX = TO
               TO = FROM
	       FROM = XX
	    ENDIF 

            CALL LIPO_IND (NAF, NBF, FROM, X, ND)
            CALL LIPO_IND (NAT, NBT, TO, X, ND)
            CALL LINPO (YFROM, FROM, Y, X, ND)
            CALL LINPO (YTO  , TO  , Y, X, ND)
	    
            IF (IORDER .GT. 0) THEN 
	       IFIRST = NBF
               LAST   = NAT
               YSUM = (Y(IFIRST) + YFROM) * (X(IFIRST) - FROM) * 0.5 
     >              + (Y(LAST  ) + YTO  ) * (TO     - X(LAST)) * 0.5
	    ELSE
	       IFIRST = NBT
               LAST   = NAF
               YSUM = (Y(LAST  ) + YFROM) * (X(LAST) - FROM) * 0.5 
     >              + (Y(IFIRST) + YTO  ) * (TO - X(IFIRST)) * 0.5
	    ENDIF 
         ELSE
C***  No boundaries given - whole range integrated
            IFIRST = 1
	    LAST = ND
            VORZEICH = 1.
            YSUM = .0
	 ENDIF

C*** If not more than 1 point betwen boundaries, skip the following
          IF (LAST .GT. IFIRST) THEN
          YSUM = YSUM 
     >         + Y(IFIRST) * ABS(X(IFIRST+1)-X(IFIRST )) * 0.5 
     >         + Y(LAST  ) * ABS(X(LAST    )-X(LAST -1)) * 0.5
          ENDIF

C*** If boundaries fall into the same interval, replace the sum by:
          IF (LAST .LT. IFIRST) 
     >      YSUM = (YFROM + YTO) * (TO - FROM) * 0.5	  
	  
          DO II=IFIRST+1, LAST-1
             YSUM = YSUM + Y(II) *
     >              ABS(X(II+1)-X(II-1)) * 0.5
          ENDDO
	  YSUM = VORZEICH * YSUM
          CALL SARGV (LINE, 3, ACTPAR1)
          WRITE (ACTPAR2, '(G15.7)') YSUM
	  CALL FLUSHLEFT (ACTPAR2)
          CALL PUTVAR (ACTPAR1, ACTPAR2, VAR, MAXVAR, NVAR)

C***  CF-LINREG  *************************************************
C***  Linear Regression following NR with error
      ELSE IF (ACTPAR .EQ. 'CF-LINREG') THEN
       IF (ND .LT. 2) GOTO 98         
       CALL CFLINREG (LINE, ACTPAR, VAR, MAXVAR, NVAR, X, Y, 
     >               ND, NDATMAX, ISYM,
     >               BLINREGYERR, YERR1, YERR2, YERRTYPE, NDATYERR, 
     >               NPAR)

      ELSE
         WRITE (0,'(//,A)') 'ERROR: Unknown COMMAND FUNCTION'
         GOTO 97
      ENDIF

   95 RETURN

C***  ERROR messages **************************************************

   99 WRITE (0,'(//,A)') 'ERROR: INVALID FORMAT IN COMMAND-FUNCTION - '
      GOTO 97

   96 WRITE (0,'(//,A)') 'ERROR: COMMAND-FUNCTION CALL'
      WRITE (0,'(A)') 'HAS NOT ENOUGH PARAMETERS'
      GOTO 97
   
   98 WRITE (0,'(//,A)') 'ERROR: COMMAND-FUNCTION CALLED,'
      WRITE (0,'(A)') 'BUT DATASET HAS NO POINTS'
      GOTO 97
   

   97 CONTINUE
      WRITE (0,'(A)')     'The error occured in the following line: '
      WRITE (0,'(A)')     LINE(:IDX(LINE))
      STOP '*** FATAL ERROR in Subr. EXCF'

      END

linpo.f/        1553528659  5006  320   100644  868       `
      SUBROUTINE LINPO (Y, X, YI, XI, N)
C***********************************************************************
C***  LINEAR INTERPOLATION: FOR GIVEN X, FIND Y=F(X) FROM A TABLE FI(XI)
C ------ INDEXSUCHE DURCH BISECTION ------
C***********************************************************************

      DIMENSION XI(N), YI(N)

      NA=1
      A=XI(1)
      NB=N
      B=XI(N)

      IF((X-A)*(X-B).GT..0) THEN
        WRITE (0,'(A,3(1X,G12.5))')
     >    'INTERPOLATION CALLED OUT OF INTERVAL: ', XI(1), X, XI(N)
        STOP 'ERROR IN SUBR. LINPO'
      ENDIF

    1 IF((NB-NA).EQ.1) GOTO 2
      NH=(NA+NB)/2
      H=XI(NH)
      IF((X-A)*(X-H).GT..0) GOTO 3
      NB=NH
      B=H
      GOTO 1
    3 NA=NH
      A=H
      GOTO 1
 
    2 CONTINUE
      P = (X-XI(NA))/(XI(NB)-XI(NA))
      Q = 1. - P
      Y = P * YI(NB) + Q * YI(NA)
      RETURN
      END
varlegal.f/     1553528659  5006  320   100644  892       `
      SUBROUTINE VARLEGAL (LINE, VARNAME, CALLEDFROM)
      CHARACTER*(*) LINE, VARNAME, CALLEDFROM
      CHARACTER DELIM*20, DOLLAR*1
      LOGICAL CHRINSTR

      DOLLAR    = CHAR(36)
      
      IF (CALLEDFROM .EQ. 'CALC') THEN
         DELIM = ' ,=:+-*/^{}()"' // DOLLAR 
      ELSE
         DELIM = ' ,=:^{}()"' // DOLLAR
      ENDIF

      IDL1 = IDX(VARNAME)

         DO K=1, IDL1 
            IF (CHRINSTR(VARNAME(K:K),DELIM)) GOTO 99
         ENDDO
      
      RETURN
      
C*****  Error branch ***********************************************      
      
   99 WRITE (*, '(//,A,A)') '**** Illegal variable name:', 
     >       VARNAME(:IDX(VARNAME))
      WRITE (*,*) 'The following characters are not allowed: '//DELIM 
      WRITE (*,*) 'THE ERROR OCCURED IN THE FOLLOWING LINE:'
      WRITE (*,*) LINE(:IDX(LINE))
      STOP 'FATAL ERROR IN SUBR. VARLEGAL'
      
      END
kd_date.f/      1553528659  5006  320   100644  1281      `
      SUBROUTINE KD_DATE (LINE, B, C, XUNITS, YUNITS, XOFS, YOFS)
C**********************************************************
C***  Printing a stamp with date and time on the plot
C**********************************************************

      DIMENSION B(6),C(6)
      CHARACTER CDATE*9, CTIME*8, TLUN*40, LINE*(*)

        CALL SARGC (LINE, N)
        IF (N .EQ. 2) THEN
          XLUN = B(3)
          YLUN = C(3)
          XLUNOFS = 1.0
          YLUNOFS = 0.0
          SLUN = 0.2
          ANGLUN = -90.
        ELSE
          CALL DECXYUNITS  (LINE, 3, B, C, XUNITS )
          CALL DECXYUNITS  (LINE, 4, B, C, YUNITS )
          CALL DECFPNUM    (LINE, 5, XOFS)
          CALL DECFPNUM    (LINE, 6, YOFS)
          CALL DECFPNUM    (LINE, 7, SLUN   )
          CALL DECFPNUM    (LINE, 8, ANGLUN )
C         Not to spoil the SAME parameters, if none are given here
	  XLUN = XUNITS
	  YLUN = YUNITS  
          XLUNOFS = XOFS 
	  YLUNOFS = YOFS 
        ENDIF

          CALL DATE(CDATE)
          CALL TIME(CTIME)
          TLUN = 'Plot created on ' // CDATE // ' ' // CTIME
C***      CONVERT INTO CM
          XCM = (XLUN-B(2)) * B(1) + XLUNOFS
          YCM = (YLUN-C(2)) * C(1) + YLUNOFS
          CALL MYSYMBL (XCM, YCM, SLUN, TLUN, ANGLUN)

      RETURN

      END

kd_file.f/      1553528659  5006  320   100644  1191      `
      SUBROUTINE KD_FILE (LINE, B, C, XUNITS, YUNITS, XOFS, YOFS,
     >                    FNAME)
C**********************************************************
C***  Printing a stamp with the name of the present plotfile
C**********************************************************

      DIMENSION B(6),C(6)
      CHARACTER FNAME*(*), LINE*(*)

        CALL SARGC (LINE, N)
        IF (N .EQ. 2) THEN
          XLUN = B(3)
          YLUN = C(3)
          XLUNOFS = 1.4
          YLUNOFS = 0.0
          SLUN = 0.2
          ANGLUN = -90.
        ELSE
          CALL DECXYUNITS  (LINE, 3, B, C, XUNITS )
          CALL DECXYUNITS  (LINE, 4, B, C, YUNITS )
          CALL DECFPNUM    (LINE, 5, XOFS)
          CALL DECFPNUM    (LINE, 6, YOFS)
          CALL DECFPNUM    (LINE, 7, SLUN   )
          CALL DECFPNUM    (LINE, 8, ANGLUN )
C         Not to spoil the SAME parameters, if none are given here
	  XLUN = XUNITS
	  YLUN = YUNITS  
          XLUNOFS = XOFS 
	  YLUNOFS = YOFS 
        ENDIF

C***      CONVERT INTO CM
          XCM = (XLUN-B(2)) * B(1) + XLUNOFS
          YCM = (YLUN-C(2)) * C(1) + YLUNOFS
          CALL MYSYMBL (XCM, YCM, SLUN, FNAME, ANGLUN)

      RETURN

      END

kd_linunlab.f/  1553528659  5006  320   100644  4631      `
      SUBROUTINE KD_LINUNLAB (LINE, B, C, XOLIUN, YOLIUN, BBGR, 
     >                        IBGRCOL, BGRL, BGRR, BGRD, BGRU, 
     >                        LASTCOLOR, BGRLINE)
C-------------------------------------------------------------
C***  KASDEF LINUNLAB (DRAWING A LINE, INTERRUPTED BY A LABEL) 
C-------------------------------------------------------------
      COMMON /COMIDEV/ IDEV
      CHARACTER*(*) LINE, BGRLINE
      DIMENSION B(6),C(6)
      CHARACTER ACTPAR*20, TLAB*144, ACTPAR2*80
      LOGICAL BBGR, BHATCH

      DATA PI / 3.14159 /

      SAVE SYMXO, SYMYO, SIZE
 
      BHATCH = .FALSE. 
      CALL SARGC (BGRLINE, NARG)
      DO I=1, NARG
         CALL SARGV (BGRLINE, I, ACTPAR2)
         IF (ACTPAR2 .EQ. 'HATCHED' .OR. ACTPAR2 .EQ. 'HTYPE') THEN
            BHATCH = .TRUE.
            EXIT
         ENDIF
      ENDDO

         CALL DECXYUNITS  (LINE, 3, B, C, X1LIUN )
         CALL DECXYUNITS  (LINE, 4, B, C, Y1LIUN )
         CALL DECXYUNITS  (LINE, 5, B, C, X2LIUN )
         CALL DECXYUNITS  (LINE, 6, B, C, Y2LIUN )
         CALL DECFPNUM    (LINE, 7,       XOLIUN )
         CALL DECFPNUM    (LINE, 8,       YOLIUN )
         CALL DECFPNUM    (LINE, 9,       OFFCENTER )
         CALL DECFPNUM    (LINE, 10,      SIZE )
         CALL SARGREST (LINE, N, 11, NSTART, NN)
         TLAB = LINE(NSTART:)
C***
         PX1 = (X1LIUN-B(2))*B(1) + XOLIUN
         PX2 = (X2LIUN-B(2))*B(1) + XOLIUN
         PY1 = (Y1LIUN-C(2))*C(1) + YOLIUN
         PY2 = (Y2LIUN-C(2))*C(1) + YOLIUN
C***     TOTAL DISTANCE BETWEEN ENDPOINTS (PYTHAGORAS)
         DX = PX2 - PX1
         DY = PY2 - PY1
         TOTLEN = SQRT (DX * DX + DY * DY)

         IF (TOTLEN .EQ. .0) THEN
	    WRITE (*,'(/A)') 'LINE HAS ZERO LENGTH'
            WRITE (*,'(A)') 'THE ERROR OCCURED IN THE FOLLOWING LINE:'
	    WRITE (*,'(A)') LINE(:IDX(LINE))
            STOP 'ERROR IN KDPLOT (LINUNLAB)'
	 ENDIF
	 
C***     ESTIMATE LENGTH OF THE STRING
         CALL MYTLEN (TEXTLEN, SIZE, TLAB, IDX(TLAB))
         TEXTLEN = TEXTLEN + SIZE

C***     FIND POINTS WHERE THE LINE MUST BE INTERRUPTED
         DXTEXTM = (-0.5 * TEXTLEN + OFFCENTER) * DX / TOTLEN
         DXTEXTP = ( 0.5 * TEXTLEN + OFFCENTER) * DX / TOTLEN
         DYTEXTP = ( 0.5 * TEXTLEN + OFFCENTER) * DY / TOTLEN
         DYTEXTM = (-0.5 * TEXTLEN + OFFCENTER) * DY / TOTLEN
         PXC = 0.5 * (PX1 + PX2) 
         PYC = 0.5 * (PY1 + PY2) 

         PXM = PXC + DXTEXTM 
         PXP = PXC + DXTEXTP
         PYM = PYC + DYTEXTM  
         PYP = PYC + DYTEXTP

         IF (.NOT. BBGR) THEN
            BGRR = 0.
            BGRL = 0.
         ENDIF

         PLXM = PXM - SIZE * BGRL * DX/TOTLEN
         PLXP = PXP + SIZE * BGRR * DX/TOTLEN
         PLYM = PYM - SIZE * BGRL * DY/TOTLEN
         PLYP = PYP + SIZE * BGRR * DY/TOTLEN
         CALL GPLOT (PX1, PY1, 3)
         CALL GPLOT (PLXM, PLYM, 2)
         CALL GPLOT (PLXP, PLYP, 3)
         CALL GPLOT (PX2, PY2, 2)

C***     INSERT LABEL
         ANG = ASIN ( DY / TOTLEN) * 180. / PI
         IF (DX .LT. 0) ANG = 180. - ANG
         XCM = PXM + 0.5 * SIZE * ( DX+DY) / TOTLEN 
         YCM = PYM + 0.5 * SIZE * (-DX+DY) / TOTLEN

C***     HINTERLEGEN DER SCHRIFT MIT EINEM FARBIG AUSGEFUELLTEN RECHTECK
         IF (BBGR) THEN
            SIZELUN = SIZE
            TEXLEN = TEXTLEN - SIZE
C***        Rotation matrix of Offsets from prefixes
            ARAD = ANG * PI / 180.
            CA = COS(ARAD)
            SA = SIN(ARAD)

            BGRXL = - SIZELUN*BGRL
            BGRXR = TEXLEN + SIZELUN*BGRR
            BGRYD = - SIZELUN*BGRD
            BGRYU = SIZELUN*(BGRU+1)

            X1 = BGRXL * CA - BGRYD * SA + XCM
            Y1 = BGRXL * SA + BGRYD * CA + YCM
            X2 = BGRXR * CA - BGRYD * SA + XCM
            Y2 = BGRXR * SA + BGRYD * CA + YCM
            X3 = BGRXR * CA - BGRYU * SA + XCM
            Y3 = BGRXR * SA + BGRYU * CA + YCM
            X4 = BGRXL * CA - BGRYU * SA + XCM
            Y4 = BGRXL * SA + BGRYU * CA + YCM
C***        open box:
            LC2 = LASTCOLOR
            CALL COLOR ('DATA', 'DUMMY', ABS(IBGRCOL), IDEV)
            CALL GCPLOT (X1, Y1, 3)
            CALL GCPLOT (X2, Y2, 2)
            CALL GCPLOT (X3, Y3, 2)
            CALL GCPLOT (X4, Y4, 2)
            CALL GCPLOT (X1, Y1, 2)
C***        Filling Command 
            IF (IBGRCOL .GE. 0 .AND. .NOT. BHATCH) THEN
               CALL GFILL
            ELSEIF (BHATCH) THEN
               CALL HFILL(BGRLINE)
            ENDIF
            CALL COLOR ('DATA', 'DUMMY', LC2, IDEV)
         ENDIF


         CALL MYSYMBL (XCM, YCM, SIZE, TLAB, ANG)
          
      RETURN

      END

plotanfs.f/     1553528659  5006  320   100644  1238      `
      SUBROUTINE PLOTANFS (KANAL,NPLOT,NHEAD,NX,NY,
     $ B1,B2,B3,B4,B5,B6,C1,C2,C3,C4,C5,C6,
     $ X,Y,N,STYLE)
C***********************************************************************
C***  DIESE ROUTINE BEREITET EIN NEUES PLOTFILE ZUR UEBERTRAGUNG VOR
C***  DIE ANGEGEBENEN WERTE BESCHREIBEN DEN PLOTKASTEN
C***********************************************************************
      CHARACTER*(*) NPLOT,NHEAD,NX,NY,STYLE

      WRITE (KANAL,1) NPLOT
      WRITE (KANAL, '(A)') 'KASDEF FONT=HELVET'
      WRITE (KANAL,2) NHEAD
      WRITE(KANAL,3) NX
      WRITE (KANAL,4) NY
    1 FORMAT (' PLOT   :',A)
    2 FORMAT (' HEADER :',A)
    3 FORMAT (' X-ACHSE:',A)
    4 FORMAT (' Y-ACHSE:',A)

C***  Special branch activating Lars' AUTO axes: set XMIN = XMAX!
      IF (B2 .EQ. B3) THEN
         WRITE (KANAL, 6)
    6   FORMAT (5X,
     $ 'MASSTAB    MINIMUM    MAXIMUM    TEILUNGEN  BESCHRIFT. DARUNTER'
     $  / ,' X: AUTO',/,' Y: ')
      ELSE
        WRITE (KANAL,5) B1,B2,B3,B4,B5,B6,C1,C2,C3,C4,C5,C6
    5   FORMAT (5X,
     $ 'MASSTAB    MINIMUM    MAXIMUM    TEILUNGEN  BESCHRIFT. DARUNTER'
     $  / ,' X: ',6(G12.6,1X),/,' Y: ',6(G12.6,1X))
      ENDIF

      CALL PLOTTABS (KANAL,X,Y,N,STYLE)

      RETURN
      END
indexx.f/       1553528659  5006  320   100644  2135      `
      SUBROUTINE INDEXX(N, ARR, INDX)

C***  GENERATE AN INDEX TABLE VIA QUICKSORT
C***  ROUTINE FROM NUMERICAL RECIPES FOR F77

      INTEGER N, INDX(N), M, NSTACK
      REAL ARR(N)
      PARAMETER (M=7, NSTACK=50)
      INTEGER I, INDXT, IR, ITEMP, J, JSTACK, K, L, ISTACK(NSTACK)
      REAL A

      DO 11 J = 1, N
        INDX(J) = J
11    CONTINUE
      JSTACK = 0
      L = 1
      IR = N
1     IF (IR-L .LT. M) THEN
        DO 13 J = L + 1, IR
          INDXT = INDX(J)
          A = ARR(INDXT)
          DO 12 I = J - 1, L, -1
            IF (ARR(INDX(I)) .LE. A) GOTO 2
            INDX(I+1) = INDX(I)
12        CONTINUE
          I = L - 1
2         INDX(I+1) = INDXT
13      CONTINUE
        IF (JSTACK .EQ. 0) RETURN
        IR = ISTACK(JSTACK)
        L = ISTACK(JSTACK-1)
        JSTACK = JSTACK - 2
      ELSE
        K = (L+IR) / 2
        ITEMP = INDX(K)
        INDX(K) = INDX(L+1)
        INDX(L+1) = ITEMP
        IF (ARR(INDX(L)) .GT. ARR(INDX(IR))) THEN
          ITEMP = INDX(L)
          INDX(L) = INDX(IR)
          INDX(IR) = ITEMP
        ENDIF
        IF (ARR(INDX(L+1)) .GT. ARR(INDX(IR))) THEN
          ITEMP = INDX(L+1)
          INDX(L+1) = INDX(IR)
          INDX(IR) = ITEMP
        ENDIF
        IF (ARR(INDX(L)) .GT. ARR(INDX(L+1))) THEN
          ITEMP = INDX(L)
          INDX(L) = INDX(L+1)
          INDX(L+1) = ITEMP
        ENDIF
        I = L + 1
        J = IR
        INDXT = INDX(L+1)
        A = ARR(INDXT)
3       CONTINUE
          I = I + 1
        IF (ARR(INDX(I)) .LT. A) GOTO 3
4       CONTINUE
          J = J - 1
        IF (ARR(INDX(J)) .GT. A) GOTO 4
        IF (J .LT. I) GOTO 5
        ITEMP = INDX(I)
        INDX(I) = INDX(J)
        INDX(J) = ITEMP
        GOTO 3
5       INDX(L+1) = INDX(J)
        INDX(J) = INDXT
        JSTACK = JSTACK + 2
        IF (JSTACK .GT. NSTACK) STOP 'SORT: INDEXX: NSTACK TOO SMALL'
        IF (IR-I+1 .GE. J-L) THEN
          ISTACK(JSTACK) = IR
          ISTACK(JSTACK-1) = I
          IR = J - 1
        ELSE
          ISTACK(JSTACK) = J - 1
          ISTACK(JSTACK-1) = L
          L = I
        ENDIF
      ENDIF
      GOTO 1
      END

quicksort.f/    1553528659  5006  320   100644  1995      `
      SUBROUTINE QUICKSORT(X,Y,NDATMAX,IDAT,BOPTIONS,X1,Y1)
C**********************************************************************
C***  SORTING OF A DATASET, CALLS INDEXX FROM NR (QUICKSORT) MAY2010
C***  CALLED FROM: SUBR. EXCMD
C**********************************************************************
      DIMENSION X(NDATMAX), Y(NDATMAX), X1(NDATMAX), Y1(NDATMAX)
      DIMENSION NEWINDICES(NDATMAX)
      LOGICAL BOPTIONS(2)
      REAL RTEMP
      INTEGER INEW

C**** SORT THE X-VALUES, RETURN INDEX-ARRAY ***************************
      CALL INDEXX(IDAT,X,NEWINDICES)

C**** COPY X-DATA TO TEMPORARY ARRAY **********************************
      DO J = 1, IDAT
         X1(J) = X(J)
      ENDDO

C**** RE-ARANGE X-DATA: SORTING ***************************************
      DO J = 1, IDAT
         IF (BOPTIONS(1)) THEN
          X(IDAT + 1 - J) = X1(NEWINDICES(J))
         ELSE
          X(J) = X1(NEWINDICES(J))
         ENDIF
      ENDDO


C**** COPY Y-DATA TO TEMPORARY ARRAY **********************************
      DO J = 1, IDAT
         X1(J) = Y(J)
      ENDDO

C**** RE-ARANGE X-DATA: SORTING ***************************************
      DO J = 1, IDAT
         IF (BOPTIONS(1)) THEN
          Y(IDAT + 1 - J) = X1(NEWINDICES(J))
         ELSE
          Y(J) = X1(NEWINDICES(J))
         ENDIF
      ENDDO


C***  JOIN X-ENTRYS WITH SAME VALUE ***********************************
      IF (BOPTIONS(2)) THEN
C***  COPY TO TEMPORARY ARRAYS ****************************************
      DO J = 1 , IDAT
        X1(J) = X(J)
       Y1(J) = Y(J)
      ENDDO

      INEW = 1
      RTEMP = X(1)
      
      DO J = 2 , IDAT
       IF ( X1(J) .EQ. RTEMP ) THEN
        NCOUNTER = NCOUNTER + 1
        Y(INEW) = (NCOUNTER - 1) * Y(INEW) / NCOUNTER
     >             + Y1(J) / NCOUNTER 
       ELSE
        NCOUNTER = 1
        INEW = INEW + 1
        X(INEW) = X1(J)
        Y(INEW) = Y1(J)
       ENDIF
       RTEMP = X1(J)
      ENDDO
      IDAT = INEW

      ENDIF

      END

expanddat.f/    1553528659  5006  320   100644  6401      `
      SUBROUTINE EXPANDDAT (LINE, X, Y, X1, Y1, NDAT, NDATMAX, MPACTIVE)

C**********************************************************************
C***  EXECUTE "COMMAND EXPAND"
C***  CALLED FROM EXCMD
C**********************************************************************

      DIMENSION X (NDATMAX), Y (NDATMAX)
      DIMENSION X1(NDATMAX), Y1(NDATMAX)
      CHARACTER*132 LINE
      CHARACTER ACTPAR*20
      LOGICAL BEX6O, MPACTIVE

      IF (NDAT .LT. 2) RETURN

C***  Test for monotonic sequence 
      V = X(NDAT) - X(1)
        DO L=2, NDAT
           IF( V*(X(L)-X(L-1)) .LT. 0 ) THEN
             WRITE(0,'(//,A)')'*** DATASET NOT IN MONOTONIC SEQUENCE'
             WRITE(0,*) X(L-2), X(L-1), X(L)
             GOTO 97
           ENDIF
        ENDDO

          BEX6O = .FALSE.
          CALL SARGV (LINE, 2, ACTPAR)
          IF (IDX(ACTPAR) .GT. 6) THEN
             IF (ACTPAR(7:13) .EQ. '-SPLINE') THEN
	        BEX6O = .TRUE.
             ELSE
                WRITE (*,'(//,2A)') '*** FATAL ERROR: ',
     >                   'only EXPAND or EXPAND-SPLINE are defined'
	        GOTO 97
             ENDIF
          ENDIF
          CALL SARGV (LINE, 3, ACTPAR)
          READ (ACTPAR, '(BN,I10)', ERR=99) NEXPA
          CALL SARGC (LINE, N)
          IF (N .GT. 3) THEN
              CALL SARGV (LINE, 4, ACTPAR)
              READ (ACTPAR, '(BN,F20.0)',ERR=99) XLEX1
              CALL SARGV (LINE, 5, ACTPAR)
              READ (ACTPAR, '(BN,F20.0)',ERR=99) XLEX2
              IF (XLEX1 .EQ. XLEX2) THEN
                WRITE(0,'(//,A)') '*** EXPAND: IDENTICAL BOUNDARIES'
                GOTO 97
              ENDIF              
          ELSE
            XLEX1 = X(1)
            XLEX2 = X(NDAT)
          ENDIF
          IF ((NDAT + MAX(2,NEXPA)) .GT. NDATMAX) THEN 
           WRITE (0,*) 'No datapoints left for COMMAND EXPAND'
           WRITE (0,'(A,I6,1X,I6)') 'NDAT = NDATMAX : ', NDAT,
     >            NDATMAX 
           STOP 'ERROR in Subr. EXCMD'
          ENDIF 

C***  Copy DATA to help Dataset X1, Y1  
          DO L=1, NDAT
            X1(L) = X(L)
            Y1(L) = Y(L)
          ENDDO
          NDAT1 = NDAT

          ICOUNT = 0
          NDATS = NDAT1

C***      Initialize Indices of Boundaries
          LXLEX1 = 1
          LXLEX2 = NDAT

C***  Insert the EXPAND boundaries XLEX1 and XLEX2, if given
          IF (XLEX1 .NE. X(1) .OR. XLEX2 .NE. X(NDAT)) THEN

C***       Force monotonic order of boundaries and X-range
           IF ( (X1(1)-X1(NDAT1))  
     >           *(XLEX1 - XLEX2) .LT. 0) THEN
             XTEMP = XLEX1
             XLEX1 = XLEX2
             XLEX2 = XTEMP
           ENDIF

C***       Test if XLEX1 is within the X-RANGE           
           DXL1 = X1(1)   - XLEX1
           DXR1 = X1(NDAT1) - XLEX1
           IF ( DXL1 * DXR1 .GT. 0.) THEN
              XLEX1 = X1(1)
              GOTO 3  
           ENDIF
C***       INSERT XLEX1
           DO L=1, NDAT1-1
            DL1 = X1(L) - XLEX1
            DR1 = X1(L+1) - XLEX1            
            IF ( (DL1 * DR1) .LT. 0.) THEN
             LXLEX1 = L+1 
             EXIT
            ELSEIF ((DL1 * DR1) .EQ. 0.) THEN
             LXLEX1 = L
             GOTO 3
            ENDIF   
           ENDDO 
C***       HOCHSCHIEBEN DER ELEMENTE AB LXLEX1 
           DO L=NDAT1,LXLEX1,-1
              Y1(L+1)=Y1(L)
              X1(L+1)=X1(L)
           ENDDO               
           X1(LXLEX1) = XLEX1
           IF (BEX6O) THEN
              CALL FSPLINE( Y1(LXLEX1), X1(LXLEX1), 
     >          Y, X, NDAT)
           ELSE
              P = (XLEX1 - X1(LXLEX1-1)) / 
     >            (X1(LXLEX1+1) - X1(LXLEX1-1))
              Q = 1. - P 
              Y1(LXLEX1)= Q*Y1(LXLEX1-1) 
     >                           + P*Y1(LXLEX1+1)
           ENDIF
           NDAT1 = NDAT1+1

C***       Test if LXLEX2 is in the X-RANGE
 3         DXL2 = X1(1)   - XLEX2
           DXR2 = X1(NDAT1) - XLEX2
           IF ( DXL2 * DXR2 .GT. 0.) THEN
              XLEX2 = X1(NDAT1)
             LXLEX2 = NDAT1
              GOTO 2
           ENDIF
C***       INSERT XLEX2
           DO L=1, NDAT1-1
            DL2 = X1(L) - XLEX2
            DR2 = X1(L+1) - XLEX2
            IF ((DL2 * DR2) .LT. 0.) THEN
             LXLEX2 = L+1
             IF (LXLEX2 .LT. LXLEX1) LXLEX1 = LXLEX1 + 1 
             EXIT
            ELSEIF ((DL2 * DR2) .EQ. 0.) THEN
             LXLEX2 = L+1
             GOTO 2
            ENDIF   
           ENDDO 
C*** HOCHSCHIEBEN DER ELEMENTE AB LXLEX2 
           DO L=NDAT1,LXLEX2,-1
              Y1(L+1)=Y1(L)
              X1(L+1)=X1(L)
           ENDDO               
           X1(LXLEX2)=XLEX2 
           IF (BEX6O) THEN
              CALL FSPLINE( Y1(LXLEX2), X1(LXLEX2), 
     >          Y, X, NDAT)
            ELSE
              P = (XLEX2 - X1(LXLEX2-1)) / 
     >            (X1(LXLEX2+1) - X1(LXLEX2-1))
              Q = 1. - P 
              Y1(LXLEX2)= Q*Y1(LXLEX2-1) 
     >                           + P*Y1(LXLEX2+1)
            ENDIF
            NDAT1 = NDAT1 + 1
             
          ENDIF

C***  LOOP **************************************
 2        IF (NDAT1 .LT. NDATS+NEXPA) THEN
            ICOUNT = ICOUNT + 1

C***  FIND LARGEST DISTANCE (L1,L1+1) 
            D1=0.
            DO L=LXLEX1,LXLEX2-1, 1
             D2=ABS(X1(L)-X1(L+1))
             IF (D2 .LT. D1) CYCLE
             L1=L
             D1=D2
            ENDDO

C*** HOCHSCHIEBEN DER ELEMENTE AB L1+1 
            DO L=NDAT1,L1+1,-1
              Y1(L+1)=Y1(L)
              X1(L+1)=X1(L)
            ENDDO

C*** INTERPOLIEREN 
            X1(L1+1) = 0.5*(X1(L1)+X1(L1+2))
            IF (BEX6O) THEN
              CALL FSPLINE(Y1(L1+1), X1(L1+1), 
     >          Y, X, NDAT)
            ELSE
              Y1(L1+1)=0.5*(Y1(L1)+Y1(L1+2))
            ENDIF
            NDAT1 = NDAT1 + 1
            LXLEX2 = LXLEX2 + 1
          GOTO 2
          ENDIF
C***  END-OF-LOOP ***************************

C***  Copy DATA back
          DO K=1, NDAT1
            X(K) = X1(K)
            Y(K) = Y1(K)
          ENDDO
          NDAT = NDAT1

          IF (.NOT. MPACTIVE)
     >     WRITE (*,'(A, I5, $)') ' EXPAND=', ICOUNT


      RETURN


   99 WRITE(6,'(//,A)') 'ERROR: INVALID FORMAT IN COMMAND LINE - '
      GOTO 97

 
   97 WRITE(6,*) 'The error occured in the following line: '
      WRITE(6,*) LINE
      STOP '*** ERROR in Subr. EXPANDDAT'

      END

insertpoint.f/  1553528659  5006  320   100644  1674      `
      SUBROUTINE INSERTPOINT(X,Y,NDATMAX,IDAT,XINS,LINS) 
C**********************************************************************
C***  INSERTING A SINGLE POINT INTO A DATASET:
C***  XINS is inserted into vector X
C***    LINS returns the new index of the inserted point
C***    Y(LINS) is linearly interpolated in the vextor Y
C***  If an identical X point already exists:
C***    - No action taken 
C***    - LINS gives the index of the identical X point 
C***  If XINS lies outside the inverval covered by X:
C***    ERROR stop executed!
C***  It is assumed that X is monotonic. 
C***  CALLED FROM: EXCMD, HLYMANA
C**********************************************************************
      DIMENSION X(NDATMAX), Y(NDATMAX)

      LINS = -1
C***  FIND L WITH XINS IN INTERVALL (L1,L1+1) 
      DO L=1,IDAT-1
         DR1 = (X(L) - XINS)
         DR2 = (X(L+1) - XINS)
         XM  = DR1 * DR2
         IF (XM .EQ. 0.) THEN
C***  POINT IS ALREADY IN THE DATASET
            IF (DR1 .EQ. 0.) THEN
               LINS = L
            ELSE
               LINS = L+1
            ENDIF
            RETURN
         ELSE IF (XM .LT. 0.) THEN
C***  HOCHSCHIEBEN DER ELEMENTE AB L1+1 
            DO LL=IDAT,L+1,-1
               Y(LL+1)=Y(LL)
               X(LL+1)=X(LL)
            ENDDO
            P = (XINS-X(L)) / (X(L+2)-X(L))
            Q = 1. - P
            X(L+1) = XINS
            Y(L+1)=Q*Y(L) + P*Y(L+2)
            LINS = L+1
            IDAT = IDAT + 1
            RETURN
         ENDIF
      ENDDO

C***  Error branch - should never be reached
      WRITE (*,*) 'ERROR Point ', XINS, ' has not been inserted'
      STOP 'ERROR IN SUBR. INSERTPOINT'

      END
voigth.f/       1553528659  5006  320   100644  1391      `
      FUNCTION VOIGTH(A,V)
C***********************************************************************
C***  normalized (!!!) VOIGT function H(a,v)
C***  ----- nach DETLEF KOESTER -----
C***********************************************************************
      DATA WPI /1.77245385/

      V=ABS(V)
      VV=V*V
      IF ((A.LT.0.2) .AND. (V.GT.5.0)) GO TO 70
      IF ((A.GE.0.2) .AND. (A.GT.1.4 .OR. (A+V).GT.3.2)) GO TO 80
      H0=EXP(-VV)
      H2=(1.-2.*VV)*H0
      IF (V.GT.2.4) GO TO 30
      IF (V.LE.1.3) GO TO 20
      H1=(-.220416*VV+1.989196*V-6.61487)*VV+9.39456*V-4.4848
      GO TO 40
   20 H1=(.42139*VV-2.34358*V+3.28868)*VV-.15517*V-1.1247
      GO TO 40
   30 H1=((-.0032783*VV+.0429913*V-.188326)*VV+.278712*V+.55415)/
     *   (VV-1.5)
   40 CONTINUE
      IF (A.GE..2) GO TO 60
   50 H=((H2*A+H1)*A+H0)
      VOIGTH=H/WPI
      RETURN

   60 HH1=H1+H0*1.12838
      HH2=H2+HH1*1.12838-H0
      HH3=(1.-H2)*0.37613-HH1*0.66667*VV+HH2*1.12838
      HH4=(3.*HH3-HH1)*0.37613+H0*0.66667*VV*VV
      H=((((HH4*A+HH3)*A+HH2)*A+HH1)*A+H0)*
     *  (((-.122727278*A+.532770573)*A-.96284325)*A+.979895032)
      VOIGTH=H/WPI
      RETURN

   70 H=((2.12/VV+.8463)/VV+.5642)*A/VV
      VOIGTH=H/WPI
      RETURN

   80 AA=A*A
      U=(AA+VV)*1.4142
      UU=U*U
      H=((((AA-10.*VV)*AA*3.+15.*VV*VV)/UU+3.*VV-AA)/UU+1.)*A*.79788/U
      VOIGTH=H/WPI
      RETURN

      END

x_minval.f/     1553528659  5006  320   100644  341       `
      FUNCTION X_MINVAL (X, N)
C***  Returns the minimum value in vector X
      DIMENSION X(N)
      IF (N .LE. 0) THEN
         WRITE (*,*) 'VECTOR HAS ZERO LENGTH'
	 STOP '*** ERROR in function X_MINVAL'
      ENDIF

      XX = X(1)
      DO I=1, N
         XX = AMIN1 (X(I),XX)
      ENDDO

      X_MINVAL = XX
      RETURN
      END
  

x_maxval.f/     1553528659  5006  320   100644  338       `
      FUNCTION X_MAXVAL (X, N)
C***  Returns the maximum value in vector X
      DIMENSION X(N)
      IF (N .LE. 0) THEN
         WRITE (*,*) 'VECTOR HAS ZERO LENGTH'
	 STOP '*** ERROR in function X_MINVAL'
      ENDIF

      XX = X(1)
      DO I=1, N
         XX = AMAX1 (X(I),XX)
      ENDDO

      X_MAXVAL = XX
      RETURN
      END
ismline.f/      1553528659  5006  320   100644  7773      `
      SUBROUTINE ISMLINE (X, Y, NDAT, NSET, NDATMAX, NSETMAX, ISYMBOL, 
     >                    NPEN, ICOLOR, COMMAND, ISETOP, LINE)

C**********************************************************************
C***  CORRECTING UV SPECTRA (e.g. IUE) FOR THE EXTINCTION BY        ***
C***                 interstellar lines                             ***
C***  - CALLED FROM: WRPLOT ( <-- COMMAND = .FALSE. ) de-activated! ***
C***        OR FROM:  EXCMD ( <-- COMMAND = .TRUE. )                ***
C***                                                                ***
C***  DATA:  X = LAMBDA[ANGSTROEM]                                  ***
C***         Y = FLUX                                               ***
C**********************************************************************

      DIMENSION X(NDATMAX,NSETMAX), Y(NDATMAX,NSETMAX)
      DIMENSION NDAT(NSETMAX), ISYMBOL(NSETMAX), NPEN(NSETMAX)
      DIMENSION ICOLOR(NSETMAX)

      CHARACTER LINE*(*), ACTPAR*20, ACTPAR2*20
      CHARACTER CHAR*1
      LOGICAL COMMAND

      DATA CLIGHT /299792.458/

C***  Constants for Voigt profile in cgs units
      DATA  XKBOLTZ /1.38065000E-16/
      DATA  CLCM    /2.99792458E+10/
      DATA  ECHAR   /4.80325000E-10/
      DATA  XME     /9.10938190E-28/
      DATA  XMP     /1.67262160E-24/

      PI    = 4.0 * ATAN(1.0)
      QPI   = 1.0 / PI
      QC    = 1.0 / CLCM
      TEMP  = -273.15
      VTURB = 0.
      VRAD = 0. 
      FVALUE = 0.
      ATMASS = 0.
      XLAM = 0.
      GAMM = 0.
      ENH = 0.

      FRBB = PI * ECHAR * ECHAR / XME / CLCM

C***  Decoding of the COMMAND line

      CALL SARGC (LINE, NPAR)

      IF (NPAR .LT. 5) THEN
         WRITE (*,'(//,A)') 
     >       '*** ERROR: COMMAND ISM needs at least 5 parameters'
         GOTO 97
      ELSE

   30    CONTINUE 

         DO IPAR=3, NPAR, 2
            CALL SARGV (LINE, IPAR, ACTPAR)
            IF (IPAR .EQ. NPAR) THEN
               WRITE (*,'(//,2A)') 
     >            '*** ERROR: Value missing for ', ACTPAR
               GOTO 97
            ENDIF
            CALL SARGV (LINE, IPAR+1, ACTPAR2)
C           For Compatiblity to SUBR. HLYMANA : COLDENS must be negative!
            IF (ACTPAR .EQ. 'COLDENS') THEN
               READ (ACTPAR2, '(BN,F20.0)',ERR=99) ENH
            ELSE IF (ACTPAR .EQ. 'VRAD') THEN
                READ (ACTPAR2, '(BN,F20.0)',ERR=99) VRAD
C           For Voigt profile: Temperature in K, V_TURBULENCE in km/s
            ELSE IF (ACTPAR .EQ. 'T') THEN
                READ (ACTPAR2, '(BN,F20.0)',ERR=99) TEMP
            ELSE IF (ACTPAR .EQ. 'VTURB') THEN
                READ (ACTPAR2, '(BN,F20.0)',ERR=99) VTURB
C           Atomic data: wavelength, atomic mass, f-value, gamma (lifetime)
            ELSE IF (ACTPAR .EQ. 'L0') THEN
                READ (ACTPAR2, '(BN,F20.0)',ERR=99) XLAM
            ELSE IF (ACTPAR .EQ. 'A') THEN
                READ (ACTPAR2, '(BN,F20.0)',ERR=99) ATMASS
            ELSE IF (ACTPAR .EQ. 'F') THEN
                READ (ACTPAR2, '(BN,F20.0)',ERR=99) FVALUE
            ELSE IF (ACTPAR .EQ. 'GAMM') THEN
                READ (ACTPAR2, '(BN,F20.0)',ERR=99) GAMM
            ELSE IF (ACTPAR .EQ. 'DATASET') THEN
                CYCLE
            ELSE
	       WRITE (*,'(//,2A)') 
     >              '*** ERROR: Invalid Keyword: ', ACTPAR
               GOTO 97
            ENDIF
         ENDDO 
      ENDIF
   34 CONTINUE

C     Apply radial velocity shift
      XLAM = XLAM * (1. + VRAD / CLIGHT)
C     Convert turbulence velocity from km/s to cm/s
      VTURB = VTURB * 1.E5
      
C     Check for consistency of given values
      IF ( FVALUE .LE. 0. ) THEN
       WRITE (*,*) 
     >  "ISMLINE : Oscillator strenght F is missing or wrong."
       STOP
      ENDIF   
      IF ( GAMM .LE. 0. ) THEN
       WRITE (*,*) "ISMLINE : Lifetime GAMM is missing or wrong."
       STOP
      ENDIF   
      IF ( XLAM .LE. 0. ) THEN
       WRITE (*,*) "ISMLINE : Wavelength L0 is missing or wrong."
       STOP
      ENDIF   
      IF ( ATMASS .LE. 0. .AND. TEMP .GT. 0.) THEN
       WRITE (*,*) 
     >  "ISMLINE : Atomic mass A for option T is missing or wrong."
       STOP
      ENDIF
      IF ( ENH .EQ. 0. ) THEN
       WRITE (*,*) 
     > "ISM : Column density COLDENS is missing or zero."
       STOP
      ENDIF

C     Coefficients for pure Lortenz profile
      IF ( TEMP .LE. 0. .AND. VTURB .LE. 0.) THEN
        C0 = 4 * PI * ECHAR * ECHAR / ( XME * CLCM * GAMM ) * FVALUE
        C1 = (4 * PI * CLCM / (XLAM * 1.E-8 * XLAM * 1.E-8 * GAMM))**2
      ENDIF

      IF (COMMAND) THEN
         I1 = ISETOP
         I2 = ISETOP
      ENDIF

C**********************************************************************
C***                EXPAND DATA TO INSERT ISM LINE                  ***
C**********************************************************************

      IDAT=NDAT(I1)

ccc      XLAMMIN = MINVAL(X(1:IDAT,I1))
      XLAMMIN = X_MINVAL(X(1,I1), IDAT)
ccc      XLAMMAX = MAXVAL(X(1:IDAT,I1)) 
      XLAMMAX = X_MAXVAL(X(1,I1),IDAT) 

         DLAMBDA = 0.0001 
         DO J=-500,500,1
          XINS = XLAM + SIGN(1,J) * J * J * DLAMBDA
          XDL1 = XLAMMIN - XINS
          XDR1 = XLAMMAX - XINS
          IF (XDL1 * XDR1 .GT. 0. ) CYCLE 
          IF (IDAT .GE. NDATMAX) THEN
           WRITE (0,*) " "
           WRITE(0,'(A,$)')
     >      "ISMLINE : CANNOT INSERT MORE POINTS TO COVER"
           WRITE (0,*) " LINE PROFILE, AT ", XLAM
           STOP
          ENDIF 
          CALL INSERTPOINT (X(1,I1), Y(1,I1), NDATMAX,
     >                      IDAT, XINS, LINS)
         ENDDO


      WRITE (0,'(A,I6,A)') "ISMLINE: DATASET EXPANDED TO ",IDAT,
     >                     " DATA POINTS " 


C***********************************************************************
C***  MULTIPLICATION WITH ABSORPTION PROFILE
C***********************************************************************

C***  MULTIPLY WITH CROSS SECTION

      NDAT(I1)    = IDAT
      ISYMBOL(I2) = ISYMBOL(I1)
      NPEN(I2)    = NPEN(I1)
      ICOLOR(I2)  = ICOLOR(I1)
      NDAT(I2)    = NDAT(I1)

      DO 16 I=1, NDAT(I2)
         X(I,I2) = X(I,I1)
         TAU = 0.

         IF ( TEMP .GT. 0. .OR. VTURB .GT. 0.) THEN        
C***     Temperature or v_turb given => Voigt profile
C          Doppler width Delta lambda in cm             
           IF ( ATMASS .GT. 0. .AND. TEMP .GT. 0. ) THEN
            DNDOPP  = XLAM * 1.E-8 * QC * 
     >               SQRT(2. * XKBOLTZ * TEMP / (XMP * ATMASS)
     >               + VTURB * VTURB )
           ELSE 
            DNDOPP  = XLAM * 1.E-8 * QC * VTURB 
           ENDIF
           QDNDOPP = 1. / DNDOPP
C          Constant "A" for normalized Voigt function
           A   = 0.25 * GAMM * QPI * QDNDOPP 
     >         * XLAM * 1.E-8 * XLAM * 1.E-8 * QC
           DLAM = X(I,I1) - XLAM
C          Variable "V" for normalized Voigt function
           V = ABS( DLAM ) * 1.E-8 * QDNDOPP
           HH = VOIGTH (A,V)
C          Factor in cm
           FAK = FRBB   * FVALUE * QDNDOPP 
     >           * XLAM * 1.E-8 * XLAM * 1.E-8 * QC
C          Sign is plus as COLDENS is negative
           TAU = TAU + FAK * HH * ENH 

         ELSE 
C***     No or neg. Temperature/V_Turb given -> Lorentz profile 
           DLAM = ( X(I,I1) - XLAM ) * 1.E-8
           TAU  = TAU + C0 * ENH / (1. + C1 * DLAM * DLAM)
         ENDIF

         IF (TAU .LT. 10.) THEN
           Y(I,I2) = Y(I,I1) * EXP(TAU)
         ELSE
           Y(I,I2) = 0.
         ENDIF

16    CONTINUE
      IF (COMMAND) RETURN

C***  Errors ****************************************************

   99 WRITE(6,'(//,A)') '*** ERROR when decoding REAL number'
      GOTO 97

   97 WRITE(6,*) 'The error occured in the following line: '
      WRITE(6,*) LINE
      STOP '*** ERROR in Subr. ISM'

      END

cflinreg.f/     1553528659  5006  320   100644  8007      `
      SUBROUTINE CFLINREG (LINE, ACTPAR, VAR, MAXVAR, NVAR, X, Y, 
     >               ND, NDATMAX, ISYM,
     >               BLINREGYERR, YERR1, YERR2, YERRTYPE, NDATYERR, 
     >               NPAR)

C**********************************************************************
C***  EXECUTE "COMMAND CF-LINREG" which return values into variables
C***  CALLED FROM EXCF
C***  If YERROR is given, the formulas from Numerical Recipes (3rd Ed.)
C***  Sect. 15.2 (p. 780 ff.) are used
C***  If no YERROR is given, a standard linear regression formula is
C***  used, the formal error is computed from chi^2, as in Num. Rec.
C**********************************************************************

      DIMENSION X(NDATMAX), Y(NDATMAX), XEP(2), YEP(2)
      DIMENSION YERR1(NDATMAX), YERR2(NDATMAX)
      CHARACTER*(*) LINE, ACTPAR, YERRTYPE
      CHARACTER*20 ACTPAR1, ACTPAR2
      CHARACTER*(*) VAR(MAXVAR,2)
      LOGICAL   BLINREGYERR

C***  CF-LINREG  *************************************************
C***  Linear Regression following NR with error

C      Endpoints will given at min, max Xvalues
ccc       XEP(1) = MINVAL(X(1:ND))
ccc       XEP(2) = MAXVAL(X(1:ND))
       XEP(1) = X(1)
       XEP(2) = X(1)
       DO II=2, ND
          IF (X(II) .LT. XEP(1)) XEP(1) = X(II)
          IF (X(II) .GT. XEP(2)) XEP(2) = X(II)
       ENDDO

C      Calculate the neccessary statistical quantities -----------------
C      with given YERROR dataset 
       IF (BLINREGYERR) THEN 

        STOT = 0. ! initialize statistical quantities
        SX   = 0.
        SY   = 0. 
        SXX  = 0.
        SXY  = 0.

        IF ((NDATYERR .GT. 1) .AND. (NDATYERR .NE. ND)) THEN
         WRITE (*,'(//,A,A)') "*** ERROR STOP LINREG: NUMBER OF GIVEN", 
     >    " SIGMA_Y .GT. 1 BUT .LT. ND"
         STOP
        ENDIF
        IF (NDATYERR .EQ. 1 .AND. YERRTYPE .EQ. 'MINMAX') THEN
          WRITE (*,'(//,A,A)') "*** ERROR STOP LINREG: YERROR IS",
     >     " MINMAX, BUT ONLY ONE MINMAX DATA PAIR GIVEN"
         STOP
        ENDIF
C       A: Uniform YERROR, same SIGMA_Y for all Y
        IF (NDATYERR .EQ. 1 .AND. YERRTYPE .EQ.'PLUSMINUS')  THEN
         SIGMAY = ( ABS(YERR1(1)) + ABS(YERR2(1)) ) / 2.
         SIGMAY2INV = 1. / ( SIGMAY * SIGMAY )  
         DO I=1, ND
          STOT   = STOT   + SIGMAY2INV
          SX  = SX  + X(I) * SIGMAY2INV 
          SY  = SY  + Y(I) * SIGMAY2INV 
          SXX = SXX + X(I) * X(I) * SIGMAY2INV 
          SXY = SXY + X(I) * Y(I) * SIGMAY2INV           
         ENDDO 
C       B: Every Y with its individual SIGMA_Y
        ELSEIF (NDATYERR .EQ. ND .AND. YERRTYPE .EQ. 'PLUSMINUS') THEN
         DO I=1, ND
          SIGMAY = ( ABS(YERR1(I)) + ABS(YERR2(I)) ) / 2.
          SIGMAY2INV = 1. / ( SIGMAY * SIGMAY )  
          STOT   = STOT   + SIGMAY2INV
          SX  = SX  + X(I) * SIGMAY2INV 
          SY  = SY  + Y(I) * SIGMAY2INV 
          SXX = SXX + X(I) * X(I) * SIGMAY2INV 
          SXY = SXY + X(I) * Y(I) * SIGMAY2INV           
         ENDDO
C       C: Every Y with its individual MINMAX values -> SIGMA_Y 
        ELSEIF (NDATYERR .EQ. ND .AND. YERRTYPE .EQ. 'MINMAX') THEN
         DO I=1, ND
          SIGMAY = (ABS(Y(I)-YERR1(I)) + ABS(YERR2(I)-Y(I))) / 2.
          SIGMAY2INV = 1. / ( SIGMAY * SIGMAY )  
          STOT   = STOT   + SIGMAY2INV
          SX  = SX  + X(I) * SIGMAY2INV 
          SY  = SY  + Y(I) * SIGMAY2INV 
          SXX = SXX + X(I) * X(I) * SIGMAY2INV 
          SXY = SXY + X(I) * Y(I) * SIGMAY2INV           
         ENDDO
        ELSE
         WRITE (*,'(//,A,A)') "*** ERROR STOPLINREG: SOMETHING IS", 
     >    " WRONG WITH YERROR"
         STOP
        ENDIF 
     
       DELTA    = STOT * SXX - SX * SX
       B_SLOPE  = (STOT * SXY - SX * SY) / DELTA
       A_OFFSET = (SXX * SY - SX * SXY) / DELTA 

       ELSE        
C      D: No SIGMA_Y given, only formal fit error
        X_MEAN = X(1)
        Y_MEAN = Y(1)
        VAR_XX = 0.
        VAR_YY = 0.
        VAR_XY = 0.
        STOT = 1. 
        SX   = X(1)
        SXX  = SX * SX
        DO I = 2, ND
C        recursive calculation of means and variances
         X_MEAN = X_MEAN - X_MEAN / (REAL(I)) + X(I) / (REAL(I)) 
         Y_MEAN = Y_MEAN - Y_MEAN / (REAL(I)) + Y(I) / (REAL(I)) 
         VAR_XX = VAR_XX - VAR_XX / (REAL(I)) + 
     >    1. / (REAL(I)-1.) * (X(I) - X_MEAN)*(X(I) - X_MEAN)
         VAR_YY = VAR_YY - VAR_YY / (REAL(I)) + 
     >    1. / (REAL(I)-1.) * (Y(I) - Y_MEAN)*(Y(I) - Y_MEAN) 
         VAR_XY = VAR_XY - VAR_XY / (REAL(I)) +
     >    1. / (REAL(I)-1.) * (X(I) - X_MEAN)*(Y(I) - Y_MEAN) 
C        needed for error estimate, not recursively:
         STOT = STOT + 1. 
         SX   = SX   + X(I)
         SXX  = SXX  + X(I) * X(I) 
        ENDDO

        B_SLOPE  = VAR_XY / VAR_XX
        A_OFFSET = Y_MEAN - B_SLOPE * X_MEAN
        DELTA = STOT * SXX - SX*SX

C       Chi-square calculation for formal fit error
        CHI2 = 0.
        DO I=1, ND
         CHI2 = CHI2 +(Y(I) - A_OFFSET - B_SLOPE * X(I))**2
        ENDDO

       ENDIF
C      End of Branching for YERROR -------------------------------------

       YEP(1) = B_SLOPE * XEP(1) + A_OFFSET
       YEP(2) = B_SLOPE * XEP(2) + A_OFFSET
       
       IF (ND .GE. 3) THEN
        IF (BLINREGYERR) THEN
         A_ERROR = SQRT(SXX / DELTA)
         B_ERROR = SQRT(STOT / DELTA)
        ELSE 
         A_ERROR = SQRT(SXX  / DELTA * CHI2/REAL(ND-2))
         B_ERROR = SQRT(STOT / DELTA * CHI2/REAL(ND-2))
        ENDIF 
       ELSE
        A_ERROR = 0.
        B_ERROR = 0.
       ENDIF
        
       WRITE (0,'(/,A,$)')
     > " Results from linear regression: y = a + b * x"
       IF (BLINREGYERR) THEN
        WRITE (*,'(A)') " (weighted by YERROR)"
       ELSE  
        WRITE (*,'(A)') " (only formal errors)"
       ENDIF
       WRITE (0,'(A,G15.7,A,G15.7)') "  a = ", A_OFFSET, 
     >        " +/- " , A_ERROR
       WRITE (0,'(A,G15.7,A,G15.7)') "  b = ", B_SLOPE, 
     >        " +/- " , B_ERROR

C***  If the end of the line reads "DATASET=...", omit the last 2 parameters
      CALL SARGV (LINE, NPAR-1, ACTPAR1)
      IF (ACTPAR1 .EQ. 'DATASET') NPAR = NPAR - 2
      
      IF (NPAR .LT. 3) GOTO 95
C     1st variable: minimum point x       
      CALL SARGV (LINE, 3, ACTPAR1)
      WRITE (ACTPAR2, '(G15.7)') XEP(1)
      CALL FLUSHLEFT (ACTPAR2)
      CALL PUTVAR (ACTPAR1, ACTPAR2, VAR, MAXVAR, NVAR)

      IF (NPAR .LT. 4) GOTO 95
c     2nd variable: minimum point y
      CALL SARGV (LINE, 4, ACTPAR1)
      WRITE (ACTPAR2, '(G15.7)') YEP(1)
      CALL FLUSHLEFT (ACTPAR2)
      CALL PUTVAR (ACTPAR1, ACTPAR2, VAR, MAXVAR, NVAR)

      IF (NPAR .LT. 5) GOTO 95
C     3rd variable: maximum point x       
      CALL SARGV (LINE, 5, ACTPAR1)
      WRITE (ACTPAR2, '(G15.7)') XEP(2)
      CALL FLUSHLEFT (ACTPAR2)
      CALL PUTVAR (ACTPAR1, ACTPAR2, VAR, MAXVAR, NVAR)

      IF (NPAR .LT. 6) GOTO 95
c     4th variable: maximum point y
      CALL SARGV (LINE, 6, ACTPAR1)
      WRITE (ACTPAR2, '(G15.7)') YEP(2)
      CALL FLUSHLEFT (ACTPAR2)
      CALL PUTVAR (ACTPAR1, ACTPAR2, VAR, MAXVAR, NVAR)

      IF (NPAR .LT. 7) GOTO 95
C     5th variable: A_OFFSET       
      CALL SARGV (LINE, 7, ACTPAR1)
      WRITE (ACTPAR2, '(G15.7)') A_OFFSET
      CALL FLUSHLEFT (ACTPAR2)
      CALL PUTVAR (ACTPAR1, ACTPAR2, VAR, MAXVAR, NVAR)

      IF (NPAR .LT. 8) GOTO 95
c     6th variable: B_SLOPE
      CALL SARGV (LINE, 8, ACTPAR1)
      WRITE (ACTPAR2, '(G15.7)') B_SLOPE
      CALL FLUSHLEFT (ACTPAR2)
      CALL PUTVAR (ACTPAR1, ACTPAR2, VAR, MAXVAR, NVAR)

      IF (NPAR .LT. 9) GOTO 95
C     7th variable: A_ERROR       
      CALL SARGV (LINE, 9, ACTPAR1)
      WRITE (ACTPAR2, '(G15.7)') A_ERROR
      CALL FLUSHLEFT (ACTPAR2)
      CALL PUTVAR (ACTPAR1, ACTPAR2, VAR, MAXVAR, NVAR)

      IF (NPAR .LT. 10) GOTO 95
c     8th variable: B_ERROR
      CALL SARGV (LINE, 10, ACTPAR1)
      WRITE (ACTPAR2, '(G15.7)') B_ERROR
      CALL FLUSHLEFT (ACTPAR2)
      CALL PUTVAR (ACTPAR1, ACTPAR2, VAR, MAXVAR, NVAR)

   95 RETURN

      END

bigcross.f/     1553528659  5006  320   100644  958       `
      SUBROUTINE BIGCROSS (X, Y, SSIZE)
C**********************************************************************
C***  PLOTTING OF A FILLABLE CROSS (SWISS CROSS)
C**********************************************************************
      CALL GCPLOT (X-0.1111*SSIZE, Y-0.1111*SSIZE, 3)
      CALL GCPLOT (X-0.3333*SSIZE, Y-0.1111*SSIZE, 2)
      CALL GCPLOT (X-0.3333*SSIZE, Y+0.1111*SSIZE, 2)
      CALL GCPLOT (X-0.1111*SSIZE, Y+0.1111*SSIZE, 2)
      CALL GCPLOT (X-0.1111*SSIZE, Y+0.3333*SSIZE, 2)
      CALL GCPLOT (X+0.1111*SSIZE, Y+0.3333*SSIZE, 2)
      CALL GCPLOT (X+0.1111*SSIZE, Y+0.1111*SSIZE, 2)
      CALL GCPLOT (X+0.3333*SSIZE, Y+0.1111*SSIZE, 2)
      CALL GCPLOT (X+0.3333*SSIZE, Y-0.1111*SSIZE, 2)
      CALL GCPLOT (X+0.1111*SSIZE, Y-0.1111*SSIZE, 2)
      CALL GCPLOT (X+0.1111*SSIZE, Y-0.3333*SSIZE, 2)
      CALL GCPLOT (X-0.1111*SSIZE, Y-0.3333*SSIZE, 2)
      CALL GCPLOT (X-0.1111*SSIZE, Y-0.1111*SSIZE, 2)
      RETURN
      END
bigcrossrot.f/  1553528659  5006  320   100644  955       `
      SUBROUTINE BIGCROSSROT (X, Y, SSIZE)
C**********************************************************************
C***  PLOTTING OF A ROTATED FILLABLE CROSS
C**********************************************************************
      CALL GCPLOT (X-0.1667*SSIZE, Y-0.0   *SSIZE, 3)
      CALL GCPLOT (X-0.3333*SSIZE, Y+0.1667*SSIZE, 2)
      CALL GCPLOT (X-0.1667*SSIZE, Y+0.3333*SSIZE, 2)
      CALL GCPLOT (X-0.0   *SSIZE, Y+0.1667*SSIZE, 2)
      CALL GCPLOT (X+0.1667*SSIZE, Y+0.3333*SSIZE, 2)
      CALL GCPLOT (X+0.3333*SSIZE, Y+0.1667*SSIZE, 2)
      CALL GCPLOT (X+0.1667*SSIZE, Y+0.0   *SSIZE, 2)
      CALL GCPLOT (X+0.3333*SSIZE, Y-0.1667*SSIZE, 2)
      CALL GCPLOT (X+0.1667*SSIZE, Y-0.3333*SSIZE, 2)
      CALL GCPLOT (X+0.0   *SSIZE, Y-0.1667*SSIZE, 2)
      CALL GCPLOT (X-0.1667*SSIZE, Y-0.3333*SSIZE, 2)
      CALL GCPLOT (X-0.3333*SSIZE, Y-0.1667*SSIZE, 2)
      CALL GCPLOT (X-0.1667*SSIZE, Y-0.0   *SSIZE, 2)
      RETURN
      END

pentastar.f/    1553528659  5006  320   100644  868       `
      SUBROUTINE PENTASTAR (X, Y, SSIZE)
C**********************************************************************
C***  PLOTTING OF A N-STAR (n=5) (CLIPPED) 
C**********************************************************************
      CALL GCPLOT (X+0.00000*SSIZE, Y+0.62922*SSIZE, 3)
      CALL GCPLOT (X+0.14127*SSIZE, Y+0.19444*SSIZE, 2)
      CALL GCPLOT (X+0.59842*SSIZE, Y+0.19444*SSIZE, 2)
      CALL GCPLOT (X+0.22858*SSIZE, Y-0.07427*SSIZE, 2)
      CALL GCPLOT (X+0.36985*SSIZE, Y-0.50905*SSIZE, 2)
      CALL GCPLOT (X-0.00000*SSIZE, Y-0.24034*SSIZE, 2)
      CALL GCPLOT (X-0.36985*SSIZE, Y-0.50905*SSIZE, 2)
      CALL GCPLOT (X-0.22858*SSIZE, Y-0.07427*SSIZE, 2)
      CALL GCPLOT (X-0.59842*SSIZE, Y+0.19444*SSIZE, 2)
      CALL GCPLOT (X-0.14127*SSIZE, Y+0.19444*SSIZE, 2)
      CALL GCPLOT (X+0.00000*SSIZE, Y+0.62922*SSIZE, 2)
      RETURN
      END
isoex_old.f/    1553528659  5006  320   100644  9782      `
      SUBROUTINE ISOEX_OLD

      PARAMETER (NDIM = 1000)

      DIMENSION T(NDIM), RT(NDIM), WERT(NDIM)
      LOGICAL   BINS(NDIM), BTEMP
      CHARACTER*255 FNNAMEN,FNFORMAL, FNOUT, FNMODA, FNANF
      CHARACTER LINE*132, ACTPAR*60
      CHARACTER SPLINE*132, KEYWRD*132
      LOGICAL REDIS

C***  EINLESEN DES FILE-NAMENS IN DEM DIE FORMAL-NAMEN GESPEICHERT SIND
      WRITE (*,*) 'NAME DES NAMEN-FILES = '
         WRITE (6,'(A)') 'Default-Name : namen.tool'
         WRITE (6,'(A)') 'Present directory is:'
         CALL SYSTEM ('pwd')
         READ (*, '(A)', END=100) FNNAMEN
         IF (IDX(FNNAMEN) .EQ. 0) THEN
           FNNAMEN = 'namen.tool'
         ENDIF
C         FNAME = FNAME(:IDX(FNAME))
C         IF (FNAME .EQ. '.' .OR. FNAME .EQ. './' .OR.
C     >       FNAME .EQ. '..' .OR. FNAME .EQ. '../' ) GOTO 97
      OPEN (UNIT=1,FILE=FNNAMEN, STATUS='OLD',ERR=99)
      OPEN (UNIT=14, FILE='isoex.log', STATUS='UNKNOWN', ERR=54)
C***  EINLESEN DER KEYWORDS
C***    SPLINE  : SPEZIFIEZIERT DIE LINIE, DIE AUSGEWERTET WERDEN SOLL
C***    REDIS   : ELECTRON REDISTRIBUTION (REDIS = (TRUE, FALSE))
C***    FNANF   : GIBT DEN ANFEANG DER FORMAL-NAMEN AN, ZB. FORMAL_C_...
C***    KEYWORD : HINTER DER POSITION DES KEYWORDS WIRD DER WERT EINGELESEN
   85 READ(1, '(A)', END=2) LINE
      IF (LINE(1:2) .EQ. '##') GOTO 85
      CALL SARGV (LINE, 1, ACTPAR)
      IF (ACTPAR .EQ. '#SPLINE') THEN
        CALL SARGV (LINE, 2, ACTPAR)
        SPLINE = ACTPAR
      ELSE
        WRITE (*,*) 'LINE=', LINE( :IDX(LINE))
       STOP 'ERROR IN READING SPLINE'
      ENDIF
   86 READ(1, '(A)', END=2) LINE
      IF (LINE(1:2) .EQ. '##') GOTO 86
      CALL SARGV (LINE, 1, ACTPAR)
      IF (ACTPAR .EQ. '#REDIS') THEN
        CALL SARGV (LINE, 2, ACTPAR)
        IF (ACTPAR .EQ. 'TRUE') THEN
          REDIS = .TRUE.
        ELSE
          REDIS = .FALSE.
        ENDIF
      ELSE
        WRITE (*,*) 'LINE=', LINE( :IDX(LINE))
        STOP 'ERROR IN READING REDIS'
      ENDIF
   87 READ(1, '(A)', END=2) LINE
      IF (LINE(1:2) .EQ. '##') GOTO 87
      CALL SARGV (LINE, 1, ACTPAR)
      IF (ACTPAR .EQ. '#FNANF') THEN
        CALL SARGV (LINE, 2, ACTPAR)
        FNANF = ACTPAR
      ELSE
        STOP 'ERROR IN READING FNANF'
      ENDIF
      READ(1, '(A)', END=2) LINE
      CALL SARGV (LINE, 1, ACTPAR)
      IF (ACTPAR .EQ. '#KEYWRD') THEN
        CALL SARGV (LINE, 2, ACTPAR)
        KEYWRD = ACTPAR
      ELSE
        STOP 'ERROR IN READING KEYWRD'
      ENDIF
   88 READ(1, '(A)', END=2) LINE
      IF (LINE(1:2) .EQ. '##') GOTO 88
      CALL SARGV (LINE, 1, ACTPAR)
      IF (ACTPAR .EQ. '#NUMBER') THEN
        CALL SARGV (LINE, 2, ACTPAR)
        READ (ACTPAR, '(I1)') NUMBER
      ELSE
        WRITE (*,*) 'LINE=', LINE( :IDX(LINE))
        STOP 'ERROR IN READING NUMBER'
      ENDIF

      LINE = FNANF
      WRITE(*,'(3A)')   ' FILE-NAME      = ', LINE( :ISTRL(LINE)), '...'
      WRITE(*,'(A, L)') ' REDISTRIBUTION = ', REDIS
      WRITE(*,'(2A)')   ' LINE NUMBER    = ', SPLINE( :ISTRL(SPLINE))
      WRITE(*,'(2A)')   ' KEYWORD        = ', KEYWRD( :ISTRL(KEYWRD))
      WRITE(*,'(A, I1)')   ' NUMBER         = ', NUMBER

      NFORMAL = 0
      DO 53 I=1, 100
        BINS(I) = .FALSE.
53    CONTINUE

C***  EINLESEN DER INCLUDE GRIDPOINTS
55      READ (1, '(A)') LINE
        CALL SARGV (LINE, 1, ACTPAR)
        IF (ACTPAR .NE. '#INSERT') THEN
          BACKSPACE (1)
          GOTO 1
        ENDIF
        NFORMAL = NFORMAL + 1
        CALL SARGV (LINE, 2, ACTPAR)
        READ (ACTPAR, '(G15.4)') T(NFORMAL)
        CALL SARGV (LINE, 3, ACTPAR)
        READ (ACTPAR, '(G15.4)') RT(NFORMAL)
        BINS(NFORMAL) = .TRUE.
      GOTO 55

C***  EINLESEN DER FORMAL-NAMEN
1     READ(1, '(A)', END=2) LINE
      CALL SARGV (LINE, 1, ACTPAR)
      IF (ACTPAR .EQ. '#NAME') THEN
        CALL SARGV (LINE, 2, ACTPAR)
        FNFORMAL = FNANF( :ISTRL(FNANF( :132)))//ACTPAR( :IDX(ACTPAR))
     >             //'.out'
        FNMODA = '/home/usr1/lars/moddata/moddata_'//
     >            ACTPAR( :IDX(ACTPAR))//'.out'
        OPEN (UNIT=2, FILE=FNFORMAL, STATUS='OLD', ERR=50)
        OPEN (UNIT=4, FILE=FNFORMAL, STATUS='OLD', ERR=52)
        NFORMAL = NFORMAL + 1
        WRITE(14,'(2A)') 
     >    'FORMAL FILE  : ',FNFORMAL( :IDX(FNFORMAL))
        WRITE(14,'(2A)') 
     >    'MODDATA FILE : ',FNFORMAL( :IDX(FNFORMAL))
c        WRITE(*,*)

        GOTO 51
      ELSE
        GOTO 1
      ENDIF
   50 WRITE(*,*) 'FILE ',FNFORMAL,' laesst sich nicht oeffnen'
      WRITE(*,*) '==========================================='
      WRITE (*,*)
      GOTO 1
   52 WRITE(*,*) 'FILE ',FNMODA,' laesst sich nicht oeffnen'
      WRITE(*,*) '==========================================='
      WRITE (*,*)
      GOTO 1
   54 WRITE(*,*) 'Log file laesst sich nicht oeffnen'
      WRITE(*,*) '==========================================='
      WRITE (*,*)
      GOTO 1
   51 CONTINUE

C***  T, RT UND WERT AUF 0. SETZEN
      IF (.NOT. BINS(NFORMAL)) THEN
        T(NFORMAL) = 0.
        RT(NFORMAL) = 0.
        WERT(NFORMAL) = 0.
      ENDIF

C***  LESEN VON FNMODA
C***  SUCHEN NACH TEMPERATUR UND TRANFORMIERTEM RADIUS
    5   READ (4, '(A)', END=4) LINE
        CALL SARGV ( LINE, 1, ACTPAR)
        IF (ACTPAR .NE. 'T*') THEN
          GOTO 5
        ELSE
          CALL SARGV (LINE, 2, ACTPAR)
          READ (ACTPAR,'(F10.0)') T(NFORMAL)          
        ENDIF
        READ (4, '(A)', END=4) LINE
        CALL SARGV (LINE, 2, ACTPAR)
        READ (ACTPAR,'(F10.0)') RT(NFORMAL)
        BINS(NFORMAL) = .FALSE.

      IF (SPLINE .EQ. '*') GOTO 110
C***  SUCHEN NACH GEWUENSCHTER LINIE
        NUM = NUMBER
    9   READ (2, '(A)', END=4) LINE
        CALL SARGV (LINE, 1, ACTPAR)
        IF (ACTPAR( :5) .NE. '-----') GOTO 9
        READ (2, '(A)', END=4) LINE
        CALL SARGV (LINE, 1, ACTPAR)
        IF (ACTPAR .NE. 'LINE') GOTO 9
        CALL SARGV (LINE, 2, ACTPAR)
        IF (ACTPAR .NE. SPLINE) GOTO 9
        NUM = NUM -1
        IF (NUM .GT. 0) GOTO 9
        WRITE (14,'(2A)') 
     >    'FROM FORMAL.OUT :', LINE(1:60)
        WRITE (14,*)
        J = 2
        CALL SARGC (LINE, JMAX)
   10   J = J + 1
        IF (J .GT. JMAX) GOTO 9
        IF (REDIS) THEN
          CALL SARGV ( LINE, J, ACTPAR)
          IF (ACTPAR( :4) .NE. 'ELEC') GOTO 10
        ELSE
          CALL SARGV (LINE, J, ACTPAR)
          IF (ACTPAR( :4) .EQ. 'ELEC') GOTO 9
        ENDIF
C***    GEWUENSCHTE LINIE (INCLUSIVE REDIS-BEDINGUNG) GEFUNDEN

C***  ENTRY POINT, IF NO LINE NUMBER IS SPECIFIED
  110   CONTINUE

C***  SUCHEN NACH GEWUENSCHTEM KEYWORD (TOTAL)
    7   READ (2,'(A)',END=4) LINE
        CALL SARGC (LINE, JMAX)
        IF (JMAX .EQ. 0) GOTO 7
        J = 0
    8     J = J + 1
          IF (J .GT. JMAX-1) GOTO 7
          CALL SARGV (LINE, J, ACTPAR)
          IF (ACTPAR .EQ. KEYWRD) THEN
            CALL SARGV (LINE, J+1, ACTPAR)
            READ (ACTPAR, '(F10.0)') WERT(NFORMAL)
          ELSE
            GOTO 8
          ENDIF
    4     CLOSE(2)
          CLOSE(4)

        GOTO 1

    2 CLOSE (1)
C***  HIER BEGINNT IE AUSWERTUNG UND DAS SCHRIEBEIN DES AUSGABE FILES

C***  OUTPUT-FILE = FNOUT
      FNOUT = 'isoex.iso'

C***  SCHREIBEN DES ERSTEN TEILS DES ISO-FILES
      OPEN (UNIT=1, FILE='iso.part1', STATUS='OLD', ERR=99, RECL=132)
      OPEN (UNIT=2, FILE='iso.part2', STATUS='OLD', ERR=99, RECL=132)
      WRITE(*,'(2A)') ' OUTPUT-FILE = ', FNOUT( :ISTRL(FNOUT))
      OPEN (UNIT=3, FILE=fnout, STATUS='UNKNOWN', ERR=99, RECL=132)
      READ (1, '(A)', END=72) LINE
      LINE = LINE(: ISTRL(LINE))//FNNAMEN
      WRITE (3, '(A)') LINE
   70 READ (1, '(A)', END=72) LINE
      WRITE (3, '(A)') LINE( :ISTRL(LINE))
      GOTO 70
   72 CONTINUE
      CLOSE (1)

C***  SCHREIBEN DES ZWEITEN TEILS DES ISO-FILES
      READ (2, '(A)', END=75) LINE
      WRITE (3, '(A)') LINE( :ISTRL(LINE))
      READ (2, '(A)', END=75) LINE
      WRITE (3, '(A)') SPLINE( :ISTRL(SPLINE))
      READ (2, '(A)', END=75) LINE
      WRITE (3, '(A)') LINE( :ISTRL(LINE))
      WRITE(3, '(2A)')   '*KEYWORD = ', KEYWRD( :ISTRL(KEYWRD))
      READ (2, '(A)', END=75) LINE
      WRITE(3, '(5A)') 'HEADER: '//FNANF( :ISTRL(FNANF( :132)))//
     >                '     '//'LINE: '//SPLINE( :ISTRL(SPLINE))
   74 READ (2, '(A)', END=75) LINE
      WRITE (3, '(A)') LINE( :ISTRL(LINE))
      GOTO 74
   75 CONTINUE
      CLOSE (2)

C!!!C***  SWAPPEN DER WERTE-PAARE
C!!!      DO 79 I=1,NFORMAL
C!!!        TEMP = T(I)
C!!!        T(I) = RT(I)
C!!!        RT(I) = TEMP
C!!!   79 CONTINUE

C***  SORTIEREN DER DATEN
      DO 80 I=1, NFORMAL
        DO 80 J=1, NFORMAL - 1
          IF (T(J) .GT. T(J+1) .OR.
     >       (T(J) .EQ. T(J+1) .AND. RT(J) .LT. RT(J+1))) THEN
            TEMP = T(J)
            T(J) = T(J+1)
            T(J+1) = TEMP
            TEMP = RT(J)
            RT(J) = RT(J+1)
            RT(J+1) = TEMP
            TEMP = WERT(J)
            WERT(J) = WERT(J+1)
            WERT(J+1) = TEMP
            BTEMP = BINS(J)
            BINS(J) = BINS(J+1)
            BINS(J+1) = BTEMP
          ENDIF
   80 CONTINUE

C*** SCHREIBEN DER ISOWERTE
      TE = -10.
      DO 82 I=1, NFORMAL
        IF (TE .LT. T(I)) THEN
          IF (T(I) .GT. 0.) THEN
            WRITE (3, '(A,F10.3)') 'T=',T(I)
            TE = T(I)
          ENDIF
        ENDIF
C!!!        IF (T(I) .GT. 0. .AND. RT(I) .GT. 0. 
C!!!     >      .AND. WERT(I) .NE. 0.) THEN
        IF (T(I) .GT. 0.) THEN
          IF (.NOT. BINS(I)) THEN
            WRITE (3, '(F10.2,3X,F10.3)') RT(I), WERT(I)
          ELSE
            WRITE (3, '(F10.2,3X,A3)') RT(I), '???'
          ENDIF
        ENDIF
   82 CONTINUE
      WRITE(3, '(A)') 'END'
      WRITE(3, '(A)') '==================================='
      CLOSE(3)


      GOTO 100

   99 WRITE(*,*) 'OPEN FEHLERHAFT'
      GOTO 100

  100 END
hfill.f/        1553528659  5006  320   100644  632       `
      SUBROUTINE HFILL (LINE)
C*************************************************************
C***  Call filling Routine for different graphic drivers.
C***  Note: for the Calcomp driver, the fillig action must be prepared
C***        by hand before the Polyline starts
C*************************************************************

      COMMON / COMACT / ACTDRIV
      CHARACTER ACTDRIV*7, LINE*(*)

      IF (ACTDRIV .EQ. 'PSOWN') THEN
         CALL PS_HFILL(LINE)
      ELSE IF (ACTDRIV .EQ. 'X11OWN') THEN
         CALL X_FILL
      ELSE
         STOP 'ERROR IN HFILL: UNKNOWN DRIVER'
      ENDIF

      RETURN
      END






ps_hfill.f/     1553528659  5006  320   100644  2440      `
      SUBROUTINE PS_HFILL (LINE)
C****************************************************************
C***  PSOWN DRIVER: Fills the current Polyline (since last "newpath"
C****************************************************************

C***  Transformation coefficients 
      COMMON / COMPLT / KPS, XOFFSET, YOFFSET, FORMATFA
C***  Hatching-Flag for Prologue, read by PS_PLTEND 
      COMMON / COMHATCHFLAG / HATCHFLAG

      REAL      HSEP, HANGLE, HW
      CHARACTER HTYPE*1, LINE*(*), ACTPAR*40, ACTPAR2*40
      LOGICAL HATCHFLAG

C***  Enable Hatching in PS-Prologue
      HATCHFLAG = .TRUE.

      HTYPE = 'Q'  ! Default type of hatching
      HSEP  = 8.0  ! Default line separation 
      HW    = 0.8  ! Default line width 

!     SCAN FOR OPTIONS HTYPE, HSEP, HW
      CALL SARGC (LINE, N)
      DO I=1, N
         CALL SARGV (LINE, I, ACTPAR)
         IF (ACTPAR .EQ. 'HTYPE') THEN
            CALL SARGV (LINE, I+1, HTYPE)
         ELSEIF (ACTPAR .EQ. 'HSEP') THEN
            CALL DECFPNUM (LINE, I+1, HSEP)
         ELSEIF (ACTPAR .EQ. 'HW') THEN
            CALL DECFPNUM (LINE, I+1, HW)
         ENDIF 
      ENDDO
      
      IF (HTYPE .EQ. 'Q') THEN
         HANGLE = 45.
      ELSEIF (HTYPE .EQ. 'V') THEN
         HANGLE = 0.
      ELSEIF (HTYPE .EQ. 'H') THEN
         HANGLE = 90.
      ELSEIF (HTYPE .EQ. 'D') THEN
         HANGLE = 135.
      ELSEIF (HTYPE .EQ. 'K') THEN
         HANGLE = 0.
      ELSE
         HANGLE = 45.
      ENDIF

      HW   = HW   * FORMATFA
      HSEP = HSEP * FORMATFA

      WRITE (KPS, '(A)') 'closepath'
      WRITE (KPS, '(A)') 'gsave' ! save the path
      WRITE (KPS, '(F8.3,A)') HANGLE, ' rotate' ! rotating angle for fill line
      WRITE (KPS, '(F8.3,A)') HW, ' SLW' ! linewidth for filling line
      WRITE (KPS, '(F8.3,A)') HSEP, ' 0.0 0.0 LineFill' ! line sep
      WRITE (KPS, '(A)') 'grestore' ! bring back path(?)

      IF (HTYPE .EQ. 'C' .OR. HTYPE .EQ. 'K' ) THEN
       WRITE (KPS, '(A)') 'gsave' ! save the path
       IF (HTYPE .EQ. 'K' ) THEN
        WRITE (KPS, '(F8.3,A)') 90., ' rotate' ! rotating angle for fill line   
       ELSE
        WRITE (KPS, '(F8.3,A)') 135., ' rotate' ! rotating angle for fill line
       ENDIF
       WRITE (KPS, '(F8.3,A)') HW, ' SLW' ! linewidth for filling line
       WRITE (KPS, '(F8.3,A)') HSEP, ' 0.0 0.0 LineFill' ! line sep
       WRITE (KPS, '(A)') 'grestore' ! bring back path(?)
      ENDIF
      
      RETURN
      END
heptastar.f/    1553528659  5006  320   100644  1092      `
      SUBROUTINE HEPTASTAR (X, Y, SSIZE)
C**********************************************************************
C***  PLOTTING OF A N-STAR (n=7) (CLIPPED) 
C**********************************************************************
      CALL GCPLOT (X+0.00000*SSIZE, Y+0.68302*SSIZE, 3)
      CALL GCPLOT (X+0.10577*SSIZE, Y+0.21963*SSIZE, 2)
      CALL GCPLOT (X+0.53400*SSIZE, Y+0.42585*SSIZE, 2)
      CALL GCPLOT (X+0.23765*SSIZE, Y+0.05424*SSIZE, 2)
      CALL GCPLOT (X+0.66589*SSIZE, Y-0.15199*SSIZE, 2)
      CALL GCPLOT (X+0.19058*SSIZE, Y-0.15199*SSIZE, 2)
      CALL GCPLOT (X+0.29635*SSIZE, Y-0.61538*SSIZE, 2)
      CALL GCPLOT (X-0.00000*SSIZE, Y-0.24377*SSIZE, 2)
      CALL GCPLOT (X-0.29635*SSIZE, Y-0.61538*SSIZE, 2)
      CALL GCPLOT (X-0.19058*SSIZE, Y-0.15199*SSIZE, 2)
      CALL GCPLOT (X-0.66589*SSIZE, Y-0.15199*SSIZE, 2)
      CALL GCPLOT (X-0.23765*SSIZE, Y+0.05424*SSIZE, 2)
      CALL GCPLOT (X-0.53400*SSIZE, Y+0.42585*SSIZE, 2)
      CALL GCPLOT (X-0.10577*SSIZE, Y+0.21962*SSIZE, 2)
      CALL GCPLOT (X+0.00000*SSIZE, Y+0.68302*SSIZE, 2)
      RETURN
      END
