skipdataset.f/  1553528659  5006  320   100644  1781      `
       SUBROUTINE SKIPDATASET (ISETOP, NSET, NDATMAX, NSETMAX, X, Y, 
     >         ISYMBOL, STRIP, NPEN, SSIZE, ICOLOR, ISETXERR, ISETYERR,
     >         XERRTYPE, YERRTYPE, SETNAME, DATASETLINE)
C******************************************************************
C***  removes dataset ISETOP; all subsequent datasets and their 
C***  attributes are shifted down by one dataset index 
C******************************************************************
      DIMENSION X(NDATMAX, NSETMAX), Y(NDATMAX, NSETMAX)
      DIMENSION NDAT(NSETMAX), NPEN(NSETMAX), ICOLOR(NSETMAX)
      DIMENSION ISYMBOL(NSETMAX) 
      DIMENSION SSIZE(NSETMAX), STRIP(2,NSETMAX)
      DIMENSION ISETXERR(NSETMAX), ISETYERR(NSETMAX)
      CHARACTER*(*) SETNAME(NSETMAX)
      CHARACTER*(*) XERRTYPE(NSETMAX), YERRTYPE(NSETMAX)
      CHARACTER*(*) DATASETLINE(NSETMAX)

      IF (ISETOP .GE. 1 .AND. ISETOP .LE. NSET) THEN
         DO I=ISETOP+1, NSET
            DO K=1, NDATMAX
              X(K,I-1) = X(K,I)
              Y(K,I-1) = Y(K,I)
	    ENDDO
            STRIP(1,I-1) = STRIP(1,I)
            STRIP(2,I-1) = STRIP(2,I)

            SSIZE(I-1) = SSIZE(I)
            NDAT(I-1) = NDAT(I)
            NPEN(I-1) = NPEN(I)
            ICOLOR(I-1) = ICOLOR(I)
            ISYMBOL(I-1) = ISYMBOL(I)
            ISETXERR(I-1) = ISETXERR(I)
            ISETYERR(I-1) = ISETYERR(I)
            SETNAME(I-1) = SETNAME(I)
            XERRTYPE(I-1) = XERRTYPE(I)
            YERRTYPE(I-1) = YERRTYPE(I)
            DATASETLINE(I-1) = DATASETLINE(I)
         ENDDO
      ELSE
         WRITE (*,'(/,A,I5)') 
     >    '*** ERROR: COMMAND SKIP called with invalid dataset number',
     >    ISETOP
	 STOP '*** FATAL ERROR in subroutine SKIPDATASET'
      ENDIF


      NSET = NSET - 1
      RETURN
      END

aripar.f/       1555062618  5006  320   100644  1025      `
      SUBROUTINE ARIPAR (ACTPAR, VALUE, IERR)
C**********************************************************************
C***  Decodes a floting-point type argument ACTPAR
C***  that is enclosed in parantheses and thus shall be avaluated 
C***  as an arithmetic expression
C**********************************************************************
      CHARACTER ACTPAR*(*), CALCLINE*1000, AREX*20
      PARAMETER (MAXVAR=2)
      CHARACTER*132 VAR(MAXVAR,2)
      LOGICAL CALC_DEBUG

      IERR = 0
      LAST = IDX(ACTPAR)
      CALCLINE = 'KASDEF CALC AREX = ' // ACTPAR(2:LAST-1)
      NVAR = 0
      DUMMY=0.
      CALC_DEBUG = .FALSE.
      CALL KD_CALC (CALCLINE, DUMMY, DUMMY, 
     >                 VAR, MAXVAR, NVAR, CALC_DEBUG)   
      READ (VAR(2,2), '(F20.0)', ERR=99) VALUE
 
      RETURN

   99 PRINT *, '*** ERROR WHEN EVALUATING ARITHMETIX EXPRESSION: ***'
      PRINT *, '>>> ', ACTPAR(:IDX(ACTPAR)), 
     >         ' <<<< CANNOT BE DECODED AS FLOATING POINT NUMBER!'

      IERR = 1
      RETURN

      END


fitsvar.f/      1654265858  5006  320   100644  2725      `
      SUBROUTINE FITSVAR (LINE, VAR, MAXVAR, NVAR)
C*******************************************************************
C***  This subroutine reads parameters from fits-file headers, 
C***  and returns them as WRplot variables 
C***  - called from: WRPLOT - EXINST 
C*******************************************************************

      CHARACTER FITSNAM*(400), COMMENT*80, ACTPAR*20, VALUE*20
      CHARACTER*(*) VAR(MAXVAR,2), LINE*(*)

C***  for FITSIO routines:
      INTEGER BLOCKSIZE

C***  Default
      NHDU = 1
      ISTATUS=0

      CALL SARGC (LINE, NPAR)
      IF (NPAR .LT. 3) THEN
         WRITE (*,*) '*** FATEL ERROR: FITSVAR needs parameters'
         GOTO 99
      ENDIF 

      CALL SARGV (LINE, 3, FITSNAM)

C***  Open fits file
      CALL MY_FITSOPEN (10, FITSNAM, ISTATUS)
      IF (ISTATUS .NE. 0) GOTO 97

      IF (NPAR .LT. 4) THEN
         WRITE (*,*) '*** FATEL ERROR: FITSVAR needs more parameters'
         GOTO 99
      ENDIF 

C***  Loop over parameters (NHDU or VAR)
      DO IPAR = 4, NPAR
         CALL SARGV (LINE, IPAR, ACTPAR)

         IF (ACTPAR .EQ. 'NHDU') THEN
C*                        ====	 
            IF (NPAR .LE. IPAR) THEN
               WRITE (*,*) '*** FATAL ERROR: NHDU without number' 
               GOTO 99
            ENDIF
            CALL SARGV (LINE, IPAR+1, ACTPAR)
	    READ (ACTPAR, '(I20)', ERR=98) NHDU
	   
C***        Select Unit 
            CALL FTMAHD (10, NHDU, HDUTYPE, ISTATUS)
            IF (ISTATUS .NE. 0) GOTO 96

         ELSEIF (ACTPAR .EQ. 'VAR') THEN
C*                            ===	 
            IF (NPAR .LE. IPAR) THEN
               WRITE (*,*) '*** FATAL ERROR: VAR without varname' 
               GOTO 99
            ENDIF
            CALL SARGV (LINE, IPAR+1, ACTPAR)

            CALL FTGKYS (10, ACTPAR(:IDX(ACTPAR)), VALUE, 
     >                  COMMENT, ISTATUS)
            IF (ISTATUS .NE. 0) GOTO 95

            CALL PUTVAR(ACTPAR, VALUE, VAR, MAXVAR, NVAR)

         ENDIF
      ENDDO

      CALL FTCLOS (10, ISTATUS)
      IF (ISTATUS .NE. 0) THEN
        WRITE (*,*) 'SUBROUTINE FITSVAR: STATUS=',STATUS
        STOP 'ERROR when closinf FITS file'
      ENDIF

      RETURN 

C********** Error exits **********************************
   95 WRITE (*,*) '*** FATAL ERROR when reading variable ', ACTPAR
      GOTO 99

   96 WRITE (*,*) '*** FATAL ERROR when opening HEADER unit ', NHDU
      GOTO 99

   97 WRITE (*,*) '*** FATAL ERROR when opening FITS file'
      GOTO 99

   98 WRITE (*,*) '*** Value of NHDU must be integer number'
      GOTO 99

   99 WRITE (*,*) '*** The error occured in the following line:'
      WRITE (*,*) LINE(:IDX(LINE))
      STOP '*** FATAL ERROR in subroutine FITSVAR'

      END


my_fitsopen.f/  1654265858  5006  320   100644  3064      `
      SUBROUTINE MY_FITSOPEN (KANAL, FILENAME, IERR)
C********************************************************************
C***  Open a FITS file
C***  If FILENAME starts with ~<user> : expand as $USER
C***  If FILENAME not found: try FILENAME.gz and then gunzip 
C********************************************************************
      CHARACTER FILENAME*(*), LINE*255, LOCALNAME*255
      CHARACTER CCOMMAND*266, USERNAME*20, TEMPNAME*50
      INTEGER*4 BLOCKSIZE, KANAL, IERR
      LFN = IDX(FILENAME)
      LOCALNAME = FILENAME

C***  First, expand possible ~<user> 
      IF (FILENAME(:1) .EQ. '~') THEN
C        Use of C routine c_systempopen (pipe) 
         CCOMMAND = 'echo ' // FILENAME(:LFN) // ' 2>&1' // CHAR(0)
         CALL C_SYSTEMPOPEN(CCOMMAND, LOCALNAME, ILENNAME)

C***  Debug
c         write (*,*) 'LOCALNAME=', LOCALNAME(:IDX(LOCALNAME))
         IF (ILENNAME .GT. 255) THEN
            WRITE (*,'(/,A)') "ERROR: EXPANDED FILENAME TOO LONG"
            WRITE (*,*) 'LOCALNAME=', LOCALNAME
            GOTO 98
         ENDIF
         LOCALNAME=LOCALNAME(:ILENNAME)
         LFN=IDX(LOCALNAME)
      ENDIF

C***  Debug
c      write (*,*) 'try opening LOCALNAME=', LOCALNAME(:LFN)

C***  Test with normaL open if file exists
      OPEN (UNIT=KANAL, FILE=LOCALNAME, STATUS='OLD', 
     >      ERR=20)
      CLOSE(KANAL)

      CALL FTOPEN (KANAL, LOCALNAME(:LFN), 0, BLOCKSIZE, IERR)
      IF (IERR .NE. 0) GOTO 94
      RETURN
            
C***  Second attempt: test if file is gzipped      
   20 LOCALNAME = LOCALNAME(:LFN) // '.gz'
      LFN = LFN + 3
C***  Debug
c      write (*,*) 'try opening LOCALNAME=', LOCALNAME(:LFN)
      OPEN (UNIT=KANAL, FILE=LOCALNAME, STATUS='OLD', 
     >      ERR=99)
      CLOSE(KANAL)
      
C***  Debug
c      WRITE (*,*) 'file exists, but is gzipped'
            
      CALL GETENV ('USER', USERNAME)
      TEMPNAME = '/tmp/wrplot_scratch_gunzip_' // USERNAME
      LINE = 'gunzip -c ' // LOCALNAME(:LFN) // ' > ' // TEMPNAME 
      CALL SYSTEM (LINE(:IDX(LINE)))

C***  Debug
c      WRITE (*,'(/,A)') '=== NOTE: input file is gzipped: ' // 
c     >            LOCALNAME(:IDX(LOCALNAME))            
c      WRITE (*,*) '-> ' // TEMPNAME(:IDX(TEMPNAME)) // ' generated' 

      CALL FTOPEN (KANAL, TEMPNAME, 0, BLOCKSIZE, IERR)
      IF (IERR .NE. 0) GOTO 96

      RETURN

***********************************************************

C***  Error branch after making gunzip      
   94 IERR = 10
      WRITE (*, '(/,A)') 'Error when opening ' // 
     >                   LOCALNAME(:IDX(LOCALNAME))
      RETURN
      
C***  Error branch after making gunzip      
   96 IERR = 10
      WRITE (*, '(/,A)') 'Error when gunzip ' // TEMPNAME
      RETURN

   98 IERR = 10
      WRITE (*, '(/,A)') 'Error after expanding ~'
      RETURN
      
C***  Exit branch after gunzip failed      
   99 IERR = 11
      WRITE (*, '(/,A)') '*** Error: file not found:'
      WRITE (*,*) 'neither ' // LOCALNAME(:IDX(LOCALNAME)-3)
      WRITE (*,*) 'nor     ' // LOCALNAME(:IDX(LOCALNAME)) 
      RETURN
      
      END
isoex_param.f/  1740158667  5006  320   100644  2840      `
      SUBROUTINE ISOEX_PARAM
C****************************************************
C***
C***  OB grids only:
C***  Creating an isoplot file for model parameters like L, VFINAL 
C***
C****************************************************

      CHARACTER LINE*120, ACTPAR*10, ACTPAR2*10, MODEL*50, 
     >     TOLD*10, KEYWORD*10, ACTPAR3*10,  ACTPAR4*10

C     Mit dieser Abfrage wird in iso.part1 gelesen, welcher Parameter 
C     gesucht lst. Defeaukt ist 'LOGL'
      KEYWORD = 'LOGL'

1001  format(A)
      OPEN(101,FILE='iso.part1',status='old')
110   READ (101, 1001, ERR=980, END=113) LINE
      CALL SARGV (LINE,1,ACTPAR)
      IF (ACTPAR .EQ. 'VFINAL') THEN
         KEYWORD = ACTPAR
         GOTO 113   
      ELSE
         GOTO 110
      ENDIF
 113  CONTINUE
      LINE = ' '
      CLOSE(101)

C***  The following "grep" should extract 3 lines from each
C***  modinfo.kasdefs, 
C***  containing the lines with
C***    1) TEFF
C***    2) GLOG
C***    3) LOGL (or VFINAL)
C***  The extracted lines are written to file iso.dat and can be checked there!
      IF (KEYWORD .EQ. 'LOGL') THEN
         CALL SYSTEM 
     >('grep -e TEFF -e GLOG -e "LOGL " gridmodels/??-??/modinfo.kasdefs > iso.dat')
      ELSE IF (KEYWORD .EQ. 'VFINAL') THEN
         CALL SYSTEM 
     >('grep -e TEFF -e GLOG -e VFINAL gridmodels/??-??/modinfo.kasdefs > iso.dat')
      ELSE
         GOTO 998
      ENDIF

      CALL SYSTEM ('cat iso.part1 > isoex.iso')

C***  Now iso.dat is read, the parameters are parsed from the lines 
C***   and the table is written to isoex.iso 
C***   in the proper input format for isopro 

      OPEN (10, FILE='iso.dat', STATUS='OLD')
      TOLD = ' '

    1 READ (10, '(A)', END=100) LINE
      CALL SARGV (LINE,3,ACTPAR2)
      IF (ACTPAR2 .NE. 'TEFF') STOP '*** Internal error 1'
      CALL SARGV (LINE,4,ACTPAR)
      IF (ACTPAR .NE. TOLD) WRITE (20,'(A)') 'T=' // ACTPAR
      TOLD = ACTPAR

      READ (10, '(A)', END=999) LINE
      CALL SARGV (LINE,3,ACTPAR2)
      IF (ACTPAR2 .NE. 'LOGL' .AND. 
     >    ACTPAR2 .NE. 'VFINAL') STOP '*** Internal error 2'
      CALL SARGV (LINE,4,ACTPAR3)

      READ (10, '(A)', END=999) LINE
      CALL SARGV (LINE,3,ACTPAR2)
      IF (ACTPAR2 .NE. 'GLOG') STOP '*** Internal error 2'
      CALL SARGV (LINE,4,ACTPAR4)

      CALL SARGV (LINE,1,MODEL)

      WRITE (20,'(2X,A,2X,A,2X,A)') ACTPAR4, ACTPAR3, MODEL

      GOTO 1


  100 CONTINUE

      WRITE (20,'(A)') 'END'
      CLOSE (20)
      CLOSE (10)

      CALL SYSTEM ('cat fort.20 >> isoex.iso')
      CALL SYSTEM ('rm -f fort.20')

      STOP 'O.K.'

C***  Errors
 998  CONTINUE
      STOP 'ERROR: DO NOT KNOW WHICH LINE-CHARACTERISTIC IS WISHED:
     > PEAK OR EQUIV!'
999   CONTINUE
      STOP 'ERROR: EOF reached before line-triple completed' 

980   PRINT *, 'Datenfile Lesefehler'
      STOP 'ERROR'

      END

